            | RescueSaturationWithinLease -> "within_60s_lease"
            | RescueSaturationLedgerDesyncInvalidatesLease -> "ledger_desync_invalidates_lease"
            | RescueSaturationLeaseExpired -> "lease_expired_no_fresh_delta"
