        let private hudRankOrZero (value: string) =
            let mutable parsed = 0L
            if Int64.TryParse(value, &parsed) then parsed else 0L

        let private rememberStrongestTerminalUnlocked (line: string) =
            let rankText = firstField ["strongest_terminal_rank"; "terminal_rank"; "rank"] line
            let statusText = firstField ["strongest_terminal_status"; "terminal_status"; "status"] line
            let decisionId =
                if String.IsNullOrWhiteSpace rankText || String.IsNullOrWhiteSpace statusText then StrongestTerminalPinNoCandidate
                else
                    let nextRank = hudRankOrZero rankText
                    let currentRank =
                        match hudFieldCache.TryGetValue "strongest_terminal_rank" with
                        | true, v -> hudRankOrZero v
                        | _ -> 0L
                    if nextRank >= currentRank then StrongestTerminalPinPromote else StrongestTerminalPinKeepExisting
            match decisionId with
            | StrongestTerminalPinPromote ->
                rememberFieldUnlocked "strongest_terminal_rank" rankText
                rememberFieldUnlocked "strongest_terminal_status" statusText
                rememberFieldUnlocked "strongest_terminal_reason" (firstField ["strongest_terminal_reason"; "reason"] line)
                rememberFieldUnlocked "strongest_terminal_site" (firstField ["strongest_terminal_site"; "terminal_site"; "site"] line)
            | _ -> ()
            rememberFieldUnlocked "strongest_terminal_pin_decision_du" (strongestTerminalPinDecisionText decisionId)

        let private rememberHardSemanticImplsUnlocked (line: string) =
            let semanticPolicy = firstField ["semantic_terminal_policy_du"] line
            let eligibility = firstField ["terminal_deferral_eligibility_du"] line
            let opName = firstField ["op_impl_name"; "missing_dependency_target"] line
            let opSig = firstField ["op_impl_signature"; "missing_hard_semantic_impls"] line
            let isHard =
                semanticPolicy = "hard_authoring_blocker"
                || eligibility = "hard_semantic_terminal_not_deferrable_by_live_replay"
            let candidate =
                if not (String.IsNullOrWhiteSpace opSig) then opSig
                elif not (String.IsNullOrWhiteSpace opName) then opName
                else ""
            let decisionId =
                if not isHard || String.IsNullOrWhiteSpace candidate then HardSemanticImplAggregationNoCandidate
                else
                    match hudFieldCache.TryGetValue "missing_hard_semantic_impls" with
                    | false, _ -> HardSemanticImplAggregationSeed
                    | true, current when String.IsNullOrWhiteSpace current -> HardSemanticImplAggregationSeed
                    | true, current when current.Contains(candidate) -> HardSemanticImplAggregationAlreadyKnown
                    | true, _ -> HardSemanticImplAggregationAppend
            match decisionId with
            | HardSemanticImplAggregationSeed ->
                rememberFieldUnlocked "missing_hard_semantic_impls" candidate
            | HardSemanticImplAggregationAppend ->
                let current =
                    match hudFieldCache.TryGetValue "missing_hard_semantic_impls" with
                    | true, v -> v
                    | _ -> ""
                let next = if current.Length > 180 then current else current + " + " + candidate
                rememberFieldUnlocked "missing_hard_semantic_impls" next
            | _ -> ()
            rememberFieldUnlocked "hard_semantic_impl_aggregation_du" (hardSemanticImplAggregationDecisionText decisionId)

        let private renderHudPhaseUnlocked (phaseId: HudPaintPhaseId) =
            if supportsHud() && hudLines.Length > 0 then
                rememberFieldUnlocked "hud_paint_phase_du" (hudPaintPhaseText phaseId)
                renderHudUnlocked()

        let private rememberJsonFieldsUnlocked (line: string) =
            let keys =
                [|
                    "kind"; "elapsed_s"; "progress_pct"; "progress_raw_pct"; "progress_cap_pct"; "progress_is_capped"; "eta_s"; "prediction_eta_s"; "prediction_total_s"; "prediction_eta_confidence"; "prediction_eta_target_du"; "prediction_eta_slope_basis_du"; "hud_refresh_source_du"; "hud_refresh_source_code"; "stalled_site"; "stalled_tag"; "stalled_node_id"; "root_finalization_state";
                    "work"; "sampled_work"; "work_delta"; "sampled_work_delta"; "semantic_receipts"; "stats_semantic_receipts"; "structural_receipts"; "stats_structural_receipts"; "spiral_sites"; "stats_spiral_file_sites";
                    "replay_scheduled"; "replay_schedules"; "replay_driver_ticks"; "replay_yields"; "replay_cooperative_yields"; "replay_delta"; "replay_progress_delta"; "root_receipts"; "root_complete_receipts"; "root_delta"; "root_complete_delta"; "terminal_signals"; "terminal_delta"; "terminal_signal_delta";
                    "cpu_core_equiv"; "proc_cpu_pct"; "proc_cpu_machine_pct"; "mem_ws_bytes"; "mem_private_bytes"; "mem_managed_bytes"; "overview_state"; "parallelism_state"; "progress_model_du"; "progress_model_code"; "no_work_replay_evidence_du"; "no_work_gate_decision_du"; "replay_quality_du"; "replay_quality_code"; "metrics_overview_score"; "metrics_overview_band_du"; "metrics_overview_band_code"; "plateau_progress_du";
                    "no_work_stall_s"; "no_work_pokes"; "no_work_rescue_completed"; "no_work_rescue_gate_busy"; "no_work_rescue_gate_busy_ratio_pct"; "single_flight_wait_acquired"; "single_flight_wait_timeout"; "work_idle_s"; "replay_idle_s"; "heartbeat_gap_class"; "heartbeat_missed_intervals"; "heartbeat_overdue_ms"; "heartbeat_lag_ms";
                    "rich_tick"; "rich_age_ms"; "rich_busy_ms"; "rich_stale"; "rich_overdue_ms"; "rich_gap_class"; "hud_paint_phase_du";
                    "repeat_stats"; "abort_origin"; "detail"; "schedule_detail"; "terminal_detail"; "pending"; "queue_depth"; "active_depth"; "term_hot_count"; "ty_hot_count"; "diagnostic_activity"; "front_worklist_pending"; "front_replay_queue"; "front_replay_active"; "front_hot_term"; "front_hot_ty"; "front_diagnostic_activity"; "hot_frontier_verdict_du"; "scheduler_work_du"; "action_du"; "status"; "rank"; "site"; "next"; "structural_action_du"; "log_cadence_du"; "decision_du"; "lease_decision_du"; "lease_count"; "physical_handoff_du"; "parent_enqueue_du"; "replay_tick_request_du"; "reason"; "tag"; "tag_du"; "waited_ms"; "root_witness_activity"; "replay_complete"; "write_witness"; "patched_holes"; "holes_patched"; "holes_patched_total"; "pending_monomorphization_queue"; "mono_queue_depth"; "codegen_bytes_written"; "fatal_dotnet_trace"; "exception_type_du"; "failing_child_du"; "expected_shape"; "actual_value_or_null"; "semantic_eval_cell"; "handoff_guard_du"; "reason_du"; "required_next"; "worker_action"; "worker_decision_du"; "worker_defer_decision_du"; "surface_ctx"; "terminal_deferral_eligibility_du"; "semantic_terminal_policy_du"; "progress_delta_class_du"; "pending_zero_forbidden_reason_du"; "assessment_resolution"; "op_impl_name"; "op_impl_signature"; "op_impl_arity"; "op_impl_node_id"; "missing_hard_semantic_impls"; "missing_impl_context"; "active_workers_state"; "active_worker_current_node_id"; "bridge_deferrals_remaining"; "q0_p0_bridge_veto_status"; "sidecar_drain_status_du"; "ty_sidecar_prefetch_drain_decision_du"; "sidecar_grace_remaining_ms"; "active_worker_introspection_du"; "delta_age_freshness_du"; "pending_ledger_health_du"; "pending_corrupted"; "pending_desync_flag"; "pending_ledger_recommended_action_du"; "last_pending_decrement_site"; "prefetch_missing_target_key"; "hopac_shadow_quorum_state"; "shadow_alt_timeout_ms"; "shadow_mailbox_hit"; "native_hopac_sidecar_drain_du"; "native_hopac_waiter_key"; "native_hopac_alt_timeout_ms"; "native_hopac_primary_blocker_du"; "native_hopac_ivar_state_du"; "native_hopac_mailbox_probe_du"; "native_hopac_alt_state_du"; "native_hopac_sidecar_lease_du"; "native_hopac_unblock_ready_du"; "hard_semantic_quarantine_active_du"; "sparse_replay_tick_quorum_evidence"; "time_since_last_delta_ms"; "no_work_stall_cause_du"; "rich_staleness_impact_du"; "idle_cross_kind_replay_driver_site"; "idle_cross_kind_replay_driver_duration_ms"; "idle_cross_kind_replay_driver_awaiting"; "no_work_rescue_loop_saturation_evidence"; "strongest_terminal_status"; "strongest_terminal_rank"; "strongest_terminal_reason"; "strongest_terminal_site"; "recent_sampled_delta"; "recent_terminal_delta"; "budget_waited_ms"; "recent_progress_decision_du"; "recent_progress_credit_du"; "cell_shape"; "obligation_shape"; "kind2"; "driver_du"; "terminal_site"; "terminal_status"; "terminal_rank"; "repeat_count"; "repeat_cap"; "hot_queue_node_id"; "hot_queue_count"; "yield_thrash_decision_du"; "cross_kind_direction"; "reentry_site"; "reentry_count"; "yield_thrash_count_since_last_real_progress"; "no_root_finish_budget_state"; "root_witness_stall_duration_ms"; "last_root_receipt_age_ms"; "time_since_last_real_root_receipt_ms"; "time_since_last_root_yield_ms"; "consecutive_thrash_on_hot_node"; "hot_node_repeat_cap_breached"; "active_tail_quiescent"; "pressure_worker_trigger"; "promote_requeue_reason"; "cross_kind_reentry_evidence_du"; "consecutive_thrash_on_same_hot_node"; "repeat_guard_trigger_shape"; "repeat_guard_trigger_site"; "stale_parent_continuation_count"; "cross_kind_obligation_at_grace_start"; "ythrash_at_grace_start"; "hot_oblig_du"; "p_starved_ms"; "dynamic_record_key_placeholder_decision_du"; "bridge_tail_live"; "bridge_tail_evidence"; "record_key_resolution_arbitration"; "placeholder_vs_repeat_cap_outcome"; "dv_symbolic_carrier_accepted"; "db_placeholder_produced"; "dynamic_join_shape"; "apply_head_site"; "active_structural_churn_decision_du"; "structural_semantic_delta_ratio"; "hot_queue_dominant_shape_du"; "abort_gate_blocker_du"
                |]
            for key in keys do
                let v = jsonScalarField key line
                if not (String.IsNullOrWhiteSpace v) then
                    // ALPHA1317: replay-driver no-task receipts use status=empty/next=none.
                    // They are liveness receipts, not terminal contracts; do not let
                    // them erase the HUD's last real semantic terminal/status focus.
                    let staleReplayNoTaskField =
                        (key = "status" && v = "empty")
                        || (key = "next" && v = "none")
                    if not staleReplayNoTaskField then
                        rememberFieldUnlocked key v
            rememberStrongestTerminalUnlocked line
            rememberHardSemanticImplsUnlocked line
            let kindForGraph = jsonScalarField "kind" line
            let siteForGraph = firstField ["site"; "terminal_site"] line
            rememberHudFileSiteUnlocked kindForGraph siteForGraph
            try
                let p = Process.GetCurrentProcess()
                let nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let cpuMs = p.TotalProcessorTime.TotalMilliseconds
                let wallDeltaMs =
                    if hudRealtimeLastMs > 0L then max 1L (nowMs - hudRealtimeLastMs)
                    else 0L
                let cpuDeltaMs =
                    if hudRealtimeLastMs > 0L then max 0.0 (cpuMs - hudRealtimeLastCpuMs)
                    else 0.0
                hudRealtimeLastMs <- nowMs
                hudRealtimeLastCpuMs <- cpuMs
                let procPct =
                    if wallDeltaMs > 0L then (cpuDeltaMs / float wallDeltaMs) * 100.0
                    else 0.0
                let machinePct =
                    let cores = max 1 Environment.ProcessorCount
                    procPct / float cores
                rememberFieldUnlocked "hud_cpu_core_equiv" ((procPct / 100.0).ToString("F3", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_proc_cpu_pct" (procPct.ToString("F2", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_proc_cpu_machine_pct" (machinePct.ToString("F2", CultureInfo.InvariantCulture))
                rememberFieldUnlocked "hud_mem_ws_bytes" (string p.WorkingSet64)
                rememberFieldUnlocked "hud_mem_private_bytes" (string p.PrivateMemorySize64)
                rememberFieldUnlocked "hud_mem_managed_bytes" (string (GC.GetTotalMemory(false)))
            with _ -> ()

        let private cachedField (keys: string list) (line: string) =
            let direct = firstField keys line
            if not (String.IsNullOrWhiteSpace direct) then direct
            else
                keys
                |> List.tryPick (fun key ->
                    let mutable value = ""
                    if hudFieldCache.TryGetValue(key, &value) && not (String.IsNullOrWhiteSpace value) then Some value
                    else None)
                |> function
                   | Some v -> v
                   | None -> ""

