            rememberJsonFieldsUnlocked line
            if kind = "compile_progress_prediction_tick" || kind = "progress_tick" then
                let elapsed = cachedField ["elapsed_s"] line
                let pct = cachedField ["progress_pct"] line
                let rawPct = cachedField ["progress_raw_pct"; "overall_pct"] line
                let capPct = cachedField ["progress_cap_pct"; "overall_cap_pct"] line
                let eta = cachedField ["eta_s"; "prediction_eta_s"] line
