                let sampledDelta = cachedField ["work_delta"; "sampled_work_delta"] line
                let replayDelta = cachedField ["replay_delta"; "replay_progress_delta"] line
                let rootDelta = cachedField ["root_delta"; "root_complete_delta"] line
                let termDelta = cachedField ["terminal_delta"; "terminal_signal_delta"] line
                let sem = cachedField ["semantic_receipts"; "stats_semantic_receipts"] line
                let structural = cachedField ["structural_receipts"; "stats_structural_receipts"] line
                let sites = cachedField ["spiral_sites"; "stats_spiral_file_sites"] line
                let replay = cachedField ["replay_scheduled"; "replay_schedules"] line
                let drivers = cachedField ["replay_driver_ticks"] line
