                let machineCpu = cachedField ["hud_proc_cpu_machine_pct"; "proc_cpu_machine_pct"] line
                let overview = cachedField ["overview_state"; "overview_state_du"] line
                let model = cachedField ["progress_model_du"] line
                let evidence = cachedField ["no_work_replay_evidence_du"] line
                let gate = cachedField ["no_work_gate_decision_du"] line
                let sfw = cachedField ["single_flight_wait_acquired"] line
                let sft = cachedField ["single_flight_wait_timeout"] line
                let idleW = cachedField ["work_idle_s"] line
                let idleR = cachedField ["replay_idle_s"] line
                let rev = string (Interlocked.Read(&hudRevision))
                let raw = if String.IsNullOrWhiteSpace rawPct then pct else rawPct
                let cap = if String.IsNullOrWhiteSpace capPct then pct else capPct
                let etaConfidence = cachedField ["prediction_eta_confidence"] line
                let etaTarget = cachedField ["prediction_eta_target_du"] line
