    /// ### EJPCodes
    /// Centralized error code definitions and classification.
    /// EJP = Error in Join Point processing
    module EJPCodes =
        /// EJP0002: Join point annotation type mismatch
        let [<Literal>] EJP0002 = "[spiral_compiler] EJP0002"
    

        /// EJP0003: Type error during parallel evaluation (race condition)
        let [<Literal>] EJP0003 = "[spiral_compiler] EJP0003"
    

        /// EJP0007: Apply type mismatch - primitive where callable expected
        let [<Literal>] EJP0007 = "[spiral_compiler] EJP0007"
    

        /// EJP0008: Deep recursion cache corruption
        let [<Literal>] EJP0008 = "[spiral_compiler] EJP0008"
    
    


        /// EJP0009: Term/type recursion depth exceeded (stack overflow preemption)
        let [<Literal>] EJP0009 = "[spiral_compiler] EJP0009"
    
    


        /// EJP0010: Insufficient execution stack (preempted stack overflow)
        let [<Literal>] EJP0010 = "[spiral_compiler] EJP0010"
    

        /// EJP0011: Re-entrant term evaluation cycle detected
        let [<Literal>] EJP0011 = "[spiral_compiler] EJP0011"
    

        /// EJP0012: Loop specialization cap exceeded
        let [<Literal>] EJP0012 = "[spiral_compiler] EJP0012"
    
    


        /// EJP0013: Void instance construction (likely cache corruption)
        let [<Literal>] EJP0013 = "[spiral_compiler] EJP0013"

        /// EJP0014: Join-point scheduler stall detected while waiting (should trigger retry)
        let [<Literal>] EJP0014 = "[spiral_compiler] EJP0014"

        /// EJP0016: Dead IVar detected while waiting (likely stale JP state after invalidation)
        let [<Literal>] EJP0016 = "[spiral_compiler] EJP0016"
        let [<Literal>] EJP0018 = "[spiral_compiler] EJP0018"
        let [<Literal>] EJP0019 = "[spiral_compiler] EJP0019"
        let [<Literal>] EJP0020 = "[spiral_compiler] EJP0020"
        let [<Literal>] EJP0030 = "[spiral_compiler] EJP0030"
        let [<Literal>] EJP0031 = "[spiral_compiler] EJP0031"

        /// Classify an error message to an EJP code
        let classifyError (msg: string) : string option =
            // NOTE: Keep these checks cheap and order them from most specific to most general.
            if msg.Contains("Cannot construct an instance of a void type") || msg.Contains("void type") && msg.Contains("Cannot construct") then
                Some EJP0013
            elif msg.Contains("apply mismatch") then
                // The "apply mismatch" marker is emitted by cache invalidation heuristics; treat it as apply-type mismatch.
                Some EJP0007
            elif msg.Contains(EJP0011) || (msg.Contains("Re-entrant") && msg.Contains("cycle")) then
                Some EJP0011
            elif msg.Contains(EJP0010) || msg.Contains("Insufficient execution stack") || msg.Contains("stack overflow") && msg.Contains("preempt") then
                Some EJP0010
            elif msg.Contains(EJP0009) || msg.Contains("recursion depth") && (msg.Contains("exceeded") || msg.Contains("overflow")) then
                Some EJP0009
            elif msg.Contains("Expected a function") &&
                 (msg.Contains("Got: i32") || msg.Contains("Got: i64") ||
                  msg.Contains("Got: f32") || msg.Contains("Got: f64") ||
                  msg.Contains("Got: bool")) then
                Some EJP0007
            elif (msg.Contains("annotation of the function does not match its body's type") ||
                      (msg.Contains("annotation of the function") && msg.Contains("does not match its body's type"))) &&
                     (msg.Contains("JPMethodRecPlaceholder") || msg.Contains("JPTypeRecPlaceholder")) then
                // Annotation mismatch where the body is still a JP placeholder: treat as join-point annotation mismatch to allow retry.
                Some EJP0002
            elif msg.Contains("annotation") && msg.Contains("mismatch") then
                Some EJP0002
            elif msg.Contains("specialization cap") || msg.Contains(EJP0012) then
                Some EJP0012
            elif msg.Contains(EJP0008) || msg.Contains("generation changed while waiting") then
                Some EJP0008
            elif msg.Contains(EJP0014) || msg.Contains("scheduler stalled while waiting") || msg.Contains("jp_wait stalled") then
                Some EJP0014
            elif msg.Contains(EJP0016) || msg.Contains("dead ivar while waiting") then
                Some EJP0016
            elif msg.Contains(EJP0018) || msg.Contains("BigStack join aborted") || (msg.Contains("BigStack") && msg.Contains("join") && msg.Contains("aborted")) then
                Some EJP0018
            elif msg.Contains(EJP0019) || msg.Contains("BigStack join stalled") || (msg.Contains("BigStack") && msg.Contains("join") && msg.Contains("stalled")) then
                Some EJP0019
            elif msg.Contains(EJP0020) || msg.Contains("BigStack join interrupted") || (msg.Contains("BigStack") && msg.Contains("join") && msg.Contains("interrupted")) then
                Some EJP0020
            elif msg.Contains("variables compared for equality") && msg.Contains("same type") then
                // Equality arg type mismatch: usually stale cached term/type pairs; retry with invalidation.
                Some EJP0003
            elif msg.Contains("Cannot apply") &&
                     (msg.Contains("JPMethodRecPlaceholder") || msg.Contains("JPTypeRecPlaceholder") || msg.Contains("JPMethodUnknownRet")) then
                // Cannot-apply involving JP placeholders is almost always a stale join-point artifact; retry with invalidation.
                Some EJP0008
            elif msg.Contains("type mismatch") || msg.Contains("Cannot apply") then
                Some EJP0003
            else
                None
    

        /// Get error description
        let describe (code: string) : string =
            match code with
            | "[spiral_compiler] EJP0002" -> "Join point annotation type mismatch"
            | "[spiral_compiler] EJP0003" -> "Type error during parallel evaluation"
            | "[spiral_compiler] EJP0007" -> "Apply type mismatch: primitive where callable expected"
            | "[spiral_compiler] EJP0008" -> "Deep recursion cache corruption"
            | "[spiral_compiler] EJP0014" -> "Join-point scheduler stall detected while waiting"
            | "[spiral_compiler] EJP0016" -> "Dead IVar detected while waiting (stale JP state)"
            | "[spiral_compiler] EJP0009" -> "Term/type recursion depth exceeded"
            | "[spiral_compiler] EJP0010" -> "Insufficient execution stack (stack overflow preempted)"
            | "[spiral_compiler] EJP0011" -> "Re-entrant term evaluation cycle detected"
            | "[spiral_compiler] EJP0012" -> "Loop specialization cap exceeded"
            | "[spiral_compiler] EJP0013" -> "Void instance construction (likely cache corruption)"
            | "[spiral_compiler] EJP0018" -> "BigStack join aborted due to cache generation change"
            | "[spiral_compiler] EJP0019" -> "BigStack join stalled (possible deadlock / runaway job)"
            | "[spiral_compiler] EJP0020" -> "BigStack join interrupted (treated as retryable abort)"
            | "[spiral_compiler] EJP0030" -> "JP watchdog abort (progress stalled / oldest job too old)"
            | "[spiral_compiler] EJP0031" -> "JP watchdog abort (a specific job exceeded its per-op timeout)"
            | _ -> "Unknown error"
    

    module DiagJson =

        let esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""
        let private run_id = System.Guid.NewGuid().ToString("N")

        // ALPHA1442: keep the minimal metronome worker-introspection helpers inside
        // DiagJson itself.  Alpha1441 defined the HUD-side DUs in CompilerConsoleHud88,
        // but the true metronome is an outer sibling module and cannot see private HUD
        // helpers or unqualified constructors.  Duplicate the tiny diagnostic contract
        // here so FS0039 cannot regress and the JSONL schema remains typed at the
        // emission point.
        let private parseInt64Safe (s: string) =
            let mutable v = 0L
            if Int64.TryParse((if isNull s then "" else s).Trim(), &v) then v else 0L

        type ActiveWorkerIntrospectionQualityId =
            | ActiveWorkerIntrospectionPerSlot
            | ActiveWorkerIntrospectionAggregateFallback

        let private activeWorkerIntrospectionQualityText = function
            | ActiveWorkerIntrospectionPerSlot -> "per_slot_worker_state"
            | ActiveWorkerIntrospectionAggregateFallback -> "aggregate_worker_state_fallback"

        type DeltaAgeFreshnessId =
            | DeltaAgeFresh
            | DeltaAgeStaleStructural
            | DeltaAgeFrozenAllDeltas

        let private deltaAgeFreshnessText = function
            | DeltaAgeFresh -> "fresh_delta"
            | DeltaAgeStaleStructural -> "stale_structural_delta"
            | DeltaAgeFrozenAllDeltas -> "frozen_all_deltas"

        type PendingLedgerHealthId =
            | PendingLedgerHealthy
            | PendingLedgerDesynced
            | PendingLedgerNegativeCorrupted

        let private pendingLedgerHealthText = function
            | PendingLedgerHealthy -> "pending_ledger_healthy"
            | PendingLedgerDesynced -> "pending_ledger_desynced"
            | PendingLedgerNegativeCorrupted -> "pending_negative_corrupted"

        type LiveTailBypassReasonId =
            | LiveTailBypassNone
            | LiveTailBypassPhysicalEvidence
            | LiveTailBypassInvalidatedByNegativePending
            | LiveTailBypassInvalidatedByErasedIdentity
            | LiveTailBypassInvalidatedByShadowTimeout
            | LiveTailBypassInvalidatedByMaterializedTerminal

        let private liveTailBypassReasonText = function
            | LiveTailBypassNone -> "none"
            | LiveTailBypassPhysicalEvidence -> "physical_live_tail_evidence"
            | LiveTailBypassInvalidatedByNegativePending -> "invalidated_by_negative_pending"
            | LiveTailBypassInvalidatedByErasedIdentity -> "invalidated_by_erased_identity"
            | LiveTailBypassInvalidatedByShadowTimeout -> "invalidated_by_shadow_timeout"
            | LiveTailBypassInvalidatedByMaterializedTerminal -> "invalidated_by_materialized_terminal_payload"

        type RescueSaturationTypedId =
            | RescueSaturationFreshDelta
            | RescueSaturationWithinLease
            | RescueSaturationLedgerDesyncInvalidatesLease
            | RescueSaturationLeaseExpired
            | RescueSaturationLeaseExpiredAndIdentityLost
            | RescueSaturationLeaseExpiredAndLedgerCorrupt

        let private rescueSaturationTypedText = function
            | RescueSaturationFreshDelta -> "fresh_delta"
            | RescueSaturationWithinLease -> "within_60s_lease"
            | RescueSaturationLedgerDesyncInvalidatesLease -> "ledger_desync_invalidates_lease"
            | RescueSaturationLeaseExpired -> "lease_expired_no_fresh_delta"
            | RescueSaturationLeaseExpiredAndIdentityLost -> "lease_expired_erased_identity"
            | RescueSaturationLeaseExpiredAndLedgerCorrupt -> "lease_expired_pending_negative"

        // ALPHA519: bounded JSON telemetry sampling.
        // Noisy worklist liveness events are useful for proving progress while a
        // frontier is unknown, but after the same kind repeats hundreds of times they
        // become storage pressure.  Sample only the noisy classes; terminal failures,
        // blockers, explicit guards and build/error receipts still emit in full.
        let private jsonKindCounts = System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        // ALPHA1108: sampled progress tick stats.  These are approximate because they
        // deliberately reuse emitted/sampled diagnostics instead of adding hot-path scans.
        let private progressSpiralSites = System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        // ALPHA1103: expose bounded kind counters to BigStack join policy.
        // These counters are diagnostic liveness evidence only; consumers must stay
        // fail-closed and may only choose a retry/drain path, never a semantic value.
        let snapshotKindCount (kind: string) =
            try
                match jsonKindCounts.TryGetValue kind with
                | true, v -> v
                | _ -> 0
            with _ -> 0

        // ALPHA1082: keep console logging policy typed.  Earlier alphas kept adding
        // string predicates and booleans to the sampler; this made it too easy to
        // accidentally unsample a terminal receipt or let a new liveness family spam
        // stderr.  The recursive DU below separates the evidence class from the
        // cadence, like a tiny GADT-ish contract for diagnostics.
        type JsonEmissionCadence =
            | EmitAlways
            | EmitDenseThenPowerThenHeartbeat of heartbeat:int
            | EmitSparsePowerThenHeartbeat of heartbeat:int
            | EmitFirstThenHeartbeat of heartbeat:int

        type JsonEmissionClass =
            | CriticalEvidence
            | NoisyEvidence of kind:string * cadence:JsonEmissionCadence
            | CompositeEvidence of primary:JsonEmissionClass * secondary:JsonEmissionClass option

        type JsonEmissionDecision =
            | EmitLine
            | DropRepeatedLine of kind:string * repeat:int * cadence:JsonEmissionCadence

        let rec private jsonEmissionClassKind = function
            | CriticalEvidence -> "critical"
            | NoisyEvidence(kind, _) -> kind
            | CompositeEvidence(primary, _) -> jsonEmissionClassKind primary

        let private densePowerHeartbeat cadence repeat =
            match cadence with
            | EmitAlways -> true
            | EmitDenseThenPowerThenHeartbeat heartbeat ->
                repeat <= 3
                || repeat = 4 || repeat = 8 || repeat = 16 || repeat = 32 || repeat = 64 || repeat = 128
                || repeat = 256 || repeat = 512 || repeat = 1024
                || (heartbeat > 0 && repeat % heartbeat = 0)
            | EmitSparsePowerThenHeartbeat heartbeat ->
                repeat = 1 || repeat = 2 || repeat = 4 || repeat = 8 || repeat = 16 || repeat = 32
                || (heartbeat > 0 && repeat % heartbeat = 0)
            | EmitFirstThenHeartbeat heartbeat ->
                repeat = 1 || (heartbeat > 0 && repeat % heartbeat = 0)

        let rec private shouldEmitEmissionClass emissionClass =
            match emissionClass with
            | CriticalEvidence -> EmitLine
            | NoisyEvidence(kind, cadence) ->
                let c = jsonKindCounts.AddOrUpdate(kind, 1, (fun _ old -> old + 1))
                if densePowerHeartbeat cadence c then EmitLine else DropRepeatedLine(kind, c, cadence)
            | CompositeEvidence(primary, secondary) ->
                match shouldEmitEmissionClass primary with
                | EmitLine -> EmitLine
                | DropRepeatedLine _ as dropped ->
                    match secondary with
                    | Some CriticalEvidence -> EmitLine
                    | Some s -> shouldEmitEmissionClass s
                    | None -> dropped

        let mutable private semanticStaleRetargetHotRowOrdinal = 0
        let private nextSemanticStaleRetargetHotRowOrdinal () =
            System.Threading.Interlocked.Increment(&semanticStaleRetargetHotRowOrdinal)
        let private shouldEmitSemanticStaleRetargetHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let mutable private parentReplayCycleBreakTerminalHotRowOrdinal = 0
        let private nextParentReplayCycleBreakTerminalHotRowOrdinal () =
            System.Threading.Interlocked.Increment(&parentReplayCycleBreakTerminalHotRowOrdinal)
        let private shouldEmitParentReplayCycleBreakTerminalHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let private isPow2 (x: int) =
            x > 0 && ((x &&& (x - 1)) = 0)

        let private jsonStringField (field: string) (s: string) =
            try
                let needle = "\"" + field + "\":\""
                let i = s.IndexOf(needle)
                if i < 0 then ""
                else
                    let start = i + needle.Length
                    let j = s.IndexOf("\"", start)
                    if j < 0 then "" else s.Substring(start, j - start)
            with _ -> ""

        let private noteProgressSiteFromJsonLine (line: string) =
            try
                let site = jsonStringField "site" line
                if site.Contains(".spi", StringComparison.OrdinalIgnoreCase)
                   || site.Contains(".spir", StringComparison.OrdinalIgnoreCase) then
                    progressSpiralSites.AddOrUpdate(site, 1, (fun _ old -> old + 1)) |> ignore
            with _ -> ()

        let private sampledProgressStatsJsonFields () =
            try
                let semanticReceipts =
                    snapshotKindCount "eval_worklist_payload"
                    + snapshotKindCount "eval_worklist_replay_commit"
                    + snapshotKindCount "eval_worklist_replay_reduce"
                    + snapshotKindCount "eval_worklist_replay_step"
                    + snapshotKindCount "eval_worklist_frame_parent_continuation"
                let structuralReceipts =
                    snapshotKindCount "eval_worklist_apply_spine_post_fuse_recursive_children_registered"
                    + snapshotKindCount "eval_worklist_if_branch_children_registered"
                    + snapshotKindCount "eval_worklist_type_apply_arg_tv_env_snapshot"
                    + snapshotKindCount "eval_worklist_type_fun_tv_child_env_snapshot"
                sprintf ",\"stats_schema\":\"sampled_progress_v1\",\"stats_semantic_receipts\":%d,\"stats_structural_receipts\":%d,\"stats_spiral_file_sites\":%d"
                    semanticReceipts structuralReceipts progressSpiralSites.Count
            with _ ->
                ",\"stats_schema\":\"sampled_progress_v1\",\"stats_semantic_receipts\":-1,\"stats_structural_receipts\":-1,\"stats_spiral_file_sites\":-1"

        do
            Progress88.set_stats_provider sampledProgressStatsJsonFields

