        let noWorkGateProbePolicyFor gateBusySeen =
            if gateBusySeen >= 16L then NoWorkGateProbeEscalated512ms
            elif gateBusySeen >= 8L then NoWorkGateProbeEscalated256ms
            elif gateBusySeen >= 3L then NoWorkGateProbeEscalated128ms
            else NoWorkGateProbeBounded64ms

        let noWorkGateProbeWaitMs gateBusySeen =
            match noWorkGateProbePolicyFor gateBusySeen with
            | NoWorkGateProbeEscalated512ms -> 512
            | NoWorkGateProbeEscalated256ms -> 256
            | NoWorkGateProbeEscalated128ms -> 128
            | NoWorkGateProbeBounded64ms -> 64

        let noWorkGateProbePolicyText = function
            | NoWorkGateProbeBounded64ms -> "bounded_64ms"
            | NoWorkGateProbeEscalated128ms -> "escalated_128ms"
            | NoWorkGateProbeEscalated256ms -> "escalated_256ms"
            | NoWorkGateProbeEscalated512ms -> "escalated_512ms"

        type NoWorkReplayEvidenceId =
            | NoWorkReplayEvidenceNone
            | NoWorkReplayEvidenceSchedulesOnly
            | NoWorkReplayEvidenceTerminalOnly
            | NoWorkReplayEvidenceLowAuthorityRootTerminalDrip
            | NoWorkReplayEvidenceDriverOrRoot
            | NoWorkReplayEvidenceMixed

        let noWorkReplayEvidenceFor replaySchedules replayDrivers rootCompleteStores terminalSignals =
            let hasReplay = replaySchedules > 0 || replayDrivers > 0
            let hasRoot = rootCompleteStores > 0
            let hasTerminal = terminalSignals > 0
            let lowAuthorityRootTerminalDrip =
                hasRoot
                && hasTerminal
                && rootCompleteStores <= 8
                && replayDrivers <= 16
                && replaySchedules <= 64
                && terminalSignals <= 32
            match hasReplay, hasRoot, hasTerminal with
            | false, false, false -> NoWorkReplayEvidenceNone
            | _, true, true when lowAuthorityRootTerminalDrip -> NoWorkReplayEvidenceLowAuthorityRootTerminalDrip
            | true, false, true -> NoWorkReplayEvidenceMixed
            | true, false, false -> NoWorkReplayEvidenceSchedulesOnly
            | false, false, true -> NoWorkReplayEvidenceTerminalOnly
            | _, true, _ -> NoWorkReplayEvidenceDriverOrRoot

        let noWorkReplayEvidenceText = function
            | NoWorkReplayEvidenceNone -> "none"
            | NoWorkReplayEvidenceSchedulesOnly -> "schedules_only"
            | NoWorkReplayEvidenceTerminalOnly -> "terminal_only"
            | NoWorkReplayEvidenceLowAuthorityRootTerminalDrip -> "low_authority_root_terminal_drip"
            | NoWorkReplayEvidenceDriverOrRoot -> "driver_or_root"
            | NoWorkReplayEvidenceMixed -> "mixed"

