            | SidecarStickyRawPendingFrontierUnknown -> "sidecar_raw_pending_frontier_unknown"
            | SidecarStickyStaleRawPendingFrontierZero -> "sidecar_stale_raw_pending_frontier_zero"
            | SidecarStickyNoPhysicalPending -> "sidecar_no_physical_pending"

        let sidecarStickyPhysicalPendingDecisionHasPhysical = function
            | SidecarStickyRawAndFrontierPending
            | SidecarStickyRawPendingFrontierUnknown -> true
            | SidecarStickyNoTarget
            | SidecarStickyStaleRawPendingFrontierZero
            | SidecarStickyNoPhysicalPending -> false

        let sidecarStickyPhysicalPendingDecisionFor (rawPending: int64) (frontierPending: int64) (frontierKnown: bool) (hasTarget: bool) =
            if not hasTarget then SidecarStickyNoTarget
            elif rawPending > 0L && frontierKnown && frontierPending > 0L then SidecarStickyRawAndFrontierPending
            elif rawPending > 0L && not frontierKnown then SidecarStickyRawPendingFrontierUnknown
            elif rawPending > 0L && frontierKnown && frontierPending <= 0L then SidecarStickyStaleRawPendingFrontierZero
            elif rawPending > 0L && frontierPending > 0L then SidecarStickyRawAndFrontierPending
            else SidecarStickyNoPhysicalPending

        type CpuQuietNoDeltaSpinDecisionId =
            | CpuQuietNoDeltaSpinNone
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent

        let cpuQuietNoDeltaSpinDecisionText = function
            | CpuQuietNoDeltaSpinNone -> "none"
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta -> "sidecar_active_cpu_quiet_no_delta"
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent -> "sidecar_physical_pending_absent_cpu_quiet_no_delta"
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent -> "frozen_driver_root_physical_pending_absent_cpu_quiet_no_delta"

        let cpuQuietNoDeltaSpinDecisionIsAbort = function
            | CpuQuietNoDeltaSpinSidecarActiveNoDelta
            | CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            | CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent -> true
            | CpuQuietNoDeltaSpinNone -> false

        let cpuQuietNoDeltaSpinDecisionFor hasTarget hasPhysicalPending hasSidecarEvidence hasLiveReplay noFreshDelta noWorkS noWorkPokes rescueCompleted cpuPct cpuMachinePct =
            let cpuQuiet =
                cpuPct >= 0.0
                && cpuPct < 18.0
                && cpuMachinePct >= 0.0
                && cpuMachinePct < 5.0
            let maturedByClock =
                noWorkS >= 60L
                && noWorkPokes >= 10L
                && rescueCompleted >= 8L
            let maturedByRescueSaturation =
                // ALPHA1529: minimal heartbeat can keep no_work_s near zero by
                // crediting tiny replay/root drips while the same sidecar row has
                // already completed 160+ rescues.  Treat that as lease exhaustion
                // when CPU is quiet and the shadow data says no fresh delta.
                rescueCompleted >= 160L
            let matured =
                (maturedByClock || maturedByRescueSaturation)
                && cpuQuiet
                && noFreshDelta
                && hasLiveReplay
            if not matured then CpuQuietNoDeltaSpinNone
            elif hasTarget && hasSidecarEvidence && not hasPhysicalPending then CpuQuietNoDeltaSpinSidecarPhysicalAbsent
            elif hasTarget && hasSidecarEvidence && hasPhysicalPending then CpuQuietNoDeltaSpinSidecarActiveNoDelta
            elif hasTarget && not hasPhysicalPending then CpuQuietNoDeltaSpinFrozenDriverRootPhysicalAbsent
            else CpuQuietNoDeltaSpinNone

        type RichStalenessImpactId =
            | RichStalenessNoImpact
            | RichStalenessLaggingButNonBlocking
            | RichStalenessBlocksStallDecision
            | RichStalenessRetryExhaustedAbort
            | RichStalenessSemanticStaleRetargetDrainGrace
            | RichStalenessMinimalForcingAbort

        let richStalenessImpactText = function
            | RichStalenessNoImpact -> "none"
            | RichStalenessLaggingButNonBlocking -> "lagging_non_blocking"
            | RichStalenessBlocksStallDecision -> "rich_stale_blocks_stall_decision"
            | RichStalenessRetryExhaustedAbort -> "rich_stale_retry_exhausted_abort"
            | RichStalenessSemanticStaleRetargetDrainGrace -> "rich_stale_semantic_stale_retarget_drain_grace"
            | RichStalenessMinimalForcingAbort -> "minimal_forcing_abort_while_rich_stale"

        type NoWorkGateDecisionId =
            | NoWorkGateDecisionNone
            | NoWorkGateDecisionAbortReady
