        let noWorkGateDecisionText = function
            | NoWorkGateDecisionNone -> "none"
            | NoWorkGateDecisionAbortReady -> "abort_ready"
            | NoWorkGateDecisionHoldoffEscalateProbe -> "holdoff_escalate_probe"
