            | NoWorkGateDecisionHoldoffNativeParentJobBindExecution -> "holdoff_native_parent_job_bind_execution"
            | NoWorkGateDecisionForceParentJobBindGraftRepair -> "force_parent_job_bind_graft_repair"
            | NoWorkGateDecisionHoldoffFinalQueueSparseReplayTickQuorum -> "holdoff_final_queue_sparse_replay_tick_quorum"
            | NoWorkGateDecisionHoldoffFinalQueueActiveDriverRootProbe -> "holdoff_final_queue_active_driver_root_probe"
            | NoWorkGateDecisionHoldoffFinalQueueDrain -> "holdoff_final_queue_drain"
            | NoWorkGateDecisionHoldoffTySidecarPrefetchDrain -> "holdoff_ty_sidecar_prefetch_drain"
            | NoWorkGateDecisionHoldoffIdleCrossKindRichStaleRetry -> "holdoff_idle_cross_kind_rich_stale_retry"
            | NoWorkGateDecisionHoldoffLateRaceFreshRootWitnessDrain -> "holdoff_late_race_fresh_root_witness_drain"
            | NoWorkGateDecisionAbortIdleCrossKindRetryExhausted -> "abort_idle_cross_kind_retry_exhausted"
            | NoWorkGateDecisionAbortReplayObligationExtendedFrozenAuthority -> "abort_replay_obligation_extended_frozen_authority"
            | NoWorkGateDecisionAbortReplayObligationMidAuthorityFrozen -> "abort_replay_obligation_mid_authority_frozen"
            | NoWorkGateDecisionAbortLateRaceTinyReplayDrip -> "abort_late_race_tiny_replay_drip"
            | NoWorkGateDecisionAbortFrozenDriverRootAuthority -> "abort_frozen_driver_root_authority"
            | NoWorkGateDecisionAbortCpuQuietNoDeltaSpin -> "abort_cpu_quiet_no_delta_spin"

        type UnderutilizedReplayDecisionId =
            | UnderutilizedReplayDecisionNone
            | UnderutilizedReplayDecisionAbortReady
            | UnderutilizedReplayDecisionAbortCpuQuietNoDeltaSpin
            | UnderutilizedReplayDecisionHoldNativeParentJobBindExecution
            | UnderutilizedReplayDecisionForceParentJobBindGraftRepair
            | UnderutilizedReplayDecisionHoldNoWorkGate
            | UnderutilizedReplayDecisionHoldPlateauEvidence
            | UnderutilizedReplayDecisionExtendQuietReplay

        let underutilizedReplayDecisionText = function
            | UnderutilizedReplayDecisionNone -> "none"
            | UnderutilizedReplayDecisionAbortReady -> "abort_ready"
            | UnderutilizedReplayDecisionAbortCpuQuietNoDeltaSpin -> "abort_cpu_quiet_no_delta_spin"
            | UnderutilizedReplayDecisionHoldNativeParentJobBindExecution -> "hold_native_parent_job_bind_execution"
            | UnderutilizedReplayDecisionForceParentJobBindGraftRepair -> "force_parent_job_bind_graft_repair"
            | UnderutilizedReplayDecisionHoldNoWorkGate -> "hold_no_work_gate"
            | UnderutilizedReplayDecisionHoldPlateauEvidence -> "hold_plateau_evidence"
            | UnderutilizedReplayDecisionExtendQuietReplay -> "extend_quiet_replay"

        let underutilizedReplayDecisionIsAbort = function
            | UnderutilizedReplayDecisionAbortReady
            | UnderutilizedReplayDecisionAbortCpuQuietNoDeltaSpin -> true
            | _ -> false

        type NoWorkMidGraphStallWindowId =
            | NoWorkMidGraphStallBeforeWindow
            | NoWorkMidGraphStallGraceWindow
            | NoWorkMidGraphStallExpired

        let noWorkMidGraphStallWindowFor stallS =
            if stallS < 30L then NoWorkMidGraphStallBeforeWindow
            elif stallS < 90L then NoWorkMidGraphStallGraceWindow
            else NoWorkMidGraphStallExpired

        let noWorkMidGraphStallWindowIsGrace = function
            | NoWorkMidGraphStallGraceWindow -> true
            | _ -> false

        let noWorkMidGraphStallWindowText = function
            | NoWorkMidGraphStallBeforeWindow -> "before_window"
            | NoWorkMidGraphStallGraceWindow -> "grace_window"
            | NoWorkMidGraphStallExpired -> "expired"

        // ALPHA1183: 1182 proved the metronome can now abort fail-closed at 95%,
        // but repeated gate-busy no-work rescues only accumulated evidence.  Keep
        // the gate-busy response typed and bounded: after several busy probes,
        // request a replay-driver tick from outside the hot path before accepting
        // the no-work abort frontier.
        type NoWorkGateBusyRescueDecisionId =
            | NoWorkGateBusyObserveOnly
            | NoWorkGateBusyScheduleReplayTick
            | NoWorkGateBusyScheduleSparseReplayTick
            | NoWorkGateBusyAbortEvidenceOnly

        let noWorkGateBusyRescueDecisionText = function
            | NoWorkGateBusyObserveOnly -> "observe_only"
            | NoWorkGateBusyScheduleReplayTick -> "schedule_replay_tick"
            | NoWorkGateBusyScheduleSparseReplayTick -> "schedule_sparse_replay_tick"
            | NoWorkGateBusyAbortEvidenceOnly -> "abort_evidence_only"

        let noWorkGateBusyRescueDecisionFor gateBusySeen =
            // ALPHA1260: 1259 ended with q=3/a=4 and 80% gate-busy rescues.
            // A gate-busy probe is evidence that the worker gate is occupied, not proof that
            // the final replay tail has been physically drained.  Keep issuing bounded replay
            // ticks through the final 96-probe window before accepting abort evidence.
            if gateBusySeen <= 1L then NoWorkGateBusyObserveOnly
            elif gateBusySeen <= 64L && gateBusySeen % 2L = 1L then NoWorkGateBusyScheduleReplayTick
            elif gateBusySeen <= 64L && gateBusySeen % 4L = 0L then NoWorkGateBusyScheduleSparseReplayTick
            elif gateBusySeen < 96L then NoWorkGateBusyScheduleReplayTick
            elif gateBusySeen < 160L && gateBusySeen % 3L = 0L then
                // ALPHA1327: 1326 ended with gate_busy=119 while root=30/terminal=54
                // still described a replay-obligation tail.  Keep a bounded sparse
                // driver tick window instead of turning those probes into inert
                // abort evidence too early.
                NoWorkGateBusyScheduleSparseReplayTick
            elif gateBusySeen < 160L then NoWorkGateBusyScheduleReplayTick
            else NoWorkGateBusyAbortEvidenceOnly

        // ALPHA1353: replay-obligation deferred/cross-kind drains are not the same
        // terminal as an inert terminal flood.  Runtime 1352 reached q/a/p=98/4/2
        // with semantic_replay_obligation_deferred and a hot cross-kind node; the
        // old 45s grace cliff still let terminal_flood_quiet_abort win.  Keep the
        // window typed so extending it cannot silently mask unrelated no-work aborts.
        type ReplayObligationDeferredNoWorkWindowId =
            | ReplayObligationDeferredNoAuthority
            | ReplayObligationDeferredInitialDrainGrace
            | ReplayObligationDeferredExtendedLiveTailGrace
            | ReplayObligationDeferredExpired

        let replayObligationDeferredNoWorkWindowText = function
            | ReplayObligationDeferredNoAuthority -> "no_authority"
            | ReplayObligationDeferredInitialDrainGrace -> "initial_drain_grace"
            | ReplayObligationDeferredExtendedLiveTailGrace -> "extended_live_tail_grace"
            | ReplayObligationDeferredExpired -> "expired"

        let replayObligationDeferredNoWorkWindowFor noWorkS noWorkPokes rescueCompleted rescueGateBusy progressPct rootComplete terminalSignals replayProgress replayObligationReceiptSeen matureTerminalReplayAuthority =
            let hasReplayObligationAuthority =
                progressPct >= 70.0
                && progressPct < 95.0
                && (rootComplete >= 24L || terminalSignals >= 48L)
                && (terminalSignals >= 48L || rootComplete >= 30L)
                && replayProgress >= 1000L
                && (replayObligationReceiptSeen || matureTerminalReplayAuthority)
            if not hasReplayObligationAuthority then ReplayObligationDeferredNoAuthority
            elif noWorkS < 45L && noWorkPokes < 12L && rescueCompleted < 96L && rescueGateBusy < 96L then
                ReplayObligationDeferredInitialDrainGrace
            elif noWorkS < 150L && noWorkPokes < 32L && rescueCompleted < 256L && rescueGateBusy < 128L then
                ReplayObligationDeferredExtendedLiveTailGrace
            else ReplayObligationDeferredExpired

        // ALPHA1179: 1178 proved the rich heartbeat can get stuck busy after the
        // hot-frontier cap extends to 90s.  Keep the 1s metronome authoritative:
        // if no sampled/replay/root/terminal deltas move after many successful
        // rescue pokes, emit a typed no-work saturation abort instead of waiting
        // for manual Ctrl-C.
        type MetronomeNoWorkSaturationDecisionId =
            | MetronomeNoWorkSaturationNone
            | MetronomeNoWorkRichDiagReset
            | MetronomeNoWorkLateLiveReplayDrainGrace
            | MetronomeNoWorkMidCapReplayDrainGrace
            | MetronomeNoWorkRichBusyReplayDrainGrace
            | MetronomeNoWorkPoisonDrainGrace
            | MetronomeNoWorkHardSemanticQuarantineLiveTailGrace
            | MetronomeNoWorkFinalQueueSparseReplayTickQuorumGrace
            | MetronomeNoWorkFinalQueueActiveDriverRootProbeGrace
            | MetronomeNoWorkFinalQueueDrainGrace
            | MetronomeNoWorkTerminalFloodConcreteOpFrontierGrace
