            | MetronomeNoWorkReplayObligationExtendedFrozenAuthorityAbort -> "replay_obligation_extended_frozen_authority_abort"
            | MetronomeNoWorkReplayObligationMidAuthorityFrozenAbort -> "replay_obligation_mid_authority_frozen_abort"
            | MetronomeNoWorkLateRaceTinyReplayDripAbort -> "late_race_tiny_replay_drip_abort"
            | MetronomeNoWorkReplayOnlyChatterQuiescentTailAbort -> "replay_only_chatter_quiescent_tail_abort"
            | MetronomeNoWorkStaleRetargetSmallQueueAbort -> "stale_retarget_small_queue_no_work_abort"
            | MetronomeNoWorkStaleRetargetPinnedContractAbort -> "stale_retarget_pinned_contract_no_work_abort"
            | MetronomeNoWorkJpWaitLiveFrameFrozenAbort -> "jp_wait_live_frame_frozen_authority_abort"
