            elif hasLiveHistory && noFreshDelta && noWorkS >= 18L && noWorkPokes >= 8L && rescueCompleted >= 80L && (semanticStaleRetargetEvidence || idleCrossKindReplayDriverEvidence || dynamicRecordKeyBridgeFrozenDrainGrace || dynamicRecordKeyBridgeFrozenExhaustedAbort) then
                MetronomeNoWorkNativeWakeBindingProbeGrace
            elif hasLiveHistory && noFreshDelta && noWorkS >= 18L && noWorkPokes >= 8L && rescueCompleted >= 80L then
                MetronomeNoWorkLiveReplayQuietAbort
            elif hasLiveHistory && noFreshDelta && noWorkS >= 20L && noWorkPokes >= 10L && rescueCompleted >= 96L then
                MetronomeNoWorkRescueLoopAbort
            else MetronomeNoWorkSaturationNone

        type ReplayProgressQualityId =
            | ReplayProgressNone
            | ReplayProgressScheduleProgress
            | ReplayProgressDriverOrRootProgress
            | ReplayProgressTerminalChatter
            | ReplayProgressScheduleTerminalChatterNoRoot

        let private replayProgressQualityText = function
            | ReplayProgressNone -> "none"
            | ReplayProgressScheduleProgress -> "schedule_progress"
            | ReplayProgressDriverOrRootProgress -> "driver_or_root_progress"
            | ReplayProgressTerminalChatter -> "terminal_chatter"
            | ReplayProgressScheduleTerminalChatterNoRoot -> "schedule_terminal_chatter_no_root"

        let private replayProgressQualityCode = function
            | ReplayProgressScheduleProgress -> 1L
            | ReplayProgressDriverOrRootProgress -> 2L
            | ReplayProgressTerminalChatter -> 3L
            | ReplayProgressScheduleTerminalChatterNoRoot -> 4L
            | ReplayProgressNone -> 0L

        // ALPHA1244: root/semantic authority is distinct from replay-driver liveness.
        // A run can have many replay drivers and still have no root or semantic authority;
        // that is exactly the fast-fail frontier seen in alpha1243.
        type ReplayRootAuthorityDecisionId =
            | ReplayRootAuthorityColdOrNoReplay
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot
            | ReplayRootAuthoritySparseRootNoSemantic
            | ReplayRootAuthorityMultiRootNoSemantic
            | ReplayRootAuthoritySemanticOrRoot

        let private replayRootAuthorityDecisionText = function
            | ReplayRootAuthorityColdOrNoReplay -> "cold_or_no_replay"
            | ReplayRootAuthorityScheduleOnlyNoRoot -> "schedule_only_no_root"
            | ReplayRootAuthorityDriverOnlyNoRoot -> "driver_only_no_root"
            | ReplayRootAuthorityTerminalOnlyNoRoot -> "terminal_only_no_root"
            | ReplayRootAuthoritySparseRootNoSemantic -> "sparse_root_no_semantic"
            | ReplayRootAuthorityMultiRootNoSemantic -> "multi_root_no_semantic"
            | ReplayRootAuthoritySemanticOrRoot -> "semantic_or_terminal_authority"

        let private replayRootAuthorityAbortCandidate = function
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot -> true
            | _ -> false

        let private replayRootAuthorityDecisionFor semanticReceipts rootCompleteStores terminalSignals replaySchedules replayDrivers replayYields =
            if semanticReceipts > 0 then ReplayRootAuthoritySemanticOrRoot
            elif rootCompleteStores > 1 then ReplayRootAuthorityMultiRootNoSemantic
            elif rootCompleteStores = 1 then ReplayRootAuthoritySparseRootNoSemantic
            elif terminalSignals > 0 then ReplayRootAuthorityTerminalOnlyNoRoot
            elif replayDrivers > 0 then ReplayRootAuthorityDriverOnlyNoRoot
            elif replaySchedules > 0 || replayYields > 0 then ReplayRootAuthorityScheduleOnlyNoRoot
            else ReplayRootAuthorityColdOrNoReplay

        // ALPHA1248: expose root/replay authority as a typed relationship instead
        // of a loose pair of strings.  This keeps the Hopac frontier honest: replay
        // movement, root stores and semantic receipts are related, but not equivalent.
        type ReplayAuthorityEvidenceId =
            | ReplayAuthorityEvidenceCold
            | ReplayAuthorityEvidenceReplayOnly of ReplayProgressQualityId
            | ReplayAuthorityEvidenceRootNoSemantic of ReplayRootAuthorityDecisionId * ReplayProgressQualityId
            | ReplayAuthorityEvidenceSemanticOrTerminal of ReplayRootAuthorityDecisionId

        let private replayAuthorityEvidenceFor rootAuthority progressQuality =
            match rootAuthority with
            | ReplayRootAuthoritySemanticOrRoot -> ReplayAuthorityEvidenceSemanticOrTerminal rootAuthority
            | ReplayRootAuthoritySparseRootNoSemantic
            | ReplayRootAuthorityMultiRootNoSemantic -> ReplayAuthorityEvidenceRootNoSemantic(rootAuthority, progressQuality)
            | ReplayRootAuthorityScheduleOnlyNoRoot
            | ReplayRootAuthorityDriverOnlyNoRoot
            | ReplayRootAuthorityTerminalOnlyNoRoot -> ReplayAuthorityEvidenceReplayOnly progressQuality
            | ReplayRootAuthorityColdOrNoReplay -> ReplayAuthorityEvidenceCold

        let private replayAuthorityEvidenceText = function
            | ReplayAuthorityEvidenceCold -> "cold"
            | ReplayAuthorityEvidenceReplayOnly q -> sprintf "replay_only:%s" (replayProgressQualityText q)
            | ReplayAuthorityEvidenceRootNoSemantic (r, q) -> sprintf "root_no_semantic:%s:%s" (replayRootAuthorityDecisionText r) (replayProgressQualityText q)
            | ReplayAuthorityEvidenceSemanticOrTerminal r -> sprintf "semantic_or_terminal:%s" (replayRootAuthorityDecisionText r)

        // ALPHA1245: EJP0025 must distinguish mature no-root/no-semantic churn
        // from a still-moving structural/draining frontier.  Runtime 1244 aborted at
        // elapsed=38s with sampled_work_delta=17 and a final HUD queue=1 active=0;
        // that is too close to a drained handoff frontier for a blind hard abort.
        type ReplayAbortMaturityId =
            | ReplayAbortMaturityColdOrImmature
            | ReplayAbortMaturityGraceStructuralWork
            | ReplayAbortMaturityGraceDrainingFrontier
            | ReplayAbortMaturityMatureNoRootNoSemantic

        let private replayAbortMaturityText = function
            | ReplayAbortMaturityColdOrImmature -> "cold_or_immature"
            | ReplayAbortMaturityGraceStructuralWork -> "grace_structural_work"
            | ReplayAbortMaturityGraceDrainingFrontier -> "grace_draining_frontier"
            | ReplayAbortMaturityMatureNoRootNoSemantic -> "mature_no_root_no_semantic"

        let private replayAbortMaturityIsAbort = function
            | ReplayAbortMaturityMatureNoRootNoSemantic -> true
            | ReplayAbortMaturityColdOrImmature
            | ReplayAbortMaturityGraceStructuralWork
            | ReplayAbortMaturityGraceDrainingFrontier -> false

        let private replayAbortMaturityFor elapsedS replaySchedules replayDrivers replayYields sampledWork sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta semanticReceipts rootCompleteStores terminalSignals =
            if semanticReceipts > 0 || rootCompleteStores > 0 || rootCompleteDelta > 0L then ReplayAbortMaturityGraceDrainingFrontier
            elif elapsedS < 42L then ReplayAbortMaturityColdOrImmature
            elif sampledWorkDelta > 4L then ReplayAbortMaturityGraceStructuralWork
            elif replaySchedules < 192 || replayDrivers < 4 || replayYields < 8192 then ReplayAbortMaturityColdOrImmature
            elif replayProgressDelta <= 0L then ReplayAbortMaturityColdOrImmature
            elif terminalSignals > 0 || terminalSignalDelta > 0L then ReplayAbortMaturityMatureNoRootNoSemantic
            elif sampledWork >= 160L then ReplayAbortMaturityMatureNoRootNoSemantic
            else ReplayAbortMaturityColdOrImmature

        // ALPHA1456: active structural churn is a first-class diagnostic decision.
        // The assessment called out fake work: replay/structural movement with zero
        // semantic conversion.  This DU does not claim semantic failure by itself; it
        // gives HUD/JSON and BigStack gates a closed label for the arbitration.
        type ActiveStructuralChurnDecisionId =
            | ActiveStructuralChurnNone
            | ActiveStructuralChurnObserveSemanticOrRoot
            | ActiveStructuralChurnBoundedLiveDrain
            | ActiveStructuralChurnCircuitBreak

        let private activeStructuralChurnDecisionText = function
            | ActiveStructuralChurnNone -> "none"
            | ActiveStructuralChurnObserveSemanticOrRoot -> "observe_semantic_or_root"
            | ActiveStructuralChurnBoundedLiveDrain -> "bounded_live_structural_drain"
            | ActiveStructuralChurnCircuitBreak -> "active_structural_churn_circuit_break"

        let private activeStructuralChurnDecisionFor elapsedS semanticDelta structuralDelta replayDelta rootDelta terminalDelta replaySchedules replayDrivers terminalSignals =
            let semanticOrRootFresh = semanticDelta > 0 || rootDelta > 0 || terminalDelta > 0
            let structuralHot = structuralDelta >= 4 || replayDelta >= 16
            let replayActive = replaySchedules >= 32 || replayDrivers >= 4
            if semanticOrRootFresh then ActiveStructuralChurnObserveSemanticOrRoot
            elif elapsedS < 30L || not structuralHot || not replayActive then ActiveStructuralChurnNone
            elif elapsedS < 120L && terminalSignals < 128 then ActiveStructuralChurnBoundedLiveDrain
            else ActiveStructuralChurnCircuitBreak

        let private structuralSemanticDeltaRatioText semanticDelta structuralDelta =
            if structuralDelta <= 0 then "none"
            elif semanticDelta <= 0 then "inf_structural_no_semantic"
            else sprintf "%.4f" (float structuralDelta / max 1.0 (float semanticDelta))

        type RetryGenerationPolicyId =
            | RetryGenerationNoInvalidateGenWait
            | RetryGenerationNoInvalidateTermReentryFuse
            | RetryGenerationInvalidateLivenessParallel
            | RetryGenerationInvalidateSequentialFallback
            | RetryGenerationInvalidateOther

        let retryGenerationPolicyText = function
            | RetryGenerationNoInvalidateGenWait -> "no_invalidate_gen_wait"
            | RetryGenerationNoInvalidateTermReentryFuse -> "no_invalidate_term_reentry_fuse"
            | RetryGenerationInvalidateLivenessParallel -> "invalidate_liveness_parallel_retry"
            | RetryGenerationInvalidateSequentialFallback -> "invalidate_sequential_fallback"
            | RetryGenerationInvalidateOther -> "invalidate_other"

        let retryGenerationPolicyFor (isGenWait: bool) (isTermReentryFuse: bool) (retryPreservesParallel: bool) (willForceSequential: bool) =
            if isGenWait then RetryGenerationNoInvalidateGenWait
            elif isTermReentryFuse then RetryGenerationNoInvalidateTermReentryFuse
            elif retryPreservesParallel then RetryGenerationInvalidateLivenessParallel
            elif willForceSequential then RetryGenerationInvalidateSequentialFallback
            else RetryGenerationInvalidateOther

        type RetryParallelismReassertDecisionId =
            | RetryParallelismReassertAllCoresAfterLivenessRetry
            | RetryParallelismNoReassertion

        let retryParallelismReassertDecisionText = function
            | RetryParallelismReassertAllCoresAfterLivenessRetry -> "reassert_all_cores_after_liveness_retry"
            | RetryParallelismNoReassertion -> "no_reassertion"

        // ALPHA1201: progress_pct was previously a rough HUD sum hard-capped at 95%.
        // Runtime 1200 proved that this made the forecast look precise while the evaluator
        // still had no replay-driver/root/write authority.  Keep progress monotone, but make
        // the cap depend on typed evidence quality and log the raw/cap/model fields.
        type ProgressForecastModelId =
            | ProgressForecastColdStart
            | ProgressForecastSampledWorkOnly
            | ProgressForecastReplayScheduleOnly
            | ProgressForecastReplayTerminalChatterNoRoot
            | ProgressForecastReplayDriverNoRoot
            | ProgressForecastSparseRootNoSemantic
            | ProgressForecastLowAuthorityRootTerminalDrip
            | ProgressForecastDriverOrRootAuthority

        let private progressForecastModelText = function
            | ProgressForecastColdStart -> "cold_start"
            | ProgressForecastSampledWorkOnly -> "sampled_work_only"
            | ProgressForecastReplayScheduleOnly -> "replay_schedule_only"
            | ProgressForecastReplayTerminalChatterNoRoot -> "replay_terminal_chatter_no_root"
            | ProgressForecastReplayDriverNoRoot -> "replay_driver_no_root"
            | ProgressForecastSparseRootNoSemantic -> "sparse_root_no_semantic"
            | ProgressForecastLowAuthorityRootTerminalDrip -> "low_authority_root_terminal_drip"
            | ProgressForecastDriverOrRootAuthority -> "driver_or_root_authority"

        let private progressForecastCapPct = function
            | ProgressForecastColdStart -> 5.0
            | ProgressForecastSampledWorkOnly -> 82.0
            | ProgressForecastReplayScheduleOnly -> 52.0
            | ProgressForecastReplayTerminalChatterNoRoot -> 60.0
            | ProgressForecastReplayDriverNoRoot -> 56.0
            | ProgressForecastSparseRootNoSemantic -> 68.0
            | ProgressForecastLowAuthorityRootTerminalDrip -> 90.5
            | ProgressForecastDriverOrRootAuthority -> 94.0

        let private progressForecastModelOrdinal = function
            | ProgressForecastColdStart -> 0
            | ProgressForecastSampledWorkOnly -> 1
            | ProgressForecastReplayScheduleOnly -> 2
            | ProgressForecastReplayTerminalChatterNoRoot -> 3
            | ProgressForecastReplayDriverNoRoot -> 4
            | ProgressForecastSparseRootNoSemantic -> 5
            | ProgressForecastLowAuthorityRootTerminalDrip -> 6
            | ProgressForecastDriverOrRootAuthority -> 7

        // ALPHA1215: migrate ETA string states to small DUs so telemetry
        // cannot silently drift into ad-hoc magic strings while the JSON
        // surface remains stable for downstream log consumers.
        type ProgressEtaTargetId =
            | ProgressEtaTargetAuthorityCap
            | ProgressEtaTargetOrganicAuthorityMargin

        type ProgressEtaSlopeBasisId =
            | ProgressEtaSlopeBasisNone
            | ProgressEtaSlopeBasisSampledWork
            | ProgressEtaSlopeBasisReplay
            | ProgressEtaSlopeBasisRoot
            | ProgressEtaSlopeBasisTerminal

        type ProgressEtaConfidenceId =
            | ProgressEtaUnknownStartup
            | ProgressEtaTargetReached
            | ProgressEtaUnknownNoRecentProgressDelta
            | ProgressEtaUnknownInsufficientAuthority
            | ProgressEtaUnknownStaleTerminalChurn
            | ProgressEtaSampledWorkRecentPctSlope
            | ProgressEtaSampledWorkCarryForward
            | ProgressEtaOrganicCapMarginRecentPctSlope
            | ProgressEtaAuthorityCapRecentPctSlope
            | ProgressEtaOrganicCapMarginCarryForward
            | ProgressEtaAuthorityCapCarryForward

        // ALPHA1217: heartbeat gap states are also typed now; the JSON label remains stable,
        // but the classification can no longer drift as ad-hoc string branches while the HUD
        // and minimal/rich ticks share the same cadence contract.
        type ProgressHeartbeatGapId =
            | ProgressHeartbeatGapOnTime
            | ProgressHeartbeatGapLate
            | ProgressHeartbeatGapCoalescedSnapshot

        let private progressHeartbeatGapText = function
            | ProgressHeartbeatGapOnTime -> "on_time"
            | ProgressHeartbeatGapLate -> "late"
            | ProgressHeartbeatGapCoalescedSnapshot -> "coalesced_snapshot"

        let private progressHeartbeatGapCode = function
            | ProgressHeartbeatGapOnTime -> 0
            | ProgressHeartbeatGapLate -> 1
            | ProgressHeartbeatGapCoalescedSnapshot -> 2

        let private progressHeartbeatGapFor missedIntervals =
            if missedIntervals >= 4L then ProgressHeartbeatGapCoalescedSnapshot
            elif missedIntervals > 0L then ProgressHeartbeatGapLate
            else ProgressHeartbeatGapOnTime

        type ProgressMetricsScoreBandId =
            | ProgressMetricsScoreCold
            | ProgressMetricsScoreWeak
            | ProgressMetricsScoreLive
            | ProgressMetricsScoreStrong
            | ProgressMetricsScoreSaturated

        let private progressMetricsScoreBandFor score =
            if score >= 900 then ProgressMetricsScoreSaturated
            elif score >= 750 then ProgressMetricsScoreStrong
            elif score >= 600 then ProgressMetricsScoreLive
            elif score >= 400 then ProgressMetricsScoreWeak
            else ProgressMetricsScoreCold

        let private progressMetricsScoreBandText = function
            | ProgressMetricsScoreCold -> "cold"
            | ProgressMetricsScoreWeak -> "weak"
            | ProgressMetricsScoreLive -> "live"
            | ProgressMetricsScoreStrong -> "strong"
            | ProgressMetricsScoreSaturated -> "saturated"

        let private progressMetricsScoreBandCode = function
            | ProgressMetricsScoreCold -> 0
            | ProgressMetricsScoreWeak -> 1
            | ProgressMetricsScoreLive -> 2
            | ProgressMetricsScoreStrong -> 3
            | ProgressMetricsScoreSaturated -> 4

        // ALPHA1218: the bottom HUD is only the renderer; the log stream is the
        // authoritative transport.  This DU marks which cadence supplied the
        // panel so stale rich snapshots do not masquerade as live data.
        type ProgressHudRefreshSourceId =
            | ProgressHudRefreshMinimalTick
            | ProgressHudRefreshMinimalTickStaleRich
            | ProgressHudRefreshRichSnapshot
            | ProgressHudRefreshCachedFallback

        let private progressHudRefreshSourceText = function
            | ProgressHudRefreshMinimalTick -> "minimal_tick_live"
            | ProgressHudRefreshMinimalTickStaleRich -> "minimal_tick_live_stale_rich"
            | ProgressHudRefreshRichSnapshot -> "rich_snapshot"
            | ProgressHudRefreshCachedFallback -> "cached_fallback"

        let private progressHudRefreshSourceCode = function
            | ProgressHudRefreshMinimalTick -> 1
            | ProgressHudRefreshMinimalTickStaleRich -> 4
            | ProgressHudRefreshRichSnapshot -> 2
            | ProgressHudRefreshCachedFallback -> 3

        let private progressEtaTargetText = function
            | ProgressEtaTargetAuthorityCap -> "authority_cap"
            | ProgressEtaTargetOrganicAuthorityMargin -> "organic_authority_margin"

        let private progressEtaSlopeBasisText = function
            | ProgressEtaSlopeBasisNone -> "none"
            | ProgressEtaSlopeBasisSampledWork -> "sampled_work_delta"
            | ProgressEtaSlopeBasisReplay -> "replay_progress_delta"
            | ProgressEtaSlopeBasisRoot -> "root_complete_delta"
            | ProgressEtaSlopeBasisTerminal -> "terminal_signal_delta"

        let private progressEtaSlopeBasisFor sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta =
            if terminalSignalDelta > 0 then ProgressEtaSlopeBasisTerminal
            elif rootCompleteDelta > 0 then ProgressEtaSlopeBasisRoot
            elif replayProgressDelta > 0 then ProgressEtaSlopeBasisReplay
            elif sampledWorkDelta > 0 then ProgressEtaSlopeBasisSampledWork
            else ProgressEtaSlopeBasisNone

        let private progressEtaConfidenceText = function
            | ProgressEtaUnknownStartup -> "unknown_startup"
            | ProgressEtaTargetReached -> "target_reached"
            | ProgressEtaUnknownNoRecentProgressDelta -> "unknown_no_recent_progress_delta"
            | ProgressEtaUnknownInsufficientAuthority -> "unknown_insufficient_authority"
            | ProgressEtaUnknownStaleTerminalChurn -> "unknown_stale_terminal_churn"
            | ProgressEtaSampledWorkRecentPctSlope -> "sampled_work_only_recent_pct_slope"
            | ProgressEtaSampledWorkCarryForward -> "sampled_work_only_carry_forward"
            | ProgressEtaOrganicCapMarginRecentPctSlope -> "organic_cap_margin_recent_pct_slope"
            | ProgressEtaAuthorityCapRecentPctSlope -> "authority_cap_recent_pct_slope"
            | ProgressEtaOrganicCapMarginCarryForward -> "organic_cap_margin_carry_forward"
            | ProgressEtaAuthorityCapCarryForward -> "authority_cap_carry_forward"

        let private progressForecastModelFor sampledWork replaySchedules replayDrivers replayYields rootComplete terminalSignals semanticReceipts =
            let lowAuthorityRootTerminalDrip =
                replaySchedules > 0
                && replaySchedules <= 64
                && replayDrivers <= 16
                && rootComplete > 0
                && rootComplete <= 8
                && terminalSignals > 0
                && terminalSignals <= 32
            if sampledWork <= 0 then ProgressForecastColdStart
            elif lowAuthorityRootTerminalDrip then ProgressForecastLowAuthorityRootTerminalDrip
            elif terminalSignals > 0 || semanticReceipts > 0 || rootComplete > 16 then ProgressForecastDriverOrRootAuthority
            elif rootComplete > 0 then ProgressForecastSparseRootNoSemantic
            elif replayDrivers > 0 && rootComplete <= 0 then ProgressForecastReplayDriverNoRoot
            elif replaySchedules > 0 && terminalSignals > 0 && rootComplete <= 0 && replayDrivers <= 16 then ProgressForecastReplayTerminalChatterNoRoot
            elif replaySchedules + replayYields > 0 then ProgressForecastReplayScheduleOnly
            else ProgressForecastSampledWorkOnly

        let private writeProgressHeartbeatLineDirect (line: string) =
            CompilerConsoleHud88.writeProgressJsonLineNonBlocking line

        let private refreshProgressHeartbeatHudOnlyDirect (line: string) =
            CompilerConsoleHud88.refreshProgressJsonLineNonBlocking line

        let private writeProgressHeartbeatLine (_directWrite: bool) (line: string) =
            writeProgressHeartbeatLineDirect line

        let private compactOverviewCode (state: string) =
            state |> progressOverviewStateOfString |> progressOverviewStateCode

        let private compactParallelismCode (state: string) =
            state |> progressParallelismStateOfString |> progressParallelismStateCode

        let lastRichSampledDelta () =
            System.Threading.Interlocked.Read(&progressPredictionLastRichSampledDelta)

        let lastRichReplayDelta () =
            System.Threading.Interlocked.Read(&progressPredictionLastRichReplayDelta)

        let lastRichRootDelta () =
            System.Threading.Interlocked.Read(&progressPredictionLastRichRootDelta)

        let lastRichTerminalDelta () =
            System.Threading.Interlocked.Read(&progressPredictionLastRichTerminalDelta)

        let lastRichTickAgeMs () =
            let lastMs = System.Threading.Interlocked.Read(&progressPredictionLastRichTickMs)
            if lastMs <= 0L then 999999
            else
                let age = max 0L (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - lastMs)
                if age > int64 System.Int32.MaxValue then System.Int32.MaxValue else int age

        let private emitTrueMetronomeBeat (scheduledMs: int64) =
            try
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let baseBefore = System.Threading.Interlocked.CompareExchange(&progressPredictionMetronomeStartMs, scheduledMs, 0L)
                let baseMs = if baseBefore = 0L then scheduledMs else baseBefore
                let beatNo = System.Threading.Interlocked.Increment(&progressPredictionMetronomeBeatTick)
                let lagMs = if scheduledMs > 0L then max 0L (now - scheduledMs) else 0L
                let missed = if scheduledMs > 0L then lagMs / progressPredictionMinimalCadenceMs else 0L
                let lastRichMs = System.Threading.Interlocked.Read(&progressPredictionLastRichTickMs)
                let richStartedMs = System.Threading.Interlocked.Read(&progressPredictionRichTickStartedMs)
                let richInFlight = System.Threading.Interlocked.CompareExchange(&progressPredictionRichTickInFlight, 0, 0) <> 0
                let richAgeMs = if lastRichMs > 0L then max 0L (now - lastRichMs) else -1L
                let richBusyMs = if richInFlight && richStartedMs > 0L then max 0L (now - richStartedMs) else 0L
                let lastRichTickNo = System.Threading.Interlocked.Read(&progressPredictionLastRichTickNo)
                let lastProgressPct = float (System.Threading.Interlocked.Read(&progressPredictionLastRichProgressBp)) / 100.0
                let lastSampledWork = System.Threading.Interlocked.Read(&progressPredictionLastRichSampledWork)
                let lastCpuCoreEquiv = float (System.Threading.Interlocked.Read(&progressPredictionLastRichCpuCoreMilli)) / 1000.0
                let etaS = System.Threading.Interlocked.Read(&progressPredictionLastRichEtaS)
                let totalS = System.Threading.Interlocked.Read(&progressPredictionLastRichTotalS)
                let semanticReceipts =
                    int64 (
                        snapshotKindCount "eval_worklist_payload"
                        + snapshotKindCount "eval_worklist_replay_commit"
                        + snapshotKindCount "eval_worklist_replay_reduce"
                        + snapshotKindCount "eval_worklist_replay_step"
                        + snapshotKindCount "eval_worklist_frame_parent_continuation")
                let structuralReceipts =
                    int64 (
                        snapshotKindCount "eval_worklist_apply_spine_post_fuse_recursive_children_registered"
                        + snapshotKindCount "eval_worklist_if_branch_children_registered"
                        + snapshotKindCount "eval_worklist_type_apply_arg_tv_env_snapshot"
                        + snapshotKindCount "eval_worklist_type_fun_tv_child_env_snapshot")
                let sites = int64 progressSpiralSites.Count
                let replaySchedules =
                    int64 (
                        snapshotKindCount "eval_worklist_replay_schedule"
                        + snapshotKindCount "eval_worklist_parent_replay_key_dedupe"
                        + snapshotKindCount "eval_worklist_cache_write_parent_handoff_enqueued")
                let replayDrivers =
                    int64 (
                        snapshotKindCount "eval_worklist_replay_driver"
                        + snapshotKindCount "eval_worklist_replay_step"
                        + snapshotKindCount "eval_worklist_replay_reduce"
                        + snapshotKindCount "eval_worklist_replay_commit"
                        + snapshotKindCount "eval_worklist_replay_payload_cell_hydrated")
                let replayYields =
                    int64 (
                        snapshotKindCount "eval_worklist_replay_driver_cooperative_yielded"
                        + snapshotKindCount "eval_worklist_replay_driver_stack_fence_yielded"
                        + snapshotKindCount "eval_worklist_global_fuse_deferred_replay_tick_requested")
                let rootComplete =
                    int64 (
                        snapshotKindCount "eval_worklist_root_complete_replay_progress_marked"
                        + snapshotKindCount "eval_worklist_source_value_stored"
                        + snapshotKindCount "eval_worklist_global_fuse_term_replay_return"
                        + snapshotKindCount "bigstack_root_complete_probe"
                        + snapshotKindCount "eval_worklist_resume")
                let terminalSignals =
                    int64 (
                        snapshotKindCount "eval_frontier"
                        + snapshotKindCount "eval_worklist_jp_wait_hidden_countdown_triage"
                        + snapshotKindCount "term_reentry_fuse"
                        + snapshotKindCount "eval_worklist_terminal_poison_cascade"
                        + snapshotKindCount "eval_worklist_terminal_contract_pinned")
                let physicalHandoffs =
                    int64 (
                        snapshotKindCount "eval_worklist_deferred_type_var_direct_cell_physical_handoff_requested"
                        + snapshotKindCount "eval_worklist_deferred_type_var_direct_cell_cycle_break_exhausted_poison"
                        + snapshotKindCount "eval_worklist_deferred_type_var_direct_cell_cycle_break"
                        + snapshotKindCount "eval_worklist_replay_queue_surge_parent_poison_injected"
                        + snapshotKindCount "eval_worklist_bigstack_pinned_terminal_queue_drain_deferred"
                        + snapshotKindCount "eval_worklist_forced_orphan_drain_worker_requested")
                let parentEnqueueDebt =
                    max 0L (replaySchedules - replayDrivers)
                    + int64 (snapshotKindCount "eval_worklist_parent_continuation_explicit_enqueue")
                let rawSampledWork = semanticReceipts + structuralReceipts
                let sampledWork =
                    let lastBeatSampled = System.Threading.Interlocked.Read(&progressPredictionLastBeatSampledWork)
                    max rawSampledWork lastBeatSampled
                let replayProgress = replaySchedules + replayDrivers + replayYields
                let sampledDelta = max 0L (sampledWork - System.Threading.Interlocked.Exchange(&progressPredictionLastBeatSampledWork, sampledWork))
                let replayDelta = max 0L (replayProgress - System.Threading.Interlocked.Exchange(&progressPredictionLastBeatReplayProgress, replayProgress))
                let rootDelta = max 0L (rootComplete - System.Threading.Interlocked.Exchange(&progressPredictionLastBeatRootComplete, rootComplete))
                let terminalDelta = max 0L (terminalSignals - System.Threading.Interlocked.Exchange(&progressPredictionLastBeatTerminalSignals, terminalSignals))
                let minimalLateRaceTinyReplayDripReceiptCount = int64 (snapshotKindCount "eval_worklist_bigstack_pinned_terminal_late_race_queue_drain_deferred")
                let minimalSidecarSameKeyChurnReceiptCount =
                    int64 (
                        snapshotKindCount "eval_worklist_parent_replay_status_preserved_deferred_scheduler_yield"
                        + snapshotKindCount "eval_worklist_parent_replay_status_preserved_deferred_bubbled"
                        + snapshotKindCount "eval_worklist_replay_same_node_site_drift_preserved"
