                                ts pid tid (esc run_id) elapsedS progressPct underutilizedReplayS (esc underutilizedReplayDecisionLabel) cpuCoreEquiv tickCpuMachinePct sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta singleFlightWaitAcquired singleFlightWaitTimeout (esc (noWorkReplayEvidenceText noWorkReplayEvidenceId)) (esc (noWorkGateDecisionText noWorkGateDecisionId)) (esc plateauDecisionText) replaySchedules replayDrivers rootCompleteStores terminalSignals (esc "[spiral_compiler] EJP0023 held: low CPU is reproducible, but typed replay/no-work evidence is still inside a bounded drain window.") (processResourceSnapshotJsonFields tickCpuDeltaMs tickCpuWallDeltaMs tickCpuPct tickCpuMachinePct)
                        writeProgressHeartbeatLine directWrite underHoldLine
                    if underutilizedAbortRecommended && underutilizedReplayS >= underutilizedAbortThresholdS && underutilizedReplayDecisionIsAbort underutilizedReplayDecisionId then
                        let underAbortLine =
                            sprintf "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"compile_progress_underutilized_abort\",\"event\":\"heartbeat_hard_abort\",\"source\":\"DiagJson.heartbeat_thread\",\"elapsed_s\":%d,\"progress_pct\":%.4f,\"underutilized_replay_s\":%d,\"underutilized_decision_du\":%s,\"cpu_core_equiv\":%.4f,\"cpu_machine_pct\":%.4f,\"sampled_work_delta\":%d,\"replay_progress_delta\":%d,\"terminal_signal_delta\":%d,\"single_flight_wait_acquired\":%d,\"single_flight_wait_timeout\":%d,\"message\":%s,\"policy\":\"fail_closed_low_cpu_replay_starvation_no_buildok\"%s}"
                                ts pid tid (esc run_id) elapsedS progressPct underutilizedReplayS (esc underutilizedReplayDecisionLabel) cpuCoreEquiv tickCpuMachinePct sampledWorkDelta replayProgressDelta terminalSignalDelta singleFlightWaitAcquired singleFlightWaitTimeout (esc "[spiral_compiler] EJP0023: replay is live but CPU/core use is too low beyond the typed drain window; aborting with a reproducible frontier instead of waiting for manual interrupt.") (processResourceSnapshotJsonFields tickCpuDeltaMs tickCpuWallDeltaMs tickCpuPct tickCpuMachinePct)
                        writeProgressHeartbeatLine directWrite underAbortLine
                        System.Environment.Exit(223)
                    if noWorkAbortRecommended && noWorkAbortReady then
                        let noWorkAbortLine =
                            sprintf "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"compile_progress_no_work_abort\",\"event\":\"heartbeat_hard_abort\",\"source\":\"DiagJson.heartbeat_thread\",\"elapsed_s\":%d,\"progress_pct\":%.4f,\"overview_state\":%s,\"overview_state_du\":%s,\"parallelism_state\":%s,\"parallelism_state_du\":%s,\"no_work_abort_reason_du\":%s,\"no_work_abort_ready\":%b,\"no_work_stall_s\":%d,\"no_work_pokes\":%d,\"no_work_rescue_in_flight\":%b,\"no_work_rescue_age_ms\":%d,\"no_work_rescue_completed\":%d,\"no_work_rescue_gate_busy\":%d,\"no_work_rescue_saturated\":%b,\"no_work_replay_evidence_du\":%s,\"no_work_gate_decision_du\":%s,\"no_work_mid_graph_holdoff\":%b,\"work_idle_s\":%d,\"replay_idle_s\":%d,\"stats_sampled_work\":%d,\"sampled_work_delta\":%d,\"replay_progress_delta\":%d,\"root_complete_delta\":%d,\"terminal_signal_delta\":%d,\"replay_schedules\":%d,\"replay_driver_ticks\":%d,\"replay_cooperative_yields\":%d,\"root_complete_receipts\":%d,\"terminal_signals\":%d,\"single_flight_wait_acquired\":%d,\"single_flight_wait_timeout\":%d,\"message\":%s,\"proof_tuple_complete\":true,\"materialized_terminal_payload_du\":\"NoWorkAbortRescueWorkerTerminalCommit\",\"hopac_ivar_registry_id\":\"no_work_abort:rescue_worker_terminal_commit\",\"witness_type\":\"NoWorkAbortRescueWorkerProof\",\"native_hopac_callback_route_du\":\"IVar.fill(no_work_abort:rescue_worker_terminal_commit)\",\"native_promise_identifier_du\":\"promise_id(no_work_abort:rescue_worker_terminal_commit,NoWorkAbortRescueWorkerProof)\",\"commit_pathway_trace_du\":\"no_work_abort_rescue_worker->IVar.fill->Job.unit\",\"active_native_callback_closure_du\":\"callback=IVar.fill(no_work_abort:rescue_worker_terminal_commit)|boundary=execute_native_direct_ast_eval_before_polling_boundary|return=Job.unit|legacy=false\",\"native_callback_control_flow_gate_du\":\"proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_Job.unit->legacy_unreachable\",\"callback_tracer_du\":\"[Witness:NoWorkAbortRescueWorkerProof]->[IVar:no_work_abort:rescue_worker_terminal_commit]->[Action:IVar.fill]\",\"thread_fate_du\":\"native_hopac_run_queue_after_inline_callback\",\"eval_worklist_boundary_reachable_after_callback\":false,\"legacy_live_tail_veto_reachable\":false,\"qap_observer_policy_du\":\"observer_only_after_no_work_abort_rescue_worker_proof_tuple\",\"policy\":\"fail_closed_typed_no_work_after_replay_with_rescue_worker_evidence_no_buildok_no_writer\"%s}"
                                ts pid tid (esc run_id) elapsedS progressPct (esc overviewState) (esc (progressOverviewStateText overviewStateId)) (esc parallelismState) (esc (progressParallelismStateText parallelismStateId)) (esc (noWorkAbortReasonText noWorkAbortReason)) noWorkAbortReady noWorkAbortEvidenceS noWorkPokeCount noWorkRescueInFlight noWorkRescueAgeMs noWorkRescueCompleted noWorkRescueGateBusyCount noWorkRescueSaturated (esc (noWorkReplayEvidenceText noWorkReplayEvidenceId)) (esc (noWorkGateDecisionText noWorkGateDecisionId)) noWorkMidGraphHoldoff workIdleS replayIdleS sampledWork sampledWorkDelta replayProgressDelta rootCompleteDelta terminalSignalDelta replaySchedules replayDrivers replayYields rootCompleteStores terminalSignals singleFlightWaitAcquired singleFlightWaitTimeout (esc "[spiral_compiler] EJP0024: heartbeat observed no sampled, replay, root, or terminal progress after live replay receipts with typed abort reason; aborting with a reproducible no-work frontier instead of waiting for manual interrupt.") (processResourceSnapshotJsonFields tickCpuDeltaMs tickCpuWallDeltaMs tickCpuPct tickCpuMachinePct)
                        writeProgressHeartbeatLine directWrite noWorkAbortLine
                        System.Environment.Exit(224)
            with _ -> ()

        let private emitProgressPredictionTickIfDue () =
            emitProgressPredictionTick false 0L "DiagJson.emit_opportunistic" false

        let private emitProgressPredictionTickMetronome (scheduledMs: int64) =
            emitTrueMetronomeBeat scheduledMs
            let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let beatNo = System.Threading.Interlocked.Read(&progressPredictionMetronomeBeatTick)
            let lastRichMs = System.Threading.Interlocked.Read(&progressPredictionLastRichTickMs)
            let richAgeMs = if lastRichMs > 0L then max 0L (now - lastRichMs) else 999999L
            let shouldQueueRich =
                lastRichMs = 0L
                || (beatNo <= 8L && richAgeMs >= progressPredictionMinimalCadenceMs)
                || richAgeMs >= progressPredictionRichCadenceMs
            if shouldQueueRich && System.Threading.Interlocked.CompareExchange(&progressPredictionRichTickInFlight, 1, 0) = 0 then
                System.Threading.Interlocked.Exchange(&progressPredictionRichTickStartedMs, now) |> ignore
                try
                    System.Threading.ThreadPool.QueueUserWorkItem(System.Threading.WaitCallback(fun _ ->
                        try
                            emitProgressPredictionTick true scheduledMs "DiagJson.true_metronome_rich_diag_async" true
                        finally
                            System.Threading.Interlocked.Exchange(&progressPredictionRichTickInFlight, 0) |> ignore)) |> ignore
                with _ ->
                    System.Threading.Interlocked.Exchange(&progressPredictionRichTickInFlight, 0) |> ignore

        let private progressPredictionHeartbeatStarted =
            lazy (
                try
                    try
                        let desiredWorkers = max 128 ((max 1 System.Environment.ProcessorCount) * 32)
                        let mutable minWorkers = 0
                        let mutable minIo = 0
                        System.Threading.ThreadPool.GetMinThreads(&minWorkers, &minIo) |> ignore
                        if minWorkers < desiredWorkers then
                            System.Threading.ThreadPool.SetMinThreads(desiredWorkers, minIo) |> ignore
                    with _ -> ()
                    let loop =
                        System.Threading.ThreadStart(fun () ->
                            let cadenceMs = progressPredictionMinimalCadenceMs
                            let mutable nextDueMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() + cadenceMs
                            while true do
                                try
                                    let mutable nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    while nowMs < nextDueMs do
                                        let sleepMs = int (min 5L (max 1L (nextDueMs - nowMs)))
                                        try System.Threading.Thread.Sleep(sleepMs) with _ -> ()
                                        nowMs <- System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    try emitProgressPredictionTickMetronome nextDueMs with _ -> ()
                                    let afterMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                                    let nominalNextDueMs = nextDueMs + cadenceMs
                                    if afterMs >= nominalNextDueMs then
                                        nextDueMs <- afterMs + cadenceMs
                                    else
                                        nextDueMs <- nominalNextDueMs
                                with _ ->
                                    try System.Threading.Thread.Sleep(5) with _ -> ())
                    let th = System.Threading.Thread(loop)
                    th.IsBackground <- true
                    try th.Name <- "spiral-progress-prediction-heartbeat" with _ -> ()
                    try th.Priority <- System.Threading.ThreadPriority.AboveNormal with _ -> ()
                    th.Start()
                    true
                with _ -> false)

        let private ensureProgressPredictionHeartbeat () =
            try progressPredictionHeartbeatStarted.Force() |> ignore with _ -> ()

        // ALPHA1238: replay/handoff receipts are not generic noise anymore.
        // The 1237 log proved the graph can move while the rich heartbeat is stale,
        // so these families get a much denser typed cadence.
        type JsonTelemetryDetailId =
            | JsonTelemetryCritical
            | JsonTelemetryReplayDetail
            | JsonTelemetryHandoffDetail
            | JsonTelemetryCycleBreakDetail
            | JsonTelemetryObligationDetail
            | JsonTelemetryQueueChatter
            | JsonTelemetryDeprecatedChatter
            | JsonTelemetryHudDetail
            | JsonTelemetryGenericNoisy

        let private jsonTelemetryDetailForKind (kind: string) =
            if System.String.IsNullOrWhiteSpace kind then JsonTelemetryCritical
            elif kind = "eval_worklist_parent_replay_key_dedupe"
                 || kind = "eval_worklist_replay_driver_stack_fence_yielded"
                 || kind = "eval_worklist_global_fuse_deferred_replay_queue_preserved"
                 || kind = "eval_worklist_single_flight_busy_no_sync_wait"
                 || kind = "eval_worklist_single_flight_reacquired_after_graph_tick"
                 || kind = "eval_worklist_orphan_global_fuse_live_replay_deferred"
                 || kind = "eval_worklist_ty_orphan_global_fuse_live_replay_deferred"
                 || kind = "eval_worklist_root_complete_stale_retarget_suppressed_after_witness_no_reinsert"
                 || kind = "eval_worklist_adapter"
                 || kind = "eval_worklist_cache_write_parent_handoff_enqueued"
                 || kind = "eval_worklist_global_fuse_deferred_replay_tick_requested"
                 || kind = "eval_worklist_parent_handoff_driver_wake_requested"
                 || kind = "eval_worklist_parent_continuation_explicit_enqueue"
                 || kind = "eval_worklist_bigstack_queue_only_replay_driver_tick_requested"
                 || kind = "eval_worklist_parent_replay_status_preserved"
                 || kind = "eval_worklist_typed_worklist_facade_active"
                 || kind.Contains("_children_registered", StringComparison.Ordinal)
                 || kind.Contains("_tv_env_snapshot", StringComparison.Ordinal)
                 || kind.Contains("_free_metavar_snapshot", StringComparison.Ordinal)
                 || kind.Contains("_reentry_prefetch_replay_drained", StringComparison.Ordinal) then JsonTelemetryQueueChatter
            elif kind = "eval_worklist_deferred_type_var_cycle_break_scheduled" then JsonTelemetryCycleBreakDetail
            elif kind = "eval_worklist_replay_obligation_deferred" then JsonTelemetryObligationDetail
            elif kind.Contains("replay_driver", StringComparison.Ordinal)
                 || kind.Contains("replay_step", StringComparison.Ordinal)
                 || kind.Contains("replay_reduce", StringComparison.Ordinal)
                 || kind.Contains("replay_commit", StringComparison.Ordinal)
                 || kind.Contains("parent_resume", StringComparison.Ordinal)
                 || kind.Contains("typed_worklist_facade_active", StringComparison.Ordinal) then JsonTelemetryReplayDetail
            elif kind.Contains("handoff", StringComparison.Ordinal)
                 || kind.Contains("parent_continuation", StringComparison.Ordinal)
                 || kind.Contains("queue_only_replay_driver", StringComparison.Ordinal) then JsonTelemetryHandoffDetail
            elif kind = "eval_worklist_hud_snapshot"
                 || kind = "rich_diag_busy"
                 || kind = "rich_diag_watchdog_reset" then JsonTelemetryHudDetail
            elif kind = "eval_worklist_forced_pressure_drain_worker_requested"
                 || kind = "eval_worklist_raise_retry_queue_surge_repeat_cap_probation_drain"
                 || kind = "eval_worklist_raise_retry_queue_surge_repeat_cap_probation_exhausted_parent_poison"
                 || kind = "eval_worklist_bigstack_replay_no_root_finish_budget"
                 || kind = "eval_worklist_bigstack_dynamic_join_terminal_deferred_for_live_replay"
                 || kind = "eval_worklist_bigstack_dynamic_join_pending_zero_no_writer_decision"
                 || kind = "eval_worklist_replay_queue_surge_parent_poison_suppressed_live_tail"
                 || kind = "eval_worklist_parent_replay_poison_repeat_cap_fresh_root_pin_suppressed"
                 || kind = "eval_worklist_live_replay_parent_replay_poison_pin_suppressed"
                 || kind = "eval_worklist_bigstack_hot_frontier_repeat_cap_probation_guard"
                 || kind = "eval_worklist_forced_active_tail_quiescent_no_queue"
                 || kind = "eval_worklist_replay_obligation_deferred_cross_kind_shielded"
                 || kind = "eval_worklist_cross_kind_yield_thrash_deferred_fresh_pending_tail"
                 || kind = "eval_worklist_cross_kind_yield_thrash_deferred_zero_repeat_active_tail"
                 || kind = "eval_worklist_cross_kind_live_tail_blocks_post_schedule_hard_poison"
                 || kind = "eval_worklist_queue_surge_repeated_deferral_matured"
                 || kind = "eval_worklist_bigstack_no_root_budget_pre_cap_active_tail_override_probation_drain"
                 || kind = "eval_worklist_bigstack_pinned_terminal_queue_drain_deferred"
                 || kind = "eval_worklist_bigstack_pinned_terminal_late_race_queue_drain_deferred"
                 || kind = "eval_worklist_replay_driver_cooperative_cap_breach_surface"
                 || kind = "eval_worklist_parent_replay_status_preserved_repeat_deferred_live_replay"
                 || kind = "eval_worklist_bigstack_dynamic_join_late_tail_deferred_live_queue"
                 || kind = "eval_worklist_replay_parent_poison_deferred_cold_structural_surge"
                 || kind = "eval_worklist_replay_queue_surge_parent_poison_event_cap_suppressed"
                 || kind = "eval_worklist_bigstack_terminal_frontier_snapshot"
                 || kind = "eval_worklist_bigstack_sequential_hot_frontier_fast_retry"
                 || kind = "eval_worklist_parent_replay_poison_stale_pending_witness_force_surface"
                 || kind = "eval_worklist_cross_kind_yield_thrash_hard_poison"
                 || kind = "eval_worklist_replay_obligation_post_schedule_cap_hard_poison"
                 || kind = "eval_worklist_bigstack_parent_replay_repeat_terminal_pending_zero_physical_tail_draining"
                 || kind = "eval_worklist_bigstack_parent_replay_recent_progress_credit_exhausted"
                 || kind = "eval_worklist_bigstack_parent_replay_poison_live_tail_cap_exhausted"
                 || kind = "compile_progress_metronome_no_work_saturation_grace"
                 || kind = "progress_tick_no_work_rescue_requested"
                 || kind = "progress_tick_no_work_rescue_worker_started"
                 || kind = "progress_tick_no_work_rescue_worker_finished"
                 || kind = "eval_worklist_root_complete_stale_retarget_repeat_blocked"
                 || kind = "eval_worklist_root_complete_stale_retarget_pending_no_queue_live_deferred"
                 || kind = "eval_worklist_idle_cross_kind_replay_poke_resumed"
                 || kind = "eval_worklist_replay_obligation_run"
                 || kind = "compile_progress_stall_probe"
                 || kind = "progress_tick_replay_detail"
                 || kind = "eval_worklist_replay_driver_stack_fence_cap_breach_probation_guard"
                 || kind = "eval_worklist_replay_driver_cooperative_cap_breach_probation_guard"
                 || kind = "eval_worklist_replay_driver_stack_fence_cap_breach_surface"
                 || kind = "eval_worklist_tfun_body_tv_binder_snapshot"
                 || kind = "eval_worklist_terminal_poison_cascade"
                 || kind = "eval_worklist_bigstack_no_root_budget_repeat_cap_pending_semantic_probation_drain"
                 || kind = "eval_worklist_idle_deferred_replay_poke_resumed"
                 || kind = "eval_worklist_type_source_value_replay_return"
                 || kind = "eval_worklist_direct_cycle_replay_return"
                 || kind = "eval_worklist_replay_fingerprint_repeat"
                 || kind = "eval_worklist_live_replay_fingerprint_repeat_deferred"
                 || kind = "eval_worklist_apply_function_body_part_eval_type_error_arg_binder_tail_deferred" then JsonTelemetryDeprecatedChatter
            elif isNoisyJsonKind kind then JsonTelemetryGenericNoisy
            else JsonTelemetryCritical

        let private jsonTelemetryDetailCadence = function
            | JsonTelemetryReplayDetail -> EmitSparsePowerThenHeartbeat 512
            | JsonTelemetryHandoffDetail -> EmitFirstThenHeartbeat 1024
            | JsonTelemetryCycleBreakDetail -> EmitSparsePowerThenHeartbeat 512
            | JsonTelemetryObligationDetail -> EmitSparsePowerThenHeartbeat 512
            | JsonTelemetryQueueChatter -> EmitFirstThenHeartbeat 4096
            | JsonTelemetryDeprecatedChatter -> EmitFirstThenHeartbeat 65536
            | JsonTelemetryHudDetail -> EmitSparsePowerThenHeartbeat 128
            | JsonTelemetryGenericNoisy -> EmitFirstThenHeartbeat 8192
            | JsonTelemetryCritical -> EmitAlways

        let private jsonTelemetryDetailKey detailId kind line =
            match detailId with
            | JsonTelemetryReplayDetail
            | JsonTelemetryHandoffDetail ->
                let driver = jsonStringField "driver" line
                let decision = jsonStringField "decision_du" line
                let status = jsonStringField "status_du" line
                kind + "|driver=" + driver + "|decision=" + decision + "|status=" + status
            | JsonTelemetryCycleBreakDetail ->
                let decision = jsonStringField "decision_du" line
                kind + "|decision=" + decision
            | JsonTelemetryObligationDetail ->
                let reason = jsonStringField "reason_du" line
                let targetKind = jsonStringField "target_kind" line
                kind + "|reason=" + reason + "|target=" + targetKind
            | JsonTelemetryQueueChatter -> kind
            | JsonTelemetryDeprecatedChatter -> kind
            | JsonTelemetryHudDetail -> kind
            | _ -> kind

        let private shouldEmitJsonLine (line: string) =
            let kind = jsonStringField "kind" line
            let structurallyNoisy =
                kind.Contains("_snapshot", StringComparison.Ordinal)
                || kind.Contains("_children_registered", StringComparison.Ordinal)
                || kind.Contains("_scheduled", StringComparison.Ordinal)
                || kind.Contains("_suppressed", StringComparison.Ordinal)
                || kind.Contains("_payload", StringComparison.Ordinal)
                || kind.Contains("_step", StringComparison.Ordinal)
                || kind.Contains("_consume", StringComparison.Ordinal)
                || kind.Contains("_wait_", StringComparison.Ordinal)
                || kind.Contains("_cached_children_", StringComparison.Ordinal)
                || kind.Contains("_children_resolved", StringComparison.Ordinal)
                || kind.Contains("_source_value_stored", StringComparison.Ordinal)
                || kind.Contains("_replay_", StringComparison.Ordinal)
                || kind.Contains("_parent_continuation", StringComparison.Ordinal)
                || kind.Contains("_terminal_", StringComparison.Ordinal)
                || kind.Contains("_handoff", StringComparison.Ordinal)
            let emissionClass =
                let detailId = jsonTelemetryDetailForKind kind
                match detailId with
                | JsonTelemetryCritical -> CriticalEvidence
                | _ ->
                    // A line that carries an explicit terminal/blocked status gets its own
                    // typed sample key.  Replay/handoff families also include driver and
                    // decision dimensions so detailed logs stay visible during live drains.
                    let status = jsonStringField "status" line
                    let sampleKey0 = jsonTelemetryDetailKey detailId kind line
                    let sampleKey =
                        if status.Contains("blocked", StringComparison.Ordinal)
                           || status.Contains("terminal", StringComparison.Ordinal)
                        then sampleKey0 + "|status=" + status
                        else sampleKey0
                    CompositeEvidence(NoisyEvidence(sampleKey, jsonTelemetryDetailCadence detailId), None)
            match shouldEmitEmissionClass emissionClass with
            | EmitLine -> true
            | DropRepeatedLine _ -> false

        // ALPHA1191: 1190 proved the heartbeat can choose hold_live_replay_evidence
        // and still lose to the global DiagJson.emit plateau fuse later.  Keep the
        // global fuse typed: if the last rich snapshot still has replay/root authority
        // and no fresh deltas, extend a short bounded lease and emit a direct receipt;
        // otherwise preserve the fail-closed EJP0022 raise.
        type PlateauGlobalEmitGuardDecisionId =
            | PlateauGlobalEmitGuardRaise
            | PlateauGlobalEmitGuardHoldLiveReplayEvidence
            | PlateauGlobalEmitGuardWaitHoldoff

        let plateauGlobalEmitGuardDecisionText = function
            | PlateauGlobalEmitGuardRaise -> "raise_ejp0022"
            | PlateauGlobalEmitGuardHoldLiveReplayEvidence -> "hold_live_replay_evidence"
            | PlateauGlobalEmitGuardWaitHoldoff -> "wait_existing_holdoff"

        let emit (json: string) =
            if progressPredictionPlateauAbortRequested then
                let now = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                let earliestRaiseMs = System.Threading.Interlocked.Read(&progressPredictionPlateauAbortEarliestRaiseMs)
                let holdoffUntilMs = System.Threading.Interlocked.Read(&progressPredictionPlateauAbortHoldoffUntilMs)
                let gateOpen = (earliestRaiseMs <= 0L || now >= earliestRaiseMs) && now >= holdoffUntilMs
                if gateOpen then
                    let lastReplaySchedules = System.Threading.Interlocked.Read(&progressPredictionLastRichReplaySchedules)
                    let lastReplayDrivers = System.Threading.Interlocked.Read(&progressPredictionLastRichReplayDrivers)
                    let lastRootComplete = System.Threading.Interlocked.Read(&progressPredictionLastRichRootComplete)
                    let lastTerminalSignals = System.Threading.Interlocked.Read(&progressPredictionLastRichTerminalSignals)
                    let lastSampledDelta = System.Threading.Interlocked.Read(&progressPredictionLastRichSampledDelta)
                    let lastReplayDelta = System.Threading.Interlocked.Read(&progressPredictionLastRichReplayDelta)
                    let lastRootDelta = System.Threading.Interlocked.Read(&progressPredictionLastRichRootDelta)
                    let lastTerminalDelta = System.Threading.Interlocked.Read(&progressPredictionLastRichTerminalDelta)
                    let lastNoWorkS = System.Threading.Interlocked.Read(&progressPredictionLastRichNoWorkS)
                    let liveReplayEvidence =
                        lastReplayDrivers > 0L
                        || lastRootComplete > 0L
                        || (lastReplaySchedules > 0L && lastTerminalSignals > 0L)
                    let noFreshDelta =
                        lastSampledDelta <= 0L
                        && lastReplayDelta <= 0L
                        && lastRootDelta <= 0L
                        && lastTerminalDelta <= 0L
                    let guardDecisionId =
                        if liveReplayEvidence && noFreshDelta && lastNoWorkS < 180L then PlateauGlobalEmitGuardHoldLiveReplayEvidence
                        else PlateauGlobalEmitGuardRaise
                    match guardDecisionId with
                    | PlateauGlobalEmitGuardHoldLiveReplayEvidence ->
                        let nextHoldoffUntilMs = now + 30000L
                        System.Threading.Interlocked.Exchange(&progressPredictionPlateauAbortHoldoffUntilMs, nextHoldoffUntilMs) |> ignore
                        let pid = string (System.Diagnostics.Process.GetCurrentProcess().Id)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        let line =
                            sprintf """{"v":1,"ts_ms":%d,"pid":%s,"tid":%s,"run_id":%s,"kind":"compile_progress_plateau_global_emit_guard_holdoff","event":"diag_emit_plateau_guard","decision_du":%s,"last_no_work_s":%d,"last_replay_scheduled":%d,"last_replay_driver_ticks":%d,"last_root_receipts":%d,"last_terminal_signals":%d,"last_sampled_delta":%d,"last_replay_delta":%d,"last_root_delta":%d,"last_terminal_delta":%d,"holdoff_ms":30000,"policy":"typed_global_emit_guard_respects_live_replay_holdoff_no_buildok_no_writer"}"""
                                now pid tid (esc run_id) (esc (plateauGlobalEmitGuardDecisionText guardDecisionId)) lastNoWorkS lastReplaySchedules lastReplayDrivers lastRootComplete lastTerminalSignals lastSampledDelta lastReplayDelta lastRootDelta lastTerminalDelta
                        writeProgressHeartbeatLineDirect line
                    | PlateauGlobalEmitGuardRaise ->
                        raise (System.InvalidOperationException(progressPredictionAbortMessage()))
                    | PlateauGlobalEmitGuardWaitHoldoff -> ()
            try
                let trimmed = if System.Object.ReferenceEquals(json,null) then "" else json.Trim()
                let already_v1 = trimmed.StartsWith("{\"v\":1,")
                let line =
                    if already_v1 then trimmed
                    elif trimmed.StartsWith("{") && trimmed.EndsWith("}") then
                        let body = trimmed.Substring(1, trimmed.Length - 2)
                        let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                        let pid = string (System.Diagnostics.Process.GetCurrentProcess().Id)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        sprintf "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,%s}" ts pid tid (esc run_id) body
                    else
                        let ts = string (System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
                        let pid = string (System.Diagnostics.Process.GetCurrentProcess().Id)
                        let tid = string (System.Threading.Thread.CurrentThread.ManagedThreadId)
                        sprintf "{\"v\":1,\"ts_ms\":%s,\"pid\":%s,\"tid\":%s,\"run_id\":%s,\"kind\":\"diag\",\"msg\":%s}" ts pid tid (esc run_id) (esc trimmed)
                let line = compactJsonLineIfLarge line
                let line = enrichJsonLineWithProcessMemory line
                noteProgressSiteFromJsonLine line
                let emitCurrentLine = shouldEmitJsonLine line
                // True 1s ticks are emitted only by the dedicated metronome thread;
                // ordinary diagnostics must not consume or delay the heartbeat slot.
                if emitCurrentLine then
                    writeProgressHeartbeatLine false line
            with _ -> ()

        do
            ensureProgressPredictionHeartbeat()
            Progress88.set_prediction_tick_sink emit

        let retry (code: string) (gen_before: int) (gen_after: int) (attempt: int) (max_attempts: int) (file: string) (backend: string) (is_gen_wait: bool) (seq: bool) (dop_env: int) (dop_forced: int) =
            emit (sprintf "{\"kind\":\"retry\",\"code\":%s,\"gen_before\":%d,\"gen_after\":%d,\"attempt\":%d,\"max_attempts\":%d,\"file\":%s,\"backend\":%s,\"gen_wait\":%b,\"seq\":%b,\"dop_env\":%d,\"dop_forced\":%d}" (esc code) gen_before gen_after attempt max_attempts (esc file) (esc backend) is_gen_wait seq dop_env dop_forced)
        let retryStop (code: string) (reason: string) (attempt: int) (max_attempts: int) (file: string) (backend: string) (key: string) (site: string) (depth: int) (re: int) (max_re: int) =
            emit (sprintf "{\"kind\":\"retry_stop\",\"code\":%s,\"reason\":%s,\"attempt\":%d,\"max_attempts\":%d,\"file\":%s,\"backend\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d}" (esc code) (esc reason) attempt max_attempts (esc file) (esc backend) (esc key) (esc site) depth re max_re)
        let termCycle (key: string) (depth: int) (site: string) (gen: int) (re: int) (max_re: int) (big: bool) (hs: string) (ks: string) (count: int) (panic: bool) =
            // Defensive truncation: term-cycle payloads can become huge and contribute to stack/alloc pressure
            let hs =
                if System.Object.ReferenceEquals(hs,null) then ""
                elif hs.Length > 512 then hs.Substring(0,512) + "…"
                else hs
            let ks =
                if System.Object.ReferenceEquals(ks,null) then ""
                elif ks.Length > 2048 then ks.Substring(0,2048) + "…"
                else ks
            let compact = count > 1 || (panic && depth > 768)
            let hs_out = if compact then "" else hs
            let ks_out = if compact then "" else ks
            emit (sprintf "{\"kind\":\"term_cycle\",\"code\":%s,\"key\":%s,\"depth\":%d,\"site\":%s,\"gen\":%d,\"re\":%d,\"max_re\":%d,\"big\":%b,\"count\":%d,\"panic\":%b,\"compact\":%b,\"hs\":%s,\"ks\":%s}" (esc EJPCodes.EJP0011) (esc key) depth (esc site) gen re max_re big count panic compact (esc hs_out) (esc ks_out))


    module TermCycleWatchdog =
        open System.Collections.Generic
        let private lock_obj = obj()
        // key -> struct(lastGen,totalCount,genCount)
        let private seen = Dictionary<string, struct(int*int*int)>()
        /// Returns total count for this key across the whole compilation session.
        let note (key: string) (gen: int) =
            lock lock_obj (fun () ->
                match seen.TryGetValue key with
                | true, struct(g,tot,genC) ->
                    let tot' = tot + 1
                    let genC' = if g = gen then genC + 1 else 1
                    seen.[key] <- struct(gen, tot', genC')
                    tot'
                | _ ->
                    seen.[key] <- struct(gen,1,1)
                    1)


    /// Global one-way fuse for EJP0011 panic.
    ///
    /// Why alpha316 needs this: under parallel evaluation, one worker can detect a real
    /// re-entrant term/type cycle and raise EJP0011, while sibling workers keep descending
    /// through the same poisoned graph. That produced useful compact JSONL in alpha315, but
    /// still ended in a process-level StackOverflow. This fuse turns the first panic cycle
    /// into an immediate minimal abort for every later evaluator entry, avoiding diagnostic
    /// recursion and preventing sibling workers from amplifying the cycle.
    module TermCycleFuse =
        let private lock_obj = obj()
        let mutable private tripped = false
        let mutable private firstKey = ""
        let mutable private firstSite = ""
        let mutable private firstDepth = 0
        let mutable private firstGen = 0
        let mutable private firstRe = 0
        let mutable private firstMaxRe = 0
        let mutable private firstTrace = []

        let private esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        let private compactTrace tr =
            let maxFrontierTrace = 48
            match tr with
            | [] -> []
            | _ ->
                let head = tr |> List.truncate (maxFrontierTrace / 2)
                let tail =
                    tr
                    |> List.rev
                    |> List.truncate (maxFrontierTrace - head.Length)
                    |> List.rev
                // Preserve order while avoiding duplicate overlap when the trace is already short.
                if head.Length + tail.Length >= tr.Length then tr
                else head @ tail

        let tripWithTrace (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) trace : unit =
            let shouldEmit =
                lock lock_obj (fun () ->
                    if tripped then false
                    else
                        tripped <- true
                        firstKey <- if System.Object.ReferenceEquals(key,null) then "" else key
                        firstSite <- if System.Object.ReferenceEquals(site,null) then "" else site
                        firstDepth <- depth
                        firstGen <- gen
                        firstRe <- re
                        firstMaxRe <- maxRe
                        firstTrace <- compactTrace trace
                        true)
            if shouldEmit then
                try
                    let traceLen = lock lock_obj (fun () -> firstTrace.Length)
                    DiagJson.emit (sprintf "{\"kind\":\"term_reentry_fuse\",\"code\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"gen\":%d,\"re\":%d,\"max_re\":%d,\"trace_lines\":%d}" (esc EJPCodes.EJP0011) (esc key) (esc site) depth gen re maxRe traceLen)
                with _ -> ()

        let trip (key: string) (site: string) (depth: int) (gen: int) (re: int) (maxRe: int) : unit =
            tripWithTrace key site depth gen re maxRe []

        let isTripped () : bool = lock lock_obj (fun () -> tripped)

        let describe () : string * string * int * int * int * int =
            lock lock_obj (fun () -> firstKey, firstSite, firstDepth, firstGen, firstRe, firstMaxRe)

        let traceSnapshot () =
            lock lock_obj (fun () -> firstTrace)

        /// Clear the one-way fuse before a whole-build retry.
        ///
        /// The fuse stays one-way inside one parallel attempt, but alpha318 can use the
        /// tripped fuse as a signal to retry the whole build in sequential mode.
        let reset () : unit =
            lock lock_obj (fun () ->
                tripped <- false
                firstKey <- ""
                firstSite <- ""
                firstDepth <- 0
                firstGen <- 0
                firstRe <- 0
                firstMaxRe <- 0
                firstTrace <- [])


    /// Centralized evaluator fallback budgets.
    ///
    /// Hardcoded only. Keep the parallel attempt strict, but give forced
    /// sequential mode a single legacy-style budget so future changes are policy edits,
    /// not scattered magic numbers. This module intentionally does not reference
    /// BigStack because it is declared later in the compiler file.
    module EvalFallbackPolicy =
        let depthBase : int = 2048
        let parallelBigDepth : int = 4096
        let sequentialBigDepth : int = 32768
        let sequentialReentryMax : int = 4096
        let sequentialJpWaitStallMs : int64 = 1000L
        let sequentialJpWaitHelpWindowMs : int64 = 0L
        let sequentialJpWaitSlowJobs : int = 4
        let sequentialDeepCycleDepth : int = 4096
        let sequentialDeepCycleReentryMax : int = 1024

        let maxDepthBig (seqNow: bool) : int =
            if seqNow then sequentialBigDepth else parallelBigDepth

        let maxReentry (seqNow: bool) (invNow: int64) (depth: int) : int =
            if seqNow && depth >= sequentialDeepCycleDepth then sequentialDeepCycleReentryMax
            elif seqNow then sequentialReentryMax
            elif depth > 512 then 64
            elif invNow > 0L then 128
            else 256

        let warnReentry (maxReentryBase: int) : int = max 32 (maxReentryBase / 4)

        let retryStopReasonForCycle (_key: string) (_site: string) (depth: int) (re: int) (maxRe: int) =
            if depth >= sequentialDeepCycleDepth && maxRe > 0 && re > maxRe then
                "deep_reentry_saturation_after_sequential_retry"
            elif depth >= sequentialBigDepth / 2 then
                "deep_reentrant_cycle_after_sequential_retry"
            elif maxRe > 0 && re > maxRe then
                "reentry_budget_exhausted_after_sequential_retry"
            else
                "semantic_cycle_after_sequential_retry"

        let describe (seqNow: bool) (invNow: int64) (depth: int) =
            sprintf "seq=%b inv=%d depth=%d max_re=%d max_depth_big=%d seq_wait_stall_ms=%d seq_wait_help_window_ms=%d deep_cycle_depth=%d deep_cycle_max_re=%d stall_clock=%s policy_next=explicit_eval_worklist" seqNow invNow depth (maxReentry seqNow invNow depth) (maxDepthBig seqNow) sequentialJpWaitStallMs sequentialJpWaitHelpWindowMs sequentialDeepCycleDepth sequentialDeepCycleReentryMax (if seqNow then "elapsed" else "idle")


    /// Generic boundary marker for the next stack-safe evaluator step.
    ///
    /// This deliberately does not know about source files such as listm/core/runtime.
    /// This deliberately stays source-path agnostic.
    /// It only records evaluator shape: sequential fallback, depth, re-entry, and fuse state.
    module EvalWorklistFrontier =
        let private esc (s: string) =
            if System.Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        let isDeepSequentialCycle (depth: int) (re: int) (maxRe: int) =
            depth >= EvalFallbackPolicy.sequentialDeepCycleDepth
            && maxRe > 0
            && re > maxRe

        let emit (code: string) (reason: string) (key: string) (site: string) (depth: int) (re: int) (maxRe: int) =
            DiagJson.emit (
                sprintf "{\"kind\":\"eval_frontier\",\"code\":%s,\"reason\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"policy\":\"stack_safe_worklist_required\",\"policy_next\":\"explicit_eval_worklist\"}"
                    (esc code) (esc reason) (esc key) (esc site) depth re maxRe)

        let reasonForCycle (fallbackReason: string) (depth: int) (re: int) (maxRe: int) =
            if isDeepSequentialCycle depth re maxRe then "explicit_worklist_required_after_sequential_cycle"
            else fallbackReason


    module Utils =
        open System
        open System.Collections.Generic
        open System.Collections.Concurrent
        open System.Runtime.CompilerServices
    

        /// ### list_try_zip
        let list_try_zip a b =
            try Some (List.zip a b) with _ -> None
    

        /// ### get_default
        let inline get_default (memo_dict: ^D) (k: ^K) (def: unit -> ^V) : ^V =
            let mutable v = Unchecked.defaultof<^V>
            if (^D : (member TryGetValue : ^K * byref<^V> -> bool) (memo_dict, k, &v)) then v
            else def()
    

        /// ### memoize'
        let inline memoize' (memo_dict: ConditionalWeakTable<_,_>) f k =
            match memo_dict.TryGetValue k with
            | true, v -> v
            | false, _ ->
                let v = f k
                memo_dict.Add(k,v)
                v
    

        /// ### memoize
        let inline memoize (memo_dict: ConcurrentDictionary<_,_>) f k =
            match memo_dict.TryGetValue k with
            | true, v -> v
            | false, _ ->
                let v = f k
                if memo_dict.TryAdd(k,v) then v
                else memo_dict.[k]
    

        /// ### file_uri
        let file_uri (x : string) =
            let result = x |> SpiralFileSystem.standardize_path |> SpiralFileSystem.new_file_uri
            trace Verbose (fun () -> $"Utils.file_uri / x: {x} / result: {result}") _locals
            result
    

    /// ## ParserCombinators
    

    /// ### index
    let inline index d = (^a : (member Index: ^b) d)
    

    /// ### index_set
    let inline index_set i d = (^a : (member set_Index: ^b -> unit) (d,i))
    

    /// ### (.>>.)
    let inline (.>>.) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok (a,b)
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### tuple3
    let inline tuple3 a b c d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c -> Ok (a, b, c)
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### tuple4
    let inline tuple4 a b c d' d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' -> Ok (a, b, c, d')
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### tuple5
    let inline tuple5 a b c d' e d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e -> Ok (a, b, c, d', e)
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### tuple6
    let inline tuple6 a b c d' e f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e ->
                            match f d with
                            | Ok f -> Ok (a, b, c, d', e, f)
                            | Error x -> Error x
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### tuple7
    let inline tuple7 a b c d' e f g d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e ->
                            match f d with
                            | Ok f ->
                                match g d with
                                | Ok g -> Ok (a, b, c, d', e, f, g)
                                | Error x -> Error x
                            | Error x -> Error x
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### pipe2
    let inline pipe2 a b f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok (f a b)
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### pipe3
    let inline pipe3 a b c f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c -> Ok (f a b c)
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### pipe4
    let inline pipe4 a b c d' f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' -> Ok (f a b c d')
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### pipe5
    let inline pipe5 a b c d' e f d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b ->
                match c d with
                | Ok c ->
                    match d' d with
                    | Ok d' ->
                        match e d with
                        | Ok e -> Ok (f a b c d' e)
                        | Error x -> Error x
                    | Error x -> Error x
                | Error x -> Error x
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### (.>>)
    let inline (.>>) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok a
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### (>>.)
    let inline (>>.) a b d =
        match a d with
        | Ok a ->
            match b d with
            | Ok b -> Ok b
            | Error x -> Error x
        | Error x -> Error x
    

    /// ### opt
    let inline opt a d =
        let s = index d
        match a d with
        | Ok a -> Ok(Some a)
        | Error x ->
            if s = index d then Ok(None)
            else Error x
    

    /// ### optional
    let inline optional a d =
        let s = index d
        match a d with
        | Ok a -> Ok()
        | Error x ->
            if s = index d then Ok()
            else Error x
    

    /// ### (|>>)
    let inline (|>>) a b d =
        match a d with
        | Ok a -> Ok(b a)
        | Error x -> Error x
    

    /// ### (>>%)
    let inline (>>%) a b d =
        match a d with
        | Ok a -> Ok(b)
        | Error x -> Error x
    

    /// ### (>>=)
    let inline (>>=) a b d =
        match a d with
        | Ok a -> b a d
        | Error x -> Error x
    

    /// ### (>>=?)
    let inline (>>=?) a b d =
        let i = index d
        match a d with
        | Ok a ->
            let i' = index d
            match b a d with
            | Ok _ as x -> x
            | Error _ as x -> (if i' = index d then index_set i d); x // Backtracks to the beginning if the parser state has not changed.
        | Error x -> Error x
    

    /// ### many_iter
    let inline many_iter f a d =
        let rec loop () =
            let s = index d
            match a d with
            | Ok _ when s = index d -> failwith "The parser succeeded without changing the parser index in `many`. Had an exception not been raised the parser would have diverged."
            | Ok x -> f x; loop()
            | Error er -> if s = index d then Ok() else Error er
        loop ()
    

    /// ### many_resize_array
    let inline many_resize_array a d =
        let ar = ResizeArray()
        match many_iter ar.Add a d with
        | Ok() -> Ok(ar)
        | Error er -> Error er
    

    /// ### many_array
    let inline many_array a d = many_resize_array a d |> Result.map (fun x -> x.ToArray())
    

    /// ### many
    let inline many a d = many_resize_array a d |> Result.map Seq.toList
    

    /// ### sepBy
    let inline sepBy a b d =
        let s = index d
        match a d with
        | Ok a' -> (many (b >>. a) |>> fun b -> a' :: b) d
        | Error x -> if s = index d then Ok [] else Error x
    

    /// ### sepBy1
    let inline sepBy1 a b d =
        match a d with
        | Ok a' -> (many (b >>. a) |>> fun b -> a' :: b) d
        | Error x -> Error x
    

    /// ### many1
    let inline many1 a d =
        match a d with
        | Ok a' -> (many a |>> fun b -> a' :: b) d
        | Error x -> Error x
    

    /// ### attempt
    let inline attempt a d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error a as a' -> index_set s d; a'
    

    /// ### restore
    /// Restores the index on an error if at least i tokens have been consumed.
    let inline restore i a d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error _ as er -> (if index d <= s + i then index_set s d); er
    

    /// ### alt
    let inline alt s a b d =
        match a d with
        | Ok x -> Ok x
        | Error a as a' ->
            if s = index d then
                match b d with
                | Ok x -> Ok x
                | Error b -> if s = index d then Error(List.append a b) else Error b
            else
                a'
    

    /// ### (<|>)
    let inline (<|>) a b d = let s = index d in alt s a b d
    

    /// ### (<|>%)
    let inline (<|>%) a b d =
        let s = index d
        match a d with
        | Ok x -> Ok x
        | Error _ as a' -> if s = index d then Ok b else a'
    

    /// ### choice
    let inline choice ar d =
        let s = index d
        let rec loop i =
            if i < Array.length ar then
                match ar.[i] d with
                | Ok x -> Ok x
                | Error a as a' ->
                    if s = index d then
                        match loop (i+1) with
                        | Ok x -> Ok x
                        | Error b -> Error(List.append a b)
                    else
                        a'
            else
                Error []
        loop 0
    

    /// ### between
    let inline between a b c = a >>. c .>> b
    

    /// ## LineParsers
    // open System
    open System.Text
    

    open Microsoft.FSharp.Core
    

    /// ### TokenizerRange
    type TokenizerRange = {from : int; nearTo : int}
    

    /// ### TokenizerError
    type TokenizerError = string
    

    /// ### Tokenizer
    type Tokenizer = {
        text : string // A single line.
        mutable from : int
        } with
    

        member t.Index with get() = t.from and set i = t.from <- i
    

    /// ### range_char
    let range_char i = {from=i; nearTo=i+1}
    

    /// ### error_char
    let error_char i er = Error [range_char i, er]
    

    /// ### inc'
    let inc' i (s : Tokenizer) = s.from <- s.from+i
    

    /// ### inc
    let inc (s : Tokenizer) = inc' 1 s
    

    /// ### lineParsersEol
    /// End Of Line character
    let lineParsersEol = Char.MaxValue
    

    /// ### peek'
    let peek' (s : Tokenizer) i =
        let i = s.from + i
        if 0 <= i && i < s.text.Length then s.text.[i]
        else lineParsersEol
    

    /// ### peek
    let peek (s : Tokenizer) = peek' s 0
    

    /// ### many1Satisfy2L
    let inline many1Satisfy2L init body label (s : Tokenizer) =
        let x = peek s
        if init x && x <> lineParsersEol then
            inc s
            let rec loop (b : StringBuilder) =
                let x = peek s
                if body x && x <> lineParsersEol then inc s; b.Append(x) |> loop
                else b.ToString()
            Ok(loop (StringBuilder().Append(x)))
        else
            let i = s.from
            error_char i label
    

    /// ### many1SatisfyL
    let inline many1SatisfyL body label (s : Tokenizer) = many1Satisfy2L body body label s
    

    /// ### skip
    let inline skip c (s : Tokenizer) = let b = peek s = c in (if b then inc s); b
    

    /// ### spaces'
    let rec spaces' (s : Tokenizer) = if peek s = ' ' then inc s; spaces' s
    

    /// ### spaces
    let spaces s = spaces' s |> Ok
    

    /// ### spaces1
    let spaces1 (s : Tokenizer) =
        if peek s = ' ' then inc s; spaces s else error_char s.from "space"
    

    /// ### skip_char
    let skip_char c (s : Tokenizer) =
        let from = s.from
        if skip c s then Ok() else error_char from (sprintf "'%c'" c)
    

    /// ### skip_string
    let skip_string x (s : Tokenizer) =
        if String.Compare(s.text,s.from,x,0,x.Length) = 0 then inc' x.Length s; Ok()
        else error_char s.from x
    

    /// ### anyOf
    let anyOf (l : char list) (s : Tokenizer) =
        let c = peek s
        if Seq.contains c l then
            inc s; Ok(c)
        else
            let i = s.from
            Error (List.map (fun c -> range_char i, string c) l)
    

    /// ### chars_till_string
    let chars_till_string close (s : Tokenizer) =
        assert (close <> "")
        let rec loop (b : StringBuilder) =
            let x = peek s
            if x = close.[0] && String.Compare(s.text,s.from,close,1,close.Length-1) = 0 then inc' close.Length s; Ok(b.ToString())
            else
                if x <> lineParsersEol then inc s; b.Append(x) |> loop
                else error_char s.from close
        loop(StringBuilder())
    

    /// ### lineParsersNumber
    /// Parses a number as a sequence of digits and optionally underscores. Filters out the underscores from the result.
    let lineParsersNumber (s : Tokenizer) =
        let x = peek s
        if Char.IsDigit x then
            inc s
            let rec loop (b : StringBuilder) =
                let x = peek s
                if x = '_' then inc s; loop b
                elif Char.IsDigit x then inc s; loop(b.Append(x))
                else Ok(b.ToString())
            loop (StringBuilder().Append(x))
        else
            let i = s.from
            error_char i "number"
    

    /// ### number_fractional
    let number_fractional s = (lineParsersNumber .>>. (opt (skip_char '.' >>. lineParsersNumber))) s
    

    /// ## VSCTypes
    

    /// ### VSCPos
    type VSCPos = {|line : int; character : int|}
    

    /// ### VSCRange
    type VSCRange = VSCPos * VSCPos
    

    /// ### RString
    type RString = VSCRange * string
    

    /// ### PackageId
    type PackageId = int
    

    /// ### ModuleId
    type ModuleId = int
    

    /// ### DirId
    type DirId = int
    

    /// ### GlobalId
    type GlobalId = { package_id : PackageId; module_id : ModuleId; tag : int }
    

    /// ### RGlobalId
    type RGlobalId = VSCRange * GlobalId
    

    /// ### SpiEdit
    type SpiEdit = {|from: int; nearTo: int; lines: string []|}
    

    /// ## Tokenize
    // open System
    // open System.Text
    // open FSharpx.Collections
    

    /// ### TokenKeyword
    type TokenKeyword =
        | SpecIn
        | SpecAnd
        | SpecFun
        | SpecMatch
        | SpecTypecase
        | SpecFunction
        | SpecWith
        | SpecWithout
        | SpecAs
        | SpecWhen
        | SpecInl
        | SpecForall
        | SpecExists
        | SpecLet
        | SpecInm
        | SpecInb
        | SpecRec
        | SpecIf
        | SpecThen
        | SpecElif
        | SpecElse
        | SpecJoin
        | SpecJoinBackend
        | SpecType
        | SpecNominal
        | SpecReal
        | SpecUnion
        | SpecOpen
        | SpecWildcard
        | SpecPrototype
        | SpecInstance
    

    /// ### ParenthesisState
    type ParenthesisState = Open | Close
    

    /// ### Parenthesis
    type Parenthesis = Round | Square | Curly
    

    /// ### MacroEnum
    type MacroEnum = MTerm | MType | MTypeLit | MTermInline
    

    /// ### Literal
    type Literal =
        | LitUInt8 of uint8
        | LitUInt16 of uint16
        | LitUInt32 of uint32
        | LitUInt64 of uint64
        | LitInt8 of int8
        | LitInt16 of int16
        | LitInt32 of int32
        | LitInt64 of int64
        | LitFloat32 of float32
        | LitFloat64 of float
        | LitBool of bool
        | LitString of string
        | LitChar of char
    

        // Converts the literal back to their string representation. Doesn't override the default printer.
        member l.LitToString() =
            match l with
            | LitUInt8 x -> x.ToString("R")
            | LitUInt16 x -> x.ToString("R")
            | LitUInt32 x -> x.ToString("R")
            | LitUInt64 x -> x.ToString("R")
            | LitInt8 x -> x.ToString("R")
            | LitInt16 x -> x.ToString("R")
            | LitInt32 x -> x.ToString("R")
            | LitInt64 x -> x.ToString("R")
            | LitFloat32 x -> x.ToString("R")
            | LitFloat64 x -> x.ToString("R")
            | LitBool x -> x.ToString()
            | LitString x -> x
            | LitChar x -> x.ToString()
    

    /// ### SemanticTokenLegend
    type SemanticTokenLegend =
        | variable = 0
        | symbol = 1
        | string = 2
        | number = 3
        | operator = 4
        | unary_operator = 5
        | comment = 6
        | keyword = 7
        | parenthesis = 8
        | type_variable = 9
        | escaped_char = 10
        | unescaped_char = 11
        | number_suffix = 12
        | escaped_var = 13
    

    /// ### SpiralToken
    type SpiralToken =
        | TokVar of string * SemanticTokenLegend
        | TokSymbol of string * SemanticTokenLegend
        | TokOperator of string * SemanticTokenLegend
        | TokUnaryOperator of string * SemanticTokenLegend
        | TokValue of Literal
        | TokValueSuffix
        | TokDefaultValue of string
        | TokComment of string
        | TokKeyword of TokenKeyword
        | TokParenthesis of Parenthesis * ParenthesisState
        | TokStringOpen | TokStringClose
        | TokText of string
        | TokEscapedChar of char
        | TokEscapedVar
        | TokUnescapedChar of char
        | TokMacroOpen | TokMacroClose
        | TokMacroTermVar of string * is_inline : bool
        | TokMacroTypeVar of string
        | TokMacroTypeLitVar of string
        | TokMacroExpression of MacroEnum * ParenthesisState
    

    /// ### token_groups
    let token_groups = function
        | TokUnaryOperator(_,r) | TokOperator(_,r) | TokVar(_,r) | TokSymbol(_,r) -> r
        | TokValue (LitChar _) | TokStringOpen | TokStringClose | TokText _ | TokMacroOpen | TokMacroClose | TokValue(LitString _) -> SemanticTokenLegend.string
        | TokComment _ -> SemanticTokenLegend.comment
        | TokKeyword _ -> SemanticTokenLegend.keyword
        | TokParenthesis _ -> SemanticTokenLegend.parenthesis
        | TokMacroTypeVar _ -> SemanticTokenLegend.type_variable
        | TokMacroTypeLitVar _ -> SemanticTokenLegend.type_variable
        | TokMacroTermVar _ -> SemanticTokenLegend.variable
        | TokMacroExpression _ -> SemanticTokenLegend.parenthesis
        | TokEscapedChar _ -> SemanticTokenLegend.escaped_char
        | TokEscapedVar -> SemanticTokenLegend.escaped_var
        | TokUnescapedChar _ -> SemanticTokenLegend.unescaped_char
        | TokValue _ | TokDefaultValue _ -> SemanticTokenLegend.number
        | TokValueSuffix -> SemanticTokenLegend.number_suffix
    

    /// ### show_lit
    let show_lit = function
        | LitUInt8 x -> sprintf "%iu8" x
        | LitUInt16 x -> sprintf "%iu16" x
        | LitUInt32 x -> sprintf "%iu32" x
        | LitUInt64 x -> sprintf "%iu64" x
        | LitInt8 x -> sprintf "%ii8" x
        | LitInt16 x -> sprintf "%ii16" x
        | LitInt32 x -> sprintf "%ii32" x
        | LitInt64 x -> sprintf "%ii64" x
        | LitFloat32 x -> sprintf "%ff32" x
        | LitFloat64 x -> sprintf "%ff64" x
        | LitBool x -> sprintf "%b" x
        | LitString x -> sprintf "%s" x
        | LitChar x -> sprintf "%c" x
    

    /// ### is_small_var_char_starting
    let is_small_var_char_starting c = Char.IsLower c || c = '_'
    

    /// ### is_var_char
    let is_var_char c = Char.IsLetterOrDigit c || c = '_' || c = char 39
    

    /// ### is_big_var_char_starting
    let is_big_var_char_starting c = Char.IsUpper c
    

    /// ### is_parenth_open
    let is_var_char_starting c = Char.IsLetter c || c = '_'
    

    /// ### is_parenth_open
    let is_parenth_open c =
        let f x = c = x
        f '(' || f '[' || f '{'
    

    /// ### is_parenth_close
    let is_parenth_close c =
        let f x = c = x
        f ')' || f ']' || f '}'
    

    /// ### is_operator_char
    // http://www.asciitable.com/
    let is_operator_char c =
        let f x = c = x
        '!' <= c && c <= '~' && (is_var_char c || f '"' || is_parenth_open c || is_parenth_close c) = false
    

    /// ### is_prefix_separator_char
    let is_prefix_separator_char c =
        let f x = c = x
        f ' ' || f lineParsersEol || is_parenth_open c
    

    /// ### is_postfix_separator_char
    let is_postfix_separator_char c =
        let f x = c = x
        f ' ' || f lineParsersEol || is_parenth_close c
    

    /// ### is_separator_char
    let is_separator_char c = is_prefix_separator_char c || is_parenth_close c
    

    /// ### var
    let var (s: Tokenizer) =
        let from = s.from
        let ok x = Ok ({from=from; nearTo=s.from}, x)
        let body x _ =
            if skip ':' s then error_char from ": is not allowed directly after a var."
            else
                let f x = TokKeyword(x)
                match x with
                | "in" -> f SpecIn
                | "and" -> f SpecAnd | "fun" -> f SpecFun
                | "match" -> f SpecMatch | "typecase" -> f SpecTypecase
                | "function" -> f SpecFunction
                | "with" -> f SpecWith | "without" -> f SpecWithout
                | "as" -> f SpecAs | "when" -> f SpecWhen
                | "inl" -> f SpecInl | "forall" -> f SpecForall
                | "let" -> f SpecLet | "inm" -> f SpecInm
                | "inb" -> f SpecInb | "rec" -> f SpecRec
                | "if" -> f SpecIf | "then" -> f SpecThen
                | "elif" -> f SpecElif | "else" -> f SpecElse
                | "join" -> f SpecJoin | "join_backend" -> f SpecJoinBackend
                | "type" -> f SpecType | "nominal" -> f SpecNominal
                | "real" -> f SpecReal | "union" -> f SpecUnion
                | "open" -> f SpecOpen | "_" -> f SpecWildcard
                | "prototype" -> f SpecPrototype | "instance" -> f SpecInstance
                | "true" -> TokValue(LitBool true) | "false" -> TokValue(LitBool false)
                | "exists" -> f SpecExists
                | x -> TokVar(x,SemanticTokenLegend.variable)
                |> ok
    

        (many1Satisfy2L is_var_char_starting is_var_char "variable" >>= body .>> spaces) s
    

    /// ### isHexDigit
    let isHexDigit c =
        ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
    

    /// ### hexNumberLineParser
    let hexNumberLineParser (s : Tokenizer) =
        let from = s.from
        if peek s = '0' && (let x = peek' s 1 in x = 'x' || x = 'X') then
            inc' 2 s
            let res = many1SatisfyL isHexDigit "hexadecimal digit" s
            if Result.isError res then error_char from "hexadecimal digit"
            else res
        else
            let i = s.from
            error_char i "0x prefix"
    

    /// ### hexNumber
    let hexNumber (s: Tokenizer) : Result<_,_> =
        let from = s.from
        let p s =
            match hexNumberLineParser s with
            | Ok hexStr ->
                let value = System.Convert.ToInt32(hexStr, 16)
                Ok ([{from=from; nearTo=s.from}, TokValue(LitInt32 value)])
            | Error e -> Error e
    

        (p .>> spaces) s
    

    /// ### tokenizeNumber
    let tokenizeNumber (s: Tokenizer) =
        let from = s.from
    

        let parser (s: Tokenizer) =
            if peek s = '-' && Char.IsDigit (peek' s 1) && is_prefix_separator_char (peek' s -1) then
                inc s
                number_fractional s |> Result.map (function
                    | (a,Some b) -> sprintf "-%s.%s" a b
                    | (a,None) -> "-"+a)
            else number_fractional s |> Result.map (function
                    | (a,Some b) -> sprintf "%s.%s" a b
                    | (a,None) -> a)
    

        let followedBySuffix x (s: Tokenizer) =
            let from' = s.from
            let inline safe_parse string_to_val val_to_lit val_dsc =
                if (let x = peek s in is_separator_char x || is_operator_char x) then
                    match string_to_val x with
                    | true, x -> Ok [{from=from; nearTo=from'}, TokValue(val_to_lit x); {from=from'; nearTo=s.from}, TokValueSuffix]
                    | false, _ -> Error [{from=from; nearTo=s.from}, (sprintf "The string %s cannot be safely parsed as %s." x val_dsc)]
                else error_char s.from "separator"
            let skip c = skip c s
            if skip 'i' then
                if skip '8' then safe_parse SByte.TryParse LitInt8 "i8"
                elif skip '1' && skip '6' then safe_parse Int16.TryParse LitInt16 "i16"
                elif skip '3' && skip '2' then safe_parse Int32.TryParse LitInt32 "i32"
                elif skip '6' && skip '4' then safe_parse Int64.TryParse LitInt64 "i64"
                else error_char s.from "8,16,32 or 64"
            elif skip 'u' then
                if skip '8' then safe_parse Byte.TryParse LitUInt8 "uint8"
                elif skip '1' && skip '6' then safe_parse UInt16.TryParse LitUInt16 "u16"
                elif skip '3' && skip '2' then safe_parse UInt32.TryParse LitUInt32 "u32"
                elif skip '6' && skip '4' then safe_parse UInt64.TryParse LitUInt64 "u64"
                else error_char s.from "8,16,32 or 64"
            elif skip 'f' then
                if skip '3' && skip '2' then safe_parse Single.TryParse LitFloat32 "f32"
                elif skip '6' && skip '4' then safe_parse Double.TryParse LitFloat64 "f64"
                else error_char s.from "32 or 64"
            else Ok [{from=from; nearTo=s.from}, TokDefaultValue x]
    

        (parser >>= followedBySuffix .>> spaces) s
    

    /// ### symbol
    let symbol s =
        let from = s.from
        let f x = ({from=from; nearTo=s.from}, x)
    

        let symbol x = TokSymbol(x,SemanticTokenLegend.symbol)
        let x = peek s
        let x' = peek' s 1
        if x = '.' && x' = '(' then inc' 2 s; ((many1SatisfyL is_operator_char "operator") .>> skip_char ')' |>> (symbol >> f) .>> spaces) s
        elif x = '.' && is_var_char_starting x' then inc s; ((many1SatisfyL is_var_char "variable") |>> (symbol >> f) .>> spaces) s
        else error_char from "symbol"
    

    /// ### TripleString
    module TripleString =
        let mutable in_triple = false
        let inline is_open () = in_triple
        let inline open' () = in_triple <- true
        let inline close () = in_triple <- false
    

    /// ### MultiComment
    module MultiComment =
        let mutable depth = 0
        let inline in_comment () = depth > 0
        let inline open' () = depth <- depth + 1
        let inline close () = if depth > 0 then depth <- depth - 1
        let inline reset () = depth <- 0
    

    /// ### reset_lexical_state
    let reset_lexical_state () =
        MultiComment.reset ()
        TripleString.close ()
    

    /// ### multi_comment_marker
    let multi_comment_marker = '\u0001'
    

    /// ### multiline_comment
    let multiline_comment (s : Tokenizer) =
        let from = s.from
        let len = s.text.Length
        let body_from = s.from
        if body_from >= len then
            Error []
        else
            let mutable i = s.from
            while i + 1 < len && MultiComment.in_comment() do
                if s.text.[i] = '(' && s.text.[i+1] = '*' then
                    MultiComment.open'()
                    i <- i + 2
                elif s.text.[i] = '*' && s.text.[i+1] = ')' then
                    MultiComment.close()
                    i <- i + 2
                else
                    i <- i + 1
            let i_end = if MultiComment.in_comment() then len else i
            let text =
                if body_from < i_end then s.text.Substring(body_from, i_end - body_from)
                else ""
            s.from <- i_end
            Ok ({from=from; nearTo=s.from},
                TokComment (string multi_comment_marker + text))
    

    /// ### comment
    let comment (s : Tokenizer) =
        if TripleString.is_open() then
            let from = s.from
            let content = s.text.Substring(from)
            s.from <- s.text.Length
            Ok ({from=from; nearTo=s.from}, TokText content)
        elif peek s = '/' && peek' s 1 = '/' then
            let from = s.from
            inc' 2 s
            while peek s = '/' || ((peek s = '!' || peek s = '-' || peek s = '>') && peek' s 1 = ' ') do
                inc s
            if skip ' ' s then
                let com = s.text.[s.from..]
                s.from <- s.text.Length
                Ok ({from=from; nearTo=s.from}, TokComment com)
            else error_char s.from "whitespace"
        elif peek s = '(' && peek' s 1 = '*' && peek' s 2 = ' ' then
            let from = s.from
            inc' 2 s
            let body_from = s.from
            let len = s.text.Length
            let mutable depth = 1
            let mutable i = s.from
            let inline at j c = j < len && s.text.[j] = c
            while i < len && depth > 0 do
                if at i '(' && at (i+1) '*' then
                    depth <- depth + 1
                    i <- i + 2
                elif at i '*' && at (i+1) ')' then
                    depth <- depth - 1
                    i <- i + 2
                else
                    i <- i + 1
            if depth <> 0 then
                Error [{from=from; nearTo=i}, "Unterminated multiline comment. Expected '*)'."]
            else
                let content = s.text.Substring(body_from, i - 2 - body_from)
                s.from <- i
                Ok ({from=from; nearTo=s.from}, TokComment content)
        else
            error_char s.from "comment"
    

    /// ### operator
    let operator (s : Tokenizer) =
        let from = s.from
        let ok x = ({from=from; nearTo=s.from}, x) |> Ok
        let is_separator_prev = is_prefix_separator_char (peek' s -1)
        let f name (s: Tokenizer) =
            if is_separator_prev && (is_postfix_separator_char (peek s) = false) then TokUnaryOperator(name,SemanticTokenLegend.unary_operator) |> ok
            else TokOperator(name,SemanticTokenLegend.operator) |> ok
        (many1SatisfyL is_operator_char "operator"  >>= f .>> spaces) s
    

    /// ### string_raw
    let string_raw s =
        let from = s.from
        let f x = {from=from; nearTo=s.from}, TokValue(LitString x)
        (skip_string "@\"" >>. chars_till_string "\"" |>> f .>> spaces) s
    

    /// ### char_quoted
    let char_quoted s =
        let char_quoted_body (s: Tokenizer) =
            let inline read on_succ =
                let x = peek s
                if x <> lineParsersEol then inc s; on_succ x
                else error_char s.from "character or '"
            read (function
                | '\\' ->
                    read (Ok << function
                        | 'n' -> '\n' | 'r' -> '\r' | 't' -> '\t' | 'b' -> '\b'
                        | x -> x
                        )
                | x -> Ok x
                )
        let from = s.from
        let f _ x _ = {from=from; nearTo=s.from}, TokValue(LitChar x)
        (pipe3 (skip_char '\'') char_quoted_body (skip_char '\'') f .>> spaces) s
    

    /// ### special_char
    let inline special_char l text s =
        let inline f from x = {from=from; nearTo=s.from}, x
        let f = f s.from
        inc s
        let esc x = inc s; text (f (TokEscapedChar x) :: l)
        let unesc x = inc s; text (f (TokUnescapedChar x) :: l)
        match peek s with
        | x when x = lineParsersEol -> error_char s.from "character"
        | 'n' -> esc '\n' | 'r' -> esc '\r'  | 't' -> esc '\t'  | 'b' -> esc '\b'
        | x -> unesc x
    

    /// ### string_triple_line
    let string_triple_line (s : Tokenizer) =
        let text = s.text
        let len = text.Length
        if TripleString.is_open() then
            if len = 0 then
                let t = ({from=0; nearTo=0}, TokText "\n")
                Ok [t]
            else
                let body_from = s.from
                let idx = text.IndexOf("\"\"\"", body_from)
                if idx >= 0 then
                    let body =
                        if body_from < idx then
                            [ ({from=body_from; nearTo=idx},
                                TokText (text.Substring(body_from, idx - body_from))) ]
                        else []
                    s.from <- idx + 3
                    TripleString.close()
                    Ok (body @ [ ({from=idx; nearTo=s.from}, TokStringClose) ])
                else
                    let content =
                        if body_from < len then
                            "\n" + text.Substring(body_from, len - body_from)
                        else
                            "\n"
                    let t = ({from=body_from; nearTo=len}, TokText content)
                    s.from <- len
                    Ok [t]
        elif peek s = '"' && peek' s 1 = '"' && peek' s 2 = '"' then
            let from_open = s.from
            inc' 3 s
            let body_from = s.from
            let text = s.text
            let len = text.Length
            let idx = text.IndexOf("\"\"\"", body_from)
            if idx >= 0 then
                let open_tok  = ({from=from_open; nearTo=from_open+3}, TokStringOpen)
                let body =
                    if body_from < idx then
                        [ ({from=body_from; nearTo=idx},
                            TokText (text.Substring(body_from, idx - body_from))) ]
                    else []
                s.from <- idx + 3
                let close_tok = ({from=idx; nearTo=s.from}, TokStringClose)
                Ok (open_tok :: body @ [close_tok])
            else
                let open_tok  = ({from=from_open; nearTo=from_open+3}, TokStringOpen)
                let content =
                    if body_from < len then
                        text.Substring(body_from, len - body_from)
                    else
                        ""
                let body =
                    [ ({from=body_from; nearTo=len}, TokText content) ]
                s.from <- len
                TripleString.open' ()
                Ok (open_tok :: body)
        else
            Error [{from=s.from; nearTo=s.from}, "triple-string: not a triple opener nor continuation"]
    

    /// ### string_quoted'
    let string_quoted' s =
        let inline f from x = {from=from; nearTo=s.from}, x
        let close l = let f = f s.from in inc s; List.rev (f TokStringClose :: l) |> Ok
        let rec text l =
            let f = f s.from
            let rec loop (str : StringBuilder) =
                let l () = if 0 < str.Length then f (TokText(str.ToString())) :: l else l
                match peek s with
                | x when x = lineParsersEol -> error_char s.from "character or \""
                | '\\' -> special_char (l ()) text s
                | '"' -> close (l ())
                | x -> inc s; loop (str.Append(x))
            loop (StringBuilder())
    

        match peek s with
        | '"' -> let f = f s.from in inc s; text [f TokStringOpen]
        | _ -> error_char s.from "\""
    

    /// ### string_quoted
    let string_quoted s = (string_quoted' .>> spaces) s
    

    /// ### TokenizerMacro
    type TokenizerMacro =
        | TokenizerText of TokenizerRange * string
        | EscapedChar of TokenizerRange * char
        | EscapedVar of TokenizerRange
        | UnescapedChar of TokenizerRange * char
        | Expression of TokenizerRange * string * MacroEnum
        | Var of TokenizerRange * string * MacroEnum
    

    /// ### range
    let inline range p s =
        let from = s.from
        match p s with
        | Ok x -> Ok({from=from; nearTo=s.from}, x)
        | Error l -> Error l
    

    /// ### brackets
    let brackets s =
        let from = s.from
        let f spec = inc s; (spaces >>% ({from=from; nearTo=s.from}, TokParenthesis(spec))) s
        match peek s with
        | '(' -> f (Round,Open) | '[' -> f (Square,Open) | '{' -> f (Curly,Open)
        | ')' -> f (Round,Close) | ']' -> f (Square,Close) | '}' -> f (Curly,Close)
        | _ -> error_char s.from "`(`,`[`,`{`,`}`,`]` or `)`"
    

    /// ### tab
    let tab s = if peek s = '\t' then Error [range_char (index s), "Tabs are not allowed."] else Error []
    

    /// ### tokenizeEol
    let tokenizeEol s = if peek s = lineParsersEol then Ok [] else Error [range_char (index s), "end of line"]
    

    let inline with_advance (p: Tokenizer -> Result<'a,(TokenizerRange * string) list>) : Tokenizer -> Result<'a,(TokenizerRange * string) list> =
        fun s ->
            let i0 = s.from
            match p s with
            | Ok x when s.from > i0 -> Ok x
            | Ok _ ->
                Error [{from=i0; nearTo=i0}, "tokenizer: zero-length token"]
            | Error e -> Error e
    

    /// ### token
    let rec token s =
        let i = s.from
        let inline (+) a b = alt i a b
        let individual_tokens =
            (string_triple_line .>> spaces)
            + string_quoted
            + hexNumber + tokenizeNumber
            + ((var + symbol + string_raw + char_quoted + (comment .>> spaces) + brackets + operator)
                |>> function
                    | (_, TokComment _) -> []
                    | t -> [t])
            |>> fun x -> x, []
        ((macro + individual_tokens) |> with_advance) s
    and tokenize text =
        let mutable ar = PersistentVector.empty
        let mutable er = []
        if TripleString.is_open() && (text : string).Length = 0 then
            ar <- PersistentVector.conj ({from=0; nearTo=0}, TokText "\n") ar
    

        let tokens =
            many_iter (fun (x : (TokenizerRange * SpiralToken) list,er' : (TokenizerRange * string) list) ->
                List.iter (fun x -> ar <- PersistentVector.conj x ar) x
                er <- List.append er' er
                ) token
        let parser =
            let body = tokens .>> (tokenizeEol <|> tab)
            fun s ->
                if TripleString.is_open() then body s
                else (spaces >>. body) s
        let er =
            match parser {from=0; text=text} with Ok() -> er | Error er' -> List.append er' er
        ar, er
    and macro s =
        let char_to_macro_expr = function
            | '`' -> MType
            | '!' -> MTerm
            | '@' -> MTypeLit
            | '#' -> MTermInline
            | _ -> failwith "Compiler error: Unknown char in the tokenizer."
    

        let p_special_char s =
            match peek' s 0, peek' s 1 with
            | '\\', ('n' | 'r' | 't' | 'b' as c) ->
                let r = {from=s.from; nearTo=s.from+2}
                inc' 2 s
                Ok(EscapedChar(r, c))
            | '\\', ('v' as c) ->
                let r = {from=s.from; nearTo=s.from+2}
                inc' 2 s
                Ok(EscapedVar(r))
            | '\\', c ->
                let r = {from=s.from; nearTo=s.from+2}
                inc' 2 s
                Ok(UnescapedChar(r, c))
            | _ -> error_char s.from "\\"
    

        let p_var s = (many1Satisfy2L is_var_char_starting is_var_char "variable") s
        let p_text closing_char s = (range (many1SatisfyL (fun c -> c <> closing_char && c <> '`' && c <> '!' && c <> '@' && c <> '#' && c <> '\\') "macro text") |>> TokenizerText) s
        let p_expr s =
            let start = anyOf ['`'; '!'; '@'; '#']
            let case_paren start_char =
                let mutable c = 1 // number of open parens.
                between (skip_char '(') (skip_char ')') (many1SatisfyL (fun x -> // Stops when the number of open parens is 0.
                    c <- c + (match x with '(' -> 1 | ')' -> -1 | _ -> 0)
                    c > 0
                    ) "not )")
                |>> fun (body) range -> Expression(range,body,char_to_macro_expr start_char)
            let case_var start_char =
                (skip_char start_char |>> fun () range -> UnescapedChar(range,start_char))
                <|> (p_var |>> fun body range -> Var(range,body,char_to_macro_expr start_char))
            (range (start >>= fun start_char -> (case_paren start_char <|> case_var start_char))
            |>> fun (range, f) -> f range) s
        let p_macro_inner closing_char s = (many (p_special_char <|> p_text closing_char <|> p_expr) <|>% []) s
        let p_macro s =
            let body a b = range (between (skip_string a) (skip_char b) (p_macro_inner b))
            (body "$\"" '"' <|> body "$'" ''') s
    

        match (p_macro .>> spaces) s with
        | Ok(r, x) ->
            let start =
                let r = {from=r.from; nearTo=r.from+2}
                r, TokMacroOpen
            let end_ =
                let r = {from=r.nearTo-1; nearTo=r.nearTo}
                r, TokMacroClose
    

            let mutable er = []
            x |> List.collect (function
                | TokenizerText(r,x) -> [r, TokText x]
                | EscapedChar(r,x) ->
                    let x = match x with 'n' -> '\n' | 'r' -> '\r' | 't' -> '\t' | 'b' -> '\b' | x -> x
                    [r, TokEscapedChar x]
                | EscapedVar(r) -> [r, TokEscapedVar]
                | UnescapedChar(r,x) -> [r, TokUnescapedChar x]
                | Var(r,x,MType) -> [r, TokMacroTypeVar x]
                | Var(r,x,MTypeLit) -> [r, TokMacroTypeLitVar x]
                | Var(r,x,(MTerm | MTermInline as u)) -> [r, TokMacroTermVar(x, u = MTermInline)]
                | Expression(r,x,t) ->
                    let start =
                        let r = {from=r.from; nearTo=r.from+2}
                        r, TokMacroExpression(t,Open)
                    let end_ =
                        let r = {from=r.nearTo-1; nearTo=r.nearTo}
                        r, TokMacroExpression(t,Close)
                    let middle,er' =
                        let adjust_range (r : TokenizerRange,x) = {from=r.from + (fst start).nearTo; nearTo=r.nearTo + (fst start).nearTo}, x
                        let middle,er' = tokenize x
                        PersistentVector.map adjust_range middle,
                        List.map adjust_range er'
                    er <- List.append er' er
                    List.concat [[start]; List.ofSeq middle; [end_]]
                )
            |> fun l -> Ok(List.concat [[start]; l; [end_]], er)
        | Error er -> Error er
    

    /// ### LineToken
    type LineToken = TokenizerRange * SpiralToken
    

    /// ### LineComment
    type LineComment = TokenizerRange * string
    

    /// ### LineTokenErrors
    type LineTokenErrors = (TokenizerRange * TokenizerError) list
    

    /// ### vscode_tokens
    let vscode_tokens ((a,b) : VSCRange) (lines : LineToken PersistentVector PersistentVector) =
        let in_range x = min lines.Length x
        let from, near_to = in_range a.line, in_range (b.line+1)
        let toks = ResizeArray()
        let rec loop i line_delta =
            if i < near_to then
                lines.[i] |> PersistentVector.fold (fun (line_delta,from_prev) (r,x) ->
                    toks.AddRange [|line_delta; r.from-from_prev; r.nearTo-r.from; int (token_groups x); 0|]
                    0, r.from
                    ) (line_delta, 0)
                |> fst |> ((+) 1) |> loop (i+1)
    

        loop from from
        toks.ToArray()
    

    module Tokenize =
        let show_lit x =
            show_lit x
    

    /// ## BlockSplitting
    // open FSharpx.Collections
    

    /// ### LineTokens
    type LineTokens = LineToken PersistentVector PersistentVector
    

    /// ### Block<'a>
    type Block<'a> = {block: 'a; offset: int}
    

    /// ### block_at
    /// Reads the comments up to a statement, and then reads the statement body. Leaves any errors for the parsing stage.
    let block_at (lines : LineTokens) i =
        let mutable block = PersistentVector.empty
        let add x = block <- PersistentVector.conj x block
        let rec loop_initial i =
            if i < lines.Length then
                let x = lines.[i]
                add x
                if 0 < x.Length then
                    let r,t = x.[0]
                    if r.from = 0 then
                        match t with
                        | TokComment _ -> loop_initial (i+1)
                        | _ -> loop_body (i+1)
                    else loop_initial (i+1) // This branch will be an error in the parsing stage unless the token is a comment.
                else loop_initial (i+1)
        and loop_body i =
            if i < lines.Length then
                let x = lines.[i]
                if 0 < x.Length then
                    let r,_ = x.[0]
                    if r.from <> 0 then add x; loop_body (i+1)
                else add x; loop_body (i+1)
        loop_initial i
        {block = block; offset = i}
    

    /// ### block_all
    // Parses all the blocks.
    let rec block_all lines i =
        if i < PersistentVector.length lines then
            let x = block_at lines i
            x :: block_all lines (i+x.block.Length) else []
    

    /// ### wdiff_block_all
    // Parses all the blocks with diffing. Only parses those blocks which are dirty based of the edit range. Preserves ref equality and saves work.
    // Without considering ref preservation, it is functionally equivalent to just call `block_all` on just `lines`.
    // This function is difficult to read as it is several operations fused into one loop.
    let wdiff_block_all (blocks : LineTokens Block list) (lines : LineTokens, lines_added, from, nearTo) =
        // Lines added minus lines removed.
        let line_adjustment = lines_added - (nearTo - from)
        // The dirty block boundary needs to be more conservative when a separator is added in the first position of block.
        // Imagine adding a newline right on a block start. This would extend the previous block, but the naive check would not react to it.
        // The same goes for pasting an indented piece of text.
        let dirty_from = let x = lines.[from] in from - (if x.Length = 0 || 0 < (fst x.[0]).from then 1 else 0)
        let is_dirty (x : LineTokens Block) = (dirty_from <= x.offset && x.offset < nearTo) || (x.offset <= dirty_from && dirty_from < x.offset + x.block.Length)
        let rec loop blocks i =
            if i < lines.Length then
                match blocks with
                | x :: xs ->
                    // If the block is dirty, forget it.
                    if is_dirty x then loop xs i else
                        // If the block is past the removal range, adjust its line offset.
                        let x = {x with offset=if nearTo <= x.offset then x.offset + line_adjustment else x.offset}
                        // The block can't be dirty here. Hence if the offsets are the same, so are the blocks. Take it.
                        if x.offset = i then x :: loop xs (i + x.block.Length)
                        // Else if the block has been skipped over, forget it.
                        elif x.offset < i then loop xs i
                        // Else the block has been dirty filtered, recalculate it.
                        else let x = block_at lines i in x :: loop blocks (i + x.block.Length)
                | [] -> block_all lines i
            else []
        loop blocks 0
    

    /// ## BlockParsing
    // open System
    // open FParsec
    // open FSharp.Core
    

    /// ### SymbolString
    type SymbolString = string
    

    /// ### VarString
    type VarString = string
    

    /// ### NominalString
    type NominalString = string
    

    /// ### Layout
    type Layout = Heap | HeapMutable | StackMutable
    

    /// ### FunType
    type FunType = FT_Vanilla | FT_Pointer | FT_Closure // The closure and the pointer are specific to the C++ backend.
    

    /// ### Op
    type Op =
        // Converts the function to a specialized type specific to the C++ backend.
        | ToFunPtr
        | ToFunClosure
    

        // Compile time hash set
        | HashSetCreate
        | HashSetAdd
        | HashSetContains
        | HashSetRemove
        | HashSetCount
    

        // Compile time hash map
        | HashMapCreate
        | HashMapSetImmutable
        | HashMapSet
        | HashMapAdd
        | HashMapTryAdd
        | HashMapContains
        | HashMapRemove
        | HashMapCount
        | HashMapTryGet
    

        // Pragma
        | PragmaUnrollPush
        | PragmaUnrollPop
    

        // Backend branching
        | UnsafeBackendSwitch
        | BackendSwitch
    

        // Reordering check
        | UsesOriginalTermVars
        | UsesOriginalNominals
    

        // Imports
        | Global
    

        // Python
        | ToPythonRecord
        | ToPythonNamedTuple
    

        // Branching
        | While
        | Do
        | Indent
    

        // Layout
        | LayoutToHeap
        | LayoutToHeapMutable
        | LayoutToStackMutable
        | LayoutIndex
    

        // Type
        | TypeToVar
        | TypeToSymbol
        | TypeLitToLit
        | LitToTypeLit
        | LitToSymbol
    

        // Closure conversion
        | Dyn
    

        // Nominal
        | NominalCreate // In addition to regular nominals, it can also creates unions
        | NominalStrip
        | NominalTypeApply
    

        // Union
        | Unbox
        | Unbox2
        | UnionTag
        | UnionUntag
        | UnionToRecord
    

        // String
        | StringLength
        | StringIndex
        | StringSlice
        | StaticStringConcat
        | Printf // Cuda specific
    

        // Array
        | ArrayCreate
        | ArrayLength
        | ArrayIndex
        | ArrayIndexSet
    

        // Record
        | RecordMap
        | RecordIter
        | RecordFilter
        | RecordFold
        | RecordFoldBack
        | RecordLength
    

        // Record Type
        | RecordTypeMap
        | RecordTypeIter
        | RecordTypeFold
        | RecordTypeFoldBack
        | RecordTypeLength
        | RecordTypeTryFind
    

        // BinOps
        | Add
        | Sub
        | Mult
        | Div
        | Mod
        | Pow
        | LTE
        | LT
        | EQ
        | TypeEq
        | NEQ
        | GT
        | GTE
        | BoolAnd
        | BoolOr
        | BitwiseAnd
        | BitwiseOr
        | BitwiseXor
        | BitwiseComplement
        | ShiftLeft
        | ShiftRight
    

        // Unary math ops
        | Neg
        | Tanh
        | Log
        | Exp
        | Sin
        | Cos
        | Sqrt
        | NanIs
        | Conv
    

        // Infinity
        | Infinity
        | Pi
    

        // Static Is
        | LitIs
        | PrimIs
        | SymbolIs
        | VarIs
        | UnionIs
        | HeapUnionIs
        | LayoutIs
        | NominalIs
        | FunctionIs
        | ExistsIs
        | PrototypeHas
    

        // Static Type Is
        | PrimTypeIs
        | SymbolTypeIs
        | UnionTypeIs
        | HeapUnionTypeIs
        | LayoutTypeIs
        | ExistsTypeIs
        | NominalTypeIs
    

        // Panic
        | FailWith
    

        // Static unary operations
        | PrintStatic
        | PrintRaw
        | ErrorType
        | ExistsStrip
        | StringLitToSymbol
        | SymbolToString
    

        // Serialization helpers
        | VarTag
        | TagToSymbol
        | FunctionTermSlotsGet
        | FunctionTermSlotsSet
        | FreeVars
        | FreeVarsReplace
        | SizeOf
    

    /// ### PatternCompilationErrors
    type PatternCompilationErrors =
        | DisjointOrPatternVar
        | DuplicateTermVar
        | DuplicateTypeVar
        | ShadowedVar
        | DuplicateRecordSymbol
        | DuplicateRecordInjection
    

    /// ### ParserErrors
    type ParserErrors =
        | TypeVarsNeedToBeExplicitForExists
        | InvalidPattern of PatternCompilationErrors
        | ExpectedKeyword of TokenKeyword
        | ExpectedStringOpen | ExpectedStringClose
        | ExpectedMacroOpen | ExpectedMacroClose
        | ExpectedMacroVar | ExpectedMacroTypeVar | ExpectedMacroTypeLitVar
        | ExpectedEscapedChar of is_term_macro : bool
        | ExpectedText | ExpectedUnescapedChar
        | ExpectedOperator'
        | ExpectedOperator of string
        | ExpectedUnaryOperator'
        | ExpectedUnaryOperator of string
        | ExpectedUnit
        | ExpectedVar
        | ExpectedVarOrOpAsNameOfRecStatement
        | ExpectedVarOrOpAsNameOfGlobalStatement
        | ExpectedSmallVar
        | ExpectedBigVar
        | ExpectedLit
        | ExpectedSymbolPaired
        | SymbolPairedShouldStartWithUppercaseInTypeScope
        | ExpectedSymbol
        | ExpectedParenthesis of Parenthesis * ParenthesisState
        | ExpectedMacroExpression of MacroEnum * ParenthesisState
        | ExpectedOpenParenthesis
        | ExpectedStatement
        | ExpectedEob
        | ExpectedFunctionAsBodyOfRecStatement
        | ExpectedSinglePatternWhenStatementNameIsNorVarOrOp
        | ExpectedGlobalFunction
        | ExpectedExpression
        | InbuiltOpNotFound
        | UnknownOperator
        | UnexpectedEob
        | UnexpectedAndInlRec
        | ForallNotAllowed
        | TypecaseNotAllowed
        | MetavarNotAllowed
        | TermNotAllowed
        | UnknownError
        | DuplicateRecordTypeVar
        | DuplicateForallVar
        | DuplicateExistsVar
        | DuplicateConstraint
        | DuplicateTermRecordSymbol
        | DuplicateTermRecordInjection
        | DuplicateRecFunctionName
        | BottomUpNumberParseError of string * string
        | ExpectedPairedSymbolInUnion
        | DuplicateUnionKey
        | MetavarShadowedByVar
        | VarShadowedByMetavar
        | ListLiteralsNotAllowedInBottomUp
        | ArrayLiteralsNotAllowedInBottomUp
        | ForallNotAllowedInTypecase
        | ExistsNotAllowedInTypecase
    

    /// ### RawKindExpr
    type RawKindExpr =
        | RawKindWildcard
        | RawKindStar
        | RawKindFun of RawKindExpr * RawKindExpr
    

    /// ### UnionLayout
    type UnionLayout = UStack | UHeap
    

    /// ### HoVar
    type HoVar = VSCRange * (VarString * RawKindExpr)
    

    /// ### TypeVar
    type TypeVar = HoVar * (VSCRange * VarString) list
    

    /// ### RawMacro
    type RawMacro =
        | RawMacroText of VSCRange * string
        | RawMacroTerm of VSCRange * RawExpr * is_inline : bool
        | RawMacroType of VSCRange * RawTExpr
        | RawMacroTypeLit of VSCRange * RawTExpr
    and RawRecordWith =
        | RawRecordWithSymbol of (VSCRange * SymbolString) * RawExpr
        | RawRecordWithSymbolModify of (VSCRange * SymbolString) * RawExpr
        | RawRecordWithInjectVar of (VSCRange * VarString) * RawExpr
        | RawRecordWithInjectVarModify of (VSCRange * VarString) * RawExpr
    and RawRecordWithout =
        | RawRecordWithoutSymbol of VSCRange * SymbolString
        | RawRecordWithoutInjectVar of VSCRange * VarString
    and PatRecordMember =
        | PatRecordMembersSymbol of (VSCRange * SymbolString) * name: Pattern
        | PatRecordMembersInjectVar of (VSCRange * VarString) * name: Pattern
    and Pattern =
        | PatB of VSCRange
        | PatE of VSCRange
        | PatVar of VSCRange * VarString
        | PatDyn of VSCRange * Pattern
        | PatUnbox of VSCRange * symbol: string * Pattern
        | PatExists of VSCRange * (VSCRange * VarString) list * Pattern
        | PatAnnot of VSCRange * Pattern * RawTExpr
        | PatPair of VSCRange * Pattern * Pattern
        | PatSymbol of VSCRange * string
        | PatRecordMembers of VSCRange * PatRecordMember list
        | PatOr of VSCRange * Pattern * Pattern
        | PatAnd of VSCRange * Pattern * Pattern
        | PatValue of VSCRange * Literal
        | PatDefaultValue of VSCRange * VarString
        | PatWhen of VSCRange * Pattern * RawExpr
        | PatNominal of VSCRange * (VSCRange * VarString) *  (VSCRange * VarString) list * Pattern
        | PatArray of VSCRange * Pattern list
        | PatFilledDefaultValue of VSCRange * VarString * RawTExpr // Filled in by the inferencer.
    and RawExpr =
        | RawB of VSCRange
        | RawV of VSCRange * VarString * is_tvar_applied : bool
        | RawLit of VSCRange * Literal
        | RawDefaultLit of VSCRange * string
        | RawSymbol of VSCRange * SymbolString
        | RawType of VSCRange * RawTExpr
        | RawMatch of VSCRange * body: RawExpr * (Pattern * RawExpr) list
        | RawFun of VSCRange * (Pattern * RawExpr) list
        | RawForall of VSCRange * TypeVar * RawExpr
        | RawExists of VSCRange * (VSCRange * RawTExpr list option) * RawExpr
        | RawRecBlock of VSCRange * ((VSCRange * VarString) * RawExpr) list * on_succ: RawExpr // The bodies of a block must be RawFun or RawForall.
        | RawRecordWith of VSCRange * RawExpr list * RawRecordWith list * RawRecordWithout list
        | RawOp of VSCRange * Op * RawExpr list
        | RawJoinPoint of VSCRange * backend: (VSCRange * string) option * RawExpr * name: string option
        | RawAnnot of VSCRange * RawExpr * RawTExpr
        | RawTypecase of VSCRange * RawTExpr * (RawTExpr * RawExpr) list
        | RawOpen of VSCRange * (VSCRange * VarString) * (VSCRange * SymbolString) list * on_succ: RawExpr
        | RawApply of VSCRange * RawExpr * RawExpr
        | RawIfThenElse of VSCRange * RawExpr * RawExpr * RawExpr
        | RawIfThen of VSCRange * RawExpr * RawExpr
        | RawPair of VSCRange * RawExpr * RawExpr
        | RawSeq of VSCRange * RawExpr * RawExpr
        | RawHeapMutableSet of VSCRange * RawExpr * RawExpr list * RawExpr
        | RawReal of VSCRange * RawExpr
        | RawMacro of VSCRange * RawMacro list
        | RawArray of VSCRange * RawExpr list
        | RawMissingBody of VSCRange
        | RawFilledForall of VSCRange * string * RawExpr // Filled in by the inferencer.
    and RawTExpr =
        | RawTWildcard of VSCRange
        | RawTB of VSCRange
        | RawTMetaVar of VSCRange * VarString
        | RawTLit of VSCRange * Literal
        | RawTVar of VSCRange * VarString
        | RawTPair of VSCRange * RawTExpr * RawTExpr
        | RawTFun of VSCRange * RawTExpr * RawTExpr * FunType
        | RawTArray of VSCRange * RawTExpr
        | RawTRecord of VSCRange * Map<int * string,RawTExpr>
        | RawTSymbol of VSCRange * SymbolString
        | RawTApply of VSCRange * RawTExpr * RawTExpr
        | RawTForall of VSCRange * TypeVar * RawTExpr
        | RawTExists of VSCRange * TypeVar list * RawTExpr
        | RawTPrim of VSCRange * PrimitiveType
        | RawTTerm of VSCRange * RawExpr
        | RawTMacro of VSCRange * RawMacro list
        | RawTUnion of VSCRange * Map<int * string,bool * RawTExpr> * UnionLayout * this: RawTExpr  // The boolean arg determines whether the union case is generalized. `this` is the self type.
        | RawTLayout of VSCRange * RawTExpr * Layout
        | RawTTypecase of VSCRange * RawTExpr * (RawTExpr * RawTExpr) list
        | RawTFilledNominal of VSCRange * GlobalId // Filled in by the inferencer.
    

    /// ### (+.)
    let (+.) (a,_) (_,b) = a,b
    

    /// ### range_of_hovar
    let range_of_hovar ((r,_) : HoVar) = r
    

    /// ### range_of_typevar
    let range_of_typevar ((x,_) : TypeVar) = range_of_hovar x
    

    /// ### hovar_name
    let hovar_name ((_,(name,_)) : HoVar) = name
    

    /// ### typevar_name
    let typevar_name ((h,_) : TypeVar) = hovar_name h
    

    /// ### range_of_record_with
    let range_of_record_with = function
        | RawRecordWithSymbol((r,_),_)
        | RawRecordWithSymbolModify((r,_),_)
        | RawRecordWithInjectVar((r,_),_)
        | RawRecordWithInjectVarModify((r,_),_) -> r
    

    /// ### range_of_record_without
    let range_of_record_without = function
        | RawRecordWithoutSymbol(r,_)
        | RawRecordWithoutInjectVar(r,_) -> r
    

    /// ### range_of_pattern
    let range_of_pattern = function
        | PatB r
        | PatE r
        | PatVar(r,_)
        | PatDyn(r,_)
        | PatUnbox(r,_,_)
        | PatExists(r,_,_)
        | PatSymbol(r,_)
        | PatValue(r,_)
        | PatDefaultValue(r,_)
        | PatRecordMembers(r,_)
        | PatArray(r,_)
        | PatAnnot(r,_,_)
        | PatPair(r,_,_)
        | PatOr(r,_,_)
        | PatAnd(r,_,_)
        | PatWhen(r,_,_)
        | PatFilledDefaultValue(r,_,_)
        | PatNominal(r,_,_,_) -> r
    

    /// ### range_of_pat_record_member
    let range_of_pat_record_member = function
        | PatRecordMembersSymbol((r,_),x)
        | PatRecordMembersInjectVar((r,_),x) -> r +. range_of_pattern x
    

    /// ### range_of_expr
    let range_of_expr = function
        | RawB r
        | RawMissingBody r
        | RawMacro(r,_)
        | RawV(r,_,_)
        | RawLit(r,_)
        | RawDefaultLit(r,_)
        | RawSymbol(r,_)
        | RawType(r,_)
        | RawJoinPoint(r,_,_,_)
        | RawArray(r,_)
        | RawMatch(r,_,_)
        | RawFun(r,_)
        | RawReal(r,_)
        | RawRecBlock(r,_,_)
        | RawOp(r,_,_)
        | RawAnnot(r,_,_)
        | RawTypecase(r,_,_)
        | RawForall(r,_,_)
        | RawExists(r,_,_)
        | RawFilledForall(r,_,_)
        | RawApply(r,_,_)
        | RawPair(r,_,_)
        | RawIfThen(r,_,_)
        | RawSeq(r,_,_)
        | RawHeapMutableSet(r,_,_,_)
        | RawRecordWith(r,_,_,_)
        | RawIfThenElse(r,_,_,_)
        | RawOpen(r,_,_,_) -> r
    

    /// ### rawv
    let rawv (r,x) = RawV(r,x,true)
    

    /// ### range_of_texpr
    let range_of_texpr = function
        | RawTWildcard r
        | RawTB r
        | RawTLit(r,_)
        | RawTMacro(r,_)
        | RawTMetaVar(r,_)
        | RawTVar(r,_)
        | RawTArray(r,_)
        | RawTRecord(r,_)
        | RawTUnion(r,_,_,_)
        | RawTSymbol(r,_)
        | RawTPrim(r,_)
        | RawTTerm(r,_)
        | RawTFilledNominal(r,_)
        | RawTPair(r,_,_)
        | RawTFun(r,_,_,_)
        | RawTApply(r,_,_)
        | RawTLayout(r,_,_)
        | RawTExists(r,_,_)
        | RawTTypecase(r,_,_)
        | RawTForall(r,_,_) -> r
    

    /// ### range_of_texpr_gadt_constructor
    let rec range_of_texpr_gadt_constructor = function
        | RawTForall(_,_,x) -> range_of_texpr_gadt_constructor x
        | RawTFun(_,_,x,_) | x -> range_of_texpr x
    

    /// ### range_of_texpr_gadt_body
    let rec range_of_texpr_gadt_body = function
        | RawTForall(_,_,x) -> range_of_texpr_gadt_body x
        | RawTFun(_,x,_,_) | x -> range_of_texpr x
    

    /// ### VectorCord
    type VectorCord = {|row : int; col : int|}
    

    /// ### BlockParsingEnv
    type BlockParsingEnv = {
        semantic_updates : (VectorCord * SemanticTokenLegend) ResizeArray
        tokens_cords : VectorCord []
        tokens : (VSCRange * SpiralToken) []
        comments : LineComment option []
        i : int ref
        is_top_down : bool
        default_env : DefaultEnv
        } with
    

        member d.Index with get() = d.i.contents and set(i) = d.i.Value <- i
    

    /// ### try_current_template
    let inline try_current_template (d : BlockParsingEnv) on_succ on_fail =
        let i = d.Index
        if i < d.tokens.Length then on_succ d.tokens.[i]
        else on_fail()
    

    /// ### try_current
    let inline try_current d f = try_current_template d (fun (p,t) -> f (p, t)) (fun () -> Error [])
    

    /// ### print_current
    let print_current d = try_current d (fun x -> printfn "%A" x; Ok()) // For parser debugging purposes.
    

    /// ### line_template
    let inline line_template d f = try_current_template d (fst >> f) (fun _ -> -1)
    

    /// ### col
    let col d = line_template d (fun (r,_) -> r.character)
    

    /// ### lineBlockParsing
    let lineBlockParsing d = line_template d (fun (r,_) -> r.line)
    

    /// ### skip'
    let skip' (d : BlockParsingEnv) i = d.i.Value <- d.i.contents+i
    

    /// ### blockParsingSkip
    let blockParsingSkip d = skip' d 1
    

    /// ### skip_string_open
    let skip_string_open d =
        try_current d <| function
            | p,TokStringOpen -> blockParsingSkip d; Ok(p)
            | p, _ -> Error [p, ExpectedStringOpen]
    

    /// ### skip_string_close
    let skip_string_close d =
        try_current d <| function
            | p,TokStringClose -> blockParsingSkip d; Ok(p)
            | p, _ -> Error [p, ExpectedStringClose]
    

    /// ### skip_macro_open
    let skip_macro_open d =
        try_current d <| function
            | p,TokMacroOpen -> blockParsingSkip d; Ok(p)
            | p, _ -> Error [p, ExpectedMacroOpen]
    

    /// ### skip_macro_close
    let skip_macro_close d =
        try_current d <| function
            | p,TokMacroClose -> blockParsingSkip d; Ok(p)
            | p, _ -> Error [p, ExpectedMacroClose]
    

    /// ### read_text
    let read_text is_term_macro d =
        let (+.) a b =
            match a with
            | Some a -> Some (a +. b)
            | None -> Some b
        let rec loop (a : VSCRange option) (str : Text.StringBuilder) =
            try_current d <| function
                | b,TokText x -> blockParsingSkip d; loop (a +. b) (str.Append(x))
                | b,TokEscapedVar when is_term_macro -> blockParsingSkip d; loop (a +. b) (str.Append("\\v"))
                | b,(TokEscapedChar x | TokUnescapedChar x) -> blockParsingSkip d; loop (a +. b) (str.Append(x))
                | b, _ ->
                    if Option.isNone a then Error [b, ExpectedText; b, ExpectedEscapedChar is_term_macro; b, ExpectedUnescapedChar]
                    else Ok(Option.get a, str.ToString())
        loop None (Text.StringBuilder())
    

    /// ### read_macro_var
    let read_macro_var d =
        try_current d <| function
            | p, TokMacroTermVar (x, is_inline) -> blockParsingSkip d; Ok(RawMacroTerm(p,rawv(p,x),is_inline))
            | p, TokMacroTypeVar x -> blockParsingSkip d; Ok(RawMacroType(p,RawTVar(p,x)))
            | p, TokMacroTypeLitVar x -> blockParsingSkip d; Ok(RawMacroTypeLit(p,RawTVar(p,x)))
            | p,_ -> Error [p, ExpectedMacroVar]
    

    /// ### read_macro_type_var
    let read_macro_type_var d =
        try_current d <| function
            | p, TokMacroTypeVar x -> blockParsingSkip d; Ok(RawMacroType(p,RawTVar(p,x)))
            | p, TokMacroTypeLitVar x -> blockParsingSkip d; Ok(RawMacroTypeLit(p,RawTVar(p,x)))
            | p,_ -> Error [p, ExpectedMacroTypeVar]
    

    /// ### skip_keyword
    let skip_keyword t d =
        try_current d <| function
            | p,TokKeyword t' when t = t' -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedKeyword t]
    

    /// ### skip_keyword'
    let skip_keyword' t d =
        try_current d <| function
            | p,TokKeyword t' when t = t' -> blockParsingSkip d; Ok p
            | p, _ -> Error [p, ExpectedKeyword t]
    

    /// ### read_unary_op
    let read_unary_op d =
        try_current d <| function
            | p, TokUnaryOperator(t',_) -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedUnaryOperator']
    

    /// ### read_unary_op'
    let read_unary_op' d =
        try_current d <| function
            | p, TokUnaryOperator(t',_) -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedUnaryOperator']
    

    /// ### read_op
    let read_op d =
        try_current d <| function
            | p, TokOperator(t',_) -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedOperator']
    

    /// ### read_op'
    let read_op' d =
        try_current d <| function
            | p, TokOperator(t',_) -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedOperator']
    

    /// ### update_semantic
    let update_semantic (d : BlockParsingEnv) = let i = d.Index in fun x -> d.semantic_updates.Add(d.tokens_cords.[i], x)
    

    /// ### read_op_type
    let read_op_type d =
        try_current d <| function
            | p, TokOperator(t',r) -> update_semantic d SemanticTokenLegend.type_variable; blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedOperator']
    

    /// ### skip_op
    let skip_op t d =
        try_current d <| function
            | p, TokOperator(t',_) when t' = t -> blockParsingSkip d; Ok p
            | p, _ -> Error [p, ExpectedOperator t]
    

    /// ### skip_unary_op
    let skip_unary_op t d =
        try_current d <| function
            | p, TokUnaryOperator(t',_) when t' = t -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedUnaryOperator t]
    

    /// ### read_var
    let read_var d =
        try_current d <| function
            | p, TokVar(t',_) -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedVar]
    

    /// ### read_var'
    let read_var' d =
        try_current d <| function
            | p, TokVar(t',_) -> let r = update_semantic d in blockParsingSkip d; Ok(p,t',r)
            | p, _ -> Error [p, ExpectedVar]
    

    /// ### read_var''
    let read_var'' d =
        try_current d <| function
            | p, TokVar(t',_) -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedVar]
    

    /// ### read_big_var
    let read_big_var d =
        try_current d <| function
            | p, TokVar(t',_) when Char.IsUpper(t',0) -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedBigVar]
    

    /// ### read_var_as_symbol
    let read_var_as_symbol d =
        try_current d <| function
            | p, TokVar(t',_) -> update_semantic d SemanticTokenLegend.symbol; blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedVar]
    

    /// ### read_big_var_as_symbol
    let read_big_var_as_symbol d =
        try_current d <| function
            | p, TokVar(t',_) when Char.IsUpper(t',0) -> update_semantic d SemanticTokenLegend.symbol; blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedBigVar]
    

    /// ### read_big_var_as_keyword
    let read_big_var_as_keyword d =
        try_current d <| function
            | p, TokVar(t',_) when Char.IsUpper(t',0) -> update_semantic d SemanticTokenLegend.keyword; blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedBigVar]
    

    /// ### read_small_var
    let read_small_var d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) = false -> blockParsingSkip d; Ok t'
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_small_var'
    let read_small_var' d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) = false -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_big_type_var
    let read_big_type_var d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) -> update_semantic d SemanticTokenLegend.type_variable; blockParsingSkip d; Ok(t')
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_big_type_var'
    let read_big_type_var' d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) -> update_semantic d SemanticTokenLegend.type_variable; blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_small_type_var
    let read_small_type_var d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) = false -> update_semantic d SemanticTokenLegend.type_variable; blockParsingSkip d; Ok(t')
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_small_type_var'
    let read_small_type_var' d =
        try_current d <| function
            | p, TokVar(t',r) when Char.IsUpper(t',0) = false -> update_semantic d SemanticTokenLegend.type_variable; blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedSmallVar]
    

    /// ### read_value
    let read_value d =
        try_current d <| function
            | p, TokValue t' ->
                blockParsingSkip d
                if d.Index < d.tokens.Length then
                    match snd d.tokens.[d.Index] with
                    | TokValueSuffix -> blockParsingSkip d
                    | _ -> ()
                Ok(p,t')
            | p, _ -> Error [p, ExpectedLit]
    

    /// ### read_symbol
    let read_symbol d =
        try_current d <| function
            | p, TokSymbol(t',r) -> blockParsingSkip d; Ok(p,t')
            | p, _ -> Error [p, ExpectedSymbol]
    

    /// ### skip_parenthesis
    let skip_parenthesis a b d =
        try_current d <| function
            | p, TokParenthesis(a',b') when a = a' && b = b' -> blockParsingSkip d; Ok()
            | p, _ -> Error [p, ExpectedParenthesis(a,b)]
    

    /// ### skip_macro_expression
    let skip_macro_expression a b d =
        try_current d <| function
            | p, TokMacroExpression(a',b') when a = a' && b = b' -> blockParsingSkip d; Ok()
            | p, _ -> Error [p, ExpectedMacroExpression(a,b)]
    

    /// ### on_succ
    let on_succ x _ = Ok x
    

    /// ### macro_expression
    // open FParsec
    let macro_expression ty a d = (skip_macro_expression ty Open >>. a .>> skip_macro_expression ty Close) d
    

    /// ### rounds
    let rounds a d = (skip_parenthesis Round Open >>. a .>> skip_parenthesis Round Close) d
    

    /// ### curlies
    let curlies a d = (skip_parenthesis Curly Open >>. a .>> skip_parenthesis Curly Close) d
    

    /// ### squares
    let squares a d = (skip_parenthesis Square Open >>. a .>> skip_parenthesis Square Close) d
    

    /// ### blockParsingIndex
    let blockParsingIndex (t : BlockParsingEnv) = t.Index
    

    /// ### blockParsingIndex_set
    let blockParsingIndex_set v (t : BlockParsingEnv) = t.Index <- v
    

    /// ### blockParsingRange
    let inline blockParsingRange exp s =
        let i = blockParsingIndex s
        exp s |> Result.map (fun x ->
            let i' = blockParsingIndex s
            if i < i' then fst s.tokens.[i] +. fst s.tokens.[i'-1], x : VSCRange * _
            else
                failwith "Compiler error: The parser passed into `range` has to consume at least one token for it to work."
            )
    

    /// ### kind
    let rec kind d = (sepBy1 ((skip_op "*" >>% RawKindStar) <|> rounds kind) (skip_op "->") |>> List.reduceBack (fun a b -> RawKindFun (a,b))) d
    

    /// ### duplicates
    let duplicates er x =
        let h = Collections.Generic.HashSet()
        x |> List.choose (fun (r : VSCRange,n : string) -> if h.Add n = false then Some(r,er) else None)
    

    /// ### blockParsingIndent
    let inline blockParsingIndent i op next d = if op i (col d) then next d else Error []
    

    /// ### record_var
    let record_var d = (read_var_as_symbol <|> rounds read_op) d
    

    /// ### patterns_validate
    let patterns_validate pats =
        let pos = Collections.Generic.Dictionary(HashIdentity.Reference)
        let errors = ResizeArray()
        let rec loop is_type pat =
            let loop = loop is_type
            let inline duplicate_var() = InvalidPattern (if is_type then DuplicateTypeVar else DuplicateTermVar)
            match pat with
            | PatFilledDefaultValue _ | PatDefaultValue _ | PatValue _ | PatSymbol _ | PatE _ | PatB _ -> Set.empty
            | PatArray(_,x) ->
                List.fold (fun s x ->
                    let x = loop x
                    let inters = Set.intersect s x
                    if Set.isEmpty inters = false then inters |> Set.iter (fun x -> errors.Add(pos.[x], duplicate_var()))
                    s + x
                    ) Set.empty x
            | PatExists(r,l,p) ->
                if is_type then
                    let s = List.fold (fun s (r,x) -> pos.Add(x,r); Set.add x s) Set.empty l
                    let x = loop p
                    let inters = Set.intersect s x
                    if Set.isEmpty inters = false then inters |> Set.iter (fun x -> errors.Add(pos.[x], duplicate_var()))
                    s + x
                else
                    loop p
            | PatVar(r,x) ->
                if is_type then
                    Set.empty
                else
                    pos.Add(x,r)
                    Set.singleton x
            | PatDyn(_,p) | PatAnnot (_,p,_) | PatNominal(_,_,_,p) | PatUnbox(_,_,p) | PatWhen(_,p,_) -> loop p
            | PatRecordMembers(_,items) ->
                let symbols = Collections.Generic.HashSet()
                let injects = Collections.Generic.HashSet()
                let vars = Collections.Generic.HashSet()
                List.iter (fun item ->
                    match item with
                    | PatRecordMembersSymbol((r,keyword),name) ->
                        if symbols.Add(keyword) = false then errors.Add (r, InvalidPattern DuplicateRecordSymbol); Set.empty else loop name
                    | PatRecordMembersInjectVar((r,var),name) ->
                        if injects.Add(var) = false then errors.Add (r, InvalidPattern DuplicateRecordInjection); Set.empty else loop name
                    |> Set.iter (fun x -> if vars.Add x = false then errors.Add (pos.[x], duplicate_var()))
                    ) items
                Set vars
            | PatPair(_,a,b) | PatAnd(_,a,b) ->
                let a, b = loop a, loop b
                Set.intersect b a |> Set.iter (fun x -> errors.Add (pos.[x], duplicate_var()))
                a + b
            | PatOr(_,a,b) ->
                let a, b = loop a, loop b
                let f = Set.iter (fun x -> errors.Add (pos.[x], InvalidPattern DisjointOrPatternVar))
                f (a-b); f (b-a)
                a
    

        let validate is_type =
            List.fold (fun s x ->
                let s' = loop is_type x
                Set.intersect s' s |> Set.iter (fun x -> errors.Add(pos.[x],InvalidPattern ShadowedVar))
                s + s'
                ) Set.empty pats |> ignore
        validate true; validate false
        errors |> Seq.toList
    

    /// ### join_point
    let join_point is_let name = function // Has the effect of removing nested join points due to not duplicating them.
        | RawJoinPoint(a,b,c,_) -> RawJoinPoint(a,b,c,name)
        | x -> if is_let then RawJoinPoint(range_of_expr x, None, x, name) else x
    

    /// ### join_point_backend
    let join_point_backend (a,b) = RawJoinPoint(range_of_expr b, Some a, b, None)
    

    /// ### unintern
    /// Some places need unique string refs, so this is to keep the compiler from interning static strings.
    let unintern (x : string) = Text.StringBuilder(x).ToString()
    

    /// ### adjust_join_point
    let rec adjust_join_point is_let name x =
        let dyn_if_let a = if is_let then PatDyn(range_of_pattern a, a) else a
        match x with
        | RawForall(r,a,b) -> RawForall(r,a,adjust_join_point is_let name b)
        | RawFun(r,[a,b]) -> RawFun(r,[dyn_if_let a, adjust_join_point is_let name b])
        | RawFun(r,l) ->
            let empty = fst r, fst r
            let n = unintern " arg"
            let a = PatVar(empty,n) |> dyn_if_let
            let b = RawMatch(empty,rawv(empty,n),l)
            RawFun(r,[a,join_point is_let name b])
        | x -> join_point is_let name x
    

    /// ### adjust_join_point'
    let adjust_join_point' is_let name = function
        | RawForall _ | RawFun _ as x -> adjust_join_point is_let name x
        | x -> x
    

    /// ### inl_or_let_process
    let inl_or_let_process (r, (is_let, is_rec, name, foralls, pats, body)) _ =
        match is_rec, name, foralls, pats with
        | false, _, [], [] ->
            match patterns_validate [name] with
            | [] -> Ok((r,name,adjust_join_point' is_let (match name with PatVar(_,name) -> Some name | _ -> None) body),is_rec)
            | ers -> Error ers
        | _, PatVar(_,name'), _, _ ->
            match patterns_validate (if is_rec then name :: pats else pats) with
            | [] ->
                let body =
                    let dyn_if_let x = if is_let then PatDyn(range_of_pattern x, x) else x
                    adjust_join_point is_let (Some name') body
                    |> List.foldBack (fun pat body -> RawFun(range_of_pattern pat +. range_of_expr body,[dyn_if_let pat,body])) pats
                    |> List.foldBack (fun typevar body -> RawForall(range_of_typevar typevar +. range_of_expr body,typevar,body)) foralls
                match is_rec, body with
                | false, _ | true, (RawFun _ | RawForall _) -> Ok((r,name,body),is_rec)
                | true, _ -> Error [r, ExpectedFunctionAsBodyOfRecStatement]
            | ers -> Error ers
        | true, _, _, _ -> Error [range_of_pattern name, ExpectedVarOrOpAsNameOfRecStatement]
        | false, _, _, _ -> Error [range_of_pattern name, ExpectedSinglePatternWhenStatementNameIsNorVarOrOp]
    

    /// ### ho_var
    let ho_var d : Result<HoVar,_> = blockParsingRange ((read_small_type_var |>> fun x -> x, RawKindWildcard) <|> rounds ((read_small_type_var .>> skip_op ":") .>>. kind)) d
    

    /// ### forall_var
    let forall_var d : Result<TypeVar,_> = (ho_var .>>. (curlies (sepBy (read_small_type_var' <|> rounds read_op_type) (skip_op ";")) <|>% [])) d
    

    /// ### forall
    let forall d =
        (skip_keyword SpecForall >>. many1 forall_var .>> skip_op "."
        >>= fun q _ ->
            let x' = q |> List.collect (fun (_,l) -> duplicates DuplicateConstraint l)
            let x = q |> List.map (fun ((r,(a,_)),_) -> r,a) |> duplicates DuplicateForallVar
            match List.append x x' with [] -> Ok q | er -> Error er
            ) d
    

    /// ### pat_exists'
    let pat_exists' d =
        (skip_keyword SpecExists >>. many (blockParsingRange read_small_type_var) .>> skip_op "."
        >>= fun q _ ->
            match duplicates DuplicateExistsVar q with [] -> Ok q | er -> Error er
            ) d
    

    /// ### exists
    let exists d =
        (skip_keyword SpecExists >>. many forall_var .>> skip_op "."
        >>= fun q _ ->
            let x' = q |> List.collect (fun (_,l) -> duplicates DuplicateConstraint l)
            let x = q |> List.map (fun ((r,(a,_)),_) -> r,a) |> duplicates DuplicateExistsVar
            match List.append x x' with [] -> Ok q | er -> Error er
            ) d
    

    /// ### annotated_body
    let inline annotated_body sep exp ty =
        pipe2 (opt (skip_op ":" >>. ty))
            (skip_op sep .>>. opt exp)
            (fun a (r,b) ->
                let b = match b with Some b -> b | None -> RawMissingBody r
                match a with
                | Some a -> RawAnnot(range_of_expr b +. range_of_texpr a,b,a)
                | None -> b)
    

    /// ### inl_or_let
    let inline inl_or_let exp pattern ty =
        blockParsingRange (tuple6 ((skip_keyword SpecInl >>% false) <|> (skip_keyword SpecLet >>% true))
                ((skip_keyword SpecRec >>% true) <|>% false) pattern
                (forall <|>% []) (many pattern) (annotated_body "=" exp ty))
        >>= inl_or_let_process
    

    /// ### and_inl_or_let
    let inline and_inl_or_let exp pattern ty =
        blockParsingRange (tuple6 (skip_keyword SpecAnd >>. ((skip_keyword SpecInl >>% false) <|> (skip_keyword SpecLet >>% true)))
                (fun _ -> Ok true) pattern
                (forall <|>% []) (many pattern) (annotated_body "=" exp ty))
        >>= inl_or_let_process
    

    /// ### Associativity
    type Associativity = FParsec.Associativity
    

    /// ### inbuilt_operators
    let inbuilt_operators x =
        match x with
        | "+" -> ValueSome(60, Associativity.Left)
        | "-" -> ValueSome(60, Associativity.Left)
        | "*" -> ValueSome(70, Associativity.Left)
        | "/" -> ValueSome(70, Associativity.Left)
        | "%" -> ValueSome(70, Associativity.Left)
        | "</>" -> ValueSome(43, Associativity.Left)
        | "<|>" -> ValueSome(42, Associativity.Left)
        | "|>" -> ValueSome(41, Associativity.Left)
        | "||>" -> ValueSome(41, Associativity.Left)
        | "|||>" -> ValueSome(41, Associativity.Left)
        | ">>" -> ValueSome(45, Associativity.Left)
        | "<-" -> ValueSome(4, Associativity.Left)
    

        | "<=" -> ValueSome(40, Associativity.None)
        | "<" -> ValueSome(40, Associativity.None)
        | "=" -> ValueSome(40, Associativity.None)
        | "`=" -> ValueSome(40, Associativity.None)
        | ">" -> ValueSome(40, Associativity.None)
        | ">=" -> ValueSome(40, Associativity.None)
        | "<>" -> ValueSome(40, Associativity.None)
        | "<<<" -> ValueSome(40, Associativity.None)
        | ">>>" -> ValueSome(40, Associativity.None)
        | "&&&" -> ValueSome(40, Associativity.None)
        | "|||" -> ValueSome(40, Associativity.None)
    

        | "||" -> ValueSome(20, Associativity.Left)
        | "&&" -> ValueSome(30, Associativity.Left)
        | "::" -> ValueSome(50, Associativity.Right)
        | "^" -> ValueSome(45, Associativity.Right)
        | "<|" -> ValueSome(41, Associativity.Right)
        | "<<" -> ValueSome(45, Associativity.Left)
        | "." -> ValueSome(2, Associativity.Right)
        | "," -> ValueSome(6, Associativity.Right)
        | ":>" -> ValueSome(35, Associativity.Right)
        | ":?>" -> ValueSome(35, Associativity.Right)
        | "**" -> ValueSome(80, Associativity.Right)
        | _ -> ValueNone
    

    /// ### precedence_associativity
    // The `.` operator has special behavior similar to F#.
    let rec precedence_associativity name =
        if 0 < String.length name then
            if 1 < String.length name && name.[0] = '.' then precedence_associativity name.[1..]
            else
                match inbuilt_operators name with
                | ValueNone -> precedence_associativity (name.[0..name.Length-2])
                | v -> v
        else ValueNone
    

    /// ### op
    let op (d : BlockParsingEnv) =
        blockParsingRange read_op d |> Result.bind (fun (o,x) ->
            match x with
            | "=>" | "|" | ":" | ";" -> skip' d -1; Error [] // Separators get special handling for sake of better error messages.
            | _ ->
                match precedence_associativity x with // TODO: Might be good to memoize this.
                | ValueNone -> Error [o, UnknownOperator]
                | ValueSome(p,a) ->
                    let inline f on_succ = Ok(p,a,fun (a,b) ->
                        let ra, rb = range_of_expr a, range_of_expr b
                        let r = ra +. rb
                        on_succ(r,a,b)
                        )
                    match x with
                    | "." -> f RawSeq
                    | "&&" -> f (fun (r,a,b) -> RawIfThenElse(r,a,b,RawLit(o,LitBool false)))
                    | "||" -> f (fun (r,a,b) -> RawIfThenElse(r,a,RawLit(o,LitBool true),b))
                    | "," -> f RawPair
                    | "<-" -> f (fun (r,a,c) ->
                        let rec loop l = function
                            | RawApply(_,a,b) -> loop (b :: l) a
                            | a -> a, l
                        let a,b = loop [] a
                        RawHeapMutableSet(r,a,b,c)
                        )
                    | x -> f (fun (r,a,b) -> RawApply(r,RawApply(r +. o,rawv(o,x),a),b))
            )
    

    /// ### string_to_op_dict
    let string_to_op_dict : Dictionary<string,Op> = Collections.Generic.Dictionary(HashIdentity.Structural)
    

    do Microsoft.FSharp.Reflection.FSharpType.GetUnionCases(typeof<Op>) |> Array.iter (fun x -> string_to_op_dict.[x.Name] <- Microsoft.FSharp.Reflection.FSharpValue.MakeUnion(x,[||]) :?> Op)
    

    /// ### string_to_op
    let string_to_op x = string_to_op_dict.TryGetValue x
    

    /// ### symbol_paired_concat
    let symbol_paired_concat k =
        let b = Text.StringBuilder()
        List.iter (fun (_, x : string) -> b.Append(x).Append('_') |> ignore) k
        b.ToString()
    

    /// ### blockParsingModule_open
    let blockParsingModule_open = blockParsingRange ((skip_keyword SpecOpen >>. read_small_var') .>>. (many read_symbol))
    

    /// ### bar
    let bar i d = blockParsingIndent i (<=) (skip_op "|") d
    

    /// ### pat_pair
    let inline pat_pair next =
        sepBy1 next (skip_op ",")
        |>> List.reduceBack (fun a b -> PatPair(range_of_pattern a +. range_of_pattern b,a,b))
    

    /// ### RootTypeFlags
    type RootTypeFlags = {
        allow_typecase_metavars : bool
        allow_term : bool
        allow_wildcard : bool
        }
    

    /// ### root_type_defaults
    let root_type_defaults = {
        allow_typecase_metavars = false
        allow_term = false
        allow_wildcard = false
        }
    

    /// ### bottom_up_number
    let bottom_up_number (default_env : DefaultEnv) (r : VSCRange,x : string) =
        let inline f string_to_val val_to_lit val_dsc =
            match string_to_val x with
            | true, x -> Ok(r, val_to_lit x)
            | false, _ -> Error [r, BottomUpNumberParseError(x,val_dsc)]
        if x.Contains '.' then
            match default_env.default_float with
            | Float32T -> f Single.TryParse LitFloat32 "f32"
            | Float64T -> f Double.TryParse LitFloat64 "f64"
            | x -> failwithf "Compiler error: Invalid default float type. Got: %A" x
        else
            match default_env.default_int with
            | Int8T -> f SByte.TryParse LitInt8 "i8"
            | Int16T -> f Int16.TryParse LitInt16 "i16"
            | Int32T -> f Int32.TryParse LitInt32 "i32"
            | Int64T -> f Int64.TryParse LitInt64 "i64"
            | UInt8T -> f Byte.TryParse LitUInt8 "u8"
            | UInt16T -> f UInt16.TryParse LitUInt16 "u16"
            | UInt32T -> f UInt32.TryParse LitUInt32 "u32"
            | UInt64T -> f UInt64.TryParse LitUInt64 "u64"
            | x -> failwithf "Compiler error: Invalid default int type. Got: %A" x
    

    /// ### typecase_validate
    let typecase_validate x _ =
        let metavars = Collections.Generic.HashSet()
        let vars = Collections.Generic.HashSet()
        let errors = ResizeArray()
        let rec f = function
            | RawTFilledNominal _ | RawTTerm _ | RawTTypecase _ -> failwith "Compiler error: This case is not supposed to appear in typecase."
            | RawTForall(r,_,_) -> errors.Add(r,ForallNotAllowedInTypecase)
            | RawTExists(r,_,_) -> errors.Add(r,ExistsNotAllowedInTypecase)
            | RawTLit _ | RawTPrim _ | RawTSymbol _ | RawTB _ | RawTWildcard _ -> ()
            | RawTMetaVar(r,a) -> if vars.Contains(a) then errors.Add(r,MetavarShadowedByVar) else metavars.Add(a) |> ignore
            | RawTVar(r,a) -> if metavars.Contains(a) then errors.Add(r,VarShadowedByMetavar) else vars.Add(a) |> ignore
            | RawTApply(_,a,b) | RawTFun(_,a,b,_) | RawTPair(_,a,b) -> f a; f b
            | RawTLayout(_,a,_) | RawTArray(_,a) -> f a
            | RawTUnion(_,a,_,_) -> Map.iter (fun _ x -> f (snd x)) a
            | RawTRecord(_,a) -> Map.iter (fun _ -> f) a
            | RawTMacro(_,a) -> a |> List.iter (function RawMacroType(_,a) -> f a | _ -> ())
        f x
        if 0 < errors.Count then Error (Seq.toList errors) else Ok(x)
    

    /// ### expr_tight
    // Parses an expression only if it is directly next to the previous one.
    let inline expr_tight next (d: BlockParsingEnv) =
        let i = blockParsingIndex d
        if 0 < i && i < d.tokens.Length then
            let r,r' = snd (fst d.tokens.[i-1]), fst (fst d.tokens.[i])
            if r.line = r'.line && r.character = r'.character then next d else Error []
        else Error []
    

    /// ### read_default_value'
    let inline read_default_value' f d =
        try_current d <| function
            | p, TokDefaultValue t' -> blockParsingSkip d; f (p,t')
            | p, _ -> Error [p, ExpectedLit]
    

    /// ### read_default_value
    let inline read_default_value on_top on_bot d =
        read_default_value' (fun (p,t') ->
            if d.is_top_down then Ok(on_top (p,t'))
            else bottom_up_number d.default_env (p,t') |> Result.map on_bot
            ) d
    

    /// ### read_string
    let read_string = tuple3 skip_string_open ((read_text false |>> snd) <|>% "") skip_string_close
    

    /// ### pat_var
    let pat_var d = (read_small_var' |>> PatVar) d
    

    /// ### pat_list_pair
    let pat_list_pair r a b = PatUnbox(r,"Cons",PatPair(r,a,b))
    

    /// ### root_pattern_var_nominal_union
    let rec root_pattern_var_nominal_union s =
        (read_var' >>= fun (r,a,re) s ->
            if Char.IsUpper(a,0) then
                (opt root_pattern_var |>> fun b ->
                    re SemanticTokenLegend.symbol
                    let b = match b with Some b -> b | None -> PatE r
                    PatUnbox(r,a,b)
                    ) s
            else
                (many (expr_tight read_symbol) >>= fun syms s ->
                    match syms with
                    | [] ->
                        (opt root_pattern_var |>> fun b ->
                            match b with
                            | Some b ->
                                re SemanticTokenLegend.type_variable
                                PatNominal(r +. range_of_pattern b,(r,a),syms,b)
                            | None ->
                                PatVar(r,a)
                            ) s
                    | _ ->
                        (root_pattern_var |>> fun b ->
                            re SemanticTokenLegend.type_variable
                            PatNominal(r +. range_of_pattern b,(r,a),syms,b)
                            ) s
                    ) s
            ) s
    and root_pattern_wildcard d = (skip_keyword' SpecWildcard |>> PatE) d
    and root_pattern_dyn d = (blockParsingRange (skip_unary_op "~" >>. root_pattern_var) |>> PatDyn) d
    and root_pattern_record d =
        let pat_record_item =
            let inj = skip_unary_op "$" >>. read_small_var' |>> fun a -> PatRecordMembersInjectVar,a
            let var = blockParsingRange record_var |>> fun a -> PatRecordMembersSymbol,a
            ((inj <|> var) .>>. (opt (skip_op "=" >>. root_pattern_pair)))
            |>> fun ((f,a),b) -> f (a, defaultArg b (PatVar a))
        (blockParsingRange (curlies (many pat_record_item)) |>> PatRecordMembers) d
    and root_pattern_type s =
        pipe2 root_pattern (opt (skip_op ":" >>. root_type_annot))
            (fun a -> function Some b -> PatAnnot(range_of_pattern a +. range_of_texpr b,a,b) | None -> a) s
    and root_pattern_rounds d =
        (blockParsingRange (rounds ((((read_op' |>> PatVar) <|> root_pattern_type) |>> fun x _ -> x) <|>% PatB))
        |>> fun (r,x) -> x r) d
    and pat_array s = (skip_unary_op ";" >>. blockParsingRange (squares (sepBy root_pattern_type (skip_op ";"))) |>> fun (r,x) -> PatArray(r,x)) s
    and pat_list s =
        (blockParsingRange (squares (sepBy root_pattern_type (skip_op ";")))
        |>> fun ((r,_),x) -> let r = r,r in List.foldBack (pat_list_pair r) x (PatUnbox(r,"Nil",PatB r))) s
    and pat_exists s = (blockParsingRange (pat_exists' .>>. root_pattern) |>> fun (r,(l,b)) -> PatExists(r,l,b)) s
    and root_pattern s =
        let body s =
            let pat_value = (read_value |>> PatValue) <|> (read_default_value PatDefaultValue PatValue)
            let pat_string = read_string |>> (fun (a,x,b) -> PatValue(a +. b,LitString x))
            let pat_symbol = read_symbol |>> PatSymbol
            let (+) = alt (blockParsingIndex s)
            (root_pattern_rounds + root_pattern_var_nominal_union + root_pattern_wildcard + root_pattern_dyn + pat_value + pat_string
            + root_pattern_record + pat_symbol + pat_array + pat_list + pat_exists) s
        let pat_and =
            sepBy1 body (skip_op "&")
            |>> List.reduce (fun a b -> PatAnd(range_of_pattern a +. range_of_pattern b, a, b))
        let pat_cons =
            blockParsingRange (sepBy1 (pat_pair pat_and) (skip_op "::"))
            |>> fun (r,x) -> List.reduceBack (pat_list_pair r) x
        let pat_or =
            sepBy1 pat_cons (skip_op "|")
            |>> List.reduce (fun a b -> PatOr(range_of_pattern a +. range_of_pattern b, a, b))
        let pat_as =
            pat_or .>>. (opt (skip_keyword SpecAs >>. read_small_var'))
            |>> function
                | a, Some (rv,x) -> PatAnd(range_of_pattern a +. rv, a, PatVar(rv,x))
                | a, None        -> a
        let pat_pair = pat_pair pat_as
        pat_pair s
    and root_pattern_when d = (root_pattern .>>. (opt (skip_keyword SpecWhen >>. root_term)) |>> function a, Some b -> PatWhen(range_of_pattern a +. range_of_expr b,a,b) | a, None -> a) d
    and root_pattern_var d =
        let (+) = alt (blockParsingIndex d)
        (pat_var + root_pattern_wildcard + root_pattern_dyn + root_pattern_rounds + root_pattern_record + pat_array + pat_list + pat_exists) d
    and root_pattern_pair d = pat_pair root_pattern_var d
    and root_type_annot d = root_type {root_type_defaults with allow_term=d.is_top_down=false; allow_wildcard=d.is_top_down} d
    and root_type_record (flags : RootTypeFlags) d =
        (blockParsingRange (curlies (sepBy ((blockParsingRange record_var .>> skip_op ":") .>>. root_type flags) (optional (skip_op ";"))))
        >>= fun (r,x) _ ->
            x |> List.map fst |> duplicates DuplicateRecordTypeVar
            |> function [] -> Ok(RawTRecord(r,x |> List.mapi (fun i ((_,n),x) -> (i,n),x) |> Map.ofList)) | er -> Error er
            ) d
    and root_type_union (flags : RootTypeFlags) d =
        let bar = bar (col d)
        let vanilla = skip_op ":" >>. root_type flags |>> fun x -> Some (false, x)
        let gadt =
            skip_op "::"
            >>. pipe2 (opt forall) (root_type flags) (Option.foldBack (List.foldBack (fun a b -> RawTForall(range_of_typevar a +. range_of_texpr b,a,b))))
            |>> fun x -> Some (true, x)
    

        let body = vanilla <|> gadt <|>% None
        (blockParsingRange (optional bar >>. sepBy1 (blockParsingRange read_big_var_as_symbol .>>. body) bar)
        >>= fun (r,x) _ ->
            x |> List.map fst |> duplicates DuplicateUnionKey
            |> function
                | [] -> Ok(r,x |> List.mapi (fun i ((r,n),x) -> (i,n), match x with Some x -> x | None -> false, RawTB r) |> Map.ofList)
                | er -> Error er
            ) d
    and root_type (flags : RootTypeFlags) d =
        let next = root_type flags
        let cases d =
            let wildcard d = if flags.allow_wildcard then (skip_keyword' SpecWildcard |>> RawTWildcard) d else Error []
            // This metavar case only occurs in typecase during the bottom-up segment. It should not be confused with metavars during top-down type inference.
            let metavar d = if flags.allow_typecase_metavars then (skip_unary_op "~" >>. read_var' |>> fun (a,b,r) -> r SemanticTokenLegend.type_variable; RawTMetaVar(a,b)) d else Error []
            let term d = if flags.allow_term then (blockParsingRange (skip_unary_op "`" >>. ((read_var'' |>> rawv) <|> rounds root_term)) |>> RawTTerm) {d with is_top_down=false} else Error []
            let symbol = read_symbol |>> RawTSymbol
            let record = root_type_record flags
            let lit = (read_value |>> RawTLit) <|> (read_string |>> fun (a,b,c) -> RawTLit(a +. c, LitString b))
            let lit_default = read_default_value' (bottom_up_number d.default_env >> Result.map RawTLit)
            let var = read_var' |>> fun (o,x,r) ->
                r SemanticTokenLegend.type_variable
                RawTVar(o, x)
            let rounds =
                blockParsingRange (rounds ((next |>> fun x _ -> x) <|>% RawTB))
                |>> fun (r,x) -> x r
            let macro =
                let read_macro_expression s =
                    (macro_expression MType (root_type root_type_defaults |>> fun x -> RawMacroType(range_of_texpr x,x))
                    <|> macro_expression MTypeLit (root_type root_type_defaults |>> fun x -> RawMacroTypeLit(range_of_texpr x,x))) s
                let body = many ((read_text false |>> RawMacroText) <|> read_macro_type_var <|> read_macro_expression)
                pipe3 skip_macro_open body skip_macro_close (fun a l b -> RawTMacro(a +. b, l))
            let exists = blockParsingRange (exists .>>. root_type flags) |>> fun (r,(l,b)) -> RawTExists(r,l,b)
            let foralls = blockParsingRange (forall .>>. root_type flags) |>> (fun (r,(l,b)) -> List.foldBack (fun a b -> RawTForall(range_of_typevar a +. range_of_texpr b,a,b)) l b)
            let (+) = alt (blockParsingIndex d)
            (rounds + lit + lit_default + wildcard + term + metavar + var + record + symbol + macro + exists + foralls) d
    

        let fold_applies a b = List.fold (fun a b -> RawTApply(range_of_texpr a +. range_of_texpr b,a,b)) a b
        let apply_tight d = pipe2 cases (many (expr_tight cases)) fold_applies d
        let apply d = pipe2 apply_tight (many (blockParsingIndent (col d) (<) apply_tight)) fold_applies d
    

        let pairs = sepBy1 apply (skip_op "*") |>> List.reduceBack (fun a b -> RawTPair(range_of_texpr a +. range_of_texpr b,a,b))
        let functions = sepBy1 pairs (skip_op "->") |>> List.reduceBack (fun a b -> RawTFun(range_of_texpr a +. range_of_texpr b,a,b,FT_Vanilla))
    

        functions d
    

    and root_term d =
        let rec expressions d =
            let next = root_term
            let case_var = read_var'' |>> rawv
            let case_value = read_value |>> RawLit
            let case_exists =
                let sequence_type d = (many (blockParsingIndent (col d) (=) (sepBy1 (root_type root_type_defaults)  (skip_op ";"))) |>> List.concat) d
                ((skip_keyword' SpecExists) .>>. (opt (squares sequence_type)) .>>. next)
                    >>= fun ((r,type_vars),body) d ->
                            if d.is_top_down || Option.isSome type_vars
                            then Ok(RawExists(r +. range_of_expr body, (r, type_vars), body))
                            else Error [r, TypeVarsNeedToBeExplicitForExists]
            let case_rounds =
                let mk_tuple xs =
                    match xs with
                    | []      -> fun r -> RawB r
                    | [x]     -> fun _ -> x
                    | x :: xr ->
                        fun _ ->
                            List.fold (fun a b -> RawPair(range_of_expr a +. range_of_expr b, a, b)) x xr
                blockParsingRange (
                    rounds (
                        sepBy (((read_op' |>> rawv) <|> next)) (skip_op ",")
                        |>> mk_tuple
                    )
                )
                |>> fun (r, build) -> build r
            let case_fun =
                (skip_keyword SpecFun >>. many1 root_pattern_pair .>>. (annotated_body "=>" next root_type_annot))
                >>= fun (pats, body) _ ->
                    match patterns_validate pats with
                    | [] -> List.foldBack (fun pat body -> RawFun(range_of_pattern pat +. range_of_expr body,[pat,body])) pats body |> Ok
                    | ers -> Error ers
    

            let case_forall d =
                if d.is_top_down then Error [] else
                    (tuple3 forall (many root_pattern_pair) (annotated_body "=>" next root_type_annot)
                    >>= fun (foralls : TypeVar list, pats, body) _ ->
                        match patterns_validate pats with
                        | [] ->
                            List.foldBack (fun pat body -> RawFun(range_of_pattern pat +. range_of_expr body,[pat,body])) pats body
                            |> List.foldBack (fun a body -> RawForall(range_of_typevar a +. range_of_expr body,a,body)) foralls |> Ok
                        | ers -> Error ers) d
    

            let case_default_value = read_default_value RawDefaultLit RawLit
            let case_if_then_else d =
                let i = col d
                let inline f' keyword = blockParsingRange (skip_keyword keyword >>. next)
                let inline f keyword = blockParsingIndent i (<=) (f' keyword)
                (pipe4 (f' SpecIf) (f SpecThen) (many (f SpecElif .>>. f SpecThen)) (opt (f SpecElse))
                    (fun cond tr elifs fl ->
                        let f cond tr = function
                            | Some fl -> fst fl, RawIfThenElse(fst cond +. fst fl,snd cond,snd tr,snd fl)
                            | None -> fst tr, RawIfThen(fst cond +. fst tr,snd cond,snd tr)
                        let fl = List.foldBack (fun (cond,tr) fl -> f cond tr fl |> Some) elifs fl
                        f cond tr fl |> snd)) d
    

            let case_match =
                let clauses d =
                    let bar = bar (col d)
                    (optional bar >>. sepBy1 (root_pattern_when .>>. (skip_op "=>" >>. next)) bar
                    >>= fun l _ ->
                        match l |> List.collect (fun (a,_) -> patterns_validate [a]) with
                        | [] -> Ok l
                        | e -> Error e
                        ) d
    

                (blockParsingRange (skip_keyword SpecFunction >>. clauses) |>> RawFun)
                <|> (blockParsingRange ((skip_keyword SpecMatch >>. next .>> skip_keyword SpecWith) .>>. clauses) |>> fun (a,(b,c)) -> RawMatch(a,b,c))
    

            let case_typecase d =
                let clauses d =
                    let bar = bar (col d)
                    let typecase = root_type {root_type_defaults with allow_typecase_metavars=true; allow_wildcard=true} >>= typecase_validate
                    (optional bar >>. sepBy1 (typecase .>>. (skip_op "=>" >>. next)) bar) d
    

                if d.is_top_down then Error [] else
                    (blockParsingRange ((skip_keyword SpecTypecase >>. root_type {root_type_defaults with allow_term=true} .>> skip_keyword SpecWith) .>>. clauses)
                    |>> fun (r, (a, b)) -> RawTypecase(r,a,b)) d
    

            let case_record =
                let create = skip_op "=" >>. next
                let modify = skip_op "#=" >>. next
                let var = blockParsingRange record_var
                let inject = skip_unary_op "$" >>. blockParsingRange read_small_var
                let record_create_body =
                    (var .>>. opt create |>> function (a,Some b) -> RawRecordWithSymbol(a,b) | (a,None) -> RawRecordWithSymbol(a,rawv a))
                    <|> (inject .>>. create |>> RawRecordWithInjectVar)
                let record_create = blockParsingRange (curlies (sepBy record_create_body (optional (skip_op ";")))) |>> fun (r,withs) -> (r,[],withs,[])
                let record_with_bodies =
                    (var >>= fun a ->
                        ((modify |>> fun b -> RawRecordWithSymbolModify(a,b))
                        <|> (opt create |>> function Some b -> RawRecordWithSymbol(a,b) | None -> RawRecordWithSymbol(a,rawv a))))
                    <|> (inject >>= fun a ->
                        ((modify |>> fun b -> RawRecordWithInjectVarModify(a,b))
                        <|> (create |>> fun b -> RawRecordWithInjectVar(a,b))))
                let record_without_bodies = (var |>> RawRecordWithoutSymbol) <|> (inject |>> RawRecordWithoutInjectVar)
                let record_with =
                    blockParsingRange
                        (curlies
                            (tuple4 read_small_var'
                                (many ((read_symbol |>> RawSymbol) <|> (skip_op "$" >>. read_small_var' |>> rawv)))
                                ((skip_keyword SpecWith >>. sepBy record_with_bodies (optional (skip_op ";"))) <|>% [])
                                ((skip_keyword SpecWithout >>. many record_without_bodies) <|>% [])))
                    |>> fun (r,(name, acs, withs, withouts)) -> (r,rawv name :: acs,withs,withouts)
    

                restore 2 record_create <|> record_with
                >>= fun (_,_,withs,withouts as x) _ ->
                    [
                    withs |> List.choose (function RawRecordWithSymbol(a,_) | RawRecordWithSymbolModify(a,_) -> Some a | _ -> None) |> duplicates DuplicateTermRecordSymbol
                    withs |> List.choose (function RawRecordWithInjectVar(a,_) | RawRecordWithInjectVarModify(a,_) -> Some a | _ -> None) |> duplicates DuplicateTermRecordInjection
                    withouts |> List.choose (function RawRecordWithoutSymbol(a,b) -> Some(a,b) | _ -> None) |> duplicates DuplicateTermRecordSymbol
                    withouts |> List.choose (function RawRecordWithoutInjectVar(a,b) -> Some(a,b) | _ -> None) |> duplicates DuplicateTermRecordInjection
                    ] |> List.concat |> function [] -> Ok(RawRecordWith x) | er -> Error er
    

            let case_join_point = skip_keyword SpecJoin >>. next |>> join_point true None
            let case_join_point_backend = skip_keyword SpecJoinBackend >>. (read_big_var_as_keyword .>>. next) |>> join_point_backend
            let case_real = skip_keyword SpecReal >>. (fun d -> next {d with is_top_down=false}) |>> fun x -> RawReal(range_of_expr x,x)
            let case_symbol = read_symbol |>> RawSymbol
            let case_list = blockParsingRange (squares sequence_body) >>= fun (r,l) d ->
                if d.is_top_down then
                    let r = fst r, fst r
                    List.foldBack (fun a b ->
                        RawApply(r,rawv(r,unintern "Cons"),RawPair(r,a,b))
                        ) l (rawv(r,unintern "Nil")) |> Ok
                else
                    Error [r, ListLiteralsNotAllowedInBottomUp]
    

            let case_string = read_string |>> fun (a, x, b) -> RawLit(a +. b,LitString x)
    

            let case_macro =
                let read_macro_expression s =
                    (macro_expression MTerm (root_term |>> fun x -> RawMacroTerm(range_of_expr x,x,false))
                    <|> macro_expression MTermInline (root_term |>> fun x -> RawMacroTerm(range_of_expr x,x,true))
                    <|> macro_expression MType (root_type root_type_defaults |>> fun x -> RawMacroType(range_of_texpr x,x))
                    <|> macro_expression MTypeLit (root_type root_type_defaults |>> fun x -> RawMacroTypeLit(range_of_texpr x,x))) s
                let body = many ((read_text true |>> RawMacroText) <|> read_macro_var <|> read_macro_expression)
                pipe3 skip_macro_open body skip_macro_close (fun a l b -> RawMacro(a +. b, l))
    

            let (+) = alt (blockParsingIndex d)
    

            (case_value + case_default_value + case_var + case_join_point + case_join_point_backend + case_real + case_symbol
            + case_typecase + case_match + case_typecase + case_rounds + case_list + case_record
            + case_if_then_else + case_fun + case_forall + case_string + case_macro + case_exists) d
    

        and application_tight d =
            let next = expressions
            pipe2 next (many (expr_tight next)) (List.fold (fun a b -> RawApply(range_of_expr a +. range_of_expr b,a,b))) d
    

        and sequence_body d = (many (blockParsingIndent (col d) (=) (sepBy1 operators (skip_op ";"))) |>> List.concat) d
        and unary_op d =
            let next = application_tight
            let f =
                read_unary_op' >>= fun (o,a) d ->
                    let type_expr d =
                        choice [|
                            read_small_type_var' |>> RawTVar
                            read_value |>> RawTLit
                            read_string |>> fun (a,b,c) -> RawTLit(a +. c, LitString b)
                            rounds (root_type {root_type_defaults with allow_term=true})
                            |] d
                    let term_expr d =
                        choice [|
                            read_var'' |>> rawv
                            read_value |>> RawLit
                            read_default_value RawDefaultLit RawLit
                            read_string |>> fun (a,b,c) -> RawLit(a +. c, LitString b)
                            rounds root_term
                            |] d
                    match a with
                    | ";" ->
                        if d.is_top_down then (blockParsingRange (squares sequence_body) |>> fun (r,x) -> RawApply(o,RawV(o,unintern "array",true), RawArray(o,x))) d
                        else Error [o, ArrayLiteralsNotAllowedInBottomUp]
                    | "!!!!" ->
                        (blockParsingRange (read_big_var .>>. (rounds (sepBy (fun d -> unary_op {d with is_top_down=false}) (skip_op ","))))
                        >>= fun (r,((ra,a), b)) _ ->
                            match string_to_op a with
                            | true, op' -> Ok(RawOp(r,op',b))
                            | false, _ -> Error [ra,InbuiltOpNotFound]) d
                    | "`" -> if d.is_top_down then Error [] else (blockParsingRange type_expr |>> RawType) d
                    | "`@" ->
                        if d.is_top_down then Error [] else
                            (blockParsingRange term_expr |>> fun (r,x) ->
                                let r' = o +. r
                                RawType(r', RawTTerm(r',RawOp(r',LitToTypeLit,[x])))
                                ) d
                    | "``" -> if d.is_top_down then Error [] else (blockParsingRange type_expr |>> fun (r,x) -> RawOp(o +. r,TypeToVar,[RawType(r,x)])) d
                    | "`$" -> (read_var'' |>> fun (r,x) -> RawV(r,x,false)) d
                    | _ -> (next |>> fun b -> RawApply(o +. range_of_expr b,rawv(o, "~" + a),b)) d
            (f <|> next) d
    

        and application (d: BlockParsingEnv) =
            let next = unary_op
            pipe2 next (many (blockParsingIndent (col d) (<) next)) (List.fold (fun a b -> RawApply(range_of_expr a +. range_of_expr b,a,b))) d
    

        and operators d =
            let term = application
            let i = col d
            let op = blockParsingIndent i (<=) op
    

            /// Pratt parser
            let rec led left (prec,asoc,m) d =
                match asoc with
                | Associativity.Right -> (tdop (prec-1) |>> fun right -> m (left, right)) d
                | _ -> (tdop prec |>> fun right -> m (left, right)) d
    

            and tdop rbp d =
                let rec loop left d =
                    ((op >>= fun (prec,_,_ as v) d ->
                        if rbp < prec then (led left v >>= loop) d
                        else skip' d -1; Error []) <|>% left) d
                (term >>= loop) d
    

            pipe2 (tdop Int32.MinValue)
                (opt (blockParsingIndent i (<=) (skip_op ":" >>. root_type_annot)))
                (fun a -> function Some b -> RawAnnot(range_of_expr a +. range_of_texpr b,a,b) | _ -> a)
                d
    

        let statements d =
            let next = operators
            let inl_or_let =
                (inl_or_let root_term root_pattern_pair root_type_annot .>>. many (and_inl_or_let root_term root_pattern_pair root_type_annot))
                >>= fun x _ ->
                    match x with
                    | ((r,name,body),false), [] -> Ok(fun on_succ -> RawMatch(r,body,[name,on_succ]))
                    | ((_,_,_),false), l -> l |> List.map (fun ((r,_,_),_) -> r, UnexpectedAndInlRec) |> Error
                    | x, xs ->
                        let l = x :: xs |> List.map (function
                            | (r,PatVar(o,name),body),true -> r, ((o,name), body)
                            | _ -> failwith "Compiler error: Recursive inl/let statements should always have PatVar for names and should always be recursive."
                            )
                        let r = l |> List.map fst |> List.reduce (+.)
                        l |> List.map (snd >> fst)
                        |> duplicates DuplicateRecFunctionName
                        |> function [] -> Ok(fun on_succ -> RawRecBlock(r, List.map snd l, on_succ)) | er -> Error er
            let module_open = blockParsingModule_open |>> fun (r,(name,acs)) on_succ -> RawOpen(r,name,acs,on_succ)
            let statement_parsers d =
                let (+) = alt (blockParsingIndex d)
                (inl_or_let + module_open) d
    

            let i = col d
            let inline if_ x = blockParsingIndent i x
            let stmts =
                many1 (if_ (=) (blockParsingRange statement_parsers))
                .>>. opt ((if_ (<=) (skip_keyword SpecIn) >>. root_term) <|> if_ (=) next)
                >>= fun (a,b) _ ->
                    match b with
                    | Some b -> Ok(a,b)
                    | None ->
                        let r = List.last a |> fst
                        Ok (a, RawB r)
            let expr = if_ (=) next |>> fun x -> [],x
            (many1 (stmts <|> expr)
            |>> fun x ->
                List.foldBack (fun (stmts,expr) s ->
                    let process_statements s = List.foldBack (fun (_,a) b -> a b) stmts s
                    match s with
                    | ValueNone -> ValueSome (process_statements expr)
                    | ValueSome expr' -> ValueSome (process_statements (RawSeq(range_of_expr expr +. range_of_expr expr',expr,expr')))
                    ) x ValueNone |> ValueOption.get
                ) d
    

        statements d
    

    /// ### comments
    let comments (s : BlockParsingEnv) =
        let line_near_to = lineBlockParsing s
        let rec loop line d =
            if 0 <= line then
                match s.comments.[line] with
                | Some(r,text) ->
                    let text = text.TrimEnd()
                    loop (line-1) ((if text = "" then "\n" else text + " ") :: d)
                | _ -> d
            else d
        loop (line_near_to-1) []
        |> String.concat ""
        |> fun x -> Ok(x.TrimEnd())
    

    /// ### Comments
    type Comments = string
    

    /// ### TopStatement
    type [<ReferenceEquality>] TopStatement =
        | TopAnd of VSCRange * TopStatement
        | TopInl of Comments * VSCRange * (VSCRange * VarString) * RawExpr * is_top_down: bool
        | TopRecInl of Comments * VSCRange * (VSCRange * VarString) * RawExpr * is_top_down: bool
        | TopNominal of VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr
        | TopNominalRec of VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr
        | TopType of VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr
        | TopPrototype of Comments * VSCRange * (VSCRange * VarString) * (VSCRange * VarString) * TypeVar list * RawTExpr
        | TopInstance of VSCRange * (VSCRange * VarString) * (VSCRange * VarString) * TypeVar list * RawExpr
        | TopOpen of VSCRange * (VSCRange * VarString) * (VSCRange * SymbolString) list
    

    /// ### top_inl_or_let_process
    let top_inl_or_let_process comments is_top_down = function
        | (r,PatVar(r',name),body),is_rec ->
            let rec loop = function
                | RawAnnot(r,body,t) -> loop body
                | RawForall _ | RawFun _ ->
                    if is_rec then Ok(TopRecInl(comments,r,(r',name),body,is_top_down))
                    else Ok(TopInl(comments,r,(r',name),body,is_top_down))
                | _ -> Error [r, ExpectedGlobalFunction]
            loop body
        | (_,x,_),_ -> Error [range_of_pattern x, ExpectedVarOrOpAsNameOfGlobalStatement]
    

    /// ### top_inl_or_let
    let top_inl_or_let d = ((comments .>>. inl_or_let root_term root_pattern_pair root_type_annot) >>= fun (comments,x) d -> top_inl_or_let_process comments d.is_top_down x) d
    

    /// ### process_union
    let process_union (r,(layout,n,a,(r',b))) _ =
        let this = (RawTVar n,a) ||> List.fold (fun s x -> RawTApply(r',s,RawTVar(r',hovar_name x)))
        match layout with
        | UHeap -> Ok(TopNominalRec(r,n,a,RawTUnion(r',b,layout,this)))
        | UStack -> Ok(TopNominal(r,n,a,RawTUnion(r',b,layout,this)))
    

    /// ### union_clauses
    let union_clauses d = root_type_union root_type_defaults d
    

    /// ### top_union
    let top_union d = ((blockParsingRange (tuple4 (skip_keyword SpecUnion >>. ((skip_keyword SpecRec >>% UHeap) <|>% UStack)) read_small_type_var' (many ho_var .>> skip_op "=") union_clauses)) >>= process_union) d
    

    /// ### top_nominal
    let top_nominal d =
        (blockParsingRange (tuple3 (skip_keyword SpecNominal >>. read_small_type_var') (many ho_var .>> skip_op "=") (root_type {root_type_defaults with allow_term=true}))
        |>> fun (r,(n,a,b)) -> TopNominal(r,n,a,b)) d
    

    /// ### type_forall
    let inline type_forall next d = (pipe2 (forall <|>% []) next (List.foldBack (fun x s -> RawTForall(range_of_typevar x +. range_of_texpr s,x,s)))) d
    

    /// ### top_prototype
    let top_prototype d =
        (blockParsingRange
            (tuple5 comments
                (skip_keyword SpecPrototype >>. (read_small_var' <|> rounds read_op')) read_small_type_var' (many forall_var)
                (skip_op ":" >>. type_forall (root_type root_type_defaults)))
        |>> fun (r,(com,a,b,c,d)) -> TopPrototype(com,r,a,b,c,d)) d
    

    /// ### top_instance
    let top_instance d =
        (blockParsingRange
            (tuple4 (skip_keyword SpecInstance >>. (read_small_var' <|> rounds read_op')) read_small_type_var' (many forall_var) (skip_op "=" >>. root_term))
        >>= fun (r,(prototype_name, nominal_name, nominal_foralls, body)) _ ->
                Ok(TopInstance(r,prototype_name,nominal_name,nominal_foralls,body))
                ) d
    

    /// ### top_type
    let top_type d = (blockParsingRange (tuple3 (skip_keyword SpecType >>. read_small_type_var') (many ho_var) (skip_op "=" >>. root_type root_type_defaults)) |>> fun (r,(a,b,c)) -> TopType(r,a,b,c)) d
    

    /// ### top_and_inl_or_let
    let top_and_inl_or_let d =
        (comments .>>. restore 1 (blockParsingRange (and_inl_or_let root_term root_pattern_pair root_type_annot))
        >>= fun (comments,(r,x)) d -> top_inl_or_let_process comments d.is_top_down x |> Result.map (fun x -> TopAnd(r,x))) d
    

    /// ### top_and
    let inline top_and f = restore 1 (blockParsingRange (skip_keyword SpecAnd >>. f)) |>> TopAnd
    

    /// ### top_and_union
    let top_and_union d = top_and ((blockParsingRange (tuple4 (skip_keyword SpecUnion >>% UHeap) read_small_type_var' (many ho_var .>> skip_op "=") union_clauses)) >>= process_union) d
    

    /// ### top_open
    let top_open d = (blockParsingModule_open |>> fun (r,(name,acs)) -> TopOpen(r,name,acs)) d
    

    /// ### top_statement
    let top_statement s =
        let (+) = alt (blockParsingIndex s)
        (top_inl_or_let + top_union + top_nominal + top_prototype + top_type + top_instance + top_and_inl_or_let + top_and_union + top_open) s
    

    /// ### ParserErrorsList
    type ParserErrorsList = (VSCRange * ParserErrors) list
    

    /// ### ParseResult
    type ParseResult = Result<TopStatement,ParserErrorsList>
    

    /// ### blockParsingParse
    let blockParsingParse (s : BlockParsingEnv) : ParseResult =
        if 0 < s.tokens.Length then
            match top_statement s with
            | Ok _ as x -> if s.Index = s.tokens.Length then x else Error [fst s.tokens.[s.Index], ExpectedEob]
            | Error [] ->
                if s.Index = s.tokens.Length then Error [fst (Array.last s.tokens), UnexpectedEob]
                else Error [fst s.tokens.[s.Index], ExpectedEob]
            | Error _ as l -> l
        else
            Error []
    

    /// ### show_parser_error
    let show_parser_error = function
        | TypeVarsNeedToBeExplicitForExists -> "The type vars for the exists body have to be specified up front in the bottom-up segment."
        | DuplicateExistsVar -> "Duplicate variable in the exists type."
        | ExistsNotAllowedInTypecase -> "The existential type is not allowed in typecase."
        | ForallNotAllowedInTypecase -> "The type lambda is not allowed in typecase."
        | MetavarShadowedByVar -> "The metavariable is shadowed by a variable."
        | VarShadowedByMetavar -> "The variable is shadowed by a metavariable."
        | ExpectedPairedSymbolInUnion -> "The union clause should be pair whose left side is a symbol."
        | ExpectedEscapedChar false -> "escaped character"
        | ExpectedEscapedChar true -> "escaped character or the escaped variable (\\v)"
        | ExpectedUnescapedChar -> "unescaped character"
        | ExpectedMacroVar -> "variable"
        | ExpectedMacroTypeVar -> "type variable"
        | ExpectedMacroTypeLitVar -> "type literal variable"
        | ExpectedText -> "text"
        | ExpectedMacroOpen -> "$\""
        | ExpectedStringOpen -> "\""
        | ExpectedMacroClose | ExpectedStringClose -> "\""
        | ExpectedKeyword x ->
            match x with
            | SpecExists -> "exists"
            | SpecIn -> "in"
            | SpecAnd -> "and"
            | SpecFun -> "fun"
            | SpecMatch -> "match"
            | SpecTypecase -> "typecase"
            | SpecFunction -> "function"
            | SpecWith -> "with"
            | SpecWithout -> "without"
            | SpecAs -> "as"
            | SpecWhen -> "when"
            | SpecInl -> "inl"
            | SpecLet -> "let"
            | SpecForall -> "forall"
            | SpecInm -> "inm"
            | SpecInb -> "inb"
            | SpecRec -> "rec"
            | SpecIf -> "if"
            | SpecThen -> "then"
            | SpecElif -> "elif"
            | SpecElse -> "else"
            | SpecJoin -> "join"
            | SpecJoinBackend -> "join_backend"
            | SpecType -> "type"
            | SpecNominal -> "nominal"
            | SpecReal -> "real"
            | SpecUnion -> "union"
            | SpecOpen -> "open"
            | SpecWildcard -> "_"
            | SpecInstance -> "instance"
            | SpecPrototype -> "prototype"
        | ExpectedParenthesis(Round,Open) -> "("
        | ExpectedParenthesis(Curly,Open) -> "{"
        | ExpectedParenthesis(Square,Open) -> "["
        | ExpectedParenthesis(Round,Close) -> ")"
        | ExpectedParenthesis(Curly,Close) -> "}"
        | ExpectedParenthesis(Square,Close) -> "]"
        | ExpectedMacroExpression(MTerm,Open) -> "`("
        | ExpectedMacroExpression(MType,Open) -> "!("
        | ExpectedMacroExpression(MTypeLit,Open) -> "@("
        | ExpectedMacroExpression(MTermInline,Open) -> "#("
        | ExpectedMacroExpression((MTerm | MTermInline | MType | MTypeLit),Close) -> ")"
        | ExpectedOpenParenthesis -> "(, { or ["
        | ExpectedOperator' -> "operator"
        | ExpectedOperator x -> x
        | ExpectedUnaryOperator' -> "unary operator"
        | ExpectedUnaryOperator x -> x
        | ExpectedUnit -> "()"
        | ExpectedSmallVar -> "lowercase variable"
        | ExpectedBigVar -> "uppercase variable"
        | ExpectedVar -> "variable"
        | ExpectedLit -> "literal"
        | ExpectedSymbol -> "symbol"
        | ExpectedSymbolPaired -> "paired symbol"
        | ExpectedStatement -> "statement"
        | ExpectedFunctionAsBodyOfRecStatement -> "Rec statements should all return functions known at parse time."
        | ExpectedGlobalFunction -> "Global inl/let statements should all return functions known at parse time."
        | ExpectedSinglePatternWhenStatementNameIsNorVarOrOp -> "Unexpected pattern."
        | ExpectedVarOrOpAsNameOfGlobalStatement -> "The first pattern of a global statement should either be a variable or compile down to it."
        | ExpectedVarOrOpAsNameOfRecStatement -> "The first pattern of a recursive statement should either be a variable or compile down to it."
        | ExpectedExpression -> "A sequence of statements should end in an expression."
        | InbuiltOpNotFound -> "Not found among the inbuilt operations."
        | UnknownOperator -> "Operator does not have known precedence and associativity."
        | ForallNotAllowed -> "Forall not allowed here."
        | InvalidPattern DisjointOrPatternVar -> "Both branches of an or pattern need to have the same variables. This one is disjoint."
        | InvalidPattern DuplicateTermVar -> "Duplicate term variable in pattern."
        | InvalidPattern DuplicateTypeVar -> "Duplicate type variable in pattern."
        | InvalidPattern ShadowedVar -> "Shadowed pattern variable."
        | MetavarNotAllowed -> "Metavariable is not allowed here."
        | SymbolPairedShouldStartWithUppercaseInTypeScope -> "Paired symbol should start with uppercase in type scope."
        | TermNotAllowed -> "The term is not allowed here."
        | TypecaseNotAllowed -> "Typecase is not allowed here."
        | UnexpectedAndInlRec -> "The first statement of a recursive block has to be marked as recursive."
        | ExpectedEob -> "Failed to parse this token."
        | UnexpectedEob -> "Unexpected end of block past this token."
        | UnknownError -> "Compiler error: Parsing failed at this position with no error message and without consuming all the tokens in a block."
        | DuplicateRecordTypeVar -> "Duplicate record type variable."
        | DuplicateForallVar -> "Duplicate forall variable."
        | DuplicateConstraint -> "Duplicate constraint."
        | InvalidPattern DuplicateRecordSymbol
        | DuplicateTermRecordSymbol -> "Duplicate record symbol."
        | InvalidPattern DuplicateRecordInjection
        | DuplicateTermRecordInjection -> "Duplicate record injection."
        | DuplicateRecFunctionName -> "Shadowing of functions by the members of the same mutually recursive block is not allowed."
        | BottomUpNumberParseError (x, val_dsc) -> sprintf "The string %s cannot be safely parsed as %s." x val_dsc
        | DuplicateUnionKey -> "Duplicate union keys are not allowed."
        | ListLiteralsNotAllowedInBottomUp -> "List literals are not allowed in the bottom-up segment."
        | ArrayLiteralsNotAllowedInBottomUp -> "Array literals are not allowed in the bottom-up segment."
    

    module HopacExtensions =
        /// ## HopacExtensions
        open Hopac
        open Hopac.Infixes
    

        let (>>**) x f =
            if x |> Hopac.Promise.Now.isFulfilled
            then x |> Hopac.Promise.Now.get |> f
            else Hopac.Infixes.(>>=*) x f
        // Runtime Hopac re-export e utilitários base (definir antes de uso para evitar FS0039).
        open System.Threading.Tasks
    

        let inline start (j: Job<unit>) = Hopac.start j
        let inline queue (j: Job<unit>) = Hopac.queue j
        let inline server x = Hopac.server x
        let inline run (j: Job<'a>) : 'a = Hopac.run j
        let inline startAsTask (j: Job<'a>) : Task<'a> = Hopac.startAsTask j
        let inline queueAsTask (j: Job<'a>) : Task<'a> = Hopac.queueAsTask j
    

        let inline awaitUnitTask (t: Task) : Job<unit> = Hopac.Job.awaitUnitTask t
        let inline awaitTask (t: Task<'a>) : Job<'a> = Job.fromAsync (Async.AwaitTask t)
    

        // Sleep/timeout como Job, para remover Async.Sleep e Alt ambiguo do resto do arquivo.
        let inline sleepMs (ms: int) : Job<unit> = awaitUnitTask (Task.Delay ms)

        // Concurrency override hook (wired later in module)
        // - default is 0 (no cap)
        // - forceConcurrency updates the backing store; this hook lets earlier helpers respect it
        let mutable private getForcedConcurrency : unit -> int = fun () -> 0

        let inline private capConcurrency (requested: int) : int =
            let req = max 1 requested
            let forced = getForcedConcurrency()
            if forced > 0 then min forced req else req

    
    


        /// ## BlockBundling
        open Hopac.Extensions
        open Hopac.Stream
        /// Run a Hopac Job/Alt with a timeout (ms), returning None on timeout.
        /// Implemented via Tasks to avoid Alt/Job operator overload pitfalls.
        let jobWithTimeoutMs (timeoutMs: int) (work: Job<'a>) : Job<'a option> = job {
            let workT = startAsTask work
            let timeoutT = System.Threading.Tasks.Task.Delay timeoutMs
            let! completed = System.Threading.Tasks.Task.WhenAny(workT :> System.Threading.Tasks.Task, timeoutT)
            if obj.ReferenceEquals(completed, (workT :> System.Threading.Tasks.Task)) then
                let! r = workT
                return Some r
            else
                return None
        }


        // ALPHA1471: Hopac-native migration scaffold.
        // This module is deliberately small and side-effect-free except for constructing
        // Hopac primitives. It gives the next migration rounds typed contracts for the
        // three architectural fronts named in the assessment: IVar cells, actor-owned
        // generation cache, and cooperative timeout/poison policy.  It does not replace
        // the evaluator yet and never manufactures semantic/root/write/build evidence.
        module NativeHopacMigration =
            type NativeHopacMigrationPhaseId =
                | NativeHopacMigrationInventory
                | NativeHopacMigrationCellIvarBridge
                | NativeHopacMigrationActorCacheBridge
                | NativeHopacMigrationJobCompositionBridge
                | NativeHopacMigrationAltTimeoutBridge
                | NativeHopacMigrationSchedulerHandover

            let nativeHopacMigrationPhaseText = function
                | NativeHopacMigrationInventory -> "inventory"
                | NativeHopacMigrationCellIvarBridge -> "cell_ivar_bridge"
                | NativeHopacMigrationActorCacheBridge -> "actor_cache_bridge"
                | NativeHopacMigrationJobCompositionBridge -> "job_composition_bridge"
                | NativeHopacMigrationAltTimeoutBridge -> "alt_timeout_bridge"
                | NativeHopacMigrationSchedulerHandover -> "scheduler_handover"

            type NativeHopacReadinessId =
                | NativeHopacReadinessLegacyBlocking
                | NativeHopacReadinessHybridBridge
                | NativeHopacReadinessNativeHopacCandidate
                | NativeHopacReadinessNativeHopacRequiredBeforeSota

            let nativeHopacReadinessText = function
                | NativeHopacReadinessLegacyBlocking -> "legacy_blocking"
                | NativeHopacReadinessHybridBridge -> "hybrid_bridge"
                | NativeHopacReadinessNativeHopacCandidate -> "native_hopac_candidate"
                | NativeHopacReadinessNativeHopacRequiredBeforeSota -> "native_hopac_required_before_sota"

            type NativeHopacWaitPrimitiveId =
                | NativeWaitManualResetEventSlimLegacy
                | NativeWaitSpinYieldLegacy
                | NativeWaitIvarRead
                | NativeWaitPromiseRead
                | NativeWaitAltChooseTimeout

            let nativeHopacWaitPrimitiveText = function
                | NativeWaitManualResetEventSlimLegacy -> "manual_reset_event_slim_legacy"
                | NativeWaitSpinYieldLegacy -> "spin_yield_legacy"
                | NativeWaitIvarRead -> "ivar_read"
                | NativeWaitPromiseRead -> "promise_read"
                | NativeWaitAltChooseTimeout -> "alt_choose_timeout"

            type NativeHopacCellStateId =
                | NativeCellCreated
                | NativeCellAwaitingProducer
                | NativeCellFulfilled
                | NativeCellPoisoned
                | NativeCellGenerationInvalidated

            let nativeHopacCellStateText = function
                | NativeCellCreated -> "created"
                | NativeCellAwaitingProducer -> "awaiting_producer"
                | NativeCellFulfilled -> "fulfilled"
                | NativeCellPoisoned -> "poisoned"
                | NativeCellGenerationInvalidated -> "generation_invalidated"

            type NativeHopacCacheOwnerId =
                | NativeCacheConcurrentDictionaryLegacy
                | NativeCacheActorOwned
                | NativeCacheGenerationOwner
                | NativeCacheSidecarPrefetchOwner

            let nativeHopacCacheOwnerText = function
                | NativeCacheConcurrentDictionaryLegacy -> "concurrent_dictionary_legacy"
                | NativeCacheActorOwned -> "actor_owned"
                | NativeCacheGenerationOwner -> "generation_owner"
                | NativeCacheSidecarPrefetchOwner -> "sidecar_prefetch_owner"

            type NativeHopacGenerationPolicyId =
                | NativeGenerationObserveOnly
                | NativeGenerationInvalidateByActor
                | NativeGenerationReplayWaiters
                | NativeGenerationPoisonStaleWaiters

            let nativeHopacGenerationPolicyText = function
                | NativeGenerationObserveOnly -> "observe_only"
                | NativeGenerationInvalidateByActor -> "invalidate_by_actor"
                | NativeGenerationReplayWaiters -> "replay_waiters"
                | NativeGenerationPoisonStaleWaiters -> "poison_stale_waiters"

            type NativeHopacTimeoutPolicyId =
                | NativeTimeoutLegacyMetronome
                | NativeTimeoutAltChooseProbe
                | NativeTimeoutAltChooseHardPoison
                | NativeTimeoutNoGlobalAbortAuthority

            let nativeHopacTimeoutPolicyText = function
                | NativeTimeoutLegacyMetronome -> "legacy_metronome"
                | NativeTimeoutAltChooseProbe -> "alt_choose_probe"
                | NativeTimeoutAltChooseHardPoison -> "alt_choose_hard_poison"
                | NativeTimeoutNoGlobalAbortAuthority -> "no_global_abort_authority"

            type NativeHopacWorklistPolicyId =
                | NativeWorklistLegacyQueueProbation
                | NativeWorklistJobCompositionCandidate
                | NativeWorklistAwaitDependencyIvar
                | NativeWorklistActorRoutedDependency

            let nativeHopacWorklistPolicyText = function
                | NativeWorklistLegacyQueueProbation -> "legacy_queue_probation"
                | NativeWorklistJobCompositionCandidate -> "job_composition_candidate"
                | NativeWorklistAwaitDependencyIvar -> "await_dependency_ivar"
                | NativeWorklistActorRoutedDependency -> "actor_routed_dependency"

            type NativeHopacCacheMsg<'k,'v> =
                | NativeCacheGet of key: 'k * reply: IVar<'v option>
                | NativeCachePut of key: 'k * value: 'v
                | NativeCacheInvalidateGeneration of generation: int64 * policy: NativeHopacGenerationPolicyId
                | NativeCacheMissingDependency of key: 'k * reply: IVar<string>
                | NativeCacheSnapshot of reply: IVar<int * int64>

            type NativeHopacCell<'a> = {
                result: IVar<'a>
                state: NativeHopacCellStateId
                wait_primitive: NativeHopacWaitPrimitiveId
                owner: NativeHopacCacheOwnerId
            }

            let createIvarCell<'a> () : NativeHopacCell<'a> =
                { result = IVar()
                  state = NativeCellCreated
                  wait_primitive = NativeWaitIvarRead
                  owner = NativeCacheActorOwned }

            let createCacheChannel<'k,'v> () : Ch<NativeHopacCacheMsg<'k,'v>> =
                Ch()

            // ALPHA1552: typed native-Hopac obligation model.
            // This is the next destructive-but-shadowed migration seam requested by the assessments:
            // replace raw replay-key strings and driver while-loops with kind-tagged obligations whose
            // reply cell and timeout budget travel with the work item.  It deliberately remains a
            // typed scaffold: no semantic value, root proof, writer witness, or BuildOk is fabricated here.
            type NativeTermKind =
                | NativeTermKind
            type NativeTyKind =
                | NativeTyKind

            [<Struct>]
            type NativeNodeId<'Kind> = NativeNodeId of int

            let nativeNodeIdValue (NativeNodeId value) = value

            type NativeReplayDriverKindId =
                | NativeReplayDriverTerm
                | NativeReplayDriverTy
                | NativeReplayDriverCrossKind

            let nativeReplayDriverKindText = function
                | NativeReplayDriverTerm -> "term"
                | NativeReplayDriverTy -> "ty"
                | NativeReplayDriverCrossKind -> "cross_kind"

            type NativeReplayShapeId =
                | NativeReplayShapeApply
                | NativeReplayShapeFunctionBody
                | NativeReplayShapeRecordKey
                | NativeReplayShapeParentHandoff
                | NativeReplayShapeContinuationCell
                | NativeReplayShapeDeferredChild
                | NativeReplayShapeUnknown

            let nativeReplayShapeText = function
                | NativeReplayShapeApply -> "apply"
                | NativeReplayShapeFunctionBody -> "function_body"
                | NativeReplayShapeRecordKey -> "record_key"
                | NativeReplayShapeParentHandoff -> "parent_handoff"
                | NativeReplayShapeContinuationCell -> "continuation_cell"
                | NativeReplayShapeDeferredChild -> "deferred_child"
                | NativeReplayShapeUnknown -> "unknown"

            type NativeReplayKey<'Kind> =
                | NativeApplyArg of node: NativeNodeId<'Kind> * index: int
                | NativeFunctionBody of node: NativeNodeId<'Kind>
                | NativeRecordKey of name: string * node: NativeNodeId<'Kind>
                | NativeParentHandoff of node: NativeNodeId<'Kind>
                | NativeContinuationCell of owner: NativeNodeId<'Kind> * child: NativeNodeId<'Kind>
                | NativeDeferredChildCell of owner: NativeNodeId<'Kind> * child: NativeNodeId<'Kind>

            let nativeReplayKeyShape = function
                | NativeApplyArg _ -> NativeReplayShapeApply
                | NativeFunctionBody _ -> NativeReplayShapeFunctionBody
                | NativeRecordKey _ -> NativeReplayShapeRecordKey
                | NativeParentHandoff _ -> NativeReplayShapeParentHandoff
                | NativeContinuationCell _ -> NativeReplayShapeContinuationCell
                | NativeDeferredChildCell _ -> NativeReplayShapeDeferredChild

            let nativeReplayKeyText renderKind key =
                let nodeText n = nativeNodeIdValue n |> string
                match key with
                | NativeApplyArg(node,index) -> sprintf "%s:EApply(%s).arg%d" (renderKind()) (nodeText node) index
                | NativeFunctionBody node -> sprintf "%s:FunctionBody(%s)" (renderKind()) (nodeText node)
                | NativeRecordKey(name,node) -> sprintf "%s:RecordKey(%s,%s)" (renderKind()) name (nodeText node)
                | NativeParentHandoff node -> sprintf "%s:ParentHandoff(%s)" (renderKind()) (nodeText node)
                | NativeContinuationCell(owner,child) -> sprintf "%s:ContinuationCell(owner=%s,child=%s)" (renderKind()) (nodeText owner) (nodeText child)
                | NativeDeferredChildCell(owner,child) -> sprintf "%s:DeferredChildCell(owner=%s,child=%s)" (renderKind()) (nodeText owner) (nodeText child)

            type NativeErasedReplayKey =
                | NativeErasedTermKey of NativeReplayKey<NativeTermKind>
                | NativeErasedTyKey of NativeReplayKey<NativeTyKind>

            let nativeErasedReplayKeyText = function
                | NativeErasedTermKey key -> nativeReplayKeyText (fun () -> "term") key
                | NativeErasedTyKey key -> nativeReplayKeyText (fun () -> "ty") key

            type NativeSemanticShadowResult<'Kind> = {
                key: NativeReplayKey<'Kind>
                generation: int64
                evidence: string
                authority: NativeHopacReadinessId
            }

            type NativeEvaluationObligation =
                | NativeTermObligation of NativeReplayKey<NativeTermKind> * IVar<Result<NativeSemanticShadowResult<NativeTermKind>,string>>
                | NativeTyObligation of NativeReplayKey<NativeTyKind> * IVar<Result<NativeSemanticShadowResult<NativeTyKind>,string>>

            let nativeEvaluationObligationKey = function
                | NativeTermObligation(key,_) -> NativeErasedTermKey key
                | NativeTyObligation(key,_) -> NativeErasedTyKey key

            // ALPHA1583: assessment-mandated existential proof envelope.
            // The mailbox still has one erased shape, but each case pins the key kind, terminal
            // payload, and IVar return witness together.  This prevents the next cutover from
            // routing a term frontier through a ty payload by string accident while staying
            // shadow-only/no-fabrication.
            type NativeTerminalPayloadWitness<'Kind> = {
                key: NativeReplayKey<'Kind>
                terminal: string
                ivar_edge: string
                terminal_commit_class_du: string
                dispatch_outcome_du: string
                mailbox_batch_summary: string
                legacy_observer_vetoed: bool
                raw_key_deprecated: bool
            }

            type NativePendingGraphExistentialDispatchProof =
                | NativeDispatchTermTerminal of NativeTerminalPayloadWitness<NativeTermKind> * IVar<string>
                | NativeDispatchTyTerminal of NativeTerminalPayloadWitness<NativeTyKind> * IVar<string>

            let nativeTerminalPayloadWitnessText renderKind (w: NativeTerminalPayloadWitness<'Kind>) =
                sprintf "key=%s|terminal=%s|edge=%s|class=%s|outcome=%s|batch=%s|legacy_vetoed=%b|raw_key_deprecated=%b"
                    (nativeReplayKeyText renderKind w.key)
                    w.terminal
                    w.ivar_edge
                    w.terminal_commit_class_du
                    w.dispatch_outcome_du
                    w.mailbox_batch_summary
                    w.legacy_observer_vetoed
                    w.raw_key_deprecated

            let nativePendingGraphExistentialDispatchProofText = function
                | NativeDispatchTermTerminal(w,_) -> nativeTerminalPayloadWitnessText (fun () -> "term") w
                | NativeDispatchTyTerminal(w,_) -> nativeTerminalPayloadWitnessText (fun () -> "ty") w

            type NativeMandatoryDispatchProofFieldId =
                | NativeProofPendingGraphDispatchOutcome
                | NativeProofHopacIvarResolutionEdge
                | NativeProofTerminalCommitClass
                | NativeProofPendingGraphMailboxBatchSummary
                | NativeProofLegacyObserverVetoed
                | NativeProofRawKeyDeprecated

            let nativeMandatoryDispatchProofFieldText = function
                | NativeProofPendingGraphDispatchOutcome -> "pending_graph_dispatch_outcome"
                | NativeProofHopacIvarResolutionEdge -> "hopac_ivar_resolution_edge"
                | NativeProofTerminalCommitClass -> "terminal_commit_class_du"
                | NativeProofPendingGraphMailboxBatchSummary -> "pending_graph_mailbox_batch_summary"
                | NativeProofLegacyObserverVetoed -> "legacy_observer_vetoed"
                | NativeProofRawKeyDeprecated -> "raw_key_deprecated"

            let nativeMandatoryDispatchProofFields =
                [ NativeProofPendingGraphDispatchOutcome
                  NativeProofHopacIvarResolutionEdge
                  NativeProofTerminalCommitClass
                  NativeProofPendingGraphMailboxBatchSummary
                  NativeProofLegacyObserverVetoed
                  NativeProofRawKeyDeprecated ]

            let nativeMandatoryDispatchProofFieldsSummary =
                nativeMandatoryDispatchProofFields
                |> List.map nativeMandatoryDispatchProofFieldText
                |> String.concat ","

            type NativeReplayDriverFn<'Kind> = NativeReplayKey<'Kind> -> Job<Result<NativeSemanticShadowResult<'Kind>,string>>

            type NativeReplayDriverEnvelope<'Kind> = {
                driver: NativeReplayDriverKindId
                timeout_ms: int
                execute: NativeReplayDriverFn<'Kind>
                claim_boundary: string
            }

            type NativeObligationMailboxReceipt = {
                driver: NativeReplayDriverKindId
                key_shape: NativeReplayShapeId
                timeout_ms: int
                wait_primitive: NativeHopacWaitPrimitiveId
                worklist_policy: NativeHopacWorklistPolicyId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeObligationMailboxReceiptText (r: NativeObligationMailboxReceipt) =
                sprintf "driver=%s|shape=%s|timeout_ms=%d|wait=%s|worklist=%s|primary=%s|claim=%s"
                    (nativeReplayDriverKindText r.driver)
                    (nativeReplayShapeText r.key_shape)
                    r.timeout_ms
                    (nativeHopacWaitPrimitiveText r.wait_primitive)
                    (nativeHopacWorklistPolicyText r.worklist_policy)
                    (nativeHopacReadinessText r.primary_authority)
                    r.claim_boundary

            let nativeObligationReceiptForTermKey key =
                { driver = NativeReplayDriverTerm
                  key_shape = nativeReplayKeyShape key
                  timeout_ms = 1500
                  wait_primitive = NativeWaitIvarRead
                  worklist_policy = NativeWorklistAwaitDependencyIvar
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_no_writer_root_buildok" }

            let nativeObligationReceiptForTyKey key =
                { driver = NativeReplayDriverTy
                  key_shape = nativeReplayKeyShape key
                  timeout_ms = 1500
                  wait_primitive = NativeWaitIvarRead
                  worklist_policy = NativeWorklistAwaitDependencyIvar
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_no_writer_root_buildok" }

            let nativeObligationMailboxSummary =
                [ nativeObligationReceiptForTermKey (NativeApplyArg(NativeNodeId 0,0))
                  nativeObligationReceiptForTyKey (NativeContinuationCell(NativeNodeId 0,NativeNodeId 1)) ]
                |> List.map nativeObligationMailboxReceiptText
                |> String.concat ";"

            // ALPHA1554: accelerate the native Hopac cutover with the first typed
            // stack-fence obligation plan.  The runtime still runs shadow-only, but the
            // frontier exposed by 1553 now has a concrete destination: a ContinuationCell
            // key, an IVar wait, and an Alt timeout/hard-poison boundary instead of a
            // repeat-cap/probation loop.  This gives later rounds a single integration
            // point to wire without promoting BuildOk, writer, root, or semantic authority.
            type NativeAltOutcomeId =
                | NativeAltOutcomeAwaitingIvar
                | NativeAltOutcomeFulfilled
                | NativeAltOutcomeTimeoutPoison
                | NativeAltOutcomeLegacyFallbackBlocked

            let nativeAltOutcomeText = function
                | NativeAltOutcomeAwaitingIvar -> "awaiting_ivar"
                | NativeAltOutcomeFulfilled -> "fulfilled"
                | NativeAltOutcomeTimeoutPoison -> "timeout_poison"
                | NativeAltOutcomeLegacyFallbackBlocked -> "legacy_fallback_blocked"

            type NativeStackFenceObligationPlan = {
                key: NativeErasedReplayKey
                wait_primitive: NativeHopacWaitPrimitiveId
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                expected_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeStackFenceObligationPlanText (p: NativeStackFenceObligationPlan) =
                sprintf "key=%s|wait=%s|timeout=%s/%dms|outcome=%s|primary=%s|claim=%s"
                    (nativeErasedReplayKeyText p.key)
                    (nativeHopacWaitPrimitiveText p.wait_primitive)
                    (nativeHopacTimeoutPolicyText p.timeout_policy)
                    p.timeout_ms
                    (nativeAltOutcomeText p.expected_outcome)
                    (nativeHopacReadinessText p.primary_authority)
                    p.claim_boundary

            let stackFenceObligationPlan =
                { key = NativeErasedTermKey (NativeContinuationCell(NativeNodeId 0, NativeNodeId 1))
                  wait_primitive = NativeWaitAltChooseTimeout
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  expected_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_stack_fence_no_writer_root_buildok" }

            let nativeStackFencePlanSummary =
                nativeStackFenceObligationPlanText stackFenceObligationPlan

            // ALPHA1555: parent-preserved yield-thrash is now modeled as a native
            // Hopac Alt/IVar obligation boundary instead of another legacy probation
            // grace.  Runtime 1554 showed the stack-fence lane firing correctly, then
            // the tail moved to parent_replay_status_preserved_yield_thrash_hard_poison.
            // Keep this as a shadow-only plan: it names the poison authority and timeout
            // that later replaces Thread.Yield/repeat-cap churn, without fabricating
            // writer/root/BuildOk or a semantic value.
            type NativeParentReplayPoisonObligationPlan = {
                parent_key: NativeErasedReplayKey
                continuation_cell: NativeErasedReplayKey
                handoff_site: string
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                expected_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
                claim_boundary: string
            }

            let nativeParentReplayPoisonObligationPlanText (p: NativeParentReplayPoisonObligationPlan) =
                sprintf "parent=%s|cell=%s|handoff=%s|timeout=%s/%dms|outcome=%s|primary=%s|claim=%s"
                    (nativeErasedReplayKeyText p.parent_key)
                    (nativeErasedReplayKeyText p.continuation_cell)
                    p.handoff_site
                    (nativeHopacTimeoutPolicyText p.timeout_policy)
                    p.timeout_ms
                    (nativeAltOutcomeText p.expected_outcome)
                    (nativeHopacReadinessText p.primary_authority)
                    p.claim_boundary

            let parentReplayPoisonObligationPlan =
                { parent_key = NativeErasedTermKey (NativeParentHandoff(NativeNodeId 0))
                  continuation_cell = NativeErasedTermKey (NativeContinuationCell(NativeNodeId 0, NativeNodeId 1))
                  handoff_site = "term_to_ty_or_parent"
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  expected_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge
                  claim_boundary = "shadow_only_parent_preserved_yield_thrash_no_writer_root_buildok" }

            let nativeParentReplayPoisonPlanSummary =
                nativeParentReplayPoisonObligationPlanText parentReplayPoisonObligationPlan

            // ALPHA1556: materialized terminal outcome + typed PendingGraph shard.
            // The 1555 assessment identified the current missing bridge: shadow Alt pierces
            // semantic_stale_retarget, but the legacy pinned terminal observer receives only
            // an instruction string (required_next=materialize_...) instead of a typed terminal
            // payload.  These DUs make the fail-closed target explicit while remaining shadow-only.
            type NativeMaterializedTerminalOutcomeId =
                | NativeTerminalShadowTimeoutStaleRetargetPierce
                | NativeTerminalSemanticStaleRetargetShadowTimeoutPierce
                | NativeTerminalMissingPrefetchCycleBreakPoison
                | NativeTerminalCrossKindContinuationPendingReplay
                | NativeTerminalLegacyObserverRejected
                | NativeTerminalDynamicRecordKeyBridgeTailPierce
                | NativeTerminalSmallQueueParentReplayPoisonPierce
                | NativeTerminalStackFenceShadowTimeoutPierce
                | NativeTerminalIfUnknownReturnConditionTailPierce
                | NativeTerminalShadowTimeoutDeferredChildPierce
                | NativeTerminalParentContinuationCycleShadowTimeoutPierce
                | NativeTerminalQapVetoRejectedPendingGraphAuthority
                | NativeTerminalLocalizedDriverCutoverRequired
                | NativeTerminalSmallQueueActiveAuthorityDrainPierce

            let nativeMaterializedTerminalOutcomeText = function
                | NativeTerminalShadowTimeoutStaleRetargetPierce -> "ShadowTimeoutStaleRetargetPierce"
                | NativeTerminalSemanticStaleRetargetShadowTimeoutPierce -> "SemanticStaleRetargetShadowTimeoutPierce"
                | NativeTerminalMissingPrefetchCycleBreakPoison -> "MissingPrefetchCycleBreakPoison"
                | NativeTerminalCrossKindContinuationPendingReplay -> "CrossKindContinuationPendingReplay"
                | NativeTerminalLegacyObserverRejected -> "LegacyObserverRejected"
                | NativeTerminalDynamicRecordKeyBridgeTailPierce -> "DynamicRecordKeyBridgeTailPierce"
                | NativeTerminalSmallQueueParentReplayPoisonPierce -> "SmallQueueParentReplayPoisonPierce"
                | NativeTerminalStackFenceShadowTimeoutPierce -> "StackFenceShadowTimeoutPierce"
                | NativeTerminalIfUnknownReturnConditionTailPierce -> "IfUnknownReturnConditionTailPierce"
                | NativeTerminalShadowTimeoutDeferredChildPierce -> "ShadowTimeoutDeferredChildPierce"
                | NativeTerminalParentContinuationCycleShadowTimeoutPierce -> "ParentContinuationCycleShadowTimeoutPierce"
                | NativeTerminalQapVetoRejectedPendingGraphAuthority -> "QapVetoRejectedPendingGraphAuthority"
                | NativeTerminalLocalizedDriverCutoverRequired -> "LocalizedDriverCutoverRequired"
                | NativeTerminalSmallQueueActiveAuthorityDrainPierce -> "SmallQueueActiveAuthorityDrainPierce"

            type NativePendingGraphReadinessId =
                | NativePendingGraphReadyToSchedule
                | NativePendingGraphAwaitingIvarFill
                | NativePendingGraphPendingReplay
                | NativePendingGraphFailClosedTerminalMaterialized

            let nativePendingGraphReadinessText = function
                | NativePendingGraphReadyToSchedule -> "ready_to_schedule"
                | NativePendingGraphAwaitingIvarFill -> "awaiting_ivar_fill"
                | NativePendingGraphPendingReplay -> "pending_replay"
                | NativePendingGraphFailClosedTerminalMaterialized -> "fail_closed_terminal_materialized"

            type NativePendingGraphShardStateId =
                | NativeShardAwaitingChild of int
                | NativeShardAwaitingCrossKindContinuation of string
                | NativeShardTerminalPayloadMaterialized of NativeMaterializedTerminalOutcomeId
                | NativeShardLegacyQapVetoRejected of q: int * active: int * pending: int

            let nativePendingGraphShardStateText = function
                | NativeShardAwaitingChild nodeId -> sprintf "AwaitingChild(NodeId<TermKind:%d>)" nodeId
                | NativeShardAwaitingCrossKindContinuation handoff -> sprintf "AwaitingCrossKindContinuation(%s)" handoff
                | NativeShardTerminalPayloadMaterialized outcome -> sprintf "TerminalPayload(%s)" (nativeMaterializedTerminalOutcomeText outcome)
                | NativeShardLegacyQapVetoRejected(q,active,pending) -> sprintf "LegacyQapVetoRejected(q=%d,a=%d,p=%d)" q active pending

            type NativePendingGraphNode =
                | NativePendingGraphTerm of key: NativeReplayKey<NativeTermKind> * status: string * readiness: NativePendingGraphReadinessId * children: NativePendingGraphNode list
                | NativePendingGraphTy of key: NativeReplayKey<NativeTyKind> * status: string * readiness: NativePendingGraphReadinessId * children: NativePendingGraphNode list

            let nativePendingGraphNodeKeyText = function
                | NativePendingGraphTerm(key,_,_,_) -> nativeReplayKeyText (fun () -> "term") key
                | NativePendingGraphTy(key,_,_,_) -> nativeReplayKeyText (fun () -> "ty") key

            let nativePendingGraphNodeReadinessText = function
                | NativePendingGraphTerm(_,_,readiness,_) -> nativePendingGraphReadinessText readiness
                | NativePendingGraphTy(_,_,readiness,_) -> nativePendingGraphReadinessText readiness

            type NativeMaterializedTerminalPayload = {
                replay_key: NativeErasedReplayKey
                terminal_outcome: NativeMaterializedTerminalOutcomeId
                pierce_target_du: string
                continuation_readiness: NativePendingGraphReadinessId
                fail_closed: bool
                expected_return_type: string
                claim_boundary: string
            }

            let nativeMaterializedTerminalPayloadText (p: NativeMaterializedTerminalPayload) =
                sprintf "key=%s|terminal=%s|target=%s|continuation=%s|fail_closed=%b|return=%s|claim=%s"
                    (nativeErasedReplayKeyText p.replay_key)
                    (nativeMaterializedTerminalOutcomeText p.terminal_outcome)
                    p.pierce_target_du
                    (nativePendingGraphReadinessText p.continuation_readiness)
                    p.fail_closed
                    p.expected_return_type
                    p.claim_boundary

            type NativeSemanticStaleRetargetMaterializationPlan = {
                hot_node: NativePendingGraphNode
                payload: NativeMaterializedTerminalPayload
                timeout_policy: NativeHopacTimeoutPolicyId
                timeout_ms: int
                alt_outcome: NativeAltOutcomeId
                primary_authority: NativeHopacReadinessId
            }

            let nativeSemanticStaleRetargetMaterializationPlanText (p: NativeSemanticStaleRetargetMaterializationPlan) =
                sprintf "node=%s|readiness=%s|payload=%s|timeout=%s/%dms|alt=%s|primary=%s"
                    (nativePendingGraphNodeKeyText p.hot_node)
                    (nativePendingGraphNodeReadinessText p.hot_node)
                    (nativeMaterializedTerminalPayloadText p.payload)
                    (nativeHopacTimeoutPolicyText p.timeout_policy)
                    p.timeout_ms
                    (nativeAltOutcomeText p.alt_outcome)
                    (nativeHopacReadinessText p.primary_authority)

            let materializeTypedSemanticStaleRetargetOutcome key : NativeMaterializedTerminalPayload =
                { replay_key = key
                  terminal_outcome = NativeTerminalSemanticStaleRetargetShadowTimeoutPierce
                  pierce_target_du = "semantic_root_complete_stale_retarget_missing_prefetch_cycle_break"
                  continuation_readiness = NativePendingGraphPendingReplay
                  fail_closed = true
                  expected_return_type = "EvalWorklistTerminal(SemanticStaleRetargetShadowTimeoutPierce)"
                  claim_boundary = "shadow_timeout_materialized_no_writer_root_buildok" }

            let semanticStaleRetargetMaterializationPlan =
                let continuation = NativeContinuationCell(NativeNodeId 0, NativeNodeId 1)
                let erased = NativeErasedTyKey continuation
                { hot_node = NativePendingGraphTy(continuation, "semantic_stale_retarget", NativePendingGraphPendingReplay, [])
                  payload = materializeTypedSemanticStaleRetargetOutcome erased
                  timeout_policy = NativeTimeoutAltChooseHardPoison
                  timeout_ms = 1500
                  alt_outcome = NativeAltOutcomeTimeoutPoison
                  primary_authority = NativeHopacReadinessHybridBridge }

            let semanticStaleRetargetMaterializationSummary =
                nativeSemanticStaleRetargetMaterializationPlanText semanticStaleRetargetMaterializationPlan

            // ALPHA1557: assessment debt burn-down.  Alpha1556 created the typed payload;
            // this slice makes the handoff decision itself typed so the next runtime can
            // distinguish "terminal materialized, fail closed" from "legacy observer froze again".
            // The values remain shadow/burn-in only and intentionally carry no writer/root/BuildOk.
            type NativeTerminalMaterializationDecisionId =
                | NativeTerminalMaterializeAndFailClosed
                | NativeTerminalSchedulePendingReplayDrain
                | NativeTerminalRequeueCrossKindContinuation
                | NativeTerminalRejectLegacyPinnedObserver
                | NativeTerminalMissingPayloadDebt

            let nativeTerminalMaterializationDecisionText = function
                | NativeTerminalMaterializeAndFailClosed -> "materialize_and_fail_closed"
                | NativeTerminalSchedulePendingReplayDrain -> "schedule_pending_replay_drain"
                | NativeTerminalRequeueCrossKindContinuation -> "requeue_cross_kind_continuation"
                | NativeTerminalRejectLegacyPinnedObserver -> "reject_legacy_pinned_observer"
                | NativeTerminalMissingPayloadDebt -> "missing_payload_debt"

            type NativeObligationLivenessId =
                | NativeObligationNoEvidence
                | NativeObligationLegacyPhysicalOnly
                | NativeObligationIvarAwaitingFill
                | NativeObligationAltTimeoutFired
                | NativeObligationTerminalMaterialized

            let nativeObligationLivenessText = function
                | NativeObligationNoEvidence -> "no_evidence"
                | NativeObligationLegacyPhysicalOnly -> "legacy_physical_only"
                | NativeObligationIvarAwaitingFill -> "ivar_awaiting_fill"
                | NativeObligationAltTimeoutFired -> "alt_timeout_fired"
                | NativeObligationTerminalMaterialized -> "terminal_materialized"

            type NativeHopacQuorumId =
                | NativeQuorumIvarWaitEmpty
                | NativeQuorumAltExpiredFailClosed
                | NativeQuorumLegacyQapVetoRejected
                | NativeQuorumPrimaryAuthorityStillGated

            let nativeHopacQuorumText = function
                | NativeQuorumIvarWaitEmpty -> "IVar_Wait_Empty"
                | NativeQuorumAltExpiredFailClosed -> "Alt_Expired_FailClosed"
                | NativeQuorumLegacyQapVetoRejected -> "Legacy_QAP_Veto_Rejected"
                | NativeQuorumPrimaryAuthorityStillGated -> "Primary_Hopac_Still_Gated"

            type NativeTypedReplayKeyProjection = {
                kind: NativeReplayDriverKindId
                shape: NativeReplayShapeId
                node_id: int
                cursor: int
                step: int
                site: string
                source_key: NativeErasedReplayKey
            }

            let nativeReplayKeyProjectionFields key =
                match key with
                | NativeApplyArg(node,index) -> NativeReplayShapeApply, nativeNodeIdValue node, index, 0, "apply_arg"
                | NativeFunctionBody node -> NativeReplayShapeFunctionBody, nativeNodeIdValue node, 0, 0, "function_body"
                | NativeRecordKey(_,node) -> NativeReplayShapeRecordKey, nativeNodeIdValue node, 0, 0, "record_key"
                | NativeParentHandoff node -> NativeReplayShapeParentHandoff, nativeNodeIdValue node, 0, 0, "parent_handoff"
                | NativeContinuationCell(owner,child) -> NativeReplayShapeContinuationCell, nativeNodeIdValue child, nativeNodeIdValue owner, nativeNodeIdValue child, "continuation_cell"
                | NativeDeferredChildCell(owner,child) -> NativeReplayShapeDeferredChild, nativeNodeIdValue child, nativeNodeIdValue owner, nativeNodeIdValue child, "deferred_child"

            let nativeTypedReplayKeyProjectionFromErased key =
                let kind, shape, nodeId, cursor, step, site =
                    match key with
                    | NativeErasedTermKey k ->
                        let shape, nodeId, cursor, step, site = nativeReplayKeyProjectionFields k
                        NativeReplayDriverTerm, shape, nodeId, cursor, step, site
                    | NativeErasedTyKey k ->
                        let shape, nodeId, cursor, step, site = nativeReplayKeyProjectionFields k
                        NativeReplayDriverTy, shape, nodeId, cursor, step, site
                { kind = kind
                  shape = shape
                  node_id = nodeId
                  cursor = cursor
                  step = step
                  site = site
                  source_key = key }

            let nativeTypedReplayKeyProjectionText p =
                sprintf "kind=%s|shape=%s|node=%d|cursor=%d|step=%d|site=%s|key=%s"
                    (nativeReplayDriverKindText p.kind)
                    (nativeReplayShapeText p.shape)
                    p.node_id
                    p.cursor
                    p.step
                    p.site
                    (nativeErasedReplayKeyText p.source_key)

            type NativeSemanticStaleRetargetTerminalBridge = {
                hot_graph: NativePendingGraphNode
                typed_key: NativeTypedReplayKeyProjection
                payload: NativeMaterializedTerminalPayload
                decision: NativeTerminalMaterializationDecisionId
                liveness: NativeObligationLivenessId
                continuation_action: NativeTerminalMaterializationDecisionId
                legacy_observer_vetoed: bool
                next_driver_stage: string
                claim_boundary: string
            }

            let nativeSemanticStaleRetargetTerminalBridgeText b =
                sprintf "typed_key=%s|payload=%s|decision=%s|liveness=%s|continuation=%s|legacy_observer_vetoed=%b|stage=%s|claim=%s"
                    (nativeTypedReplayKeyProjectionText b.typed_key)
                    (nativeMaterializedTerminalPayloadText b.payload)
                    (nativeTerminalMaterializationDecisionText b.decision)
                    (nativeObligationLivenessText b.liveness)
                    (nativeTerminalMaterializationDecisionText b.continuation_action)
                    b.legacy_observer_vetoed
                    b.next_driver_stage
                    b.claim_boundary

            let semanticStaleRetargetTerminalBridge =
                let plan = semanticStaleRetargetMaterializationPlan
                { hot_graph = plan.hot_node
                  typed_key = nativeTypedReplayKeyProjectionFromErased plan.payload.replay_key
                  payload = plan.payload
                  decision = NativeTerminalMaterializeAndFailClosed
                  liveness = NativeObligationTerminalMaterialized
                  continuation_action = NativeTerminalRequeueCrossKindContinuation
                  legacy_observer_vetoed = true
                  next_driver_stage = "materialized_terminal_pending_graph_burnin"
                  claim_boundary = "shadow_terminal_payload_materialized_requeue_typed_continuation_no_writer_root_buildok" }

            let semanticStaleRetargetTerminalBridgeSummary =
                nativeSemanticStaleRetargetTerminalBridgeText semanticStaleRetargetTerminalBridge

            // ALPHA1558: parent-continuation cycle materialization burn-in.
            // The 1557 runtime moved the hot frontier to semantic_parent_continuation_cycle_deferred
            // with cooperative_replay_handoff and an active cross-kind sidecar drain.  This bridge
            // makes that frontier a first-class typed terminal/continuation obligation instead of
            // leaving it as a legacy observer/bridge-tail wait.
