            type NativeHopacShadowWaitCell<'k,'v> = {
                key: 'k
                generation: int64
                result: IVar<Result<'v,string>>
                state: NativeHopacCellStateId
                wait_primitive: NativeHopacWaitPrimitiveId
                owner: NativeHopacCacheOwnerId
                legacy_wait_signature: string
            }

            let createShadowIvarWaitCell<'k,'v> (key: 'k) (generation: int64) (legacyWaitSignature: string) : NativeHopacShadowWaitCell<'k,'v> =
                { key = key
                  generation = generation
                  result = IVar<Result<'v,string>>()
                  state = NativeCellAwaitingProducer
                  wait_primitive = NativeWaitIvarRead
                  owner = NativeCacheActorOwned
                  legacy_wait_signature = legacyWaitSignature }

            let readShadowIvarWaitCell (cell: NativeHopacShadowWaitCell<'k,'v>) : Job<Result<'v,string>> =
                IVar.read cell.result

            let fulfillShadowIvarWaitCell (cell: NativeHopacShadowWaitCell<'k,'v>) (value: 'v) : Job<unit> =
                IVar.tryFill cell.result (Ok value)

            let poisonShadowIvarWaitCell (cell: NativeHopacShadowWaitCell<'k,'v>) (reason: string) : Job<unit> =
                IVar.tryFill cell.result (Error reason)

            type NativeHopacActorCacheState<'k,'v when 'k : comparison> = {
                generation: int64
                store: Map<'k,'v>
                missing_dependency_count: int64
                invalidation_count: int64
            }

            let emptyActorCacheState<'k,'v when 'k : comparison> (generation: int64) : NativeHopacActorCacheState<'k,'v> =
                { generation = generation
                  store = Map.empty
                  missing_dependency_count = 0L
                  invalidation_count = 0L }

            let shadowActorCacheStep<'k,'v when 'k : comparison> (state: NativeHopacActorCacheState<'k,'v>) (msg: NativeHopacCacheMsg<'k,'v>) : Job<NativeHopacActorCacheState<'k,'v>> =
                job {
                    match msg with
                    | NativeCacheGet(key, reply) ->
                        do! IVar.tryFill reply (Map.tryFind key state.store)
                        return state
                    | NativeCachePut(key, value) ->
                        return { state with store = Map.add key value state.store }
                    | NativeCacheInvalidateGeneration(generation, _policy) ->
                        return { state with generation = generation; store = Map.empty; invalidation_count = state.invalidation_count + 1L }
                    | NativeCacheMissingDependency(_key, reply) ->
                        do! IVar.tryFill reply (sprintf "missing_dependency_shadow|generation=%d|misses=%d" state.generation (state.missing_dependency_count + 1L))
                        return { state with missing_dependency_count = state.missing_dependency_count + 1L }
                    | NativeCacheSnapshot reply ->
                        do! IVar.tryFill reply (state.store.Count, state.generation)
                        return state
                }

            let rec shadowActorCacheLoop<'k,'v when 'k : comparison> (ch: Ch<NativeHopacCacheMsg<'k,'v>>) (state: NativeHopacActorCacheState<'k,'v>) : Job<unit> =
                job {
                    let! msg = Ch.take ch
                    let! nextState = shadowActorCacheStep state msg
                    return! shadowActorCacheLoop ch nextState
                }

            let startShadowActorCache<'k,'v when 'k : comparison> (generation: int64) : Job<Ch<NativeHopacCacheMsg<'k,'v>>> =
                job {
                    let ch = Ch<NativeHopacCacheMsg<'k,'v>>()
                    do! Job.start (shadowActorCacheLoop ch (emptyActorCacheState<'k,'v> generation))
                    return ch
                }

