                | ParentPoisonDeferLiveTailEvidence -> "defer_poison_live_tail_evidence"
                | ParentPoisonDeferLiveTailPhysicalPending -> "defer_poison_live_tail_physical_pending"
                | ParentPoisonLiveReplayEvidenceStillDraining -> "live_replay_evidence_still_draining"
                | ParentPoisonShadowAltTimeoutPiercesLiveTailOverride -> "shadow_alt_timeout_pierces_live_tail_override"
                | ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides -> "shadow_alt_timeout_pierces_all_legacy_overrides"
                | ParentPoisonWinsNoLiveReplayEvidenceGraceExpired -> "poison_wins_no_live_replay_evidence_grace_expired"

            let parentPoisonVsLiveTailVerdictPiercesLegacy = function
                | ParentPoisonShadowAltTimeoutPiercesLiveTailOverride
                | ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides -> true
                | _ -> false

            let parentPoisonVsLiveTailVerdictFor
                (isParentPoison: bool)
                (pending: int)
                (queueDepth: int)
                (activeDepth: int)
                (progressYield: int)
                (witnessAgeMs: float)
                (hardCapReceipts: int)
                (suppressedPins: int)
                (preservedRepeats: int)
                (liveTailOverride: bool) =
                if not isParentPoison then ParentPoisonNoCycleBreak
                elif liveTailOverride
                     && witnessAgeMs >= 1500.0
                     && (hardCapReceipts > 0
                         || suppressedPins >= 4
                         || preservedRepeats >= 4
                         || progressYield >= 512) then
                    // ALPHA1524: make the 1523 verdict explicitly broader than
                    // one named row.  The shadow Alt timeout is a typed assassin
                    // for every legacy liveness override in this parent-poison lane,
                    // not just the no-root-bypass spelling that surfaced first.
                    ParentPoisonShadowAltTimeoutPiercesAllLegacyOverrides
                elif liveTailOverride && pending > 0 then
                    ParentPoisonDeferLiveTailPhysicalPending
                elif liveTailOverride then ParentPoisonDeferLiveTailEvidence
                elif pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYield > 0 then
                    ParentPoisonLiveReplayEvidenceStillDraining
                else ParentPoisonWinsNoLiveReplayEvidenceGraceExpired

