                | NativeMailboxProbeExpiredFailClosed

            let nativeHopacMailboxProbeStateText = function
                | NativeMailboxProbeNone -> "mailbox_probe_none"
                | NativeMailboxProbeScheduled -> "mailbox_probe_scheduled"
                | NativeMailboxProbeObservedMiss -> "mailbox_probe_observed_miss"
                | NativeMailboxProbeObservedHitPrimaryBlocked -> "mailbox_probe_observed_hit_primary_blocked"
                | NativeMailboxProbeExpiredFailClosed -> "mailbox_probe_expired_fail_closed"

            type NativeHopacAltStateId =
                | NativeAltNoTarget
                | NativeAltArmedShadowOnly
                | NativeAltHoldoff
                | NativeAltExpiredFailClosed

            let nativeHopacAltStateText = function
