                | NativeAltArmedShadowOnly -> "alt_armed_shadow_only"
                | NativeAltHoldoff -> "alt_timeout_holdoff"
                | NativeAltExpiredFailClosed -> "alt_timeout_expired_fail_closed"

            type NativeHopacSidecarLeaseStateId =
                | NativeSidecarLeaseNoTarget
                | NativeSidecarLeasePhysicalPending
                | NativeSidecarLeaseQ0P0Vetoed
                | NativeSidecarLeaseExpiredFailClosed

            let nativeHopacSidecarLeaseStateText = function
                | NativeSidecarLeaseNoTarget -> "lease_no_target"
                | NativeSidecarLeasePhysicalPending -> "lease_physical_pending"
                | NativeSidecarLeaseQ0P0Vetoed -> "lease_q0_p0_vetoed"
                | NativeSidecarLeaseExpiredFailClosed -> "lease_expired_fail_closed"

            let nativeHopacSidecarHasTarget (targetKey: string) =
                not (System.String.IsNullOrWhiteSpace targetKey) && targetKey <> "-" && targetKey <> "none"

            let nativeHopacSidecarIvarStateFor (pending: int) (targetKey: string) (ageMs: int64) =
                if not (nativeHopacSidecarHasTarget targetKey) then NativeSidecarIvarNoTarget
                elif pending <= 0 || ageMs >= 60000L then NativeSidecarIvarExpiredFailClosed
                else NativeSidecarIvarAwaitingFill

            let nativeHopacMailboxProbeStateFor (pending: int) (queueDepth: int) (activeDepth: int) (targetKey: string) (ageMs: int64) =
                if not (nativeHopacSidecarHasTarget targetKey) then NativeMailboxProbeNone
                elif pending <= 0 || ageMs >= 60000L then NativeMailboxProbeExpiredFailClosed
                elif queueDepth > 0 || activeDepth > 0 then NativeMailboxProbeScheduled
                else NativeMailboxProbeObservedMiss

            let nativeHopacAltStateFor (pending: int) (targetKey: string) (ageMs: int64) =
                if not (nativeHopacSidecarHasTarget targetKey) then NativeAltNoTarget
                elif pending <= 0 || ageMs >= 60000L then NativeAltExpiredFailClosed
                elif ageMs >= 40000L then NativeAltHoldoff
                else NativeAltArmedShadowOnly

            let nativeHopacSidecarLeaseStateFor (pending: int) (queueDepth: int) (activeDepth: int) (targetKey: string) (ageMs: int64) =
                if not (nativeHopacSidecarHasTarget targetKey) then NativeSidecarLeaseNoTarget
                elif pending <= 0 && queueDepth <= 0 then NativeSidecarLeaseQ0P0Vetoed
                elif ageMs >= 60000L then NativeSidecarLeaseExpiredFailClosed
                else NativeSidecarLeasePhysicalPending

            let nativeHopacSidecarUnblockReadyText ivarState mailboxState altState leaseState =
                match ivarState, mailboxState, altState, leaseState with
                | NativeSidecarIvarAwaitingFill, NativeMailboxProbeScheduled, NativeAltArmedShadowOnly, NativeSidecarLeasePhysicalPending -> "shadow_unblock_not_ready_probe_scheduled"
                | NativeSidecarIvarExpiredFailClosed, _, _, _
                | _, NativeMailboxProbeExpiredFailClosed, _, _
                | _, _, NativeAltExpiredFailClosed, _
                | _, _, _, NativeSidecarLeaseExpiredFailClosed
                | _, _, _, NativeSidecarLeaseQ0P0Vetoed -> "unblock_fail_closed"
                | _ -> "shadow_unblock_not_ready_primary_blocked"

            let nativeHopacSidecarDrainAuthorityFor (pending: int) (queueDepth: int) (activeDepth: int) (targetKey: string) (ageMs: int64) =
                let hasTarget = not (System.String.IsNullOrWhiteSpace targetKey) && targetKey <> "-" && targetKey <> "none"
                if not hasTarget then NativeSidecarDrainNoTarget
                elif pending <= 0 then NativeSidecarDrainAltTimeoutExpiredFailClosed
                elif ageMs >= 60000L then NativeSidecarDrainAltTimeoutExpiredFailClosed
                elif queueDepth > 0 || activeDepth > 0 then NativeSidecarDrainMailboxProbeScheduled
                else NativeSidecarDrainShadowIvarRegistered

            let nativeHopacSidecarDrainPrimaryBlockerText (authority: NativeHopacSidecarDrainAuthorityId) =
