            type NativeHopacPrefetchRequest<'k> = {
                key: 'k
                local_generation: int64
                global_generation: int64
                source: NativeHopacPrefetchSourceId
                blocked_by_reentry: bool
                sidecar_ty_reentry_prefetch: bool
                fuse_depth: int
                re_counter: int
                reentry_thrash_count: int
                same_hot_count: int
                pending_active_sum: int
                replay_delta_recent: bool
                semantic_receipts_recent: bool
            }

            type NativeHopacPrefetchArbitrationReceipt<'k> = {
                request: NativeHopacPrefetchRequest<'k>
                decision: NativeHopacPrefetchDecisionId
                veto_evidence: string
                claim_boundary: string
            }

            let decideShadowPrefetchMailbox (req: NativeHopacPrefetchRequest<'k>) : NativeHopacPrefetchDecisionId =
                let generationStale = req.local_generation <> req.global_generation
                let liveTail = 0 < req.pending_active_sum || req.replay_delta_recent || req.semantic_receipts_recent
                let reentryFuse = req.blocked_by_reentry || req.sidecar_ty_reentry_prefetch || 0 < req.fuse_depth || 0 < req.reentry_thrash_count || 0 < req.same_hot_count
                if generationStale && not liveTail then NativePrefetchPoisonStaleGeneration
                elif reentryFuse && liveTail then NativePrefetchDeferTermCycleFuseLiveTail
                elif generationStale then NativePrefetchEscalateSemanticMissingAfterBlocked
                elif liveTail then NativePrefetchAwaitActorReply
                else NativePrefetchHoldShadowOnly

            let nativeHopacPrefetchArbitrationReceiptText (renderKey: 'k -> string) (r: NativeHopacPrefetchArbitrationReceipt<'k>) =
                sprintf "key=%s|src=%s|decision=%s|gen=%d/%d|blocked_by_reentry=%b|sidecar_ty=%b|fuse_depth=%d|re=%d|thrash=%d|same_hot=%d|pending_active=%d|replay_recent=%b|semantic_recent=%b|veto=%s|claim=%s"
                    (renderKey r.request.key)
                    (nativeHopacPrefetchSourceText r.request.source)
                    (nativeHopacPrefetchDecisionText r.decision)
                    r.request.local_generation
                    r.request.global_generation
                    r.request.blocked_by_reentry
                    r.request.sidecar_ty_reentry_prefetch
                    r.request.fuse_depth
                    r.request.re_counter
                    r.request.reentry_thrash_count
                    r.request.same_hot_count
                    r.request.pending_active_sum
                    r.request.replay_delta_recent
                    r.request.semantic_receipts_recent
                    r.veto_evidence
                    r.claim_boundary

            type NativeHopacPrefetchMsg<'k,'v> =
                | NativePrefetchRequest of NativeHopacPrefetchRequest<'k> * IVar<Result<'v, NativeHopacPrefetchDecisionId * string>>
                | NativePrefetchResolve of key: 'k * value: 'v
                | NativePrefetchPoisonGeneration of generation: int64 * reason: string
                | NativePrefetchMailboxSnapshot of reply: IVar<int * int64>

            type NativeHopacPrefetchMailboxState<'k,'v when 'k : comparison> = {
                generation: int64
                resolved: Map<'k,'v>
                blocked_requests: int64
                live_tail_deferrals: int64
                stale_generation_poisons: int64
            }

            let inline emptyPrefetchMailboxState<'k,'v when 'k : comparison> (generation: int64) : NativeHopacPrefetchMailboxState<'k,'v> =
                { generation = generation
                  resolved = Map.empty<'k,'v>
                  blocked_requests = 0L
                  live_tail_deferrals = 0L
                  stale_generation_poisons = 0L }

            let shadowPrefetchMailboxStep<'k,'v when 'k : comparison> (state: NativeHopacPrefetchMailboxState<'k,'v>) (msg: NativeHopacPrefetchMsg<'k,'v>) : Job<NativeHopacPrefetchMailboxState<'k,'v>> =
                job {
                    match msg with
                    | NativePrefetchRequest(req, reply) ->
                        match Map.tryFind req.key state.resolved with
                        | Some value ->
                            do! IVar.tryFill reply (Ok value)
                            return state
                        | None ->
                            let decision = decideShadowPrefetchMailbox req
                            do! IVar.tryFill reply (Error(decision, "shadow_prefetch_mailbox_no_runtime_value"))
                            return
                                match decision with
                                | NativePrefetchDeferTermCycleFuseLiveTail -> { state with blocked_requests = state.blocked_requests + 1L; live_tail_deferrals = state.live_tail_deferrals + 1L }
                                | NativePrefetchPoisonStaleGeneration -> { state with blocked_requests = state.blocked_requests + 1L; stale_generation_poisons = state.stale_generation_poisons + 1L }
                                | _ -> { state with blocked_requests = state.blocked_requests + 1L }
                    | NativePrefetchResolve(key, value) ->
                        return { state with resolved = Map.add key value state.resolved }
                    | NativePrefetchPoisonGeneration(generation, _reason) ->
                        return { state with generation = generation; resolved = Map.empty; stale_generation_poisons = state.stale_generation_poisons + 1L }
                    | NativePrefetchMailboxSnapshot reply ->
                        do! IVar.tryFill reply (state.resolved.Count, state.generation)
                        return state
                }

            let rec shadowPrefetchMailboxLoop<'k,'v when 'k : comparison> (ch: Ch<NativeHopacPrefetchMsg<'k,'v>>) (state: NativeHopacPrefetchMailboxState<'k,'v>) : Job<unit> =
                job {
                    let! msg = Ch.take ch
                    let! nextState = shadowPrefetchMailboxStep state msg
                    return! shadowPrefetchMailboxLoop ch nextState
                }

            let inline startShadowPrefetchMailbox<'k,'v when 'k : comparison> (generation: int64) : Job<Ch<NativeHopacPrefetchMsg<'k,'v>>> =
                job {
                    let ch: Ch<NativeHopacPrefetchMsg<'k,'v>> = Ch<NativeHopacPrefetchMsg<'k,'v>>()
                    let initialState: NativeHopacPrefetchMailboxState<'k,'v> = emptyPrefetchMailboxState<'k,'v> generation
                    do! Job.start (shadowPrefetchMailboxLoop<'k,'v> ch initialState)
                    return ch
                }

