            // ALPHA1475: shadow-to-runtime wiring gate.
            // Alpha1474 made the sidecar prefetch mailbox observable.  This round adds
            // the typed decision layer that says when a mailbox reply is allowed to
            // become a real compile-log probe and when it must remain shadow-only.
            // It still preserves legacy runtime authority and does not claim BuildOk.
            type NativeHopacProbeLaneId =
                | NativeProbeLaneStaticReceipt
                | NativeProbeLaneConsoleOnly
                | NativeProbeLaneCompileLogDryRun
                | NativeProbeLaneRuntimeProbeCandidate
                | NativeProbeLaneRuntimeParityBurnIn

            let nativeHopacProbeLaneText = function
                | NativeProbeLaneStaticReceipt -> "static_receipt"
                | NativeProbeLaneConsoleOnly -> "console_only"
                | NativeProbeLaneCompileLogDryRun -> "compile_log_dry_run"
                | NativeProbeLaneRuntimeProbeCandidate -> "runtime_probe_candidate"
                | NativeProbeLaneRuntimeParityBurnIn -> "runtime_parity_burnin"

            type NativeHopacPrefetchRuntimeActionId =
                | NativePrefetchRuntimeKeepShadowOnly
                | NativePrefetchRuntimeEmitConsoleProbe
                | NativePrefetchRuntimeAwaitDependencyThenRecheckFuse
                | NativePrefetchRuntimePoisonOrCleanRetry
                | NativePrefetchRuntimePromoteAfterCompileLogReceipt

            let nativeHopacPrefetchRuntimeActionText = function
                | NativePrefetchRuntimeKeepShadowOnly -> "keep_shadow_only"
                | NativePrefetchRuntimeEmitConsoleProbe -> "emit_console_probe"
                | NativePrefetchRuntimeAwaitDependencyThenRecheckFuse -> "await_dependency_then_recheck_fuse"
                | NativePrefetchRuntimePoisonOrCleanRetry -> "poison_or_clean_retry"
                | NativePrefetchRuntimePromoteAfterCompileLogReceipt -> "promote_after_compile_log_receipt"

            type NativeHopacPrefetchRuntimeWiringReceipt<'k> = {
                request: NativeHopacPrefetchRequest<'k>
                mailbox_decision: NativeHopacPrefetchDecisionId
                runtime_action: NativeHopacPrefetchRuntimeActionId
                probe_lane: NativeHopacProbeLaneId
