            }

            let chooseShadowPrefetchRuntimeAction (decision: NativeHopacPrefetchDecisionId) =
                match decision with
                | NativePrefetchDeferTermCycleFuseLiveTail -> NativePrefetchRuntimeAwaitDependencyThenRecheckFuse
                | NativePrefetchAwaitActorReply -> NativePrefetchRuntimeEmitConsoleProbe
                | NativePrefetchEscalateSemanticMissingAfterBlocked -> NativePrefetchRuntimePoisonOrCleanRetry
                | NativePrefetchPoisonStaleGeneration -> NativePrefetchRuntimePoisonOrCleanRetry
                | NativePrefetchHoldShadowOnly -> NativePrefetchRuntimeKeepShadowOnly

            let chooseShadowPrefetchProbeLane (action: NativeHopacPrefetchRuntimeActionId) =
                match action with
                | NativePrefetchRuntimeAwaitDependencyThenRecheckFuse -> NativeProbeLaneCompileLogDryRun
                | NativePrefetchRuntimeEmitConsoleProbe -> NativeProbeLaneConsoleOnly
                | NativePrefetchRuntimePoisonOrCleanRetry -> NativeProbeLaneCompileLogDryRun
                | NativePrefetchRuntimePromoteAfterCompileLogReceipt -> NativeProbeLaneRuntimeProbeCandidate
                | NativePrefetchRuntimeKeepShadowOnly -> NativeProbeLaneStaticReceipt

