            let nativeHopacPendingFenceProbeAwait<'k> (cell: NativeHopacPendingFenceProbeCell<'k>) : Job<NativeHopacPendingFenceProbeResult<'k>> = job {
                let! payload = jobWithTimeoutMs cell.timeout_ms (IVar.read cell.reply)
                match payload with
                | Some text ->
                    return
                        { key = cell.key
                          stack_fence_pending_key = cell.stack_fence_pending_key
                          cycle_fuse_hot_node_id = cell.cycle_fuse_hot_node_id
                          outcome = NativePendingFenceProbeIvarResolved
                          resolved_payload = Some text
                          timeout_ms = cell.timeout_ms
                          runtime_authority_promoted = false }
                | None ->
                    return
                        { key = cell.key
                          stack_fence_pending_key = cell.stack_fence_pending_key
                          cycle_fuse_hot_node_id = cell.cycle_fuse_hot_node_id
                          outcome = NativePendingFenceProbeAltTimeoutGrace
