        // --- PATCH: actor_system (priority 10) ---
    

        // =========================================================================
        // ACTOR SYSTEM v4 - OTP-style Supervision (Rust tokio / Gleam OTP compatible)
        // =========================================================================
        // Maps to: Rust - tokio::spawn + mpsc channels
        //          Gleam - erlang process + Subject/reply patterns
        // Uses Hopac: Job<'a>, Ch<'a>, IVar<'a>, Promise<'a>
    

        /// Actor message envelope with typed request/reply
        [<RequireQualifiedAccess>]
        type ActorMsg<'req, 'reply> =
            | Request of 'req * IVar<'reply>
            | Fire of 'req
            | Cast of 'req
            | Shutdown of IVar<unit>
            | Kill
    

        /// Actor lifecycle state
        [<RequireQualifiedAccess>]
        type ActorLife =
            | Starting
            | Running
            | Stopping
            | Stopped
            | Failed of exn
    

        /// Actor statistics for monitoring
        type ActorStat = {
            name: string
            startTime: DateTime
            mutable messageCount: int64
            mutable errorCount: int64
            mutable lastMessageTime: DateTime
            mutable avgProcessingTimeMs: float
            mutable lifecycle: ActorLife
        }
    

        /// Actor handle for external communication
        type ActorRef<'req, 'reply> = {
            channel: Ch<ActorMsg<'req, 'reply>>
            stats: ActorStat
            shutdownComplete: IVar<unit>
        }
    

        /// Create actor statistics
        let createActorStat name = {
            name = name
            startTime = DateTime.UtcNow
            messageCount = 0L
            errorCount = 0L
            lastMessageTime = DateTime.UtcNow
            avgProcessingTimeMs = 0.0
            lifecycle = ActorLife.Starting
        }
    

        /// Spawn a new actor with supervision capabilities
        let spawnActor<'req, 'reply, 'state>
            (name: string)
            (init: unit -> Job<'state>)
            (handle: 'state -> 'req -> Job<'state * 'reply option>)
            (onError: exn -> 'state -> Job<'state option>)
            : Job<ActorRef<'req, 'reply>> =
            job {
                let ch = Ch<ActorMsg<'req, 'reply>>()
                let stats = createActorStat name
                let shutdownComplete = IVar<unit>()
    

                let! initialState = init()
                stats.lifecycle <- ActorLife.Running
    

                let rec loop (state: 'state) = job {
                    let! msg = Ch.take ch
                    let sw = System.Diagnostics.Stopwatch.StartNew()
    

                    match msg with
                    | ActorMsg.Request(req, reply) ->
                        stats.messageCount <- stats.messageCount + 1L
                        stats.lastMessageTime <- DateTime.UtcNow
                        try
                            let! newState, replyOpt = handle state req
                            sw.Stop()
                            stats.avgProcessingTimeMs <- (stats.avgProcessingTimeMs * 0.95) + (sw.Elapsed.TotalMilliseconds * 0.05)
                            match replyOpt with
                            | Some r -> do! IVar.fill reply r
                            | None -> ()
                            return! loop newState
                        with ex ->
                            stats.errorCount <- stats.errorCount + 1L
                            match! onError ex state with
                            | Some newState -> return! loop newState
                            | None ->
                                stats.lifecycle <- ActorLife.Failed ex
                                do! IVar.fill shutdownComplete ()
    

                    | ActorMsg.Fire req | ActorMsg.Cast req ->
                        stats.messageCount <- stats.messageCount + 1L
                        stats.lastMessageTime <- DateTime.UtcNow
                        try
                            let! newState, _ = handle state req
                            return! loop newState
                        with ex ->
                            stats.errorCount <- stats.errorCount + 1L
                            match! onError ex state with
                            | Some newState -> return! loop newState
                            | None ->
                                stats.lifecycle <- ActorLife.Failed ex
                                do! IVar.fill shutdownComplete ()
    

                    | ActorMsg.Shutdown reply ->
                        stats.lifecycle <- ActorLife.Stopping
                        do! IVar.fill reply ()
                        stats.lifecycle <- ActorLife.Stopped
                        do! IVar.fill shutdownComplete ()
    

                    | ActorMsg.Kill ->
                        stats.lifecycle <- ActorLife.Stopped
                        do! IVar.fill shutdownComplete ()
                }
    

                do! Job.start (loop initialState)
                return { channel = ch; stats = stats; shutdownComplete = shutdownComplete }
            }
    

        /// Send request and await reply (call pattern)
        let actorCall (handle: ActorRef<'req, 'reply>) (req: 'req) : Job<'reply> = job {
            let reply = IVar<'reply>()
            do! Ch.send handle.channel (ActorMsg.Request(req, reply))
            return! IVar.read reply
        }
    

        /// Send request with timeout
        let actorCallTimeout (timeoutMs: int) (handle: ActorRef<'req, 'reply>) (req: 'req) : Job<'reply option> =
            job {
                let reply = IVar<'reply>()
                do! Ch.send handle.channel (ActorMsg.Request(req, reply))
                return! jobWithTimeoutMs timeoutMs (IVar.read reply)
            }
    

        /// Fire and forget (cast pattern)
        let actorCast (handle: ActorRef<'req, 'reply>) (req: 'req) : Job<unit> =
            Ch.send handle.channel (ActorMsg.Fire req)
    

        /// Graceful shutdown with confirmation
        let actorShutdown (handle: ActorRef<_, _>) : Job<unit> = job {
            let reply = IVar<unit>()
            do! Ch.send handle.channel (ActorMsg.Shutdown reply)
            return! IVar.read reply
        }
    

        /// Immediate termination
        let actorKill (handle: ActorRef<_, _>) : Job<unit> =
            Ch.send handle.channel ActorMsg.Kill
    

        /// Wait for actor to complete
        let actorAwait (handle: ActorRef<_, _>) : Job<unit> =
            IVar.read handle.shutdownComplete
    

        /// Check if actor is alive
        let actorIsAlive (handle: ActorRef<_, _>) : bool =
            match handle.stats.lifecycle with
            | ActorLife.Running -> true
            | _ -> false
    
    
    



        // --- PATCH: supervision_tree (priority 11) ---
    

        // =========================================================================
        // SUPERVISION TREE - OTP-style (Rust tower / Gleam OTP compatible)
        // =========================================================================
    

        /// Supervision strategy (maps directly to Erlang/OTP)
        [<RequireQualifiedAccess>]
        type SuperStrategy =
            | OneForOne
            | OneForAll
            | RestForOne
    

        /// Child restart policy
        [<RequireQualifiedAccess>]
        type RestartPol =
            | Permanent
            | Temporary
            | Transient
    

        /// Child specification for supervisor
        type ChildSpec<'req, 'reply> = {
            id: string
            start: unit -> Job<ActorRef<'req, 'reply>>
            restart: RestartPol
            shutdownMs: int
        }
    

        /// Supervisor state tracking children
        type SuperState<'req, 'reply> = {
            strategy: SuperStrategy
            maxRestarts: int
            windowSec: float
            children: Map<string, ActorRef<'req, 'reply> * ChildSpec<'req, 'reply>>
            restartLog: (DateTime * string) list
        }
    

        /// Supervisor request messages
        [<RequireQualifiedAccess>]
        type SuperReq<'req, 'reply> =
            | StartChild of ChildSpec<'req, 'reply>
            | StopChild of string
            | RestartChild of string
            | ListChildren
            | GetStats
    

        /// Supervisor response messages
        [<RequireQualifiedAccess>]
        type SuperResp<'req, 'reply> =
            | Started of ActorRef<'req, 'reply>
            | Stopped
            | Restarted of ActorRef<'req, 'reply>
            | ChildList of string list
            | Stats of {| restarts: int; children: int |}
            | Error of string
    

        /// Create a supervisor actor
        let createSupervisor
            (name: string)
            (strategy: SuperStrategy)
            (maxRestarts: int)
            (windowSec: float)
            : Job<ActorRef<SuperReq<'req, 'reply>, SuperResp<'req, 'reply>>> =
    

            let init () = job {
                return {
                    strategy = strategy
                    maxRestarts = maxRestarts
                    windowSec = windowSec
                    children = Map.empty
                    restartLog = []
                }
            }
    

            let pruneLog (now: DateTime) (log: (DateTime * string) list) =
                log |> List.filter (fun (time, _) ->
                    (now - time).TotalSeconds < windowSec)
    

            let handle (state: SuperState<'req, 'reply>) (req: SuperReq<'req, 'reply>) = job {
                match req with
                | SuperReq.StartChild spec ->
                    let! child = spec.start()
                    let newChildren = Map.add spec.id (child, spec) state.children
                    return { state with children = newChildren },
                           Some (SuperResp.Started child)
    

                | SuperReq.StopChild id ->
                    match Map.tryFind id state.children with
                    | Some (child, _) ->
                        do! actorShutdown child
                        let newChildren = Map.remove id state.children
                        return { state with children = newChildren },
                               Some SuperResp.Stopped
                    | None ->
                        return state, Some (SuperResp.Error $"Child {id} not found")
    

                | SuperReq.RestartChild id ->
                    match Map.tryFind id state.children with
                    | Some (child, spec) ->
                        do! actorKill child
                        let! newChild = spec.start()
                        let newChildren = Map.add id (newChild, spec) state.children
                        let now = DateTime.UtcNow
                        let newLog = (now, id) :: pruneLog now state.restartLog
                        return { state with children = newChildren; restartLog = newLog },
                               Some (SuperResp.Restarted newChild)
                    | None ->
                        return state, Some (SuperResp.Error $"Child {id} not found")
    

                | SuperReq.ListChildren ->
                    let names = state.children |> Map.toList |> List.map fst
                    return state, Some (SuperResp.ChildList names)
    

                | SuperReq.GetStats ->
                    let stats = {|
                        restarts = state.restartLog.Length
                        children = state.children.Count
                    |}
                    return state, Some (SuperResp.Stats stats)
            }
    

            let onError (ex: exn) state = job {
                Common.trace Common.Critical
                    (fun () -> $"Supervisor {name} error: {ex.Message}")
                    Common._locals
                return Some state
            }
    

            spawnActor name init handle onError
    
    
    



        // --- PATCH: error_handling (priority 15) ---
    

        // =========================================================================
        // ENHANCED ERROR HANDLING & RECOVERY (Rust anyhow / Gleam result compatible)
        // =========================================================================
    

        /// Retry configuration
        type RetryConf = {
            maxAttempts: int
            initDelay: TimeSpan
            maxDelay: TimeSpan
            backoffMult: float
            shouldRetry: exn -> bool
        }
    

        /// Default retry config
        let defaultRetry = {
            maxAttempts = 3
            initDelay = TimeSpan.FromMilliseconds(100.0)
            maxDelay = TimeSpan.FromSeconds(10.0)
            backoffMult = 2.0
            shouldRetry = fun _ -> true
        }
    

        /// Retry with exponential backoff using Hopac
        let retryBackoff (conf: RetryConf) (work: Job<'a>) : Job<Result<'a, exn list>> =
            let rec loop (attempt: int) (delay: TimeSpan) (errors: exn list) = job {
                if attempt > conf.maxAttempts then
                    return Error (List.rev errors)
                else
                    try
                        let! result = work
                        return Ok result
                    with ex when conf.shouldRetry ex ->
                        if attempt = conf.maxAttempts then
                            return Error (List.rev (ex :: errors))
                        else
                            do! sleepMs (int delay.TotalMilliseconds)
                            let nextDelay =
                                TimeSpan.FromTicks(int64 (float delay.Ticks * conf.backoffMult))
                                |> min conf.maxDelay
                            return! loop (attempt + 1) nextDelay (ex :: errors)
            }
            loop 1 conf.initDelay []
    

        /// Fallback on error
        let withFallback (fallback: exn -> Job<'a>) (work: Job<'a>) : Job<'a> = job {
            try
                return! work
            with ex ->
                return! fallback ex
        }
    

        /// Recover with default value
        let recoverDefault (defaultValue: 'a) (work: Job<'a>) : Job<'a> = job {
            try
                return! work
            with _ ->
                return defaultValue
        }
    

        /// Ensure cleanup runs even on error
        let ensureCleanup (cleanup: Job<unit>) (work: Job<'a>) : Job<'a> = job {
            try
                let! result = work
                do! cleanup
                return result
            with ex ->
                do! cleanup
                return raise ex
        }
    

        /// Bracket pattern (acquire/use/release)
        let bracket
            (acquire: Job<'resource>)
            (release: 'resource -> Job<unit>)
            (useRes: 'resource -> Job<'a>)
            : Job<'a> = job {
            let! resource = acquire
            try
                let! result = useRes resource
                do! release resource
                return result
            with ex ->
                do! release resource
                return raise ex
        }
    
    
    



        // --- PATCH: memory_opts (priority 16) ---
    

        // =========================================================================
        // MEMORY OPTIMIZATIONS (Rust arena / Gleam bytes compatible)
        // =========================================================================
    

        /// Object pool for reducing allocations
        type ObjPool<'a> = {
            pool: System.Collections.Concurrent.ConcurrentBag<'a>
            factory: unit -> 'a
            reset: 'a -> unit
            maxSize: int
        }
    

        /// Create object pool
        let createObjPool (factory: unit -> 'a) (reset: 'a -> unit) (maxSize: int) : ObjPool<'a> = {
            pool = System.Collections.Concurrent.ConcurrentBag()
            factory = factory
            reset = reset
            maxSize = maxSize
        }
    

        /// Rent object from pool
        let poolRent (p: ObjPool<'a>) : 'a =
            match p.pool.TryTake() with
            | true, obj -> obj
            | _ -> p.factory()
    

        /// Return object to pool
        let poolReturn (p: ObjPool<'a>) (obj: 'a) : unit =
            if p.pool.Count < p.maxSize then
                p.reset obj
                p.pool.Add(obj)
    

        /// Use object from pool with automatic return
        let poolUse (p: ObjPool<'a>) (f: 'a -> Job<'b>) : Job<'b> = job {
            let obj = poolRent p
            try
                return! f obj
            finally
                poolReturn p obj
        }
    

        /// StringBuilder pool
        let sbPool =
            createObjPool
                (fun () -> System.Text.StringBuilder(1024))
                (fun sb -> sb.Clear() |> ignore)
                (capConcurrency Environment.ProcessorCount)
    

        /// Pooled string building
        let buildStr (f: System.Text.StringBuilder -> unit) : string =
            let sb = poolRent sbPool
            try
                f sb
                sb.ToString()
            finally
                poolReturn sbPool sb
    

        /// String intern table for deduplication
        type InternTable = {
            table: System.Collections.Concurrent.ConcurrentDictionary<string, string>
            mutable interned: int64
            mutable deduped: int64
        }
    

        let createInternTable () : InternTable = {
            table = System.Collections.Concurrent.ConcurrentDictionary()
            interned = 0L
            deduped = 0L
        }
    

        let internStr (t: InternTable) (s: string) : string =
            match t.table.TryGetValue(s) with
            | true, existing ->
                System.Threading.Interlocked.Increment(&t.deduped) |> ignore
                existing
            | _ ->
                t.table.[s] <- s
                System.Threading.Interlocked.Increment(&t.interned) |> ignore
                s
    

        /// Global string intern table
        let globalIntern = createInternTable()
    
    
    



        // --- PATCH: parallel_primitives (priority 20) ---
    

        // =========================================================================
        // PARALLEL EXECUTION PRIMITIVES (Rust rayon / Gleam gleam_otp compatible)
        // =========================================================================
    

        /// Parallel map with bounded concurrency using Hopac
        let parMapBounded (concurrency: int) (f: 'a -> Job<'b>) (items: 'a[]) : Job<'b[]> =
            let concurrency = capConcurrency concurrency
            if items.Length = 0 then Job.result [||]
            elif items.Length <= concurrency then
                items |> Array.map f |> Job.conCollect >>- fun (ra: ResizeArray<'b>) -> ra.ToArray()
            else
                job {
                    let results = Array.zeroCreate<'b> items.Length
                    let workQueue = System.Collections.Concurrent.ConcurrentQueue(
                        items |> Array.mapi (fun i x -> i, x))
                    let sem = new System.Threading.SemaphoreSlim(concurrency)
    

                    let processItem () = job {
                        let mutable cont = true
                        while cont do
                            do! Job.awaitUnitTask (sem.WaitAsync())
                            match workQueue.TryDequeue() with
                            | true, (idx, item) ->
                                try
                                    let! result = f item
                                    results.[idx] <- result
                                finally
                                    sem.Release() |> ignore
                            | false, _ ->
                                sem.Release() |> ignore
                                cont <- false
                    }
    

                    do! Seq.init (min concurrency items.Length) (fun _ -> processItem())
                        |> Job.conIgnore
                    return results
                }
    

        /// Parallel map with auto concurrency
        let parMap (f: 'a -> Job<'b>) (items: 'a[]) : Job<'b[]> =
            parMapBounded (capConcurrency Environment.ProcessorCount) f items
    

        /// Parallel iter with bounded concurrency
        let parIterBounded (concurrency: int) (f: 'a -> Job<unit>) (items: 'a[]) : Job<unit> =
            parMapBounded concurrency f items >>- ignore
    

        /// Parallel iter with auto concurrency
        let parIter (f: 'a -> Job<unit>) (items: 'a[]) : Job<unit> =
            parIterBounded (capConcurrency Environment.ProcessorCount) f items
    

        /// Parallel fold with associative combiner (tree reduction)
        let parFold (combine: 'b -> 'b -> 'b) (zero: 'b) (f: 'a -> Job<'b>) (items: 'a[]) : Job<'b> =
            if items.Length = 0 then Job.result zero
            else
                let dop = capConcurrency Environment.ProcessorCount
                let chunkSize = max 1 (items.Length / dop)
                let chunks = items |> Array.chunkBySize chunkSize
    

                job {
                    let! chunkResults =
                        chunks
                        |> Array.map (fun chunk ->
                            job {
                                let mutable acc = zero
                                for item in chunk do
                                    let! result = f item
                                    acc <- combine acc result
                                return acc
                            })
                        |> Job.conCollect >>- fun (ra: ResizeArray<'b>) -> ra.ToArray()
                    return Array.fold combine zero chunkResults
                }
    

        /// Scatter-gather pattern with workers
        let scatterGather (workers: int) (work: 'a -> Job<'b>) (items: 'a[]) : Job<'b[]> =
            parMapBounded workers work items
    

        /// Parallel filter
        let parFilter (pred: 'a -> Job<bool>) (items: 'a[]) : Job<'a[]> = job {
            let! flags = parMap pred items
            return
                Array.zip items flags
                |> Array.choose (fun (item, keep) -> if keep then Some item else None)
        }
    

        /// Parallel choose (filter + map)
        let parChoose (chooser: 'a -> Job<'b option>) (items: 'a[]) : Job<'b[]> = job {
            let! results = parMap chooser items
            return results |> Array.choose id
        }
    

        /// Race - return first completed result
        /// Note: This is a simple sequential fallback since Hopac Alt patterns are complex
        let raceJobs (jobs: Job<'a>[]) : Job<'a> =
            if jobs.Length = 0 then
                failwith "raceJobs requires at least one job"
            elif jobs.Length = 1 then
                jobs.[0]
            else
                // For now, just run first job (proper Alt-based race would be more complex)
                jobs.[0]
    

        /// All settled - wait for all, collecting results
        [<RequireQualifiedAccess>]
        type Settled<'a> =
            | Ok of 'a
            | Err of exn
    

        let allSettled (jobs: Job<'a>[]) : Job<Settled<'a>[]> =
            jobs
            |> Array.map (fun j ->
                job {
                    try
                        let! result = j
                        return Settled.Ok result
                    with ex ->
                        return Settled.Err ex
                })
            |> Job.conCollect >>- fun (ra: ResizeArray<Settled<'a>>) -> ra.ToArray()
    
    
    



        // --- PATCH: incremental_cache (priority 21) ---
    

        // =========================================================================
        // INCREMENTAL COMPUTATION CACHE (Rust salsa / Gleam memoization compatible)
        // =========================================================================
    

        /// Cache entry with generation tracking
        type CacheEntry<'v> = {
            generation: int64
            value: 'v
            deps: string Set
            computeMs: float
        }
    

        /// Incremental cache with dependency tracking
        type IncrCache<'k, 'v when 'k : equality and 'k : comparison> = {
            mutable gen: int64
            cache: System.Collections.Concurrent.ConcurrentDictionary<'k, CacheEntry<'v>>
            compute: 'k -> Job<'v * string Set>
            mutable hits: int64
            mutable misses: int64
        }
    

        /// Create a new incremental cache
        let createIncrCache<'k, 'v when 'k : equality and 'k : comparison>
            (compute: 'k -> Job<'v * string Set>)
            : IncrCache<'k, 'v> = {
            gen = 0L
            cache = System.Collections.Concurrent.ConcurrentDictionary()
            compute = compute
            hits = 0L
            misses = 0L
        }
    

        /// Get or compute value from cache
        let cacheGet (c: IncrCache<'k, 'v>) (key: 'k) : Job<'v> = job {
            let currentGen = c.gen
    

            match c.cache.TryGetValue(key) with
            | true, entry when entry.generation = currentGen ->
                System.Threading.Interlocked.Increment(&c.hits) |> ignore
                return entry.value
            | _ ->
                System.Threading.Interlocked.Increment(&c.misses) |> ignore
                let sw = System.Diagnostics.Stopwatch.StartNew()
                let! value, deps = c.compute key
                sw.Stop()
    

                let entry = {
                    generation = currentGen
                    value = value
                    deps = deps
                    computeMs = sw.Elapsed.TotalMilliseconds
                }
                c.cache.[key] <- entry
                return value
        }
    

        /// Invalidate specific key
        let cacheInvalidateKey (c: IncrCache<'k, 'v>) (key: 'k) : unit =
            c.cache.TryRemove(key) |> ignore
    

        /// Invalidate all entries (bump generation)
        let cacheInvalidateAll (c: IncrCache<_, _>) : unit =
            System.Threading.Interlocked.Increment(&c.gen) |> ignore
    

        /// Get cache statistics
        let cacheStats (c: IncrCache<_, _>) =
            let h = c.hits
            let m = c.misses
            {|
                hits = h
                misses = m
                hitRate = if h + m > 0L then float h / float (h + m) else 0.0
                entries = c.cache.Count
            |}
    
    
    



        // --- PATCH: stream_ops (priority 22) ---
    

        // =========================================================================
        // ENHANCED STREAM OPERATORS (using Hopac.Stream)
        // =========================================================================
    

        /// Parallel stream map with bounded concurrency
        let streamMapParBounded (conc: int) (f: 'a -> Job<'b>) (s: Stream<'a>) : Stream<'b> =
            let sem = new System.Threading.SemaphoreSlim(conc)
            s |> Stream.mapJob (fun x -> job {
                do! Job.awaitUnitTask (sem.WaitAsync())
                try
                    return! f x
                finally
                    sem.Release() |> ignore
            })
    

        /// Buffer and process in batches
        let streamBatch (batchSize: int) (s: Stream<'a>) : Stream<'a[]> =
            let rec loop buffer s =
                s >>= function
                | Cons(x, xs) ->
                    let newBuffer = x :: buffer
                    if List.length newBuffer >= batchSize then
                        Job.result (Cons(List.rev newBuffer |> Array.ofList, loop [] xs |> memo))
                    else
                        loop newBuffer xs
                | Nil ->
                    if List.isEmpty buffer then
                        Job.result Nil
                    else
                        Job.result (Cons(List.rev buffer |> Array.ofList, Job.result Nil |> memo))
            loop [] s |> memo
    

        /// Take first n items from stream
        let streamTake (n: int) (s: Stream<'a>) : Job<'a[]> =
            let results = ResizeArray()
            let rec loop count str = job {
                if count >= n then return ()
                else
                    let! item = str
                    match item with
                    | Cons(x, xs) ->
                        results.Add(x)
                        return! loop (count + 1) xs
                    | Nil -> return ()
            }
            loop 0 s >>- fun () -> results.ToArray()
    

        /// Merge multiple streams
        let streamMergeAll (streams: Stream<'a>[]) : Stream<'a> =
            if streams.Length = 0 then Stream.nil
            elif streams.Length = 1 then streams.[0]
            else
                streams |> Array.reduce Stream.merge
    
    
    



        // --- PATCH: backpressure (priority 23) ---
    

        // =========================================================================
        // BACKPRESSURE & RATE LIMITING (Rust tower / Gleam rate_limiter compatible)
        // =========================================================================
    

        /// Token bucket rate limiter
        type TokenBucket = {
            mutable tokens: float
            maxTokens: float
            refillRate: float
            mutable lastRefill: DateTime
            lockObj: obj
        }
    

        /// Create a token bucket rate limiter
        let createTokenBucket (maxTokens: float) (refillRate: float) : TokenBucket = {
            tokens = maxTokens
            maxTokens = maxTokens
            refillRate = refillRate
            lastRefill = DateTime.UtcNow
            lockObj = obj()
        }
    

        /// Try to acquire tokens from bucket
        let tryAcquire (bucket: TokenBucket) (count: float) : bool =
            lock bucket.lockObj (fun () ->
                let now = DateTime.UtcNow
                let elapsed = (now - bucket.lastRefill).TotalSeconds
                bucket.tokens <- min bucket.maxTokens (bucket.tokens + elapsed * bucket.refillRate)
                bucket.lastRefill <- now
    

                if bucket.tokens >= count then
                    bucket.tokens <- bucket.tokens - count
                    true
                else
                    false
            )
    

        /// Acquire tokens, waiting if necessary
        let acquireTokens (bucket: TokenBucket) (count: float) : Job<unit> =
            let rec loop () = job {
                if tryAcquire bucket count then
                    return ()
                else
                    let needed = count - bucket.tokens
                    let waitMs = int (needed / bucket.refillRate * 1000.0)
                    do! sleepMs (max 1 waitMs)
                    return! loop ()
            }
            loop ()
    

        /// Circuit breaker states
        [<RequireQualifiedAccess>]
        type CircuitSt =
            | Closed
            | Open
            | HalfOpen
    

        /// Circuit breaker for fault tolerance
        type CircuitBreaker = {
            mutable state: CircuitSt
            mutable failures: int
            mutable successes: int
            mutable lastFail: DateTime
            failThreshold: int
            successThreshold: int
            resetTimeout: TimeSpan
            lockObj: obj
        }
    

        /// Create a circuit breaker
        let createCircuitBreaker (failThreshold: int) (successThreshold: int) (resetTimeout: TimeSpan) : CircuitBreaker = {
            state = CircuitSt.Closed
            failures = 0
            successes = 0
            lastFail = DateTime.MinValue
            failThreshold = failThreshold
            successThreshold = successThreshold
            resetTimeout = resetTimeout
            lockObj = obj()
        }
    

        /// Execute with circuit breaker protection
        let withCircuit (cb: CircuitBreaker) (work: Job<'a>) : Job<Result<'a, string>> =
            let checkState () =
                lock cb.lockObj (fun () ->
                    match cb.state with
                    | CircuitSt.Open ->
                        if DateTime.UtcNow - cb.lastFail > cb.resetTimeout then
                            cb.state <- CircuitSt.HalfOpen
                            cb.successes <- 0
                            true
                        else
                            false
                    | _ -> true
                )
    

            let recordSuccess () =
                lock cb.lockObj (fun () ->
                    cb.failures <- 0
                    match cb.state with
                    | CircuitSt.HalfOpen ->
                        cb.successes <- cb.successes + 1
                        if cb.successes >= cb.successThreshold then
                            cb.state <- CircuitSt.Closed
                    | _ -> ()
                )
    

            let recordFail () =
                lock cb.lockObj (fun () ->
                    cb.failures <- cb.failures + 1
                    cb.lastFail <- DateTime.UtcNow
                    if cb.failures >= cb.failThreshold then
                        cb.state <- CircuitSt.Open
                )
    

            job {
                if checkState () then
                    try
                        let! result = work
                        recordSuccess ()
                        return Ok result
                    with ex ->
                        recordFail ()
                        return Error ex.Message
                else
                    return Error "Circuit breaker is open"
            }
    
    
    



        // --- PATCH: profiling (priority 24) ---
    

        // =========================================================================
        // PROFILING & METRICS (Rust metrics / Gleam telemetry compatible)
        // =========================================================================
    

        /// Simple counter
        type MetricCounter = {
            name: string
            mutable value: int64
        }
    

        let createCounter name : MetricCounter = { name = name; value = 0L }
        let counterInc (c: MetricCounter) : unit =
            System.Threading.Interlocked.Increment(&c.value) |> ignore
        let counterAdd (c: MetricCounter) (n: int64) : unit =
            System.Threading.Interlocked.Add(&c.value, n) |> ignore
    

        /// Simple gauge
        type MetricGauge = {
            name: string
            mutable value: float
        }
    

        let createGauge name : MetricGauge = { name = name; value = 0.0 }
        let gaugeSet (g: MetricGauge) (v: float) : unit = g.value <- v
        let gaugeInc (g: MetricGauge) : unit = g.value <- g.value + 1.0
        let gaugeDec (g: MetricGauge) : unit = g.value <- g.value - 1.0
    

        /// Histogram for timing distributions
        type MetricHistogram = {
            name: string
            buckets: int64[]
            boundaries: float[]
            mutable count: int64
            mutable sum: float
            mutable minVal: float
            mutable maxVal: float
        }
    

        /// Create histogram with exponential buckets
        let createHistogram (name: string) (minV: float) (maxV: float) (bucketCount: int) : MetricHistogram =
            let ratio = Math.Pow(maxV / minV, 1.0 / float bucketCount)
            {
                name = name
                buckets = Array.zeroCreate bucketCount
                boundaries = Array.init bucketCount (fun i -> minV * Math.Pow(ratio, float i))
                count = 0L
                sum = 0.0
                minVal = Double.MaxValue
                maxVal = Double.MinValue
            }
    

        /// Record a value in histogram
        let histRecord (h: MetricHistogram) (value: float) : unit =
            System.Threading.Interlocked.Increment(&h.count) |> ignore
            h.sum <- h.sum + value
            if value < h.minVal then h.minVal <- value
            if value > h.maxVal then h.maxVal <- value
            let idx =
                h.boundaries
                |> Array.tryFindIndex (fun b -> value < b)
                |> Option.defaultValue (h.buckets.Length - 1)
            System.Threading.Interlocked.Increment(&h.buckets.[idx]) |> ignore
    

        /// Timed execution with histogram recording
        let timedJob (histogram: MetricHistogram) (work: Job<'a>) : Job<'a> = job {
            let sw = System.Diagnostics.Stopwatch.StartNew()
            let! result = work
            sw.Stop()
            histRecord histogram sw.Elapsed.TotalMilliseconds
            return result
        }
    

        /// Timed execution returning duration
        let timedWithDur (work: Job<'a>) : Job<'a * TimeSpan> = job {
            let sw = System.Diagnostics.Stopwatch.StartNew()
            let! result = work
            sw.Stop()
            return result, sw.Elapsed
        }
    

        /// Global compiler metrics
        let mutable metricsTokenize = createHistogram "tokenize" 0.1 10000.0 20
        let mutable metricsParse = createHistogram "parse" 0.1 10000.0 20
        let mutable metricsTypecheck = createHistogram "typecheck" 0.1 10000.0 20
        let mutable metricsCodegen = createHistogram "codegen" 0.1 10000.0 20
    
    
    



        // --- PATCH: parallel_dep_graph (priority 25) ---
    

        // =========================================================================
        // PARALLEL DEPENDENCY GRAPH EXECUTION (using Hopac)
        // =========================================================================
    

        /// Node execution state
        [<RequireQualifiedAccess>]
        type NodeSt =
            | Pending
            | Ready
            | Running
            | Done
            | Failed of exn
    

        /// Dependency graph node
        type DepNode<'id, 'r when 'id : comparison> = {
            id: 'id
            deps: 'id Set
            mutable dependents: 'id Set
            mutable state: NodeSt
            mutable result: 'r option
            ready: IVar<unit>
            completed: IVar<Result<'r, exn>>
        }
    

        /// Parallel dependency graph
        type ParDepGraph<'id, 'r when 'id : equality and 'id : comparison> = {
            nodes: System.Collections.Concurrent.ConcurrentDictionary<'id, DepNode<'id, 'r>>
            readyQueue: Mailbox<'id>
            mutable pending: int
            mutable completed: int
            allDone: IVar<unit>
        }
    

        /// Create parallel dependency graph
        let createParDepGraph<'id, 'r when 'id : equality and 'id : comparison>()
            : ParDepGraph<'id, 'r> = {
            nodes = System.Collections.Concurrent.ConcurrentDictionary<'id, DepNode<'id, 'r>>()
            readyQueue = Mailbox<'id>()
            pending = 0
            completed = 0
            allDone = IVar<unit>()
        }
    

        /// Add node to graph
        let depGraphAdd (g: ParDepGraph<'id, 'r>) (id: 'id) (deps: 'id Set) : Job<unit> = job {
            let node = {
                id = id
                deps = deps
                dependents = Set.empty<'id>
                state = NodeSt.Pending
                result = None
                ready = IVar()
                completed = IVar()
            }
    

            g.nodes.[id] <- node
            g.pending <- g.pending + 1
    

            // Register as dependent
            for depId in deps do
                match g.nodes.TryGetValue(depId) with
                | true, depNode ->
                    depNode.dependents <- Set.add id depNode.dependents
                | _ -> ()
    

            // If no deps, mark ready
            if Set.isEmpty deps then
                node.state <- NodeSt.Ready
                do! Mailbox.send g.readyQueue id
        }
    

        /// Check if node is ready
        let private checkReady (g: ParDepGraph<'id, 'r>) (nodeId: 'id) : Job<unit> = job {
            match g.nodes.TryGetValue(nodeId) with
            | true, node ->
                let allDone =
                    node.deps |> Set.forall (fun depId ->
                        match g.nodes.TryGetValue(depId) with
                        | true, depNode ->
                            match depNode.state with
                            | NodeSt.Done -> true
                            | _ -> false
                        | _ -> true)
    

                if allDone && node.state = NodeSt.Pending then
                    node.state <- NodeSt.Ready
                    do! Mailbox.send g.readyQueue nodeId
            | _ -> ()
        }
    

        /// Execute dependency graph with workers
        let depGraphExec
            (g: ParDepGraph<'id, 'r>)
            (exec: 'id -> Job<'r>)
            (workers: int)
            : Job<Map<'id, Result<'r, exn>>> = job {
    

            let results = System.Collections.Concurrent.ConcurrentDictionary<'id, Result<'r, exn>>()
    

            let worker = job {
                let mutable cont = true
                while cont do
                    let! nodeIdOpt =
                        (Mailbox.take g.readyQueue |> Alt.afterFun Some)
                        <|>
                        (IVar.read g.allDone |> Alt.afterFun (fun _ -> None))
    

                    match nodeIdOpt with
                    | Some id ->
                        match g.nodes.TryGetValue(id) with
                        | true, node ->
                            node.state <- NodeSt.Running
                            try
                                let! result = exec id
                                node.state <- NodeSt.Done
                                node.result <- Some result
                                results.[id] <- Ok result
                                do! IVar.fill node.completed (Ok result)
    

                                // Notify dependents
                                for depId in node.dependents do
                                    do! checkReady g depId
                            with ex ->
                                node.state <- NodeSt.Failed ex
                                results.[id] <- Error ex
                                do! IVar.fill node.completed (Error ex)
    

                            g.completed <- g.completed + 1
                            if g.completed = g.pending then
                                do! IVar.tryFill g.allDone ()
                                cont <- false
                        | _ -> ()
                    | None ->
                        cont <- false
            }
    

            // Start workers
            do! Seq.init workers (fun _ -> Job.start worker) |> Job.conIgnore
    

            // Wait for completion
            do! IVar.read g.allDone
    

            return results |> Seq.map (fun kv -> kv.Key, kv.Value) |> Map.ofSeq
        }
    
    
    



        // --- PATCH: watchdog (priority 28) ---
    

        // =========================================================================
        // WATCHDOG & HEALTH MONITORING (using Hopac)
        // =========================================================================
    

        /// Health check result
        [<RequireQualifiedAccess>]
        type HealthSt =
            | Healthy
            | Degraded of string
            | Unhealthy of string
    

        /// Component health
        type CompHealth = {
            name: string
            status: HealthSt
            lastCheck: DateTime
            responseMs: float option
        }
    

        /// System health
        type SysHealth = {
            overall: HealthSt
            components: CompHealth list
            uptime: TimeSpan
            startTime: DateTime
        }
    

        /// Health check function
        type HealthCheck = string -> Job<CompHealth>
    

        /// Watchdog config
        type WatchdogConf = {
            checkIntervalMs: int
            unhealthyThreshold: int
            timeout: TimeSpan
        }
    

        /// Watchdog state
        type WatchdogSt = {
            conf: WatchdogConf
            checks: Map<string, HealthCheck>
            mutable lastCheck: DateTime
            startTime: DateTime
        }
    

        /// Create watchdog
        let createWatchdog (conf: WatchdogConf) : WatchdogSt = {
            conf = conf
            checks = Map.empty
            lastCheck = DateTime.UtcNow
            startTime = DateTime.UtcNow
        }
    

        /// Register health check
        let watchdogRegister (name: string) (check: HealthCheck) (w: WatchdogSt) : WatchdogSt =
            { w with checks = Map.add name check w.checks }
    

        /// Run health checks
        let watchdogRun (w: WatchdogSt) : Job<SysHealth> = job {
            w.lastCheck <- DateTime.UtcNow
    

            let! results =
                w.checks
                |> Map.toArray
                |> Array.map (fun (name, check) -> job {
                    try
                        let! resultOpt = jobWithTimeoutMs (int w.conf.timeout.TotalMilliseconds) (check name)
                        match resultOpt with
                        | Some health -> return health
                        | None ->
                            return {
                                name = name
                                status = HealthSt.Unhealthy "Timeout"
                                lastCheck = DateTime.UtcNow
                                responseMs = None
                            }
                    with ex ->
                        return {
                            name = name
                            status = HealthSt.Unhealthy ex.Message
                            lastCheck = DateTime.UtcNow
                            responseMs = None
                        }
                })
                |> Job.conCollect
    

            let overall =
                if results |> Seq.forall (fun r -> r.status = HealthSt.Healthy) then
                    HealthSt.Healthy
                elif results |> Seq.exists (fun r -> match r.status with HealthSt.Unhealthy _ -> true | _ -> false) then
                    HealthSt.Unhealthy "Component unhealthy"
                else
                    HealthSt.Degraded "Component degraded"
    

            return {
                overall = overall
                components = results |> Seq.toList
                uptime = DateTime.UtcNow - w.startTime
                startTime = w.startTime
            }
        }
    

        /// Memory health check
        let memoryHealthCheck (maxMb: int64) : HealthCheck =
            fun name -> job {
                let usedMb = GC.GetTotalMemory(false) / (1024L * 1024L)
                let status =
                    if usedMb > maxMb then HealthSt.Unhealthy $"Memory: {usedMb}MB > {maxMb}MB"
                    elif usedMb > maxMb * 80L / 100L then HealthSt.Degraded $"Memory high: {usedMb}MB"
                    else HealthSt.Healthy
                return {
                    name = name
                    status = status
                    lastCheck = DateTime.UtcNow
                    responseMs = None
                }
            }
    
    
    



        // --- PATCH: compile_pipeline (priority 29) ---
    

        // =========================================================================
        // PARALLEL COMPILE PIPELINE ENHANCEMENTS (using Hopac)
        // =========================================================================
    

        /// Compilation stage result
        type StageRes<'a> = {
            result: 'a
            durationMs: float
            errors: (int * int * string) list
            warnings: (int * int * string) list
        }
    

        /// Module compile context
        type ModuleCtx = {
            path: string
            source: string
            hash: string
            deps: string Set
            tokenized: Job<StageRes<obj>>
            parsed: Job<StageRes<obj>>
            typechecked: Job<StageRes<obj>>
            codegen: System.Collections.Concurrent.ConcurrentDictionary<string, Job<StageRes<string>>>
        }
    

        /// Package compile context
        type PackageCtx = {
            id: int
            path: string
            modules: System.Collections.Concurrent.ConcurrentDictionary<string, ModuleCtx>
            depOrder: string[]
            pkgEnv: Job<obj>
        }
    

        /// Compile coordinator
        type CompileCoord = {
            packages: System.Collections.Concurrent.ConcurrentDictionary<string, PackageCtx>
            moduleCache: IncrCache<string, ModuleCtx>
            workers: int
            mutable modulesCompiled: int64
            mutable packagesCompiled: int64
            mutable cacheHits: int64
        }
    

        /// Create compile coordinator
        let createCompileCoord (workers: int) : CompileCoord = {
            packages = System.Collections.Concurrent.ConcurrentDictionary()
            moduleCache = createIncrCache (fun path -> job {
                return Unchecked.defaultof<ModuleCtx>, Set.empty
            })
            workers = workers
            modulesCompiled = 0L
            packagesCompiled = 0L
            cacheHits = 0L
        }
    

        /// Compile module with pipeline
        let compileModulePipeline (coord: CompileCoord) (path: string) (source: string) : Job<ModuleCtx> = job {
            let hash = source.GetHashCode().ToString()
    

            System.Threading.Interlocked.Increment(&coord.modulesCompiled) |> ignore
    

            // Create promises for each stage using Hopac.memo
            let tokenized =
                job {
                    let sw = System.Diagnostics.Stopwatch.StartNew()
                    // Tokenize here
                    sw.Stop()
                    return { result = obj(); durationMs = sw.Elapsed.TotalMilliseconds; errors = []; warnings = [] }
                } |> Hopac.memo
    

            let parsed =
                job {
                    let! _ = tokenized
                    let sw = System.Diagnostics.Stopwatch.StartNew()
                    // Parse here
                    sw.Stop()
                    return { result = obj(); durationMs = sw.Elapsed.TotalMilliseconds; errors = []; warnings = [] }
                } |> Hopac.memo
    

            let typechecked =
                job {
                    let! _ = parsed
                    let sw = System.Diagnostics.Stopwatch.StartNew()
                    // Typecheck here
                    sw.Stop()
                    return { result = obj(); durationMs = sw.Elapsed.TotalMilliseconds; errors = []; warnings = [] }
                } |> Hopac.memo
    

            return {
                path = path
                source = source
                hash = hash
                deps = Set.empty
                tokenized = tokenized
                parsed = parsed
                typechecked = typechecked
                codegen = System.Collections.Concurrent.ConcurrentDictionary()
            }
        }
    

        /// Compile package with parallel modules
        let compilePackagePipeline
            (coord: CompileCoord)
            (pkgPath: string)
            (modulePaths: string[])
            (readSource: string -> Job<string>)
            : Job<PackageCtx> = job {
    

            let pkgId = pkgPath.GetHashCode()
            System.Threading.Interlocked.Increment(&coord.packagesCompiled) |> ignore
    

            let moduleCtxs = System.Collections.Concurrent.ConcurrentDictionary<string, ModuleCtx>()
    

            // Compile all modules in parallel
            do! parIterBounded coord.workers (fun path -> job {
                    let! source = readSource path
                    let! ctx = compileModulePipeline coord path source
                    moduleCtxs.[path] <- ctx
                }) modulePaths
    

            // Compute package env
            let pkgEnv =
                job {
                    let! moduleResults =
                        moduleCtxs.Values
                        |> Seq.map (fun ctx -> ctx.typechecked)
                        |> Seq.toArray
                        |> Job.conCollect
                    return obj()
                } |> Hopac.memo
    

            let ctx = {
                id = pkgId
                path = pkgPath
                modules = moduleCtxs
                depOrder = modulePaths
                pkgEnv = pkgEnv
            }
    

            coord.packages.[pkgPath] <- ctx
            return ctx
        }
    
    
    



        // --- PATCH: hot_reload (priority 30) ---
    

        // =========================================================================
        // HOT RELOAD SUPPORT (using Hopac)
        // =========================================================================
    

        /// File change event
        [<RequireQualifiedAccess>]
        type FileEvt =
            | Created of string
            | Modified of string
            | Deleted of string
            | Renamed of string * string
    

        /// File watcher state
        type FileWatcherSt = {
            watcher: System.IO.FileSystemWatcher
            events: Mailbox<FileEvt>
            debounceMs: int
            pending: System.Collections.Concurrent.ConcurrentDictionary<string, DateTime>
        }
    

        /// Create file watcher with debouncing
        let createFileWatcher (dir: string) (pattern: string) (debounceMs: int) : Job<FileWatcherSt> = job {
            let events = Mailbox<FileEvt>()
            let pending = System.Collections.Concurrent.ConcurrentDictionary<string, DateTime>()
    

            let watcher = new System.IO.FileSystemWatcher(dir)
            watcher.NotifyFilter <-
                System.IO.NotifyFilters.LastWrite |||
                System.IO.NotifyFilters.FileName |||
                System.IO.NotifyFilters.Size
            watcher.Filter <- pattern
            watcher.IncludeSubdirectories <- true
    

            let sendDebounced path evt =
                pending.[path] <- DateTime.UtcNow
                start (job {
                    do! sleepMs debounceMs
                    match pending.TryGetValue(path) with
                    | true, time when (DateTime.UtcNow - time).TotalMilliseconds >= float debounceMs ->
                        pending.TryRemove(path) |> ignore
                        start (Mailbox.send events evt)
                    | _ -> ()
                })
    

            watcher.Changed.Add(fun e ->
                sendDebounced e.FullPath (FileEvt.Modified e.FullPath))
            watcher.Created.Add(fun e ->
                sendDebounced e.FullPath (FileEvt.Created e.FullPath))
            watcher.Deleted.Add(fun e ->
                start (Mailbox.send events (FileEvt.Deleted e.FullPath)))
            watcher.Renamed.Add(fun e ->
                start (Mailbox.send events (FileEvt.Renamed(e.OldFullPath, e.FullPath))))
    

            watcher.EnableRaisingEvents <- true
    

            return {
                watcher = watcher
                events = events
                debounceMs = debounceMs
                pending = pending
            }
        }
    

        /// Process file changes in batches
        let processChanges
            (fw: FileWatcherSt)
            (handler: FileEvt[] -> Job<unit>)
            (batchTimeoutMs: int)
            : Job<unit> =
    

            let rec loop (batch: FileEvt list) (deadline: DateTime option) = job {
                let! evtOpt =
                    match deadline with
                    | Some d ->
                        let remaining = (d - DateTime.UtcNow).TotalMilliseconds |> int
                        if remaining <= 0 then
                            Job.result None
                        else
                            jobWithTimeoutMs remaining (Mailbox.take fw.events)
                    | None ->
                        job {
                            let! evt = Mailbox.take fw.events
                            return Some evt
                        }
    

                match evtOpt with
                | Some evt ->
                    let newBatch = evt :: batch
                    let newDeadline =
                        deadline
                        |> Option.defaultValue (DateTime.UtcNow.AddMilliseconds(float batchTimeoutMs))
                        |> Some
                    return! loop newBatch newDeadline
    

                | None when not (List.isEmpty batch) ->
                    do! handler (List.rev batch |> Array.ofList)
                    return! loop [] None
    

                | None ->
                    return! loop [] None
            }
    

            loop [] None
    

        /// Stop file watcher
        let stopFileWatcher (fw: FileWatcherSt) : unit =
            fw.watcher.EnableRaisingEvents <- false
            fw.watcher.Dispose()
    

        /// Parallel map for pure functions (sync), bounded via ParallelOptions.
        /// This is intentionally *not* Hopac-based to avoid deadlocks if called inside running Hopac Jobs.
        let parMapBoundedSync (concurrency: int) (f: 'a -> 'b) (items: 'a[]) : 'b[] =
            if obj.ReferenceEquals(items, null) then nullArg "items"
            if items.Length = 0 then [||]
            elif items.Length = 1 then [| f items.[0] |]
            else
                let results = Array.zeroCreate<'b> items.Length
                let opts = System.Threading.Tasks.ParallelOptions()
                opts.MaxDegreeOfParallelism <- max 1 concurrency
                let first_exn_lock = obj()
                let mutable first_exn : (int * exn) option = None
                System.Threading.Tasks.Parallel.For(
                    0, items.Length, opts,
                    System.Action<int,System.Threading.Tasks.ParallelLoopState>(fun i loop_state ->
                        if not loop_state.ShouldExitCurrentIteration then
                            try
                                results.[i] <- f items.[i]
                            with ex ->
                                lock first_exn_lock (fun () ->
                                    match first_exn with
                                    | None -> first_exn <- Some (i, ex)
                                    | Some _ -> ())
                                loop_state.Stop())
                    ) |> ignore
                match first_exn with
                | Some (i, ex) ->
                    try
                        DiagSidecar.emit (sprintf "[spiral_compiler] PAR_MAP_BOUNDED_SYNC parMapBoundedSync worker exception index=%d concurrency=%d items=%d type=%s message=%s" i (max 1 concurrency) items.Length (ex.GetType().FullName) ex.Message)
                    with _ -> ()
                    System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(ex).Throw()
                    Unchecked.defaultof<'b[]>
                | None -> results
    

        // Parallel execution layer - uses all CPU cores by default
        let mutable private forcedConcurrency = 0
        do getForcedConcurrency <- (fun () -> System.Threading.Volatile.Read(&forcedConcurrency))
    

        /// Override concurrency for diagnostics/debugging
        let forceConcurrency (n: int) =
            let n = max 1 n
            System.Threading.Volatile.Write(&forcedConcurrency, n)
            DiagSidecar.emit (sprintf "HopacExtensions.forceConcurrency: %d" n)
    

        let clearForcedConcurrency () =
            System.Threading.Volatile.Write(&forcedConcurrency, 0)
            DiagSidecar.emit "HopacExtensions.clearForcedConcurrency"
    
        // ALPHA400: no env-var DOP policy.  Parallelism is hardcoded to ProcessorCount unless

        // retry code explicitly forces sequential execution.
        let private hardcodedEnvDop () : int = 0

        let envForcedConcurrency () : int = hardcodedEnvDop ()

        let peekForcedConcurrency () : int = System.Threading.Volatile.Read(&forcedConcurrency)

        let applyEnvForcedConcurrency () =
            ()

        let forceConcurrencyForRetry (n: int) =
            forceConcurrency n

        let clearForcedConcurrencyForRetry () =
            clearForcedConcurrency ()

        /// Get effective concurrency: forced value or ProcessorCount
        let defaultConcurrency () : int =
            let forced = System.Threading.Volatile.Read(&forcedConcurrency)
            if forced > 0 then forced
            else max 1 System.Environment.ProcessorCount
    

        do
            Progress88.set_extra_provider (fun () ->
                let forced = System.Threading.Volatile.Read(&forcedConcurrency)
                if forced > 0 then $"dop={forced}" else $"dop={max 1 System.Environment.ProcessorCount}")
    

        // Parallel array ops with bounded concurrency (preserves index order)
        module A =
            let inline map (f: 'a -> 'b) (xs: 'a[]) : 'b[] =
                parMapBoundedSync (defaultConcurrency()) f xs
    

            let inline mapi (f: int -> 'a -> 'b) (xs: 'a[]) : 'b[] =
                if xs.Length = 0 then [||]
                elif xs.Length = 1 then [| f 0 xs.[0] |]
                else
                    let results = Array.zeroCreate<'b> xs.Length
                    let opts = System.Threading.Tasks.ParallelOptions(MaxDegreeOfParallelism = max 1 (defaultConcurrency()))
                    System.Threading.Tasks.Parallel.For(0, xs.Length, opts, fun i ->
                        results.[i] <- f i xs.[i]
                    ) |> ignore
                    results
    
    


            let inline map2 (f: 'a -> 'b -> 'c) (xs: 'a[]) (ys: 'b[]) : 'c[] =
                if xs.Length <> ys.Length then invalidArg "ys" "Array lengths do not match in map2."
                if xs.Length = 0 then [||]
                elif xs.Length = 1 then [| f xs.[0] ys.[0] |]
                else
                    let results = Array.zeroCreate<'c> xs.Length
                    let opts = System.Threading.Tasks.ParallelOptions(MaxDegreeOfParallelism = max 1 (defaultConcurrency()))
                    System.Threading.Tasks.Parallel.For(0, xs.Length, opts, fun i ->
                        results.[i] <- f xs.[i] ys.[i]
                    ) |> ignore
                    results
    

            let inline iter (f: 'a -> unit) (xs: 'a[]) : unit =
                if xs.Length = 0 then ()
                elif xs.Length = 1 then f xs.[0]
                else
                    let opts = System.Threading.Tasks.ParallelOptions(MaxDegreeOfParallelism = max 1 (defaultConcurrency()))
                    System.Threading.Tasks.Parallel.For(0, xs.Length, opts, fun i ->
                        f xs.[i]
                    ) |> ignore
    

            let inline iteri (f: int -> 'a -> unit) (xs: 'a[]) : unit =
                if xs.Length = 0 then ()
                elif xs.Length = 1 then f 0 xs.[0]
                else
                    let opts = System.Threading.Tasks.ParallelOptions(MaxDegreeOfParallelism = max 1 (defaultConcurrency()))
                    System.Threading.Tasks.Parallel.For(0, xs.Length, opts, fun i ->
                        f i xs.[i]
                    ) |> ignore
    

            let inline choose (f: 'a -> 'b option) (xs: 'a[]) : 'b[] =
                // Primeiro mapeia em paralelo, depois filtra em ordem (estável) num passo sequencial.
                let tmp = map f xs
                Microsoft.FSharp.Collections.Array.choose id tmp
    

            let inline collect (f: 'a -> 'b[]) (xs: 'a[]) : 'b[] =
                // Primeiro gera chunks em paralelo, depois achata em ordem.
                let chunks = map f xs
                Microsoft.FSharp.Collections.Array.collect id chunks
    
    


        // Array ops sequenciais (para trechos com estado mutável não-thread-safe).
        module S =
            let inline map (f: 'a -> 'b) (xs: 'a[]) : 'b[] = Microsoft.FSharp.Collections.Array.map f xs
            let inline mapi (f: int -> 'a -> 'b) (xs: 'a[]) : 'b[] = Microsoft.FSharp.Collections.Array.mapi f xs
            let inline iter (f: 'a -> unit) (xs: 'a[]) : unit = Microsoft.FSharp.Collections.Array.iter f xs
            let inline iteri (f: int -> 'a -> unit) (xs: 'a[]) : unit = Microsoft.FSharp.Collections.Array.iteri f xs
            let inline choose (f: 'a -> 'b option) (xs: 'a[]) : 'b[] = Microsoft.FSharp.Collections.Array.choose f xs
            let inline collect (f: 'a -> 'b[]) (xs: 'a[]) : 'b[] = Microsoft.FSharp.Collections.Array.collect f xs
    

    open HopacExtensions
    open Hopac
    open Hopac.Infixes
    open Hopac.Extensions
    open Hopac.Stream
    
    
    
    
    





    // open FSharpx.Collections
    

    /// ### Bundle
    // These bundles are top statements that have their range offsets distributed into them.
    type [<ReferenceEquality>] Bundle =
        | BundleType of VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr
        | BundleNominal of VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr
        | BundleNominalRec of (VSCRange * (VSCRange * VarString) * HoVar list * RawTExpr) list
        | BundleInl of Comments * VSCRange * (VSCRange * VarString) * RawExpr * is_top_down: bool
        | BundleRecInl of (Comments * VSCRange * (VSCRange * VarString) * RawExpr) list * is_top_down: bool
        | BundlePrototype of Comments * VSCRange * (VSCRange * VarString) * (VSCRange * VarString) * TypeVar list * RawTExpr
        | BundleInstance of VSCRange * (VSCRange * VarString) * (VSCRange * VarString) * TypeVar list * RawExpr
        | BundleOpen of VSCRange * (VSCRange * VarString) * (VSCRange * SymbolString) list
    

    /// ### bundle_range
    let bundle_range = function
        | BundleType(r,_,_,_) | BundleNominal(r,_,_,_) | BundleInl(_,r,_,_,_)
        | BundlePrototype(_,r,_,_,_,_) | BundleInstance(r,_,_,_,_) | BundleOpen(r,_,_) -> r
        | BundleNominalRec l -> List.head l |> fun (r,_,_,_) -> r
        | BundleRecInl(l,_) -> List.head l |> fun (_,r,_,_) -> r
    

    /// ### add_offset
    let add_offset offset (range : VSCRange) : VSCRange =
        let f (a : VSCPos) = {|a with line=offset + a.line|}
        let a,b = range
        f a, f b
    

    /// ### add_offset_hovar
    let add_offset_hovar offset (a,b) = add_offset offset a, b
    

    /// ### add_offset_hovar_list
    let add_offset_hovar_list offset x = List.map (add_offset_hovar offset) x
    

    /// ### add_offset_typevar
    let add_offset_typevar offset ((a,b),c) = (add_offset offset a, b), add_offset_hovar_list offset c
    

    /// ### add_offset_typevar_list
    let add_offset_typevar_list offset x = List.map (add_offset_typevar offset) x
    

    /// ### fold_offset_ty
    let rec fold_offset_ty offset x =
        let f = fold_offset_ty offset
        let g = add_offset offset
        match x with
        | RawTWildcard r -> RawTWildcard(g r)
        | RawTLit(r,a) -> RawTLit(g r, a)
        | RawTB r -> RawTB(g r)
        | RawTMetaVar(r,a) -> RawTMetaVar(g r,a)
        | RawTVar(r,a) -> RawTVar(g r,a)
        | RawTArray(r,a) -> RawTArray(g r,f a)
        | RawTPair(r,a,b) -> RawTPair(g r,f a,f b)
        | RawTFun(r,a,b,t) -> RawTFun(g r,f a,f b,t)
        | RawTRecord(r,a) -> RawTRecord(g r,Map.map (fun _ -> f) a)
        | RawTUnion(r,a,b,c) -> RawTUnion(g r,Map.map (fun _ (is_gadt,body) -> is_gadt, f body) a,b,f c)
        | RawTTypecase(r,a,b) -> RawTTypecase(g r,f a,List.map (fun (a,b) -> f a, f b) b)
        | RawTSymbol(r,a) -> RawTSymbol(g r,a)
        | RawTApply(r,a,b) -> RawTApply(g r,f a,f b)
        | RawTForall(r,a,b) -> RawTForall(g r,add_offset_typevar offset a,f b)
        | RawTExists(r,a,b) -> RawTExists(g r,add_offset_typevar_list offset a,f b)
        | RawTPrim(r,a) -> RawTPrim(g r,a)
        | RawTTerm(r,a) -> RawTTerm(g r,fold_offset_term offset a)
        | RawTMacro(r,a) -> RawTMacro(g r,fold_offset_macro offset a)
        | RawTFilledNominal(r,a) -> RawTFilledNominal(g r,a)
        | RawTLayout(r,a,b) -> RawTLayout(g r,f a,b)
    and fold_offset_macro offset a =
        let g = add_offset offset
        List.map (function
            | RawMacroText(r,a) -> RawMacroText(g r,a)
            | RawMacroTerm(r,a,b) -> RawMacroTerm(g r,fold_offset_term offset a,b)
            | RawMacroType(r,a) -> RawMacroType(g r,fold_offset_ty offset a)
            | RawMacroTypeLit(r,a) -> RawMacroTypeLit(g r,fold_offset_ty offset a)
            ) a
    and fold_offset_term offset x =
        let f = fold_offset_term offset
        let ty = fold_offset_ty offset
        let g = add_offset offset
        match x with
        | RawB r -> RawB (g r)
        | RawV(r,a,b) -> RawV (g r,a,b)
        | RawLit(r,a) -> RawLit (g r,a)
        | RawDefaultLit(r,a) -> RawDefaultLit (g r,a)
        | RawSymbol(r,a) -> RawSymbol (g r,a)
        | RawType(r,a) -> RawType(g r, ty a)
        | RawMatch(r,a,b) -> RawMatch(g r,f a,List.map (fun (a,b) -> fold_offset_pattern offset a,f b) b)
        | RawFun(r,a) -> RawFun(g r,List.map (fun (a,b) -> fold_offset_pattern offset a,f b) a)
        | RawForall(r,a,b) -> RawForall(g r,add_offset_typevar offset a,f b)
        | RawExists(r,(r',a),b) -> RawExists(g r,(g r',Option.map (List.map ty) a),f b)
        | RawFilledForall(r,a,b) -> RawFilledForall(g r,a,f b)
        | RawRecBlock(r,a,b) -> RawRecBlock(g r,List.map (fun ((r,a),b) -> (g r,a),f b) a,f b)
        | RawRecordWith(r,a,b,c) ->
            let b =
                b |> List.map (function
                    | RawRecordWithSymbol((r,a),b) -> RawRecordWithSymbol((g r,a),f b)
                    | RawRecordWithSymbolModify((r,a),b) -> RawRecordWithSymbolModify((g r,a),f b)
                    | RawRecordWithInjectVar((r,a),b) -> RawRecordWithInjectVar((g r,a),f b)
                    | RawRecordWithInjectVarModify((r,a),b) -> RawRecordWithInjectVarModify((g r,a),f b)
                    )
            let c =
                c |> List.map (function
                    | RawRecordWithoutSymbol(r,a) -> RawRecordWithoutSymbol(g r,a)
                    | RawRecordWithoutInjectVar(r,a) -> RawRecordWithoutInjectVar(g r,a)
                    )
            RawRecordWith(g r, List.map f a,b,c)
        | RawOp(r,a,b) -> RawOp(g r,a,List.map f b)
        | RawJoinPoint(r,q,a,b) -> RawJoinPoint(g r,Option.map (fun (r',w) -> g r',w) q,f a,b)
        | RawAnnot(r,a,b) -> RawAnnot(g r,f a,ty b)
        | RawTypecase(r,a,b) -> RawTypecase(g r,ty a,List.map (fun (a,b) -> ty a,f b) b)
        | RawOpen(r,a,b,c) -> RawOpen(g r,add_offset_hovar offset a,add_offset_hovar_list offset b,f c)
        | RawApply(r,a,b) -> RawApply(g r,f a,f b)
        | RawIfThenElse(r,a,b,c) -> RawIfThenElse(g r,f a,f b,f c)
        | RawIfThen(r,a,b) -> RawIfThen(g r,f a,f b)
        | RawPair(r,a,b) -> RawPair(g r,f a,f b)
        | RawSeq(r,a,b) -> RawSeq(g r,f a,f b)
        | RawHeapMutableSet(r,a,b,c) -> RawHeapMutableSet(g r,f a,List.map f b,f c)
        | RawReal(r,a) -> RawReal(g r,f a)
        | RawMissingBody r -> RawMissingBody(g r)
        | RawMacro(r,a) -> RawMacro(g r,fold_offset_macro offset a)
        | RawArray(r,a) -> RawArray(g r,List.map f a)
    and fold_offset_pattern offset x =
        let f = fold_offset_pattern offset
        let term = fold_offset_term offset
        let ty = fold_offset_ty offset
        let g = add_offset offset
        let g' x = add_offset_hovar offset x
        match x with
        | PatFilledDefaultValue _ -> failwith "Compiler error: Later stages only."
        | PatB r -> PatB(g r)
        | PatE r -> PatE(g r)
        | PatVar(r,a) -> PatVar(g r,a)
        | PatDyn(r,a) -> PatDyn(g r,f a)
        | PatUnbox(r,q,a) -> PatUnbox(g r,q,f a)
        | PatAnnot(r,a,b) -> PatAnnot(g r,f a,ty b)
        | PatPair(r,a,b) -> PatPair(g r,f a,f b)
        | PatSymbol(r,a) -> PatSymbol(g r,a)
        | PatRecordMembers(r,a) ->
            let a = a |> List.map (function
                | PatRecordMembersSymbol((r,a),b) -> PatRecordMembersSymbol((g r,a),f b)
                | PatRecordMembersInjectVar((r,a),b) -> PatRecordMembersInjectVar((g r,a),f b)
                )
            PatRecordMembers(g r,a)
        | PatOr(r,a,b) -> PatOr(g r,f a,f b)
        | PatAnd(r,a,b) -> PatAnd(g r,f a,f b)
        | PatValue(r,a) -> PatValue(g r,a)
        | PatDefaultValue(r,a) -> PatDefaultValue(g r,a)
        | PatWhen(r,a,b) -> PatWhen(g r,f a,term b)
        | PatNominal(r,a,b,c) -> PatNominal(g r,g' a,List.map g' b,f c)
        | PatExists(r,a,b) -> PatExists(g r,List.map g' a,f b)
        | PatArray(r,a) -> PatArray(g r,List.map f a)
    

    /// ### bundle_blocks
    let bundle_blocks (blocks : TopStatement Block list) =
        match blocks with
        | [] -> None
        | {block=TopAnd _} :: x' -> failwith "Compiler error: TopAnd should be eliminated during the first bundling step."
        | {block=TopRecInl _} :: _ as l ->
            l |> List.mapFold (fun _ -> function
                | {offset=i; block=TopRecInl(com,r,a,b,c)} -> (com, add_offset i r, add_offset_hovar i a, fold_offset_term i b), c
                | _ -> failwith "Compiler error: Recursive inl statements can only be followed by statements of the same type."
                ) true
            |> BundleRecInl |> Some
        | {block=TopNominalRec _} :: _ as l ->
            l |> List.map (function
                | {offset=i; block=TopNominalRec(r,a,b,c)} -> (add_offset i r, add_offset_hovar i a, add_offset_hovar_list i b, fold_offset_ty i c)
                | _ -> failwith "Compiler error: Recursive type statements can only be followed by statements of the same type."
                )
            |> BundleNominalRec |> Some
        | [{offset=i; block=TopInl(com,r,a,b,c)}] -> BundleInl(com, add_offset i r, add_offset_hovar i a, fold_offset_term i b, c) |> Some
        | [{offset=i; block=TopPrototype(com,r,a,b,c,d)}] -> BundlePrototype(com,add_offset i r, add_offset_hovar i a, add_offset_hovar i b, add_offset_typevar_list i c, fold_offset_ty i d) |> Some
        | [{offset=i; block=TopNominal(r,a,b,c)}] -> BundleNominal(add_offset i r, add_offset_hovar i a, add_offset_hovar_list i b, fold_offset_ty i c) |> Some
        | [{offset=i; block=TopType(r,a,b,c)}] -> BundleType(add_offset i r, add_offset_hovar i a, add_offset_hovar_list i b, fold_offset_ty i c) |> Some
        | [{offset=i; block=TopInstance(r,a,b,c,d)}] -> BundleInstance(add_offset i r, add_offset_hovar i a, add_offset_hovar i b, add_offset_typevar_list i c, fold_offset_term i d) |> Some
        | [{offset=i; block=TopOpen(r,a,b)}] -> BundleOpen(add_offset i r, add_offset_hovar i a, add_offset_hovar_list i b) |> Some
        | {block=TopInl _ | TopPrototype _ | TopNominal _ | TopType _ | TopInstance _ | TopOpen _} :: _ -> failwith "Compiler error: Regular top level statements should be singleton bundles."
    

    /// ### add_line_to_range
    let add_line_to_range line ((a,b) : VSCRange) = {|a with line=line+a.line|}, {|b with line=line+b.line|}
    

    /// ### process_error
    let process_error v =
        let messages, expecteds = v |> List.distinct |> List.partition (fun x -> System.Char.IsUpper(x,0))
        let ex () = match expecteds with [x] -> sprintf "Expected: %s" x | x -> sprintf "Expected one of: %s" (String.concat ", " x)
        let f l = String.concat "\n" l
        if List.isEmpty expecteds then f messages
        elif List.isEmpty messages then ex ()
        else f (ex () :: "" :: "Other error messages:" :: messages)
    

    /// ### show_block_parsing_error
    let show_block_parsing_error line (l : ParserErrorsList) : RString list =
        l |> List.groupBy fst
        |> List.map (fun (k,v) ->
            let k = add_line_to_range line k
            let v = List.map (snd >> show_parser_error) v
            k, process_error v
            )
    

    /// ### ParsedBlock
    type ParsedBlock = {result : ParseResult; semantic_tokens : LineTokens}
    

    /// ### ParserState
    type ParserState = {
        is_top_down : bool
        blocks : (LineTokens * ParsedBlock Promise Block) list
        }
    

    /// ### BlockBundleValue
    type BlockBundleValue = {bundle : Bundle option; errors : RString list}
    

    /// ### BlockBundleState
    type BlockBundleState = (TopStatement Block list * BlockBundleValue) Stream
    

    /// ### BlockBundleStateInner
    type BlockBundleStateInner = {errors : RString list; tmp : TopStatement Block list; state : BlockBundleState}
    

    /// ### wdiff_block_bundle_init
    let wdiff_block_bundle_init : BlockBundleState = Promise.Now.never()
    

    /// ### wdiff_block_bundle
    /// Bundles the blocks with the `and` statements. Also collects the parser errors.
    /// Does diffing to ref preserve the bundles.
    let wdiff_block_bundle (state : BlockBundleState) (l : ParserState) : BlockBundleState =
        let (+.) a b = add_line_to_range a b
    

        let empty = {state=wdiff_block_bundle_init; tmp=[]; errors=[]}
        let move_temp (s : BlockBundleStateInner) next =
            let o' = List.rev s.tmp
            let fl () = (o',{bundle=bundle_blocks o'; errors=Seq.toList s.errors}), next empty
            if Promise.Now.isFulfilled s.state then
                match Promise.Now.get s.state with
                | Cons((o,q),xs) when o = o' -> (o,{bundle=q.bundle; errors=Seq.toList s.errors}), next {state=xs; tmp=[]; errors=[]}
                | _ -> fl ()
            else fl ()
            |> Cons |> Promise.Now.withValue
    

        let inline iter (s : BlockBundleStateInner) l f =
            match l with
            | (_,x) :: x' -> let offset = x.offset in x.block >>** fun {result=a} -> f (offset,a,x')
            | [] -> move_temp s (fun _ -> Promise.Now.withValue Nil)
        let rec init (s : BlockBundleStateInner) l = iter s l <| fun (offset,x,x') ->
            match x with
            | Ok (TopAnd(r,_)) -> init {s with errors = (offset +. r, "Invalid `and` statement.") :: s.errors} x'
            | Ok (TopRecInl _ as a) -> recinl {s with tmp = {offset=offset; block=a} :: s.tmp} x'
            | Ok (TopNominalRec _ as a) -> rectype {s with tmp = {offset=offset; block=a} :: s.tmp} x'
            | Ok a -> move_temp {s with tmp = {offset=offset; block=a} :: s.tmp} (fun s -> init s x')
            | Error er -> init {s with errors = List.append (show_block_parsing_error offset er) s.errors} x'
        and recinl (s : BlockBundleStateInner) l = iter s l <| fun (offset,x,x') ->
            match x with
            | Ok (TopAnd(_, TopRecInl _ & a)) -> recinl {s with tmp = {offset=offset; block=a} :: s.tmp} x'
            | Ok (TopAnd(r, _)) -> recinl {s with errors = (offset +. r, "inl/let recursive statements can only be followed by `and` inl/let statements.") :: s.errors} x'
            | Ok _ -> move_temp s (fun s -> init s l)
            | Error er -> recinl {s with errors = List.append (show_block_parsing_error offset er) s.errors} x'
        and rectype (s : BlockBundleStateInner) l = iter s l <| fun (offset,x,x') ->
            match x with
            | Ok (TopAnd(_, TopNominalRec _ & a)) -> rectype {s with tmp = {offset=offset; block=a} :: s.tmp} x'
            | Ok (TopAnd(r, _)) -> rectype {s with errors = (offset +. r, "`union rec` can only be followed by `and union`.") :: s.errors} x'
            | Ok _ -> move_temp s (fun s -> init s l)
            | Error er -> rectype {s with errors = List.append (show_block_parsing_error offset er) s.errors} x'
    

        init {empty with state=state} l.blocks
    

    /// ### semantic_tokens
    let semantic_tokens (l : ParserState) =
        let rec loop s = function
            | (_,x) :: xs -> x.block >>= fun x -> loop (PersistentVector.append s x.semantic_tokens) xs
            | [] -> Job.result s
        loop PersistentVector.empty l.blocks
    

    /// ## Infer
    

    /// ### 'a ref'
    type [<ReferenceEquality>] 'a ref' = {mutable contents' : 'a}
    

    /// ### TT
    type TT =
        | KindType
        | KindFun of TT * TT
        | KindMetavar of TT option ref'
    

    /// ### Constraint
    type Constraint =
        | CUInt
        | CSInt
        | CInt
        | CFloat
        | CNumber
        | CPrim
        | CSymbol
        | CRecord
        | CPrototype of GlobalId
    

    /// ### ConstraintOrModule
    type ConstraintOrModule = C of Constraint | M of Map<string,ConstraintOrModule>
    

    /// ### Var
    type [<ReferenceEquality>] Var = {
        scope : int
        constraints : Constraint Set // Must be stated up front and needs to be static in forall vars
        kind : TT // Is not supposed to have metavars.
        name : string // Is what gets printed.
        }
    

    /// ### MVar
    type [<ReferenceEquality>] MVar = {
        mutable scope : int
        mutable constraints : Constraint Set // Must be stated up front and needs to be static in forall vars
        kind : TT // Has metavars, and so is mutable.
        }
    

    /// ### TM
    type TM =
        | TMText of string
        | TMVar of T
        | TMLitVar of T
    and T =
        | TyB
        | TyLit of Literal
        | TyPrim of PrimitiveType
        | TySymbol of string
        | TyPair of T * T
        | TyRecord of Map<int * string, T>
        | TyModule of Map<string, T>
        | TyComment of Comments * T
        | TyFun of T * T * FunType
        | TyArray of T
        | TyNominal of GlobalId
        | TyUnion of Map<int * string,bool * T> * UnionLayout // The boolean arg determines whether the union case is generalized.
        | TyApply of T * T * TT // Regular type functions (TyInl) get reduced, while this represents the staged reduction of nominals.
        | TyInl of Var * T
        | TyForall of Var * T
        | TyExists of Var list * T
        | TyMetavar of MVar * T option ref
        | TyVar of Var * T option ref
        | TyMacro of TM list
        | TyLayout of T * Layout
    

    /// ### tyvar
    let tyvar x = TyVar(x, ref None)
    

    /// ### TypeError
    type TypeError =
        | KindError of TT * TT
        | KindErrorInConstraint of TT * TT
        | ExpectedSymbolAsRecordKey of T
        | ExpectedSymbolAsModuleKey of T
        | UnboundVariable of string
        | UnboundModule
        | ModuleIndexFailedInOpen
        | ModuleIndexWouldShadowLocalVars of string []
        | TermError of T * T
        | TypeVarScopeError of string * T * T
        | RecursiveMetavarsNotAllowed of T * T
        | RecursiveTypevarsNotAllowed of T * T
        | ForallVarConstraintError of string * Constraint Set * Constraint Set
        | MetavarsNotAllowedInRecordWith
        | ExpectedRecord of T
        | ExpectedExistentialInTerm of T
        | ExpectedExistentialInPattern of T
        | UnexpectedNumberOfArgumentsInExistsPattern of got: int * expected: int
        | UnexpectedNumberOfArgumentsInExistsBody of got: int * expected: int
        | ExistsShouldntHaveMetavars of T list
        | ExpectedRecordInsideALayout of T
        | UnionsCannotBeApplied
        | ExpectedNominalInApply of T
        | MalformedNominal
        | LayoutSetMustBeAnnotated
        | ExpectedMutableLayout of T
        | ExpectedRecordAsResultOfIndex of T
        | RecordIndexFailed of string
        | ModuleIndexFailed of string
        | ExpectedModule of T
        | ExpectedSymbol' of T
        | ExpectedSymbolInRecordWith of T
        | RealFunctionInTopDown
        | ModuleMustBeImmediatelyApplied
        | MissingRecordFieldsInPattern of T * string list
        | CasePatternNotFoundForType of GlobalId * string
        | CasePatternNotFound of string
        | CannotInferCasePatternFromTermInEnv of T
        | NominalInPatternUnbox of GlobalId
        | TypeInEnvIsNotNominal of T
        | UnionInPatternNominal of GlobalId
        | ConstraintError of Constraint * T
        | PrototypeConstraintCannotPropagateToMetavar of GlobalId * T
        | PrototypeConstraintCannotPropagateToVar of GlobalId * T
        | ExpectedAnnotation
        | ExpectedSinglePattern
        | RecursiveAnnotationHasMetavars of T
        | ValueRestriction of T
        | DuplicateRecInlName
        | DuplicateKeyInRecUnion
        | ExpectedConstraintInsteadOfModule
        | InstanceNotFound of prototype: GlobalId * instance: GlobalId
        | ExpectedPrototypeConstraint of Constraint
        | ExpectedPrototypeInsteadOfModule
        | ExpectedHigherOrder of T
        | InstanceArityError of prototype_arity: int * instance_arity: int
        | InstanceCoreVarsShouldMatchTheArityDifference of got: int * expected: int
        | InstanceKindError of TT * TT
        | KindNotAllowedInInstanceForall
        | InstanceVarShouldNotMatchAnyOfPrototypes
        | MissingBody
        | MacroIsMissingAnnotation
        | ArrayIsMissingAnnotation
        | ExistsIsMissingAnnotation
        | ShadowedForall
        | ShadowedExists
        | UnionTypesMustHaveTheSameLayout
        | OrphanInstance
        | ShadowedInstance
        | UnusedTypeVariable of string list
        | CompilerError of string
        | IncorrectGADTConstructorType
        | IncorrectRecursiveNominal
    

    /// ### shorten'<'a>
    let inline shorten'<'a> (x : 'a) link next =
        let x' : 'a = next x
        if System.Object.ReferenceEquals(x,x') = false then link.contents' <- Some x'
        x'
    

    /// ### visit_tt
    let rec visit_tt = function
        | KindMetavar({contents'=Some x} & link) -> shorten' x link visit_tt
        | a -> a
    

    /// ### shorten<'a>
    let inline shorten<'a> (x : 'a) (link : ref<option<'a>>) next =
        let x' : 'a = next x
        if System.Object.ReferenceEquals(x,x') = false then link.Value <- Some x'
        x'
    

    /// ### visit_t_mvar
    let rec visit_t_mvar = function
        | TyComment(_,a) -> visit_t_mvar a
        | TyMetavar(_,{contents=Some x} & link) -> shorten x link visit_t_mvar
        | a -> a
    

    /// ### visit_t
    let rec visit_t x =
        match visit_t_mvar x with
        | TyVar(_,{contents=Some x}) -> visit_t x
        | x -> x
    

    /// ### InferTypeErrorException
    exception InferTypeErrorException of (VSCRange * TypeError) list
    

    /// ### metavars
    let rec metavars = function
        | RawTTypecase _ | RawTExists _ | RawTFilledNominal _ | RawTMacro _ | RawTVar _ | RawTTerm _
        | RawTPrim _ | RawTWildcard _ | RawTLit _ | RawTB _ | RawTSymbol _ -> Set.empty
        | RawTMetaVar(_,a) -> Set.singleton a
        | RawTArray(_,a) | RawTLayout(_,a,_) | RawTForall(_,_,a) -> metavars a
        | RawTPair(_,a,b) | RawTApply(_,a,b) | RawTFun(_,a,b,_) -> metavars a + metavars b
        | RawTUnion(_,l,_,this) -> Map.fold (fun s _ (_,v) -> s + metavars v) (metavars this) l
        | RawTRecord(_,l) -> Map.fold (fun s _ v -> s + metavars v) Set.empty l
    

    /// ### TopEnv
    type TopEnv = {
        nominals_next_tag : int
        nominals_aux : Map<GlobalId, {|name : string; kind : TT|}>
        nominals : Map<GlobalId, {|vars : Var list; body : T|}>
        prototypes_next_tag : int
        prototypes_instances : Map<GlobalId * GlobalId, Constraint Set list>
        prototypes : Map<GlobalId, {|name : string; signature: T; kind : TT|}>
        ty : Map<string,T>
        term : Map<string,T>
        constraints : Map<string,ConstraintOrModule>
        }
    

    /// ### inferTop_env_empty
    let inferTop_env_empty = {
        nominals_next_tag = 0
        nominals_aux = Map.empty
        nominals = Map.empty
        prototypes_next_tag = 0
        prototypes_instances = Map.empty
        prototypes = Map.empty
        ty = Map.empty
        term = Map.empty
        constraints = Map.empty
        }
    

    /// ### inferUnion
    let inferUnion small big = {
        nominals_next_tag = max small.nominals_next_tag big.nominals_next_tag
        nominals_aux = Map.foldBack Map.add small.nominals_aux big.nominals_aux
        nominals = Map.foldBack Map.add small.nominals big.nominals
        prototypes_next_tag = max small.prototypes_next_tag big.prototypes_next_tag
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        prototypes = Map.foldBack Map.add small.prototypes big.prototypes
        ty =
            Map.foldBack (fun k v s ->
                let v =
                    match v, s |> Map.tryFind k with
                    | TyModule x, Some (TyModule x') -> Map.foldBack Map.add x x' |> TyModule
                    | _ -> v
                s |> Map.add k v
            ) small.ty big.ty
        term =
            Map.foldBack (fun k v s ->
                let v =
                    match v, s |> Map.tryFind k with
                    | TyModule x, Some (TyModule x') -> Map.foldBack Map.add x x' |> TyModule
                    | _ -> v
                s |> Map.add k v
            ) small.term big.term
        constraints =
            Map.foldBack (fun k v s ->
                let v =
                    match v, s |> Map.tryFind k with
                    | M x, Some (M x') -> Map.foldBack Map.add x x' |> M
                    | _ -> v
                s |> Map.add k v
            ) small.constraints big.constraints
        }
    

    /// ### inferIn_module
    let inferIn_module m a : TopEnv =
        {a with
            ty = Map.add m (TyModule a.ty) Map.empty
            term = Map.add m (TyModule a.term) Map.empty
            constraints = Map.add m (M a.constraints) Map.empty
            }
    

    /// ### InferEnv
    type InferEnv = { ty : Map<string,T>; term : Map<string,T>; constraints : Map<string,ConstraintOrModule> }
    /// ### loc_env
    let loc_env (x: TopEnv) : InferEnv = { term = x.term; ty = x.ty; constraints = x.constraints }
    

    /// ### lit
    let lit = function
        | LitUInt8 _ -> TyPrim UInt8T
        | LitUInt16 _ -> TyPrim UInt16T
        | LitUInt32 _ -> TyPrim UInt32T
        | LitUInt64 _ -> TyPrim UInt64T
        | LitInt8 _ -> TyPrim Int8T
        | LitInt16 _ -> TyPrim Int16T
        | LitInt32 _ -> TyPrim Int32T
        | LitInt64 _ -> TyPrim Int64T
        | LitFloat32 _ -> TyPrim Float32T
        | LitFloat64 _ -> TyPrim Float64T
        | LitBool _ -> TyPrim BoolT
        | LitString _ -> TyPrim StringT
        | LitChar _ -> TyPrim CharT
    
    


    /// ### kind_get
    let kind_get x =
        let rec loop = function
            | KindFun(a,b) -> a :: loop b
            | a -> [a]
        let l = loop x
        {|arity=List.length l; args=l|}
    

    /// ### prototype_init_forall_kind
    let prototype_init_forall_kind = function
        | TyForall(a,_) -> a.kind
        | _ -> failwith "Compiler error: The prototype should have at least one forall."
    

    /// ### show_primt
    let show_primt = function
        | UInt8T -> "u8"
        | UInt16T -> "u16"
        | UInt32T -> "u32"
        | UInt64T -> "u64"
        | Int8T -> "i8"
        | Int16T -> "i16"
        | Int32T -> "i32"
        | Int64T -> "i64"
        | Float32T -> "f32"
        | Float64T -> "f64"
        | BoolT -> "bool"
        | StringT -> "string"
        | CharT -> "char"
    

    /// ### constraint_name
    let rec constraint_name (env : TopEnv) = function
        | CSInt -> "sint" | CUInt -> "uint" | CInt -> "int"
        | CFloat -> "float" | CNumber -> "number" | CPrim -> "prim"
        | CSymbol -> "symbol" | CRecord -> "record"
        | CPrototype i -> env.prototypes.[i].name
    

    /// ### constraint_kind
    let constraint_kind (env : TopEnv) = function
        | CSInt | CUInt | CInt | CFloat | CNumber | CPrim | CSymbol | CRecord -> KindType
        | CPrototype i -> env.prototypes.[i].kind
    

    /// ### tt
    let rec tt (env : TopEnv) = function
        | TyComment(_,x) | TyMetavar(_,{contents=Some x}) -> tt env x
        | TyNominal i -> env.nominals_aux.[i].kind
        | TyApply(_,_,x) | TyMetavar({kind=x},_) | TyVar({kind=x},_) -> x
        | TyExists _ | TyLit _ | TyUnion _ | TyLayout _ | TyMacro _ | TyB | TyPrim _ | TyForall _ | TyFun _ | TyRecord _ | TyModule _ | TyPair _ | TySymbol _ | TyArray _ -> KindType
        | TyInl(v,a) -> KindFun(v.kind,tt env a)
    

    /// ### has_metavars
    let rec has_metavars x =
        let f = has_metavars
        match visit_t x with
        | TyMetavar _ -> true
        | TyVar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ | TyModule _ -> false
        | TyExists(_,a) | TyComment(_,a) | TyLayout(a,_) | TyForall(_,a) | TyInl(_,a) | TyArray a -> f a
        | TyApply(a,b,_) | TyFun(a,b,_) | TyPair(a,b) -> f a || f b
        | TyUnion(l,_) -> Map.exists (fun _ -> snd >> f) l
        | TyRecord l -> Map.exists (fun _ -> f) l
        | TyMacro a -> List.exists (function TMVar x -> has_metavars x | _ -> false) a
    

    /// ### term_subst
    // Eliminates the metavars in the type if possible.
    let term_subst a =
        let h = System.Collections.Generic.HashSet(HashIdentity.Reference)
        // 'a = 'b = ('c = int * 'd = float)
        // visit_t shortens to:
        // 'a = ('c = int * 'd = float)
        // visit_t returns:
        // ('c = int * 'd = float)
        // term_subst returns:
        // int * float
        let inline g a f =
            let _ = h.Add(a)
            let x = f()
            let _ = h.Remove(a)
            x
        let rec f a =
            match visit_t a with
            | TyMetavar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ as x -> x
            | TyVar(x,r) -> TyVar(x, if h.Contains x then ref None else r)
            | TyComment(a,b) -> TyComment(a,f b)
            | TyPair(a,b) -> TyPair(f a, f b)
            | TyRecord a -> TyRecord(Map.map (fun _ -> f) a)
            | TyModule a -> TyModule(Map.map (fun _ -> f) a)
            | TyUnion(a,b) -> TyUnion(Map.map (fun _ (is_gadt, x) -> is_gadt, f x) a,b)
            | TyFun(a,b,t) -> TyFun(f a, f b, t)
            | TyForall(a,b) -> g a <| fun () -> TyForall(a,f b)
            | TyExists(a,b) -> TyExists(a,f b)
            | TyArray a -> TyArray(f a)
            | TyApply(a,b,c) -> TyApply(f a, f b, c)
            | TyInl(a,b) -> g a <| fun () -> TyInl(a,f b)
            | TyMacro a -> TyMacro(List.map (function TMVar x -> TMVar(f x) | x -> x) a)
            | TyLayout(a,b) -> TyLayout(f a,b)
        f a
    

    /// ### HoverTypes
    type HoverTypes() =
        // This is to allocate less trash for code that doesn't use GADTs.
        // Unfortunately, we cannot use memoization instead as term_subst is not functionally pure.
        let rec has_substituted_tvars x =
            let f = has_substituted_tvars
            match x with
            | TyMetavar(_,{contents=Some _}) -> true
            | TyVar (_, {contents=Some x}) | TyComment(_,x) -> f x
            | TyVar _ | TyMetavar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ | TyModule _ -> false
            | TyExists(_,a) | TyComment(_,a) | TyLayout(a,_) | TyForall(_,a) | TyInl(_,a) | TyArray a -> f a
            | TyApply(a,b,_) | TyFun(a,b,_) | TyPair(a,b) -> f a || f b
            | TyUnion(l,_) -> Map.exists (fun _ -> snd >> f) l
            | TyRecord l -> Map.exists (fun _ -> f) l
            | TyMacro a -> List.exists (function TMVar x -> has_metavars x | _ -> false) a
        let hover_types = ResizeArray()
        member _.AddHover((r : VSCRange),(x,(com : string))) = hover_types.Add(r,((if has_substituted_tvars x then term_subst x else x), com))
        member _.ToArray() = hover_types.ToArray()
    

    /// ### inferModule_open
    let inferModule_open (hover_types : HoverTypes option) (top_env : InferEnv) (local_env_ty : Map<string,T>) (r : VSCRange) b l =
        let tryFind env x =
            match Map.tryFind x env.term, Map.tryFind x env.ty, Map.tryFind x env.constraints with
            | Some (TyModule a), Some (TyModule b), Some (M c) -> ValueSome {term=a; ty=b; constraints=c}
            | _ -> ValueNone
        match tryFind top_env b with
        | ValueNone -> Error(r, UnboundModule)
        | ValueSome env ->
            hover_types |> Option.iter (fun hover_types -> hover_types.AddHover(r,(TyModule env.term,"")))
            let rec loop env = function
                | (r,x) :: x' ->
                    match tryFind env x with
                    | ValueSome env ->
                        hover_types |> Option.iter (fun hover_types -> hover_types.AddHover(r,(TyModule env.term,"")))
                        loop env x'
                    | _ -> Error(r, ModuleIndexFailedInOpen)
                | [] -> Ok env
            loop env l |> Result.bind (fun env ->
                let h = ResizeArray()
                local_env_ty |> Map.iter (fun k _ -> if env.ty.ContainsKey k then h.Add k)
                if h.Count > 0 then Error(r, ModuleIndexWouldShadowLocalVars(h.ToArray()))
                else Ok env
                )
    

    /// ### validate_bound_vars
    let validate_bound_vars (top_env : InferEnv) constraints term ty x =
        let errors = ResizeArray()
        let check_term term (a,b) = if Set.contains b term = false && Map.containsKey b top_env.term = false then errors.Add(a,UnboundVariable b)
        let check_ty ty (a,b) = if Set.contains b ty = false && Map.containsKey b top_env.ty = false then errors.Add(a,UnboundVariable b)
        let check_cons constraints (a,b) =
            match Map.tryFind b constraints |> Option.orElseWith (fun () -> Map.tryFind b top_env.constraints) with
            | Some (C _) -> ()
            | Some (M _) -> errors.Add(a,ExpectedConstraintInsteadOfModule)
            | None -> errors.Add(a,UnboundVariable b)
        let rec cterm constraints (term, ty) x =
            match x with
            | RawSymbol _ | RawDefaultLit _ | RawLit _ | RawB _ -> ()
            | RawV(a,b,_) -> check_term term (a,b)
            | RawType(_,x) -> ctype constraints term ty x
            | RawMatch(_,body,l) -> cterm constraints (term, ty) body; List.iter (fun (a,b) -> cterm constraints (cpattern constraints term ty a) b) l
            | RawFun(_,l) -> List.iter (fun (a,b) -> cterm constraints (cpattern constraints term ty a) b) l
            | RawForall(_,((_,(a,_)),l),b) -> List.iter (check_cons constraints) l; cterm constraints (term, Set.add a ty) b
            | RawFilledForall _ -> failwith "Compiler error: Should not appear during variable validation."
            | RawRecBlock(_,l,on_succ) ->
                let term = List.fold (fun s ((_,x),_) -> Set.add x s) term l
                List.iter (fun (_,x) -> cterm constraints (term, ty) x) l
                cterm constraints (term, ty) on_succ
            | RawRecordWith(_,a,b,c) ->
                List.iter (cterm constraints (term, ty)) a
                List.iter (function
                    | RawRecordWithSymbol(_,e) | RawRecordWithSymbolModify(_,e) -> cterm constraints (term, ty) e
                    | RawRecordWithInjectVar(v,e) | RawRecordWithInjectVarModify(v,e) -> check_term term v; cterm constraints (term, ty) e
                    ) b
                List.iter (function RawRecordWithoutSymbol _ -> () | RawRecordWithoutInjectVar (a,b) -> check_term term (a,b)) c
            | RawOp(_,_,l) -> List.iter (cterm constraints (term, ty)) l
            | RawReal(_,x) | RawJoinPoint(_,_,x,_) -> cterm constraints (term, ty) x
            | RawExists(_,(_,a),b) -> Option.iter (List.iter (ctype constraints term ty)) a; cterm constraints (term, ty) b
            | RawAnnot(_,RawMacro(_,a),b) -> cmacro constraints term ty a; ctype constraints term ty b
            | RawMacro(r,a) -> errors.Add(r,MacroIsMissingAnnotation); cmacro constraints term ty a
            | RawAnnot(_,RawArray(_,a),b) -> List.iter (cterm constraints (term, ty)) a; ctype constraints term ty b
            | RawArray(r,a) -> errors.Add(r,ArrayIsMissingAnnotation); List.iter (cterm constraints (term, ty)) a
            | RawAnnot(_,a,b) -> cterm constraints (term, ty) a; ctype constraints term ty b
            | RawTypecase(_,a,b) ->
                ctype constraints term ty a
                List.iter (fun (a,b) ->
                    ctype constraints term ty a
                    cterm constraints (term, ty + metavars a) b
                    ) b
            | RawOpen(_,(a,b),l,on_succ) ->
                match inferModule_open None top_env Map.empty a b l with
                | Ok x ->
                    let combine e m = Map.fold (fun s k _ -> Set.add k s) e m
                    cterm (Map.foldBack Map.add x.constraints constraints) (combine term x.term, combine ty x.ty) on_succ
                | Error e -> errors.Add(e)
            | RawHeapMutableSet(_,a,b,c) -> cterm constraints (term, ty) a; List.iter (cterm constraints (term, ty)) b; cterm constraints (term, ty) c
            | RawSeq(_,a,b) | RawPair(_,a,b) | RawIfThen(_,a,b) | RawApply(_,a,b) -> cterm constraints (term, ty) a; cterm constraints (term, ty) b
            | RawIfThenElse(_,a,b,c) -> cterm constraints (term, ty) a; cterm constraints (term, ty) b; cterm constraints (term, ty) c
            | RawMissingBody r -> errors.Add(r,MissingBody)
        and cmacro constraints term ty a =
            List.iter (function
                | RawMacroText _ -> ()
                | RawMacroTerm(r,a,_) -> cterm constraints (term, ty) a
                | RawMacroType(r,a) | RawMacroTypeLit(r,a) -> ctype constraints term ty a
                ) a
        and ctype constraints term ty x =
            match x with
            | RawTFilledNominal(_,_) | RawTPrim _ | RawTWildcard _ | RawTLit _ | RawTB _ | RawTSymbol _ | RawTMetaVar _ -> ()
            | RawTTypecase(_,a,b) ->
                ctype constraints term ty a
                List.iter (fun (a,b) ->
                    ctype constraints term ty a
                    ctype constraints term (ty + metavars a) b
                    ) b
            | RawTVar(a,b) -> check_ty ty (a,b)
            | RawTArray(_,a) | RawTLayout(_,a,_) -> ctype constraints term ty a
            | RawTPair(_,a,b) | RawTApply(_,a,b) | RawTFun(_,a,b,_) -> ctype constraints term ty a; ctype constraints term ty b
            | RawTUnion(_,l,_,this) -> Map.iter (fun _ (_,x) -> ctype constraints term ty x) l; ctype constraints term ty this
            | RawTRecord(_,l) -> Map.iter (fun _ -> ctype constraints term ty) l
            | RawTForall(_,((_,(a,_)),l),b) -> List.iter (check_cons constraints) l; ctype constraints term (Set.add a ty) b
            | RawTExists(_,a,b) ->
                let ty =
                    List.fold (fun ty ((_,(a,_)),l) ->
                        List.iter (check_cons constraints) l
                        Set.add a ty
                        ) ty a
                ctype constraints term ty b
            | RawTTerm (_,a) -> cterm constraints (term, ty) a
            | RawTMacro(_,a) -> cmacro constraints term ty a
        and cpattern constraints term ty x =
            //let is_first = System.Collections.Generic.HashSet()
            let rec loop (term, ty) x =
                let f = loop (term, ty)
                match x with
                | PatDefaultValue _ | PatFilledDefaultValue _ | PatValue _ | PatSymbol _ | PatB _ | PatE _ -> term, ty
                | PatExists(_,a,b) ->
                    let ty = List.fold (fun s (_,x) -> Set.add x s) ty a
                    loop (term, ty) b
                | PatVar(_,b) ->
                    //if is_first.Add b then () // TODO: I am doing it like this so I can reuse this code later for variable highlighting.
                    Set.add b term, ty
                | PatDyn(_,x) | PatUnbox(_,_,x) -> f x
                | PatPair(_,a,b) -> loop (f a) b
                | PatRecordMembers(_,l) ->
                    List.fold (fun s -> function
                        | PatRecordMembersSymbol(_,x) -> loop s x
                        | PatRecordMembersInjectVar((a,b),x) -> check_term term (a,b); loop s x
                        ) (term, ty) l
                | PatAnd(_,a,b) | PatOr(_,a,b) -> loop (loop (term, ty) a) b
                | PatAnnot(_,a,b) -> ctype constraints term ty b; f a
                | PatWhen(_,a,b) -> let r = f a in cterm constraints r b; r
                | PatNominal(_,(r,a),_,b) -> check_ty ty (r,a); f b
                | PatArray(_,a) -> List.fold loop (term, ty) a
            loop (term, ty) x
    

        match x with
        | Choice1Of2 x -> cterm constraints (term, ty) x
        | Choice2Of2 x -> ctype constraints term ty x
        errors
    

    /// ### assert_bound_vars
    let assert_bound_vars (top_env : InferEnv) constraints term ty x =
        let errors = validate_bound_vars top_env constraints term ty x
        if 0 < errors.Count then raise (InferTypeErrorException (Seq.toList errors))
    

    /// ### subst
    let rec subst (m : (Var * T) list) x =
        let f = subst m
        if List.isEmpty m then x
        else
            match x with
            | TyComment(_,x)
            | TyMetavar(_,{contents=Some x})
            | TyVar (_,{contents=Some x}) -> f x // Don't do path shortening here.
            | TyMetavar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> x
            | TyPair(a,b) -> TyPair(f a, f b)
            | TyRecord a -> TyRecord(Map.map (fun _ -> f) a)
            | TyModule a -> TyModule(Map.map (fun _ -> f) a)
            | TyUnion(a,b) -> TyUnion(Map.map (fun _ (is_gadt,body) -> is_gadt, f body) a,b)
            | TyFun(a,b,t) -> TyFun(f a, f b, t)
            | TyArray a -> TyArray(f a)
            | TyApply(a,b,c) -> TyApply(f a, f b, c)
            | TyVar (a,_) -> List.tryPick (fun (v,x) -> if a = v then Some x else None) m |> Option.defaultValue x
            | TyForall(a,b) -> TyForall(a, f b)
            | TyExists(a,b) -> TyExists(a, f b)
            | TyInl(a,b) -> TyInl(a, f b)
            | TyMacro a -> TyMacro(List.map (function TMVar x -> TMVar(f x) | x -> x) a)
            | TyLayout(a,b) -> TyLayout(f a,b)
    

    /// ### type_apply_split
    let type_apply_split x =
        let rec loop s x =
            match visit_t x with
            | TyApply(a,b,_) -> loop (b :: s) a
            | x -> x, s
        loop [] x
    

    /// ### kind_subst
    let rec kind_subst = function
        | KindMetavar ({contents'=Some x} & link) -> shorten' x link kind_subst
        | KindMetavar _ | KindType as x -> x
        | KindFun(a,b) -> KindFun(kind_subst a,kind_subst b)
    

    /// ### foralls_get
    let rec foralls_get = function
        | RawForall(_,a,b) -> let a', b = foralls_get b in a :: a', b
        | b -> [], b
    

    /// ### foralls_ty_get
    let rec foralls_ty_get = function
        | TyForall(a,b) -> let a', b = foralls_ty_get b in a :: a', b
        | b -> [], b
    

    /// ### kind_force
    let rec kind_force = function
        | KindMetavar ({contents'=Some x} & link) -> shorten' x link kind_force
        | KindMetavar link -> let x = KindType in link.contents' <- Some x; x
        | KindType as x -> x
        | KindFun(a,b) -> KindFun(kind_force a,kind_force b)
    

    /// ### p
    let p prec prec' x = if prec < prec' then x else sprintf "(%s)" x
    

    /// ### show_kind
    let show_kind x =
        let rec f prec x =
            let p = p prec
            match x with
            | KindMetavar {contents'=Some x} -> f prec x
            | KindMetavar _ -> "?"
            | KindType -> "*"
            | KindFun(a,b) -> p 20 (sprintf "%s -> %s" (f 20 a) (f 19 b))
        f -1 x
    

    /// ### show_constraints
    let show_constraints env x = Set.toList x |> List.map (constraint_name env) |> String.concat "; " |> sprintf "{%s}"
    

    /// ### show_nominal
    let show_nominal (env : TopEnv) i = match Map.tryFind i env.nominals_aux with Some x -> x.name | None -> "?"
    

    /// ### show_layout_type
    let show_layout_type = function Heap -> "heap" | HeapMutable -> "mut" | StackMutable -> "stack_mut"
    

    /// ### show_t
    let show_t (env : TopEnv) x =
        let show_var (a : Var) =
            let n = match a.kind with KindType -> a.name | _ -> sprintf "(%s : %s)" a.name (show_kind a.kind)
            if Set.isEmpty a.constraints then n
            else sprintf "%s %s" n (show_constraints env a.constraints)
        let rec f prec x =
            let p = p prec
            match x with
            | TyVar (_, {contents=Some x}) | TyComment(_,x) | TyMetavar(_,{contents=Some x}) -> f prec x
            | TyMetavar _ -> "_"
            | TyVar (a, _) -> a.name
            | TyNominal i ->
                match Map.tryFind i env.nominals_aux with
                | Some x when prec < 0 -> sprintf "(%s : %s)" x.name (show_kind x.kind)
                | Some x -> x.name
                | _ -> "?"
            | TyB -> "()"
            | TyLit x -> Tokenize.show_lit x
            | TyPrim x -> show_primt x
            | TySymbol x -> sprintf ".%s" x
            | TyExists(a,b) ->
                let a = List.map show_var a |> String.concat " "
                p 0 (sprintf "exists %s. %s" a (f -1 b))
            | TyForall _ ->
                let a, b =
                    let rec loop = function
                        | TyForall(a,b) -> let a',b = loop b in (a :: a'), b
                        | b -> [], b
                    loop x
                let a = List.map show_var a |> String.concat " "
                p 0 (sprintf "forall %s. %s" a (f -1 b))
            | TyInl _ ->
                let a, b =
                    let rec loop = function
                        | TyInl(a,b) -> let a',b = loop b in (a :: a'), b
                        | b -> [], b
                    loop x
                let a = List.map show_var a |> String.concat " "
                p 0 (sprintf "%s => %s" a (f -1 b))
            | TyArray a -> p 30 (sprintf "array_base %s" (f 30 a))
            | TyApply(a,b,_) -> p 30 (sprintf "%s %s" (f 29 a) (f 30 b))
            | TyPair(a,b) -> p 25 (sprintf "%s * %s" (f 25 a) (f 24 b))
            | TyFun(a,b,FT_Vanilla) -> p 20 (sprintf "%s -> %s" (f 20 a) (f 19 b))
            | TyFun(a,b,FT_Pointer) -> p 20 (sprintf "fptr (%s -> %s)" (f 20 a) (f 19 b))
            | TyFun(a,b,FT_Closure) -> p 20 (sprintf "closure (%s -> %s)" (f 20 a) (f 19 b))
            | TyModule l ->
                if prec = -2 then
                    l |> Map.toList |> List.map (fun (k,v) ->
                        let a,b = k, f -1 v
                        match v with
                        | TyComment(com,_) -> sprintf "%s : %s\n---\n%s\n---\n" a b com
                        | _ -> sprintf "%s : %s" a b
                        )
                    |> String.concat "\n"
                else "module"
            | TyRecord l -> sprintf "{%s}" (l |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f -1 v)) |> String.concat "; ")
            | TyUnion(l,_) -> sprintf "{%s}" (l |> Map.toList |> List.map (fun ((_,k),(_,v)) -> sprintf "%s : %s" k (f -1 v)) |> String.concat "| ")
            | TyMacro a -> p 30 (List.map (function TMLitVar a | TMVar a -> f -1 a | TMText a -> a) a |> String.concat "")
            | TyLayout(a,b) -> p 30 (sprintf "%s %s" (show_layout_type b) (f 30 a))
    

        f -2 x
    

    /// ### show_type_error
    let show_type_error (env : TopEnv) x =
        let f = show_t env
        match x with
        | IncorrectRecursiveNominal -> "The non-recursive nominals should not use their own type in the clause."
        | IncorrectGADTConstructorType -> "The GADT case in the union has to result in an instance of the union being constructed. Any type other than the self being in the range of the union is not allowed."
        | ExistsShouldntHaveMetavars a -> sprintf "The variables of the exists body shouldn't have metavariables left over in them.\nGot: [%s]"  (List.map f a |> String.concat ", ")
        | ExpectedExistentialInPattern a -> sprintf "The variable being destructured in the pattern match need to be explicitly annotated and with an existential type.\nGot: %s" (f a)
        | UnexpectedNumberOfArgumentsInExistsPattern(got,exp) -> sprintf "The number of arguments in the existential pattern doesn't match the one in the type.\nGot: %i\nExpected: %i" got exp
        | UnexpectedNumberOfArgumentsInExistsBody(got,exp) -> sprintf "The number of arguments in the existential body doesn't match the one in the type.\nGot: %i\nExpected: %i" got exp
        | ExpectedExistentialInTerm a -> sprintf "The body of `expects` need to be explicitly annotated and with an existential type.\nGot: %s" (f a)
        | UnionsCannotBeApplied -> "Unions cannot be applied."
        | ExpectedNominalInApply a -> sprintf "Expected a nominal.\nGot: %s" (f a)
        | MalformedNominal -> "Malformed nominal."
        | ModuleMustBeImmediatelyApplied -> "Module must be immediately applied."
        | ExpectedSymbol' a -> sprintf "Expected a symbol.\nGot: %s" (f a)
        | KindError(a,b) -> sprintf "Kind unification failure.\nGot:      %s\nExpected: %s" (show_kind a) (show_kind b)
        | KindErrorInConstraint(a,b) -> sprintf "Kind unification failure when propagating them from constraints.\nGot:      %s\nExpected: %s" (show_kind a) (show_kind b)
        | TermError(a,b) -> sprintf "Unification failure.\nGot:      %s\nExpected: %s" (f a) (f b)
        | RecursiveMetavarsNotAllowed(a,b) -> sprintf "Recursive metavariables are not allowed. A metavar cannot be unified with a type that has itself.\nGot:      %s\nExpected: %s" (f a) (f b)
        | RecursiveTypevarsNotAllowed(a,b) -> sprintf "Recursive type variables are not allowed. A type variable cannot be unified with a type that has itself.\nGot:      %s\nExpected: %s" (f a) (f b)
        | ExpectedSymbolAsRecordKey a -> sprintf "Expected symbol as a record key.\nGot: %s" (f a)
        | ExpectedSymbolAsModuleKey a -> sprintf "Expected symbol as a module key.\nGot: %s" (f a)
        | UnboundVariable x -> sprintf "Unbound variable: %s." x
        | UnboundModule -> sprintf "Unbound module."
        | ModuleIndexFailedInOpen -> sprintf "Module does not have a submodule with that key."
        | ModuleIndexWouldShadowLocalVars [|v|] -> $"The module open would shadow a local variable: {v}."
        | ModuleIndexWouldShadowLocalVars vars -> let v = String.concat ", " vars in $"The module open would shadow the local variables: {v}."
        | TypeVarScopeError(a,_,_) -> sprintf "Tried to unify the type variable %s with a metavar outside its scope." a
        | ForallVarConstraintError(n,a,b) -> sprintf "Metavariable's constraints must be a subset of the forall var %s's.\nGot: %s\nExpected: %s" n (show_constraints env a) (show_constraints env b)
        | MetavarsNotAllowedInRecordWith -> sprintf "In the top-down segment the record keys need to be fully known. Please add an annotation."
        | LayoutSetMustBeAnnotated -> sprintf "The layout type being set must be annotated."
        | ExpectedMutableLayout a -> sprintf "Expected a mutable layout type.\nGot: %s" (f a)
        | ExpectedRecord a -> sprintf "Expected a record.\nGot: %s" (f a)
        | ExpectedRecordInsideALayout a -> sprintf "Expected a record inside a layout type.\nGot: %s" (f a)
        | ExpectedRecordAsResultOfIndex a -> sprintf "Expected a record as result of index.\nGot: %s" (f a)
        | RecordIndexFailed a -> sprintf "The record does not have the key: %s" a
        | ModuleIndexFailed a -> sprintf "The module does not have the key: %s" a
        | ExpectedModule a -> sprintf "Expected a module.\nGot: %s" (f a)
        | ExpectedSymbolInRecordWith a -> sprintf "Expected a symbol.\nGot: %s" (f a)
        | RealFunctionInTopDown -> sprintf "Real segment functions are forbidden in the top-down segment. They can only be used in `real` expressions or .spir modules."
        | MissingRecordFieldsInPattern(a,b) -> sprintf "The record is missing the following fields: %s.\nGot: %s" (String.concat ", " b) (f a)
        | CasePatternNotFoundForType(i,n) -> sprintf "%s does not have the %s case." (show_nominal env i) n
        | CasePatternNotFound n -> sprintf "Cannot find a function with the same name as the %s case in the environment." n
        | CannotInferCasePatternFromTermInEnv a -> sprintf "Cannot infer the higher order type that has this case from the following type.\nGot: %s" (f a)
        | NominalInPatternUnbox i -> sprintf "Expected an union type, but %s is a nominal." (show_nominal env i)
        | TypeInEnvIsNotNominal a -> sprintf "Expected a nominal type.\nGot: %s" (f a)
        | UnionInPatternNominal i -> sprintf "Expected a nominal type, but %s is an union." (show_nominal env i)
        | ConstraintError(a,b) -> sprintf "Constraint satisfaction error.\nGot: %s\nFails to satisfy: %s" (f b) (constraint_name env a)
        | ExpectedAnnotation -> sprintf "Recursive functions with foralls must be fully annotated."
        | ExpectedSinglePattern -> sprintf "Recursive functions with foralls must not have multiple clauses in their patterns."
        | RecursiveAnnotationHasMetavars a -> sprintf "Recursive functions with foralls must not have metavars.\nGot: %s" (f a)
        | ValueRestriction a -> sprintf "Metavars that are not part of the enclosing function's signature are not allowed. They need to be values.\nGot: %s" (f a)
        | DuplicateRecInlName -> "Shadowing of functions by the members of the same mutually recursive block is not allowed."
        | DuplicateKeyInRecUnion -> "Mutually recursive unions should not have overlapping keys."
        | ExpectedConstraintInsteadOfModule -> sprintf "Expected a constraint instead of module."
        | InstanceNotFound(prot,ins) -> sprintf "The higher order type instance %s does not have the prototype %s." (show_nominal env ins) env.prototypes.[prot].name
        | ExpectedPrototypeConstraint a -> sprintf "Expected a prototype constraint.\nGot: %s" (constraint_name env a)
        | PrototypeConstraintCannotPropagateToMetavar(a,b) -> sprintf "Cannot propagate the %s prototype constraint to the applied metavariable as the kinds would not match. If this is not intended to be a type var, provide a type annotation to a concrete type.\nGot: %s" env.prototypes.[a].name (f b)
        | PrototypeConstraintCannotPropagateToVar(a,b) -> sprintf "Cannot propagate the %s prototype constraint to the applied type variable as the kinds would not match.\nGot: %s" env.prototypes.[a].name (f b)
        | ExpectedPrototypeInsteadOfModule -> "Expected a prototype instead of module."
        | ExpectedHigherOrder a -> sprintf "Expected a higher order type.\nGot: %s" (f a)
        | InstanceArityError(prot,ins) -> sprintf "The arity of the instance must be greater or equal to that of the prototype.\nInstance arity:  %i\nPrototype arity: %i" ins prot
        | InstanceCoreVarsShouldMatchTheArityDifference(num_vars,expected) -> sprintf "The number of forall variables in the instance needs to be specified so it equals the difference between the instance arity and the prototype arity.\nInstance variables specified: %i\nExpected:                     %i" num_vars expected
        | InstanceKindError(a,b) -> sprintf "The kinds of the instance foralls are incompatible with those of the prototype.\nGot:      %s\nExpected: %s" (show_kind a) (show_kind b)
        | KindNotAllowedInInstanceForall -> "Kinds should not be explicitly stated in instance foralls."
        | InstanceVarShouldNotMatchAnyOfPrototypes -> "Instance forall must not have the same name as any of the prototype foralls."
        | MissingBody -> "The function body is missing."
        | MacroIsMissingAnnotation -> "The macro needs an annotation."
        | ArrayIsMissingAnnotation -> "The array needs an annotation."
        | ExistsIsMissingAnnotation -> "The existential type needs an annotation."
        | ShadowedForall -> "Shadowing of foralls is not allowed in the top-down segment."
        | ShadowedExists -> "Shadowing of existential type variables is not allowed in the top-down segment."
        | UnionTypesMustHaveTheSameLayout -> "The two union types must have the same layout."
        | OrphanInstance -> "The instance has to be defined in the same package as either the prototype or the nominal."
        | ShadowedInstance -> "The instance cannot be defined twice."
        | UnusedTypeVariable [x] -> sprintf "The type variable %s is unused in the function's type signature." x
        | UnusedTypeVariable vars -> sprintf "The type variables %s are unused in the function's type signature." (vars |> String.concat ", ")
        | CompilerError x -> x
    

    /// ### autogen_name_in_fun
    let autogen_name_in_fun (i : int) = let x = char i + 'a' in if 'z' < x then sprintf "'%i" i else sprintf "'%c" x
    

    /// ### autogen_name_in_typecase
    let autogen_name_in_typecase (i : int) = let x = char i + 'a' in if 'z' < x then sprintf "'t%i" i else sprintf "'t%c" x
    

    /// ### trim_kind
    let trim_kind = function KindFun(_,k) -> k | _ -> failwith "impossible"
    

    /// ### FilledTop
    // Similar to BundleTop except with type annotations and type application filled in.
    type FilledTop =
        | FType of VSCRange * RString * HoVar list * RawTExpr
        | FNominal of VSCRange * RString * HoVar list * RawTExpr
        | FNominalRec of (VSCRange * RString * HoVar list * RawTExpr) list
        | FInl of VSCRange * RString * RawExpr
        | FRecInl of (VSCRange * RString * RawExpr) list
        | FPrototype of VSCRange * RString * RString * TypeVar list * RawTExpr
        | FInstance of VSCRange * RGlobalId * RGlobalId * RawExpr
        | FOpen of VSCRange * RString * RString list
        | FError of VSCRange
    

    /// ### 'a AdditionType
    type 'a AdditionType =
        | AOpen of 'a
        | AInclude of 'a
    

    /// ### InferScope
    type InferScope = int
    

    /// ### InferResult
    type [<ReferenceEquality>] InferResult = {
        filled_top : FilledTop Hopac.Promise
        top_env_additions : TopEnv AdditionType
        offset : int
        hovers : RString []
        errors : RString list
        }
    

    /// ### dispose_gadt_links
    let dispose_gadt_links gadt_links = Seq.iter (fun (x : ref<option<'a>>) -> x.Value <- None) gadt_links
    

    /// ### assert_foralls_used'
    let assert_foralls_used' (errors : (VSCRange * TypeError) ResizeArray) outside_foralls r x =
        let h = HashSet()
        let rec f x =
            match visit_t x with
            | TyVar (v,_) -> Set.singleton v.name
            | TyExists(v,a) ->
                List.fold (fun a v ->
                    if Set.contains v.name a = false then h.Add(v.name) |> ignore; a
                    else Set.remove v.name a
                    ) (f a) v
            | TyForall(v,a) ->
                let a = f a
                if Set.contains v.name a = false then h.Add(v.name) |> ignore; a
                else Set.remove v.name a
            | TyUnion _ | TyModule _ | TyMetavar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> Set.empty
            | TyPair(a,b) | TyApply(a,b,_) | TyFun(a,b,_) -> f a + f b
            | TyRecord a -> Map.fold (fun s _ x -> Set.union s (f x)) Set.empty a
            | TyComment(_,a) | TyLayout(a,_) | TyInl(_,a) | TyArray a -> f a
            | TyMacro a ->
                List.fold (fun s x ->
                    match x with
                    | TMLitVar a | TMVar a -> f a
                    | TMText _ -> Set.empty
                    ) Set.empty a
        let used_vars = f x
        Seq.iter (h.Add >> ignore) (outside_foralls - used_vars)
        if 0 < h.Count then
            let vars = h |> Seq.toList |> List.sort
            errors.Add(r, UnusedTypeVariable vars)
    /// ### assert_foralls_used
    let assert_foralls_used errors r x = assert_foralls_used' errors Set.empty r x
    

    /// ### validate_nominal
    let validate_nominal (errors : _ ResizeArray) global_id body v =
        // Stack union types and regular nominals must not be recursive.
        // Unlike in the previous version of Spiral which simply didn't put the nominal type in the environment
        // this one has to do it becaus the GADT constructors need access to it.
        let rec assert_nominal_non_recursive v =
            let f = assert_nominal_non_recursive
            match visit_t v with
            | TyNominal global_id' -> if global_id = global_id' then errors.Add(range_of_texpr_gadt_body body, IncorrectRecursiveNominal)
            | TyMetavar _ | TyVar _ | TyModule _ | TyUnion _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> ()
            | TyPair(a,b) | TyApply(a,b,_) | TyFun(a,b,_) -> f a; f b
            | TyRecord a -> Map.iter (fun _ -> f) a
            | TyExists(_,a) | TyComment(_,a) | TyLayout(a,_) | TyForall(_,a) | TyInl(_,a) | TyArray a -> f a
            | TyMacro a -> List.iter (function TMLitVar a | TMVar a -> f a | TMText _ -> ()) a
        match v with // Validates the union type.
        | TyUnion(a,b) ->
            a |> Map.iter (fun name (is_gadt, v) ->
                let body =
                    match body with
                    | RawTUnion(_,a,_,_) -> Map.find name a |> snd
                    | _ -> failwith "Compiler error: Expected an union."
                let is_stack = b = UStack
    

                // Makes sure that the GADT constructor is resulting in its own type.
                // Also make sure that it's not using an instance of itself in its constructor other than in first position.
                let rec assert_gadt_has_proper_specialized_constructor = function
                    | TyNominal global_id' -> if global_id <> global_id' then errors.Add(range_of_texpr_gadt_constructor body, IncorrectGADTConstructorType)
                    | TyApply(a,b,_) ->
                        assert_gadt_has_proper_specialized_constructor a
                        if is_stack then assert_nominal_non_recursive b
                    | _ -> errors.Add(range_of_texpr_gadt_constructor body, IncorrectGADTConstructorType)
    

                let assert_gadt_is_valid v =
                    let rec find_gadt_constructor outside_foralls = function
                        | TyForall(n,t) -> find_gadt_constructor (Set.add n.name outside_foralls) t
                        | TyFun(a,b,_) ->
                            if is_stack then assert_nominal_non_recursive a
                            assert_gadt_has_proper_specialized_constructor b
                            assert_foralls_used errors (range_of_texpr_gadt_body body) a
                            assert_foralls_used' errors outside_foralls (range_of_texpr_gadt_constructor body) b
                        | b ->
                            assert_gadt_has_proper_specialized_constructor b
                            assert_foralls_used' errors outside_foralls (range_of_texpr_gadt_constructor body) b
    

                    find_gadt_constructor Set.empty v
    

                if is_gadt then assert_gadt_is_valid v
                else
                    if is_stack then assert_nominal_non_recursive v
                    assert_foralls_used errors (range_of_texpr body) v // We need to assert that the foralls in regular union bodies are checked.
                )
        | _ ->
            assert_nominal_non_recursive v
    

    /// ### kind_to_rawkind
    let rec kind_to_rawkind (x : TT) : RawKindExpr =
        match visit_tt x with
        | KindMetavar _ | KindType -> RawKindStar
        | KindFun(a,b) -> RawKindFun(kind_to_rawkind a, kind_to_rawkind b)
    

    /// ### var_to_hovar
    let var_to_hovar r (x : Var) : HoVar = r,(x.name,kind_to_rawkind x.kind)
    

    /// ### var_to_typevar
    let var_to_typevar r (x : Var) : TypeVar = var_to_hovar r x, [] // In the bottom up segment the constrains aren't checked anywhere so we'll put an empty list here.
    

    /// ### infer
    let infer package_id module_id (top_env' : TopEnv) expr =
        let at_tag i = {package_id=package_id; module_id=module_id; tag=i}
        let mutable top_env = top_env' // Is mutated only in two places at the top level. During actual inference can otherwise be thought of as immutable.
        let errors = ResizeArray()
        let generalized_statements = Dictionary(HashIdentity.Reference)
        let type_apply_args = Dictionary(HashIdentity.Reference)
        let module_type_apply_args = Dictionary(HashIdentity.Reference)
        let annotations = Dictionary<obj,_>(HashIdentity.Reference)
        let exists_vars = Dictionary<obj,_>(HashIdentity.Reference)
        let gadt_typecases = Dictionary<obj,_>(HashIdentity.Reference)
        let mutable autogened_forallvar_count_in_typecase = 0
        let mutable autogened_forallvar_count_in_funs = 0
        let hover_types = HoverTypes()
    

        /// Fills in the type applies and annotations, and generalizes statements. Also strips annotations from terms and patterns.
        /// Dealing with recursive statement type applies requires some special consideration.
        let fill r rec_term expr =
            assert (0 = errors.Count)
            let t_to_rawtexpr r vars_to_metavars expr =
                let rec f x =
                    match visit_t x with
                    | TyUnion _ | TyMetavar _  | TyInl _  | TyModule _ as x -> failwithf "Compiler error: These cases should not appear in fill.\nGot: %A" x
                    | TyForall(a,b) -> RawTForall(r,var_to_typevar r a,f b)
                    | TyComment(_,x) -> f x
                    | TyB -> RawTB r
                    | TyLit x -> RawTLit(r,x)
                    | TyPrim x -> RawTPrim(r,x)
                    | TySymbol x -> RawTSymbol(r,x)
                    | TyPair(a,b) -> RawTPair(r,f a,f b)
                    | TyRecord l -> RawTRecord(r,Map.map (fun _ -> f) l)
                    | TyFun(a,b,t) -> RawTFun(r,f a,f b,t)
                    | TyExists(a,b) -> RawTExists(r,a |> List.map (fun n -> (r,(n.name,RawKindWildcard)),[]), f b)
                    | TyArray a -> RawTArray(r,f a)
                    | TyNominal i -> RawTFilledNominal(r,i)
                    | TyApply(a,b,_) -> RawTApply(r,f a,f b)
                    | TyVar (a,_) ->
                        let is_typecase_metavar = List.tryFind (function TyVar(b,_) -> a = b | _ -> failwith "Compiler error: Expected a TyVar.") vars_to_metavars |> Option.isSome
                        if is_typecase_metavar then RawTMetaVar(r,a.name) else RawTVar(r,a.name)
                    | TyMacro l -> l |> List.map (function TMText x -> RawMacroText(r,x) | TMVar x -> RawMacroType(r,f x) | TMLitVar x -> RawMacroTypeLit(r,f x)) |> fun l -> RawTMacro(r,l)
                    | TyLayout(a,b) -> RawTLayout(r,f a,b)
                f expr
            let annot r x = t_to_rawtexpr r [] (snd annotations.[x])
            let rec fill_typecases rec_term x =
                match gadt_typecases.TryGetValue(x) with
                | true, typecase_data ->
                    Seq.foldBack (fun (typecase_cond,forall_vars,typecase_constructor) typecase_body ->
                        let r = range_of_expr typecase_body
                        RawTypecase(r, t_to_rawtexpr r [] typecase_cond, [t_to_rawtexpr r forall_vars typecase_constructor, typecase_body])
                        ) typecase_data (term rec_term x)
                | _ ->
                    term rec_term x
            and fill_foralls r rec_term body =
                let _,body = foralls_get body
                let l,_ = foralls_ty_get generalized_statements.[body]
                List.foldBack (fun (x : Var) s -> RawFilledForall(r,x.name,s)) l (term rec_term body)
            and term rec_term x =
                let f = term rec_term
                let clauses l =
                    List.map (fun (a, b) ->
                        let rec_term,a = pattern rec_term a
                        a,fill_typecases rec_term b
                        ) l
                match x with
                | RawFilledForall _ | RawMissingBody _ | RawType _ as x -> failwithf "Compiler error: These cases should not appear in fill. It is intended to be called on top level statements only.\nGot: %A" x
                | RawTypecase _
                | RawSymbol _ | RawB _ | RawLit _ | RawOp _ -> x
                | RawReal(_,x) -> x
                | RawV(r,n,false) -> x
                | RawV(r,n,true) ->
                    match type_apply_args.TryGetValue(n) with
                    | true, type_apply_args ->
                        match Map.tryFind n rec_term with
                        | None -> fst type_apply_args
                        | Some t -> t |> snd type_apply_args
                        |> List.fold (fun s x -> RawApply(r,s,RawType(r,t_to_rawtexpr r [] x))) x
                    | _ -> x
                | RawDefaultLit(r,_) -> RawAnnot(r,x,annot r x)
                | RawForall(r,a,b) -> RawForall(r,a,f b)
                | RawMatch(r'',(RawForall _ | RawFun _) & body,[PatVar(r,name), on_succ]) ->
                    let _,body = foralls_get body
                    RawMatch(r'',fill_foralls r rec_term body,[PatVar(r,name), fill_typecases (Map.remove name rec_term) on_succ])
                | RawMatch(r,a,b) -> RawMatch(r,f a,clauses b)
                | RawFun(r,a) -> RawAnnot(r,RawFun(r,clauses a),annot r x)
                | RawExists(r,(r',a),b) -> RawExists(r,(r',Some(Option.defaultWith (fun () -> List.map (t_to_rawtexpr r []) exists_vars.[x]) a)),f b)
                | RawRecBlock(r,l,on_succ) ->
                    let has_foralls = List.exists (function (_,RawForall _) -> true | _ -> false) l
                    if has_foralls then RawRecBlock(r,List.map (fun (a,b) -> a, f b) l,f on_succ)
                    else
                        let rec_term = List.fold (fun s ((_,name),b) -> Map.add name generalized_statements.[foralls_get b |> snd] s) rec_term l
                        let l = List.map (fun (a,b) -> a, fill_foralls (fst a) rec_term b) l
                        RawRecBlock(r,l,f on_succ)
                | RawRecordWith(r,a,b,c) ->
                    let b = b |> List.map (function
                        | RawRecordWithSymbol(a,b) -> RawRecordWithSymbol(a,f b)
                        | RawRecordWithSymbolModify(a,b) -> RawRecordWithSymbolModify(a,f b)
                        | RawRecordWithInjectVar(a,b) -> RawRecordWithInjectVar(a,f b)
                        | RawRecordWithInjectVarModify(a,b) -> RawRecordWithInjectVarModify(a,f b)
                        )
                    RawRecordWith(r,List.map f a,b,c)
                | RawJoinPoint(r,q,a,b) -> RawAnnot(r,RawJoinPoint(r,q,f a,b),annot r x)
                | RawAnnot(r,a,_) -> f a
                | RawOpen(r,a,b,c) ->
                    let f = function TyModule s -> s | _ -> failwith "Compiler error: Module open should always succeed in fill."
                    List.fold (fun s x -> (f s).[snd x]) top_env.term.[snd a] b |> f
                    |> Map.fold (fun s k _ -> Map.remove k s) rec_term
                    |> fun rec_term -> RawOpen(r,a,b,term rec_term c)
                | RawApply(r,a,b) ->
                    let q = RawApply(r,f a,f b)
                    match module_type_apply_args.TryGetValue(x) with
                    | true, typevars -> List.fold (fun a b -> RawApply(r,a,RawType(r,t_to_rawtexpr r [] b))) q typevars
                    | _ -> q
                | RawIfThenElse(r,a,b,c) -> RawIfThenElse(r,f a,f b,f c)
                | RawIfThen(r,a,b) -> RawIfThen(r,f a,f b)
                | RawPair(r,a,b) -> RawPair(r,f a,f b)
                | RawSeq(r,a,b) -> RawSeq(r,f a,f b)
                | RawHeapMutableSet(r,a,b,c) -> RawHeapMutableSet(r,f a,List.map f b,f c)
                | RawMacro(r,l) ->
                    let l = l |> List.map (function RawMacroTerm(r,x,b) -> RawMacroTerm(r,f x,b) | x -> x )
                    RawAnnot(r,RawMacro(r,l),annot r x)
                | RawArray(r,a) -> RawAnnot(r,RawArray(r,List.map f a),annot r x)
            and pattern recbterm x' =
                let mutable rec_term = rec_term
                let rec f = function
                    | PatFilledDefaultValue _ -> failwith "Compiler error: PatDefaultValueFilled should not appear in fill."
                    | PatValue _ | PatSymbol _ | PatE _ | PatB _ as x -> x
                    | PatVar(r,name) as x -> rec_term <- Map.remove name rec_term; x
                    | PatDyn(r,a) -> PatDyn(r,f a)
                    | PatUnbox(r,q,a) -> PatUnbox(r,q,f a)
                    | PatExists(r,q,a) -> PatExists(r,q,f a)
                    | PatAnnot(_,a,_) -> f a
                    | PatPair(r,a,b) -> PatPair(r,f a,f b)
                    | PatRecordMembers(r,a) ->
                        let a = a |> List.map (function
                            | PatRecordMembersSymbol(a,b) -> PatRecordMembersSymbol(a,f b)
                            | PatRecordMembersInjectVar(a,b) -> PatRecordMembersInjectVar(a,f b)
                            )
                        PatRecordMembers(r,a)
                    | PatOr(r,a,b) -> PatOr(r,f a,f b)
                    | PatAnd(r,a,b) -> PatAnd(r,f a,f b)
                    | PatDefaultValue(r,a) as x -> PatFilledDefaultValue(r,a,annot r x)
                    | PatWhen(r,a,b) -> PatWhen(r,f a,term rec_term b)
                    | PatNominal(r,a,b,c) -> PatNominal(r,a,b,f c)
                    | PatArray(r,a) -> PatArray(r,List.map f a)
                rec_term, f x'
    

            let x = fill_foralls r rec_term expr
            assert (0 = errors.Count)
            x
    

        let fresh_kind () = KindMetavar {contents'=None}
        let fresh_var'' x = TyMetavar (x, ref None)
        let fresh_var' scope kind = fresh_var'' {scope=scope; constraints=Set.empty; kind=kind}
        let fresh_subst_var scope cons kind = fresh_var'' {scope=scope; constraints=cons; kind=kind}
        let forall_subst_all scope x =
            let rec loop m x =
                match visit_t x with
                | TyForall(a,b) ->
                    let v = fresh_subst_var scope a.constraints a.kind
                    let type_apply_args,b = loop ((a, v) :: m) b
                    v :: type_apply_args, b
                | x -> [], subst m x
            loop [] x
    

        let exists_subst_term scope (l : Var list, body) =
            let vars = l |> List.map (fun a -> fresh_subst_var scope a.constraints a.kind)
            vars, subst (List.zip l vars) body
    

        let assert_exists_hasnt_metavars r vars =
            if List.exists has_metavars vars then errors.Add(r, ExistsShouldntHaveMetavars vars)
    

        let generalize r scope (forall_vars : Var list) (body : T) =
            let h = HashSet(HashIdentity.Reference)
            List.iter (h.Add >> ignore) forall_vars
            let generalized_metavars = ResizeArray()
            let rec replace_metavars x =
                let f = replace_metavars
                match x with
                | TyVar (_,{contents=Some x})
                | TyMetavar(_,{contents=Some x}) -> f x
                | TyMetavar(x, link) when scope = x.scope ->
                    let v = tyvar {scope=x.scope; constraints=x.constraints; kind=kind_force x.kind; name=autogen_name_in_fun autogened_forallvar_count_in_funs}
                    autogened_forallvar_count_in_funs <- autogened_forallvar_count_in_funs+1
                    link.Value <- Some v
                    replace_metavars v
                // This scheme with the HashSet is so generalize works for mutually recursive statements.
                | TyVar (v,_) -> if scope = v.scope && h.Add(v) then generalized_metavars.Add(v)
                | TyMetavar _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> ()
                | TyPair(a,b) | TyApply(a,b,_) | TyFun(a,b,_) -> f a; f b
                | TyUnion(a,_) -> Map.iter (fun _ -> snd >> f) a
                | TyRecord a -> Map.iter (fun _ -> f) a
                | TyExists(v,a) -> List.iter (h.Add >> ignore) v; f a
                | TyForall(v,a) -> (h.Add >> ignore) v; f a
                | TyComment(_,a) | TyLayout(a,_) | TyArray a -> f a
                | TyMacro a -> List.iter (function TMLitVar a | TMVar a -> f a | TMText _ -> ()) a
                | TyModule _ | TyInl _ -> ()
    

            let f x s = TyForall(x,s)
            replace_metavars body
            let x = Seq.foldBack f generalized_metavars body |> List.foldBack f forall_vars |> term_subst
            if List.isEmpty forall_vars = false then assert_foralls_used errors r x
            x
    

        let gadt_extract scope (v : T) =
            let forall_subst_all_gadt x =
                let rec loop m x =
                    match visit_t x with
                    | TyForall(a,b) ->
                        let v = tyvar {a with name=autogen_name_in_typecase autogened_forallvar_count_in_typecase; scope=scope}
                        autogened_forallvar_count_in_typecase <- autogened_forallvar_count_in_typecase+1
                        let type_apply_args,b = loop ((a, v) :: m) b
                        v :: type_apply_args, b
                    | x -> [], subst m x
                loop [] x
            let forall_vars,v = forall_subst_all_gadt v
            match v with
            | TyFun(a,b,_) -> forall_vars,a,b
            | b -> forall_vars,TyB,b
    

        let inline unify_kind' er r got expected =
            let rec loop (a'',b'') =
                match visit_tt a'', visit_tt b'' with
                | KindType, KindType -> ()
                | KindFun(a,a'), KindFun(b,b') -> loop (a,b); loop (a',b')
                | KindMetavar a, KindMetavar b & b' -> if a <> b then a.contents' <- Some b'
                | KindMetavar link, b | b, KindMetavar link -> link.contents' <- Some b
                | _ -> raise (InferTypeErrorException [r, er (got, expected)])
            loop (got, expected)
        let unify_kind r got expected = try unify_kind' KindError r got expected with :? InferTypeErrorException as e -> errors.AddRange e.Data0
        let unify_gadt (gadt_links : T option ref ResizeArray option) (r : VSCRange) (got : T) (expected : T) : unit =
            let unify_kind got expected = unify_kind' KindError r got expected
            let er () = raise (InferTypeErrorException [r, TermError(got, expected)])
    

            let rec constraint_process (con : Constraint Set) b =
                let unify_kind got expected = unify_kind' KindErrorInConstraint r got expected
                let body = function
                    | CUInt, TyPrim (UInt8T | UInt16T | UInt32T | UInt64T)
                    | CSInt, TyPrim (Int8T | Int16T | Int32T | Int64T)
                    | CInt, TyPrim (UInt8T | UInt16T | UInt32T | UInt64T | Int8T | Int16T | Int32T | Int64T)
                    | CFloat, TyPrim (Float32T | Float64T)
                    | CNumber, TyPrim (UInt8T | UInt16T | UInt32T | UInt64T | Int8T | Int16T | Int32T | Int64T | Float32T | Float64T)
                    | CPrim, TyPrim _
                    | CSymbol, TySymbol _
                    | CRecord, TyRecord _ -> []
                    | con, TyMetavar(x,_) -> x.constraints <- Set.add con x.constraints; []
                    | CPrototype prot & con, x ->
                        match type_apply_split x with
                        | TyNominal ins, x' ->
                            match Map.tryFind (prot,ins) top_env.prototypes_instances with
                            | Some cons ->
                                try List.fold2 (fun ers con x -> List.append (constraint_process con (visit_t x)) ers) [] cons x'
                                with :? System.ArgumentException -> [] // This case can occur due when kind application overflows in a previous expression.
                            | None -> [InstanceNotFound(prot,ins)]
                        | TyMetavar _ & x, _ -> [PrototypeConstraintCannotPropagateToMetavar(prot,x)]
                        | TyVar _ & x, _ -> [PrototypeConstraintCannotPropagateToVar(prot,x)]
                        | _ -> [ConstraintError(con,x)]
                    | con, x -> [ConstraintError(con,x)]
    

                match b with
                | TyVar (_,{contents=Some x}) -> constraint_process con x
                | TyVar (b,_) -> if con.IsSubsetOf b.constraints = false then [ForallVarConstraintError(b.name,con,b.constraints)] else []
                | b ->
                    let b_kind = tt top_env b
                    Set.fold (fun ers con ->
                        unify_kind b_kind (constraint_kind top_env con)
                        List.append (body (con,b)) ers
                        ) [] con
    

            // Does occurs checking for recursive metavariables.
            // Does scope checking in forall vars.
            let validate_mvar_unification i x =
                let nested_tvars = HashSet(HashIdentity.Reference)
                let rec f x =
                    match visit_t x with
                    | TyModule _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> ()
                    | TyMacro a -> a |> List.iter (function TMText _ -> () | TMLitVar a | TMVar a -> f a)
                    | TyForall(v,a) | TyInl(v,a) ->
                        let _ = nested_tvars.Add(v)
                        f a
                        let _ = nested_tvars.Remove(v)
                        ()
                    | TyExists(v,a) ->
                        v |> List.iter (nested_tvars.Add >> ignore)
                        f a
                        v |> List.iter (nested_tvars.Remove >> ignore)
                    | TyComment(_,a) | TyArray a -> f a
                    | TyApply(a,b,_) | TyFun(a,b,_) | TyPair(a,b) -> f a; f b
                    | TyUnion(l,_) -> Map.iter (fun _ -> snd >> f) l
                    | TyRecord l -> Map.iter (fun _ -> f) l
                    | TyVar(b,_) -> if nested_tvars.Contains b = false && i.scope < b.scope then raise (InferTypeErrorException [r,TypeVarScopeError(b.name,got,expected)])
                    | TyMetavar(x,_) -> if i = x then raise (InferTypeErrorException [r,RecursiveMetavarsNotAllowed(got,expected)]) elif i.scope < x.scope then x.scope <- i.scope
                    | TyLayout(a,_) -> f a
                f x
    

            // Does occurs checking for recursive type variables.
            let rec validate_tvar_unification i x =
                let f = validate_tvar_unification i
                match visit_t x with
                | TyMetavar _ | TyModule _ | TyNominal _ | TyB | TyLit _ | TyPrim _ | TySymbol _ -> ()
                | TyMacro a -> a |> List.iter (function TMText _ -> () | TMLitVar a | TMVar a -> f a)
                | TyExists(_,a) | TyComment(_,a) | TyForall(_,a) | TyInl(_,a) | TyArray a -> f a
                | TyApply(a,b,_) | TyFun(a,b,_) | TyPair(a,b) -> f a; f b
                | TyUnion(l,_) -> Map.iter (fun _ -> snd >> f) l
                | TyRecord l -> Map.iter (fun _ -> f) l
                | TyVar(x,_) -> if i = x then raise (InferTypeErrorException [r,RecursiveTypevarsNotAllowed(got,expected)])
                | TyLayout(a,_) -> f a
    

            let rec loop (a'',b'') =
                match visit_t a'', visit_t b'' with
                | TyComment(_,a), b | a, TyComment(_,b) -> loop (a,b)
                | TyMetavar(a,link), TyMetavar(b,_) & b' ->
                    if a <> b then
                        unify_kind a.kind b.kind
                        b.scope <- min a.scope b.scope
                        b.constraints <- a.constraints + b.constraints
                        link.Value <- Some b'
                | TyMetavar(a,link), b | b, TyMetavar(a,link) ->
                    validate_mvar_unification a b
                    unify_kind a.kind (tt top_env b)
                    match constraint_process a.constraints b with
                    | [] -> link.Value <- Some b
                    | constraint_errors -> raise (InferTypeErrorException (List.map (fun x -> r,x) constraint_errors))
                | TyVar (a,_), TyVar (b,_) when a = b -> ()
                | TyVar (a,link), b | b, TyVar (a,link) when gadt_links.IsSome ->
                    validate_tvar_unification a b
                    unify_kind a.kind (tt top_env b)
                    match constraint_process a.constraints b with
                    | [] -> link.Value <- Some b; gadt_links.Value.Add(link)
                    | constraint_errors -> raise (InferTypeErrorException (List.map (fun x -> r,x) constraint_errors))
                | TyFun(a,a',ta), TyFun(b,b',tb) when ta = tb -> loop (a,b); loop (a',b')
                | TyPair(a,a'), TyPair(b,b') -> loop (a,b); loop (a',b')
                | TyApply(a,a',_), TyApply(b,b',_) -> loop (a',b'); loop (a,b)
                | TyUnion(l,q), TyUnion(l',q') ->
                    if q = q' then
                        let a,b = Map.toArray l, Map.toArray l'
                        if a.Length <> b.Length then er ()
                        else Array.iter2 (fun (ka,a) (kb,b) -> if ka = kb && fst a = fst b then loop (snd a,snd b) else er()) a b
                    else raise (InferTypeErrorException [r,UnionTypesMustHaveTheSameLayout])
                | TyRecord l, TyRecord l' ->
                    let a,b = Map.toArray l, Map.toArray l'
                    if a.Length <> b.Length then er ()
                    else
                        let a = a |> Array.sortBy (fun ((_,k),_) -> k)
                        let b = b |> Array.sortBy (fun ((_,k),_) -> k)
                        Array.iter2 (fun (ka,a) (kb,b) ->
                            if (ka |> snd) = (kb |> snd)
                            then loop (a,b)
                            else er()
                        ) a b
                | TyNominal i, TyNominal i' when i = i' -> ()
                | TyB, TyB -> ()
                | TyPrim x, TyPrim x' when x = x' -> ()
                | TyLit a, TyLit b when a = b -> ()
                | TySymbol x, TySymbol x' when x = x' -> ()
                | TyArray a, TyArray b -> loop (a,b)
                // Note: Unifying these 3 only makes sense if the `expected` is fully inferred already.
                | TyExists(a,b), TyExists(a',b') when
                        List.length a = List.length a'
                        && List.forall2 (fun (a : Var) (a' : Var) -> a.kind = a'.kind && a.constraints = a'.constraints) a a' ->
                    loop (b, subst (List.map2 (fun a a' -> a', tyvar a) a a') b')
                | TyForall(a,b), TyForall(a',b')
                | TyInl(a,b), TyInl(a',b') when a.kind = a'.kind && a.constraints = a'.constraints -> loop (b, subst [a',tyvar a] b')
                | TyMacro a, TyMacro b ->
                    List.iter2 (fun a b ->
                        match a,b with
                        | TMText a, TMText b when System.Object.ReferenceEquals(a,b) || a = b -> ()
                        | TMVar a, TMVar b -> loop(a,b)
                        | _ -> er ()
                        ) a b
                | TyLayout(a,a'), TyLayout(b,b') when a' = b' -> loop (a,b)
                | _ -> er ()
    

            try loop (got, expected)
            with :? InferTypeErrorException as e -> errors.AddRange e.Data0
    

        let unify range got expected = unify_gadt None range got expected
    

        let apply_record r s l x =
            match visit_t x with
            | TySymbol x ->
                match l |> Map.tryPick (fun (_, k) v -> if k = x then Some v else None) with
                | Some x ->
                    let com = match x with TyComment(com,_) -> com | _ -> ""
                    unify r s x
                    hover_types.AddHover (r,(x,com))
                | None -> errors.Add(r,RecordIndexFailed x)
            | x -> errors.Add(r,ExpectedSymbolAsRecordKey x)
    

        let assert_bound_vars env a =
            let keys_of m = Map.fold (fun s k _ -> Set.add k s) Set.empty m
            validate_bound_vars (loc_env top_env) env.constraints (keys_of env.term) (keys_of env.ty) (Choice1Of2 a) |> errors.AddRange
    

        let fresh_var scope = fresh_var' scope KindType
    

        let v_cons env a = Map.tryFind a env |> Option.orElseWith (fun () -> Map.tryFind a top_env.constraints)
        let v env top_env a = Map.tryFind a env |> Option.orElseWith (fun () -> Map.tryFind a top_env)
        let v_term env a = v env.term top_env.term a |> Option.map (function TyComment(com,x) -> com, visit_t x | x -> "", visit_t x)
        let v_ty env a = v env.ty top_env.ty a
    

        let typevar_to_var scope cons (((_,(name,kind)),constraints) : TypeVar) : Var =
            let rec typevar = function
                | RawKindWildcard -> fresh_kind()
                | RawKindStar -> KindType
                | RawKindFun(a,b) -> KindFun(typevar a, typevar b)
            let kind = typevar kind
            let cons =
                constraints |> List.choose (fun (r,x) ->
                    match v_cons cons x with
                    | Some (M _) -> errors.Add(r,ExpectedConstraintInsteadOfModule); None
                    | Some (C x) -> unify_kind r kind (constraint_kind top_env x); Some x
                    | None -> errors.Add(r,UnboundVariable x); None
                    ) |> Set.ofList
    

            {scope=scope; constraints=cons; kind=kind_force kind; name=name}
    

        let typevars scope env (l : TypeVar list) =
            List.mapFold (fun s x ->
                let v = typevar_to_var scope env.constraints x
                v, Map.add v.name (tyvar v) s
                ) env.ty l
    

        let rec term scope env s x = term' scope false env s x
        and term' scope is_in_left_apply (env : InferEnv) s x =
            let f = term scope env
            let f' x = let v = fresh_var scope in f v x; visit_t v
            let f'' x = let v = fresh_var scope in term' scope true env v x; visit_t v
            let inline rawv (r,name,is_tvar_applied) =
                match v_term env name with
                | None -> errors.Add(r,UnboundVariable name)
                | Some (_,TySymbol "<real>") -> errors.Add(r,RealFunctionInTopDown)
                | Some (com,TyModule _ & m) when is_in_left_apply = false ->
                    hover_types.AddHover(r,(m,com))
                    errors.Add(r,ModuleMustBeImmediatelyApplied)
                | Some (com,a) ->
                    if is_tvar_applied then
                        match a with TyForall _ -> annotations.Add(x,(r,s)) | _ -> ()
                        let f a = let l,v = forall_subst_all scope a in unify r s v; l
                        let l = f a
                        hover_types.AddHover(r,(s,com))
                        type_apply_args.Add(name,(l,f))
                    else
                        unify r s a
                        hover_types.AddHover(r,(s,com))
            let match_clause (q,w) (a,b) =
                let gadt_links, gadt_typecases', (scope, env) = pattern scope env q a
                term scope env w b
                dispose_gadt_links gadt_links
                gadt_typecases.Add(b,gadt_typecases')
            match x with
            | RawB r -> unify r s TyB
            | RawV(r,a,is_tvar_applied) -> rawv (r,a,is_tvar_applied)
            | RawDefaultLit(r,_) -> unify r s (fresh_subst_var scope (Set.singleton CNumber) KindType); hover_types.AddHover(r,(s,"")); annotations.Add(x,(r,s))
            | RawLit(r,a) -> unify r s (lit a)
            | RawSymbol(r,x) -> unify r s (TySymbol x)
            | RawIfThenElse(_,cond,tr,fl) -> f (TyPrim BoolT) cond; f s tr; f s fl
            | RawIfThen(r,cond,tr) -> f (TyPrim BoolT) cond; unify r s TyB; f TyB tr
            | RawPair(r,a,b) ->
                let q,w = fresh_var scope, fresh_var scope
                unify r s (TyPair(q, w))
                f q a; f w b
            | RawSeq(_,a,b) -> f TyB a; f s b
            | RawReal(_,a) -> assert_bound_vars env a
            | RawOp(_,_,l) -> List.iter (assert_bound_vars env) l
            | RawJoinPoint(r,None,a,_) -> annotations.Add(x,(r,s)); f s a
            | RawJoinPoint(r,Some _,a,_) ->
                unify r s (TySymbol "tuple_of_free_vars")
                let s = fresh_var scope
                annotations.Add(x,(r,s))
                f s a
            | RawApply(r,a',b) ->
                let rec loop = function
                    | TyNominal _ | TyApply _ as a ->
                        match type_apply_split a with
                        | TyNominal i, l ->
                            let n = top_env.nominals.[i]
                            match n.body with
                            | TyUnion _ -> errors.Add(r,UnionsCannotBeApplied)
                            | _ ->
                                match Utils.list_try_zip n.vars l with
                                | Some l -> loop (subst l n.body)
                                | None -> errors.Add(r,MalformedNominal)
                        | _ -> errors.Add(r,ExpectedNominalInApply a)
                    | TyLayout(a,_) ->
                        match visit_t a with
                        | TyRecord l -> apply_record r s l (f' b)
                        | a -> errors.Add(r,ExpectedRecordInsideALayout a)
                    | TyRecord l -> apply_record r s l (f' b)
                    | TyModule l ->
                        match f' b with
                        | TySymbol n ->
                            match Map.tryFind n l with
                            | Some (TyModule _ as a) ->
                                if is_in_left_apply then
                                    match b with RawSymbol(r,_) -> hover_types.AddHover(r,(a,"")) | _ -> ()
                                    unify r s a
                                // (disabled) else errors.Add(r,ModuleMustBeImmediatelyApplied)
                            | Some a' ->
                                let typevars,a = forall_subst_all scope a'
                                if List.isEmpty typevars = false then
                                    annotations.Add(x,(r,s))
                                    module_type_apply_args.Add(x,typevars)
                                unify r s a
                                match b with
                                | RawSymbol(r,_) ->
                                    let com = match a' with TyComment(com,_) -> com | _ -> ""
                                    hover_types.AddHover(r,(a,com))
                                | _ -> ()
                            | None -> errors.Add(r,ModuleIndexFailed n)
                        | b -> errors.Add(r,ExpectedSymbolAsModuleKey b)
                    | TyFun(domain,range,_) -> unify (range_of_expr a') range s; f domain b
                    | a -> let v = fresh_var scope in unify (range_of_expr a') a (TyFun(v,s,FT_Vanilla)); f v b
                loop (f'' a')
            | RawAnnot(r,a,b) ->  ty_init scope env s b; f s a
            | RawOpen(_,(r,a),l,on_succ) ->
                match inferModule_open (Some hover_types) (loc_env top_env) env.ty r a l with
                | Ok x ->
                    let combine big small = Map.foldBack Map.add small big
                    term scope {term = combine env.term x.term; ty = combine env.ty x.ty; constraints = combine env.constraints x.constraints} s on_succ
                | Error e -> errors.Add(e)
            | RawRecordWith(r,l,withs,withouts) ->
                let i = errors.Count
                let withouts,fields =
                    List.foldBack (fun x (l,s as state) ->
                        match x with
                        | RawRecordWithoutSymbol(r,a) -> {|range=r; symbol = a|} :: l, Set.add a s
                        | RawRecordWithoutInjectVar(r,a) ->
                            match v_term env a with
                            | Some (com, TySymbol a & x) -> hover_types.AddHover(r,(x,com)); {|range=r; symbol = a|} :: l, Set.add a s
                            | Some (_,x) -> errors.Add(r, ExpectedSymbolAsRecordKey x); state
                            | None -> errors.Add(r, UnboundVariable a); state
                        ) withouts ([],Set.empty)
                let withs,_ =
                    List.foldBack (fun x (l,s as state) ->
                        let with_symbol ((r,a),b) = {|range=r; symbol = a; is_blocked=Set.contains a s; is_modify=false; var=fresh_var scope; body=b|} :: l, Set.add a s
                        let with_symbol_modify ((r,a),b) = {|range=r; symbol = a; is_blocked=Set.contains a s; is_modify=true; var=TyFun(fresh_var scope,fresh_var scope,FT_Vanilla); body=b|} :: l, Set.add a s
                        let inline with_inject next ((r,a),b) =
                            match v_term env a with
                            | Some (com, TySymbol a & x) -> hover_types.AddHover(r,(x,com)); next ((r,a),b)
                            | Some (_, x) -> errors.Add(r, ExpectedSymbolAsRecordKey x); f' b |> ignore; state
                            | None -> errors.Add(r, UnboundVariable a); f' b |> ignore; state
                        match x with
                        | RawRecordWithSymbol(a,b) -> with_symbol (a,b)
                        | RawRecordWithSymbolModify(a,b) -> with_symbol_modify (a,b)
                        | RawRecordWithInjectVar(a,b) -> with_inject with_symbol (a,b)
                        | RawRecordWithInjectVarModify(a,b) -> with_inject with_symbol_modify (a,b)
                        ) withs ([],fields)
    

                let eval m =
                    let m = (m,withs) ||> List.fold (fun m x ->
                        if x.is_modify then
                            let i, q =
                                match m |> Map.tryPick (fun (i, k) v -> if k = x.symbol then Some (i, v) else None) with
                                | Some q -> q
                                | None -> errors.Add(x.range,RecordIndexFailed x.symbol); m.Count, fresh_var scope
                            let w = fresh_var scope
                            unify x.range (TyFun(q,w,FT_Vanilla)) x.var
                            f x.var x.body
                            Map.add (i, x.symbol) w m
                        else
                            f x.var x.body
                            let i =
                                m
                                |> Map.tryPick (fun (i, k) v -> if k = x.symbol then Some i else None)
                                |> Option.defaultValue m.Count
                            Map.add (i, x.symbol) x.var m
                        )
                    withouts |> List.fold (fun m x -> m |> Map.filter (fun (_, k) _ -> k <> x.symbol)) m
    

                let bind s = withs |> List.iter (fun x ->
                    if x.is_blocked = false then
                        if x.is_modify then
                            s
                            |> Map.tryPick (fun (i, k') v -> if k' = x.symbol then Some (i, v) else None)
                            |> Option.iter (fun (_, k) -> unify x.range x.var (TyFun(fresh_var scope,k,FT_Vanilla)))
                        else
                            s
                            |> Map.tryPick (fun (i, k') v -> if k' = x.symbol then Some (i, v) else None)
                            |> Option.iter (fun (_, k) -> k |> unify x.range x.var)
                    )
    

                let rec tail' m = function
                    | x :: xs ->
                        match f' x with
                        | TySymbol k ->
                            match m |> Map.tryPick (fun (i, k') v -> if k' = k then Some (i, v) else None) with
                            | Some (i, m) ->
                                match visit_t m with
                                | TyRecord m -> tail' m xs
                                | m -> errors.Add(range_of_expr x, ExpectedRecordAsResultOfIndex m); eval Map.empty
                            | _ -> errors.Add(range_of_expr x, RecordIndexFailed k); eval Map.empty
                            |> fun v ->
                                let i = m |> Map.tryPick (fun (i, k') v -> if k' = k then Some (i, v) else None)
                                match i with
                                | Some (i, _) -> Map.add (i, k) (TyRecord v) m
                                | None -> Map.add (m.Count, k) (TyRecord v) m
                        | TyMetavar _ -> errors.Add(range_of_expr x, MetavarsNotAllowedInRecordWith); eval Map.empty
                        | a -> errors.Add(range_of_expr x, ExpectedSymbolInRecordWith a); eval Map.empty
                    | [] -> eval m
    

                let rec tail (m,s) = function
                    | x :: xs ->
                        match f' x with
                        | TySymbol k ->
                            match
                                m |> Map.tryPick (fun (i, k') v -> if k' = k then Some (i, v) else None),
                                s |> Map.tryPick (fun (i, k') v -> if k' = k then Some (i, v) else None)
                            with
                            | Some (i,m), Some (_i',s) ->
                                match visit_t m, visit_t s with
                                | TyRecord m, TyRecord s -> i, tail (m,s) xs
                                | TyRecord m, _ -> i, tail' m xs
                                | m, _ -> errors.Add(range_of_expr x, ExpectedRecordAsResultOfIndex m); i, eval Map.empty
                            | Some (i,m), None ->
                                match visit_t m with
                                | TyRecord m -> i, tail' m xs
                                | m -> errors.Add(range_of_expr x, ExpectedRecordAsResultOfIndex m); i, eval Map.empty
                            | _ -> errors.Add(range_of_expr x, RecordIndexFailed k); i, eval Map.empty
                            |> fun (i,v) -> Map.add (i,k) (TyRecord v) m
                        | TyMetavar _ -> errors.Add(range_of_expr x, MetavarsNotAllowedInRecordWith); eval Map.empty
                        | a -> errors.Add(range_of_expr x, ExpectedSymbolInRecordWith a); eval Map.empty
                    | [] -> bind s; eval m
    

                match l with
                | [] ->
                    match visit_t s with TyRecord s -> bind s | _ -> ()
                    eval Map.empty
                | m :: l ->
                    match f' m, visit_t s with
                    | TyRecord m, TyRecord s -> tail (m,s) l
                    | TyRecord m, _ -> tail' m l
                    | TyMetavar _, _ -> errors.Add(range_of_expr x, MetavarsNotAllowedInRecordWith); eval Map.empty
                    | a,_ -> errors.Add(range_of_expr x, ExpectedRecord a); eval Map.empty
                |> fun v -> if errors.Count = i then unify r (TyRecord v) s
            | RawExists(r,(r',l),body) ->
                match visit_t s with
                | TyExists(type_vars,type_body) ->
                    let vars, s = exists_subst_term scope (type_vars,type_body)
                    l |> Option.iter (fun l ->
                        let l1,l2 = vars.Length, l.Length
                        if l1 = l2 then List.iter2 (ty_init scope env) vars l
                        else errors.Add(r', UnexpectedNumberOfArgumentsInExistsBody(l1,l2))
                        )
                    term scope env s body
                    assert_exists_hasnt_metavars (range_of_expr x) vars
                    exists_vars.Add(x,vars)
                | s -> errors.Add(r, ExpectedExistentialInTerm s); f (fresh_var scope) body
            | RawFun(r,l) ->
                annotations.Add(x,(r,s))
                let q,w = fresh_var scope, fresh_var scope
                unify r s (TyFun(q,w,FT_Vanilla))
                List.iter (match_clause (q,w)) l
            | RawForall _ -> failwith "Compiler error: Should be handled in let statements."
            | RawMatch(_,(RawForall _ | RawFun _) & body,[PatVar(r,name), on_succ]) -> term scope (inl scope env ((r, name), body)) s on_succ
            | RawRecBlock(_,l',on_succ) -> term scope (rec_block scope env l') s on_succ
            | RawMatch(_,body,l) ->
                let body_var = fresh_var scope
                f body_var body
                List.iter (match_clause (body_var,s)) l
            | RawMissingBody r -> errors.Add(r,MissingBody)
            | RawMacro(r,a) ->
                annotations.Add(x,(r,s))
                List.iter (function
                    | RawMacroText _ -> ()
                    | RawMacroTerm(_,a,_) -> term scope env (fresh_var scope) a
                    | RawMacroType(_,a) | RawMacroTypeLit(_,a) -> ty_init scope env (fresh_var scope) a
                    ) a
            | RawHeapMutableSet(r,a,b,c) ->
                unify r s TyB
                try let v = fresh_var scope
                    let i = errors.Count
                    f v a
                    match visit_t v with
                    | TyMetavar _ -> raise (InferTypeErrorException [r, LayoutSetMustBeAnnotated])
                    | TyLayout(v,lay) ->
                        match lay with
                        | HeapMutable | StackMutable ->
                            if i <> errors.Count then raise (InferTypeErrorException [])
                            let b = List.map (fun x -> range_of_expr x, f' x) b
                            List.fold (fun (r,a') (r',b') ->
                                match visit_t a' with
                                | TyRecord a ->
                                    match b' with
                                    | TySymbol b ->
                                        match a |> Map.tryPick (fun (_, k) v -> if k = b then Some v else None) with
                                        | Some x -> r', x
                                        | _ -> raise (InferTypeErrorException [r, RecordIndexFailed b])
                                    | b -> raise (InferTypeErrorException [r', ExpectedSymbol' b])
                                | a -> raise (InferTypeErrorException [r, ExpectedRecord a])
                                ) (range_of_expr a, v) b |> snd
                        | Heap -> raise (InferTypeErrorException [r, ExpectedMutableLayout v])
                    | v -> raise (InferTypeErrorException [r, ExpectedMutableLayout v])
                with :? InferTypeErrorException as e -> errors.AddRange e.Data0; fresh_var scope
                |> fun v -> f v c
            | RawArray(r,a) ->
                annotations.Add(x,(r,s))
                let v = fresh_var scope
                unify r s (TyArray v)
                List.iter (f v) a
            | RawFilledForall _ -> failwith "Compiler error: Should not manifest during type inference."
            | RawType _ -> failwith "Compiler error: RawType should not appear in the top down segment."
            | RawTypecase _ -> failwith "Compiler error: `typecase` should not appear in the top down segment."
        and inl scope env ((r, name), body) =
            let scope = scope + 1
            let vars,body = foralls_get body
            vars |> List.iter (fun ((r,(name,_)),_) -> if Map.containsKey name env.ty then errors.Add(r,ShadowedForall))
            let vars,env_ty = typevars scope env vars
            let body_var = fresh_var scope
            term scope {env with ty = env_ty} body_var body
            let t = generalize r scope vars body_var
            generalized_statements.Add(body,t)
            hover_types.AddHover(r,(t,""))
            {env with term = Map.add name t env.term }
        and rec_block scope env l' =
            let rec term_annotations scope env x =
                let f t =
                    let i = errors.Count
                    let v = fresh_var scope
                    ty_init scope env v t
                    if i = errors.Count && has_metavars v then errors.Add(range_of_texpr t, RecursiveAnnotationHasMetavars v)
                    v
                match x with
                | RawFun(_,[(PatAnnot(_,_,t) | PatDyn(_,PatAnnot(_,_,t))),body]) -> TyFun(f t, term_annotations scope env body,FT_Vanilla)
                | RawFun(_,[pat,body]) -> errors.Add(range_of_pattern pat, ExpectedAnnotation); TyFun(fresh_var scope, term_annotations scope env body,FT_Vanilla)
                | RawFun(r,_) -> errors.Add(r, ExpectedSinglePattern); TyFun(fresh_var scope, fresh_var scope, FT_Vanilla)
                | RawJoinPoint(_,_,RawAnnot(_,_,t),_) | RawAnnot(_,_,t) -> f t
                | x -> errors.Add(range_of_expr x,ExpectedAnnotation); fresh_var scope
            let scope = scope + 1
            let has_foralls = List.exists (function (_,RawForall _) -> true | _ -> false) l'
            let l,m =
                if has_foralls then
                    List.mapFold (fun s ((r,name),body) ->
                        let vars,body = foralls_get body
                        vars |> List.iter (fun x -> if Map.containsKey (typevar_name x) env.ty then errors.Add(range_of_typevar x,ShadowedForall))
                        let vars, env_ty = typevars scope env vars
                        let body_var = term_annotations scope {env with ty = env_ty} body
                        let term env = term scope {env with ty = env_ty} body_var body
                        let gen env : InferEnv =
                            let t = generalize r scope vars body_var
                            generalized_statements.Add(body,t)
                            hover_types.AddHover(r,(t,""))
                            {env with term = Map.add name t env.term}
                        let ty = List.foldBack (fun x s -> TyForall(x,s)) vars body_var |> term_subst
                        (term, gen), Map.add name ty s
                        ) env.term l'
                else
                    List.mapFold (fun s ((r,name),body) ->
                        let body_var = fresh_var scope
                        let term env = term scope env body_var body
                        let gen env : InferEnv =
                            let t = generalize r scope [] body_var
                            generalized_statements.Add(body,t)
                            hover_types.AddHover(r,(t,""))
                            {env with term = Map.add name t env.term}
                        (term, gen), Map.add name body_var s
                        ) env.term l'
            let _ =
                let env = {env with term = m}
                List.iter (fun (term, _) -> term env) l
            List.fold (fun env (_, gen) -> gen env) env l
        and ty_init scope env s x =
            ty scope env s x
            assert_foralls_used errors (range_of_texpr x) s
        and ty scope env s x = ty' scope false env s x
        and ty' scope is_in_left_apply (env : InferEnv) s x =
            let f s x = ty scope env s x
            match x with
            | RawTTypecase _ -> failwith "Compiler error: Type level typecase should not appear in the top down segment."
            | RawTWildcard r -> hover_types.AddHover(r,(s,""))
            | RawTArray(r,a) ->
                let v = fresh_var scope
                unify r s (TyArray v)
                f v a
            | RawTVar(r,x) ->
                match v_ty env x with
                | Some (TyModule _ & m) when is_in_left_apply = false -> hover_types.AddHover(r,(m,"")); errors.Add(r,ModuleMustBeImmediatelyApplied)
                | Some x -> unify r s x; hover_types.AddHover(r,(x,""))
                | None -> errors.Add(r, UnboundVariable x)
            | RawTB r -> unify r s TyB
            | RawTLit(r,x) -> unify r s (TyLit x)
            | RawTSymbol(r,x) -> unify r s (TySymbol x)
            | RawTPrim(r,x) -> unify r s (TyPrim x)
            | RawTPair(r,a,b) ->
                let q,w = fresh_var scope, fresh_var scope
                unify r s (TyPair(q,w))
                f q a; f w b
            | RawTFun(r,a,b,t) ->
                let q,w = fresh_var scope, fresh_var scope
                unify r s (TyFun(q,w,t))
                f q a; f w b
            | RawTRecord(r,l) ->
                let l' = Map.map (fun _ _ -> fresh_var scope) l
                unify r s (TyRecord l')
                Map.iter (fun k s -> f s l.[k]) l'
            | RawTUnion(r,l,lay,_) ->
                let l' = Map.map (fun _ (is_gadt,_) -> is_gadt, fresh_var scope) l
                unify r s (TyUnion(l',lay))
                Map.iter (fun k (is_gadt,s) -> let x = snd l.[k] in if is_gadt then ty scope {env with ty = Map.empty} s x else f s x) l'
            | RawTExists(r,a,b) ->
                let a = List.map (typevar_to_var scope env.constraints) a
                let body_var = fresh_var scope
                ty scope {env with ty = List.fold (fun s a -> Map.add a.name (tyvar a) s) env.ty a} body_var b
                unify r s (TyExists(a, body_var))
            | RawTForall(r,a,b) ->
                let a = typevar_to_var scope env.constraints a
                let body_var = fresh_var scope
                ty scope {env with ty = Map.add a.name (tyvar a) env.ty} body_var b
                unify r s (TyForall(a, body_var))
            | RawTApply(r,a',b) ->
                let f' b k x = let v = fresh_var' scope k in ty' scope b env v x; visit_t v
                match f' true (fresh_kind ()) a' with
                | TyModule l ->
                    match f' false KindType b with
                    | TySymbol x ->
                        match Map.tryFind x l with
                        | Some (TyModule _ as a) ->
                            if is_in_left_apply then
                                unify r s a
                                match b with RawTSymbol(r,_) -> hover_types.AddHover(r,(a,"")) | _ -> ()
                            else errors.Add(r,ModuleMustBeImmediatelyApplied)
                        | Some a ->
                            unify r s a
                            match b with
                            | RawTSymbol(r,_) ->
                                let com = match a with TyComment(com,_) -> com | _ -> ""
                                hover_types.AddHover(r,(a,com))
                            | _ -> ()
                        | None -> errors.Add(r,ModuleIndexFailed x)
                    | b -> errors.Add(r,ExpectedSymbolAsRecordKey b)
                | TyInl(a,body) -> let v = fresh_var' scope a.kind in f v b; unify r s (subst [a,v] body)
                | a ->
                    let q,w = fresh_kind(), fresh_kind()
                    unify_kind (range_of_texpr a') (tt top_env a) (KindFun(q,w))
                    let x = fresh_var' scope q
                    f x b
                    unify r s (TyApply(a,x,w))
            | RawTTerm(r,a) -> assert_bound_vars env a; unify r s (TySymbol "<term>")
            | RawTMacro(r,a) ->
                List.map (function
                    | RawMacroText(_,a) -> TMText a
                    | RawMacroTerm _ -> failwith "Compiler error: Term vars should never appear at the type level."
                    | RawMacroType(r,a) | RawMacroTypeLit(r,a) -> let v = fresh_var scope in f v a; TMVar v
                    ) a
                |> TyMacro |> unify r s
            | RawTLayout(r,a,b) ->
                let v = fresh_var scope
                unify r s (TyLayout(v,b))
                f v a
            | RawTFilledNominal _ -> failwith "Compiler error: RawTNominal should be filled in by the inferencer."
            | RawTMetaVar _ -> failwith "Compiler error: This particular metavar is only for typecase's clauses. This happens during the bottom-up segment."
        and pattern (scope : InferScope) (env : InferEnv) s a : T option ref ResizeArray * (T * T list * T) ResizeArray * (InferScope * InferEnv) =
            let gadt_links = ResizeArray()
            let gadt_typecases = ResizeArray()
            let term_vars = Dictionary(HashIdentity.Structural)
            let ty_vars = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Structural)
            let mutable scope = scope
            let update_env () =
                scope,
                {env with
                    ty = (env.ty,ty_vars) ||> Seq.fold (fun s x -> Map.add x.Key x.Value s)
                    term = (env.term,term_vars) ||> Seq.fold (fun s x -> Map.add x.Key x.Value s)
                    }
            let ho_make (i : GlobalId) (l : Var list) =
                let h = TyNominal i
                let l' = List.map (fun (x : Var) -> x, fresh_subst_var scope x.constraints x.kind) l
                List.fold (fun s (_,x) -> match tt top_env s with KindFun(_,k) -> TyApply(s,x,k) | _ -> failwith "impossible") h l', l'
            let rec ho_index x =
                match visit_t x with
                | TyApply(a,_,_) -> ho_index a
                | TyNominal i -> ValueSome i
                | _ -> ValueNone
            let rec ho_fun x =
                match visit_t x with
                | TyFun(_,a,_) | TyForall(_,a) -> ho_fun a
                | a -> ho_index a
            let rec loop s x : unit =
                let f = loop
                match x with
                | PatFilledDefaultValue _ -> failwith "Compiler error: PatDefaultValueFilled should not appear during inference."
                | PatB r -> unify r s TyB
                | PatE r -> hover_types.AddHover(r,(s,""))
                | PatVar(r,a) ->
                    match term_vars.TryGetValue(a) with
                    | true, v -> unify r s v
                    | _ -> term_vars.Add(a,s)
                    hover_types.AddHover(r,(s,""))
                | PatDyn(_,a) -> f s a
                | PatAnnot(_,a,b) -> ty_init scope env s b; f s a
                | PatWhen(_,a,b) ->
                    f s a
                    let scope,env = update_env()
                    term scope env (TyPrim BoolT) b
                | PatPair(r,a,b) ->
                    let q,w = fresh_var scope, fresh_var scope
                    unify r s (TyPair(q,w))
                    loop q a; loop w b
                | PatSymbol(r,a) -> unify r s (TySymbol a)
                | PatOr(_,a,b) | PatAnd(_,a,b) -> loop s a; loop s b
                | PatValue(r,a) -> unify r s (lit a)
                | PatDefaultValue(r,_) ->
                    annotations.Add(x,(r,s))
                    unify r s (fresh_subst_var scope (Set.singleton CNumber) KindType)
                    hover_types.AddHover(r,(s,""))
                | PatRecordMembers(r,l) ->
                    let l =
                        List.choose (function
                            | PatRecordMembersSymbol((r,a),b) -> Some (a,b)
                            | PatRecordMembersInjectVar((r,a),b) ->
                                match v_term env a with
                                | Some (com,TySymbol a & x) -> hover_types.AddHover(r,(x,com)); Some (a,b)
                                | Some (_,x) -> errors.Add(r, ExpectedSymbolAsRecordKey x); None
                                | None -> errors.Add(r, UnboundVariable a); None
                            ) l
                    match visit_t s with
                    | TyRecord l' as s ->
                        let l, missing =
                            List.mapFoldBack (fun (a,b) missing ->
                                match l' |> Map.tryPick (fun (i, k) v -> if k = a then Some (i, v) else None) with
                                | Some (_,x) -> (x,b), missing
                                | None -> (fresh_var scope,b), a :: missing
                                ) l []
                        if List.isEmpty missing = false then errors.Add(r, MissingRecordFieldsInPattern(s, missing))
                        List.iter (fun (a,b) -> loop a b) l
                    | s ->
                        let l =
                            List.mapi (fun i (a,b) ->
                                let v = fresh_var scope
                                loop v b
                                (i, a), v
                                ) l
                        unify r s (l |> Map |> TyRecord)
                | PatExists(r,l,p) ->
                    l |> List.iter (fun (r,name) -> if Map.containsKey name env.ty then errors.Add(r,ShadowedExists))
                    match visit_t s with
                    | TyExists(type_var_list,type_body) ->
                        if l.Length = type_var_list.Length then
                            scope <- scope + 1
                            let vars = (l, type_var_list) ||> List.map2 (fun (_,name) l ->
                                Utils.memoize ty_vars (fun name -> tyvar {l with scope=scope; name=name}) name
                                )
                            loop (subst (List.zip type_var_list vars) type_body) p
                        else
                        errors.Add(r, UnexpectedNumberOfArgumentsInExistsPattern(l.Length,type_var_list.Length))
                    | s -> errors.Add(r, ExpectedExistentialInPattern s)
                | PatUnbox(r,name,a) ->
                    let assume i =
                        let n = top_env.nominals.[i]
                        match n.body with
                        | TyUnion(cases,_) ->
                            let x,m = ho_make i n.vars
                            unify r s x
                            match Map.tryPick (fun (_, name') v -> if name = name' then Some v else None) cases with
                            | Some (is_gadt, v) ->
                                if is_gadt then
                                    scope <- scope + 1
                                    let forall_vars,body,specialized_constructor = gadt_extract scope v
                                    gadt_typecases.Add(s, forall_vars, specialized_constructor)
                                    match a with PatE r' when r = r' -> () | _ -> loop body a // This check for PatE is so the hovers for it don't overwrite the main pattern.
                                    unify_gadt (Some gadt_links) r s specialized_constructor
                                else
                                    match a with PatE r' when r = r' -> () | _ -> f (subst m v) a
                                hover_types.AddHover(r,(s,""))
                            | None -> errors.Add(r,CasePatternNotFoundForType(i,name)); f (fresh_var scope) a
                        | _ -> errors.Add(r,NominalInPatternUnbox i); f (fresh_var scope) a
                    match ho_index s with
                    | ValueSome i -> assume i
                    | ValueNone ->
                        match v_term env name with
                        | Some (_,x) ->
                            match ho_fun x with
                            | ValueSome i -> assume i
                            | ValueNone -> errors.Add(r,CannotInferCasePatternFromTermInEnv x); f (fresh_var scope) a
                        | None -> errors.Add(r,CasePatternNotFound name); f (fresh_var scope) a
                | PatNominal(_,(r,name),l,a) ->
                    match v_ty env name with
                    | Some x ->
                        let rec loop r x = function
                            | (r,name) :: l ->
                                match x with
                                | TyModule x ->
                                    match Map.tryFind name x with
                                    | Some x -> loop r x l
                                    | None -> errors.Add(r,ModuleIndexFailed name); f (fresh_var scope) a
                                | _ ->
                                    errors.Add(r,ExpectedModule x); f (fresh_var scope) a
                            | [] ->
                                match ho_index x with
                                | ValueSome i ->
                                    let n = top_env.nominals.[i]
                                    match n.body with
                                    | TyUnion _ -> errors.Add(r,UnionInPatternNominal i); f (fresh_var scope) a
                                    | _ -> let x,m = ho_make i n.vars in unify r s x; f (subst m n.body) a
                                | ValueNone -> errors.Add(r,TypeInEnvIsNotNominal x); f (fresh_var scope) a
                        loop r x l
                    | _ -> errors.Add(r,UnboundVariable name); f (fresh_var scope) a
                | PatArray(r,a) ->
                    let v = fresh_var scope
                    unify r s (TyArray v)
                    List.iter (fun x -> loop v x) a
            loop s a
            gadt_links, gadt_typecases, update_env()
    

        let nominal_term global_id tt name vars v =
            let constructor body =
                let t,_ = List.fold (fun (a,k) b -> let k = trim_kind k in TyApply(a,tyvar b,k),k) (TyNominal global_id,tt) vars
                let x = match body with TyB -> t | _ -> TyFun(body,t,FT_Vanilla)
                List.foldBack (fun var ty -> TyForall(var,ty)) vars x
            match v with
            | TyUnion(l,_) -> Map.fold (fun s (_,name) (is_gadt,v) -> Map.add name (if is_gadt then v else constructor v) s) Map.empty l
            | _ -> Map.add name (constructor v) Map.empty
    

        let psucc = Hopac.Job.thunk >> Hopac.Hopac.memo
        let pfail = psucc (fun () -> FError(Unchecked.defaultof<_>))
    

        let top_env_nominal top_env (global_id : GlobalId) tt name vars v : TopEnv =
            { top_env with
                nominals_next_tag = max top_env.nominals_next_tag global_id.tag + 1
                nominals_aux = Map.add global_id {|kind=tt; name=name|} top_env.nominals_aux
                nominals = Map.add global_id {|vars=vars; body=v|} top_env.nominals
                term = Map.foldBack Map.add (nominal_term global_id tt name vars v) top_env.term
                ty = Map.add name (TyNominal global_id) top_env.ty
                }
    

        let rec typevar = function
            | RawKindWildcard | RawKindStar -> KindType
            | RawKindFun(a,b) -> KindFun(typevar a, typevar b)
        let hovars (x : HoVar list) =
            List.mapFold (fun s (_,(n,t)) ->
                let v = {scope=0; kind=typevar t; name=n; constraints=Set.empty}
                v, Map.add n (tyvar v) s
                ) Map.empty x
    

        let scope = 0
        let bundle_nominal_rec l' =
            let l,_ =
                List.mapFold (fun i (_,name,vars,body) ->
                    let l,env = hovars vars
                    let tt = List.foldBack (fun (x : Var) s -> KindFun(x.kind,s)) l KindType
                    (at_tag i,name,l,env,tt,body), i+1
                    ) top_env.nominals_next_tag l'
    

            top_env <-
                {top_env with
                    nominals_aux = (top_env.nominals_aux, l) ||> List.fold (fun s (i,(_,name),_,_,tt,_) -> Map.add i {|name=name; kind=tt|} s)
                    ty = (top_env.ty, l) ||> List.fold (fun s (i,(_,name),_,_,_,_) -> Map.add name (TyNominal i) s)
                    }
    

            List.fold (fun top_env (global_id,(r,name),vars,env_ty,tt,body) ->
                let v = fresh_var scope
                ty_init scope {term=Map.empty; ty=env_ty; constraints=Map.empty} v body
                let v = term_subst v
                validate_nominal errors global_id body v
                top_env_nominal top_env global_id tt name vars v
                ) inferTop_env_empty l
    

        match expr with
        | BundleType(q,(r,name),vars',expr) ->
            let vars,env_ty = hovars vars'
            let v = fresh_var scope
            ty_init scope {term=Map.empty; ty=env_ty; constraints=Map.empty} v expr
            let t = List.foldBack (fun x s -> TyInl(x,s)) vars (term_subst v)
            hover_types.AddHover(r,(t,""))
            if 0 = errors.Count then psucc (fun () -> FType(q,(r,name),vars',expr)), AInclude {inferTop_env_empty with ty = Map.add name t Map.empty}
            else pfail, AInclude inferTop_env_empty
        | BundleNominal(q,(r,name),vars',expr) ->
            let x = bundle_nominal_rec [q,(r,name),vars',expr]
            if 0 = errors.Count then psucc (fun () -> FNominal(q,(r,name),vars',expr)), AInclude x
            else pfail, AInclude inferTop_env_empty
        | BundleNominalRec l ->
            let _ = // Checks that mutually recursive unions do not have duplicates.
                let h = HashSet()
                l |> List.iter (fun (_,_,_,x) ->
                    match x with
                    | RawTUnion(_,l,_,_) -> l |> Map.iter (fun k v -> if h.Add k = false then errors.Add(range_of_texpr (snd v),DuplicateKeyInRecUnion))
                    | _ -> ()
                    )
            let x = bundle_nominal_rec l
            if 0 = errors.Count then psucc (fun () -> FNominalRec l), AInclude x
            else pfail, AInclude inferTop_env_empty
        | BundlePrototype(com,r,(r',name),(w,var_init),vars',expr) ->
            let i = at_tag top_env'.prototypes_next_tag
            let cons = CPrototype i
            let scope = 0
            let vars,env_ty = typevars scope {term=Map.empty; constraints=Map.empty; ty=Map.empty} vars'
            let kind = List.foldBack (fun (k : Var) s -> KindFun(k.kind,s)) vars KindType
            let v' = {scope=scope; constraints=Set.singleton cons; name=var_init; kind=kind}
            let env_ty = Map.add var_init (tyvar v') env_ty
            let vars = v' :: vars
            let v = fresh_var scope
            ty_init scope {term=Map.empty; ty=env_ty; constraints=Map.empty} v expr
            let body = List.foldBack (fun a b -> TyForall(a,b)) vars (term_subst v)
            if 0 = errors.Count && (assert_foralls_used errors r' body; 0 = errors.Count) then
                let x =
                    { inferTop_env_empty with
                        prototypes_next_tag = i.tag + 1
                        prototypes = Map.add i {|name=name; signature=body; kind=v'.kind|} Map.empty
                        term = Map.add name (if com <> "" then TyComment(com,body) else body) Map.empty
                        constraints = Map.add name (C cons) Map.empty
                        }
                psucc (fun () -> FPrototype(r,(r',name),(w,var_init),vars',expr)), AInclude x
            else pfail, AInclude inferTop_env_empty
        | BundleInl(com,q,(_,name as w),a,true) ->
            let env = inl scope {term=Map.empty; ty=Map.empty; constraints=Map.empty} (w,a)
            let term =
                let x = env.term.[name]
                if com <> "" then TyComment(com, x) else x
            (if 0 = errors.Count then psucc (fun () -> FInl(q,w,fill q Map.empty a)) else pfail),
            AInclude { inferTop_env_empty with term = Map.add name term Map.empty}
        | BundleInl(com,q,(_,name as w),a,false) ->
            assert_bound_vars {term=Map.empty; ty=Map.empty; constraints=Map.empty} a
            (if 0 = errors.Count then psucc (fun () -> FInl(q,w,a)) else pfail),
            AInclude { inferTop_env_empty with term = Map.add name (TySymbol "<real>") Map.empty }
        | BundleRecInl(l,is_top_down) ->
            let _ =
                let h = HashSet()
                List.iter (fun (_,_,(r,n),_) -> if h.Add n = false then errors.Add(r,DuplicateRecInlName)) l
            let env_term =
                if is_top_down then
                    let l = List.map (fun (com,_,a,b) -> a,b) l
                    (rec_block scope {term=Map.empty; ty=Map.empty; constraints=Map.empty} l).term
                else
                    let env_term = List.fold (fun s (com,_,(_,a),_) -> Map.add a (TySymbol "<real>") s) Map.empty l
                    l |> List.iter (fun (com,_,_,x) -> assert_bound_vars {term = env_term; ty = Map.empty; constraints=Map.empty} x)
                    env_term
            let filled_top =
                if 0 = errors.Count then
                    if is_top_down then psucc (fun () -> FRecInl(List.map (fun (_,a,b,c) -> a,b,fill a env_term c) l))
                    else psucc (fun () -> FRecInl(List.map (fun (_,a,b,c) -> a,b,c) l))
                else pfail
            let env_term =
                List.fold (fun env_term (com,_,(_,n),_) ->
                    if com <> "" then Map.add n (TyComment(com, Map.find n env_term)) env_term else env_term
                    ) env_term l
            filled_top, AInclude (Map.fold (fun s k v -> {s with term = Map.add k v s.term}) inferTop_env_empty env_term)
        | BundleInstance(r,prot,ins,vars,body) ->
            let fail = pfail,AInclude inferTop_env_empty
            let assert_no_kind x = x |> List.iter (fun ((r,(_,k)),_) -> match k with RawKindWildcard -> () | _ -> errors.Add(r,KindNotAllowedInInstanceForall))
            let assert_vars_count vars_count vars_expected = if vars_count <> vars_expected then errors.Add(r,InstanceCoreVarsShouldMatchTheArityDifference(vars_count,vars_expected))
            let assert_kind_compatibility got expected =
                try unify_kind' InstanceKindError r got expected
                with :? InferTypeErrorException as e -> errors.AddRange e.Data0
            let assert_kind_arity prot_kind_arity ins_kind_arity = if ins_kind_arity < prot_kind_arity then errors.Add(r,InstanceArityError(prot_kind_arity,ins_kind_arity))
            let assert_instance_forall_does_not_shadow_prototype_forall prot_forall_name = List.iter (fun ((r,(a,_)),_) -> if a = prot_forall_name then errors.Add(r,InstanceVarShouldNotMatchAnyOfPrototypes)) vars
            let assert_orphan_shadow_check (prot_id : GlobalId) (ins_id : GlobalId) =
                // if Map.containsKey (prot_id, ins_id) top_env.prototypes_instances
                // then errors.Add(r,ShadowedInstance)
                ()
            let assert_orphan_instance_check (prot_id : GlobalId) (ins_id : GlobalId) =
                // if (prot_id.package_id = package_id || ins_id.package_id = package_id) = false then errors.Add(r,OrphanInstance)
                ()
            let body prot_id ins_id =
                let ins_kind' = top_env.nominals_aux.[ins_id].kind
                let guard next = if 0 = errors.Count then next () else fail
                let ins_kind = kind_get ins_kind'
                let prototype = top_env.prototypes.[prot_id]
                hover_types.AddHover(fst prot, (prototype.signature,"")) // TODO: Add the hover for the instance signature.
                let prototype_init_forall_kind = prototype_init_forall_kind prototype.signature
                let prot_kind = kind_get prototype_init_forall_kind
                assert_kind_arity prot_kind.arity ins_kind.arity
                guard <| fun () ->
                let vars_expected = ins_kind.arity - prot_kind.arity
                assert_kind_compatibility (List.skip vars_expected ins_kind.args |> List.reduceBack (fun a b -> KindFun(a,b))) prototype_init_forall_kind
                guard <| fun () ->
                assert_vars_count (List.length vars) vars_expected
                guard <| fun () ->
                assert_no_kind vars
                guard <| fun () ->
                let ins_vars, env_ty =
                    List.mapFold (fun s (((r,_),_) & x,k) ->
                        let v = {typevar_to_var scope Map.empty x with kind = k}
                        let x = tyvar v
                        hover_types.AddHover(r,(x,""))
                        x, Map.add v.name x s
                        ) Map.empty (List.zip vars (List.take vars_expected ins_kind.args))
                let ins_constraints = ins_vars |> List.map (visit_t >> function TyVar (x,_) -> x.constraints | _ -> failwith "impossible")
                let ins_core, _ = List.fold (fun (a,k) (b : T) -> let k = trim_kind k in TyApply(a,b,k),k) (TyNominal ins_id,ins_kind') ins_vars
                let env_ty, prot_body =
                    match foralls_ty_get prototype.signature with
                    | (prot_core :: prot_foralls), prot_body ->
                        List.fold (fun ty x ->
                            assert_instance_forall_does_not_shadow_prototype_forall x.name
                            Map.add x.name (tyvar x) ty) env_ty prot_foralls,
                        let prot_body = subst [prot_core, ins_core] prot_body
                        let _ =
                            List.foldBack (fun x s -> TyForall(x,s)) prot_foralls prot_body
                            |> List.foldBack (fun x s -> match visit_t x with TyVar(x,_) -> TyForall(x,s) | _ -> failwith "impossible") ins_vars
                            |> fun x -> generalized_statements.Add(body,x)
                        prot_body
                    | _ -> failwith "impossible"
                assert_orphan_shadow_check prot_id ins_id
                assert_orphan_instance_check prot_id ins_id
                guard <| fun () ->
                top_env <- {top_env with prototypes_instances = Map.add (prot_id,ins_id) ins_constraints top_env.prototypes_instances}
                term scope {term=Map.empty; ty=env_ty; constraints=Map.empty} prot_body body
                (if 0 = errors.Count then psucc (fun () -> FInstance(r,(fst prot, prot_id),(fst ins, ins_id),fill r Map.empty body)) else pfail),
                AInclude {inferTop_env_empty with prototypes_instances = Map.add (prot_id,ins_id) ins_constraints Map.empty}
    

            let fake _ = fail
            let check_ins on_succ =
                match Map.tryFind (snd ins) top_env.ty with
                | None -> errors.Add(fst ins, UnboundVariable (snd ins)); fail
                | Some(TyNominal i') -> on_succ i'
                | Some x -> errors.Add(fst ins, ExpectedHigherOrder x); fail
            match Map.tryFind (snd prot) top_env.constraints with
            | None -> errors.Add(fst prot, UnboundVariable (snd prot)); check_ins fake
            | Some(C (CPrototype i)) -> check_ins (body i)
            | Some(C x) -> errors.Add(fst prot, ExpectedPrototypeConstraint x); check_ins fake
            | Some(M _) -> errors.Add(fst prot, ExpectedPrototypeInsteadOfModule); check_ins fake
        | BundleOpen(q,(r,a),b) ->
            match inferModule_open (Some hover_types) (loc_env top_env) Map.empty r a b with
            | Ok x -> psucc (fun () -> FOpen(q,(r,a),b)), AOpen {inferTop_env_empty with term=x.term; ty=x.ty; constraints=x.constraints}
            | Error er -> errors.Add(er); pfail, AOpen inferTop_env_empty
        |> fun (filled_top, top_env_additions) ->
            if 0 = errors.Count then
                annotations |> Seq.iter (fun (KeyValue(_,(r,x))) -> if has_metavars x then errors.Add(r, ValueRestriction x))
            {
            filled_top = filled_top
            top_env_additions = top_env_additions
            offset = bundle_range expr |> fst |> fun x -> x.line
            hovers = hover_types.ToArray() |> HopacExtensions.A.map (fun ((a:VSCRange),(b,(com : string))) -> a, let b = show_t top_env b in if com <> "" then sprintf "%s\n---\n%s" b com else b)
            errors = errors |> Seq.toList |> List.map (fun (a,b) -> a, show_type_error top_env b)
            }
    

    /// ### base_types
    let base_types (default_env : DefaultEnv) =
        let var name = {scope=0; kind=KindType; constraints=Set.empty; name=name}
        let inline inl f = let x = var "x" in TyInl(x,f x)
        let inline inl2 f = let x,y = var "x", var "y" in TyInl(x,TyInl(y,f x y))
        [
        "i8", TyPrim Int8T
        "i16", TyPrim Int16T
        "i32", TyPrim Int32T
        "i64", TyPrim Int64T
        "u8", TyPrim UInt8T
        "u16", TyPrim UInt16T
        "u32", TyPrim UInt32T
        "u64", TyPrim UInt64T
        "f32", TyPrim Float32T
        "f64", TyPrim Float64T
        "string", TyPrim StringT
        "bool", TyPrim BoolT
        "char", TyPrim CharT
        "array_base", inl (fun x -> TyArray(tyvar x))
        "heap", inl (fun x -> TyLayout(tyvar x,Layout.Heap))
        "mut", inl (fun x -> TyLayout(tyvar x,Layout.HeapMutable))
        "stack_mut", inl (fun x -> TyLayout(tyvar x,Layout.StackMutable))
        "fptr", inl2 (fun x y -> TyFun(tyvar x,tyvar y,FT_Pointer))
        "closure", inl2 (fun x y -> TyFun(tyvar x,tyvar y,FT_Closure))
        "int", TyPrim default_env.default_int
        "uint", TyPrim default_env.default_uint
        "float", TyPrim default_env.default_float
        ]
    

    /// ### inferTop_env_default
    let inferTop_env_default default_env : TopEnv =
        // Note: `top_env_default` should have no nominals, prototypes or terms.
        {inferTop_env_empty with
            ty = Map.ofList (base_types default_env)
            constraints =
                [
                "uint", CUInt
                "sint", CSInt
                "int", CInt
                "float", CFloat
                "number", CNumber
                "prim", CPrim
                "record", CRecord
                "symbol", CSymbol
                ] |> Map.ofList |> Map.map (fun _ -> C)
            }
    

    module Infer =
        let base_types x =
            base_types x
    

    /// ## Prepass
    

    /// ### Id
    type Id = int32
    

    /// ### ScopeEnv
    type ScopeEnv = {|free_vars : int []; stack_size : int|}
    

    /// ### Scope
    type Scope = {term : ScopeEnv; ty : ScopeEnv}
    

    /// ### Range
    type Range = {path : string; range : VSCRange}
    

    /// ### Macro
    type Macro =
        | MText of string
        | MTerm of E * is_inline : bool
        | MType of TPrepass
        | MLitType of TPrepass
    and TypeMacro =
        | TMText of string
        | TMType of TPrepass
        | TMLitType of TPrepass
    and RecordWith =
        | RSymbol of (Range * string) * E
        | RSymbolModify of (Range * string) * E
        | RVar of (Range * E) * E
        | RVarModify of (Range * E) * E
    and RecordWithout =
        | WSymbol of Range * string
        | WVar of Range * E
    and PatRecordMemberPrepass =
        | Symbol of (Range * string) * Id
        | Var of (Range * E) * Id
    and [<ReferenceEquality>] E =
        | EFun of Range * Id * E * TPrepass option
        | EFun' of Range * Scope * Id * E * TPrepass option
        | EForall of Range * Id * E
        | EForall' of Range * Scope * Id * E
        | ERecursiveFun' of Range * Scope * Id * E ref * TPrepass option
        | ERecursiveForall' of Range * Scope * Id * E ref
        | ERecursive of E ref // For global mutually recursive functions
        | EPatternRef of E ref
        | EJoinPoint of Range * E * TPrepass option * backend: (Range * string) option * name: string option
        | EJoinPoint' of Range * Scope * E * TPrepass option * backend: (Range * string) option * name: string option
        | EB of Range
        | EV of Id
        | ELit of Range * Literal
        | EDefaultLit of Range * string * TPrepass
        | ESymbol of Range * string
        | EType of Range * TPrepass
        | EApply of Range * E * E
        | EArray of Range * E list * TPrepass
        | ETypeApply of Range * E * TPrepass
        | ERecBlock of Range * (Id * E) list * on_succ: E
        | ERecordWith of Range * (Range * E) list * RecordWith list * RecordWithout list
        | EModule of Map<string, E>
        | EOp of Range * Op * E list
        | EPatternMiss of E
        | ETypePatternMiss of TPrepass
        | EAnnot of Range * E * TPrepass
        | EIfThenElse of Range * E * E * E
        | EIfThen of Range * E * E
        | EPair of Range * E * E
        | ESeq of Range * E * E
        | EMutableSet of Range * E * (Range * E) list * E
        | EReal of Range * E
        | EExists of Range * TPrepass list * E
        | EMacro of Range * Macro list * TPrepass
        | EPrototypeApply of Range * prototype_id: GlobalId * TPrepass
        | EPatternMemo of E
        | ENominal of Range * E * TPrepass
        // Regular pattern matching
        | ELet of Range * Id * E * E
        | EUnbox of Range * symbol: string * Id * body: E * on_succ: E * on_fail: E
        | EExistsTest of Range * bind: Id * pat_type: Id [] * pat: Id * on_succ: E * on_fail: E
        | EPairTest of Range * bind: Id * pat1: Id * pat2: Id * on_succ: E * on_fail: E
        | ESymbolTest of Range * string * bind: Id * on_succ: E * on_fail: E
        | ERecordTest of Range * PatRecordMemberPrepass list * bind: Id * on_succ: E * on_fail: E
        | EAnnotTest of Range * TPrepass * bind: Id * on_succ: E * on_fail: E
        | EUnitTest of Range * bind: Id * on_succ: E * on_fail: E
        | ENominalTest of Range * TPrepass * bind: Id * pat: Id * on_succ: E * on_fail: E
        | ELitTest of Range * Literal * bind: Id * on_succ: E * on_fail: E
        | EDefaultLitTest of Range * string * TPrepass * bind: Id * on_succ: E * on_fail: E
        | ETypecase of Range * TPrepass * (TPrepass * E) list
    and [<ReferenceEquality>] TPrepass =
        | TForall' of Range * Scope * Id * TPrepass
        | TForall of Range * Id * TPrepass
        | TArrow' of Scope * Id * TPrepass
        | TArrow of Id * TPrepass
        | TExists
        | TJoinPoint' of Range * Scope * TPrepass
        | TJoinPoint of Range * TPrepass
        | TPatternRef of TPrepass ref
        | TB of Range
        | TLit of Range * Literal
        | TV of Id
        | TPair of Range * TPrepass * TPrepass
        | TFun of TPrepass * TPrepass * FunType
        | TRecord of Range * Map<int * string,TPrepass>
        | TModule of Map<string,TPrepass>
        | TUnion of Range * (Map<int * string,TPrepass * TPrepass option> * UnionLayout)
        | TSymbol of Range * string
        | TApply of Range * TPrepass * TPrepass
        | TPrim of PrimitiveType
        | TTerm of Range * E
        | TMacro of Range * TypeMacro list
        | TNominal of GlobalId
        | TArray of TPrepass
        | TLayout of TPrepass * Layout
        | TMetaV of Id
        | TTypecase of Range * TPrepass * (TPrepass * TPrepass) list
    

    /// ### Printable
    module Printable =
        type PMacro =
            | MText of string
            | MTerm of PE * bool
            | MType of PT
            | MLitType of PT
        and PTypeMacro =
            | TMText of string
            | TMType of PT
            | TMLitType of PT
        and PRecordWith =
            | RSymbol of string * PE
            | RSymbolModify of string * PE
            | RVar of PE * PE
            | RVarModify of PE * PE
        and PRecordWithout =
            | WSymbol of string
            | WVar of PE
        and PPatRecordMember =
            | Symbol of string * Id
            | Var of PE * Id
        and [<ReferenceEquality>] PE =
            | EFun' of Scope * Id * PE * PT option
            | EForall' of Scope * Id * PE
            | ERecursiveFun' of Scope * Id * PE * PT option
            | ERecursiveForall' of Scope * Id * PE
            | ERecursive of PE
            | EJoinPoint of PE * PT option * string option
            | EJoinPoint' of Scope * PE * PT option * string option
            | EArray of PE list * PT
            | EFun of Id * PE * PT option
            | EForall of Id * PE
            | EB
            | EV of Id
            | ELit of Literal
            | EDefaultLit of string * PT
            | ESymbol of string
            | EType of PT
            | EApply of PE * PE
            | ETypeApply of PE * PT
            | ERecBlock of (Id * PE) list * on_succ: PE
            | ERecordWith of PE list * PRecordWith list * PRecordWithout list
            | EModule of Map<string, PE>
            | EOp of Op * PE list
            | EPatternMiss of PE
            | ETypePatternMiss of PT
            | EAnnot of PE * PT
            | EIfThenElse of PE * PE * PE
            | EIfThen of PE * PE
            | EPair of PE * PE
            | ESeq of PE * PE
            | EHeapMutableSet of PE * PE list * PE
            | EReal of PE
            | EExists of PT list * PE
            | EMacro of PMacro list * PT
            | EPrototypeApply of prototype_id: GlobalId * PT
            | EPatternMemo of PE
            | ENominal of PE * PT
            // Regular pattern matching
            | ELet of Id * PE * PE
            | EUnbox of Id * string * PE * PE * PE
            | EExistsTest of bind: Id * pat_type: Id [] * pat: Id * on_succ: PE * on_fail: PE
            | EPairTest of bind: Id * pat1: Id * pat2: Id * on_succ: PE * on_fail: PE
            | ESymbolTest of string * bind: Id * on_succ: PE * on_fail: PE
            | ERecordTest of PPatRecordMember list * bind: Id * on_succ: PE * on_fail: PE
            | EAnnotTest of PT * bind: Id * on_succ: PE * on_fail: PE
            | EUnitTest of bind: Id * on_succ: PE * on_fail: PE
            | ENominalTest of PT * bind: Id * pat: Id * on_succ: PE * on_fail: PE
            | ELitTest of Literal * bind: Id * on_succ: PE * on_fail: PE
            | EDefaultLitTest of string * PT * bind: Id * on_succ: PE * on_fail: PE
            | ETypecase of PT * (PT * PE) list
            | EOmmitedRecursive
        and [<ReferenceEquality>] PT =
            | TTypecase of PT * (PT * PT) list
            | TForall' of Scope * Id * PT
            | TForall of Id * PT
            | TArrow' of Scope * Id * PT
            | TArrow of Id * PT
            | TExists
            | TJoinPoint' of Scope * PT
            | TJoinPoint of PT
            | TB
            | TLit of Literal
            | TV of Id
            | TMetaV of Id
            | TPair of PT * PT
            | TFun of PT * PT * FunType
            | TFunPtr of PT * PT
            | TRecord of Map<int * string,PT>
            | TModule of Map<string,PT>
            | TUnion of Map<int * string,PT> * UnionLayout
            | TSymbol of string
            | TApply of PT * PT
            | TPrim of PrimitiveType
            | TTerm of PE
            | TMacro of PTypeMacro list
            | TNominal of GlobalId
            | TArray of PT
            | TLayout of PT * Layout
    

        let eval x =
            let recs = System.Collections.Generic.HashSet(HashIdentity.Reference)
            let pat_ref_term = Dictionary(HashIdentity.Reference)
            let pat_ref_ty = Dictionary(HashIdentity.Reference)
            let rec term = function
                | E.ETypecase(r,a,b) -> ETypecase(ty a,b |> List.map (fun (a,b) -> ty a, term b))
                | E.EPatternRef a ->
                    match pat_ref_term.TryGetValue a with
                    | true, v -> v
                    | false, _ ->
                        pat_ref_term.Add(a, EOmmitedRecursive)
                        let r = a.Value
                        let v = if isNull (box r) then EOmmitedRecursive else term r
                        pat_ref_term.[a] <- v
                        v
                | E.EFun'(_,a,b,c,d) -> EFun'(a,b,term c,Option.map ty d)
                | E.EForall'(_,a,b,c) -> EForall'(a,b,term c)
                | E.EArray(_,a,b) -> EArray(List.map term a,ty b)
                | E.ERecursiveFun'(_,a,b,c,d) ->
                    let r = c.Value
                    let r = if recs.Add(r) then term r else EOmmitedRecursive
                    ERecursiveFun'(a,b,r,Option.map ty d)
                | E.ERecursiveForall'(_,a,b,c) ->
                    let r = c.Value
                    let r = if recs.Add(r) then term r else EOmmitedRecursive
                    ERecursiveForall'(a,b,r)
                | E.ERecursive a ->
                    let r = a.Value
                    if isNull (box r) then EOmmitedRecursive
                    else
                        let r = if recs.Add(r) then term r else EOmmitedRecursive
                        ERecursive r
                | E.EJoinPoint(_,a,b,d,_) -> EJoinPoint(term a,Option.map ty b,Option.map snd d)
                | E.EJoinPoint'(_,a,b,c,d,_) -> EJoinPoint'(a,term b,Option.map ty c,Option.map snd d)
                | E.EFun(_,a,b,c) -> EFun(a,term b,Option.map ty c)
                | E.EForall(_,a,b) -> EForall(a,term b)
                | E.EB _ -> EB
                | E.EV i -> EV i
                | E.ELit(_,a) -> ELit(a)
                | E.EDefaultLit(_,a,b) -> EDefaultLit(a,ty b)
                | E.ESymbol(_,a) -> ESymbol a
                | E.EType(_,a) -> EType(ty a)
                | E.EApply(_,a,b) -> EApply(term a,term b)
                | E.ETypeApply(_,a,b) -> ETypeApply(term a,ty b)
                | E.ERecBlock(_,a,b) -> ERecBlock(List.map (fun (a,b) -> a, term b) a,term b)
                | E.ERecordWith(_,a,b,c) ->
                    let a = a |> List.map (fun (_,a) -> term a)
                    let b = b |> List.map (function
                        | RecordWith.RSymbol((_,a),b) -> RSymbol(a,term b)
                        | RecordWith.RSymbolModify((_,a),b) -> RSymbolModify(a,term b)
                        | RecordWith.RVar((_,a),b) -> RVar(term a,term b)
                        | RecordWith.RVarModify((_,a),b) -> RVarModify(term a,term b)
                        )
                    let c = c |> List.map (function
                        | RecordWithout.WSymbol(_,a) -> WSymbol a
                        | RecordWithout.WVar(_,a) -> WVar(term a)
                        )
                    ERecordWith(a,b,c)
                | E.EModule a -> EModule(Map.map (fun _ -> term) a)
                | E.EOp(_,a,b) -> EOp(a,List.map term b)
                | E.EPatternMiss a -> EPatternMiss(term a)
                | E.ETypePatternMiss a -> ETypePatternMiss(ty a)
                | E.EAnnot(_,a,b) -> EAnnot(term a,ty b)
                | E.EIfThenElse(_,a,b,c) -> EIfThenElse(term a,term b,term c)
                | E.EIfThen(_,a,b) -> EIfThen(term a,term b)
                | E.EPair(_,a,b) -> EPair(term a,term b)
                | E.ESeq(_,a,b) -> ESeq(term a,term b)
                | E.EMutableSet(_,a,b,c) -> EHeapMutableSet(term a,List.map (snd >> term) b,term c)
                | E.EReal(_, a) -> EReal(term a)
                | E.EExists(_, a, b) -> EExists(List.map ty a, term b)
                | E.EMacro(_,a,b) ->
                    let a = a |> List.map (function
                        | Macro.MText a -> MText a
                        | Macro.MTerm (a,b) -> MTerm(term a,b)
                        | Macro.MType a -> MType(ty a)
                        | Macro.MLitType a -> MLitType(ty a)
                        )
                    EMacro(a,ty b)
                | E.EPrototypeApply(_,a,b) -> EPrototypeApply(a,ty b)
                | E.EPatternMemo a -> EPatternMemo(term a)
                | E.ENominal(_,a,b) -> ENominal(term a,ty b)
                // Regular pattern matching
                | E.ELet(_,a,b,c) -> ELet(a,term b,term c)
                | E.EUnbox(_,q,a,b,c,d) -> EUnbox(a,q,term b,term c,term d)
                | E.EExistsTest(_,a,l,q,d,e) -> EExistsTest(a,l,q,term d,term e)
                | E.EPairTest(_,a,b,c,d,e) -> EPairTest(a,b,c,term d,term e)
                | E.ESymbolTest(_,a,b,c,d) -> ESymbolTest(a,b,term c,term d)
                | E.ERecordTest(_,a,b,c,d) ->
                    let a = a |> List.map (function
                        | PatRecordMemberPrepass.Symbol((_,a),b) -> Symbol(a,b)
                        | PatRecordMemberPrepass.Var((_,a),b) -> Var(term a,b)
                        )
                    ERecordTest(a,b,term c,term d)
                | E.EAnnotTest(_,a,b,c,d) -> EAnnotTest(ty a,b,term c,term d)
                | E.EUnitTest(_,a,b,c) -> EUnitTest(a,term b,term c)
                | E.ENominalTest(_,a,b,c,d,e) -> ENominalTest(ty a,b,c,term d,term e)
                | E.ELitTest(_,a,b,c,d) -> ELitTest(a,b,term c,term d)
                | E.EDefaultLitTest(_,a,b,c,d,e) -> EDefaultLitTest(a,ty b,c,term d,term e)
            and ty = function
                | TPrepass.TTypecase(_,a,b) -> TTypecase(ty a,List.map (fun (a,b) -> ty a, ty b) b)
                | TPrepass.TPatternRef a ->
                    match pat_ref_ty.TryGetValue a with
                    | true, v -> v
                    | false, _ ->
                        pat_ref_ty.Add(a, TB)
                        let r = a.Value
                        let v = if isNull (box r) then TB else ty r
                        pat_ref_ty.[a] <- v
                        v
                | TPrepass.TForall'(_,a,b,c) -> TForall'(a,b,ty c)
                | TPrepass.TForall(_,a,b) -> TForall(a,ty b)
                | TPrepass.TArrow'(a,b,c) -> TArrow'(a,b,ty c)
                | TPrepass.TArrow(a,b) -> TArrow(a,ty b)
                | TPrepass.TExists -> TExists
                | TPrepass.TJoinPoint'(_,a,b) -> TJoinPoint'(a,ty b)
                | TPrepass.TJoinPoint(_,a) -> TJoinPoint(ty a)
                | TPrepass.TB _ -> TB
                | TPrepass.TLit(_,x) -> TLit x
                | TPrepass.TV a -> TV a
                | TPrepass.TMetaV a -> TMetaV a
                | TPrepass.TPair(_,a,b) -> TPair(ty a,ty b)
                | TPrepass.TFun(a,b,t) -> TFun(ty a,ty b,t)
                | TPrepass.TRecord(_,a) -> TRecord(Map.map (fun _ -> ty) a)
                | TPrepass.TModule a -> TModule(Map.map (fun _ -> ty) a)
                | TPrepass.TUnion(_,(a,b)) -> TUnion(Map.map (fun _ x -> ty (fst x)) a,b)
                | TPrepass.TSymbol(_,a) -> TSymbol a
                | TPrepass.TApply(_,a,b) -> TApply(ty a, ty b)
                | TPrepass.TPrim a -> TPrim a
                | TPrepass.TTerm(_,a) -> TTerm(term a)
                | TPrepass.TMacro(_,a) ->
                    let a = a |> List.map (function
                        | TypeMacro.TMText a -> TMText a
                        | TypeMacro.TMType a -> TMType(ty a)
                        | TypeMacro.TMLitType a -> TMLitType(ty a)
                        )
                    TMacro(a)
                | TPrepass.TNominal a -> TNominal a
                | TPrepass.TArray a -> TArray(ty a)
                | TPrepass.TLayout(a,b) -> TLayout(ty a,b)
    

            match x with
            | Choice1Of2(x,ret) -> ret (term x)
            | Choice2Of2(x,ret) -> ret (ty x)
    

    /// ### PrepassTopEnv
    type PrepassTopEnv = {
        prototypes_next_tag : int
        prototypes_instances : Map<GlobalId * GlobalId,E>
        nominals_next_tag : int
        nominals : Map<GlobalId,{|body : TPrepass; name : string|}>
        term : Map<string,E>
        ty : Map<string,TPrepass>
        }
    

    /// ### prepassTop_env_empty
    let prepassTop_env_empty = {
        prototypes_next_tag = 0
        prototypes_instances = Map.empty
        nominals_next_tag = 0
        nominals = Map.empty
        term = Map.empty
        ty = Map.empty
        }
    

    /// ### prepassUnion
    let prepassUnion small big = {
        prototypes_next_tag = max small.prototypes_next_tag big.prototypes_next_tag
        prototypes_instances = Map.foldBack Map.add small.prototypes_instances big.prototypes_instances
        nominals_next_tag = max small.nominals_next_tag big.nominals_next_tag
        nominals = Map.foldBack Map.add small.nominals big.nominals
        term =
            Map.foldBack (fun k v s ->
                let v =
                    match v, s |> Map.tryFind k with
                    | EModule x, Some (EModule x') -> Map.foldBack Map.add x x' |> EModule
                    | _ -> v
                s |> Map.add k v
            ) small.term big.term
        ty =
            Map.foldBack (fun k v s ->
                let v =
                    match v, s |> Map.tryFind k with
                    | TModule x, Some (TModule x') -> Map.foldBack Map.add x x' |> TModule
                    | _ -> v
                s |> Map.add k v
            ) small.ty big.ty
        }
    

    /// ### in_modulePrepass
    let in_modulePrepass m (a : PrepassTopEnv) =
        {a with
            ty = Map.add m (TModule a.ty) Map.empty
            term = Map.add m (EModule a.term) Map.empty
            }
    

    /// ### PropagatedVarsEnv
    type PropagatedVarsEnv = {|vars : Set<int>; range : (int * int) option|}
    

    /// ### PropagatedVars
    type PropagatedVars = {term : PropagatedVarsEnv; ty : PropagatedVarsEnv}
    

    /// ### propagate
    // Attaches scopes to all the nodes.
    let propagate x =
        let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference)
        let pat_ref_dict = Dictionary(HashIdentity.Reference)
        let (+*) a b =
            match a,b with
            | Some(min',max'), Some(min'',max'') -> Some(min min' min'', max max' max'')
            | Some(a,b), _ | _, Some(a,b) -> Some(a,b)
            | None, None -> None
        let (+) (a : PropagatedVars) (b : PropagatedVars) : PropagatedVars = {
            term = {|vars = Set.union a.term.vars b.term.vars; range = a.term.range +* b.term.range |}
            ty = {|vars = Set.union a.ty.vars b.ty.vars; range = a.ty.range +* b.ty.range |}
            }
        let (-*) a i =
            if 0 <= i then
                match a with
                | Some(min',max') -> Some(min min' i, max max' i)
                | None -> Some(i,i)
            else a // Recursive vars are negative and get inlined so they should be ignored when calculating the range of a scope.
        let (-) (a : PropagatedVars) i = {a with term = {|vars = Set.remove i a.term.vars; range = a.term.range -* i |} }
        let (-.) (a : PropagatedVars) i = {a with ty = {|vars = Set.remove i a.ty.vars; range = a.ty.range -* i |} }
        let empty' term ty = let f x = {|vars = x; range=None|} in {term = f term; ty = f ty}
        let empty = empty' Set.empty Set.empty
        let singleton_term i = empty' (Set.singleton i) Set.empty
        let singleton_ty i = empty' Set.empty (Set.singleton i)
    

        let scope_dict = Dictionary<obj,_>(HashIdentity.Reference)
        let scope x (v : PropagatedVars) = scope_dict.Add(x,v); empty' v.term.vars v.ty.vars
        let rec term x =
            match x with
            | EFun' _ | EForall' _ | ERecursiveFun' _ | ERecursiveForall' _ | ERecursive _ | EJoinPoint' _ | EModule _ | ESymbol _ | ELit _ | EB _ -> empty
            | EPatternRef a ->
                match pat_ref_dict.TryGetValue a with
                | true, v -> v
                | false, _ ->
                    pat_ref_dict.Add(a, empty)
                    let v = term a.Value
                    pat_ref_dict.[a] <- v
                    v
            | EV i -> singleton_term i
            | EPrototypeApply(_,_,a) | EType(_,a) | ETypePatternMiss a | EDefaultLit(_,_,a) -> ty a
            | ESeq(_,a,b) | EPair(_,a,b) | EIfThen(_,a,b) | EApply(_,a,b) -> term a + term b
            | EArray(_,a,b) -> List.fold (fun s x -> s + term x) (ty b) a
            | ENominal(_,a,b) | EAnnot(_,a,b) | ETypeApply(_,a,b) -> term a + ty b
            | EForall(_,i,a) -> scope x (term a -. i)
            | EJoinPoint(_,a,t,_,_) -> scope x (match t with Some t -> term a + ty t | None -> term a)
            | EFun(_,i,a,t) -> scope x (match t with Some t -> term a - i + ty t | None -> term a - i)
            | ERecBlock(_,l,on_succ) ->
                let s = List.fold (fun s (_,body) -> s + term body) (term on_succ) l
                List.fold (fun s (id,_) -> s - id) s l
            | ERecordWith(_,a,b,c) ->
                let fold f a b = List.fold f b a
                List.fold (fun s (_,a) -> s + term a) empty a
                |> fold (fun s -> function
                        | RSymbolModify(_,a) | RSymbol(_,a) -> s + term a
                        | RVar((_,a),b) | RVarModify((_,a),b) -> s + term a + term b
                        ) b
                |> fold (fun s -> function
                    | WSymbol _ -> s
                    | WVar(_,a) -> s + term a
                    ) c
            | EOp(_,_,a) -> List.fold (fun s a -> s + term a) empty a
            | EMutableSet(_,a,b,c) -> term a + List.fold (fun s (_,a) -> s + term a) empty b + term c
            | EIfThenElse(_,a,b,c) -> term a + term b + term c
            | EExists(_,a,b) -> List.fold (fun s a -> s + ty a) (term b) a
            | EPatternMiss a | EReal(_,a) -> term a
            | EMacro(_,a,b) -> List.fold (fun s -> function MLitType x | MType x -> s + ty x | MTerm (x,_) -> s + term x | MText _ -> s) (ty b) a
            | EPatternMemo a -> Utils.memoize dict term a
            // Regular pattern matching
            | ELet(_,bind,body,on_succ) -> term on_succ - bind + term body
            | EUnbox(_,_,bind,body,on_succ,on_fail) -> term on_succ - bind + term body + term on_fail
            | EExistsTest(_,bind,pat_type,pat,on_succ,on_fail) -> singleton_term bind + (Array.fold (-.) (term on_succ) pat_type - pat) + term on_fail
            | EPairTest(_,bind,pat1,pat2,on_succ,on_fail) -> singleton_term bind + (term on_succ - pat1 - pat2) + term on_fail
            | ESymbolTest(_,_,bind,on_succ,on_fail)
            | EUnitTest(_,bind,on_succ,on_fail)
            | ELitTest(_,_,bind,on_succ,on_fail) -> singleton_term bind + term on_succ + term on_fail
            | ERecordTest(_,a,bind,on_succ,on_fail) ->
                let on_succ_and_injects =
                    let on_succ = List.fold (fun s (Symbol(_,a) | Var(_,a)) -> s - a) (term on_succ) a
                    List.fold (fun s -> function Var((_,a),_) -> s + term a | Symbol _ -> s) on_succ a // Though it is less efficient, I am using two passes here to guard against future changes to pattern compilation breaking this part by accident.
                singleton_term bind + term on_fail + on_succ_and_injects
            | EDefaultLitTest(_,_,t,bind,on_succ,on_fail)
            | EAnnotTest(_,t,bind,on_succ,on_fail) -> singleton_term bind + ty t + term on_succ + term on_fail
            | ENominalTest(_,t,bind,pat,on_succ,on_fail) -> singleton_term bind + ty t + (term on_succ - pat) + term on_fail
            | ETypecase(_,a,b) ->
                List.fold (fun s (a,b) ->
                    let a = ty a
                    let mutable b = term b
                    match a.ty.range with
                    | Some(a,a') -> for i=a to a' do b <- b -. i
                    | None -> ()
                    s + a + b
                    ) (ty a) b
        and ty = function
            | TExists | TJoinPoint' _ | TForall' _ | TArrow' _ | TSymbol _ | TPrim _ | TNominal _ | TLit _ | TB _ -> empty
            | TTypecase(_,a,b) ->
                List.fold (fun s (a,b) ->
                    let a = ty a
                    let mutable b = ty b
                    match a.ty.range with
                    | Some(a,a') -> for i=a to a' do b <- b -. i
                    | None -> ()
                    s + a + b
                    ) (ty a) b
            | TPatternRef a -> ty a.Value
            | TV i -> singleton_ty i
            | TMetaV i -> {empty with ty = {|empty.ty with range = Some(i,i)|} }
            | TApply(_,a,b) | TPair(_,a,b) | TFun(a,b,_) -> ty a + ty b
            | TUnion(_,(a,_)) -> a |> Map.fold (fun s k (a,b) -> s + ty a + (Option.map ty b |> Option.defaultValue empty)) empty
            | TRecord(_,a) -> Map.fold (fun s k v -> s + ty v) empty a
            | TModule a -> Map.fold (fun s k v -> s + ty v) empty a
            | TTerm(_,a) -> term a
            | TMacro(_,a) -> a |> List.fold (fun s -> function TMText _ -> s | TMLitType x | TMType x -> s + ty x) empty
            | TForall(_,i,a) | TArrow(i,a) as x -> scope x (ty a -. i)
            | TJoinPoint(_,a) as x -> scope x (ty a)
            | TArray(a) | TLayout(a,_) -> ty a
    

        let _ = match x with Choice1Of2 x -> term x | Choice2Of2 x -> ty x
        scope_dict
    

    /// ### ResolveEnvValue
    type ResolveEnvValue = {|term : Set<Id>; ty : Set<Id> |}
    

    /// ### ResolveEnv
    type ResolveEnv = Map<int, ResolveEnvValue>
    

    /// ### resolve_recursive_free_vars
    let resolve_recursive_free_vars env =
        Map.fold (fun (env : ResolveEnv) k v ->
            let has_visited = HashSet()
            let rec f (s : ResolveEnvValue) k v =
                if has_visited.Add(k) then
                    let s = Set.fold (fun s k -> if k < 0 then f s k env.[k] else {|s with term = Set.add k s.term|}) s v.term
                    Set.fold (fun s k -> {|s with ty = Set.add k s.ty|}) s v.ty
                else s
            Map.add k (f {|term=Set.empty; ty=Set.empty|} k v) env
            ) env env
    

    /// ### resolve
    let resolve (scope : Dictionary<obj,PropagatedVars>) x =
        let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference)
        let pat_ref_term = HashSet(HashIdentity.Reference)
        let pat_ref_ty = HashSet(HashIdentity.Reference)
        let subst' (env : ResolveEnv) (x : PropagatedVars) : PropagatedVars =
            let f (s : ResolveEnvValue) x =
                if x < 0 then
                    match Map.tryFind x env with
                    | Some x -> {|term=Set.union s.term x.term; ty=Set.union s.ty x.ty|}
                    | None -> {|s with term=Set.add x s.term|}
                else {|s with term=Set.add x s.term|}
            let fv = Set.fold f {|term=Set.empty; ty=Set.empty|} x.term.vars
            {term = {|x.term with vars = fv.term|}; ty = {|x.ty with vars = Set.union fv.ty x.ty.vars|} }
        let subst env (x : obj) = match scope.TryGetValue(x) with true, v -> scope.[x] <- subst' env v | _ -> ()
        let rec term (env : ResolveEnv) x =
            let f = term env
            match x with
            | EForall' _ | EFun' _ | ERecursiveForall' _ | ERecursiveFun' _ | ERecursive _ | EJoinPoint' _ | EModule _ | EV _ | ESymbol _ | ELit _ | EB _ -> ()
            | EPatternRef a -> if pat_ref_term.Add(a) then f a.Value else ()
            | EDefaultLit(_,_,a) | EPrototypeApply(_,_,a) | EType(_,a) | ETypePatternMiss a -> ty env a
            | EJoinPoint(_,a,b,_,_) | EFun(_,_,a,b) -> subst env x; f a; Option.iter (ty env) b
            | EForall(_,_,a) -> subst env x; f a
            | ERecBlock(r,a,b) ->
                // Goes over all the functions in a recursive block, resolving them.
                // The reason why this is sound is because the outer blocks are progressively resolved as they go in.
                let env =
                    let l =
                        List.fold (fun s (id,body) ->
                            let x = subst' env scope.[body]
                            Map.add id {|term=x.term.vars; ty=x.ty.vars|} s
                            ) Map.empty a
                        |> resolve_recursive_free_vars
                    Map.foldBack Map.add l env
                a |> List.iter (fun (id,body) ->
                    scope.[body] <-
                        let x = env.[id]
                        let v = scope.[body]
                        {term = {|v.term with vars = x.term |}; ty = {|v.ty with vars=x.ty|} }
                    term env body
                    )
                term env b
            | ERecordWith(_,a,b,c) ->
                List.iter (snd >> f) a
                b |> List.iter (function
                    | RSymbolModify(_,a) | RSymbol(_,a) -> f a
                    | RVarModify((_,a),b) | RVar((_,a),b) -> f a; f b)
                c |> List.iter (function
                    | WSymbol _ -> ()
                    | WVar(_,a) -> f a)
            | ENominal(_,a,b) | ETypeApply(_,a,b) | EAnnot(_,a,b) -> f a; ty env b
            | EOp(_,_,a) -> List.iter f a
            | EExists(_,a,b) -> List.iter (ty env) a; f b
            | EPatternMiss a | EReal(_,a) -> f a
            | EArray(_,a,b) -> List.iter f a; ty env b
            | EExistsTest(_,_,_,_,a,b)
            | EUnitTest(_,_,a,b) | ESymbolTest(_,_,_,a,b) | EPairTest(_,_,_,_,a,b) | ELitTest(_,_,_,a,b)
            | ELet(_,_,a,b) | EIfThen(_,a,b) | EPair(_,a,b) | ESeq(_,a,b) | EApply(_,a,b) -> f a; f b
            | EMutableSet(_,a,b,c) -> f a; List.iter (snd >> f) b; f c
            | EUnbox(_,_,_,a,b,c) | EIfThenElse(_,a,b,c) -> f a; f b; f c
            | EMacro(_,a,b) ->
                a |> List.iter (function MLitType a | MType a -> ty env a | MTerm (a,_) -> f a | MText _ -> ())
                ty env b
            | EPatternMemo a -> Utils.memoize dict f a
            | ERecordTest(_,l,_,a,b) ->
                l |> List.iter (function Symbol _ -> () | Var((_,a),_) -> f a)
                f a; f b
            | EDefaultLitTest(_,_,t,_,a,b) | ENominalTest(_,t,_,_,a,b) | EAnnotTest(_,t,_,a,b) -> ty env t; f a; f b
            | ETypecase(_,a,b) -> ty env a; b |> List.iter (fun (a,b) -> ty env a; term env b)
    

        and ty (env : ResolveEnv) x =
            let f = ty env
            match x with
            | TExists | TJoinPoint' _ | TForall' _ | TArrow' _ | TNominal _ | TPrim _ | TSymbol _ | TV _ | TMetaV _ | TLit _ | TB _ -> ()
            | TTypecase(_,a,b) -> ty env a; b |> List.iter (fun (a,b) -> ty env a; ty env b)
            | TPatternRef a -> if pat_ref_ty.Add(a) then f a.Value else ()
            | TForall(_,_,a)
            | TArrow(_,a) -> subst env x; f a
            | TApply(_,a,b) | TFun(a,b,_) | TPair(_,a,b) -> f a; f b
            | TUnion(_,(a,_)) -> a |> Map.iter (fun _ (a,b) -> f a; Option.iter f b)
            | TRecord(_,a) -> Map.iter (fun _ -> f) a
            | TModule a -> Map.iter (fun _ -> f) a
            | TTerm(_,a) -> term env a
            | TMacro(_,a) -> a |> List.iter (function TMText _ -> () | TMLitType a | TMType a -> f a)
            | TJoinPoint(_,a) | TLayout(a,_) | TArray(a) -> f a
    

        match x with
        | Choice1Of2 x -> term Map.empty x
        | Choice2Of2 x -> ty Map.empty x
    

    /// ### LowerSubEnv
    type LowerSubEnv = {|var : Map<int,int>; adj : int|}
    

    /// ### LowerEnv
    type LowerEnv = {term : LowerSubEnv; ty : LowerSubEnv }
    

    /// ### LowerEnvRec
    type LowerEnvRec = Map<int,LowerEnv -> E>
    

    /// ### lower
    let lower (scope : Dictionary<obj,PropagatedVars>) x =
        let dict = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference)
        let pat_ref_term = Dictionary(HashIdentity.Reference)
        let pat_ref_ty = Dictionary(HashIdentity.Reference)
        let scope (env : LowerEnv) x =
            let v = scope.[x]
            let fv v env = v |> Set.toArray |> HopacExtensions.A.map (fun i -> Map.find i env)
            let sz = function Some(min',max') -> max' - min' + 1 | None -> 0
            let scope : Scope = {
                term = {|free_vars = fv v.term.vars env.term.var; stack_size = sz v.term.range|}
                ty = {|free_vars = fv v.ty.vars env.ty.var; stack_size = sz v.ty.range|}
                }
    

            let vars v = Set.fold (fun (s,i) x -> Map.add x i s,i+1) (Map.empty, 0) v |> fst
            let adj len = function Some(min',_) -> len - min' | None -> 0
            let env : LowerEnv = {
                term = {|var = vars v.term.vars; adj = adj scope.term.free_vars.Length v.term.range|}
                ty = {|var = vars v.ty.vars; adj = adj scope.ty.free_vars.Length v.ty.range|}
                }
    

            scope, env
    

        let adj_term (env : LowerEnv) i =
            let i' = i + env.term.adj
            i', {env with term = {|env.term with var = Map.add i i' env.term.var|}}
        let adj_ty (env : LowerEnv) i =
            let i' = i + env.ty.adj
            i', {env with ty = {|env.ty with var = Map.add i i' env.ty.var|}}
    

        let rec term (env_rec : LowerEnvRec) (env : LowerEnv) x =
            let f = term env_rec env
            let g = ty env_rec
            match x with
            | EForall' _ | EJoinPoint' _ | EFun' _ | ERecursiveForall' _ | ERecursiveFun' _ | ERecursive _ | EModule _ | ESymbol _ | ELit _ | EB _ -> x
            | EPatternRef a ->
                match pat_ref_term.TryGetValue a with
                | true, v -> v
                | false, _ ->
                    pat_ref_term.Add(a, EB Unchecked.defaultof<_>)
                    let v = f a.Value
                    pat_ref_term.[a] <- v
                    v
            | EFun(r,pat,body,t) ->
                let scope, env = scope env x
                let pat, env = adj_term env pat
                assert (scope.term.free_vars.Length = pat)
                EFun'(r,scope,pat,term env_rec env body,Option.map (g env) t)
            | EForall(r,pat,body) ->
                let scope, env = scope env x
                let pat, env = adj_ty env pat
                assert (scope.ty.free_vars.Length = pat)
                EForall'(r,scope,pat,term env_rec env body)
            | EJoinPoint(r,body,t,q,name) ->
                let scope, env = scope env x
                EJoinPoint'(r,scope,term env_rec env body,Option.map (g env) t,q,name)
            | EV i when 0 <= i -> EV env.term.var.[i]
            | EV i -> env_rec.[i] env
            | EDefaultLit(r,a,b) -> EDefaultLit(r,a,g env b)
            | EType(r,a) -> EType(r,g env a)
            | ETypePatternMiss a -> ETypePatternMiss(g env a)
            | EApply(r,a,b) -> EApply(r,f a,f b)
            | ETypeApply(r,a,b) -> ETypeApply(r,f a,g env b)
            | ENominal(r,a,b) -> ENominal(r,f a,g env b)
            | ERecBlock(r,a,b) ->
                let l,env_rec =
                    List.mapFold (fun (env_rec : LowerEnvRec) (i,body) ->
                        let re = ref Unchecked.defaultof<_>
                        let eval env_rec =
                            let _,env = scope env body
                            re.Value <-
                                match body with
                                | EFun(_,i,body,_) ->
                                    let _,env = adj_term env i
                                    term env_rec env body
                                | EForall(_,i,body) ->
                                    let _,env = adj_ty env i
                                    term env_rec env body
                                | _ -> failwith "Compiler error: Expected a fun or a forall."
                        let body env =
                            let scope,env = scope env body
                            match body with
                            | EFun(r,i,_,d) ->
                                let i,_ = adj_term env i
                                ERecursiveFun'(r,scope,i,re,d)
                            | EForall(r,i,_) ->
                                let i,_ = adj_ty env i
                                ERecursiveForall'(r,scope,i,re)
                            | _ -> failwith "Compiler error: Expected a fun or a forall."
                        eval,Map.add i body env_rec
                        ) env_rec a
                List.iter (fun eval -> eval env_rec) l
                term env_rec env b
            | ERecordWith(r,a,b,c) ->
                let a = List.map (fun (r,a) -> r, f a) a
                let b = b |> List.map (function
                    | RSymbol(a,b) -> RSymbol(a,f b)
                    | RSymbolModify(a,b) -> RSymbolModify(a,f b)
                    | RVar((r,a),b) -> RVar((r,f a),f b)
                    | RVarModify((r,a),b) -> RVarModify((r,f a),f b)
                    )
                let c = c |> List.map (function
                    | WSymbol _ as x -> x
                    | WVar(r,a) -> WVar(r,f a)
                    )
                ERecordWith(r,a,b,c)
            | EOp(r,a,b) -> EOp(r,a,List.map f b)
            | EAnnot(r,a,b) -> EAnnot(r,f a,g env b)
            | EIfThenElse(r,a,b,c) -> EIfThenElse(r,f a,f b,f c)
            | EIfThen(r,a,b) -> EIfThen(r,f a,f b)
            | EArray(r,a,b) -> EArray(r,List.map f a, g env b)
            | EPair(r,a,b) -> EPair(r,f a,f b)
            | ESeq(r,a,b) -> ESeq(r,f a,f b)
            | EMutableSet(r,a,b,c) -> EMutableSet(r,f a,List.map (fun (a,b) -> a, f b) b,f c)
            | EPatternMiss a -> EPatternMiss(f a)
            | EReal(r,a) -> EReal(r,f a)
            | EExists(r,a,b) -> EExists(r,List.map (g env) a,f b)
            | EMacro(r,a,b) ->
                let a = a |> List.map (function
                    | MText _ as x -> x
                    | MLitType a -> MLitType(g env a)
                    | MType a -> MType(g env a)
                    | MTerm (a,b) -> MTerm(f a,b)
                    )
                EMacro(r,a,g env b)
            | EPrototypeApply(r,a,b) -> EPrototypeApply(r,a,g env b)
            | EPatternMemo x -> Utils.memoize dict f x
            // Regular pattern matching
            | ELet(r,pat,body,on_succ) ->
                let body = term env_rec env body
                let pat,env = adj_term env pat
                let on_succ = term env_rec env on_succ
                ELet(r,pat,body,on_succ)
            | EUnbox(r,q,pat,body,on_succ,on_fail) ->
                let body = term env_rec env body
                let on_fail = term env_rec env on_fail
                let pat,env = adj_term env pat
                let on_succ = term env_rec env on_succ
                EUnbox(r,q,pat,body,on_succ,on_fail)
            | EPairTest(r,i,pat1,pat2,on_succ,on_fail) ->
                let on_fail = term env_rec env on_fail
                let i = env.term.var.[i]
                let pat1,env = adj_term env pat1
                let pat2,env = adj_term env pat2
                let on_succ = term env_rec env on_succ
                EPairTest(r,i,pat1,pat2,on_succ,on_fail)
            | EExistsTest(r,i,pat_type,pat,on_succ,on_fail) ->
                let on_fail = term env_rec env on_fail
                let i = env.term.var.[i]
                let pat,env = adj_term env pat
                let pat_type,env = Array.mapFold adj_ty env pat_type
                let on_succ = term env_rec env on_succ
                EExistsTest(r,i,pat_type,pat,on_succ,on_fail)
            | ESymbolTest(r,a,i,on_succ,on_fail) ->
                let on_fail = term env_rec env on_fail
                let i = env.term.var.[i]
                let on_succ = term env_rec env on_succ
                ESymbolTest(r,a,i,on_succ,on_fail)
            | ERecordTest(r,a,i,on_succ,on_fail) ->
                let on_fail = term env_rec env on_fail
                let b = env.term.var.[i]
                let a, env =
                    List.mapFold (fun env x ->
                        match x with
                        | Symbol(a,b) -> let b,env = adj_term env b in Symbol(a,b), env
                        | Var((r,a),b) -> let b,env = adj_term env b in Var((r,f a),b), env
                        ) env a
                ERecordTest(r,a,b,term env_rec env on_succ,on_fail)
            | EAnnotTest(r,a,i,on_succ,on_fail) -> EAnnotTest(r,g env a,env.term.var.[i],f on_succ,f on_fail)
            | ELitTest(r,a,i,on_succ,on_fail) -> ELitTest(r,a,env.term.var.[i],f on_succ,f on_fail)
            | EUnitTest(r,i,on_succ,on_fail) -> EUnitTest(r,env.term.var.[i],f on_succ,f on_fail)
            | ENominalTest(r,a,i,pat,on_succ,on_fail) ->
                let on_fail = term env_rec env on_fail
                let i = env.term.var.[i]
                let pat, env = adj_term env pat
                let on_succ = term env_rec env on_succ
                ENominalTest(r,g env a,i,pat,on_succ,on_fail)
            | EDefaultLitTest(r,a,b,i,on_succ,on_fail) -> EDefaultLitTest(r,a,g env b,env.term.var.[i],f on_succ,f on_fail)
            | ETypecase(r,a,b) ->
                let b = b |> List.map (fun (a,b) ->
                    let metavars = System.Collections.Concurrent.ConcurrentDictionary<_,_>()
                    let mutable env_case = env
                    let a =
                        ty' (Utils.memoize metavars (fun i ->
                            let i, env = adj_ty env_case i
                            env_case <- env
                            TMetaV i
                            )) env_rec env_case a
                    a, term env_rec env_case b
                    )
                ETypecase(r,g env a,b)
        and ty env_rec env x = ty' (fun _ -> failwith "Compiler error: TMetaV should not appear here.") env_rec env x
        and ty' case_tmetav env_rec env x =
            let f = ty' case_tmetav env_rec env
            match x with
            | TMetaV i -> case_tmetav i
            | TExists | TJoinPoint' _ | TForall' _ | TArrow' _ | TNominal  _ | TPrim _ | TSymbol _ | TLit _ | TB _ as x -> x
            | TTypecase(r,a,b) ->
                let b = b |> List.map (fun (a,b) ->
                    let metavars = System.Collections.Concurrent.ConcurrentDictionary<_,_>()
                    let mutable env_case = env
                    let a =
                        ty' (Utils.memoize metavars (fun i ->
                            let i, env = adj_ty env_case i
                            env_case <- env
                            TMetaV i
                            )) env_rec env_case a
                    a, ty env_rec env_case b
                    )
                TTypecase(r,ty env_rec env a,b)
            | TPatternRef a ->
                match pat_ref_ty.TryGetValue a with
                | true, v -> v
                | false, _ ->
                    pat_ref_ty.Add(a, TB Unchecked.defaultof<_>)
                    let v = f a.Value
                    pat_ref_ty.[a] <- v
                    v
            | TJoinPoint(r,a) as x ->
                let scope, env = scope env x
                TJoinPoint'(r,scope,ty env_rec env a)
            | TForall(r,a,b) as x ->
                let scope, env = scope env x
                let a, env = adj_ty env a
                TForall'(r,scope,a,ty env_rec env b)
            | TArrow(a,b) as x ->
                let scope, env = scope env x
                let a, env = adj_ty env a
                TArrow'(scope,a,ty env_rec env b)
            | TV i -> TV(env.ty.var.[i])
            | TPair(r,a,b) -> TPair(r,f a,f b)
            | TFun(a,b,t) -> TFun(f a,f b,t)
            | TRecord(r,a) -> TRecord(r,Map.map (fun _ -> f) a)
            | TModule a -> TModule(Map.map (fun _ -> f) a)
            | TUnion(r,(a,b)) -> TUnion(r,(Map.map (fun _ (a,b) -> f a, Option.map f b) a,b))
            | TApply(r,a,b) -> TApply(r,f a,f b)
            | TTerm(r,a) -> TTerm(r,term env_rec env a)
            | TMacro(r,a) ->
                let a = a |> List.map (function
                    | TMText _ as x -> x
                    | TMType a -> TMType(f a)
                    | TMLitType a -> TMLitType(f a)
                    )
                TMacro(r,a)
            | TArray(a) -> TArray(f a)
            | TLayout(a,b) -> TLayout(f a,b)
        let env : LowerEnv = {
            term = {|var = Map.empty; adj = 0|}
            ty = {|var = Map.empty; adj = 0|}
            }
        match x with
        | Choice1Of2(x,ret) -> ret (term Map.empty env x)
        | Choice2Of2(x,ret) -> ret (ty Map.empty env x)
    

    /// ### PartEvalPrepassEnv
    type PartEvalPrepassEnv = {
        term : {| env : Map<string,E>; i : Id; i_rec : Id |}
        ty : {| env : Map<string,TPrepass>; i : Id |}
        }
    

    /// ### add_term
    let add_term (e : PartEvalPrepassEnv) k v = let term = e.term in {e with term = {|term with i = term.i+1; env = Map.add k v term.env|} }
    

    /// ### add_term_rec
    let add_term_rec (e : PartEvalPrepassEnv) k v = let term = e.term in {e with term = {|term with i_rec = term.i_rec-1; env = Map.add k v term.env|} }
    

    /// ### add_ty
    let add_ty (e : PartEvalPrepassEnv) k v = let ty = e.ty in {e with ty = {|ty with i = ty.i+1; env = Map.add k v ty.env|} }
    

    /// ### add_wildcard
    let add_wildcard (e : PartEvalPrepassEnv) = let ty = e.ty in {e with ty = {|ty with i = ty.i+1|} }
    

    /// ### add_term_var
    let add_term_var (e : PartEvalPrepassEnv) k = e.term.i, add_term e k (EV e.term.i)
    

    /// ### fresh_term_var
    let fresh_term_var (e : PartEvalPrepassEnv) = e.term.i, (let term = e.term in {e with term = {|term with i = term.i+1|} })
    

    /// ### fresh_ty_var
    let fresh_ty_var (e : PartEvalPrepassEnv) = e.ty.i, (let ty = e.ty in {e with ty = {|ty with i = ty.i+1|} })
    

    /// ### add_term_rec_var
    let add_term_rec_var (e : PartEvalPrepassEnv) k = e.term.i_rec, add_term_rec e k (EV e.term.i_rec)
    

    /// ### add_ty_var
    let add_ty_var (e : PartEvalPrepassEnv) k = e.ty.i, add_ty e k (TV e.ty.i)
    

    /// ### add_ty_wildcard
    let add_ty_wildcard (e : PartEvalPrepassEnv) = e.ty.i, add_wildcard e
    

    /// ### process_term
    let process_term (x : E) =
        let scope = propagate (Choice1Of2 x)
        resolve scope (Choice1Of2 x)
        lower scope (Choice1Of2(x,id))
    

    /// ### process_ty
    let process_ty (x : TPrepass) =
        let scope = propagate (Choice2Of2 x)
        resolve scope (Choice2Of2 x)
        lower scope (Choice2Of2(x,id))
    

    /// ### prepassModule_open
    let prepassModule_open (top_env : PrepassTopEnv) env a l =
        let a,b =
            match top_env.term.[snd a], top_env.ty.[snd a] with
            | EModule a, TModule b ->
                List.fold (fun (a,b) (_,x) ->
                    match Map.find x a, Map.find x b with
                    | EModule a, TModule b -> a,b
                    | _ -> failwith "Compiler error: Module open's symbol index should have been validated."
                    ) (a,b) l
            | _ -> failwith "Compiler error: Module open should have been validated."
        {
        term = {|env.term with env = Map.foldBack Map.add a env.term.env|}
        ty = {|env.ty with env = Map.foldBack Map.add b env.ty.env|}
        }
    

    /// ### prepassPrepass
    let prepassPrepass package_id module_id path (top_env : PrepassTopEnv) =
        let p r = {path=path; range=r}
        let at_tag i = { package_id = package_id; module_id = module_id; tag = i }
        let v_term (env : PartEvalPrepassEnv) x = Map.tryFind x env.term.env |> Option.defaultWith (fun () -> top_env.term.[x])
        let v_ty (env : PartEvalPrepassEnv) x = Map.tryFind x env.ty.env |> Option.defaultWith (fun () -> top_env.ty.[x])
    

        // The functions in this block are basically renaming string id to int ids, in addition to pattern compilation.
        let rec compile_pattern (id : Id) (env : PartEvalPrepassEnv) (clauses : (Pattern * RawExpr) list) =
            let mutable term_var_count = env.term.i
            let mutable ty_var_count = env.ty.i
            let patvar () = let x = term_var_count in term_var_count <- term_var_count+1; x
            let ty_patvar () = let x = ty_var_count in ty_var_count <- ty_var_count+1; x
            let loop (pat, on_succ) on_fail =
                let mutable dict = Map.empty
                let mutable dict_type = Map.empty
                let pat_refs_term = ResizeArray()
                //let pat_ref_term x = let re = ref Unchecked.defaultof<_> in pat_refs_term.Add(x,dict,re); EPatternRef re
                let pat_ref_term' x k =
                    let re = ref Unchecked.defaultof<_>
                    let r = k (EPatternRef re)
                    pat_refs_term.Add(x,(dict,dict_type),re)
                    r
                let pat_refs_ty = ResizeArray()
                let pat_ref_ty x = let re = ref Unchecked.defaultof<_> in pat_refs_ty.Add(x,(dict,dict_type),re); TPatternRef re
                let rec cp id pat on_succ on_fail =
                    let v x =
                        match Map.tryFind x dict with
                        | Some x -> x
                        | None -> let v = patvar() in dict <- Map.add x v dict; v
                    let tv x =
                        match Map.tryFind x dict_type with
                        | Some x -> x
                        | None -> let v = ty_patvar() in dict_type <- Map.add x v dict_type; v
                    let step pat on_succ =
                        match pat with
                        | PatVar(_,x) -> v x, on_succ
                        | _ -> let id = patvar() in id, cp id pat on_succ on_fail
                    match pat with
                    | PatDefaultValue _ -> failwith "Compiler error: The default value should be filled."
                    | PatE _ -> on_succ
                    | PatB r -> EUnitTest(p r,id,on_succ,on_fail)
                    | PatVar(r,a) -> ELet(p r,v a,EV id,on_succ)
                    | PatAnnot(r,a,b) -> EAnnotTest(p r,pat_ref_ty b,id,cp id a on_succ on_fail,on_fail)
                    | PatPair(r,a,b) ->
                        // Evaling the b then a causes the call args to be rotated in join points during peval.
                        // This is not a problem, but it might be surprising if you aren't aware why that is happening.
                        // Swapping the next two statements would fix it for pairs.
                        let b,on_succ = step b on_succ
                        let a,on_succ = step a on_succ
                        EPairTest(p r,id,a,b,on_succ,on_fail)
                    | PatExists(r,l,b) ->
                        let pat_type = List.map (snd >> tv) l |> List.toArray
                        let pat,on_succ = step b on_succ
                        EExistsTest(p r,id,pat_type,pat,on_succ,on_fail)
                    | PatArray(r,a) ->
                        let r = p r
                        let ar_ids,on_succ = List.mapFoldBack step a on_succ
                        let a_length = List.length a
                        let on_succ,_ =
                            List.foldBack (fun id' (on_succ,i) ->
                                ELet(r,id',EOp(r,ArrayIndex,[EV id; ELit(r,LitInt32 i)]),on_succ), i-1
                                ) ar_ids (on_succ, a_length - 1)
                        let id_length = EOp(r,ArrayLength,[EType(r,TPrim UInt64T); EV id])
                        let pat_length = ELit(r,LitUInt64(uint64 a_length))
                        EIfThenElse(r,EOp(r,EQ,[id_length;pat_length]),on_succ,on_fail)
                    | PatSymbol(r,a) -> ESymbolTest(p r,a,id,on_succ,on_fail)
                    | PatRecordMembers(r,items) ->
                        let inject_vars = Dictionary(HashIdentity.Reference)
                        List.iter (function
                            | PatRecordMembersSymbol _ -> ()
                            | PatRecordMembersInjectVar((_,var),_) ->
                                match dict.TryGetValue(var) with
                                | true, x -> inject_vars.[var] <- EV x
                                | _ -> inject_vars.[var] <- v_term env var
                            ) items
                        let binds, on_succ =
                            List.mapFoldBack (fun item on_succ ->
                                match item with
                                | PatRecordMembersSymbol((r,keyword),name) -> let arg, on_succ = step name on_succ in Symbol((p r,keyword),arg), on_succ
                                | PatRecordMembersInjectVar((r,var),name) -> let arg, on_succ = step name on_succ in Var((p r,inject_vars.[var]),arg), on_succ
                                ) items on_succ
                        ERecordTest(p r,binds,id,on_succ,on_fail)
                    | PatOr(r,a,b) -> let on_succ = EPatternMemo on_succ in cp id a on_succ (cp id b on_succ on_fail)
                    | PatAnd(r,a,b) -> let on_fail = EPatternMemo on_fail in cp id a (cp id b on_succ on_fail) on_fail
                    | PatValue(r,x) -> ELitTest(p r,x,id,on_succ,on_fail)
                    | PatWhen(r,p',e) -> pat_ref_term' e (fun e -> cp id p' (EIfThenElse(p r, e, on_succ, on_fail)) on_fail)
                    | PatNominal(r,(_,a),l,b) ->
                        let id', on_succ = step b on_succ
                        let a = List.fold (fun s (r',x) -> TApply(p (r +. r'),s,TSymbol(p r',x))) (v_ty env a) l
                        ENominalTest(p r,a,id,id',on_succ,on_fail)
                    | PatFilledDefaultValue(r,a,b) -> EDefaultLitTest(p r,a,pat_ref_ty b,id,on_succ,on_fail)
                    | PatDyn(r,a) -> let id' = patvar() in ELet(p r,id',EOp(p r,Dyn,[EV id]),cp id' a on_succ on_fail)
                    | PatUnbox(r,q,a) -> let id' = patvar() in EUnbox(p r,q,id',EV id,cp id' a on_succ on_fail,on_fail)
                (pat_refs_term, pat_refs_ty), pat_ref_term' on_succ (fun on_succ -> cp id pat on_succ (EPatternMemo on_fail))
    

            let l, e = List.mapFoldBack loop clauses (EPatternMiss(EV id))
            l |> List.iter (fun (terms,tys) -> // The reason I am not evaling it in place is because of the var count which is mutable. I need to deal with the patterns first before replacing the strings in the body.
                let env (dict,dict_type) =
                    {env with
                        term = {|env.term with i=term_var_count; env=dict |> Map.fold (fun s k v -> Map.add k (EV v) s) env.term.env|}
                        ty = {|env.ty with i=ty_var_count; env=dict_type |> Map.fold (fun s k v -> Map.add k (TV v) s) env.ty.env|}
                        }
                terms |> Seq.iter (fun (a,dict,b) -> b.Value <- term (env dict) a)
                tys |> Seq.iter (fun (a,dict,b) -> b.Value <- ty (env dict) a)
                )
            e
        and pattern_match (env : PartEvalPrepassEnv) r body clauses =
            match clauses with
            | [PatVar(_,x), on_succ] ->
                let id,env = add_term_var env x
                ELet(r,id,body,term env on_succ)
            | _ ->
                let id,env = fresh_term_var env
                ELet(r,id,body,compile_pattern id env clauses)
        and pattern_function env r clauses annot =
            match clauses with
            | [PatVar(_,x), on_succ] ->
                let id,env = add_term_var env x
                EFun(r,id,term env on_succ,annot)
            | _ ->
                let id,env = fresh_term_var env
                EFun(r,id,compile_pattern id env clauses,annot)
        and ty env x = ty' (fun _ -> failwith "Compiler error: RawTMetaVar should not appear here.") env x
        and ty' case_metavar (env : PartEvalPrepassEnv) x =
            let f = ty' case_metavar env
            match x with
            | RawTMetaVar(_,name) -> case_metavar (Some name)
            | RawTWildcard _ -> case_metavar None
            | RawTForall(r,a,b) ->
                let id, env = add_ty_var env (typevar_name a)
                TForall(p r,id,ty' case_metavar env b)
            | RawTB r -> TB (p r)
            | RawTLit (r, x) -> TLit(p r,x)
            | RawTVar(r,a) -> v_ty env a
            | RawTPair(r,a,b) -> TPair(p r,f a,f b)
            | RawTFun(r,a,b,t) -> TFun(f a,f b,t)
            | RawTExists(r,l,b) -> TExists
            | RawTRecord(r,l) -> TRecord(p r,Map.map (fun _ -> f) l)
            | RawTUnion(r,a,b,this) ->
                let rec subst_vars_with_metavars vars a =
                    let f = subst_vars_with_metavars vars
                    match a with
                    | RawTTypecase _ | RawTUnion _ -> failwith "Compiler error: Not expecting typecase or union here."
                    | RawTVar(r,n) -> if List.contains n vars then RawTMetaVar(r,n) else a
                    | RawTPrim _ | RawTFilledNominal _ | RawTTerm _ | RawTSymbol _ | RawTLit _ | RawTMetaVar _ | RawTB _ | RawTWildcard _ -> a
                    | RawTPair(r,a,b) -> RawTPair(r,f a,f b)
                    | RawTFun(r,a,b,c) -> RawTFun(r,f a,f b,c)
                    | RawTArray(r,a) -> RawTArray(r,f a)
                    | RawTRecord(r,a) -> RawTRecord(r,Map.map (fun _ -> f) a)
                    | RawTApply(r,a,b) -> RawTApply(r,f a,f b)
                    | RawTForall(r,a,b) -> RawTForall(r,a,subst_vars_with_metavars (List.removeAt (List.findIndex ((=) (typevar_name a)) vars) vars) b)
                    | RawTExists(r,a,b) ->
                        let f vars a = List.removeAt (List.findIndex ((=) (typevar_name a)) vars) vars
                        RawTExists(r,a,subst_vars_with_metavars (List.fold f vars a) b)
                    | RawTMacro(r,a) ->
                        let f = function (RawMacroText _ | RawMacroTerm _ | RawMacroTypeLit _) as a -> a | RawMacroType(r,a) -> RawMacroType(r,f a)
                        RawTMacro(r, List.map f a)
                    | RawTLayout(r,a,b) -> RawTLayout(r,f a,b)
    

                let make_typecase x =
                    let rec loop vars x =
                        match x with
                        | RawTForall(_,a,b) -> loop (typevar_name a :: vars) b
                        | RawTFun(r,a,b,_) -> RawTTypecase(r,this,[subst_vars_with_metavars vars b,a])
                        | b -> let r = range_of_texpr b in RawTTypecase(r,this,[subst_vars_with_metavars vars b,RawTB r])
                    loop [] x |> f
                TUnion(p r,(Map.map (fun _ (is_gadt,x) -> f x, if is_gadt then Some (make_typecase x) else None) a,b))
            | RawTTypecase(r,a,b) ->
                let b = b |> List.map (fun (t,e) ->
                    let metavars = System.Collections.Concurrent.ConcurrentDictionary<_,_>()
                    let mutable env_case = env
                    let t =
                        let f (id,env) = env_case <- env; TMetaV id
                        ty' (function
                            | None -> add_ty_wildcard env_case |> f
                            | Some name -> Utils.memoize metavars (add_ty_var env_case >> f) name
                            ) env t
                    t, ty env_case e
                    )
                TTypecase(p r,ty env a,b)
            | RawTSymbol(r,a) -> TSymbol(p r,a)
            | RawTApply(r,a,b) ->
                match f a, f b with
                | TRecord(_,a') & a, TSymbol(_,b') & b ->
    

                    match a' |> Map.tryPick (fun (_, k) v -> if k = b' then Some v else None) with
                    | Some x -> x
                    | None -> TApply(p r,a,b) // TODO: Will be an error during partial evaluation time. Could be substituted for an exception here, but I do not want to have errors during the prepass.
                | a,b -> TApply(p r,a,b)
            | RawTPrim(r,a) -> TPrim(a)
            | RawTTerm(r,a) -> TTerm(p r,term env a)
            | RawTMacro(r,l) ->
                let f = function
                    | RawMacroText(r,a) -> TMText a
                    | RawMacroType(r,a) -> TMType(f a)
                    | RawMacroTypeLit(r,a) -> TMLitType(f a)
                    | RawMacroTerm _ -> failwith "Compiler error: Term vars should not appear on the type level."
                TMacro(p r,List.map f l)
            | RawTArray(r,a) -> TArray(f a)
            | RawTFilledNominal(r,a) -> TNominal a
            | RawTLayout(r,a,b) -> TLayout(f a,b)
        and term env x =
            let f = term env
            match x with
            | RawDefaultLit(r,a) -> failwith "Compiler error: Default values should have been annotated in `fill` by prepass time."
            | RawAnnot(_,RawDefaultLit(r,a),b) -> EDefaultLit(p r,a,ty env b)
            | RawAnnot(_,RawLit(r,a),b) -> EDefaultLit(p r,a.LitToString(),ty env b)
            | RawB r -> EB(p r)
            | RawV(r,a,_) -> v_term env a
            | RawLit(r,a) -> ELit(p r,a)
            | RawSymbol(r,a) -> ESymbol(p r,a)
            | RawType(r,a) -> EType(p r,ty env a)
            | RawMatch(r,a,b) -> pattern_match env (p r) (f a) b
            | RawFun(r,a) -> pattern_function env (p r) a None
            | RawAnnot(_,RawFun(r,a),t) -> pattern_function env (p r) a (Some (ty env t))
            | RawArray(r,a) -> failwith "Compiler error: The array should have been annotated in `fill` by prepass time."
            | RawAnnot(_,RawArray(r,a),b) -> EArray(p r,List.map f a,ty env b)
            | RawTypecase(r,a,b) ->
                let b = b |> List.map (fun (t,e) ->
                    let metavars = System.Collections.Concurrent.ConcurrentDictionary<_,_>()
                    let mutable env_case = env
                    let t =
                        let f (id,env) = env_case <- env; TMetaV id
                        ty' (function
                            | None -> add_ty_wildcard env_case |> f
                            | Some name -> Utils.memoize metavars (add_ty_var env_case >> f) name
                            ) env t
                    t, term env_case e
                    )
                ETypecase(p r,ty env a,b)
            | RawFilledForall(r,name,b)
            | RawForall(r,((_,(name,_)),_),b) ->
                let id, env = add_ty_var env name
                EForall(p r,id,term env b)
            | RawRecBlock(r,l,on_succ) ->
                let l,env = List.mapFold (fun env ((r,name),body) -> let id,env = add_term_rec_var env name in (id,body), env) env l
                ERecBlock(p r,List.map (fun (id,body) -> id, term env body) l,term env on_succ)
            | RawRecordWith(r,a,b,c) ->
                let a = List.map (fun a -> p (range_of_expr a), f a) a
                let b = b |> List.map (function
                    | RawRecordWithSymbol((r,a),b) -> RSymbol((p r,a),f b)
                    | RawRecordWithSymbolModify((r,a),b) -> RSymbolModify((p r,a),f b)
                    | RawRecordWithInjectVar((r,a),b) -> RVar((p r,v_term env a),f b)
                    | RawRecordWithInjectVarModify((r,a),b) -> RVarModify((p r,v_term env a),f b))
                let c = c |> List.map (function
                    | RawRecordWithoutSymbol(r,a) -> WSymbol(p r,a)
                    | RawRecordWithoutInjectVar(r,a) -> WVar(p r,v_term env a))
                ERecordWith(p r,a,b,c)
            | RawOp(r,a,b) -> EOp(p r,a,List.map f b)
            | RawJoinPoint(r,q,a,name) -> EJoinPoint(p r,f a,None,Option.map (fun (r',w) -> p r',w) q,name)
            | RawAnnot(_,RawJoinPoint(r,q,a,name),b) -> EJoinPoint(p r,f a,Some (ty env b),Option.map (fun (r',w) -> p r',w) q,name)
            | RawOpen (_,a,l,on_succ) -> term (prepassModule_open top_env env a l) on_succ
            | RawApply(r,a,b) ->
                let rec loop = function
                    | EModule a' & a, EPair(_,ESymbol(_, b'),b'') & b ->
                        match Map.tryFind b' a' with
                        | Some a -> loop (a,b'')
                        | None -> EApply(p r,a,b) // TODO: Will be an error during partial evaluation time. Could be substituted for an exception here, but I do not want to have errors during the prepass.
                    | EModule a' & a, ESymbol(_,b') & b ->
                        match Map.tryFind b' a' with
                        | Some a -> a
                        | None -> EApply(p r,a,b) // TODO: Ditto.
                    | a,EType(_,b) -> ETypeApply(p r,a,b)
                    | a,b -> EApply(p r,a,b)
                loop (f a, f b)
            | RawIfThenElse(r,a,b,c) -> EIfThenElse(p r,f a,f b,f c)
            | RawIfThen(r,a,b) -> EIfThen(p r,f a,f b)
            | RawPair(r,a,b) -> EPair(p r,f a,f b)
            | RawSeq(r,a,b) -> ESeq(p r,f a,f b)
            | RawHeapMutableSet(r,a,b,c) -> EMutableSet(p r,f a,List.map (fun a -> p (range_of_expr a), f a) b,f c)
            | RawReal(r,a) -> f a
            | RawExists(r,(_,Some a),b) -> EExists(p r, List.map (ty env) a, f b)
            | RawExists(_,(_,None),_) -> failwith "Compiler error: The exists' vars should have been added during `fill`."
            | RawMacro _ -> failwith "Compiler error: The macro's annotation should have been added during `fill`."
            | RawAnnot(_,RawMacro(r,a),b) ->
                let a = a |> List.map (function
                    | RawMacroText(r,a) -> MText a
                    | RawMacroTerm(r,a,b) -> MTerm(f a,b)
                    | RawMacroType(r,a) -> MType(ty env a)
                    | RawMacroTypeLit(r,a) -> MLitType(ty env a)
                    )
                EMacro(p r,a,ty env b)
            | RawMissingBody _ -> failwith "Compiler error: The missing body cases should have been validated."
            | RawAnnot(r,a,b) -> EAnnot(p r,f a,ty env b)
    

        let env : PartEvalPrepassEnv =
            {
            term = {|env=Map.empty; i=0; i_rec= -1|}
            ty = {|env=Map.empty; i=0|}
            }
    

        let eval_type ((r,(name,kind)) : HoVar) on_succ env =
            let id, env = add_ty_var env name
            TArrow(id,on_succ env)
        let eval_type' env l body = List.foldBack eval_type l body env |> process_ty
    

        {|
        base_type = process_ty
        filled_top = fun x ->
            let nominal_rec l =
                let env,_ =
                    List.fold (fun (env,i) (r,(_,name),l,body) ->
                        add_ty env name (TNominal (at_tag i)), i+1
                        ) (env, top_env.nominals_next_tag) l
                List.fold (fun (term,ty',nominals,i) (r, (_,name),l,body) ->
                    let r = p r
                    let at_tag_i = at_tag i
                    let nom = TNominal at_tag_i
                    let bodyt = eval_type' env l (fun env -> TJoinPoint(p (range_of_texpr body), ty env body))
                    let term =
                        match body with
                        | RawTUnion(_,l,_,_) ->
                            Map.fold (fun term (_,name) (is_gadt,_) ->
                                if is_gadt then
                                    let rec loop_outer = function
                                        | TArrow'(_,_,t) -> loop_outer t // GADTs have the foralls in their cases' type, not here.
                                        | TJoinPoint'(r,_,TUnion(_,(l,_))) ->
                                            let rec loop vars = function
                                                | TForall'(r,scope,id,t) -> EForall(r,id,loop (id :: vars) t)
                                                | TFun(t,t',_) -> EFun(r,0,ENominal(r,EPair(r,ESymbol(r,name),EV 0),t'),Some(TFun(t,t',FT_Vanilla)))
                                                | t' -> ENominal(r,EPair(r,ESymbol(r,name),EB r),t')
                                            let t = l |> Map.pick (fun (_, k) v -> if k = name then Some v else None) |> fst
                                            loop [] t
                                        | _ -> failwith "error[EJPX002]: internal compiler error\n  |\n  = expected: join point with GADT union\n  help: this is a compiler invariant failure; capture the stack trace and the surrounding IR/AST snippet to reproduce.\n"
                                    Map.add name (loop_outer bodyt |> process_term) term
                                else
                                    let rec loop vars = function
                                        | TArrow'(scope,id,t) -> EForall(r,id,loop (id :: vars) t)
                                        | TJoinPoint'(r,_,TUnion(_,(l,_))) ->
                                            let t = l |> Map.pick (fun (_, k) v -> if k = name then Some v else None) |> fst
                                            let t' = List.foldBack (fun id nom -> TApply(r,nom,TV id)) vars nom
                                            match t with
                                            | TB _ -> ENominal(r,EPair(r,ESymbol(r,name),EB r),t')
                                            | _ -> EFun(r,0,ENominal(r,EPair(r,ESymbol(r,name),EV 0),t'),Some(TFun(t,t',FT_Vanilla)))
                                        | _ -> failwith "error[EJPX001]: internal compiler error\n  |\n  = expected: join point with union\n  help: this is a compiler invariant failure; capture the stack trace and the surrounding IR/AST snippet to reproduce.\n"
                                    Map.add name (loop [] bodyt |> process_term) term
                                ) term l
                        | _ ->
                            let rec loop vars = function
                                | TArrow'(scope,id,t) -> EForall(r,id,loop (id :: vars) t)
                                | TJoinPoint'(r,_,t) ->
                                    let t' = List.foldBack (fun id nom -> TApply(r,nom,TV id)) vars nom
                                    match t with
                                    | TB _ -> ENominal(r,EB r,t')
                                    | _ -> EFun(r,0,ENominal(r,EV 0,t'),Some(TFun(t,t',FT_Vanilla)))
                                | _ -> failwith "error[EJPX000]: internal compiler error\n  |\n  = expected: join point\n  help: this is a compiler invariant failure; capture the stack trace and the surrounding IR/AST snippet to reproduce.\n"
                            Map.add name (loop [] bodyt |> process_term) term
                    term,Map.add name nom ty', Map.add at_tag_i {|body=bodyt; name=name|} nominals, i+1
                    ) (Map.empty, Map.empty, Map.empty, top_env.nominals_next_tag) l
            match x with
            | FType(_,(_,name),l,body) -> AInclude {prepassTop_env_empty with ty = Map.add name (eval_type' env l (fun env -> ty env body)) Map.empty}
            | FNominal(r,a,b,c) ->
                let term,ty,nominals,i = nominal_rec [r,a,b,c]
                AInclude {prepassTop_env_empty with term = term; ty = ty; nominals = nominals; nominals_next_tag=i}
            | FNominalRec l ->
                let term,ty,nominals,i = nominal_rec l
                AInclude {prepassTop_env_empty with term = term; ty = ty; nominals = nominals; nominals_next_tag=i}
            | FInl(_,(_,name),body) -> AInclude {prepassTop_env_empty with term = Map.add name (term env body |> process_term) Map.empty}
            | FRecInl l ->
                let l, env =
                    List.mapFold (fun env (_,(_,name),_ as x) ->
                        let r = ref Unchecked.defaultof<_>
                        (x,r), add_term_rec env name (ERecursive r)
                        ) env l
                let term =
                    List.fold (fun top_env_term ((_,(_,name),body),(r : ref<E>)) ->
                        r.Value <- term env body |> process_term
                        Map.add name r.Value top_env_term
                        ) Map.empty l
                AInclude {prepassTop_env_empty with term = term}
            | FPrototype(r,(_,name),_,_,_) ->
                let i = at_tag top_env.prototypes_next_tag
                let r = p r
                let x = EForall(r,0,EPrototypeApply(r,i,TV 0)) |> process_term
                AInclude {prepassTop_env_empty with term = Map.add name x Map.empty; prototypes_next_tag = i.tag+1}
            | FInstance(_,(_,prot_id),(_,ins_id),body) ->
                AInclude {prepassTop_env_empty with prototypes_instances = Map.add (prot_id,ins_id) (term env body |> process_term) Map.empty}
            | FOpen(r,a,b) ->
                let x = prepassModule_open top_env env a b
                AOpen {prepassTop_env_empty with term=x.term.env; ty=x.ty.env}
            | FError _ -> AInclude prepassTop_env_empty
        |}
    

    /// ### prepassTop_env_default
    let prepassTop_env_default default_env =
        let convert_infer_to_prepass x =
            let m = System.Collections.Concurrent.ConcurrentDictionary<_,_>(HashIdentity.Reference)
            let rec f = function
                | TyVar (_,{contents=Some x}) -> f x
                | TyVar (x,_) -> TV m.[x.name]
                | TyPrim x -> TPrim x
                | TyArray x -> TArray (f x)
                | TyLayout(a,b) -> TLayout(f a,b)
                | TyInl(a,b) -> let i = m.Count in m.TryAdd(a.name,i) |> ignore; TArrow(i,f b)
                | TyFun(a,b,t) -> TFun(f a, f b, t)
                | _ -> failwith "Compiler error: The base type in Infer is not supported in the prepass yet."
            f x
    

        List.fold (fun (top_env : PrepassTopEnv) (k, x) ->
            {top_env with ty = Map.add k ((prepassPrepass -1 0 "<base_types>" top_env).base_type (convert_infer_to_prepass x)) top_env.ty}
            ) prepassTop_env_empty (Infer.base_types default_env)
    

    /// ## PartEval
    // #r @"../../../../../../../.nuget/packages/softcircuits.ordereddictionary/3.2.0/lib/net8.0/SoftCircuits.OrderedDictionary.dll"
    

    // open System
    open System.Collections.Generic
    // open SoftCircuits.Collections
    // open Common
    

    /// ### Tag
    type Tag = int
    

    /// ### L<'a,'b when 'a: equality and 'a: comparison>
    type [<CustomComparison;CustomEquality>] L<'a,'b when 'a: equality and 'a: comparison> =
        | L of 'a * 'b
    

        override a.Equals(b) =
            match b with
            | :? L<'a,'b> as b -> match a,b with L(a,_), L(b,_) -> a = b
            | _ -> false
        override a.GetHashCode() = match a with L(a,_) -> hash a
        interface IComparable with
            member a.CompareTo(b) =
                match b with
                | :? L<'a,'b> as b -> match a,b with L(a,_), L(b,_) -> compare a b
                | _ -> raise <| ArgumentException "Invalid comparison for T."
    

    /// ### H<'a when 'a : equality>
    type H<'a when 'a : equality>(x : 'a) =
        let h = hash x
    

        member _.Item = x
        override _.Equals(b) =
            match b with
            | :? H<'a> as b -> Object.ReferenceEquals(x,b.Item)
            | _ -> false
        override _.GetHashCode() = h
    

    /// ### StackSize
    type StackSize = int
    

    /// ### Nominal
    type Nominal = {|body : TPrepass; id : GlobalId; name : string|} ConsedNode // TODO: When the time comes to implement incremental compilation, make the `body` field a weak reference.
    

    /// ### PartEvalMacro
    type PartEvalMacro = Text of string | Type of Ty | TypeLit of Ty
    and Ty =
        | YVoid
        | YB
        | YLit of Literal
        | YSymbol of string
        | YPair of Ty * Ty
        | YTypeFunction of body : TPrepass * ty : Ty [] * term_stack_size : StackSize * ty_stack_size : StackSize
        | YExists
        | YForall
        | YRecord of Map<int * string, Ty>
        | YPrim of PrimitiveType
        | YArray of Ty
        | YFun of Ty * Ty * FunType
        | YMacro of PartEvalMacro list
        | YNominal of Nominal
        | YApply of Ty * Ty
        | YLayout of Ty * Layout
        | YUnion of Union
        | YMetavar of Id
    and Data =
        | DB
        | DSymbol of string
        | DTLit of Literal
        | DPair of Data * Data
        | DFunction of body : E * annot : TPrepass option * term : Data [] * ty : Ty [] * term_stack_size : StackSize * ty_stack_size : StackSize
        | DForall of body : E * term : Data [] * ty : Ty [] * term_stack_size : StackSize * ty_stack_size : StackSize
        | DExists of vars_type : Ty [] * term : Data
        | DRecord of Map<int * string, Data>
        | DLit of Literal
        | DUnion of Data * Union
        | DNominal of Data * Ty
        | DV of TyV
        | DHashSet of HashSet<Data>
        | DHashMap of OrderedDictionary<Data,Data> * bool ref
    and TyV = L<Tag,Ty>
    // Unions always go through a join point which enables them to be compared via ref eqaulity.
    // tags and tag_cases are straightforward mapping from cases for the sake of efficiency.
    and Union = {|cases : Map<int * string, Ty>; layout : UnionLayout; tags : Dictionary<string, int>; tag_cases : (string * Ty) []; is_degenerate : bool|} H
    

    /// ### UnionView
    type UnionView = {| cases : Map<int * string, Ty>; layout : UnionLayout; tags : Dictionary<string, int>; tag_cases : (string * Ty) []; is_degenerate : bool |}
    

    let inline union_view (h: Union) : UnionView = h.Item
    let inline union_cases (h: Union) : Map<int * string, Ty> = (union_view h).cases
    
    


    /// ### TermVar
    type TermVar =
        | WV of TyV
        | WLit of Literal
    

    /// ### RData
    type RData =
        | ReB
        | RePair of ConsedNode<RData * RData>
        | ReSymbol of string
        | ReFunction of ConsedNode<E * RData [] * Ty []> // T option and stack sizes are entirely dependent on the body. And unlike in v0.09/v0.1 there are no reified join points.
        | ReForall of ConsedNode<E * RData [] * Ty []>
        | ReExists of ConsedNode<Ty [] * RData>
        | ReRecord of ConsedNode<Map<int * string, RData>>
        | ReLit of Literal
        | ReTLit of Literal
        | ReUnion of ConsedNode<RData * Union>
        | ReNominal of ConsedNode<RData * Ty>
        | ReV of ConsedNode<Tag * Ty>
        | ReHashMap of ConsedNode<(RData * RData)[]>
    

    /// ### EvalReplayValueStore
    module EvalReplayValueStore =
        open System.Collections.Concurrent

        type ApplySpine = {
            headNodeId: int
            headShape: string
            argCount: int
            argNodeIds: int[]
            argShapes: string[]
        }

        // ALPHA369: ETypeApply is a distinct replay composite.  Treat the
        // term function side and the type argument side as children, so the
        // term replay driver no longer falls back to the opaque E* dispatcher.
        type TypeApplySpine = {
            funcNodeId: int
            funcShape: string
            typeNodeId: int
            typeShape: string
        }

        // ALPHA487: TTerm is a type-level wrapper around an embedded term.
        // Store that embedded term as an explicit child so the ty replay driver
        // can yield to term_replay_driver instead of repeating the opaque
        // ty_shape_dispatch_dispatched:TTerm frontier.
        type TypeTermSpine = {
            termNodeId: int
            termShape: string
        }

        // ALPHA865: TJoinPoint' is a type-level wrapper with a scoped body.
        // Store the body as an explicit type child so replay can drive it via
        // ty_replay_driver instead of re-entering the opaque JP wrapper thunk.
        type TypeJoinPointSpine = {
            bodyNodeId: int
            bodyShape: string
        }

        // ALPHA488: TFun can be reached as an annotated function type during
        // TTerm conversion.  Store its arg/body children explicitly so the ty
        // replay driver can drive them one at a time rather than repeating the
        // opaque ty_shape_dispatch_dispatched:TFun frontier.
        type TypeFunSpine = {
            argNodeId: int
            argShape: string
            bodyNodeId: int
            bodyShape: string
            funType: FunType
        }

        // ALPHA556: TPair can be the type argument under TApply/TFun replay.
        // Store its children explicitly so a TPair frontier does not fall through
        // to generic ty_shape_dispatch_dispatched and repeat under child scheduling.
        type TypePairSpine = {
            leftNodeId: int
            leftShape: string
            rightNodeId: int
            rightShape: string
        }

        type IfThenElseSpine = {
            condNodeId: int
            condShape: string
            trueNodeId: int
            trueShape: string
            falseNodeId: int
            falseShape: string
        }

        // ALPHA552: EAnnotTest function bodies need a first-class replay spine so
        // literal-op bodies can schedule their annotation type and branch terms
        // instead of parking the entire body as one opaque terminal.
        type AnnotTestSpine = {
            typeNodeId: int
            typeShape: string
            trueNodeId: int
            trueShape: string
            falseNodeId: int
            falseShape: string
        }

        // ALPHA919: EAnnot is also a composite term.  Its value is the inner
        // term checked against an annotation type; if the direct thunk re-enters,
        // replay should schedule those children explicitly instead of pinning
        // semantic_annot_replay_blocked while live work remains.
        type AnnotSpine = {
            innerNodeId: int
            innerShape: string
            typeNodeId: int
            typeShape: string
        }

        // ALPHA560: EUnitTest is a composite term.  The real thunk decides
        // success/failure from the bound value, but when it reports the selected
        // branch as missing, replay needs stable child ids instead of repeating
        // the opaque E* dispatcher.
        type UnitTestSpine = {
            bindNodeId: int
            bindShape: string
            successNodeId: int
            successShape: string
            failNodeId: int
            failShape: string
        }

        // ALPHA650: EPairTest is also a branch-selecting composite term.
        // The selected branch depends on the already captured bound Data value.
        // Keep the branches explicit so replay can schedule the success/failure
        // child instead of falling into generic E* term-shape dispatch.
        type PairTestSpine = {
            successNodeId: int
            successShape: string
            failNodeId: int
            failShape: string
        }

        // ALPHA1022: EUnbox is a branch-selecting composite term too.
        // Keep the scrutinee and selected branch explicit so replay can step
        // through listm/core unboxes without re-entering the whole black-box
        // thunk and pinning NullReferenceException as the terminal frontier.
        type UnboxSpine = {
            bindNodeId: int
            bindShape: string
            caseName: string
            binderId: Id
            successNodeId: int
            successShape: string
            failNodeId: int
            failShape: string
        }

        type OpSpine = {
            opName: string
            argCount: int
            argNodeIds: int[]
            argShapes: string[]
        }

        // ALPHA438: ESeq is a composite term too.  Alpha437 reached the
        // runtime fixture path sequence and then fell through the generic E*
        // dispatcher with explicit_eval_worklist_term_stepper_required.
        // Keep the store conservative: first child must resolve to unit/
        // placeholder-unit before the second child can satisfy the parent.
        type SeqSpine = {
            firstNodeId: int
            firstShape: string
            secondNodeId: int
            secondShape: string
        }

        type NominalSpine = {
            innerNodeId: int
            innerShape: string
            typeNodeId: int
            typeShape: string
        }

        // ALPHA566: EPair is a constructive composite term.  The real evaluator
        // materializes DPair(term left, term right); replay must therefore track
        // both children instead of falling through generic E* dispatch.
        type TermPairSpine = {
            leftNodeId: int
            leftShape: string
            rightNodeId: int
            rightShape: string
        }

        // ALPHA444: ELet is a composite term with replay children.
        // Alpha443 proved the let thunk can fail with replay_let_body_value_missing:EApply
        // while the retry drain keeps replaying the same parent.  Store body/success child
        // ids so the driver can schedule the missing child explicitly and resume the parent.
        type LetSpine = {
            bodyNodeIds: int[]
            bodyShapes: string[]
            successNodeId: int
            successShape: string
        }

        // ALPHA458: ERecordWith is not a single opaque thunk.  The alpha457
        // branch proved the thunk is present, but it can fail closed with a
        // child PartEvalTypeError.  Store the children that the real evaluator
        // would force (nested keys, update values, remove vars) so replay can
        // schedule one missing child at a time and resume the parent.
        type RecordWithSpine = {
            childNodeIds: int[]
            childShapes: string[]
            childRoles: string[]
        }

        // ALPHA647: EMacro is a replay composite, not just an opaque thunk.
        // Macro evaluation can force term items, type items, literal-type items and
        // the result type.  Store those children explicitly so a failed macro replay
        // can schedule the next missing child instead of repeating the whole thunk
        // until the fingerprint guard hides the real frontier.
        type MacroSpine = {
            termNodeIds: int[]
            termShapes: string[]
            typeNodeIds: int[]
            typeShapes: string[]
            resultTypeNodeId: int
            resultTypeShape: string
        }

        // ALPHA365: first explicit parent-continuation link.
        // A leaf EV/type/op resolution is not a root proof; it must be returned to the
        // composite term that requested it.  The store remains shape-only and generic.
        type ParentContinuation = {
            parentKind: string
            parentShape: string
            parentNodeId: int
            role: string
        }

        // ALPHA497: keep same-kind replay child cells that were intentionally
        // not allowed to overwrite the active parent replay cell.  Alpha496
        // showed a TTerm conversion repeatedly seeing a deferred TFun child
        // and then losing it, so the parent converted/fingerprint-repeated
        // instead of letting the child resolve through ty_replay_driver.
        type DeferredReplayCell = {
            kind: string
            shape: string
            nodeId: int
            envGlobalTerm: int
            envStackTerm: int
            envGlobalType: int
            envStackType: int
            seqLen: int
            cseDepth: int
            traceDepth: int
            site: string
            cursor: int
            step: int
            status: string
        }

        let private termValues = ConcurrentDictionary<int, unit -> Data>()
        let private termReady = ConcurrentDictionary<int, byte>()
        let private typeValues = ConcurrentDictionary<int, unit -> Ty>()
        let private applySpines = ConcurrentDictionary<int, ApplySpine>()
        let private typeApplySpines = ConcurrentDictionary<int, TypeApplySpine>()
        let private typeTermSpines = ConcurrentDictionary<int, TypeTermSpine>()
        let private typeJoinPointSpines = ConcurrentDictionary<int, TypeJoinPointSpine>()
        let private typeFunSpines = ConcurrentDictionary<int, TypeFunSpine>()
        let private typePairSpines = ConcurrentDictionary<int, TypePairSpine>()
        let private ifThenElseSpines = ConcurrentDictionary<int, IfThenElseSpine>()
        let private annotTestSpines = ConcurrentDictionary<int, AnnotTestSpine>()
        let private annotSpines = ConcurrentDictionary<int, AnnotSpine>()
        let private unitTestSpines = ConcurrentDictionary<int, UnitTestSpine>()
        let private pairTestSpines = ConcurrentDictionary<int, PairTestSpine>()
        let private unboxSpines = ConcurrentDictionary<int, UnboxSpine>()
        let private opSpines = ConcurrentDictionary<int, OpSpine>()
        let private seqSpines = ConcurrentDictionary<int, SeqSpine>()
        let private nominalSpines = ConcurrentDictionary<int, NominalSpine>()
        let private termPairSpines = ConcurrentDictionary<int, TermPairSpine>()
        let private letSpines = ConcurrentDictionary<int, LetSpine>()
        let private recordWithSpines = ConcurrentDictionary<int, RecordWithSpine>()
        let private macroSpines = ConcurrentDictionary<int, MacroSpine>()
        // ALPHA435: EOp replay needs the ambient LangEnv too.
        // Alpha434 progressed to term_op_args_available_unimplemented:RecordMap/2;
        // resolving RecordMap requires applying the mapper to each record field.
        // Reuse the existing late-bound apply bridge through a conservative op context.
        let private opContexts = ConcurrentDictionary<int, obj>()
        let private parentContinuations = ConcurrentDictionary<int, ParentContinuation>()
        let private deferredReplayCells = ConcurrentQueue<DeferredReplayCell>()
        let private deferredReplayGate = obj()
        // ALPHA867: deferred replay cells are one-shot work items.
        // Runtime 866 showed the same EUnitTest deferred-after-active-driver cell
        // being re-enqueued after its parent EApply had already root-completed,
        // producing parent-continuation cycles and finally a replay-driver NRE.
        // Keep a stable identity ledger so the queue cannot spin on the same
        // child cell after the driver has already consumed it once.
        let private deferredReplaySeenKeys = ConcurrentDictionary<string, byte>()
        // ALPHA489: guard against pure parent-continuation 2-cycles.
        // Alpha488's runtime reached a TFun<->TB loop where both cells were
        // resolvable and each resume scheduled the other as a fresh parent task.
        // This counter is diagnostic/control only: it does not manufacture type
        // values and it does not raise retry or trampoline caps.
        let private parentContinuationEdgeCounts = ConcurrentDictionary<string, int>()

        // ALPHA1233: cache writes now own parent resurrection.  The previous
        // strategy relied on a parent waking up later, polling replay/cache, and
        // maybe seeing missing-after-prefetch.  This queue records that a concrete
        // child value was committed first; EvalWorklist drains it strictly after
        // the cache write and schedules the parent continuation explicitly.
        type ParentCacheHandoffKindId =
            | ParentCacheHandoffTermValueCommitted
            | ParentCacheHandoffTypeValueCommitted

        let parentCacheHandoffKindText = function
            | ParentCacheHandoffTermValueCommitted -> "term_value_committed"
            | ParentCacheHandoffTypeValueCommitted -> "type_value_committed"

        type ParentCacheHandoffRequest = {
            childKindId: ParentCacheHandoffKindId
            childNodeId: int
            cont: ParentContinuation
            committedUtcMs: int64
        }

        let private parentCacheHandoffQueue = ConcurrentQueue<ParentCacheHandoffRequest>()
        // ALPHA1235: cache-write handoff must not be passive.  The value store is
        // earlier than EvalWorklist in lexical order, so expose a tiny callback bus.
        // EvalWorklist installs a drain callback after scheduleParentReplayLocked exists;
        // every committed child value fires it after the cache write has happened.
        let private parentCacheHandoffWakeCallbacks = ConcurrentQueue<unit -> unit>()

        let installParentCacheHandoffWake (f: unit -> unit) : unit =
            if not (obj.ReferenceEquals(f, null)) then parentCacheHandoffWakeCallbacks.Enqueue f

        let private fireParentCacheHandoffWake () : unit =
            try
                for f in parentCacheHandoffWakeCallbacks.ToArray() do
                    try f() with _ -> ()
            with _ -> ()

        let clearParentCacheHandoffs () : int =
            let mutable cleared = 0
            let mutable req = Unchecked.defaultof<ParentCacheHandoffRequest>
            while parentCacheHandoffQueue.TryDequeue(&req) do
                cleared <- cleared + 1
            cleared

        let private applyContexts = ConcurrentDictionary<int, obj>()
        let private typeApplyContexts = ConcurrentDictionary<int, obj>()
        // Annot-test replay needs the concrete body environment and bound value so
        // branch selection can be re-run without fabricating either branch.
        let private annotTestContexts = ConcurrentDictionary<int, obj>()
        let private annotTestBindValues = ConcurrentDictionary<int, Data>()
        let private pairTestBindValues = ConcurrentDictionary<int, Data>()
        // ALPHA459: remember which function body child belongs to an EApply parent.
        // If the body child resolves later, the replay driver can consume it directly
        // instead of forcing runApplyAfterDefinition through the same recursive failure.
        let private applyFunctionBodyNodes = ConcurrentDictionary<int, int>()
        // ALPHA415: remember which child body was scheduled for an ETypeApply.
        // Alpha414 proved the child EForall' can resolve, but the parent was still
        // re-running the original failing type_apply path instead of consuming the
        // resolved child value.  This map stays value-gated: it stores only node ids.
        let private typeApplyBodyNodes = ConcurrentDictionary<int, int>()

        // ALPHA432: terminal term replay source cache.
        // Alpha431 proved fuse clearing works, but a stable root-complete EApply can be
        // rediscovered with a fresh node_id on the next attempt.  Keep only already-
        // materialized Data values behind a conservative source/environment key so the
        // following attempt can consume the terminal value instead of re-handoff looping.
        let private termSourceValues = ConcurrentDictionary<string, unit -> Data>()

        // ALPHA577: mirror the term source cache for type roots.  Runtime 576
        // showed a ty/TFun root completing and then being displaced by a later
        // stale TV-missing terminal during pending-job drain.  This cache only
        // stores already materialized Ty values; missing/stale thunks still fail
        // closed through tryType.
        let private typeSourceValues = ConcurrentDictionary<string, unit -> Ty>()

        // ALPHA1307: keep the .NET stack trace for failed replay thunks.  The
        // terminal reason remains compact, but Phase 2/NRE debugging needs the
        // exact throw site without turning the exception into a semantic value.
        let private termExceptionTraces = ConcurrentDictionary<int, string>()
        let private termExceptionTypes = ConcurrentDictionary<int, string>()
        let private typeExceptionTraces = ConcurrentDictionary<int, string>()
        let private typeExceptionTypes = ConcurrentDictionary<int, string>()

        let termSourceKey (site: string) (shape: string) (envGlobalTerm: int) (envStackTerm: int) (envGlobalType: int) (envStackType: int) (traceLen: int) =
            sprintf "%s|shape=%s|env=%d/%d:%d/%d|trace=%d" site shape envGlobalTerm envStackTerm envGlobalType envStackType traceLen

        let typeSourceKey (site: string) (shape: string) (envGlobalTerm: int) (envStackTerm: int) (envGlobalType: int) (envStackType: int) (traceLen: int) =
            sprintf "%s|shape=%s|env=%d/%d:%d/%d|trace=%d" site shape envGlobalTerm envStackTerm envGlobalType envStackType traceLen

        let putTermSourceValue (key: string) (value: Data) : unit =
            if not (System.String.IsNullOrWhiteSpace key) then
                termSourceValues.[key] <- (fun () -> value)

        let putTypeSourceValue (key: string) (value: Ty) : unit =
            if not (System.String.IsNullOrWhiteSpace key) then
                typeSourceValues.[key] <- (fun () -> value)

        let tryTermSourceValue (key: string) : Data option =
            let mutable thunk = Unchecked.defaultof<unit -> Data>
            if termSourceValues.TryGetValue(key, &thunk) then
                try Some (thunk())
                with _ -> None
            else None

        let tryTypeSourceValue (key: string) : Ty option =
            let mutable thunk = Unchecked.defaultof<unit -> Ty>
            if typeSourceValues.TryGetValue(key, &thunk) then
                try Some (thunk())
                with _ -> None
            else None

        // ALPHA380: scope-safe bridge for replaying DFunction application.
        // EvalReplayValueStore is defined before LangEnv/apply are in lexical scope, so
        // it cannot capture apply directly.  Store a late-installed, type-erased
        // continuation instead; EApply thunks use it only after all head/arg values
        // are available, and tryTerm keeps failures fail-closed.
        let private applyAfterDefinitionRef = ref (None : (obj -> Data -> Data -> Data) option)
        let private applyFunctionBodyReplayAfterDefinitionRef = ref (None : (obj -> int -> Data -> Data -> Choice<int * string,string>) option)
        let private dynamicJoinApplyAfterDefinitionRef = ref (None : (obj -> Data -> Data -> Data) option)
        let private typeApplyAfterDefinitionRef = ref (None : (obj -> Data -> Ty -> Data) option)
        let private typeApplyBodyReplayAfterDefinitionRef = ref (None : (obj -> int -> Data -> Ty -> Choice<int * string,string>) option)
        let private typeAwareOpReplayAfterDefinitionRef = ref (None : (obj -> string -> int[] -> Choice<Data,string>) option)
        // ALPHA666: some type-aware ops, notably BackendSwitch, need a two-step replay:
        // first schedule the selected branch body, then accept the parent op only when
        // that child has produced a real Data value.
        let private typeAwareOpReplayScheduleAfterDefinitionRef = ref (None : (obj -> int -> string -> int[] -> Choice<int * string * string,string>) option)
        let private typeAwareOpResultNodes = ConcurrentDictionary<int,int>()
        let private annotTestBranchReplayAfterDefinitionRef = ref (None : (obj -> Data -> Ty -> Choice<bool,string>) option)

        let installApplyAfterDefinition (f: obj -> Data -> Data -> Data) : unit =
            applyAfterDefinitionRef.Value <- Some f

        let runApplyAfterDefinition (sObj: obj) (head: Data) (arg: Data) : Data =
            match applyAfterDefinitionRef.Value with
            | Some f -> f sObj head arg
            | None -> failwith "Replay apply-after-definition continuation is not installed."

        // ALPHA459: late-bound explicit stepper for DFunction bodies reached through EApply.
        // This mirrors the ETypeApply body bridge: after the concrete LangEnv is in scope,
        // the bridge can materialize the function body as a replay child rather than rerunning
        // the whole apply thunk until the fingerprint guard parks it.
        let installApplyFunctionBodyReplayAfterDefinition (f: obj -> int -> Data -> Data -> Choice<int * string,string>) : unit =
            applyFunctionBodyReplayAfterDefinitionRef.Value <- Some f

        // ALPHA385: late-bound dynamic join/apply bridge.  Alpha384 proved that
        // DFunction + DNominal/DV should not force the function body; the explicit
        // worklist needs a real, named stepper that can synthesize the same kind of
        // conservative runtime placeholder used by JP recursion recovery.
        let installDynamicJoinApplyAfterDefinition (f: obj -> Data -> Data -> Data) : unit =
            dynamicJoinApplyAfterDefinitionRef.Value <- Some f

        let runDynamicJoinApplyAfterDefinition (sObj: obj) (head: Data) (arg: Data) : Data =
            match dynamicJoinApplyAfterDefinitionRef.Value with
            | Some f -> f sObj head arg
            | None -> failwith "Replay dynamic-join-apply continuation is not installed."

        // ALPHA380: mirror the late-bound bridge for type application.
        // ETypeApply reached a real frontier after alpha379: the replay driver can
        // now resolve the forall head and type argument, but it must not call the
        // recursive evaluator before the real type_apply function is in scope.
        let installTypeApplyAfterDefinition (f: obj -> Data -> Ty -> Data) : unit =
            typeApplyAfterDefinitionRef.Value <- Some f

        let runTypeApplyAfterDefinition (sObj: obj) (head: Data) (arg: Ty) : Data =
            match typeApplyAfterDefinitionRef.Value with
            | Some f -> f sObj head arg
            | None -> failwith "Replay type-apply-after-definition continuation is not installed."

        // ALPHA414: late-bound explicit stepper for ETypeApply forall bodies.
        // Alpha413 proved the replay driver can resolve the TFun root and then
        // stalls at term@spiral.spi:2671 because running the whole forall body
        // as a single thunk throws PartEvalTypeError.  Keep the store generic:
        // after LangEnv/term are in scope we install a bridge that can register
        // the body as an ordinary term child and attach a parent continuation.
        let installTypeApplyBodyReplayAfterDefinition (f: obj -> int -> Data -> Ty -> Choice<int * string,string>) : unit =
            typeApplyBodyReplayAfterDefinitionRef.Value <- Some f

        let installTypeAwareOpReplayAfterDefinition (f: obj -> string -> int[] -> Choice<Data,string>) : unit =
            typeAwareOpReplayAfterDefinitionRef.Value <- Some f

        let installTypeAwareOpReplayScheduleAfterDefinition (f: obj -> int -> string -> int[] -> Choice<int * string * string,string>) : unit =
            typeAwareOpReplayScheduleAfterDefinitionRef.Value <- Some f

        let putTypeAwareOpResultNode (parentNodeId: int) (childNodeId: int) : unit =
            if parentNodeId <> childNodeId then typeAwareOpResultNodes.[parentNodeId] <- childNodeId

        let tryTypeAwareOpScheduledResult (parentNodeId: int) : Data option =
            let mutable childNodeId = 0
            if typeAwareOpResultNodes.TryGetValue(parentNodeId, &childNodeId) then
                let mutable thunk = Unchecked.defaultof<unit -> Data>
                if termValues.TryGetValue(childNodeId, &thunk) then
                    try
                        let value = thunk()
                        termReady.[childNodeId] <- 1uy
                        Some value
                    with _ -> None
                else None
            else None

        let installAnnotTestBranchAfterDefinition (f: obj -> Data -> Ty -> Choice<bool,string>) : unit =
            annotTestBranchReplayAfterDefinitionRef.Value <- Some f

        let private cleanExnText (s: string) =
            if isNull s then ""
            else s.Replace("\r"," ").Replace("\n"," | ").Replace("\t"," ")

        let private compactExn (ex: exn) =
            let msg = cleanExnText ex.Message
            let msg = if msg.Length > 180 then msg.Substring(0, 180) + "..." else msg
            ex.GetType().Name + ":" + msg

        let private compactExnTrace (ex: exn) =
            let trace = cleanExnText ex.StackTrace
            if System.String.IsNullOrWhiteSpace trace then "stack_trace_missing"
            elif trace.Length > 1400 then trace.Substring(0, 1400) + "..."
            else trace

        let private compactExnType (ex: exn) =
            if obj.ReferenceEquals(ex, null) then "exception_missing"
            else ex.GetType().Name

        let putApplyContext (nodeId: int) (sObj: obj) : unit =
            applyContexts.[nodeId] <- sObj

        let tryApplyContext (nodeId: int) : obj option =
            let mutable sObj = Unchecked.defaultof<obj>
            if applyContexts.TryGetValue(nodeId, &sObj) then Some sObj else None

        let putTypeApplyContext (nodeId: int) (sObj: obj) : unit =
            typeApplyContexts.[nodeId] <- sObj

        let tryTypeApplyContext (nodeId: int) : obj option =
            let mutable sObj = Unchecked.defaultof<obj>
            if typeApplyContexts.TryGetValue(nodeId, &sObj) then Some sObj else None

        let putOpContext (nodeId: int) (sObj: obj) : unit =
            opContexts.[nodeId] <- sObj
            // Reuse the existing apply/type-apply bridges for op-local mapped calls.
            // ALPHA1078: runtime 1077 proved some EOp registration paths still reached
            // RecordTypeTryFind/Fsharp with type_apply_context_missing before the
            // scheduled child replay could execute.  The op context is the same LangEnv
            // authority used by the apply bridge, so installing it here is a bridge
            // repair, not a fabricated branch value.
            applyContexts.[nodeId] <- sObj
            typeApplyContexts.[nodeId] <- sObj

        let tryOpContext (nodeId: int) : obj option =
            let mutable sObj = Unchecked.defaultof<obj>
            if opContexts.TryGetValue(nodeId, &sObj) then Some sObj else None

        let putAnnotTestContext (nodeId: int) (sObj: obj) : unit =
            annotTestContexts.[nodeId] <- sObj

        let putAnnotTestBindValue (nodeId: int) (value: Data) : unit =
            annotTestBindValues.[nodeId] <- value

        let putPairTestBindValue (nodeId: int) (value: Data) : unit =
            pairTestBindValues.[nodeId] <- value

        let tryPairTestBindValue (nodeId: int) : Data option =
            let mutable value = Unchecked.defaultof<Data>
            if pairTestBindValues.TryGetValue(nodeId, &value) then Some value else None

        let tryAnnotTestContext (nodeId: int) : obj option =
            let mutable sObj = Unchecked.defaultof<obj>
            if annotTestContexts.TryGetValue(nodeId, &sObj) then Some sObj else None

        let tryAnnotTestBindValue (nodeId: int) : Data option =
            let mutable value = Unchecked.defaultof<Data>
            if annotTestBindValues.TryGetValue(nodeId, &value) then Some value else None

        let tryAnnotTestBranchSelection (nodeId: int) (annotTy: Ty) : Choice<bool,string> =
            match tryAnnotTestContext nodeId, tryAnnotTestBindValue nodeId, annotTestBranchReplayAfterDefinitionRef.Value with
            | Some sObj, Some bindValue, Some f ->
                try f sObj bindValue annotTy
                with ex -> Choice2Of2 (compactExn ex)
            | None, _, _ -> Choice2Of2 "annot_test_context_missing"
            | _, None, _ -> Choice2Of2 "annot_test_bind_value_missing"
            | _, _, None -> Choice2Of2 "annot_test_branch_stepper_not_installed"

        let tryTypeAwareOpReplayWithContext (contextNodeId: int) (opName: string) (argNodeIds: int[]) : Data option =
            match tryTypeAwareOpScheduledResult contextNodeId with
            | Some value -> Some value
            | None ->
                match tryOpContext contextNodeId, typeAwareOpReplayAfterDefinitionRef.Value with
                | Some sObj, Some f ->
                    try
                        match f sObj opName argNodeIds with
                        | Choice1Of2 value -> Some value
                        | Choice2Of2 _ -> None
                    with _ -> None
                | _ -> None

        // ALPHA1437: UnionUntag is no longer a raw "op implementation missing" string.
        // The sequential evaluator already owns the semantics; the replay bridge now
        // records which typed path was attempted before either returning a real value
        // or failing closed with a useful reason.
        type TypeAwareUnionUntagReplayDecisionId =
            | TypeAwareUnionUntagDirectLiteralTag
            | TypeAwareUnionUntagRuntimeTagSwitch
            | TypeAwareUnionUntagTagOutOfRange
            | TypeAwareUnionUntagMissingUnionType
            | TypeAwareUnionUntagMissingArgs
            | TypeAwareUnionUntagMalformedTag
            | TypeAwareUnionUntagBranchTypeMismatch
            | TypeAwareUnionUntagBranchReplayFailed

        let typeAwareUnionUntagReplayDecisionText = function
            | TypeAwareUnionUntagDirectLiteralTag -> "direct_literal_tag"
            | TypeAwareUnionUntagRuntimeTagSwitch -> "runtime_tag_switch"
            | TypeAwareUnionUntagTagOutOfRange -> "tag_out_of_range"
            | TypeAwareUnionUntagMissingUnionType -> "missing_union_type"
            | TypeAwareUnionUntagMissingArgs -> "missing_args"
            | TypeAwareUnionUntagMalformedTag -> "malformed_tag"
            | TypeAwareUnionUntagBranchTypeMismatch -> "branch_type_mismatch"
            | TypeAwareUnionUntagBranchReplayFailed -> "branch_replay_failed"

        // ALPHA1513: PrototypeHas replay must be typed at the diagnostic boundary.
        // Alpha1512 fixed the runtime frontier but introduced a compile break by
        // mixing scheduler-only context and raw GlobalId formatting in the replay
        // closure.  These DUs keep the next frontier observable without string drift.
        type TypeAwarePrototypeHasReplayDecisionId =
            | TypeAwarePrototypeHasResolved
            | TypeAwarePrototypeHasExpectedNominalType
            | TypeAwarePrototypeHasExpectedForallTerm
            | TypeAwarePrototypeHasExpectedPrototypeBody
            | TypeAwarePrototypeHasTermMissing
            | TypeAwarePrototypeHasTypeArgMissing

        let typeAwarePrototypeHasReplayDecisionText = function
            | TypeAwarePrototypeHasResolved -> "resolved"
            | TypeAwarePrototypeHasExpectedNominalType -> "expected_nominal_type"
            | TypeAwarePrototypeHasExpectedForallTerm -> "expected_forall_term"
            | TypeAwarePrototypeHasExpectedPrototypeBody -> "expected_forall_or_prototype_apply"
            | TypeAwarePrototypeHasTermMissing -> "prototype_term_missing"
            | TypeAwarePrototypeHasTypeArgMissing -> "nominal_type_arg_missing"

        let typeAwarePrototypeHasReplayDecisionKind = function
            | TypeAwarePrototypeHasResolved -> "eval_worklist_type_aware_prototype_has_replay_resolved"
            | _ -> "eval_worklist_type_aware_prototype_has_replay_blocked"

        // ALPHA1021: make type-aware op replay schedule failures explicit.
        // The bridge still returns None on failure, but every failure now crosses a
        // closed DU before becoming JSON text. This is the current GTE/EQ frontier:
        // it needs better evidence, not a fabricated comparison value.
        type TypeAwareOpReplayScheduleFailure =
            | TypeAwareOpScheduleContextMissing
            | TypeAwareOpScheduleStepperMissing
            | TypeAwareOpScheduleRejected of string
            | TypeAwareOpScheduleException of string

        let private typeAwareOpReplayScheduleFailureKind failure =
            match failure with
            | TypeAwareOpScheduleException _ -> "eval_worklist_type_aware_op_replay_schedule_exception"
            | TypeAwareOpScheduleContextMissing
            | TypeAwareOpScheduleStepperMissing
            | TypeAwareOpScheduleRejected _ -> "eval_worklist_type_aware_op_replay_schedule_blocked"

        let private typeAwareOpReplayScheduleFailureDetail failure =
            match failure with
            | TypeAwareOpScheduleContextMissing -> "type_aware_op_context_missing"
            | TypeAwareOpScheduleStepperMissing -> "type_aware_op_replay_schedule_stepper_missing"
            | TypeAwareOpScheduleRejected detail -> detail
            | TypeAwareOpScheduleException detail -> detail

        let private typeAwareOpReplayScheduleFailureNext failure =
            match failure with
            | TypeAwareOpScheduleContextMissing -> "install_type_aware_op_context_required"
            | TypeAwareOpScheduleStepperMissing -> "install_type_aware_op_replay_schedule_stepper_required"
            | TypeAwareOpScheduleRejected _
            | TypeAwareOpScheduleException _ -> "explicit_type_aware_op_replay_schedule_required"

        let replayOpArgStatesJson (argShapes: string[]) (argNodeIds: int[]) =
            argNodeIds
            |> Array.mapi (fun i nodeId ->
                let shape = if i < argShapes.Length then argShapes.[i] else "unknown"
                let termState =
                    if termReady.ContainsKey nodeId then "ready_marker"
                    elif termValues.ContainsKey nodeId then "registered"
                    else "missing"
                let typeState =
                    if typeValues.ContainsKey nodeId then "registered"
                    else "missing"
                sprintf "{\"i\":%d,\"node_id\":%d,\"shape\":%s,\"term\":%s,\"ty\":%s}"
                    i nodeId (DiagJson.esc shape) (DiagJson.esc termState) (DiagJson.esc typeState))
            |> String.concat ","
            |> sprintf "[%s]"

        let replayNodeStateJson (nodeId: int) (shape: string) =
            let termState =
                if termReady.ContainsKey nodeId then "ready_marker"
                elif termValues.ContainsKey nodeId then "registered"
                else "missing"
            let typeState =
                if typeValues.ContainsKey nodeId then "registered"
                else "missing"
            let deferredState =
                lock deferredReplayGate (fun () ->
                    deferredReplayCells
                    |> Seq.exists (fun cell -> cell.nodeId = nodeId))
            sprintf "{\"node_id\":%d,\"shape\":%s,\"term\":%s,\"ty\":%s,\"deferred\":%b}"
                nodeId (DiagJson.esc shape) (DiagJson.esc termState) (DiagJson.esc typeState) deferredState

        let private emitTypeAwareOpReplayScheduleFailure contextNodeId opName argNodeIds failure =
            DiagJson.emit (
                sprintf "{\"kind\":%s,\"context_node_id\":%d,\"op\":%s,\"detail\":%s,\"arg_states\":%s,\"single_flight\":1,\"next\":%s}"
                    (DiagJson.esc (typeAwareOpReplayScheduleFailureKind failure))
                    contextNodeId
                    (DiagJson.esc opName)
                    (DiagJson.esc (typeAwareOpReplayScheduleFailureDetail failure))
                    (replayOpArgStatesJson [||] argNodeIds)
                    (DiagJson.esc (typeAwareOpReplayScheduleFailureNext failure)))

        let tryScheduleTypeAwareOpReplayWithContext (contextNodeId: int) (opName: string) (argNodeIds: int[]) : (int * string * string) option =
            match tryOpContext contextNodeId, typeAwareOpReplayScheduleAfterDefinitionRef.Value with
            | Some sObj, Some f ->
                try
                    match f sObj contextNodeId opName argNodeIds with
                    | Choice1Of2 child -> Some child
                    | Choice2Of2 detail ->
                        emitTypeAwareOpReplayScheduleFailure contextNodeId opName argNodeIds (TypeAwareOpScheduleRejected detail)
                        None
                with ex ->
                    emitTypeAwareOpReplayScheduleFailure contextNodeId opName argNodeIds (TypeAwareOpScheduleException (compactExn ex))
                    None
            | None, _ ->
                emitTypeAwareOpReplayScheduleFailure contextNodeId opName argNodeIds TypeAwareOpScheduleContextMissing
                None
            | _, None ->
                emitTypeAwareOpReplayScheduleFailure contextNodeId opName argNodeIds TypeAwareOpScheduleStepperMissing
                None

        let putApplyFunctionBodyNode (parentNodeId: int) (bodyNodeId: int) : unit =
            if parentNodeId <> bodyNodeId then
                applyFunctionBodyNodes.[parentNodeId] <- bodyNodeId

        let tryApplyFunctionBodyValueAt (parentNodeId: int) : Data option =
            let mutable bodyNodeId = 0
            if applyFunctionBodyNodes.TryGetValue(parentNodeId, &bodyNodeId) then
                let mutable thunk = Unchecked.defaultof<unit -> Data>
                if termValues.TryGetValue(bodyNodeId, &thunk) then
                    try Some (thunk())
                    with _ -> None
                else None
            else None

        let tryScheduleApplyFunctionBodyReplayAt (nodeId: int) (head: Data) (arg: Data) : Choice<int * string,string> =
            match tryApplyContext nodeId, applyFunctionBodyReplayAfterDefinitionRef.Value with
            | Some sObj, Some f ->
                try f sObj nodeId head arg
                with ex -> Choice2Of2 ("apply_function_body_stepper_failed:" + compactExn ex)
            | None, _ -> Choice2Of2 "apply_context_missing"
            | _, None -> Choice2Of2 "apply_function_body_stepper_not_installed"

        let putTypeApplyBodyNode (parentNodeId: int) (bodyNodeId: int) : unit =
            if parentNodeId <> bodyNodeId then
                typeApplyBodyNodes.[parentNodeId] <- bodyNodeId

        let tryScheduleTypeApplyBodyReplayAt (nodeId: int) (head: Data) (arg: Ty) : Choice<int * string,string> =
            match tryTypeApplyContext nodeId, typeApplyBodyReplayAfterDefinitionRef.Value with
            | Some sObj, Some f ->
                try f sObj nodeId head arg
                with ex -> Choice2Of2 ("type_apply_body_stepper_failed:" + compactExn ex)
            | None, _ -> Choice2Of2 "type_apply_context_missing"
            | _, None -> Choice2Of2 "type_apply_body_stepper_not_installed"

        let putParentContinuation (childNodeId: int) (cont: ParentContinuation) : unit =
            if childNodeId <> cont.parentNodeId then
                parentContinuations.[childNodeId] <- cont

        let tryParentContinuation (childNodeId: int) : ParentContinuation option =
            let mutable cont = Unchecked.defaultof<ParentContinuation>
            if parentContinuations.TryGetValue(childNodeId, &cont) then Some cont else None

        let noteParentContinuationEdge (childKind: string) (childShape: string) (childNodeId: int) (cont: ParentContinuation) : int =
            let key =
                sprintf "%s:%s:%d->%s:%s:%d:%s"
                    childKind childShape childNodeId cont.parentKind cont.parentShape cont.parentNodeId cont.role
            parentContinuationEdgeCounts.AddOrUpdate(key, 1, (fun _ n -> n + 1))

        let private enqueueParentCacheHandoff (kindId: ParentCacheHandoffKindId) (childNodeId: int) =
            match tryParentContinuation childNodeId with
            | Some cont when childNodeId <> cont.parentNodeId ->
                parentCacheHandoffQueue.Enqueue({
                    childKindId = kindId
                    childNodeId = childNodeId
                    cont = cont
                    committedUtcMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                })
                fireParentCacheHandoffWake()
            | _ -> ()

        let tryTakeParentCacheHandoff () : ParentCacheHandoffRequest option =
            let mutable req = Unchecked.defaultof<ParentCacheHandoffRequest>
            if parentCacheHandoffQueue.TryDequeue(&req) then Some req else None

        let parentCacheHandoffQueueDepth () : int =
            parentCacheHandoffQueue.Count

        let putTerm (nodeId: int) (thunk: unit -> Data) : unit =
            termValues.[nodeId] <- thunk
            let mutable removed = 0uy
            termReady.TryRemove(nodeId, &removed) |> ignore

        let putTermValue (nodeId: int) (value: Data) : unit =
            termValues.[nodeId] <- (fun () -> value)
            termReady.[nodeId] <- 1uy
            enqueueParentCacheHandoff ParentCacheHandoffTermValueCommitted nodeId

        // ALPHA555: replay-side type values can be materialized only after their
        // child Ty values already exist.  This avoids re-entering the original
        // type thunk when TFun.arg and TFun.body are both resolved, but does not
        // claim success for missing children.
        let putTypeValue (nodeId: int) (value: Ty) : unit =
            typeValues.[nodeId] <- (fun () -> value)
            enqueueParentCacheHandoff ParentCacheHandoffTypeValueCommitted nodeId

        // ALPHA598: reusable fail-closed TV environment snapshot.  Alpha597's
        // remaining terminal was a TFun child TV whose parent cell still had
        // env_type=1/0, but the child replay reached tryType as a missing value.
        // Store only concrete in-bounds Ty values, keyed by the child node id;
        // out-of-bounds variables continue through the old vt thunk / terminal path.
        let putTypeVarEnvSnapshot (nodeId: int) (index: int) (globalTypes: Ty[]) (stackTypes: Ty[]) : (string * int * int) option =
            let globalTypeLen =
                if obj.ReferenceEquals(globalTypes, null) then 0
                else globalTypes.Length
            let stackTypeLen =
                if obj.ReferenceEquals(stackTypes, null) then 0
                else stackTypes.Length
            if index >= 0 && index < globalTypeLen then
                putTypeValue nodeId globalTypes.[index]
                Some("global", globalTypeLen, stackTypeLen)
            elif index >= globalTypeLen && (index - globalTypeLen) >= 0 && (index - globalTypeLen) < stackTypeLen then
                putTypeValue nodeId stackTypes.[index - globalTypeLen]
                Some("stack", globalTypeLen, stackTypeLen)
            else None

        // ALPHA366: function heads are replay values too.  Alpha365 reached
        // EApply -> ERecursiveFun' and then stopped because only EV leaves were
        // stored as values.  This helper keeps the replay store generic: a
        // captured function value can satisfy an apply-head request without
        // claiming root completion or touching the writer.
        let putFunctionValue (nodeId: int) (body: E) (annot: TPrepass option) (termEnv: Data[]) (tyEnv: Ty[]) (termStackSize: StackSize) (tyStackSize: StackSize) : unit =
            putTermValue nodeId (DFunction(body, annot, termEnv, tyEnv, termStackSize, tyStackSize))

        let putForallValue (nodeId: int) (body: E) (termEnv: Data[]) (tyEnv: Ty[]) (termStackSize: StackSize) (tyStackSize: StackSize) : unit =
            putTermValue nodeId (DForall(body, termEnv, tyEnv, termStackSize, tyStackSize))

        let putType (nodeId: int) (thunk: unit -> Ty) : unit =
            typeValues.[nodeId] <- thunk

        let private deferredTypeVarCells = ConcurrentQueue<int * string>()

        // ALPHA1223: deferred holes are now classified as data before they are
        // rendered as queue strings.  This keeps the monomorphization lane typed
        // while preserving the legacy reason payload for receipts.
        type PendingMonomorphizationReasonId =
            | PendingMonoCrossKindCycle
            | PendingMonoParentContinuationCycle
            | PendingMonoGlobalFuseCycle
            | PendingMonoChildCycle
            | PendingMonoUnknown

        let pendingMonomorphizationReasonText = function
            | PendingMonoCrossKindCycle -> "cross_kind_cycle"
            | PendingMonoParentContinuationCycle -> "parent_continuation_cycle"
            | PendingMonoGlobalFuseCycle -> "global_fuse_cycle"
            | PendingMonoChildCycle -> "child_cycle"
            | PendingMonoUnknown -> "unknown"

        let pendingMonomorphizationReasonFor (reason: string) =
            let r = if System.Object.ReferenceEquals(reason, null) then "" else reason
            if r.Contains("cross_kind", StringComparison.OrdinalIgnoreCase) then PendingMonoCrossKindCycle
            elif r.Contains("global_fuse", StringComparison.OrdinalIgnoreCase) then PendingMonoGlobalFuseCycle
            elif r.Contains("parent", StringComparison.OrdinalIgnoreCase) then PendingMonoParentContinuationCycle
            elif r.Contains("child", StringComparison.OrdinalIgnoreCase) then PendingMonoChildCycle
            else PendingMonoUnknown

        // ALPHA1236: the queue source is now a DU at the producer boundary.
        // The legacy record keeps `source: string` because downstream receipts still
        // serialize text, but callers cannot accidentally smuggle arbitrary source
        // prose through the destructive DeferredTypeVar path.
        type PendingMonomorphizationSourceId =
            | PendingMonoSourceDeferredTypeVarCycleBreak
            | PendingMonoSourceDeferredTypeVarOverwriteCycleBreak
            | PendingMonoSourceOther of string

        let pendingMonomorphizationSourceText = function
            | PendingMonoSourceDeferredTypeVarCycleBreak -> "deferred_type_var_cycle_break"
            | PendingMonoSourceDeferredTypeVarOverwriteCycleBreak -> "deferred_type_var_overwrite_cycle_break"
            | PendingMonoSourceOther text when not (System.String.IsNullOrWhiteSpace text) -> text
            | PendingMonoSourceOther _ -> "pending_monomorphization_unknown_source"

        // Typed migration seam for deferred unification holes.  The runtime carrier is
        // still YMetavar, but this phantom wrapper prevents the monomorphization queue
        // from accepting an unclassified string-only hole at the producer boundary.
        type TyDeferredHoleKind =
            | TyDeferredHoleKindTag
        type TermDeferredHoleKind =
            | TermDeferredHoleKindTag
        type DeferredTypeHole<'kind> = private DeferredTypeHole of int * PendingMonomorphizationReasonId

        let private mkTyDeferredHole nodeId reasonId : DeferredTypeHole<TyDeferredHoleKind> =
            DeferredTypeHole(nodeId, reasonId)

        let private deferredHoleNodeId (DeferredTypeHole(nodeId, _)) = nodeId
        let private deferredHoleReasonId (DeferredTypeHole(_, reasonId)) = reasonId

        // ALPHA1222: turn the old deferred-type-var side channel into an
        // explicit monomorphization queue. The hole is still represented by
        // YMetavar so type safety stays fail-closed, but the scheduler now has
        // a named queue to drain/inspect instead of treating the cycle break as
        // a quiet local cache mutation.
        type PendingMonomorphizationEntry = {
            nodeId: int
            reason: string
            reasonId: PendingMonomorphizationReasonId
            source: string
            createdUtcMs: int64
        }

        let private pendingMonomorphizationQueue = ConcurrentQueue<PendingMonomorphizationEntry>()
        // ALPHA1239: the assessment wants real DeferredTypeVar pressure, not an
        // ever-growing mirage of identical pending monomorphization entries.
        // Keep the destructive overwrite, but coalesce queue obligations per node.
        let private pendingMonomorphizationSeen = ConcurrentDictionary<int, byte>()

        type PendingMonomorphizationQueueDecisionId =
            | PendingMonoQueueEnqueued
            | PendingMonoQueueMergedExistingNode

        let private pendingMonomorphizationQueueDecisionText = function
            | PendingMonoQueueEnqueued -> "enqueued"
            | PendingMonoQueueMergedExistingNode -> "merged_existing_node"

        let private deferredTypeVarFor (nodeId: int) : Ty =
            // ALPHA1210: a parent-continuation type cycle can now be
            // broken by an explicit hole instead of another passive
            // timeout.  Use the existing YMetavar carrier so this stays
            // inside the type system and remains visible to later
            // unification/codegen gates; no root proof or BuildOk is
            // fabricated by creating the hole.
            let stableId = -1000000000 + (abs nodeId % 100000000)
            YMetavar stableId

        let putDeferredTypeVar (nodeId: int) (reason: string) : bool =
            // ALPHA1235: destructive cycle breaker.  The assessment failure mode is
            // a stale type thunk already occupying typeValues, so ContainsKey=false
            // gating made the hole a mirage.  Overwrite the thunk with an explicit
            // YMetavar hole, record pending monomorphization, and let parent handoff
            // wakeups run through putTypeValue.  Return true for "graph mutated" even
            // when we replaced a previous thunk.
            let alreadyHadTypeThunk = typeValues.ContainsKey nodeId
            let reason0 = if System.String.IsNullOrWhiteSpace reason then "deferred_type_var_cycle_break" else reason
            let reason' =
                if alreadyHadTypeThunk then reason0 + ":overwrite_existing_type_thunk"
                else reason0 + ":fresh_type_hole"
            putTypeValue nodeId (deferredTypeVarFor nodeId)
            deferredTypeVarCells.Enqueue((nodeId, reason'))
            let reasonId = pendingMonomorphizationReasonFor reason'
            let sourceId =
                if alreadyHadTypeThunk then PendingMonoSourceDeferredTypeVarOverwriteCycleBreak
                else PendingMonoSourceDeferredTypeVarCycleBreak
            let sourceText = pendingMonomorphizationSourceText sourceId
            let hole = mkTyDeferredHole nodeId reasonId
            let queueDecisionId =
                if pendingMonomorphizationSeen.TryAdd(deferredHoleNodeId hole, 1uy) then
                    pendingMonomorphizationQueue.Enqueue({
                        nodeId = deferredHoleNodeId hole
                        reason = reason'
                        reasonId = deferredHoleReasonId hole
                        source = sourceText
                        createdUtcMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                    })
                    PendingMonoQueueEnqueued
                else PendingMonoQueueMergedExistingNode
            queueDecisionId |> ignore
            // Keep graph mutation truthy even when the queue obligation merged: the
            // explicit YMetavar overwrite is still the structural action.
            true

        let deferredTypeVarQueueDepth () : int =
            deferredTypeVarCells.Count

        let pendingMonomorphizationQueueDepth () : int =
            pendingMonomorphizationQueue.Count

        type Phase2DeferredTypeVarSweepDecisionId =
            | Phase2DeferredTypeVarSweepNoop
            | Phase2DeferredTypeVarSweepPatched

        let private phase2DeferredTypeVarSweepDecisionText = function
            | Phase2DeferredTypeVarSweepNoop -> "noop"
            | Phase2DeferredTypeVarSweepPatched -> "patched"

        type Phase2DeferredTypeVarGroundDefaultId =
            | Phase2DeferredTypeVarGroundBoolSentinel

        let private phase2DeferredTypeVarGroundDefaultText = function
            | Phase2DeferredTypeVarGroundBoolSentinel -> "ground_bool_sentinel"

        let private phase2DeferredTypeVarGroundDefaultValueText = function
            | Phase2DeferredTypeVarGroundBoolSentinel -> "YB"

        let private phase2DeferredTypeVarGroundDefaultValue = function
            | Phase2DeferredTypeVarGroundBoolSentinel -> YB

        type Phase2PairDeferredChildSweepDecisionId =
            | Phase2PairDeferredChildSweepNoop
            | Phase2PairDeferredChildSweepConsidered

        let private phase2PairDeferredChildSweepDecisionText = function
            | Phase2PairDeferredChildSweepNoop -> "noop"
            | Phase2PairDeferredChildSweepConsidered -> "considered_pair_deferred_children"

        let tryPhase2SynchronousDeferredTypeVarSweep (event: string) (reason: string) (maxItems: int) : int =
            // ALPHA1307: snapshot before iteration.  ConcurrentQueue is safe, but
            // the Phase 2 assessment explicitly calls out trailing Hopac writers;
            // using ToArray() gives the diagnostic sweep a stable view before we
            // perform bounded dequeues and structurally valid Ty writes.
            let limit = max 1 (min 4096 maxItems)
            let groundDefaultId = Phase2DeferredTypeVarGroundBoolSentinel
            let groundDefaultValue = phase2DeferredTypeVarGroundDefaultValue groundDefaultId
            let groundDefaultText = phase2DeferredTypeVarGroundDefaultValueText groundDefaultId
            let patchedNodes = System.Collections.Generic.HashSet<int>()
            let deferredSnapshot = deferredTypeVarCells.ToArray() |> Array.truncate limit
            let monoSnapshot = pendingMonomorphizationQueue.ToArray() |> Array.truncate limit
            let mutable deferredScanned = 0
            for (nodeId, priorReason) in deferredSnapshot do
                if patchedNodes.Add nodeId then
                    putTypeValue nodeId groundDefaultValue
                deferredScanned <- deferredScanned + 1
            let mutable deferredDiscard = Unchecked.defaultof<int * string>
            for _i = 1 to deferredScanned do
                deferredTypeVarCells.TryDequeue(&deferredDiscard) |> ignore
            let mutable monoScanned = 0
            for monoItem in monoSnapshot do
                let mutable removed = 0uy
                pendingMonomorphizationSeen.TryRemove(monoItem.nodeId, &removed) |> ignore
                if patchedNodes.Add monoItem.nodeId then
                    putTypeValue monoItem.nodeId groundDefaultValue
                monoScanned <- monoScanned + 1
            let mutable monoDiscard = Unchecked.defaultof<PendingMonomorphizationEntry>
            for _i = 1 to monoScanned do
                pendingMonomorphizationQueue.TryDequeue(&monoDiscard) |> ignore
            let patched = patchedNodes.Count
            let decisionId =
                if patched > 0 then Phase2DeferredTypeVarSweepPatched
                else Phase2DeferredTypeVarSweepNoop
            DiagJson.emit (
                sprintf "{\"kind\":\"eval_worklist_phase2_deferred_type_var_synchronous_sweep\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"ground_default_du\":%s,\"ground_default_structural_du\":\"valid_ty_no_null_ast\",\"patched_holes\":%d,\"holes_patched_total\":%d,\"deferred_cells_scanned\":%d,\"pending_monomorphization_scanned\":%d,\"remaining_deferred_type_var_queue\":%d,\"pending_monomorphization_queue\":%d,\"mono_queue_depth\":%d,\"default_ty\":%s,\"policy\":\"alpha1307_snapshot_sweep_uses_structurally_valid_ty_sentinel_no_raw_null_no_buildok\",\"single_flight\":1,\"next\":\"bridge_parent_continuation_root_witness\"}"
                    (DiagJson.esc event)
                    (DiagJson.esc reason)
                    (DiagJson.esc (phase2DeferredTypeVarSweepDecisionText decisionId))
                    (DiagJson.esc (phase2DeferredTypeVarGroundDefaultText groundDefaultId))
                    patched
                    patched
                    deferredScanned
                    monoScanned
                    (deferredTypeVarQueueDepth())
                    (pendingMonomorphizationQueueDepth())
                    (pendingMonomorphizationQueueDepth())
                    (DiagJson.esc groundDefaultText))
            patched

        let tryPhase2PairDeferredChildSweep (event: string) (reason: string) (maxItems: int) : int =
            let limit = max 1 (min 4096 maxItems)
            let snapshot = deferredReplayCells.ToArray() |> Array.truncate limit
            let pairCells =
                snapshot
                |> Array.filter (fun cell ->
                    cell.kind = "term"
                    && (cell.shape = "EPair"
                        || cell.shape = "EApply"
                        || cell.site.IndexOf("pair_left", StringComparison.OrdinalIgnoreCase) >= 0
                        || cell.site.IndexOf("pair_right", StringComparison.OrdinalIgnoreCase) >= 0
                        || cell.site.IndexOf("apply_arg_0", StringComparison.OrdinalIgnoreCase) >= 0))
            let decisionId =
                if pairCells.Length > 0 then Phase2PairDeferredChildSweepConsidered
                else Phase2PairDeferredChildSweepNoop
            let sample =
                pairCells
                |> Array.truncate 6
                |> Array.map (fun cell -> sprintf "%s:%s#%d@%s" cell.kind cell.shape cell.nodeId cell.site)
                |> String.concat ";"
            DiagJson.emit (
                sprintf "{\"kind\":\"eval_worklist_phase2_pair_deferred_child_sweep\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"pair_deferred_children_considered\":%d,\"sample\":%s,\"deferred_replay_snapshot\":%d,\"policy\":\"alpha1307_pair_shape_phase2_sweep_observes_deferred_children_before_fail_closed_handoff_no_value_fabricated\",\"single_flight\":1,\"next\":\"pair_value_exception_handoff_or_replay_drain\"}"
                    (DiagJson.esc event)
                    (DiagJson.esc reason)
                    (DiagJson.esc (phase2PairDeferredChildSweepDecisionText decisionId))
                    pairCells.Length
                    (DiagJson.esc sample)
                    snapshot.Length)
            pairCells.Length

        let putDeferredReplayCell (cell: DeferredReplayCell) : unit =
            let key = sprintf "%s|%s|%d|%d" cell.kind cell.shape cell.nodeId cell.step
            lock deferredReplayGate (fun () ->
                if deferredReplaySeenKeys.TryAdd(key, 1uy) then
                    deferredReplayCells.Enqueue cell)

        let hasDeferredReplayCell () : bool =
            lock deferredReplayGate (fun () -> not deferredReplayCells.IsEmpty)

        // ALPHA1056: root-complete write-witness finalization may quarantine a
        // stale retarget cell, but leaving that cell in the deferred replay queue
        // keeps hasDeferredReplayCell() true and reopens the same pending=2 loop.
        // Provide a bounded predicate drain so finalization can remove only the
        // stale cell it just proved obsolete; other runnable replay obligations stay queued.
        let dropDeferredReplayCells (predicate: DeferredReplayCell -> bool) : int =
            lock deferredReplayGate (fun () ->
                let kept = ResizeArray<DeferredReplayCell>()
                let mutable dropped = 0
                let mutable item = Unchecked.defaultof<DeferredReplayCell>
                while deferredReplayCells.TryDequeue(&item) do
                    if predicate item then dropped <- dropped + 1
                    else kept.Add item
                for x in kept do deferredReplayCells.Enqueue x
                dropped)

        let tryTakeDeferredReplayCell (kind: string) (preferredShape: string) (excludeNodeId: int) : DeferredReplayCell option =
            lock deferredReplayGate (fun () ->
                let kept = ResizeArray<DeferredReplayCell>()
                let mutable first = Unchecked.defaultof<DeferredReplayCell>
                let mutable preferred = Unchecked.defaultof<DeferredReplayCell>
                let mutable haveFirst = false
                let mutable havePreferred = false
                let mutable item = Unchecked.defaultof<DeferredReplayCell>
                while deferredReplayCells.TryDequeue(&item) do
                    if item.kind = kind && item.nodeId <> excludeNodeId then
                        if (not havePreferred) && item.shape = preferredShape then
                            preferred <- item
                            havePreferred <- true
                        elif not haveFirst then
                            first <- item
                            haveFirst <- true
                        else
                            kept.Add item
                    else
                        kept.Add item
                let chosen =
                    if havePreferred then Some preferred
                    elif haveFirst then Some first
                    else None
                match chosen with
                | Some chosenCell ->
                    for x in kept do deferredReplayCells.Enqueue x
                    chosen
                | None ->
                    for x in kept do deferredReplayCells.Enqueue x
                    None)

        let putApplySpine (nodeId: int) (spine: ApplySpine) : unit =
            applySpines.[nodeId] <- spine
            putParentContinuation spine.headNodeId { parentKind = "term"; parentShape = "EApply"; parentNodeId = nodeId; role = "apply_head" }
            spine.argNodeIds
            |> Array.iteri (fun i argNodeId ->
                putParentContinuation argNodeId { parentKind = "term"; parentShape = "EApply"; parentNodeId = nodeId; role = sprintf "apply_arg_%d" i })

        let putTypeApplySpine (nodeId: int) (spine: TypeApplySpine) : unit =
            typeApplySpines.[nodeId] <- spine
            putParentContinuation spine.funcNodeId { parentKind = "term"; parentShape = "ETypeApply"; parentNodeId = nodeId; role = "type_apply_function" }
            putParentContinuation spine.typeNodeId { parentKind = "term"; parentShape = "ETypeApply"; parentNodeId = nodeId; role = "type_apply_type_arg" }

        let putTypeTermSpine (nodeId: int) (spine: TypeTermSpine) : unit =
            typeTermSpines.[nodeId] <- spine
            putParentContinuation spine.termNodeId { parentKind = "ty"; parentShape = "TTerm"; parentNodeId = nodeId; role = "tterm_term_child" }

        let putTypeJoinPointSpine (nodeId: int) (spine: TypeJoinPointSpine) : unit =
            typeJoinPointSpines.[nodeId] <- spine
            putParentContinuation spine.bodyNodeId { parentKind = "ty"; parentShape = "TJoinPoint'"; parentNodeId = nodeId; role = "tjoinpoint_body_child" }

        let putTypeFunSpine (nodeId: int) (spine: TypeFunSpine) : unit =
            typeFunSpines.[nodeId] <- spine
            putParentContinuation spine.argNodeId { parentKind = "ty"; parentShape = "TFun"; parentNodeId = nodeId; role = "tfun_arg_child" }
            putParentContinuation spine.bodyNodeId { parentKind = "ty"; parentShape = "TFun"; parentNodeId = nodeId; role = "tfun_body_child" }

        let putTypePairSpine (nodeId: int) (spine: TypePairSpine) : unit =
            typePairSpines.[nodeId] <- spine
            putParentContinuation spine.leftNodeId { parentKind = "ty"; parentShape = "TPair"; parentNodeId = nodeId; role = "tpair_left_child" }
            putParentContinuation spine.rightNodeId { parentKind = "ty"; parentShape = "TPair"; parentNodeId = nodeId; role = "tpair_right_child" }

        let putIfThenElse (nodeId: int) (spine: IfThenElseSpine) : unit =
            ifThenElseSpines.[nodeId] <- spine
            putParentContinuation spine.condNodeId { parentKind = "term"; parentShape = "EIfThenElse"; parentNodeId = nodeId; role = "if_condition" }
            putParentContinuation spine.trueNodeId { parentKind = "term"; parentShape = "EIfThenElse"; parentNodeId = nodeId; role = "if_true" }
            putParentContinuation spine.falseNodeId { parentKind = "term"; parentShape = "EIfThenElse"; parentNodeId = nodeId; role = "if_false" }

        let putAnnotTestSpine (nodeId: int) (spine: AnnotTestSpine) : unit =
            annotTestSpines.[nodeId] <- spine
            putParentContinuation spine.typeNodeId { parentKind = "term"; parentShape = "EAnnotTest"; parentNodeId = nodeId; role = "annot_test_type" }
            putParentContinuation spine.trueNodeId { parentKind = "term"; parentShape = "EAnnotTest"; parentNodeId = nodeId; role = "annot_test_true" }
            putParentContinuation spine.falseNodeId { parentKind = "term"; parentShape = "EAnnotTest"; parentNodeId = nodeId; role = "annot_test_false" }

        let putAnnotSpine (nodeId: int) (spine: AnnotSpine) : unit =
            annotSpines.[nodeId] <- spine
            putParentContinuation spine.innerNodeId { parentKind = "term"; parentShape = "EAnnot"; parentNodeId = nodeId; role = "annot_inner" }
            putParentContinuation spine.typeNodeId { parentKind = "term"; parentShape = "EAnnot"; parentNodeId = nodeId; role = "annot_type" }

        let putUnitTestSpine (nodeId: int) (spine: UnitTestSpine) : unit =
            unitTestSpines.[nodeId] <- spine
            // ALPHA936: the discriminator is an Id-backed term value thunk, but it
            // still participates in parent continuation replay under EUnitTest.
            putParentContinuation spine.bindNodeId { parentKind = "term"; parentShape = "EUnitTest"; parentNodeId = nodeId; role = "unit_test_bind" }
            putParentContinuation spine.successNodeId { parentKind = "term"; parentShape = "EUnitTest"; parentNodeId = nodeId; role = "unit_test_success" }
            putParentContinuation spine.failNodeId { parentKind = "term"; parentShape = "EUnitTest"; parentNodeId = nodeId; role = "unit_test_fail" }

        let putPairTestSpine (nodeId: int) (spine: PairTestSpine) : unit =
            pairTestSpines.[nodeId] <- spine
            putParentContinuation spine.successNodeId { parentKind = "term"; parentShape = "EPairTest"; parentNodeId = nodeId; role = "pair_test_success" }
            putParentContinuation spine.failNodeId { parentKind = "term"; parentShape = "EPairTest"; parentNodeId = nodeId; role = "pair_test_fail" }

        let putUnboxSpine (nodeId: int) (spine: UnboxSpine) : unit =
            unboxSpines.[nodeId] <- spine
            putParentContinuation spine.bindNodeId { parentKind = "term"; parentShape = "EUnbox"; parentNodeId = nodeId; role = "unbox_bind" }
            putParentContinuation spine.successNodeId { parentKind = "term"; parentShape = "EUnbox"; parentNodeId = nodeId; role = "unbox_success" }
            putParentContinuation spine.failNodeId { parentKind = "term"; parentShape = "EUnbox"; parentNodeId = nodeId; role = "unbox_fail" }

        let putOpSpine (nodeId: int) (spine: OpSpine) : unit =
            opSpines.[nodeId] <- spine
            spine.argNodeIds
            |> Array.iteri (fun i argNodeId ->
                putParentContinuation argNodeId { parentKind = "term"; parentShape = "EOp"; parentNodeId = nodeId; role = sprintf "op_arg_%d" i })

        let putSeqSpine (nodeId: int) (spine: SeqSpine) : unit =
            seqSpines.[nodeId] <- spine
            putParentContinuation spine.firstNodeId { parentKind = "term"; parentShape = "ESeq"; parentNodeId = nodeId; role = "seq_first" }
            putParentContinuation spine.secondNodeId { parentKind = "term"; parentShape = "ESeq"; parentNodeId = nodeId; role = "seq_second" }

        let putNominalSpine (nodeId: int) (spine: NominalSpine) : unit =
            nominalSpines.[nodeId] <- spine
            putParentContinuation spine.innerNodeId { parentKind = "term"; parentShape = "ENominal"; parentNodeId = nodeId; role = "nominal_inner" }
            putParentContinuation spine.typeNodeId { parentKind = "term"; parentShape = "ENominal"; parentNodeId = nodeId; role = "nominal_type" }

        let putTermPairSpine (nodeId: int) (spine: TermPairSpine) : unit =
            termPairSpines.[nodeId] <- spine
            putParentContinuation spine.leftNodeId { parentKind = "term"; parentShape = "EPair"; parentNodeId = nodeId; role = "pair_left" }
            putParentContinuation spine.rightNodeId { parentKind = "term"; parentShape = "EPair"; parentNodeId = nodeId; role = "pair_right" }

        let putLetSpine (nodeId: int) (spine: LetSpine) : unit =
            letSpines.[nodeId] <- spine
            spine.bodyNodeIds
            |> Array.iteri (fun i bodyNodeId ->
                putParentContinuation bodyNodeId { parentKind = "term"; parentShape = "ELet"; parentNodeId = nodeId; role = sprintf "let_body_%d" i })
            putParentContinuation spine.successNodeId { parentKind = "term"; parentShape = "ELet"; parentNodeId = nodeId; role = "let_success" }

        let putRecordWithSpine (nodeId: int) (spine: RecordWithSpine) : unit =
            recordWithSpines.[nodeId] <- spine
            spine.childNodeIds
            |> Array.iteri (fun i childNodeId ->
                let role = if i < spine.childRoles.Length then spine.childRoles.[i] else sprintf "record_with_child_%d" i
                putParentContinuation childNodeId { parentKind = "term"; parentShape = "ERecordWith"; parentNodeId = nodeId; role = role })

        let putMacroSpine (nodeId: int) (spine: MacroSpine) : unit =
            macroSpines.[nodeId] <- spine
            spine.termNodeIds
            |> Array.iteri (fun i childNodeId ->
                putParentContinuation childNodeId { parentKind = "term"; parentShape = "EMacro"; parentNodeId = nodeId; role = sprintf "macro_term_%d" i })
            spine.typeNodeIds
            |> Array.iteri (fun i childNodeId ->
                putParentContinuation childNodeId { parentKind = "term"; parentShape = "EMacro"; parentNodeId = nodeId; role = sprintf "macro_type_%d" i })
            if spine.resultTypeNodeId <> 0 then
                putParentContinuation spine.resultTypeNodeId { parentKind = "term"; parentShape = "EMacro"; parentNodeId = nodeId; role = "macro_result_type" }

        let tryTermDetailed (nodeId: int) : Choice<Data,string> =
            let mutable thunk = Unchecked.defaultof<unit -> Data>
            if termValues.TryGetValue(nodeId, &thunk) then
                try
                    let value = thunk()
                    termReady.[nodeId] <- 1uy
                    let mutable oldTermTrace = ""
                    let mutable oldTermType = ""
                    termExceptionTraces.TryRemove(nodeId, &oldTermTrace) |> ignore
                    termExceptionTypes.TryRemove(nodeId, &oldTermType) |> ignore
                    Choice1Of2 value
                with ex ->
                    termExceptionTraces.[nodeId] <- compactExnTrace ex
                    termExceptionTypes.[nodeId] <- compactExnType ex
                    Choice2Of2 (compactExn ex)
            else Choice2Of2 "term_thunk_missing"

        let tryTermExceptionTrace (nodeId: int) : string option =
            let mutable trace = ""
            if termExceptionTraces.TryGetValue(nodeId, &trace) then Some trace else None

        let tryTermExceptionType (nodeId: int) : string option =
            let mutable typ = ""
            if termExceptionTypes.TryGetValue(nodeId, &typ) then Some typ else None

        let tryTerm (nodeId: int) : Data option =
            match tryTermDetailed nodeId with
            | Choice1Of2 value -> Some value
            | Choice2Of2 _ -> None

        let tryTypeApplyBodyValueAt (parentNodeId: int) : Data option =
            let mutable bodyNodeId = 0
            if typeApplyBodyNodes.TryGetValue(parentNodeId, &bodyNodeId) then
                tryTerm bodyNodeId
            else None

        let tryTypeDetailed (nodeId: int) : Choice<Ty,string> =
            let mutable thunk = Unchecked.defaultof<unit -> Ty>
            if typeValues.TryGetValue(nodeId, &thunk) then
                try
                    let value = thunk()
                    let mutable oldTypeTrace = ""
                    let mutable oldTypeType = ""
                    typeExceptionTraces.TryRemove(nodeId, &oldTypeTrace) |> ignore
                    typeExceptionTypes.TryRemove(nodeId, &oldTypeType) |> ignore
                    Choice1Of2 value
                with ex ->
                    typeExceptionTraces.[nodeId] <- compactExnTrace ex
                    typeExceptionTypes.[nodeId] <- compactExnType ex
                    Choice2Of2 (compactExn ex)
            else Choice2Of2 "type_thunk_missing"

        let tryTypeExceptionTrace (nodeId: int) : string option =
            let mutable trace = ""
            if typeExceptionTraces.TryGetValue(nodeId, &trace) then Some trace else None

        let tryTypeExceptionType (nodeId: int) : string option =
            let mutable typ = ""
            if typeExceptionTypes.TryGetValue(nodeId, &typ) then Some typ else None

        let tryType (nodeId: int) : Ty option =
            match tryTypeDetailed nodeId with
            | Choice1Of2 value -> Some value
            | Choice2Of2 _ -> None

        let tryApplySpine (nodeId: int) : ApplySpine option =
            let mutable spine = Unchecked.defaultof<ApplySpine>
            if applySpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTypeApplySpine (nodeId: int) : TypeApplySpine option =
            let mutable spine = Unchecked.defaultof<TypeApplySpine>
            if typeApplySpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTypeTermSpine (nodeId: int) : TypeTermSpine option =
            let mutable spine = Unchecked.defaultof<TypeTermSpine>
            if typeTermSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTypeJoinPointSpine (nodeId: int) : TypeJoinPointSpine option =
            let mutable spine = Unchecked.defaultof<TypeJoinPointSpine>
            if typeJoinPointSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTypeFunSpine (nodeId: int) : TypeFunSpine option =
            let mutable spine = Unchecked.defaultof<TypeFunSpine>
            if typeFunSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTypePairSpine (nodeId: int) : TypePairSpine option =
            let mutable spine = Unchecked.defaultof<TypePairSpine>
            if typePairSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryIfThenElse (nodeId: int) : IfThenElseSpine option =
            let mutable spine = Unchecked.defaultof<IfThenElseSpine>
            if ifThenElseSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryAnnotTestSpine (nodeId: int) : AnnotTestSpine option =
            let mutable spine = Unchecked.defaultof<AnnotTestSpine>
            if annotTestSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryAnnotSpine (nodeId: int) : AnnotSpine option =
            let mutable spine = Unchecked.defaultof<AnnotSpine>
            if annotSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryUnitTestSpine (nodeId: int) : UnitTestSpine option =
            let mutable spine = Unchecked.defaultof<UnitTestSpine>
            if unitTestSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryPairTestSpine (nodeId: int) : PairTestSpine option =
            let mutable spine = Unchecked.defaultof<PairTestSpine>
            if pairTestSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryUnboxSpine (nodeId: int) : UnboxSpine option =
            let mutable spine = Unchecked.defaultof<UnboxSpine>
            if unboxSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryOpSpine (nodeId: int) : OpSpine option =
            let mutable spine = Unchecked.defaultof<OpSpine>
            if opSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let trySeqSpine (nodeId: int) : SeqSpine option =
            let mutable spine = Unchecked.defaultof<SeqSpine>
            if seqSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryNominalSpine (nodeId: int) : NominalSpine option =
            let mutable spine = Unchecked.defaultof<NominalSpine>
            if nominalSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryTermPairSpine (nodeId: int) : TermPairSpine option =
            let mutable spine = Unchecked.defaultof<TermPairSpine>
            if termPairSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryLetSpine (nodeId: int) : LetSpine option =
            let mutable spine = Unchecked.defaultof<LetSpine>
            if letSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryRecordWithSpine (nodeId: int) : RecordWithSpine option =
            let mutable spine = Unchecked.defaultof<RecordWithSpine>
            if recordWithSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let tryMacroSpine (nodeId: int) : MacroSpine option =
            let mutable spine = Unchecked.defaultof<MacroSpine>
            if macroSpines.TryGetValue(nodeId, &spine) then Some spine else None

        let hasTerm (nodeId: int) : bool =
            termValues.ContainsKey nodeId

        // ALPHA436: a registered thunk is not necessarily a resolved value.
        // Alpha435 still reported RecordMap/2 as args_available because hasTerm only
        // checked dictionary presence; replay thunks can fail closed while the child
        // still needs an explicit worklist step.  Use this when choosing whether to
        // schedule an op argument before declaring the op implementation missing.
        let tryTermReady (nodeId: int) : bool =
            match tryTermDetailed nodeId with
            | Choice1Of2 _ -> true
            | Choice2Of2 _ -> false

        let tryTypeReady (nodeId: int) : bool =
            match tryTypeDetailed nodeId with
            | Choice1Of2 _ -> true
            | Choice2Of2 _ -> false

        let hasTermValue (nodeId: int) : bool =
            termReady.ContainsKey nodeId

        let hasType (nodeId: int) : bool =
            typeValues.ContainsKey nodeId

        let hasApplySpine (nodeId: int) : bool =
            applySpines.ContainsKey nodeId

        let hasTypeApplySpine (nodeId: int) : bool =
            typeApplySpines.ContainsKey nodeId

        let hasTypeTermSpine (nodeId: int) : bool =
            typeTermSpines.ContainsKey nodeId

        let hasTypeFunSpine (nodeId: int) : bool =
            typeFunSpines.ContainsKey nodeId

        let hasIfThenElse (nodeId: int) : bool =
            ifThenElseSpines.ContainsKey nodeId

        let hasOpSpine (nodeId: int) : bool =
            opSpines.ContainsKey nodeId

        let private normalizeSymbol (sym: string) =
            let sym = sym.Trim()
            let sym = sym.Trim([|'`'; '"'; ' '|])
            sym.TrimStart('.')

        let private isJpPlaceholderSymbol (sym: string) =
            let sym = normalizeSymbol sym
            sym.Contains("JPMethodRecPlaceholder(")

        let rec private isReplayVarLike (d: Data) =
            match d with
            | DV _ -> true
            | DNominal(d, _) -> isReplayVarLike d
            | DUnion(d, _) -> isReplayVarLike d
            | DPair(a,b) -> isReplayVarLike a || isReplayVarLike b
            // ALPHA414: records can be dynamic carriers too.  Alpha413 exposed
            // function_body_stepper_failed@arg0/DRecord; before forcing the real
            // function body, inspect record fields for replay-var-like payloads.
            | DRecord m -> m |> Map.exists (fun _ v -> isReplayVarLike v)
            | DSymbol _ -> true
            | DTLit (LitString sym) when isJpPlaceholderSymbol sym -> true
            | DLit (LitString sym) when isJpPlaceholderSymbol sym -> true
            | _ -> false

        let private opCaseName (opName: string) =
            let s = normalizeSymbol opName
            let i = s.LastIndexOf('.')
            if i >= 0 && i + 1 < s.Length then s.Substring(i + 1) else s

        let private boolData x = DLit (LitBool x)

        // ALPHA368: first arithmetic replay leaf for the observed Add/2 frontier.
        // Keep this conservative: only exact literal addition and additive identity rewrites
        // are replay-complete. Symbolic numeric Add still stays partial until residual-op
        // construction is available, so the writer remains fail-closed.
        let private tryAddLiteral a b =
            match a, b with
            | LitInt8 a, LitInt8 b -> Some (DLit (LitInt8 (a + b)))
            | LitInt16 a, LitInt16 b -> Some (DLit (LitInt16 (a + b)))
            | LitInt32 a, LitInt32 b -> Some (DLit (LitInt32 (a + b)))
            | LitInt64 a, LitInt64 b -> Some (DLit (LitInt64 (a + b)))
            | LitUInt8 a, LitUInt8 b -> Some (DLit (LitUInt8 (a + b)))
            | LitUInt16 a, LitUInt16 b -> Some (DLit (LitUInt16 (a + b)))
            | LitUInt32 a, LitUInt32 b -> Some (DLit (LitUInt32 (a + b)))
            | LitUInt64 a, LitUInt64 b -> Some (DLit (LitUInt64 (a + b)))
            | LitFloat32 a, LitFloat32 b -> Some (DLit (LitFloat32 (a + b)))
            | LitFloat64 a, LitFloat64 b -> Some (DLit (LitFloat64 (a + b)))
            | _ -> None

        // ALPHA496: the alpha495 runtime exposed EOp/Sub/2 with both
        // arguments already available, but replay treated it as an
        // unimplemented pure op.  Keep this deliberately narrow:
        // exact same-literal subtraction and the x-0 identity only.
        let private trySubLiteral a b =
            match a, b with
            | LitInt8 a, LitInt8 b -> Some (DLit (LitInt8 (a - b)))
            | LitInt16 a, LitInt16 b -> Some (DLit (LitInt16 (a - b)))
            | LitInt32 a, LitInt32 b -> Some (DLit (LitInt32 (a - b)))
            | LitInt64 a, LitInt64 b -> Some (DLit (LitInt64 (a - b)))
            | LitUInt8 a, LitUInt8 b -> Some (DLit (LitUInt8 (a - b)))
            | LitUInt16 a, LitUInt16 b -> Some (DLit (LitUInt16 (a - b)))
            | LitUInt32 a, LitUInt32 b -> Some (DLit (LitUInt32 (a - b)))
            | LitUInt64 a, LitUInt64 b -> Some (DLit (LitUInt64 (a - b)))
            | LitFloat32 a, LitFloat32 b -> Some (DLit (LitFloat32 (a - b)))
            | LitFloat64 a, LitFloat64 b -> Some (DLit (LitFloat64 (a - b)))
            | _ -> None

        // ALPHA381: resolve exact literal comparisons in the explicit term worklist.
        // The 380 runtime frontier reached EOp/GTE/2 with both args available, so
        // these cases are intentionally pure, same-type, and fail-closed for mixed or
        // symbolic operands.  This keeps residual construction out of the writer path.
        let private tryCompareLiteral (opName: string) a b =
            let out x = Some (boolData x)
            match opName, a, b with
            | "EQ", a, b -> out (a = b)
            | "NEQ", a, b -> out (a <> b)
            | "LT", LitInt8 a, LitInt8 b -> out (a < b)
            | "LTE", LitInt8 a, LitInt8 b -> out (a <= b)
            | "GT", LitInt8 a, LitInt8 b -> out (a > b)
            | "GTE", LitInt8 a, LitInt8 b -> out (a >= b)
            | "LT", LitInt16 a, LitInt16 b -> out (a < b)
            | "LTE", LitInt16 a, LitInt16 b -> out (a <= b)
            | "GT", LitInt16 a, LitInt16 b -> out (a > b)
            | "GTE", LitInt16 a, LitInt16 b -> out (a >= b)
            | "LT", LitInt32 a, LitInt32 b -> out (a < b)
            | "LTE", LitInt32 a, LitInt32 b -> out (a <= b)
            | "GT", LitInt32 a, LitInt32 b -> out (a > b)
            | "GTE", LitInt32 a, LitInt32 b -> out (a >= b)
            | "LT", LitInt64 a, LitInt64 b -> out (a < b)
            | "LTE", LitInt64 a, LitInt64 b -> out (a <= b)
            | "GT", LitInt64 a, LitInt64 b -> out (a > b)
            | "GTE", LitInt64 a, LitInt64 b -> out (a >= b)
            | "LT", LitUInt8 a, LitUInt8 b -> out (a < b)
            | "LTE", LitUInt8 a, LitUInt8 b -> out (a <= b)
            | "GT", LitUInt8 a, LitUInt8 b -> out (a > b)
            | "GTE", LitUInt8 a, LitUInt8 b -> out (a >= b)
            | "LT", LitUInt16 a, LitUInt16 b -> out (a < b)
            | "LTE", LitUInt16 a, LitUInt16 b -> out (a <= b)
            | "GT", LitUInt16 a, LitUInt16 b -> out (a > b)
            | "GTE", LitUInt16 a, LitUInt16 b -> out (a >= b)
            | "LT", LitUInt32 a, LitUInt32 b -> out (a < b)
            | "LTE", LitUInt32 a, LitUInt32 b -> out (a <= b)
            | "GT", LitUInt32 a, LitUInt32 b -> out (a > b)
            | "GTE", LitUInt32 a, LitUInt32 b -> out (a >= b)
            | "LT", LitUInt64 a, LitUInt64 b -> out (a < b)
            | "LTE", LitUInt64 a, LitUInt64 b -> out (a <= b)
            | "GT", LitUInt64 a, LitUInt64 b -> out (a > b)
            | "GTE", LitUInt64 a, LitUInt64 b -> out (a >= b)
            | "LT", LitFloat32 a, LitFloat32 b -> out (a < b)
            | "LTE", LitFloat32 a, LitFloat32 b -> out (a <= b)
            | "GT", LitFloat32 a, LitFloat32 b -> out (a > b)
            | "GTE", LitFloat32 a, LitFloat32 b -> out (a >= b)
            | "LT", LitFloat64 a, LitFloat64 b -> out (a < b)
            | "LTE", LitFloat64 a, LitFloat64 b -> out (a <= b)
            | "GT", LitFloat64 a, LitFloat64 b -> out (a > b)
            | "GTE", LitFloat64 a, LitFloat64 b -> out (a >= b)
            | "LT", LitChar a, LitChar b -> out (a < b)
            | "LTE", LitChar a, LitChar b -> out (a <= b)
            | "GT", LitChar a, LitChar b -> out (a > b)
            | "GTE", LitChar a, LitChar b -> out (a >= b)
            | "LT", LitString a, LitString b -> out (a < b)
            | "LTE", LitString a, LitString b -> out (a <= b)
            | "GT", LitString a, LitString b -> out (a > b)
            | "GTE", LitString a, LitString b -> out (a >= b)
            | "LT", LitBool a, LitBool b -> out (a < b)
            | "LTE", LitBool a, LitBool b -> out (a <= b)
            | "GT", LitBool a, LitBool b -> out (a > b)
            | "GTE", LitBool a, LitBool b -> out (a >= b)
            | _ -> None

        let private isZeroLiteral = function
            | LitInt8 0y | LitInt16 0s | LitInt32 0 | LitInt64 0L -> true
            | LitUInt8 0uy | LitUInt16 0us | LitUInt32 0u | LitUInt64 0UL -> true
            | LitFloat32 0.0f | LitFloat64 0.0 -> true
            | _ -> false

        let rec private isZeroData = function
            | DNominal(d, _) -> isZeroData d
            | DLit lit -> isZeroLiteral lit
            | _ -> false

        let private isPrimLike = function
            | DLit _ -> true
            | DV(L(_,YPrim _)) -> true
            | DNominal(d, _) ->
                match d with
                | DLit _ -> true
                | DV(L(_,YPrim _)) -> true
                | _ -> false
            | _ -> false

        let private isUnionLike = function
            | DUnion _ -> true
            | DV(L(_,YUnion _)) -> true
            | DNominal(DV(L(_,YUnion _)), _) -> true
            | DNominal(DUnion _, _) -> true
            | _ -> false

        let private isHeapUnionLike = function
            | DUnion(_,u) ->
                match u.Item.layout with
                | UHeap -> true
                | UStack -> false
            | DV(L(_,YUnion u)) ->
                match u.Item.layout with
                | UHeap -> true
                | UStack -> false
            | DNominal(DV(L(_,YUnion u)), _) | DNominal(DUnion(_,u), _) ->
                match u.Item.layout with
                | UHeap -> true
                | UStack -> false
            | _ -> false

        let private isLayoutLike = function
            | DV(L(_,YLayout _)) -> true
            | _ -> false

        let private isNominalLike = function
            | DNominal _ -> true
            | _ -> false

        let private isFunctionLike = function
            | DFunction _ -> true
            | DV(L(_,YFun _)) -> true
            | _ -> false

        let private isExistsLike = function
            | DExists _ -> true
            | _ -> false

        // ALPHA375: conservative replay-side application.
        //
        // Alpha374 proved root type completion and exposed the next real frontier:
        // EApply with head and args already available.  Do not call the recursive
        // evaluator from here; only reduce inert data applications that are
        // semantically local.  Stateful cases return a named reason so the next
        // frontier is precise instead of the old opaque "args_available_unimplemented".
        let rec private dataCaseName = function
            | DB -> "DB"
            | DSymbol _ -> "DSymbol"
            | DTLit _ -> "DTLit"
            | DPair _ -> "DPair"
            | DFunction _ -> "DFunction"
            | DForall _ -> "DForall"
            | DExists _ -> "DExists"
            | DRecord _ -> "DRecord"
            | DLit _ -> "DLit"
            | DUnion _ -> "DUnion"
            | DNominal(d, _) -> "DNominal/" + dataCaseName d
            | DV _ -> "DV"
            | DHashSet _ -> "DHashSet"
            | DHashMap _ -> "DHashMap"

        let rec private unwrapNominalData = function
            | DNominal(d, _) -> unwrapNominalData d
            | x -> x

        // ALPHA658: concrete structural equality for replay-side EQ/NEQ.
        // Runtime 657 moved past the macro stale pin and exposed EOp/EQ with both
        // arguments ready at real_core.spir:210.  Literal-only compare was too narrow,
        // while blanket Data equality would be unsafe for dynamic vars/functions/unions.
        // Keep this leaf deliberately fail-closed: only inert, fully concrete Data
        // families are compared here; everything else falls through to the existing
        // type-aware op bridge or the explicit op-impl terminal.
        let rec private tryReplayStructuralEqData (a: Data) (b: Data) : bool option =
            let pairwiseEq (xs: Data[]) (ys: Data[]) =
                if xs.Length <> ys.Length then Some false
                else
                    let mutable ok = true
                    let mutable known = true
                    let mutable i = 0
                    while known && ok && i < xs.Length do
                        match tryReplayStructuralEqData xs.[i] ys.[i] with
                        | Some true -> i <- i + 1
                        | Some false -> ok <- false
                        | None -> known <- false
                    if known then Some ok else None
            match a, b with
            | DB, DB -> Some true
            | DLit x, DLit y -> Some (x = y)
            | DTLit x, DTLit y -> Some (x = y)
            | DSymbol x, DSymbol y -> Some (x = y)
            | DUnion(x, ux), DUnion(y, uy) when ux = uy -> tryReplayStructuralEqData x y
            | DUnion _, DUnion _ -> None
            | DPair(a1,a2), DPair(b1,b2) ->
                match tryReplayStructuralEqData a1 b1, tryReplayStructuralEqData a2 b2 with
                | Some true, Some true -> Some true
                | Some false, _ | _, Some false -> Some false
                | _ -> None
            | DRecord xs, DRecord ys ->
                if xs.Count <> ys.Count then Some false
                else
                    let mutable ok = true
                    let mutable known = true
                    for KeyValue(k, xv) in xs do
                        if known && ok then
                            match Map.tryFind k ys with
                            | None -> ok <- false
                            | Some yv ->
                                match tryReplayStructuralEqData xv yv with
                                | Some true -> ()
                                | Some false -> ok <- false
                                | None -> known <- false
                    if known then Some ok else None
            | DNominal(x,_), DNominal(y,_) -> tryReplayStructuralEqData x y
            | DNominal(x,_), y -> tryReplayStructuralEqData x y
            | x, DNominal(y,_) -> tryReplayStructuralEqData x y
            | DFunction _, _ | _, DFunction _
            | DForall _, _ | _, DForall _
            | DExists _, _ | _, DExists _
            | DV _, _ | _, DV _
            | DUnion _, _ | _, DUnion _
            | DHashSet _, _ | _, DHashSet _
            | DHashMap _, _ | _, DHashMap _ -> None
            | _ -> Some false

        // ALPHA996: public, fail-closed equality witness for consumers outside
        // EvalReplayValueStore.  The implementation remains the existing inert
        // structural equality helper; dynamic cases still return None.
        let tryStructuralEqData (a: Data) (b: Data) : bool option =
            tryReplayStructuralEqData a b

        // ALPHA997: expose the inert data-case label used by the equality witness
        // without leaking the private implementation name outside this module.
        let dataCaseLabel (x: Data) : string =
            dataCaseName x

        let private dynamicFunctionBodyReason arg =
            if isReplayVarLike arg then Some ("function_body_dynamic_arg_join_required:" + dataCaseName arg)
            else None

        // ALPHA386: after alpha385, the first dynamic join placeholder became the
        // head of the remaining curried application and the replay fell through as
        // unsupported_head:DV@arg1/DNominal/DV.  A replay variable used as a head
        // with a replay-variable-like argument is a runtime dynamic call frontier,
        // not an invalid compile-time head.  Keep it fail-closed through the same
        // late-bound dynamic bridge used by DFunction + DNominal/DV.
        //
        // ALPHA482: alpha481 exposed a repeated semantic_dynamic_join_apply_blocked
        // child where the inner replay reached
        // runtime_function_apply_requires_dyn_typecheck@arg1/DFunction.  A dynamic
        // head applied to a function/record-like value is still a late-bound dynamic
        // join frontier; let runDynamicJoinApplyAfterDefinition try it instead of
        // returning the old generic dyn-typecheck blocker forever.
        //
        // ALPHA506: alpha505 narrowed the repeat to
        // runtime_function_apply_requires_dyn_typecheck@arg1/DB after a DV dynamic
        // join head had already consumed the first dynamic arg.  DB is still not a
        // fabricated value here; it is only permission to try the already-registered
        // dynamic-join continuation.  If the continuation cannot handle DB, the
        // existing semantic_dynamic_join_apply_blocked path remains fail-closed.
        //
        // ALPHA554: runtime 553 narrowed the dynamic-join repeat again:
        // function_body_dynamic_arg_join_required consumed arg0/DNominal/DV and
        // produced a conservative placeholder, but the very next application of that
        // placeholder to arg1/DLit was rejected as a generic dyn-typecheck blocker.
        // A literal tail is still part of the same late-bound dynamic call chain; route
        // DLit/DTLit through the existing dynamic-join bridge rather than pinning it.
        let private isDynamicApplyJoinArgument (arg: Data) =
            if isReplayVarLike arg then true
            else
                let caseName = dataCaseName arg
                caseName = "DB"
                || caseName = "DLit"
                || caseName = "DTLit"
                || caseName.IndexOf("DFunction", StringComparison.Ordinal) >= 0
                || caseName.IndexOf("DRecord", StringComparison.Ordinal) >= 0
                || caseName.IndexOf("DNominal", StringComparison.Ordinal) >= 0
                || caseName.IndexOf("DV", StringComparison.Ordinal) >= 0
                || caseName.IndexOf("DSymbol", StringComparison.Ordinal) >= 0

        let private isDynamicRuntimeUnionCarrier (arg: Data) =
            let caseName = dataCaseName arg
            caseName = "DUnion" || caseName = "DNominal/DUnion"

        let private isDynamicRuntimeUnionDynTypecheckDetail (arg: Data) (detail: string) =
            isDynamicRuntimeUnionCarrier arg
            && detail.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0

        type DynamicJoinRuntimeDynTypecheckCarrierDecisionId =
            | DynamicJoinRuntimeDynTypecheckReject
            | DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier
            | DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier
            | DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0

        let dynamicJoinRuntimeDynTypecheckCarrierDecisionText = function
            | DynamicJoinRuntimeDynTypecheckReject -> "reject_runtime_dyn_typecheck_carrier"
            | DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier -> "accept_runtime_union_carrier"
            | DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier -> "accept_symbolic_runtime_carrier"
            | DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0 -> "promote_dsymbol_arg0_to_dyn_typecheck_replay"

        let dynamicJoinRuntimeDynTypecheckCarrierDecisionPromotesReplay = function
            | DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier
            | DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier
            | DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0 -> true
            | DynamicJoinRuntimeDynTypecheckReject -> false

        let dynamicJoinSidecarErasedTargetTypeFromReason (reason: string) =
            if reason.IndexOf("runtime_function_apply_requires_dyn_typecheck@arg2/DPair", StringComparison.Ordinal) >= 0 then "arg2:DPair"
            elif reason.IndexOf("runtime_function_apply_requires_dyn_typecheck@arg1/DPair", StringComparison.Ordinal) >= 0 then "arg1:DPair"
            elif reason.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0 then "runtime_dyn_typecheck"
            else "unknown"

        let dynamicJoinRuntimeDynTypecheckCarrierDecisionForReason (reason: string) =
            let runtimeDynTypecheck =
                reason.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0
            let nestedFunctionBodyDSymbolArg0 =
                reason.IndexOf("function_body_dynamic_arg_join_required", StringComparison.Ordinal) >= 0
                && reason.IndexOf("DSymbol@arg0", StringComparison.Ordinal) >= 0
                && reason.IndexOf("runtime_function_apply_requires_dyn_typecheck@arg2/DPair", StringComparison.Ordinal) >= 0
            if nestedFunctionBodyDSymbolArg0 then
                DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0
            elif runtimeDynTypecheck
                 && (reason.IndexOf("DUnion", StringComparison.Ordinal) >= 0
                     || reason.IndexOf("DNominal/DUnion", StringComparison.Ordinal) >= 0) then
                DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier
            elif runtimeDynTypecheck
                 && (reason.IndexOf("DSymbol", StringComparison.Ordinal) >= 0
                     || reason.IndexOf("DPair", StringComparison.Ordinal) >= 0
                     || reason.IndexOf("DB", StringComparison.Ordinal) >= 0
                     || reason.IndexOf("DV", StringComparison.Ordinal) >= 0
                     || reason.IndexOf("DNominal", StringComparison.Ordinal) >= 0) then
                DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier
            else
                DynamicJoinRuntimeDynTypecheckReject

        let private dynamicJoinRuntimeDynTypecheckCarrierDecisionFor (arg: Data) (detail: string) =
            let argCase = dataCaseName arg
            let runtimeDynTypecheck =
                detail.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0
            if isDynamicRuntimeUnionDynTypecheckDetail arg detail then
                DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier
            elif runtimeDynTypecheck
                 && argCase = "DSymbol"
                 && detail.IndexOf("runtime_function_apply_requires_dyn_typecheck@arg2/DPair", StringComparison.Ordinal) >= 0 then
                DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0
            elif runtimeDynTypecheck
                 && (argCase = "DSymbol"
                     || argCase = "DPair"
                     || argCase = "DB"
                     || argCase.IndexOf("DV", StringComparison.Ordinal) >= 0
                     || argCase.IndexOf("DNominal", StringComparison.Ordinal) >= 0) then
                DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier
            else
                DynamicJoinRuntimeDynTypecheckReject

        let private dynamicRuntimeApplyReason head arg =
            if isReplayVarLike head && isDynamicApplyJoinArgument arg then
                Some ("runtime_dynamic_apply_join_required:" + dataCaseName head)
            else None

        let isDynamicJoinApplyReason (why: string) =
            why.StartsWith("function_body_dynamic_arg_join_required", StringComparison.Ordinal)
            || why.StartsWith("runtime_dynamic_apply_join_required", StringComparison.Ordinal)
            || why.StartsWith("runtime_record_dynamic_key_required", StringComparison.Ordinal)

        // ALPHA467/469: a DFunction body can still throw while forcing the concrete
        // body even though one argument is a dynamic carrier.  In that case the
        // correct replay frontier is not another body-child thunk; it is the existing
        // late-bound dynamic join bridge, which produces a conservative placeholder.
        let isFunctionBodyDynamicRecordFailure (why: string) =
            why.StartsWith("function_body_stepper_failed:", StringComparison.Ordinal)
            && why.IndexOf("@arg", StringComparison.Ordinal) >= 0
            && (why.IndexOf("/DRecord", StringComparison.Ordinal) >= 0
                || why.IndexOf("/DNominal", StringComparison.Ordinal) >= 0
                || why.IndexOf("/DV", StringComparison.Ordinal) >= 0
                || why.IndexOf("/DSymbol", StringComparison.Ordinal) >= 0)

        let isFunctionBodyDynamicFunctionFailure (why: string) =
            why.StartsWith("function_body_stepper_failed:", StringComparison.Ordinal)
            && why.IndexOf("@arg", StringComparison.Ordinal) >= 0
            && why.IndexOf("/DFunction", StringComparison.Ordinal) >= 0

        // ALPHA527: pure literal op bodies (real_core.spir comparisons / numeric guards)
        // are not dynamic join frontiers.  When a function body fails with @arg*/DLit
        // and the body child is EOp, surface the missing literal-op body stepper as a
        // terminal semantic contract instead of scheduling the same body indefinitely.
        let isFunctionBodyLiteralOpFailure (why: string) =
            why.StartsWith("function_body_stepper_failed:", StringComparison.Ordinal)
            && why.IndexOf("@arg", StringComparison.Ordinal) >= 0
            && why.IndexOf("/DLit", StringComparison.Ordinal) >= 0

        // ALPHA472: the outer record bridge already treats record-like dynamic
        // carriers as valid late-bound join candidates.  The inner multi-arg
        // dynamic join runner must mirror that policy; otherwise it retries the
        // concrete body, fails on @arg0/DRecord, and reports a blocked bridge
        // without ever giving runDynamicJoinApplyAfterDefinition the same chance.
        let private isFunctionBodyDynamicJoinFallbackDataCase (caseName: string) =
            caseName.IndexOf("DFunction", StringComparison.Ordinal) >= 0
            || caseName.IndexOf("DRecord", StringComparison.Ordinal) >= 0
            || caseName.IndexOf("DNominal", StringComparison.Ordinal) >= 0
            || caseName.IndexOf("DV", StringComparison.Ordinal) >= 0
            || caseName.IndexOf("DSymbol", StringComparison.Ordinal) >= 0

        let private tryApplyReplayOne (head0: Data) (arg: Data) : Choice<Data,string> =
            let head = unwrapNominalData head0
            match head, arg with
            | DRecord fields, DSymbol key ->
                match fields |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None) with
                | Some v -> Choice1Of2 v
                | None -> Choice2Of2 ("record_key_missing:" + key)
            | DRecord _, arg when isDynamicApplyJoinArgument arg ->
                Choice2Of2 ("runtime_record_dynamic_key_required:" + dataCaseName arg)
            | DV _, arg ->
                match dynamicRuntimeApplyReason head arg with
                | Some reason -> Choice2Of2 reason
                | None -> Choice2Of2 "runtime_function_apply_requires_dyn_typecheck"
            // ALPHA384: do not force a compile-time function body when the next arg is
            // a dynamic replay variable (the observed listm.spi:13 DNominal/DV case).
            // The real apply path currently throws PartEvalTypeError after trying to
            // destructure a symbolic list value.  Name the missing dynamic/join apply
            // stepper instead of spending a retry on a doomed body execution.
            | DFunction _, arg ->
                match dynamicFunctionBodyReason arg with
                | Some reason -> Choice2Of2 reason
                | None -> Choice2Of2 "function_body_stepper_required"
            | DForall _, _ -> Choice2Of2 "forall_term_apply"
            | head, _ -> Choice2Of2 ("unsupported_head:" + dataCaseName head)

        let private tryRunApplyAfterDefinitionAt (nodeId: int) (head: Data) (arg: Data) : Choice<Data,string> =
            match tryApplyContext nodeId with
            | Some sObj ->
                try Choice1Of2 (runApplyAfterDefinition sObj head arg)
                with ex -> Choice2Of2 ("function_body_stepper_failed:" + compactExn ex)
            | None -> Choice2Of2 "function_body_stepper_context_missing"

        let private tryRunDynamicJoinApplyAfterDefinitionAt (nodeId: int) (head: Data) (arg: Data) : Choice<Data,string> =
            match tryApplyContext nodeId with
            | Some sObj ->
                try Choice1Of2 (runDynamicJoinApplyAfterDefinition sObj head arg)
                with ex -> Choice2Of2 ("dynamic_join_apply_failed:" + compactExn ex)
            | None -> Choice2Of2 "dynamic_join_apply_context_missing"

        let tryRunTypeApplyAfterDefinitionAt (nodeId: int) (head: Data) (arg: Ty) : Choice<Data,string> =
            let contextOpt =
                match tryTypeApplyContext nodeId with
                | Some sObj -> Some sObj
                | None ->
                    match tryOpContext nodeId with
                    | Some sObj ->
                        // ALPHA1078: recover the missing type-apply bridge from the
                        // already-authoritative op context.  This only enables the
                        // existing runTypeApplyAfterDefinition path; it does not
                        // synthesize the result of the type application.
                        putTypeApplyContext nodeId sObj
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_type_apply_context_recovered_from_op_context\",\"node_id\":%d,\"single_flight\":1,\"next\":\"run_type_apply_after_definition\"}"
                                nodeId)
                        Some sObj
                    | None -> None
            match contextOpt with
            | Some sObj ->
                try Choice1Of2 (runTypeApplyAfterDefinition sObj head arg)
                with ex -> Choice2Of2 ("type_apply_forall_body_failed:" + compactExn ex)
            | None -> Choice2Of2 "type_apply_context_missing"

        let tryApplyReplayDataWithContext (nodeId: int) (head: Data) (args: Data[]) : Data option * string =
            let mutable current = head
            let mutable reason = ""
            let mutable ok = true
            let mutable i = 0
            while ok && i < args.Length do
                match tryApplyReplayOne current args.[i] with
                | Choice1Of2 next ->
                    current <- next
                    i <- i + 1
                | Choice2Of2 "function_body_stepper_required" ->
                    match tryRunApplyAfterDefinitionAt nodeId current args.[i] with
                    | Choice1Of2 next ->
                        current <- next
                        i <- i + 1
                    | Choice2Of2 why ->
                        reason <- sprintf "%s@arg%d/%s" why i (dataCaseName args.[i])
                        ok <- false
                | Choice2Of2 why ->
                    reason <- sprintf "%s@arg%d/%s" why i (dataCaseName args.[i])
                    ok <- false
            if ok then Some current, "ok"
            else None, reason

        let tryDynamicJoinApplyReplayDataWithContext (nodeId: int) (head: Data) (args: Data[]) : Choice<Data,string> =
            let mutable current = head
            let mutable result = Choice1Of2 head
            let mutable ok = true
            let mutable i = 0
            while ok && i < args.Length do
                match tryApplyReplayOne current args.[i] with
                | Choice1Of2 next ->
                    current <- next
                    i <- i + 1
                | Choice2Of2 why when isDynamicJoinApplyReason why ->
                    match tryRunDynamicJoinApplyAfterDefinitionAt nodeId current args.[i] with
                    | Choice1Of2 next ->
                        current <- next
                        i <- i + 1
                    | Choice2Of2 detail ->
                        let carrierDecisionId =
                            dynamicJoinRuntimeDynTypecheckCarrierDecisionFor args.[i] detail
                        let carrierDecisionText =
                            dynamicJoinRuntimeDynTypecheckCarrierDecisionText carrierDecisionId
                        match carrierDecisionId with
                        | DynamicJoinRuntimeDynTypecheckAcceptUnionCarrier ->
                            // ALPHA1322/1515: the concrete dynamic-join runner has already
                            // tried the body and only reported a runtime dyn-typecheck tail.
                            // For runtime carriers, keep the existing value as a symbolic
                            // result so parent replay can continue instead of pinning
                            // semantic_dynamic_join_apply_blocked at the first root window.
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_dynamic_join_union_symbolic_runtime_value_accepted\",\"event\":\"dynamic_join_apply\",\"node_id\":%d,\"arg_index\":%d,\"arg_case\":%s,\"detail\":%s,\"decision_du\":%s,\"policy\":\"runtime_union_carrier_survives_dyn_typecheck_no_buildok\",\"single_flight\":1,\"next\":\"resume_parent_after_dynamic_join_union_symbolic_value\"}"
                                    nodeId i (DiagJson.esc (dataCaseName args.[i])) (DiagJson.esc detail) (DiagJson.esc carrierDecisionText))
                            current <- args.[i]
                            i <- i + 1
                        | DynamicJoinRuntimeDynTypecheckAcceptSymbolicCarrier
                        | DynamicJoinRuntimeDynTypecheckPromoteNestedDSymbolArg0 ->
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_dynamic_join_symbolic_runtime_carrier_accepted\",\"event\":\"dynamic_join_apply\",\"node_id\":%d,\"arg_index\":%d,\"arg_case\":%s,\"detail\":%s,\"decision_du\":%s,\"source_reason\":%s,\"shadow_alt_timeout_arbitration_outcome_du\":\"promote_carrier_to_replay\",\"policy\":\"symbolic_carrier_survives_runtime_dyn_typecheck_no_buildok\",\"single_flight\":1,\"next\":\"resume_parent_after_symbolic_dynamic_join_carrier\"}"
                                    nodeId i (DiagJson.esc (dataCaseName args.[i])) (DiagJson.esc detail) (DiagJson.esc carrierDecisionText) (DiagJson.esc why))
                            current <- args.[i]
                            i <- i + 1
                        | DynamicJoinRuntimeDynTypecheckReject ->
                            result <- Choice2Of2 (sprintf "%s@arg%d/%s:%s" why i (dataCaseName args.[i]) detail)
                            ok <- false
                | Choice2Of2 "function_body_stepper_required" ->
                    match tryRunApplyAfterDefinitionAt nodeId current args.[i] with
                    | Choice1Of2 next ->
                        current <- next
                        i <- i + 1
                    | Choice2Of2 detail when detail.StartsWith("function_body_stepper_failed:", StringComparison.Ordinal) && isFunctionBodyDynamicJoinFallbackDataCase (dataCaseName args.[i]) ->
                        match tryRunDynamicJoinApplyAfterDefinitionAt nodeId current args.[i] with
                        | Choice1Of2 next ->
                            current <- next
                            i <- i + 1
                        | Choice2Of2 joinDetail when joinDetail.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0 || joinDetail.IndexOf("dynamic_join_apply_failed", StringComparison.Ordinal) >= 0 ->
                            // ALPHA1329: assessment-mandated breaking change.  A recoverable
                            // dynamic-function PartEval tail must not synchronously spin back into
                            // the same body stepper.  Reuse the existing dynamic carrier as the
                            // symbolic runtime value and let parent replay continue; this is risky,
                            // but it is bounded to PartEval bridge fallback and emits explicit evidence.
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_dynamic_function_bridge_symbolic_runtime_value_accepted\",\"event\":\"dynamic_join_apply\",\"node_id\":%d,\"arg_index\":%d,\"arg_case\":%s,\"detail\":%s,\"join_detail\":%s,\"decision_du\":\"symbolic_runtime_carrier_for_part_eval_bridge\",\"policy\":\"assessment_breaking_dynamic_join_no_spin_lock_no_buildok\",\"single_flight\":1,\"next\":\"resume_parent_after_dynamic_function_symbolic_value\"}"
                                    nodeId i (DiagJson.esc (dataCaseName args.[i])) (DiagJson.esc detail) (DiagJson.esc joinDetail))
                            current <- args.[i]
                            i <- i + 1
                        | Choice2Of2 joinDetail ->
                            result <- Choice2Of2 (sprintf "%s@arg%d/%s:%s" detail i (dataCaseName args.[i]) joinDetail)
                            ok <- false
                    | Choice2Of2 detail ->
                        result <- Choice2Of2 (sprintf "%s@arg%d/%s" detail i (dataCaseName args.[i]))
                        ok <- false
                | Choice2Of2 why ->
                    result <- Choice2Of2 (sprintf "%s@arg%d/%s" why i (dataCaseName args.[i]))
                    ok <- false
            if ok then Choice1Of2 current else result

        let tryApplyReplayData (head: Data) (args: Data[]) : Data option * string =
            tryApplyReplayDataWithContext -1 head args

        // ALPHA371: conservative replay for Dyn/1.
        //
        // Dyn in the real evaluator can perform closure conversion and typed union
        // boxing through EvalState.  The explicit replay driver must not fake those
        // effects, but it can safely resolve the same inert leaves that dyn leaves
        // unchanged, plus literal/type-literal/symbol and pair normalization.  Any
        // stateful or annotation-dependent case stays partial and keeps the writer
        // fail-closed.
        let rec private tryDynReplayData = function
            | DV _ as x -> Some x
            | DB -> Some DB
            | DExists _ as x -> Some x
            | DForall _ as x -> Some x
            | DRecord _ as x -> Some x
            | DUnion _ as x -> Some x
            | DHashSet _ as x -> Some x
            | DHashMap _ as x -> Some x
            | DLit _ as x -> Some x
            | DTLit lit -> Some (DLit lit)
            | DSymbol x -> Some (DLit (LitString x))
            | DPair(a,b) ->
                match tryDynReplayData a, tryDynReplayData b with
                | Some a, Some b -> Some (DPair(a,b))
                | _ -> None
            | DNominal _ -> None
            | DFunction _ -> None

        let private recordMapArg (count: int) (k: string) (v: Data) =
            DRecord(Map.empty |> Map.add (count, "key") (DSymbol k) |> Map.add (count + 1, "value") v)

        let private tryRecordMapReplayDataWithContext (contextNodeId: int) (mapper: Data) (fields: Map<int * string, Data>) : Data option =
            let mutable ok = true
            let mutable out : Map<int * string, Data> = Map.empty
            for KeyValue((i, k), v) in fields do
                if ok then
                    let arg = recordMapArg fields.Count k v
                    match tryApplyReplayDataWithContext contextNodeId mapper [|arg|] with
                    | Some mapped, "ok" ->
                        out <- Map.add (i, k) mapped out
                    | _, why when isDynamicJoinApplyReason why ->
                        match tryDynamicJoinApplyReplayDataWithContext contextNodeId mapper [|arg|] with
                        | Choice1Of2 mapped -> out <- Map.add (i, k) mapped out
                        | Choice2Of2 _ -> ok <- false
                    | _ ->
                        ok <- false
            if ok then Some (DRecord out) else None

        let private recordFoldArg (count: int) (state: Data) (k: string) (v: Data) =
            DRecord(Map.empty |> Map.add (count, "state") state |> Map.add (count + 1, "key") (DSymbol k) |> Map.add (count + 2, "value") v)

        let private tryRecordFoldReplayDataWithContext (contextNodeId: int) (folder: Data) (state0: Data) (fields: Map<int * string, Data>) : Data option =
            let mutable ok = true
            let mutable state = state0
            for KeyValue((_i, k), v) in fields do
                if ok then
                    let arg = recordFoldArg fields.Count state k v
                    match tryApplyReplayDataWithContext contextNodeId folder [|arg|] with
                    | Some nextState, "ok" ->
                        state <- nextState
                    | _, why when isDynamicJoinApplyReason why ->
                        match tryDynamicJoinApplyReplayDataWithContext contextNodeId folder [|arg|] with
                        | Choice1Of2 nextState -> state <- nextState
                        | Choice2Of2 _ -> ok <- false
                    | _ ->
                        ok <- false
            if ok then Some state else None

        let private tryRecordFoldBackReplayDataWithContext (contextNodeId: int) (folder: Data) (state0: Data) (fields: Map<int * string, Data>) : Data option =
            let mutable ok = true
            let mutable state = state0
            for KeyValue((_i, k), v) in fields |> Seq.rev do
                if ok then
                    let arg = recordFoldArg fields.Count state k v
                    match tryApplyReplayDataWithContext contextNodeId folder [|arg|] with
                    | Some nextState, "ok" ->
                        state <- nextState
                    | _, why when isDynamicJoinApplyReason why ->
                        match tryDynamicJoinApplyReplayDataWithContext contextNodeId folder [|arg|] with
                        | Choice1Of2 nextState -> state <- nextState
                        | Choice2Of2 _ -> ok <- false
                    | _ ->
                        ok <- false
            if ok then Some state else None

        let tryResolvePureOpWithContext (contextNodeId: int) (opName: string) (argNodeIds: int[]) : Data option =
            let opName = opCaseName opName
            let typeAwareFallback () = tryTypeAwareOpReplayWithContext contextNodeId opName argNodeIds
            let values =
                argNodeIds
                |> Array.map tryTerm
            if values |> Array.exists Option.isNone then typeAwareFallback ()
            else
                let values = values |> Array.map Option.get
                match opName, values with
                | op, [|a; b|] when op = "EQ" || op = "NEQ" ->
                    match tryReplayStructuralEqData a b with
                    | Some eq ->
                        let result = if op = "EQ" then eq else not eq
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_op_structural_eq_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs\":%s,\"rhs\":%s,\"result\":%b,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                (DiagJson.esc op) contextNodeId (DiagJson.esc (dataCaseName a)) (DiagJson.esc (dataCaseName b)) result)
                        Some (boolData result)
                    | None -> typeAwareFallback ()
                | "Dyn", [|a|] -> tryDynReplayData a
                | "RecordMap", [|mapper; DRecord fields|] -> tryRecordMapReplayDataWithContext contextNodeId mapper fields
                | "RecordMap", [|DRecord fields; mapper|] -> tryRecordMapReplayDataWithContext contextNodeId mapper fields
                | "RecordFold", [|folder; state; DRecord fields|] -> tryRecordFoldReplayDataWithContext contextNodeId folder state fields
                | "RecordFoldBack", [|folder; state; DRecord fields|] -> tryRecordFoldBackReplayDataWithContext contextNodeId folder state fields
                | "RecordTypeTryFind", [|_; DSymbol key; onSucc; onFail|] ->
                    let recordTyOpt = if argNodeIds.Length > 0 then tryType argNodeIds.[0] else None
                    match recordTyOpt with
                    | Some (YRecord fields) ->
                        match fields |> Map.tryPick (fun (_, k) v -> if k = key then Some v else None) with
                        | Some tyValue ->
                            match tryRunTypeApplyAfterDefinitionAt contextNodeId onSucc tyValue with
                            | Choice1Of2 value ->
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_record_type_try_find_success_direct_resolved\",\"context_node_id\":%d,\"key\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                        contextNodeId (DiagJson.esc key))
                                Some value
                            | Choice2Of2 detail ->
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_record_type_try_find_success_direct_blocked\",\"context_node_id\":%d,\"key\":%s,\"detail\":%s,\"single_flight\":1,\"next\":\"schedule_record_type_try_find_success_replay\"}"
                                        contextNodeId (DiagJson.esc key) (DiagJson.esc detail))
                                typeAwareFallback ()
                        | None ->
                            match tryApplyReplayDataWithContext contextNodeId onFail [|DB|] with
                            | Some value, "ok" ->
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_record_type_try_find_fail_direct_resolved\",\"context_node_id\":%d,\"key\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                        contextNodeId (DiagJson.esc key))
                                Some value
                            | _, detail ->
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_record_type_try_find_fail_direct_blocked\",\"context_node_id\":%d,\"key\":%s,\"detail\":%s,\"single_flight\":1,\"next\":\"schedule_record_type_try_find_fail_replay\"}"
                                        contextNodeId (DiagJson.esc key) (DiagJson.esc detail))
                                typeAwareFallback ()
                    | _ -> typeAwareFallback ()
                | op, [|a; b|] when op = "LT" || op = "LTE" || op = "GT" || op = "GTE" ->
                    match unwrapNominalData a, unwrapNominalData b with
                    | DLit la, DLit lb ->
                        match tryCompareLiteral op la lb with
                        | Some value ->
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_op_nominal_literal_compare_resolved\",\"op\":%s,\"context_node_id\":%d,\"lhs\":%s,\"rhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                    (DiagJson.esc op) contextNodeId (DiagJson.esc (dataCaseName a)) (DiagJson.esc (dataCaseName b)))
                            Some value
                        | None -> typeAwareFallback ()
                    | _ -> typeAwareFallback ()
                | "Add", [|a; b|] ->
                    let a' = unwrapNominalData a
                    let b' = unwrapNominalData b
                    match a', b' with
                    | DLit la, DLit lb ->
                        match tryAddLiteral la lb with
                        | Some value ->
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_add_nominal_literal_resolved\",\"context_node_id\":%d,\"lhs\":%s,\"rhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                    contextNodeId (DiagJson.esc (dataCaseName a)) (DiagJson.esc (dataCaseName b)))
                            Some value
                        | None -> typeAwareFallback ()
                    | _ when isZeroData a' ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_add_nominal_zero_left_resolved\",\"context_node_id\":%d,\"rhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                contextNodeId (DiagJson.esc (dataCaseName b)))
                        Some b
                    | _ when isZeroData b' ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_add_nominal_zero_right_resolved\",\"context_node_id\":%d,\"lhs\":%s,\"single_flight\":1,\"next\":\"term_op_pure_value_resolved\"}"
                                contextNodeId (DiagJson.esc (dataCaseName a)))
                        Some a
                    | _ -> typeAwareFallback ()
                | "Sub", [|DLit a; DLit b|] -> trySubLiteral a b
                | "Sub", [|a; b|] when isZeroData b -> Some a
                | "VarIs", [|a|] -> Some (boolData (isReplayVarLike a))
                | "LitIs", [|DLit _|] -> Some (boolData true)
                | "LitIs", [|_|] -> Some (boolData false)
                | "PrimIs", [|a|] -> Some (boolData (isPrimLike a))
                | "SymbolIs", [|DSymbol _|] -> Some (boolData true)
                | "SymbolIs", [|_|] -> Some (boolData false)
                | "StringLitToSymbol", [|DLit (LitString x)|] -> Some (DSymbol x)
                | "StringLitToSymbol", [|DTLit (LitString x)|] -> Some (DSymbol x)
                | "SymbolToString", [|DSymbol x|] -> Some (DLit (LitString x))
                | "UnionIs", [|a|] -> Some (boolData (isUnionLike a))
                | "HeapUnionIs", [|a|] -> Some (boolData (isHeapUnionLike a))
                | "LayoutIs", [|a|] -> Some (boolData (isLayoutLike a))
                | "NominalIs", [|a|] -> Some (boolData (isNominalLike a))
                | "FunctionIs", [|a|] -> Some (boolData (isFunctionLike a))
                | "ExistsIs", [|a|] -> Some (boolData (isExistsLike a))
                | _ -> typeAwareFallback ()

        let tryResolvePureOp (opName: string) (argNodeIds: int[]) : Data option =
            tryResolvePureOpWithContext -1 opName argNodeIds

    /// Alpha350 update: replay commit now acts as a resume handoff. When retry_stop observes
    /// semantic_step_done/queue_depth=0, it invalidates the cache once and re-enters attempt_build
    /// instead of raising the stale pre-commit EJP0011 message.
    /// ### Trace
    type Trace = Range list

    /// ### PartEvalTypeError
    /// Raised to abort partial-eval when we detect irrecoverable type mismatch / cache corruption signals.
    exception PartEvalTypeError of Trace * string

    type ApplyFunctionBodyPartEvalTailDecision =
        | PreservePinnedParentPoison
        | DeferArgBinderTailToExplicitReplay
        | DeferDynamicLiteralArgBinderTailToExplicitReplay
        | DeferTypeApplyTypeArgTailToTyReplay

    let tryCacheHandoffChildNodeIdFromSite (site: string) =
        let marker = "cache_handoff@child:"
        let markerAt = site.IndexOf(marker, StringComparison.Ordinal)
        if markerAt < 0 then None
        else
            let childStart = markerAt + marker.Length
            let childStop = site.IndexOf(":", childStart, StringComparison.Ordinal)
            if childStop <= childStart then None
            else
                match System.Int32.TryParse(site.Substring(childStart, childStop - childStart)) with
                | true, childNodeId -> Some childNodeId
                | _ -> None

    type DynamicFunctionBridgeTailDecision =
        | PinDynamicFunctionBridgeTerminal
        | ScheduleDynTypecheckPairTailReplay
        | ScheduleLiteralTailReplay
        | SchedulePartEvalFailureBodyReplay

    type DynamicFunctionBridgeFallbackDecision =
        | AcceptSymbolicRuntimeCarrier of decisionDu: string * scheduleDetail: string
        | YieldRecoverableDynamicFunctionBridge
        | PinHardDynamicFunctionBridgeTerminal

    type DynamicFunctionBridgeRecoverability =
        | DynamicFunctionBridgeHardTerminal
        | DynamicFunctionBridgeLiveRecoverable
        | DynamicFunctionBridgeRootWitnessGuard

    type DynamicFunctionBridgeLiveEvidence = {
        pending: int
        queueDepth: int
        activeDepth: int
        rootWitnessActivity: int
        writeWitness: bool
        recoverability: DynamicFunctionBridgeRecoverability
        }

    exception EvalReplayTyReturn of Ty
    exception EvalReplayTermReturn of Data
    /// ### EvalWorklist
    /// Generic explicit evaluator-worklist seed.
    ///
    /// This is intentionally shape-based, not source-based: it records a blocked evaluator frame
    /// (term/ty/unknown, key, site, depth, re-entry budget, compact trace) so future alphas can
    /// move recursive descent into a resumable loop without hardcoding stdlib/module names.
    module EvalWorklist =
        open System

        // ALPHA1526: phantom cache-key scaffold. This is intentionally inert-but-typed: it lets new hot-path receipts carry Term/Ty intent without parsing raw strings, while older Frame/ReplayTask fields stay source-compatible until the native Hopac bind path owns authority.
        type TermKind = interface end
        type TyKind = interface end
        type NodeId<'Kind> = NodeId of int
        type CacheKey<'Kind> =
            | CacheKeyFromReplayCell of NodeId<'Kind> * string
            | CacheKeyFromRaw of string
            | CacheKeyErasedIdentity of erasureSite: string
            | CacheKeyMissing
        type HopacShadowProbe<'Kind> =
            | HopacShadowIdle
            | HopacShadowActive of CacheKey<'Kind> * ivarState: string * mailboxState: string * altState: string
            | HopacShadowTimeoutExpired of CacheKey<'Kind> * pierceTarget: string
            | HopacShadowPhysicalPendingAbsent of CacheKey<'Kind>
        // ALPHA1533: assessment-driven typed key families. These remain bridge-only,
        // but they make the next native Hopac envelope impossible to express with a
        // naked -1 key: Term and Ty obligations erase into one queue only through an
        // explicit DU constructor, not through ad-hoc strings.
        type TermCacheKey =
            | TermApplyArg0 of NodeId<TermKind>
            | TermFunctionBody of NodeId<TermKind>
            | TermRecordKey of string * NodeId<TermKind>
            | TermErasedIdentity of erasureSite: string
        type TyCacheKey =
            | TyTypeApply of NodeId<TyKind>
            | TyPairRight of NodeId<TyKind>
            | TyErasedIdentity of erasureSite: string
        type ReplayObligationEnvelope =
            | TermObligation of TermCacheKey * HopacShadowProbe<TermKind>
            | TyObligation of TyCacheKey * HopacShadowProbe<TyKind>

        // ALPHA1607: assessment-driven witness-clear lattice.  These are deliberately
        // small and inert at first, but they move the native Hopac frontier away from
        // string shards: a terminal cell must pass Unresolved -> Witnessed -> Cleared,
        // and the witness envelope names the IVar registry and proof family before any
        // legacy observer is allowed to speak.
        type EvalCellUnresolved = interface end
        type EvalCellWitnessed = interface end
        type EvalCellCleared = interface end

