            | TerminalShardHardPoisonObligationCapImmediateFill
            | TerminalShardParentCacheHandoffWake
            | TerminalShardParentReplayStatusPreservedCacheHandoff
            | TerminalShardCooperativeReplayNativeBind
            | TerminalShardTyGlobalFuseParentContinuation
            | TerminalShardReentryPrefetchTerminalDriver
            | TerminalShardJoinWaitDriverPromise
            | TerminalShardNoRootBudgetParentReplayImmediateFill
            | TerminalShardUnknown of string

        let pendingGraphMailboxBatchSummaryText = function
            | TerminalShardSingleQapQuarantinedLegacyZero -> "terminal_shards=1|qap_quarantine=1|legacy_observer=0"
            | TerminalShardSingleImmediateFill -> "terminal_shards=1|qap_quarantine=1|legacy_observer=0|immediate_fill=1"
            | TerminalShardSemanticStaleRetargetImmediateFill -> "terminal_shards=1|semantic_stale_retarget=1|qap_quarantine=1|legacy_observer=0|immediate_fill=1"
            | TerminalShardDynamicJoinReplay -> "terminal_shards=1|dynamic_join_replay=1|legacy_observer=0"
            | TerminalShardIdleCrossKindDrain -> "terminal_shards=1|idle_cross_kind_sidecar_drain=1|legacy_observer=0"
            | TerminalShardDynamicBridgeCommit -> "terminal_shards=1|dynamic_record_key_bridge_commit=1|legacy_observer=0"
            | TerminalShardParentPoisonLiveTail -> "terminal_shards=1|parent_replay_poison_live_tail=1|legacy_observer=0"
            | TerminalShardParentReplayCycleBreakPoisonImmediateFill -> "terminal_shards=1|parent_replay_cycle_break_poison=1|qap_quarantine=1|legacy_observer=0|immediate_fill=1"
            | TerminalShardCrossKindYieldThrashHardPoison -> "terminal_shards=1|cross_kind_yield_thrash_hard_poison=1|qap_quarantine=1|legacy_observer=0|bounded_guard=1"
            | TerminalShardHardPoisonObligationCapImmediateFill -> "terminal_shards=1|hard_poison_obligation_cap=1|qap_quarantine=1|legacy_observer=0|immediate_fill=1|repeat_cap_observer=1"
            | TerminalShardParentCacheHandoffWake -> "terminal_shards=1|parent_cache_handoff_wake=1|legacy_observer=0|driver_wake=1"
            | TerminalShardParentReplayStatusPreservedCacheHandoff -> "terminal_shards=1|parent_replay_status_preserved_cache_handoff=1|legacy_observer=0|immediate_fill=1|repeat_status_observer=1"
            | TerminalShardCooperativeReplayNativeBind -> "terminal_shards=1|cooperative_replay_native_bind=1|legacy_observer=0|job_bind=1|threadpool_observer=1"
            | TerminalShardTyGlobalFuseParentContinuation -> "terminal_shards=1|ty_global_fuse_parent_continuation=1|legacy_observer=0"
            | TerminalShardReentryPrefetchTerminalDriver -> "terminal_shards=1|reentry_prefetch_terminal_driver=1|legacy_observer=0"
            | TerminalShardJoinWaitDriverPromise -> "terminal_shards=1|join_wait_driver_promise=1|legacy_observer=0"
            | TerminalShardNoRootBudgetParentReplayImmediateFill -> "terminal_shards=1|no_root_budget_parent_replay=1|qap_quarantine=1|legacy_observer=0|immediate_fill=1|no_root_budget_observer=1"
            | TerminalShardUnknown x -> x

        type PendingGraphProofTuple = {
            witness: TerminalWitnessEnvelope
            commitClass: TerminalCommitClassId
            mailboxBatch: PendingGraphMailboxBatchSummaryId
            fillStrategy: ParentContinuationFillStrategyId
            qapAuthority: QapAuthorityId
            legacyVeto: LegacyVetoQuarantineId
            rawKeyDeprecated: bool
            shadowTimeoutMs: int
            }

        let pendingGraphProofTupleComplete tuple =
            tuple.rawKeyDeprecated && tuple.shadowTimeoutMs = 0

        // ALPHA1617: assessment asked for tuple expansion and native Promise visibility.
        // These renderers make the tuple's required slots explicit before HUD/JSONL,
        // keeping repeat caps and legacy live-tail as observers after a witnessed IVar exists.
        type NativeHopacPromiseStateId =
            | NativePromisePending of NativeHopacIvarRegistryId
            | NativePromiseMaterialized of NativeHopacIvarRegistryId
            | NativePromiseWitnessed of NativeHopacIvarRegistryId * TerminalWitnessKindId
            | NativePromiseFilled of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativePromiseLegacyObserverQuarantined of NativeHopacIvarRegistryId * LegacyVetoQuarantineId

        let nativeHopacPromiseStateText = function
            | NativePromisePending ivar -> "Pending(" + nativeHopacIvarRegistryText ivar + ")"
            | NativePromiseMaterialized ivar -> "Materialized(" + nativeHopacIvarRegistryText ivar + ")"
            | NativePromiseWitnessed (ivar,witness) -> "Witnessed(" + nativeHopacIvarRegistryText ivar + "," + terminalWitnessKindText witness + ")"
            | NativePromiseFilled (ivar,fill) -> "Filled(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativePromiseLegacyObserverQuarantined (ivar,legacy) -> "LegacyObserverQuarantined(" + nativeHopacIvarRegistryText ivar + "," + legacyVetoQuarantineText legacy + ")"

        type HotRowRecyclePolicyId =
            | RecycleEmitFullThenCompactTerminalTuple
            | RecycleCompactSemanticStaleRetarget
            | RecycleCompactParentReplayCycleBreakPoison
            | RecycleCompactCrossKindYieldThrashHardPoison
            | RecycleCompactHardPoisonObligationCap
            | RecycleCompactParentReplayStatusPreservedCacheHandoff
            | RecycleCompactCooperativeReplayNativeBind
            | RecycleCompactJoinWaitAfterWitness
            | RecycleCompactMetronomeAfterAuthority
            | RecycleCompactNoRootBudgetParentReplay
            | RecycleKeepFullUntilWitness

        let hotRowRecyclePolicyText = function
            | RecycleEmitFullThenCompactTerminalTuple -> "emit_full_once_then_compact_terminal_tuple"
            | RecycleCompactSemanticStaleRetarget -> "emit_once_then_compact_semantic_stale_retarget"
            | RecycleCompactParentReplayCycleBreakPoison -> "emit_once_then_compact_parent_replay_cycle_break_poison"
            | RecycleCompactCrossKindYieldThrashHardPoison -> "emit_once_then_compact_cross_kind_yield_thrash_hard_poison"
            | RecycleCompactHardPoisonObligationCap -> "emit_once_then_compact_hard_poison_obligation_cap"
            | RecycleCompactParentReplayStatusPreservedCacheHandoff -> "emit_once_then_compact_parent_replay_status_preserved_cache_handoff"
            | RecycleCompactCooperativeReplayNativeBind -> "emit_once_then_compact_cooperative_replay_native_bind"
            | RecycleCompactJoinWaitAfterWitness -> "emit_once_then_compact_join_wait_after_witness"
            | RecycleCompactMetronomeAfterAuthority -> "emit_once_then_compact_metronome_authority"
            | RecycleCompactNoRootBudgetParentReplay -> "emit_once_then_compact_no_root_budget_parent_replay"
            | RecycleKeepFullUntilWitness -> "keep_full_until_witness_materialized"

        type ProofTupleMatrixStatus = {
            witnessOk: bool
            ivarRegistryOk: bool
            cycleRootOk: bool
            commitClassOk: bool
            fillOk: bool
            promiseState: NativeHopacPromiseStateId
            recyclePolicy: HotRowRecyclePolicyId
            }

        let proofTupleMatrixStatusFor tuple =
            let recyclePolicy =
                match tuple.witness.kind with
                | WitnessSemanticStaleRetargetProof -> RecycleCompactSemanticStaleRetarget
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof -> RecycleCompactParentReplayCycleBreakPoison
                | WitnessCrossKindYieldThrashHardPoisonProof -> RecycleCompactCrossKindYieldThrashHardPoison
                | WitnessHardPoisonObligationCapProof -> RecycleCompactHardPoisonObligationCap
                | WitnessParentReplayStatusPreservedCacheHandoffProof -> RecycleCompactParentReplayStatusPreservedCacheHandoff
                | WitnessCooperativeReplayNativeBindProof -> RecycleCompactCooperativeReplayNativeBind
                | WitnessJoinWaitDriverPromiseProof -> RecycleCompactJoinWaitAfterWitness
                | WitnessMetronomeTerminalAuthorityProof -> RecycleCompactMetronomeAfterAuthority
                | WitnessNoRootBudgetParentReplayImmediateFillProof -> RecycleCompactNoRootBudgetParentReplay
                | _ -> RecycleEmitFullThenCompactTerminalTuple
            { witnessOk = true
              ivarRegistryOk = true
              cycleRootOk = not (System.String.IsNullOrWhiteSpace tuple.witness.cycleRootOrigin)
              commitClassOk = true
              fillOk = true
              promiseState =
                if pendingGraphProofTupleComplete tuple then NativePromiseFilled (tuple.witness.ivar, tuple.fillStrategy)
                else NativePromiseWitnessed (tuple.witness.ivar, tuple.witness.kind)
              recyclePolicy = recyclePolicy }

        let proofTupleMatrixText matrix =
            sprintf "[Witness:%s]|[IVar Reg:%s]|[Cycle Root:%s]|[Commit Class:%s]|[Fill:%s]|promise=%s|recycle=%s"
                (if matrix.witnessOk then "OK" else "Missing")
                (if matrix.ivarRegistryOk then "OK" else "Missing")
                (if matrix.cycleRootOk then "OK" else "Missing")
                (if matrix.commitClassOk then "OK" else "Missing")
                (if matrix.fillOk then "OK" else "Missing")
                (nativeHopacPromiseStateText matrix.promiseState)
                (hotRowRecyclePolicyText matrix.recyclePolicy)

        let proofTupleCriticalPathText tuple =
            sprintf "payload_witness=%s -> ivar=%s -> fill=%s -> legacy=%s -> qap=observer"
                (terminalWitnessKindText tuple.witness.kind)
                (nativeHopacIvarRegistryText tuple.witness.ivar)
                (parentContinuationFillStrategyText tuple.fillStrategy)
                (legacyVetoQuarantineText tuple.legacyVeto)

        let pendingGraphProofTupleText tuple =
            sprintf "witness=%s|commit=%s|mailbox=%s|fill=%s|qap=%s|legacy=%s|raw_key_deprecated=%b|timeout_ms=%d|complete=%b"
                (terminalWitnessEnvelopeText tuple.witness)
                (terminalCommitClassText tuple.commitClass)
                (pendingGraphMailboxBatchSummaryText tuple.mailboxBatch)
                (parentContinuationFillStrategyText tuple.fillStrategy)
                (qapAuthorityText tuple.qapAuthority)
                (legacyVetoQuarantineText tuple.legacyVeto)
                tuple.rawKeyDeprecated
                tuple.shadowTimeoutMs
                (pendingGraphProofTupleComplete tuple)

        // ALPHA1622: close the authority gap between tuple existence and action.
        // The decision/projection pair is the typed source for JSON/HUD compact rows;
        // string rendering happens only at the boundary.
        type ProofTupleAuthorityDecisionId =
            | ProofTupleDecisionFillIvarImmediately of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | ProofTupleDecisionBindNativePromise of NativeHopacIvarRegistryId
            | ProofTupleDecisionQuarantineHudFrontier of LegacyVetoQuarantineId
            | ProofTupleDecisionCompactObserverPolling of HotRowRecyclePolicyId

        let proofTupleAuthorityDecisionText = function
            | ProofTupleDecisionFillIvarImmediately (ivar,fill) -> "fill_ivar_immediately(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | ProofTupleDecisionBindNativePromise ivar -> "bind_native_promise_before_hud_frontier(" + nativeHopacIvarRegistryText ivar + ")"
            | ProofTupleDecisionQuarantineHudFrontier legacy -> "quarantine_eval_worklist_hud_frontier(" + legacyVetoQuarantineText legacy + ")"
            | ProofTupleDecisionCompactObserverPolling recycle -> "compact_observer_polling(" + hotRowRecyclePolicyText recycle + ")"

        // ALPHA1625: authoritative ordering is now a DU projection.  It makes
        // the assessment invariant explicit: typed proof and native callback
        // outrank HUD frontier, q/a/p, repeat caps and legacy live-tail polling.
        type ProofTupleAuthorityStackId =
            | ProofTupleAuthorityStackMissingWitness
            | ProofTupleAuthorityStackTypedProofNativeCallback
            | ProofTupleAuthorityStackTypedProofRecycleThenCallback
            | ProofTupleAuthorityStackLegacyObserverQuarantined
            | ProofTupleAuthorityStackUnknown of string

        let proofTupleAuthorityStackText = function
            | ProofTupleAuthorityStackMissingWitness -> "missing_witness_then_bind_native_promise"
            | ProofTupleAuthorityStackTypedProofNativeCallback -> "typed_proof>native_callback>compact_recycle>legacy_observer"
            | ProofTupleAuthorityStackTypedProofRecycleThenCallback -> "typed_proof>compact_hot_row>native_callback>legacy_observer"
            | ProofTupleAuthorityStackLegacyObserverQuarantined -> "legacy_observer_quarantined_after_proof_tuple"
            | ProofTupleAuthorityStackUnknown x -> x

        type NativeCallbackCommitmentId =
            | NativeCallbackCommitmentIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeCallbackCommitmentPromiseBind of NativeHopacIvarRegistryId
            | NativeCallbackCommitmentCyclePoisonPromise of TerminalWitnessKindId
            | NativeCallbackCommitmentHudFrontierQuarantine

        let nativeCallbackCommitmentText = function
            | NativeCallbackCommitmentIvarFill (ivar,fill) -> "commit:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeCallbackCommitmentPromiseBind ivar -> "commit:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeCallbackCommitmentCyclePoisonPromise witness -> "commit:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeCallbackCommitmentHudFrontierQuarantine -> "commit:quarantine_eval_worklist_hud_terminal_frontier"

        type CompactObserverEnvelopeId =
            | CompactObserverEnvelopeFullOnceThenKeyedDelta
            | CompactObserverEnvelopeProofTupleOnly
            | CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill
            | CompactObserverEnvelopeCacheHandoffPayloadPromiseNext
            | CompactObserverEnvelopeHardPoisonPayloadWitnessIvar

        let compactObserverEnvelopeText = function
            | CompactObserverEnvelopeFullOnceThenKeyedDelta -> "emit_full_once_then_keyed_delta"
            | CompactObserverEnvelopeProofTupleOnly -> "payload,witness,ivar,fill,authority,next"
            | CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill -> "join_wait:key,payload,witness,ivar,fill,next"
            | CompactObserverEnvelopeCacheHandoffPayloadPromiseNext -> "cache_handoff:payload,promise,callback,next"
            | CompactObserverEnvelopeHardPoisonPayloadWitnessIvar -> "hard_poison:payload,witness,ivar,cycle_root,next"

        // ALPHA1626: hot rows that still surface through backup ticks, pin snapshots
        // or parent-poison live-tail override are explicitly projected from the proof
        // tuple before JSON rendering.  This keeps the old scheduler fields as
        // receipts instead of authority.
        type HotRowAuthorityProjectionId =
            | HotRowProjectionNativeBackupTick of HotRowRecyclePolicyId
            | HotRowProjectionTerminalFrontierPin of TerminalWitnessKindId
            | HotRowProjectionParentPoisonLiveTailOverride of TerminalWitnessKindId
            | HotRowProjectionReplayDriverSurface of TerminalWitnessKindId
            | HotRowProjectionUnknown of string

        let hotRowAuthorityProjectionText = function
            | HotRowProjectionNativeBackupTick recycle -> "native_backup_tick_suppressed_by_proof_tuple(" + hotRowRecyclePolicyText recycle + ")"
            | HotRowProjectionTerminalFrontierPin witness -> "terminal_frontier_pin_observes_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionParentPoisonLiveTailOverride witness -> "parent_poison_live_tail_override_bypassed_by_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionReplayDriverSurface witness -> "replay_driver_surface_observes_proof_tuple(" + terminalWitnessKindText witness + ")"
            | HotRowProjectionUnknown x -> x


        // ALPHA1627: a materialized proof must make the HUD frontier topologically unreachable.
        // These DUs render the final cutover contract: inline IVar.fill / Job.bind wins before
        // any pinned-terminal observer, live-tail veto, no-root budget or repeat-cap path can run.
        type NativeInlineCallbackCutoverId =
            | NativeInlineCallbackCutoverMissingWitness
            | NativeInlineCallbackCutoverIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeInlineCallbackCutoverJobBind of NativeHopacIvarRegistryId
            | NativeInlineCallbackCutoverCyclePoison of TerminalWitnessKindId
            | NativeInlineCallbackCutoverHudFrontierSevered of LegacyVetoQuarantineId

        let nativeInlineCallbackCutoverText = function
            | NativeInlineCallbackCutoverMissingWitness -> "missing_witness_no_inline_callback"
            | NativeInlineCallbackCutoverIvarFill (ivar,fill) -> "inline:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeInlineCallbackCutoverJobBind ivar -> "inline:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeInlineCallbackCutoverCyclePoison witness -> "inline:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeInlineCallbackCutoverHudFrontierSevered legacy -> "sever_eval_worklist_hud_terminal_frontier(" + legacyVetoQuarantineText legacy + ")"

        type LegacyObserverTopologyId =
            | LegacyObserverTopologyReachableBeforeWitness
            | LegacyObserverTopologySeveredByInlineIvarFill
            | LegacyObserverTopologySeveredByNativePromiseBind
            | LegacyObserverTopologySeveredByCyclePoison

        let legacyObserverTopologyText = function
            | LegacyObserverTopologyReachableBeforeWitness -> "legacy_observer_reachable_until_witness"
            | LegacyObserverTopologySeveredByInlineIvarFill -> "legacy_observer_topologically_inaccessible_after_inline_ivar_fill"
            | LegacyObserverTopologySeveredByNativePromiseBind -> "legacy_observer_topologically_inaccessible_after_job_bind"
            | LegacyObserverTopologySeveredByCyclePoison -> "legacy_observer_topologically_inaccessible_after_cycle_poison"

        type WitnessRoutingLatticeId =
            | WitnessRoutingLatticeUnresolved
            | WitnessRoutingLatticeImmediateFill of TerminalWitnessKindId * NativeHopacIvarRegistryId
            | WitnessRoutingLatticePromiseBind of TerminalWitnessKindId * NativeHopacIvarRegistryId
            | WitnessRoutingLatticeCyclePoison of TerminalWitnessKindId

        let witnessRoutingLatticeText = function
            | WitnessRoutingLatticeUnresolved -> "[Witness:Missing]->[Route:Wait]->[Status:Unresolved]"
            | WitnessRoutingLatticeImmediateFill (w,ivar) -> "[Witness:" + terminalWitnessKindText w + "]->[Route:IVar.fill]->[IVar:" + nativeHopacIvarRegistryText ivar + "]->[Status:InlineCommitted]"
            | WitnessRoutingLatticePromiseBind (w,ivar) -> "[Witness:" + terminalWitnessKindText w + "]->[Route:Job.bind]->[Promise:" + nativeHopacIvarRegistryText ivar + "]->[Status:NativeQueue]"
            | WitnessRoutingLatticeCyclePoison w -> "[Witness:" + terminalWitnessKindText w + "]->[Route:CyclePoisonPromise]->[Status:NativeQueue]"

        // ALPHA1628: the assessment asked for memory-level native Promise identifiers and
        // the exact commit pathway executing the continuation.  These DUs keep that
        // topology typed before JSON/HUD rendering, making the legacy frontier an
        // impossible return target once the proof tuple is complete.
        type NativePromiseIdentifierId =
            | NativePromiseIdentifier of NativeHopacIvarRegistryId * TerminalWitnessKindId
            | NativePromiseIdentifierCyclePoison of TerminalWitnessKindId
            | NativePromiseIdentifierUnknown of string

        let nativePromiseIdentifierText = function
            | NativePromiseIdentifier (ivar,witness) -> "promise_id(" + nativeHopacIvarRegistryText ivar + "," + terminalWitnessKindText witness + ")"
            | NativePromiseIdentifierCyclePoison witness -> "cycle_poison_promise_id(" + terminalWitnessKindText witness + ")"
            | NativePromiseIdentifierUnknown x -> x

        type WorkerReturnTopologyId =
            | WorkerReturnNativeRunQueueAfterIvarFill of NativeHopacIvarRegistryId
            | WorkerReturnNativeRunQueueAfterJobBind of NativeHopacIvarRegistryId
            | WorkerReturnNativeRunQueueAfterCyclePoison of TerminalWitnessKindId
            | WorkerReturnLegacyHudFrontierForbidden of LegacyVetoQuarantineId

        let workerReturnTopologyText = function
            | WorkerReturnNativeRunQueueAfterIvarFill ivar -> "return:native_hopac_run_queue_after_IVar.fill(" + nativeHopacIvarRegistryText ivar + ")"
            | WorkerReturnNativeRunQueueAfterJobBind ivar -> "return:native_hopac_run_queue_after_Job.bind(" + nativeHopacIvarRegistryText ivar + ")"
            | WorkerReturnNativeRunQueueAfterCyclePoison witness -> "return:native_hopac_run_queue_after_CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | WorkerReturnLegacyHudFrontierForbidden legacy -> "forbid:return_to_eval_worklist_hud_terminal_frontier(" + legacyVetoQuarantineText legacy + ")"

        type NativeRunQueueCommitId =
            | NativeRunQueueCommitIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeRunQueueCommitJobBind of NativeHopacIvarRegistryId
            | NativeRunQueueCommitCyclePoison of TerminalWitnessKindId
            | NativeRunQueueCommitReceiptOnly

        let nativeRunQueueCommitText = function
            | NativeRunQueueCommitIvarFill (ivar,fill) -> "commit:IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeRunQueueCommitJobBind ivar -> "commit:Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeRunQueueCommitCyclePoison witness -> "commit:CyclePoisonPromise(" + terminalWitnessKindText witness + ")"
            | NativeRunQueueCommitReceiptOnly -> "commit:receipt_only_after_native_callback"

        type ProofTupleExecutionClosure = {
            promiseIdentifier: NativePromiseIdentifierId
            workerReturn: WorkerReturnTopologyId
            runQueueCommit: NativeRunQueueCommitId
            legacyYieldForbidden: bool
            hudFrontierReceiptOnly: bool
            }

        let nativePromiseIdentifierFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof -> NativePromiseIdentifierCyclePoison tuple.witness.kind
            | _ -> NativePromiseIdentifier (tuple.witness.ivar, tuple.witness.kind)

        let workerReturnTopologyFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> WorkerReturnNativeRunQueueAfterCyclePoison tuple.witness.kind
                | _ -> WorkerReturnNativeRunQueueAfterIvarFill tuple.witness.ivar
            else WorkerReturnNativeRunQueueAfterJobBind tuple.witness.ivar

        let nativeRunQueueCommitFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeRunQueueCommitCyclePoison tuple.witness.kind
                | _ -> NativeRunQueueCommitIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeRunQueueCommitJobBind tuple.witness.ivar

        let proofTupleExecutionClosureFor (tuple: PendingGraphProofTuple) =
            { promiseIdentifier = nativePromiseIdentifierFor tuple
              workerReturn = workerReturnTopologyFor tuple
              runQueueCommit = nativeRunQueueCommitFor tuple
              legacyYieldForbidden = pendingGraphProofTupleComplete tuple
              hudFrontierReceiptOnly = pendingGraphProofTupleComplete tuple }

        let proofTupleExecutionClosureText (closure: ProofTupleExecutionClosure) =
            sprintf "promise=%s|worker=%s|run_queue=%s|legacy_yield_forbidden=%b|hud_receipt_only=%b"
                (nativePromiseIdentifierText closure.promiseIdentifier)
                (workerReturnTopologyText closure.workerReturn)
                (nativeRunQueueCommitText closure.runQueueCommit)
                closure.legacyYieldForbidden
                closure.hudFrontierReceiptOnly

        type ActiveNativeCallbackBoundaryId =
            | ActiveCallbackExecuteBeforeEvalWorklistBoundary
            | ActiveCallbackBindExistingPromiseBeforeLegacyObserver
            | ActiveCallbackReturnJobUnitAfterInlineCommit
            | ActiveCallbackObserverOnlyUntilWitness

        let activeNativeCallbackBoundaryText = function
            | ActiveCallbackExecuteBeforeEvalWorklistBoundary -> "execute_native_direct_ast_eval_before_polling_boundary"
            | ActiveCallbackBindExistingPromiseBeforeLegacyObserver -> "bind_existing_promise_before_legacy_observer"
            | ActiveCallbackReturnJobUnitAfterInlineCommit -> "return:Job.unit_after_inline_native_callback"
            | ActiveCallbackObserverOnlyUntilWitness -> "observer_only_until_witness_materializes"

        type ActiveNativeCallbackClosure = {
            callback: NativeCallbackCommitmentId
            boundary: ActiveNativeCallbackBoundaryId
            workerReturn: WorkerReturnTopologyId
            runQueueCommit: NativeRunQueueCommitId
            legacyLiveTailReachable: bool
            evalWorklistBoundaryReachable: bool
            }

        let activeNativeCallbackClosureFor (tuple: PendingGraphProofTuple) =
            let complete = pendingGraphProofTupleComplete tuple
            { callback = if complete then NativeCallbackCommitmentIvarFill (tuple.witness.ivar, tuple.fillStrategy) else NativeCallbackCommitmentPromiseBind tuple.witness.ivar
              boundary = if complete then ActiveCallbackExecuteBeforeEvalWorklistBoundary else ActiveCallbackBindExistingPromiseBeforeLegacyObserver
              workerReturn = workerReturnTopologyFor tuple
              runQueueCommit = nativeRunQueueCommitFor tuple
              legacyLiveTailReachable = not complete
              evalWorklistBoundaryReachable = not complete }

        let activeNativeCallbackClosureText (closure: ActiveNativeCallbackClosure) =
            sprintf "callback=%s|boundary=%s|worker=%s|run_queue=%s|legacy_live_tail_reachable=%b|eval_worklist_boundary_reachable=%b|return=Job.unit"
                (nativeCallbackCommitmentText closure.callback)
                (activeNativeCallbackBoundaryText closure.boundary)
                (workerReturnTopologyText closure.workerReturn)
                (nativeRunQueueCommitText closure.runQueueCommit)
                closure.legacyLiveTailReachable
                closure.evalWorklistBoundaryReachable

        let proofTupleAuthorityDecisionFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                ProofTupleDecisionFillIvarImmediately (tuple.witness.ivar, tuple.fillStrategy)
            else
                ProofTupleDecisionBindNativePromise tuple.witness.ivar

        type ProofTupleCompactProjection = {
            payloadDu: string
            witnessKind: TerminalWitnessKindId
            ivarRegistry: NativeHopacIvarRegistryId
            fillStrategy: ParentContinuationFillStrategyId
            authorityDecision: ProofTupleAuthorityDecisionId
            recyclePolicy: HotRowRecyclePolicyId
            nextAction: string
            }

        let proofTupleCompactProjectionFor (tuple: PendingGraphProofTuple) =
            let matrix = proofTupleMatrixStatusFor tuple
            let decision = proofTupleAuthorityDecisionFor tuple
            let nextAction =
                match decision with
                | ProofTupleDecisionFillIvarImmediately _ -> "fill_parent_continuation_ivar_immediately"
                | ProofTupleDecisionBindNativePromise _ -> "bind_native_promise_before_hud_frontier"
                | ProofTupleDecisionQuarantineHudFrontier _ -> "quarantine_hud_frontier"
                | ProofTupleDecisionCompactObserverPolling _ -> "compact_observer_polling"
            { payloadDu = tuple.witness.payload
              witnessKind = tuple.witness.kind
              ivarRegistry = tuple.witness.ivar
              fillStrategy = tuple.fillStrategy
              authorityDecision = decision
              recyclePolicy = matrix.recyclePolicy
              nextAction = nextAction }

        let proofTupleCompactProjectionText (projection: ProofTupleCompactProjection) =
            sprintf "payload=%s|witness=%s|ivar=%s|fill=%s|decision=%s|recycle=%s|next=%s"
                projection.payloadDu
                (terminalWitnessKindText projection.witnessKind)
                (nativeHopacIvarRegistryText projection.ivarRegistry)
                (parentContinuationFillStrategyText projection.fillStrategy)
                (proofTupleAuthorityDecisionText projection.authorityDecision)
                (hotRowRecyclePolicyText projection.recyclePolicy)
                projection.nextAction

        let proofTupleAuthorityStackFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof
                | WitnessParentReplayStatusPreservedCacheHandoffProof
                | WitnessNoRootBudgetParentReplayImmediateFillProof
                | WitnessCooperativeReplayNativeBindProof -> ProofTupleAuthorityStackTypedProofRecycleThenCallback
                | _ -> ProofTupleAuthorityStackTypedProofNativeCallback
            else ProofTupleAuthorityStackMissingWitness

        let nativeCallbackCommitmentFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeCallbackCommitmentCyclePoisonPromise tuple.witness.kind
                | _ -> NativeCallbackCommitmentIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeCallbackCommitmentPromiseBind tuple.witness.ivar

        let compactObserverEnvelopeFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessJoinWaitDriverPromiseProof -> CompactObserverEnvelopeJoinWaitKeyPayloadIvarFill
            | WitnessParentCacheHandoffWakeProof
            | WitnessParentReplayStatusPreservedCacheHandoffProof
            | WitnessCooperativeReplayNativeBindProof -> CompactObserverEnvelopeCacheHandoffPayloadPromiseNext
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof -> CompactObserverEnvelopeHardPoisonPayloadWitnessIvar
            | _ when pendingGraphProofTupleComplete tuple -> CompactObserverEnvelopeProofTupleOnly
            | _ -> CompactObserverEnvelopeFullOnceThenKeyedDelta

        let nativeInlineCallbackCutoverFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> NativeInlineCallbackCutoverCyclePoison tuple.witness.kind
                | _ -> NativeInlineCallbackCutoverIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeInlineCallbackCutoverJobBind tuple.witness.ivar

        let legacyObserverTopologyFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> LegacyObserverTopologySeveredByCyclePoison
                | _ -> LegacyObserverTopologySeveredByInlineIvarFill
            else LegacyObserverTopologySeveredByNativePromiseBind

        let witnessRoutingLatticeFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof -> WitnessRoutingLatticeCyclePoison tuple.witness.kind
                | _ -> WitnessRoutingLatticeImmediateFill (tuple.witness.kind, tuple.witness.ivar)
            else WitnessRoutingLatticePromiseBind (tuple.witness.kind, tuple.witness.ivar)

        let proofTupleAuthorityClosureText (tuple: PendingGraphProofTuple) =
            sprintf "stack=%s|callback=%s|inline_cutover=%s|topology=%s|compact=%s|hud=severed|legacy=topologically_inaccessible"
                (proofTupleAuthorityStackText (proofTupleAuthorityStackFor tuple))
                (nativeCallbackCommitmentText (nativeCallbackCommitmentFor tuple))
                (nativeInlineCallbackCutoverText (nativeInlineCallbackCutoverFor tuple))
                (legacyObserverTopologyText (legacyObserverTopologyFor tuple))
                (compactObserverEnvelopeText (compactObserverEnvelopeFor tuple))

        type ProofTupleWakeAuthorityId =
            | ProofTupleWakeApplySpineStoreDirect
            | ProofTupleWakeSemanticStaleRetarget
            | ProofTupleWakeDynamicRecordKeyBridgeTail
            | ProofTupleWakeIdleCrossKindSidecarDrain
            | ProofTupleWakeParentReplayCycleBreakPoison
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill
            | ProofTupleWakePendingGraphCommittedTerminal

        let private proofTupleWakeSanitizeTargetKey (targetKey: string) =
            if System.String.IsNullOrWhiteSpace targetKey then "frontier_unknown"
            else targetKey.Replace("\"", "'").Replace("\\", "/")

        let private proofTupleWakeExtractValue (marker: string) (targetKey: string) =
            let target = proofTupleWakeSanitizeTargetKey targetKey
            let ix = target.IndexOf(marker, System.StringComparison.OrdinalIgnoreCase)
            if ix < 0 then ""
            else
                let start = ix + marker.Length
                let mutable stop = target.Length
                for ch in [|',';')';']';'|';' '|] do
                    let j = target.IndexOf(ch, start)
                    if j >= 0 && j < stop then stop <- j
                target.Substring(start, max 0 (stop - start))

        let private proofTupleWakeNodeFromHashSuffix (targetKey: string) =
            let target = proofTupleWakeSanitizeTargetKey targetKey
            let hashIx = target.LastIndexOf("#", System.StringComparison.Ordinal)
            if hashIx >= 0 && hashIx + 1 < target.Length then target.Substring(hashIx + 1) else ""

        let private proofTupleWakeIvarRegistryText = function
            | ProofTupleWakeApplySpineStoreDirect -> "metronome_terminal_authority:apply_spine_store_direct"
            | ProofTupleWakeSemanticStaleRetarget -> "metronome_terminal_authority:semantic_stale_retarget"
            | ProofTupleWakeDynamicRecordKeyBridgeTail -> "metronome_terminal_authority:dynamic_record_key_bridge_commit"
            | ProofTupleWakeIdleCrossKindSidecarDrain -> "metronome_terminal_authority:idle_cross_kind_terminal_commit"
            | ProofTupleWakeParentReplayCycleBreakPoison -> "metronome_terminal_authority:parent_replay_poison_live_tail"
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill -> "metronome_terminal_authority:no_root_budget_parent_replay_immediate_fill"
            | ProofTupleWakePendingGraphCommittedTerminal -> "metronome_terminal_authority:pending_graph_committed_terminal"

        let private proofTupleWakeTargetNodeToken authority targetKey =
            let child = proofTupleWakeExtractValue "child=" targetKey
            let node = proofTupleWakeExtractValue "node=" targetKey
            let owner = proofTupleWakeExtractValue "owner=" targetKey
            let suffix = proofTupleWakeNodeFromHashSuffix targetKey
            let structural = if child <> "" then child elif node <> "" then node elif owner <> "" then owner elif suffix <> "" then suffix else ""
            if structural <> "" then structural
            else
                let raw = proofTupleWakeIvarRegistryText authority + "|" + proofTupleWakeSanitizeTargetKey targetKey
                string (hash raw &&& System.Int32.MaxValue)

        let private proofTupleWakeTopologyEdgeText authority targetKey =
            let target = proofTupleWakeSanitizeTargetKey targetKey
            let owner = proofTupleWakeExtractValue "owner=" targetKey
            let child = proofTupleWakeExtractValue "child=" targetKey
            let node = proofTupleWakeExtractValue "node=" targetKey
            let targetNode = proofTupleWakeTargetNodeToken authority targetKey
            let ownerText =
                if owner <> "" then owner
                elif target <> "" && target <> "frontier_unknown" then target
                elif node <> "" then node
                elif targetNode <> "" then targetNode
                else "UNKNOWN_OWNER"
            let childText = if child <> "" then child else targetNode
            "owner=" + ownerText + "->child=" + childText + "|target=" + target

        let private proofTupleWakeStructuralNodeIdText authority targetKey =
            "IVar_for_Node_" + proofTupleWakeTargetNodeToken authority targetKey

        let private proofTupleWakePromiseIdText authority targetKey =
            "Promise_for_Node_" + proofTupleWakeTargetNodeToken authority targetKey

        let private proofTupleWakeContinuationBindingTargetsText authority targetKey =
            let edge = proofTupleWakeTopologyEdgeText authority targetKey
            match authority with
            | ProofTupleWakeApplySpineStoreDirect -> "[ApplySpineStoreDirectConsumer(" + edge + ");ParentContinuationCell(" + edge + ");PendingGraphTerminalConsumer(" + edge + ")]"
            | ProofTupleWakeSemanticStaleRetarget -> "[RootCompleteLiveReplay(" + edge + ");IdleCrossKindSidecarDrain(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | ProofTupleWakeDynamicRecordKeyBridgeTail -> "[DynamicBridgeParentContinuation(" + edge + ");DynamicJoinApplyReplay(" + edge + ");WriterlessQueueDrain(" + edge + ")]"
            | ProofTupleWakeIdleCrossKindSidecarDrain -> "[TySidecarDrainContinuation(" + edge + ");CrossKindSiblingReplay(" + edge + ");ParentContinuationCell(" + edge + ")]"
            | ProofTupleWakeParentReplayCycleBreakPoison -> "[ParentReplayPoisonContinuation(" + edge + ");CycleBreakConsumer(" + edge + ")]"
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill -> "[NoRootBudgetParentReplayJobBind(" + edge + ");ParentReplayCycleBreakConsumer(" + edge + ");ContinuationCellWake(" + edge + ")]"
            | ProofTupleWakePendingGraphCommittedTerminal -> "[PendingGraphTerminalConsumer(" + edge + ")]"

        type ProofTupleWakeBindingStateId =
            | ProofTupleWakeBoundParentContinuationTargets
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired
            | ProofTupleWakeUnboundTopologicalIsland

        let private proofTupleWakeBindingStateText = function
            | ProofTupleWakeBoundParentContinuationTargets -> "bound_parent_continuation_targets"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> "partial_owner_identity_parent_bind_probe_required"
            | ProofTupleWakeUnboundTopologicalIsland -> "unbound_topological_island"

        let private proofTupleWakeFateText = function
            | ProofTupleWakeBoundParentContinuationTargets -> "native_fill_wakes_parent_job_bind_cascade"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> "native_fill_requires_parent_binding_identity_repair"
            | ProofTupleWakeUnboundTopologicalIsland -> "native_fill_executed_but_no_parent_job_bind_listener"

        let private proofTupleWakeContinuationBindingCount authority targetKey =
            let listeners = proofTupleWakeContinuationBindingTargetsText authority targetKey
            let target = proofTupleWakeSanitizeTargetKey targetKey
            if target = "frontier_unknown" || target.Contains("[ERASED_IDENTITY]", System.StringComparison.OrdinalIgnoreCase) then 0
            elif listeners.Contains(";", System.StringComparison.Ordinal) then listeners.Split([|';'|], System.StringSplitOptions.RemoveEmptyEntries).Length else 1

        let private proofTupleWakeBindingStateId authority targetKey =
            let count = proofTupleWakeContinuationBindingCount authority targetKey
            let listeners = proofTupleWakeContinuationBindingTargetsText authority targetKey
            if count <= 0 then ProofTupleWakeUnboundTopologicalIsland
            elif listeners.Contains("UNKNOWN_OWNER", System.StringComparison.OrdinalIgnoreCase) then ProofTupleWakePartialOwnerIdentityParentBindProbeRequired
            else ProofTupleWakeBoundParentContinuationTargets

        let private proofTupleWakeRepairActionText bindingState activeParentProbePresent =
            match bindingState, activeParentProbePresent with
            | ProofTupleWakeBoundParentContinuationTargets, _ -> "parent_promise_binding_resolved_from_wake_edge"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, true -> "graft_active_worker_as_parent_promise_listener"
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, false -> "materialize_missing_parent_job_bind_listener"
            | ProofTupleWakeUnboundTopologicalIsland, true -> "graft_active_worker_as_parent_promise_listener"
            | ProofTupleWakeUnboundTopologicalIsland, false -> "materialize_missing_parent_job_bind_listener"

        type ProofTupleParentJobBindMaterializationId =
            | ProofTupleParentJobBindAlreadyMaterialized
            | ProofTupleParentJobBindGraftFromWakeAuthority
            | ProofTupleParentJobBindMaterializeMissingConsumer

        let private proofTupleParentJobBindMaterializationText = function
            | ProofTupleParentJobBindAlreadyMaterialized -> "parent_job_bind_already_materialized"
            | ProofTupleParentJobBindGraftFromWakeAuthority -> "graft_parent_job_bind_from_proof_tuple_wake_authority"
            | ProofTupleParentJobBindMaterializeMissingConsumer -> "materialize_missing_parent_job_bind_consumer"

        let private proofTupleParentJobBindMaterializationFor authority bindingState =
            match authority, bindingState with
            | _, ProofTupleWakeBoundParentContinuationTargets -> ProofTupleParentJobBindAlreadyMaterialized
            | ProofTupleWakeNoRootBudgetParentReplayImmediateFill, _ -> ProofTupleParentJobBindGraftFromWakeAuthority
            | _, ProofTupleWakePartialOwnerIdentityParentBindProbeRequired -> ProofTupleParentJobBindGraftFromWakeAuthority
            | _, ProofTupleWakeUnboundTopologicalIsland -> ProofTupleParentJobBindMaterializeMissingConsumer

        let private proofTupleParentJobBindContractText materialization edge bindTarget promiseId =
            "materialization=" + proofTupleParentJobBindMaterializationText materialization + "|edge=" + edge + "|bind_target=" + bindTarget + "|wake_promise=" + promiseId + "|return=Job.bind->Job.unit"

        type ProofTupleParentJobBindExecutionId =
            | ProofTupleParentJobBindExecutionNotRequired
            | ProofTupleParentJobBindExecuteWakeAuthority
            | ProofTupleParentJobBindExecuteMissingConsumer

        let private proofTupleParentJobBindExecutionFor = function
            | ProofTupleParentJobBindAlreadyMaterialized -> ProofTupleParentJobBindExecutionNotRequired
            | ProofTupleParentJobBindGraftFromWakeAuthority -> ProofTupleParentJobBindExecuteWakeAuthority
            | ProofTupleParentJobBindMaterializeMissingConsumer -> ProofTupleParentJobBindExecuteMissingConsumer

        let private proofTupleParentJobBindExecutionText = function
            | ProofTupleParentJobBindExecutionNotRequired -> "parent_job_bind_execution_not_required"
            | ProofTupleParentJobBindExecuteWakeAuthority -> "execute_job_bind_from_proof_tuple_wake_authority"
            | ProofTupleParentJobBindExecuteMissingConsumer -> "execute_job_bind_for_missing_parent_consumer"

        let private proofTupleParentJobBindExecutionClosureText execution bindTarget promiseId =
            match execution with
            | ProofTupleParentJobBindExecutionNotRequired -> "none:parent_job_bind_already_materialized"
            | _ -> "Job.bind(" + bindTarget + ")->" + promiseId + "|schedule=native_direct_ast_eval_before_any_polling_boundary|return=Job.unit"

        let private proofTupleParentJobBindRecyclePolicyText execution =
            match execution with
            | ProofTupleParentJobBindExecutionNotRequired -> "retain_cadence_after_existing_bind"
            | _ -> "emit_first_bind_execution_then_hud_only_until_delta"

        type ProofTupleParentJobBindGraftStatusId =
            | ProofTupleParentJobBindGraftMaterialized
            | ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleParentJobBindGraftNoDeltaAfterGraft
            | ProofTupleParentJobBindGraftUnboundIsland

        let private proofTupleParentJobBindGraftStatusFor (bindingState: ProofTupleWakeBindingStateId) (execution: ProofTupleParentJobBindExecutionId) =
            match bindingState, execution with
            | ProofTupleWakeBoundParentContinuationTargets, ProofTupleParentJobBindExecutionNotRequired -> ProofTupleParentJobBindGraftMaterialized
            | ProofTupleWakeBoundParentContinuationTargets, _ -> ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleWakePartialOwnerIdentityParentBindProbeRequired, _ -> ProofTupleParentJobBindGraftPendingForceReplay
            | ProofTupleWakeUnboundTopologicalIsland, _ -> ProofTupleParentJobBindGraftUnboundIsland

        let private proofTupleParentJobBindGraftStatusText = function
            | ProofTupleParentJobBindGraftMaterialized -> "materialized"
            | ProofTupleParentJobBindGraftPendingForceReplay -> "pending_force_replay"
            | ProofTupleParentJobBindGraftNoDeltaAfterGraft -> "no_delta_after_graft"
            | ProofTupleParentJobBindGraftUnboundIsland -> "unbound_island"

        // ALPHA1661: proof-tuple hot rows now mirror the runtime HUD path with
        // typed expected-delta and continuation-status DUs instead of rechecking
        // string literals when deciding graft repair, consumer delta and direct
        // evaluation contracts.
        type ProofTupleWakeExpectedDeltaId =
            | ProofTupleWakeExpectedDeltaNone
            | ProofTupleWakeExpectedDeltaApplySpineStore
            | ProofTupleWakeExpectedDeltaPendingGraphTerminal
            | ProofTupleWakeExpectedDeltaParentContinuation
            | ProofTupleWakeExpectedDeltaCrossKindSibling
            | ProofTupleWakeExpectedDeltaSidecarDrain
            | ProofTupleWakeExpectedDeltaGraftRepair

        let private proofTupleExpectedDeltaFor (targetsText: string) (bindingState: ProofTupleWakeBindingStateId) =
            if bindingState = ProofTupleWakeUnboundTopologicalIsland then ProofTupleWakeExpectedDeltaNone
            elif targetsText.Contains("ApplySpineStoreDirectConsumer", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaApplySpineStore
            elif targetsText.Contains("PendingGraphTerminalConsumer", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaPendingGraphTerminal
            elif targetsText.Contains("ObservedPinnedParentContinuation", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaParentContinuation
            elif targetsText.Contains("TySidecarDrainContinuation", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaSidecarDrain
            elif targetsText.Contains("CrossKindSiblingReplay", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaCrossKindSibling
            elif targetsText.Contains("ParentContinuationCell", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaParentContinuation
            elif targetsText.Contains("ParentBindingProbe", System.StringComparison.Ordinal) then ProofTupleWakeExpectedDeltaGraftRepair
            else ProofTupleWakeExpectedDeltaNone

        let private proofTupleExpectedDeltaText = function
            | ProofTupleWakeExpectedDeltaNone -> "none"
            | ProofTupleWakeExpectedDeltaApplySpineStore -> "apply_spine_store_delta_expected"
            | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> "pending_graph_terminal_delta_expected"
            | ProofTupleWakeExpectedDeltaParentContinuation -> "parent_continuation_delta_expected"
            | ProofTupleWakeExpectedDeltaCrossKindSibling -> "cross_kind_sibling_delta_expected"
            | ProofTupleWakeExpectedDeltaSidecarDrain -> "sidecar_drain_delta_expected"
            | ProofTupleWakeExpectedDeltaGraftRepair -> "graft_repair_delta_expected"

        type ProofTupleContinuationTargetStatusId =
            | ProofTupleTargetApplySpineStore
            | ProofTupleTargetPendingGraphTerminal
            | ProofTupleTargetRunnableParentContinuation
            | ProofTupleTargetWaitingCrossKind
            | ProofTupleTargetSidecarDrain
            | ProofTupleTargetPoisoned
            | ProofTupleTargetUnknown

        let private proofTupleContinuationTargetStatusFor (targetsText: string) =
            if targetsText.Contains("ParentReplayPoison", System.StringComparison.Ordinal) || targetsText.Contains("CycleBreak", System.StringComparison.Ordinal) then ProofTupleTargetPoisoned
            elif targetsText.Contains("ApplySpineStoreDirectConsumer", System.StringComparison.Ordinal) then ProofTupleTargetApplySpineStore
            elif targetsText.Contains("PendingGraphTerminalConsumer", System.StringComparison.Ordinal) then ProofTupleTargetPendingGraphTerminal
            elif targetsText.Contains("CrossKindSiblingReplay", System.StringComparison.Ordinal) then ProofTupleTargetWaitingCrossKind
            elif targetsText.Contains("TySidecarDrainContinuation", System.StringComparison.Ordinal) then ProofTupleTargetSidecarDrain
            elif targetsText.Contains("ParentContinuationCell", System.StringComparison.Ordinal) then ProofTupleTargetRunnableParentContinuation
            else ProofTupleTargetUnknown

        let private proofTupleContinuationTargetStatusText = function
            | ProofTupleTargetApplySpineStore -> "apply_spine_store_direct"
            | ProofTupleTargetPendingGraphTerminal -> "pending_graph_terminal"
            | ProofTupleTargetRunnableParentContinuation -> "runnable_parent_continuation"
            | ProofTupleTargetWaitingCrossKind -> "waiting_cross_kind"
            | ProofTupleTargetSidecarDrain -> "sidecar_drain"
            | ProofTupleTargetPoisoned -> "poisoned"
            | ProofTupleTargetUnknown -> "unknown"

        let private proofTupleWakeGraphText authority targetKey =
            let nodeId = proofTupleWakeStructuralNodeIdText authority targetKey
            "IVar[Node:" + nodeId + "] filled -> Unblocked Continuations: " + proofTupleWakeContinuationBindingTargetsText authority targetKey

        let private proofTupleWakeTopologicalDisconnectProbeText authority targetKey =
            let listeners = proofTupleWakeContinuationBindingTargetsText authority targetKey
            let target = proofTupleWakeSanitizeTargetKey targetKey
            if target = "frontier_unknown" || target.Contains("[ERASED_IDENTITY]", System.StringComparison.OrdinalIgnoreCase) then "wake_graph_unbound_or_erased_identity"
            elif listeners.Contains("UNKNOWN_OWNER", System.StringComparison.OrdinalIgnoreCase) then "wake_graph_partial_owner_identity_requires_parent_bind_probe"
            else "wake_graph_has_structural_continuation_targets"

        let proofTupleWakeMetronomeAuthorityFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessSemanticStaleRetargetProof -> ProofTupleWakeSemanticStaleRetarget
            | WitnessDynamicJoinBridgeTailProof
            | WitnessDynamicRecordKeyBridgeCommitProof -> ProofTupleWakeDynamicRecordKeyBridgeTail
            | WitnessIdleCrossKindSidecarDrainProof -> ProofTupleWakeIdleCrossKindSidecarDrain
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessParentReplayPoisonLiveTailProof -> ProofTupleWakeParentReplayCycleBreakPoison
            | WitnessNoRootBudgetParentReplayImmediateFillProof -> ProofTupleWakeNoRootBudgetParentReplayImmediateFill
            | _ -> ProofTupleWakePendingGraphCommittedTerminal

        let pendingGraphProofTupleJsonFields tuple =
            let matrix = proofTupleMatrixStatusFor tuple
            let authorityDecision = proofTupleAuthorityDecisionFor tuple
            let compactProjection = proofTupleCompactProjectionFor tuple
            let authorityStack = proofTupleAuthorityStackFor tuple
            let callbackCommitment = nativeCallbackCommitmentFor tuple
            let compactEnvelope = compactObserverEnvelopeFor tuple
            let authorityClosure = proofTupleAuthorityClosureText tuple
            let inlineCutover = nativeInlineCallbackCutoverFor tuple
            let legacyTopology = legacyObserverTopologyFor tuple
            let witnessRoutingLattice = witnessRoutingLatticeFor tuple
            let executionClosure = proofTupleExecutionClosureFor tuple
            let activeClosure = activeNativeCallbackClosureFor tuple
            let nativeCallbackControlFlowGateText =
                if pendingGraphProofTupleComplete tuple then
                    "proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_Job.unit->legacy_unreachable"
                else
                    "proof_tuple_incomplete->Job.bind_existing_promise_before_legacy_observer"
            let nativePromiseIdentifier = nativePromiseIdentifierFor tuple
            let workerReturnTopology = workerReturnTopologyFor tuple
            let nativeRunQueueCommit = nativeRunQueueCommitFor tuple
            let readinessGateText = if pendingGraphProofTupleComplete tuple then "inline_ivar_fill_ready" else "native_promise_bind_ready"
            let callbackRouteText =
                if pendingGraphProofTupleComplete tuple then
                    "IVar.fill(" + nativeHopacIvarRegistryText tuple.witness.ivar + "," + parentContinuationFillStrategyText tuple.fillStrategy + ")"
                else "Job.bind(Promise(" + nativeHopacIvarRegistryText tuple.witness.ivar + "))"
            let deprecatedPollingText =
                match tuple.witness.kind with
                | WitnessParentReplayCycleBreakPoisonImmediateFillProof
                | WitnessCrossKindYieldThrashHardPoisonProof
                | WitnessHardPoisonObligationCapProof
                | WitnessParentReplayStatusPreservedCacheHandoffProof
                | WitnessNoRootBudgetParentReplayImmediateFillProof
                | WitnessCooperativeReplayNativeBindProof
                | WitnessSemanticStaleRetargetProof
                | WitnessTyGlobalFuseParentContinuationProof
                | WitnessIdleCrossKindSidecarDrainProof
                | WitnessJoinWaitDriverPromiseProof -> "recycle_qap_recent_sample_term_age_delta_replay"
                | WitnessMetronomeTerminalAuthorityProof -> "compact_polling_fields_after_witness"
                | _ -> "retain_full_fields_for_first_emission"
            let criticalNodeText =
                sprintf "payload=%s|witness=%s|ivar=%s|callback=%s|gate=%s|recycle=%s"
                    tuple.witness.payload
                    (terminalWitnessKindText tuple.witness.kind)
                    (nativeHopacIvarRegistryText tuple.witness.ivar)
                    callbackRouteText
                    readinessGateText
                    deprecatedPollingText
            let hotProjectionText = hotRowAuthorityProjectionText (HotRowProjectionReplayDriverSurface tuple.witness.kind)
            let wakeAuthority = proofTupleWakeMetronomeAuthorityFor tuple
            let wakeTargetKey = tuple.witness.cycleRootOrigin
            let wakeNodeId = proofTupleWakeStructuralNodeIdText wakeAuthority wakeTargetKey
            let wakePromiseId = proofTupleWakePromiseIdText wakeAuthority wakeTargetKey
            let wakeTargets = proofTupleWakeContinuationBindingTargetsText wakeAuthority wakeTargetKey
            let wakeCount = proofTupleWakeContinuationBindingCount wakeAuthority wakeTargetKey
            let wakeBindingStateId = proofTupleWakeBindingStateId wakeAuthority wakeTargetKey
            let wakeBindingState = wakeBindingStateId |> proofTupleWakeBindingStateText
            let wakeFate = wakeBindingStateId |> proofTupleWakeFateText
            let wakeRepair = proofTupleWakeRepairActionText wakeBindingStateId (wakeCount > 0)
            let wakeGraph = proofTupleWakeGraphText wakeAuthority wakeTargetKey
            let wakeProbe = proofTupleWakeTopologicalDisconnectProbeText wakeAuthority wakeTargetKey
            let parentJobBindMaterializationId = proofTupleParentJobBindMaterializationFor wakeAuthority wakeBindingStateId
            let parentJobBindMaterializationText = proofTupleParentJobBindMaterializationText parentJobBindMaterializationId
            let parentJobBindWakeConsumerText = "Job.bind(" + wakeTargets + ")->" + wakePromiseId
            let parentJobBindGraftContractText = proofTupleParentJobBindContractText parentJobBindMaterializationId (proofTupleWakeTopologyEdgeText wakeAuthority wakeTargetKey) wakeTargets wakePromiseId
            let parentJobBindExecutionId = proofTupleParentJobBindExecutionFor parentJobBindMaterializationId
            let parentJobBindExecutionText = proofTupleParentJobBindExecutionText parentJobBindExecutionId
            let parentJobBindExecutionClosureText = proofTupleParentJobBindExecutionClosureText parentJobBindExecutionId wakeTargets wakePromiseId
            let parentJobBindRecyclePolicyText = proofTupleParentJobBindRecyclePolicyText parentJobBindExecutionId
            let parentJobBindGraftStatusId = proofTupleParentJobBindGraftStatusFor wakeBindingStateId parentJobBindExecutionId
            let parentJobBindGraftStatusText = proofTupleParentJobBindGraftStatusText parentJobBindGraftStatusId
            let wakeExpectedDeltaId = proofTupleExpectedDeltaFor wakeTargets wakeBindingStateId
            let wakeExpectedDeltaText = proofTupleExpectedDeltaText wakeExpectedDeltaId
            let wakeExpectedDeltaFlag = wakeExpectedDeltaId <> ProofTupleWakeExpectedDeltaNone
            let continuationTargetStatusId = proofTupleContinuationTargetStatusFor wakeTargets
            let continuationTargetStatusText = proofTupleContinuationTargetStatusText continuationTargetStatusId
            let wakeConsumerDeltaResultText =
                if wakeExpectedDeltaFlag then "consumer_expected_delta_but_deferred"
                elif continuationTargetStatusId = ProofTupleTargetPoisoned then "consumer_poison_only_no_structural_delta"
                else "consumer_delta_not_expected"
            let crossKindObligationDetailText =
                match wakeExpectedDeltaId with
                | ProofTupleWakeExpectedDeltaApplySpineStore -> "apply_spine_store_owns_window"
                | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> "pending_graph_terminal_owns_window"
                | ProofTupleWakeExpectedDeltaSidecarDrain -> "sidecar_drain_owns_window"
                | ProofTupleWakeExpectedDeltaCrossKindSibling -> "cross_kind_sibling_waiting"
                | ProofTupleWakeExpectedDeltaParentContinuation -> "parent_continuation_pending"
                | ProofTupleWakeExpectedDeltaGraftRepair -> "graft_repair_owns_window"
                | ProofTupleWakeExpectedDeltaNone when parentJobBindGraftStatusId = ProofTupleParentJobBindGraftPendingForceReplay -> "graft_repair_owns_window"
                | _ -> "none"
            let nativeDirectEvaluationContractText =
                match wakeExpectedDeltaId with
                | ProofTupleWakeExpectedDeltaApplySpineStore -> "native_direct_ast_eval_apply_spine_store_return_job_unit"
                | ProofTupleWakeExpectedDeltaPendingGraphTerminal -> "native_direct_ast_eval_pending_graph_terminal_return_job_unit"
                | ProofTupleWakeExpectedDeltaParentContinuation -> "native_direct_ast_eval_parent_continuation_return_job_unit"
                | ProofTupleWakeExpectedDeltaSidecarDrain
                | ProofTupleWakeExpectedDeltaCrossKindSibling -> "native_direct_ast_eval_cross_kind_sidecar_return_job_unit"
                | ProofTupleWakeExpectedDeltaGraftRepair -> "native_direct_ast_eval_dynamic_join_apply_return_job_unit"
                | ProofTupleWakeExpectedDeltaNone -> "none"
            let noWorkAbortOverrideReasonText = if wakeExpectedDeltaFlag then "bound_wake_expected_delta" else "proof_tuple_complete_recycle_not_abort"
            let payloadProbeText = "payload=" + tuple.witness.payload + "|witness=" + terminalWitnessKindText tuple.witness.kind + "|edge=" + proofTupleWakeTopologyEdgeText wakeAuthority wakeTargetKey
            let causalityChainText = "fill(" + wakeNodeId + ")->" + continuationTargetStatusText + "->consumer=" + wakeConsumerDeltaResultText + "->expected=" + wakeExpectedDeltaText + "->graft=" + parentJobBindGraftStatusText + "->contract=" + nativeDirectEvaluationContractText
            sprintf ",\"hopac_ivar_registry_id\":%s,\"hopac_ivar_resolution_edge\":%s,\"witness_type\":%s,\"cycle_root_origin\":%s,\"terminal_commit_class_du\":%s,\"pending_graph_mailbox_batch_summary\":%s,\"terminal_witness_envelope_du\":%s,\"parent_continuation_fill_strategy_du\":%s,\"qap_authority_du\":%s,\"legacy_veto_quarantine_du\":%s,\"raw_key_deprecated\":%b,\"proof_tuple_complete\":%b,\"native_hopac_alt_timeout_ms\":%d,\"shadow_timeout_bypassed_by_witness\":%b,\"proof_tuple_matrix_du\":%s,\"native_hopac_promise_state_du\":%s,\"hot_row_recycle_policy_du\":%s,\"critical_path_du\":%s,\"repeat_cap_authority_du\":\"observer_only_after_witness_tuple\",\"witness_clear_readiness_gate_du\":%s,\"native_hopac_callback_route_du\":%s,\"eval_worklist_hud_frontier_authority_du\":\"quarantined_after_typed_proof_tuple\",\"deprecated_polling_fields_du\":%s,\"proof_tuple_critical_path_node_du\":%s,\"proof_tuple_authority_decision_du\":%s,\"proof_tuple_compact_projection_du\":%s,\"proof_tuple_authority_stack_du\":%s,\"native_callback_commitment_du\":%s,\"compact_observer_envelope_du\":%s,\"proof_tuple_authority_closure_du\":%s,\"hot_row_authority_projection_du\":%s,\"native_inline_callback_cutover_du\":%s,\"legacy_observer_topology_du\":%s,\"witness_routing_lattice_du\":%s,\"commit_pathway_trace_du\":%s,\"native_promise_identifier_du\":%s,\"worker_return_topology_du\":%s,\"native_run_queue_commit_du\":%s,\"proof_tuple_execution_closure_du\":%s,\"active_native_callback_closure_du\":%s,\"native_callback_control_flow_gate_du\":%s,\"callback_tracer_du\":%s,\"native_hopac_ivar_memory_identity_du\":%s,\"native_hopac_promise_id\":%s,\"continuation_binding_targets_du\":%s,\"continuation_binding_target_count\":%d,\"parent_job_bind_materialization_du\":%s,\"parent_job_bind_wake_consumer_du\":%s,\"parent_job_bind_graft_contract_du\":%s,\"parent_job_bind_execution_du\":%s,\"parent_job_bind_execution_closure_du\":%s,\"parent_job_bind_jsonl_recycle_policy_du\":%s,\"parent_job_bind_graft_status_du\":%s,\"expected_work_delta_from_wake_graph\":%b,\"wake_graph_expected_delta_du\":%s,\"continuation_target_status_du\":%s,\"wake_consumer_delta_result_du\":%s,\"cross_kind_obligation_detail_du\":%s,\"native_direct_evaluation_contract_du\":%s,\"no_work_abort_override_reason_du\":%s,\"resolution_payload_probe_du\":%s,\"wake_graph_causality_chain_du\":%s,\"wake_binding_repair_action_du\":%s,\"wake_graph_du\":%s,\"wake_graph_binding_state_du\":%s,\"wake_graph_native_fate_du\":%s,\"topological_disconnect_probe_du\":%s,\"thread_fate_du\":\"native_hopac_run_queue_after_inline_callback\",\"eval_worklist_boundary_reachable_after_callback\":false,\"legacy_polling_metrics_observer_only\":true,\"qap_observer_policy_du\":\"observer_only_after_proof_tuple_complete\",\"eval_worklist_hud_frontier_yield_path_du\":\"topologically_severed_after_proof_tuple\",\"legacy_live_tail_veto_reachable\":false"
                (DiagJson.esc (nativeHopacIvarRegistryText tuple.witness.ivar))
                (DiagJson.esc (nativeHopacIvarRegistryText tuple.witness.ivar + "->" + terminalCommitClassText tuple.commitClass))
                (DiagJson.esc (terminalWitnessKindText tuple.witness.kind))
                (DiagJson.esc tuple.witness.cycleRootOrigin)
                (DiagJson.esc (terminalCommitClassText tuple.commitClass))
                (DiagJson.esc (pendingGraphMailboxBatchSummaryText tuple.mailboxBatch))
                (DiagJson.esc (terminalWitnessEnvelopeText tuple.witness))
                (DiagJson.esc (parentContinuationFillStrategyText tuple.fillStrategy))
                (DiagJson.esc (qapAuthorityText tuple.qapAuthority))
                (DiagJson.esc (legacyVetoQuarantineText tuple.legacyVeto))
                tuple.rawKeyDeprecated
                (pendingGraphProofTupleComplete tuple)
                tuple.shadowTimeoutMs
                (pendingGraphProofTupleComplete tuple && (tuple.shadowTimeoutMs = 0))
                (DiagJson.esc (proofTupleMatrixText matrix))
                (DiagJson.esc (nativeHopacPromiseStateText matrix.promiseState))
                (DiagJson.esc (hotRowRecyclePolicyText matrix.recyclePolicy))
                (DiagJson.esc (proofTupleCriticalPathText tuple))
                (DiagJson.esc readinessGateText)
                (DiagJson.esc callbackRouteText)
                (DiagJson.esc deprecatedPollingText)
                (DiagJson.esc criticalNodeText)
                (DiagJson.esc (proofTupleAuthorityDecisionText authorityDecision))
                (DiagJson.esc (proofTupleCompactProjectionText compactProjection))
                (DiagJson.esc (proofTupleAuthorityStackText authorityStack))
                (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment))
                (DiagJson.esc (compactObserverEnvelopeText compactEnvelope))
                (DiagJson.esc authorityClosure)
                (DiagJson.esc hotProjectionText)
                (DiagJson.esc (nativeInlineCallbackCutoverText inlineCutover))
                (DiagJson.esc (legacyObserverTopologyText legacyTopology))
                (DiagJson.esc (witnessRoutingLatticeText witnessRoutingLattice))
                (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment))
                (DiagJson.esc (nativePromiseIdentifierText nativePromiseIdentifier))
                (DiagJson.esc (workerReturnTopologyText workerReturnTopology))
                (DiagJson.esc (nativeRunQueueCommitText nativeRunQueueCommit))
                (DiagJson.esc (proofTupleExecutionClosureText executionClosure))
                (DiagJson.esc (activeNativeCallbackClosureText activeClosure))
                (DiagJson.esc nativeCallbackControlFlowGateText)
                (DiagJson.esc (nativeCallbackCommitmentText callbackCommitment))
                (DiagJson.esc wakeNodeId)
                (DiagJson.esc wakePromiseId)
                (DiagJson.esc wakeTargets)
                wakeCount
                (DiagJson.esc parentJobBindMaterializationText)
                (DiagJson.esc parentJobBindWakeConsumerText)
                (DiagJson.esc parentJobBindGraftContractText)
                (DiagJson.esc parentJobBindExecutionText)
                (DiagJson.esc parentJobBindExecutionClosureText)
                (DiagJson.esc parentJobBindRecyclePolicyText)
                (DiagJson.esc parentJobBindGraftStatusText)
                wakeExpectedDeltaFlag
                (DiagJson.esc wakeExpectedDeltaText)
                (DiagJson.esc continuationTargetStatusText)
                (DiagJson.esc wakeConsumerDeltaResultText)
                (DiagJson.esc crossKindObligationDetailText)
                (DiagJson.esc nativeDirectEvaluationContractText)
                (DiagJson.esc noWorkAbortOverrideReasonText)
                (DiagJson.esc payloadProbeText)
                (DiagJson.esc causalityChainText)
                (DiagJson.esc wakeRepair)
                (DiagJson.esc wakeGraph)
                (DiagJson.esc wakeBindingState)
                (DiagJson.esc wakeFate)
                (DiagJson.esc wakeProbe)

        let witnessClearBypassesShadowTimeout tuple =
            pendingGraphProofTupleComplete tuple && (tuple.shadowTimeoutMs = 0)

        type EvalCell<'State,'Kind> = private {
            nodeId: NodeId<'Kind>
            payload: string
            witness: TerminalWitnessEnvelope option
            }

        module EvalCellOps =
            let unresolved nodeId payload : EvalCell<EvalCellUnresolved,'Kind> =
                { nodeId = nodeId; payload = payload; witness = None }

            let provideWitness witness (cell: EvalCell<EvalCellUnresolved,'Kind>) : EvalCell<EvalCellWitnessed,'Kind> =
                { nodeId = cell.nodeId; payload = cell.payload; witness = Some witness }

            let clear (cell: EvalCell<EvalCellWitnessed,'Kind>) : EvalCell<EvalCellCleared,'Kind> =
                { nodeId = cell.nodeId; payload = cell.payload; witness = cell.witness }

            let witnessTypeText (cell: EvalCell<_,_>) =
                match cell.witness with
                | Some witness -> terminalWitnessKindText witness.kind
                | None -> "none"

        type WitnessClearTransitionId =
            | WitnessClearNoPayload
            | WitnessClearMaterialized
            | WitnessClearWitnessed
            | WitnessClearFilledParentContinuation
            | WitnessClearLegacyVetoQuarantined

        let witnessClearTransitionText = function
            | WitnessClearNoPayload -> "Pending"
            | WitnessClearMaterialized -> "Materialized"
            | WitnessClearWitnessed -> "Witnessed"
            | WitnessClearFilledParentContinuation -> "Cleared"
            | WitnessClearLegacyVetoQuarantined -> "LegacyVetoQuarantined"

        type ReplayObligationTree<'Kind> =
            | ReplayObligationRoot
            | ReplayObligationParent of NodeId<'Kind>
            | ReplayObligationSibling of CacheKey<'Kind> * ReplayObligationTree<'Kind>

        let rec replayObligationTreeDepth = function
            | ReplayObligationRoot -> 0
            | ReplayObligationParent _ -> 1
            | ReplayObligationSibling (_, next) -> 1 + replayObligationTreeDepth next

        // ALPHA1617: recursive DU obligation graph.  This is the next bridge away
        // from typed_key strings: immediate-fill, sibling bridge and cycle poison
        // are constructors, while the phantom phase keeps Pending/Witnessed/Cleared
        // lanes separated for future native Hopac Job.bind cutover.
        type ReplayPendingPhase = interface end
        type ReplayWitnessedPhase = interface end
        type ReplayClearedPhase = interface end

        type NativeReplayObligation<'Kind,'Phase> =
            | NativeImmediateFill of owner: string * child: string * ivar: NativeHopacIvarRegistryId * fill: ParentContinuationFillStrategyId
            | NativeSiblingBridge of bridge: CacheKey<'Kind> * next: NativeReplayObligation<'Kind,'Phase>
            | NativeCyclePoison of witness: TerminalWitnessEnvelope
            | NativePromiseBind of ivar: NativeHopacIvarRegistryId * next: NativeReplayObligation<'Kind,'Phase>

        let rec nativeReplayObligationDepth = function
            | NativeImmediateFill _ -> 1
            | NativeCyclePoison _ -> 1
            | NativePromiseBind (_, next) -> 1 + nativeReplayObligationDepth next
            | NativeSiblingBridge (_, next) -> 1 + nativeReplayObligationDepth next

        let nativeReplayObligationText obligation =
            sprintf "native_replay_obligation_depth=%d" (nativeReplayObligationDepth obligation)

        // ALPHA1618: make the proof tuple an authority gate, not just a set of
        // JSON fields.  A complete tuple routes directly to a native Hopac callback
        // contract and explicitly demotes repeat caps, probation drains and HUD
        // frontier polling to observation-only.
        type ProofTupleAuthorityGateId =
            | ProofTupleAuthorityMissingWitness
            | ProofTupleAuthorityWitnessReady
            | ProofTupleAuthorityIvarFillReady
            | ProofTupleAuthorityLegacyBypassed
            | ProofTupleAuthorityHudPollingQuarantined

        let proofTupleAuthorityGateText = function
            | ProofTupleAuthorityMissingWitness -> "missing_witness"
            | ProofTupleAuthorityWitnessReady -> "witness_ready"
            | ProofTupleAuthorityIvarFillReady -> "ivar_fill_ready"
            | ProofTupleAuthorityLegacyBypassed -> "legacy_probation_bypassed"
            | ProofTupleAuthorityHudPollingQuarantined -> "eval_worklist_hud_frontier_quarantined"

        type NativeHopacCallbackRouteId =
            | NativeCallbackRouteNone
            | NativeCallbackRouteIvarFill of NativeHopacIvarRegistryId * ParentContinuationFillStrategyId
            | NativeCallbackRouteJobBindPromise of NativeHopacIvarRegistryId
            | NativeCallbackRouteCyclePoisonPromise of NativeHopacIvarRegistryId

        let nativeHopacCallbackRouteText = function
            | NativeCallbackRouteNone -> "none"
            | NativeCallbackRouteIvarFill (ivar,fill) -> "IVar.fill(" + nativeHopacIvarRegistryText ivar + "," + parentContinuationFillStrategyText fill + ")"
            | NativeCallbackRouteJobBindPromise ivar -> "Job.bind(Promise(" + nativeHopacIvarRegistryText ivar + "))"
            | NativeCallbackRouteCyclePoisonPromise ivar -> "CyclePoisonPromise(" + nativeHopacIvarRegistryText ivar + ")"

        type PollingFieldDeprecationId =
            | PollingFieldsRetainedForFirstFullEmission
            | PollingFieldsCompactAfterWitness
            | PollingFieldsRecycleQapRecentAndTermAge
            | PollingFieldsDropLegacyLiveTailAfterTuple

        let pollingFieldDeprecationText = function
            | PollingFieldsRetainedForFirstFullEmission -> "retain_full_fields_for_first_emission"
            | PollingFieldsCompactAfterWitness -> "compact_polling_fields_after_witness"
            | PollingFieldsRecycleQapRecentAndTermAge -> "recycle_qap_recent_sample_term_age_delta_replay"
            | PollingFieldsDropLegacyLiveTailAfterTuple -> "drop_legacy_live_tail_veto_after_tuple"

        let proofTupleAuthorityGateFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then ProofTupleAuthorityIvarFillReady
            else ProofTupleAuthorityWitnessReady

        let nativeHopacCallbackRouteFor (tuple: PendingGraphProofTuple) =
            if pendingGraphProofTupleComplete tuple then NativeCallbackRouteIvarFill (tuple.witness.ivar, tuple.fillStrategy)
            else NativeCallbackRouteJobBindPromise tuple.witness.ivar

        let pollingFieldDeprecationFor (tuple: PendingGraphProofTuple) =
            match tuple.witness.kind with
            | WitnessParentReplayCycleBreakPoisonImmediateFillProof
            | WitnessCrossKindYieldThrashHardPoisonProof
            | WitnessHardPoisonObligationCapProof
            | WitnessParentReplayStatusPreservedCacheHandoffProof
            | WitnessCooperativeReplayNativeBindProof
            | WitnessSemanticStaleRetargetProof
            | WitnessTyGlobalFuseParentContinuationProof
            | WitnessIdleCrossKindSidecarDrainProof
            | WitnessJoinWaitDriverPromiseProof -> PollingFieldsRecycleQapRecentAndTermAge
            | WitnessMetronomeTerminalAuthorityProof -> PollingFieldsCompactAfterWitness
            | _ -> PollingFieldsRetainedForFirstFullEmission

        type ProofTupleCriticalPathNode = {
            payload: string
            witness: TerminalWitnessKindId
            ivar: NativeHopacIvarRegistryId
            callback: NativeHopacCallbackRouteId
            gate: ProofTupleAuthorityGateId
            recycle: PollingFieldDeprecationId
            }

        let proofTupleCriticalPathNodeFor (tuple: PendingGraphProofTuple) : ProofTupleCriticalPathNode =
            { payload = tuple.witness.payload
              witness = tuple.witness.kind
              ivar = tuple.witness.ivar
              callback = nativeHopacCallbackRouteFor tuple
              gate = proofTupleAuthorityGateFor tuple
              recycle = pollingFieldDeprecationFor tuple }

        let proofTupleCriticalPathNodeText (node: ProofTupleCriticalPathNode) =
            sprintf "payload=%s|witness=%s|ivar=%s|callback=%s|gate=%s|recycle=%s"
                node.payload
                (terminalWitnessKindText node.witness)
                (nativeHopacIvarRegistryText node.ivar)
                (nativeHopacCallbackRouteText node.callback)
                (proofTupleAuthorityGateText node.gate)
                (pollingFieldDeprecationText node.recycle)

        // ALPHA1618: Church-style visitor scaffold for the next migration slice.
        // The payload remains a normal F# DU-backed record today, but consumers can
        // start depending on visitor methods instead of downcasting JSON strings.
        type IProofTupleVisitor<'Result> =
            abstract VisitParentReplayPoison : PendingGraphProofTuple -> 'Result
            abstract VisitCrossKindHardPoison : PendingGraphProofTuple -> 'Result
            abstract VisitDynamicJoin : PendingGraphProofTuple -> 'Result
            abstract VisitCacheOrFuse : PendingGraphProofTuple -> 'Result
            abstract VisitGeneric : PendingGraphProofTuple -> 'Result

        type IPendingGraphProof =
            abstract Apply<'Result> : IProofTupleVisitor<'Result> -> 'Result

        type PendingGraphProofBox(tuple: PendingGraphProofTuple) =
            member _.Tuple = tuple
            interface IPendingGraphProof with
                member _.Apply<'Result>(visitor: IProofTupleVisitor<'Result>) =
                    match tuple.witness.kind with
                    | WitnessParentReplayCycleBreakPoisonImmediateFillProof -> visitor.VisitParentReplayPoison tuple
                    | WitnessCrossKindYieldThrashHardPoisonProof -> visitor.VisitCrossKindHardPoison tuple
                    | WitnessDynamicJoinSymbolicCarrierProof
                    | WitnessDynamicJoinCooperativeAltTimeoutProof
                    | WitnessDynamicJoinBridgeTailProof -> visitor.VisitDynamicJoin tuple
                    | WitnessParentCacheHandoffWakeProof
                    | WitnessParentReplayStatusPreservedCacheHandoffProof
                    | WitnessCooperativeReplayNativeBindProof
                    | WitnessTyGlobalFuseParentContinuationProof -> visitor.VisitCacheOrFuse tuple
                    | _ -> visitor.VisitGeneric tuple

        // ALPHA1609: native-Hopac promise registry scaffold for the assessment HUD.
        // This gives the bottom HUD a typed source for the "top oldest unresolved IVars"
        // idea instead of rebuilding it from q/a/p strings.  It is still inert/shadow-only,
        // but every parent-continuation cycle row can now name the promise it would fill.
        type LivePromiseRegistrySlot<'Kind> = {
            slot: int
            ivar: NativeHopacIvarRegistryId
            obligation: ReplayObligationTree<'Kind>
            ageMs: int64
            awaitKind: string
            }

        type DeadlockDependencyEdge<'Kind> = {
            waiter: NodeId<'Kind>
            parent: NodeId<'Kind>
            reason: string
            fillStrategy: string
            }

        let livePromiseRegistrySlotText slot =
            sprintf "slot=%d|ivar=%s|obligation_depth=%d|age_ms=%d|await=%s"
                slot.slot
                (nativeHopacIvarRegistryText slot.ivar)
                (replayObligationTreeDepth slot.obligation)
                slot.ageMs
                slot.awaitKind

        let deadlockDependencyEdgeText edge =
            sprintf "waiter=%A<-parent=%A|reason=%s|fill=%s" edge.waiter edge.parent edge.reason edge.fillStrategy

        // ALPHA1549: first assessment-migration slice.  These DUs make the cooperative-yield
        // and cross-kind continuation frontiers explicit without promoting primary Hopac or
        // fabricating writer/root/BuildOk witnesses.  Future rounds can replace HUD strings
        // with these values at the source of the scheduler decisions.
        type CooperativeYieldHandoffId =
            | CooperativeYieldHandoffNone
            | CooperativeYieldHandoffTermToTy
            | CooperativeYieldHandoffTyToTermOrParent
            | CooperativeYieldHandoffSameNodePingPong
        let cooperativeYieldHandoffText = function
            | CooperativeYieldHandoffNone -> "none"
            | CooperativeYieldHandoffTermToTy -> "term_to_ty"
            | CooperativeYieldHandoffTyToTermOrParent -> "ty_to_term_or_parent"
            | CooperativeYieldHandoffSameNodePingPong -> "same_node_ping_pong"
        type SameHotReasonId =
            | SameHotNone
            | SameHotYieldThrash
            | SameHotQueuedReplaySpam
            | SameHotCrossKindContinuationWait
            | SameHotMissingImpl
        let sameHotReasonText = function
            | SameHotNone -> "None"
            | SameHotYieldThrash -> "YieldThrash"
            | SameHotQueuedReplaySpam -> "QueuedReplaySpam"
            | SameHotCrossKindContinuationWait -> "CrossKindContinuationWait"
            | SameHotMissingImpl -> "MissingImpl"
        type ContinuationCellReadinessId =
            | ContinuationCellUnknown
            | ContinuationCellBlockedByReentry
            | ContinuationCellPendingReplay
            | ContinuationCellReady
            | ContinuationCellCrossKindSiblingWaiting
        let continuationCellReadinessText = function
            | ContinuationCellUnknown -> "unknown"
            | ContinuationCellBlockedByReentry -> "blocked_by_reentry"
            | ContinuationCellPendingReplay -> "pending_replay"
            | ContinuationCellReady -> "ready"
            | ContinuationCellCrossKindSiblingWaiting -> "cross_kind_sibling_waiting"
        type CrossKindObligationId =
            | CrossKindObligationNone
            | CrossKindObligationTyToTermOrParent of count: int64
            | CrossKindObligationTermToTy of count: int64
        let crossKindObligationText = function
            | CrossKindObligationNone -> "none"
            | CrossKindObligationTyToTermOrParent count -> sprintf "%d@ty_to_term_or_parent" count
            | CrossKindObligationTermToTy count -> sprintf "%d@term_to_ty" count
        type TerminalFloodCreditGuardId =
            | TerminalFloodCreditNoOverride
            | TerminalFloodCreditProtectedMaterialTail
            | TerminalFloodCreditExpiredCooperativeHandoffTail
        let terminalFloodCreditGuardText = function
            | TerminalFloodCreditNoOverride -> "no_override"
            | TerminalFloodCreditProtectedMaterialTail -> "protected_material_tail"
            | TerminalFloodCreditExpiredCooperativeHandoffTail -> "expired_cooperative_handoff_tail"
        // ALPHA1535: start the breaking migration in a deliberately inert shape.
        // The assessment's final cutover asks for Job/Alt/IVar-owned obligations
        // and a structural pending graph.  These DUs are not primary authority yet;
        // they name the future typed surface so new receipts can stop depending on
        // raw q/a/p strings before the EvalWorklist queue is deleted.
        type ReplayShapeKind =
            | ReplayShapeTerm
            | ReplayShapeTy
            | ReplayShapeDynamicJoin
            | ReplayShapeIfUnknownReturn
            | ReplayShapeParentContinuation
        type ReplayKey<'Kind,'Shape> = {
            nodeId: NodeId<'Kind>
            site: string
            cursor: int
            step: int
            shape: ReplayShapeKind
            stableKey: string
            }
        type PendingStateDu =
            | PendingHealthy of pending: int
            | PendingZeroQueueLive of queueDepth: int * activeDepth: int
            | PendingNegativeDesync of rawPending: int * frontierPending: int * nodeErasureSite: string
            | PendingWriterMissing of key: string * queueDepth: int
            | PendingGraphPoisoned of reason: string
        type PendingGraph<'Kind,'Shape> = {
            key: ReplayKey<'Kind,'Shape>
            pending: PendingStateDu
            writerWitnessFreshMs: int64
            rootWitnessFreshMs: int64
            hopacProbe: HopacShadowProbe<'Kind>
            }
        type NativeHopacMigrationStageId =
            | NativeHopacShadowOnly
            | NativeHopacTypedReceiptBridge
            | NativeHopacJobEnvelopeScaffold
            | NativeHopacAltChooseBurnIn
            | NativeHopacMaterializedTerminalPendingGraphBurnIn
            | NativeHopacPrimaryBlockedNoFabrication
        let nativeHopacMigrationStageText = function
            | NativeHopacShadowOnly -> "shadow_only"
            | NativeHopacTypedReceiptBridge -> "typed_receipt_bridge"
            | NativeHopacJobEnvelopeScaffold -> "job_envelope_scaffold"
            | NativeHopacAltChooseBurnIn -> "alt_choose_burnin"
            | NativeHopacMaterializedTerminalPendingGraphBurnIn -> "materialized_terminal_pending_graph_burnin"
            | NativeHopacPrimaryBlockedNoFabrication -> "primary_blocked_no_fabrication"
        type MaterializedTerminalOutcomeId =
            | MaterializedTerminalNone
            | MaterializedTerminalShadowTimeoutStaleRetargetPierce
            | MaterializedTerminalSemanticStaleRetargetShadowTimeoutPierce
            | MaterializedTerminalMissingPrefetchCycleBreakPoison
            | MaterializedTerminalCrossKindPendingReplayContinuation
            | MaterializedTerminalParentContinuationImmediateFill
            | MaterializedTerminalObservedPinnedTerminalContract
            | MaterializedTerminalObservedPinnedTerminalImmediateFill
            | MaterializedTerminalMetronomeObservedPinnedAuthority
            | MaterializedTerminalDynamicJoinSymbolicCarrierReplay
            | MaterializedTerminalDynamicJoinCooperativeAltTimeout
            | MaterializedTerminalDynamicJoinBridgeTailHandoff
            | MaterializedTerminalIdleCrossKindSidecarDrain
            | MaterializedTerminalIdleCrossKindTerminalCommit
            | MaterializedTerminalDynamicRecordKeyBridgeCommit
            | MaterializedTerminalParentReplayPoisonLiveTail
            | MaterializedTerminalParentReplayCycleBreakPoisonImmediateFill
            | MaterializedTerminalCrossKindYieldThrashHardPoison
            | MaterializedTerminalHardPoisonObligationCapImmediateFill
            | MaterializedTerminalParentCacheHandoffWake
            | MaterializedTerminalParentReplayStatusPreservedCacheHandoff
            | MaterializedTerminalCooperativeReplayNativeBind
            | MaterializedTerminalTyGlobalFuseParentContinuation
            | MaterializedTerminalReentryPrefetchTerminalDriver
            | MaterializedTerminalJoinWaitDriverPromise
            | MaterializedTerminalNoRootBudgetParentReplayImmediateFill
            | MaterializedTerminalIfUnknownReturnConditionTailPierce
        let materializedTerminalOutcomeText = function
            | MaterializedTerminalNone -> "none"
            | MaterializedTerminalShadowTimeoutStaleRetargetPierce -> "ShadowTimeoutStaleRetargetPierce"
            | MaterializedTerminalSemanticStaleRetargetShadowTimeoutPierce -> "SemanticStaleRetargetShadowTimeoutPierce"
            | MaterializedTerminalMissingPrefetchCycleBreakPoison -> "MissingPrefetchCycleBreakPoison"
            | MaterializedTerminalCrossKindPendingReplayContinuation -> "CrossKindPendingReplayContinuation"
            | MaterializedTerminalParentContinuationImmediateFill -> "ParentContinuationImmediateFill"
            | MaterializedTerminalObservedPinnedTerminalContract -> "ObservedPinnedTerminalContract"
            | MaterializedTerminalObservedPinnedTerminalImmediateFill -> "ObservedPinnedTerminalImmediateFill"
            | MaterializedTerminalMetronomeObservedPinnedAuthority -> "MetronomeObservedPinnedAuthority"
            | MaterializedTerminalDynamicJoinSymbolicCarrierReplay -> "DynamicJoinSymbolicCarrierReplay"
            | MaterializedTerminalDynamicJoinCooperativeAltTimeout -> "DynamicJoinCooperativeAltTimeout"
            | MaterializedTerminalDynamicJoinBridgeTailHandoff -> "DynamicJoinBridgeTailHandoff"
            | MaterializedTerminalIdleCrossKindSidecarDrain -> "IdleCrossKindSidecarDrain"
            | MaterializedTerminalIdleCrossKindTerminalCommit -> "IdleCrossKindTerminalCommit"
            | MaterializedTerminalDynamicRecordKeyBridgeCommit -> "DynamicRecordKeyBridgeCommit"
            | MaterializedTerminalParentReplayPoisonLiveTail -> "ParentReplayPoisonLiveTail"
            | MaterializedTerminalParentReplayCycleBreakPoisonImmediateFill -> "ParentReplayCycleBreakPoisonImmediateFill"
            | MaterializedTerminalCrossKindYieldThrashHardPoison -> "CrossKindYieldThrashHardPoison"
            | MaterializedTerminalHardPoisonObligationCapImmediateFill -> "HardPoisonObligationCapImmediateFill"
            | MaterializedTerminalParentCacheHandoffWake -> "ParentCacheHandoffWake"
            | MaterializedTerminalParentReplayStatusPreservedCacheHandoff -> "ParentReplayStatusPreservedCacheHandoff"
            | MaterializedTerminalCooperativeReplayNativeBind -> "CooperativeReplayNativeBind"
            | MaterializedTerminalTyGlobalFuseParentContinuation -> "TyGlobalFuseParentContinuation"
            | MaterializedTerminalReentryPrefetchTerminalDriver -> "ReentryPrefetchTerminalDriver"
            | MaterializedTerminalJoinWaitDriverPromise -> "JoinWaitDriverPromise"
            | MaterializedTerminalNoRootBudgetParentReplayImmediateFill -> "NoRootBudgetParentReplayImmediateFill"
            | MaterializedTerminalIfUnknownReturnConditionTailPierce -> "IfUnknownReturnConditionTailPierce"
        type TypedTerminalPayload = {
            outcome: MaterializedTerminalOutcomeId
            replayKey: string
            expectedReturn: string
            failClosed: bool
            claim: string
            }
