            | MaterializedTerminalParentReplayCycleBreakPoisonImmediateFill -> proofTupleForParentReplayCycleBreakPoisonImmediateFill key
            | MaterializedTerminalCrossKindYieldThrashHardPoison -> proofTupleForCrossKindYieldThrashHardPoison key
            | MaterializedTerminalHardPoisonObligationCapImmediateFill -> proofTupleForHardPoisonObligationCapImmediateFill key
            | MaterializedTerminalParentCacheHandoffWake -> proofTupleForParentCacheHandoffWake key
            | MaterializedTerminalParentReplayStatusPreservedCacheHandoff -> proofTupleForParentReplayStatusPreservedCacheHandoff key
            | MaterializedTerminalCooperativeReplayNativeBind -> proofTupleForCooperativeReplayNativeBind key
            | MaterializedTerminalTyGlobalFuseParentContinuation -> proofTupleForTyGlobalFuseParentContinuation key
            | MaterializedTerminalReentryPrefetchTerminalDriver -> proofTupleForReentryPrefetchTerminalDriver key
            | MaterializedTerminalJoinWaitDriverPromise -> proofTupleForJoinWaitDriverPromise key
            | MaterializedTerminalNoRootBudgetParentReplayImmediateFill -> proofTupleForNoRootBudgetParentReplayImmediateFill key
            | MaterializedTerminalObservedPinnedTerminalContract -> proofTupleForObservedPinnedImmediateFill key
            | MaterializedTerminalMetronomeObservedPinnedAuthority -> proofTupleForObservedPinnedImmediateFill key
            | _ -> proofTupleForParentContinuationImmediateFill key

        let replayTickProofTupleFor (eventText: string) (reasonText: string) =
            let eventLower = if System.Object.ReferenceEquals(eventText, null) then "" else eventText.ToLowerInvariant()
            let reasonLower = if System.Object.ReferenceEquals(reasonText, null) then "" else reasonText.ToLowerInvariant()
            let stableKey = "replay_tick:" + eventLower + ":" + reasonLower
            if eventLower.Contains("app_root_base16")
               || reasonLower.Contains("app_root_base16")
               || reasonLower.Contains("root_witness_finalization_self_loop")
               || reasonLower.Contains("live_replay_livelock")
               || reasonLower.Contains("stale_retarget") then
                Some (proofTupleForSemanticStaleRetargetImmediateFill stableKey)
            elif reasonLower.Contains("parent_replay_status_preserved_repeat") && reasonLower.Contains("cache_handoff") then
                Some (proofTupleForParentReplayStatusPreservedCacheHandoff stableKey)
            elif eventLower.Contains("cooperative_replay_handoff") || reasonLower.Contains("cooperative_replay_handoff") then
                Some (proofTupleForCooperativeReplayNativeBind stableKey)
            elif eventLower.Contains("cache_write_parent_handoff")
                 || reasonLower.Contains("post_commit_parent_queue_driver_tick") then
                Some (proofTupleForParentCacheHandoffWake stableKey)
            elif eventLower.Contains("no_root_budget")
                 || reasonLower.Contains("no_root_budget")
                 || eventLower.Contains("bigstack_no_root_budget")
                 || reasonLower.Contains("materialized_terminal_beats_no_root_budget") then
                Some (proofTupleForNoRootBudgetParentReplayImmediateFill stableKey)
            elif eventLower.Contains("join_wait") || reasonLower.Contains("join_wait") then
                Some (proofTupleForJoinWaitDriverPromise stableKey)
            elif eventLower.Contains("term_reentry_prefetch")
                 || eventLower.Contains("ty_reentry_prefetch")
                 || reasonLower.Contains("reentry_prefetch")
                 || reasonLower.Contains("reentrant_replay_driver") then
                Some (proofTupleForReentryPrefetchTerminalDriver stableKey)
            elif reasonLower.Contains("hard_poison_obligation") then
                Some (proofTupleForHardPoisonObligationCapImmediateFill stableKey)
            elif reasonLower.Contains("parent_replay_status_preserved_repeat")
                 || reasonLower.Contains("parent_replay")
                 || reasonLower.Contains("poison") then
                Some (proofTupleForParentReplayCycleBreakPoisonImmediateFill stableKey)
            elif reasonLower.Contains("dynamic_join") then
                Some (proofTupleForDynamicJoinSymbolicCarrier stableKey)
            elif reasonLower.Contains("dynamic_record_key_bridge") || reasonLower.Contains("bridge_tail") then
                Some (proofTupleForDynamicRecordKeyBridgeCommit stableKey)
            elif reasonLower.Contains("idle_cross_kind") || reasonLower.Contains("active_ty_sidecar") then
                Some (proofTupleForIdleCrossKindSidecarDrain stableKey)
            else None

        let replayTickProofTupleJsonFields (eventText: string) (reasonText: string) =
            match replayTickProofTupleFor eventText reasonText with
            | Some tuple -> pendingGraphProofTupleJsonFields tuple
            | None -> ""

        let pendingGraphProofTupleOptionJsonFields (tupleOpt: PendingGraphProofTuple option) =
            match tupleOpt with
            | Some tuple -> pendingGraphProofTupleJsonFields tuple
            | None -> ""

        let pendingGraphProofTupleOptionComplete (tupleOpt: PendingGraphProofTuple option) =
            match tupleOpt with
            | Some tuple -> pendingGraphProofTupleComplete tuple
            | None -> false

        type AuthorityWinnerId =
            | AuthorityWinnerLegacyStillValid
            | AuthorityWinnerShadowAltTimeoutStackFence
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturn
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturnAbsentSidecar
