            | AuthorityWinnerShadowAltTimeoutSemanticStaleRetarget
            | AuthorityWinnerShadowAltTimeoutDynamicRecordKeyBridgeTail
            | AuthorityWinnerShadowAltTimeoutParentContinuationDeferredChild
            | AuthorityWinnerLedgerIdentityPanic
            | AuthorityWinnerNoWinner
        let authorityWinnerText = function
            | AuthorityWinnerLegacyStillValid -> "legacy_still_valid"
            | AuthorityWinnerShadowAltTimeoutStackFence -> "shadow_alt_timeout_stack_fence"
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturn -> "shadow_alt_timeout_if_unknown_return"
            | AuthorityWinnerShadowAltTimeoutIfUnknownReturnAbsentSidecar -> "shadow_alt_timeout_if_unknown_return_absent_sidecar"
            | AuthorityWinnerShadowAltTimeoutParentReplayCycleBreak -> "shadow_alt_timeout_parent_replay_cycle_break_poison"
            | AuthorityWinnerShadowAltTimeoutSemanticStaleRetarget -> "shadow_alt_timeout_semantic_stale_retarget"
            | AuthorityWinnerShadowAltTimeoutDynamicRecordKeyBridgeTail -> "shadow_alt_timeout_dynamic_record_key_bridge_tail"
            | AuthorityWinnerShadowAltTimeoutParentContinuationDeferredChild -> "shadow_alt_timeout_parent_continuation_deferred_child"
            | AuthorityWinnerLedgerIdentityPanic -> "ledger_identity_panic"
            | AuthorityWinnerNoWinner -> "none"
        type BlockerHierarchyId =
            | BlockerHierarchyShadowAltOverLegacyStackFence
            | BlockerHierarchyShadowAltOverIfUnknownReturn
            | BlockerHierarchyShadowAltOverIfUnknownReturnAbsentSidecar
            | BlockerHierarchyShadowAltOverParentReplayCycleBreak
            | BlockerHierarchyShadowAltOverSemanticStaleRetarget
            | BlockerHierarchyShadowAltOverDynamicRecordKeyBridgeTail
            | BlockerHierarchyShadowAltOverParentContinuationDeferredChild
            | BlockerHierarchyLedgerOverSidecar
            | BlockerHierarchyLegacyOnly
            | BlockerHierarchyNone
        let blockerHierarchyText = function
            | BlockerHierarchyShadowAltOverLegacyStackFence -> "shadow_alt_timeout > blocked_repeat_cap_before_stack_fence_yield > physical_qap"
            | BlockerHierarchyShadowAltOverIfUnknownReturn -> "shadow_alt_timeout > if_unknown_return_repeat_cap > physical_queue"
            | BlockerHierarchyShadowAltOverIfUnknownReturnAbsentSidecar -> "shadow_alt_timeout > if_unknown_return_absent_sidecar > legacy_repeat_cap_or_quarantine_tail"
            | BlockerHierarchyShadowAltOverParentReplayCycleBreak -> "shadow_alt_timeout > parent_replay_cycle_break_poison > repeat_cap_probation_drain > physical_qap"
            | BlockerHierarchyShadowAltOverSemanticStaleRetarget -> "shadow_alt_timeout > semantic_stale_retarget > missing_prefetch_cycle_break > stale_root_retarget"
            | BlockerHierarchyShadowAltOverDynamicRecordKeyBridgeTail -> "shadow_alt_timeout > dynamic_record_key_bridge_tail > weak_pending_active_root > physical_qap"
            | BlockerHierarchyShadowAltOverParentContinuationDeferredChild -> "shadow_alt_timeout > parent_continuation_deferred_child > bridge_tail > ty_sidecar_prefetch_grace"
            | BlockerHierarchyLedgerOverSidecar -> "ledger_identity_panic > sidecar_prefetch > live_tail"
            | BlockerHierarchyLegacyOnly -> "legacy_only_no_shadow_breach"
            | BlockerHierarchyNone -> "none"
        type IfUnknownReturnConditionObligationId =
            | IfUnknownReturnNotCurrent
            | IfUnknownReturnBranchProbeRequired
            | IfUnknownReturnPhysicalQueueDrainBeforeTerminal
            | IfUnknownReturnShadowTimeoutPiercesRepeatCap
            | IfUnknownReturnAbsentSidecarShadowTimeoutPiercesRepeatCap
        let ifUnknownReturnConditionObligationText = function
            | IfUnknownReturnNotCurrent -> "not_if_unknown_return"
            | IfUnknownReturnBranchProbeRequired -> "if_unknown_return_branch_probe_required"
            | IfUnknownReturnPhysicalQueueDrainBeforeTerminal -> "if_unknown_return_physical_queue_drain_before_terminal"
            | IfUnknownReturnShadowTimeoutPiercesRepeatCap -> "if_unknown_return_shadow_timeout_pierces_repeat_cap"
            | IfUnknownReturnAbsentSidecarShadowTimeoutPiercesRepeatCap -> "if_unknown_return_absent_sidecar_shadow_timeout_pierces_repeat_cap"
        let cacheKeyText = function
            | CacheKeyFromReplayCell (NodeId nodeId, site) -> sprintf "node:%d@%s" nodeId site
            | CacheKeyFromRaw key when key = "-1" -> "[ERASED_IDENTITY]"
            | CacheKeyFromRaw key -> key
            | CacheKeyErasedIdentity site -> "[ERASED_IDENTITY:" + site + "]"
            | CacheKeyMissing -> "missing"
        // ALPHA347: typed replay cell carried alongside the text envelope.
        // The string payload remains for stable logs, but the driver now has a small typed
        // object to hand to the future stack-safe term/ty stepper.
        type ReplayCell = {
            kind: string
            shape: string
            nodeId: int
            envGlobalTerm: int
            envStackTerm: int
            envGlobalType: int
            envStackType: int
            seqLen: int
            cseDepth: int
            traceDepth: int
            site: string
            cursor: int
            step: int
            status: string
        }

        let termCacheKeyFromCell (cell: ReplayCell option) (fallbackKey: string) =
            match cell with
            | Some c -> CacheKeyFromReplayCell ((NodeId c.nodeId : NodeId<TermKind>), c.site)
            | None when String.IsNullOrWhiteSpace fallbackKey -> CacheKeyMissing
            | None -> CacheKeyFromRaw fallbackKey

        type Frame = {
            kind: string
            key: string
            site: string
