            | ReplayExceptionLetSuccessApply -> ReplayReasonLetSuccessReplayDriverNull
            | ReplayExceptionLetSuccessApplyContinuationRepeat -> ReplayReasonLetSuccessApplyContinuationNullRepeatTerminal
            | ReplayExceptionLetSuccessApplyContinuationRootWitnessDeferred -> ReplayReasonLetSuccessApplyContinuationNullAfterRootComplete
            | ReplayExceptionLetSuccessApplyContinuationDriverRepeat -> ReplayReasonLetSuccessApplyContinuationDriverNullRepeatTerminal
            | ReplayExceptionLetSuccessApplyContinuationDriverDeferred -> ReplayReasonLetSuccessApplyContinuationDriverNullDeferred
            | ReplayExceptionLetSuccessApplyContinuationDriverTerminal -> ReplayReasonLetSuccessApplyContinuationDriverNull
            | ReplayExceptionApplyContinuationRootWitnessRepeat -> ReplayReasonApplyContinuationReplayDriverNullRepeatTerminal
            | ReplayExceptionApplyContinuationRootWitnessDeferred -> ReplayReasonApplyContinuationReplayDriverNullAfterRootComplete
            | ReplayExceptionApplyContinuationRootWitnessRetryRepeat -> ReplayReasonApplyContinuationReplayDriverNullRetryRepeatTerminal
            | ReplayExceptionApplyContinuationRootWitnessRetryDeferred -> ReplayReasonApplyContinuationReplayDriverNullAfterPriorRootGuard
            | ReplayExceptionOpContinuationRootWitnessRepeat -> ReplayReasonOpReplayDriverNullRepeatTerminal
            | ReplayExceptionOpContinuationRootWitnessDeferred -> ReplayReasonOpReplayDriverNullAfterRootComplete
            | ReplayExceptionApplyContinuationAfterSeqUnknown -> ReplayReasonApplyContinuationReplayDriverNullAfterSeqUnknown
            | ReplayExceptionApplyContinuationDriverNull -> ReplayReasonApplyContinuationReplayDriverNull
            | ReplayExceptionDeferredFunctionDriverNull -> ReplayReasonDeferredFunctionReplayDriverNull
            | ReplayExceptionTypeApplyArgNull -> ReplayReasonTypeApplyArgReplayNullTerminal
            | ReplayExceptionGeneric -> ReplayReasonReplayDriverException

        let private replayDriverExceptionCellStatusId kind =
            match kind with
            | ReplayExceptionLetSuccessApply -> ReplayCellLetSuccessApplyExceptionBlocked
            | ReplayExceptionLetSuccessApplyContinuationRepeat -> ReplayCellLetSuccessApplyContinuationBlocked
            | ReplayExceptionLetSuccessApplyContinuationRootWitnessDeferred -> ReplayCellLetSuccessApplyContinuationRootWitnessDeferred
            | ReplayExceptionLetSuccessApplyContinuationDriverRepeat -> ReplayCellLetSuccessApplyContinuationBlocked
            | ReplayExceptionLetSuccessApplyContinuationDriverDeferred -> ReplayCellLetSuccessApplyContinuationDeferred
            | ReplayExceptionLetSuccessApplyContinuationDriverTerminal -> ReplayCellLetSuccessApplyContinuationBlocked
            | ReplayExceptionApplyContinuationRootWitnessRepeat -> ReplayCellApplyContinuationExceptionBlocked
            | ReplayExceptionApplyContinuationRootWitnessDeferred -> ReplayCellApplyContinuationRootWitnessNullGuarded
            | ReplayExceptionApplyContinuationRootWitnessRetryRepeat -> ReplayCellApplyContinuationExceptionBlocked
            | ReplayExceptionApplyContinuationRootWitnessRetryDeferred -> ReplayCellApplyContinuationRootWitnessRetryGuarded
            | ReplayExceptionOpContinuationRootWitnessRepeat -> ReplayCellReplayDriverExceptionBlocked
            | ReplayExceptionOpContinuationRootWitnessDeferred -> ReplayCellOpContinuationRootWitnessNullGuarded
            | ReplayExceptionApplyContinuationAfterSeqUnknown -> ReplayCellApplyContinuationAfterSeqUnknownBlocked
            | ReplayExceptionApplyContinuationDriverNull -> ReplayCellApplyContinuationExceptionBlocked
            | ReplayExceptionDeferredFunctionDriverNull -> ReplayCellDeferredFunctionReplayExceptionBlocked
            | ReplayExceptionTypeApplyArgNull -> ReplayCellReplayDriverExceptionBlocked
            | ReplayExceptionGeneric -> ReplayCellReplayDriverExceptionBlocked

        let private replayDriverExceptionNextId kind =
            match kind with
            | ReplayExceptionLetSuccessApply -> ReplayNextLetSuccessApplyExceptionRequired
            | ReplayExceptionLetSuccessApplyContinuationRepeat -> ReplayNextLetSuccessApplyContinuationRequired
            | ReplayExceptionLetSuccessApplyContinuationRootWitnessDeferred -> ReplayNextLetSuccessApplyContinuationRootWitnessNullGuard
            | ReplayExceptionLetSuccessApplyContinuationDriverRepeat -> ReplayNextLetSuccessApplyContinuationRequired
            | ReplayExceptionLetSuccessApplyContinuationDriverDeferred -> ReplayNextLetSuccessApplyContinuationDeferred
            | ReplayExceptionLetSuccessApplyContinuationDriverTerminal -> ReplayNextLetSuccessApplyContinuationRequired
            | ReplayExceptionApplyContinuationRootWitnessRepeat -> ReplayNextApplyContinuationExceptionRequired
            | ReplayExceptionApplyContinuationRootWitnessDeferred -> ReplayNextApplyContinuationRootWitnessNullGuard
            | ReplayExceptionApplyContinuationRootWitnessRetryRepeat -> ReplayNextApplyContinuationExceptionRequired
            | ReplayExceptionApplyContinuationRootWitnessRetryDeferred -> ReplayNextApplyContinuationRootWitnessRetryGuard
            | ReplayExceptionOpContinuationRootWitnessRepeat -> ReplayNextReplayDriverExceptionRequired
            | ReplayExceptionOpContinuationRootWitnessDeferred -> ReplayNextOpRootWitnessNullGuard
            | ReplayExceptionApplyContinuationAfterSeqUnknown -> ReplayNextApplyContinuationAfterSeqUnknownRequired
            | ReplayExceptionApplyContinuationDriverNull -> ReplayNextApplyContinuationExceptionRequired
            | ReplayExceptionDeferredFunctionDriverNull -> ReplayNextDeferredFunctionReplayExceptionRequired
            | ReplayExceptionTypeApplyArgNull -> ReplayNextReplayDriverExceptionRequired
            | ReplayExceptionGeneric -> ReplayNextReplayDriverExceptionRequired

        type SemanticStatusId =
            | SemanticRootComplete
            | SemanticStepPartial
            | SemanticParentContinuationCycleBlocked
            | SemanticRootCompletePendingJobsBlocked
            | SemanticAppRootBase16StaleRetargetHardcapBlocked
            | SemanticDynamicJoinApplyBlocked
            | SemanticReplayChildScheduleRepeatBlocked
            | SemanticRecordWithValueBlocked
            | SemanticReplayFingerprintRepeatBlocked
            | SemanticOpImplRequiredBlocked
            | SemanticErrorTypeBlocked
            | SemanticCodegenJpBodyDictMissingBlocked
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked
            | SemanticRootCompleteStaleRetargetPendingNoQueueDeferred
            | SemanticParentContinuationCycleDeferred
            | SemanticGlobalFuseParentContinuationCycleBlocked
            | SemanticMacroThunkMissingBlocked
            | SemanticLiteralOpBodyStepperBlocked
            | SemanticApplySeqUnknownReturnWitnessBlocked
            | SemanticApplyContinuationAfterSeqUnknownBlocked
            | SemanticSeqUnknownReturnWitnessBlocked
            | SemanticIfUnknownReturnConditionBlocked
            | SemanticIfSymbolicConditionBlocked
            | SemanticAnnotTestBranchSelectionBlocked
            | SemanticTypeApplyNominalConstructorStepperBlocked
            | SemanticNominalConstructorStepperBlocked
            | SemanticTermTypeValueBlocked
            | SemanticPairValueBlocked
            | SemanticTypeApplyNestedForallStepperBlocked
            | SemanticSeqTypeErrorBlocked
            | SemanticLeafParentContinuationMissingBlocked
            | SemanticUnitTestValueBlocked
            | SemanticTypeApplyForallBodyStepperBlocked
            | SemanticTypeVariableValueMissingBlocked
            | SemanticApplyContinuationExceptionBlocked
            | SemanticParentReplayStatusPreservedRepeatBlocked
            | SemanticParentReplayCycleBreakPoisoned
            | SemanticReentrantReplayDriverStarvationBlocked
            | SemanticRootCompleteStaleRetargetRepeatBlocked
            | SemanticSelectedFrontierRepeatBlocked
            | SemanticTjoinpointStepperBlocked
            | SemanticJoinpointValueBlocked
            | SemanticJoinpointTermStepperBlocked
            | SemanticReplayPayloadMissingBlocked
            | SemanticReplayDriverExceptionBlocked
            | SemanticStaleRootRetargetBlocked
            | SemanticLetSuccessAllReadyApplyBlocked
            | SemanticDeferredFunctionReplayExceptionBlocked
            | SemanticLetSuccessApplyContinuationBlocked
            | SemanticLetSuccessApplyExceptionBlocked
            | SemanticUnboxReplayBlocked
            | SemanticApplySpineMissingDirectValueBlocked
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked
            | SemanticMissingAfterPrefetchBlocked

            | SemanticOther of string

        // ALPHA959: continue the alpha953 migration away from policy-by-string.
        // Frame.status is still serialized as text at the log/bundle boundary, but
        // central liveness decisions now pass through a closed DU instead of ad-hoc
        // string disjunctions.  This keeps the runtime evidence readable while making
        // new live/terminal cases explicit at the migration seam.
        type FrameStatusId =
            | FrameReadyExplicitLoop
            | FrameTracingExplicitLoop
            | FrameContinuationEnvelope
            | FrameSemanticStepPartial
            | FrameSemanticRootComplete
            | FrameSemanticLeafComplete
            | FrameBlockedByReentry
            | FrameUnknown of string

        type ReplayChildRoleId =
            | ApplyHeadChild
            | ApplyArgChild
            | TypeApplyTypeArgChild
            | TypeApplyFunctionChild
            | TypeAwareOpChild
            | TTermTermChild
            | TFunArgChild
            | TFunBodyChild
            | TPairLeftChild
            | TPairRightChild
            | DeferredReplayChild
            | RecordWithChild
            | MacroChild
            | SeqChild
            | PairLeftChild
            | PairRightChild
            | LetSuccessChild
            | LetBodyChild
            | UnknownReplayChildRole of string

        type EvalCellKindId =
            | CellTerm
            | CellTy
            | CellData
            | CellUnknownKind of string

        type EvalCellShapeId =
            | CellShapeELet
            | CellShapeEApply
            | CellShapeETypeApply
            | CellShapeEForall
            | CellShapeOther of string

        type CodegenJpKindId =
            | CodegenMethod
            | CodegenClosure
            | CodegenUnknownJpKind of string

        let private codegenJpKindOfString kind =
            match kind with
            | "method" -> CodegenMethod
            | "closure" -> CodegenClosure
            | other -> CodegenUnknownJpKind other

        let private codegenJpKindToString kind =
            match kind with
            | CodegenMethod -> "method"
            | CodegenClosure -> "closure"
            | CodegenUnknownJpKind other -> other

        let private frameStatusOfString (status: string) =
            match status with
            | "ready_explicit_loop" -> FrameReadyExplicitLoop
            | "tracing_explicit_loop" -> FrameTracingExplicitLoop
            | "continuation_envelope" -> FrameContinuationEnvelope
            | "semantic_step_partial" -> FrameSemanticStepPartial
            | "semantic_root_complete" -> FrameSemanticRootComplete
            | "semantic_leaf_complete" -> FrameSemanticLeafComplete
            | "blocked_by_reentry" -> FrameBlockedByReentry
            | other -> FrameUnknown other

        let private frameStatusToString status =
            match status with
            | FrameReadyExplicitLoop -> "ready_explicit_loop"
            | FrameTracingExplicitLoop -> "tracing_explicit_loop"
            | FrameContinuationEnvelope -> "continuation_envelope"
            | FrameSemanticStepPartial -> "semantic_step_partial"
            | FrameSemanticRootComplete -> "semantic_root_complete"
            | FrameSemanticLeafComplete -> "semantic_leaf_complete"
            | FrameBlockedByReentry -> "blocked_by_reentry"
            | FrameUnknown x -> x

        let private isLiveExplicitFrameStatusId status =
            match status with
            | FrameReadyExplicitLoop
            | FrameTracingExplicitLoop
            | FrameContinuationEnvelope
            | FrameSemanticStepPartial -> true
            | _ -> false

        let isLiveExplicitFrameStatus status =
            status |> frameStatusOfString |> isLiveExplicitFrameStatusId

        let private isLiveOrRootCompleteFrameStatus status =
            match frameStatusOfString status with
            | FrameSemanticRootComplete -> true
            | statusId -> isLiveExplicitFrameStatusId statusId

        let private isContinuationEnvelopeFrameStatus status =
            match frameStatusOfString status with
            | FrameContinuationEnvelope -> true
            | _ -> false

        let private replayChildRoleOfString (role: string) =
            match role with
            | "apply_head_child" -> ApplyHeadChild
            | "apply_arg_child" -> ApplyArgChild
            | "type_apply_type_arg_child" -> TypeApplyTypeArgChild
            | "type_apply_function_child" -> TypeApplyFunctionChild
            | "type_aware_op_child" -> TypeAwareOpChild
            | "tterm_term_child" -> TTermTermChild
            | "tfun_arg_child" -> TFunArgChild
            | "tfun_body_child" -> TFunBodyChild
            | "tpair_left_child" -> TPairLeftChild
            | "tpair_right_child" -> TPairRightChild
            | "deferred_replay_child" -> DeferredReplayChild
            | "record_with_child" -> RecordWithChild
            | "macro_child" -> MacroChild
            | "seq_child" -> SeqChild
            | "pair_left_child" -> PairLeftChild
            | "pair_right_child" -> PairRightChild
            | "let_success_child" -> LetSuccessChild
            | "let_body_child" -> LetBodyChild
            | other -> UnknownReplayChildRole other

        let private cellKindOfString (kind: string) =
            match kind with
            | "term" -> CellTerm
            | "ty" -> CellTy
            | "data" -> CellData
            | other -> CellUnknownKind other

        let private cellShapeOfString (shape: string) =
            match shape with
            | "ELet" -> CellShapeELet
            | "EApply" -> CellShapeEApply
            | "ETypeApply" -> CellShapeETypeApply
            | "EForall'" -> CellShapeEForall
            | other -> CellShapeOther other

        let private isSeqReplayChildRoleId role =
            match role with
            | SeqChild -> true
            | _ -> false

        let private isTypeApplyFunctionReplayChildRoleId role =
            match role with
            | TypeApplyFunctionChild -> true
            | _ -> false

        let private isTermLetCellId kind shape =
            match kind, shape with
            | CellTerm, CellShapeELet -> true
            | _ -> false

        let private isTermTypeApplyCellId kind shape =
            match kind, shape with
            | CellTerm, CellShapeETypeApply -> true
            | _ -> false

        let private isSemanticReplayChildScheduleRepeatBlockedStatusId status =
            match status with
            | SemanticReplayChildScheduleRepeatBlocked -> true
            | _ -> false

        let private evalKindOfString (kind: string) =
            match kind with
            | "term" -> EvalTerm
            | "ty" -> EvalTy
            | "data" -> EvalData
            | "codegen" -> EvalCodegen
            | other -> EvalUnknown other

        let private evalKindToString kind =
            match kind with
            | EvalTerm -> "term"
            | EvalTy -> "ty"
            | EvalData -> "data"
            | EvalCodegen -> "codegen"
            | EvalUnknown x -> x

        let private replayDriverOfString (driver: string) =
            match driver with
            | "term_replay_driver" -> TermReplayDriver
            | "ty_replay_driver" -> TyReplayDriver
            | other -> UnknownReplayDriver other

        let private replayDriverToString driver =
            match driver with
            | TermReplayDriver -> "term_replay_driver"
            | TyReplayDriver -> "ty_replay_driver"
            | UnknownReplayDriver x -> x

        let private replayTickQueuePressureFor qd activeDepth stackFenceQueued staleQueued =
            if qd <= 0 then ReplayTickQueueEmpty
            elif staleQueued then ReplayTickFenceStale
            elif stackFenceQueued && activeDepth > 0 then ReplayTickActiveDrainBackpressure
            elif stackFenceQueued then ReplayTickFenceAlreadyQueued
            else ReplayTickScheduleableQueue

        let private replayTickQueuePressureText = function
            | ReplayTickQueueEmpty -> "queue_empty"
            | ReplayTickScheduleableQueue -> "scheduleable_queue"
            | ReplayTickFenceAlreadyQueued -> "fence_already_queued"
            | ReplayTickActiveDrainBackpressure -> "active_drain_backpressure"
            | ReplayTickFenceStale -> "fence_stale"

        let private replayTickEventOfString (event: string) =
            match if System.Object.ReferenceEquals(event, null) then "" else event with
            | "cooperative_replay_handoff" -> ReplayTickEventCooperativeReplayHandoff
            | "cache_write_parent_handoff_wake_callback" -> ReplayTickEventCacheWriteParentHandoffWakeCallback
            | "bigstack_queue_only_live_replay" -> ReplayTickEventBigstackQueueOnlyLiveReplay
            | "bigstack_join_wait_live_replay_drain" -> ReplayTickEventBigstackJoinWaitLiveReplayDrain
            | "bigstack_join_wait" -> ReplayTickEventBigstackJoinWait
            | "term_entry" -> ReplayTickEventTermEntry
            | "term_reentry_prefetch" -> ReplayTickEventTermReentryPrefetch
            | "ty_reentry_prefetch" -> ReplayTickEventTyReentryPrefetch
            | "join_wait" -> ReplayTickEventJoinWait
            | x -> ReplayTickEventUnknown x

        let private replayTickEventToString = function
            | ReplayTickEventCooperativeReplayHandoff -> "cooperative_replay_handoff"
            | ReplayTickEventCacheWriteParentHandoffWakeCallback -> "cache_write_parent_handoff_wake_callback"
            | ReplayTickEventBigstackQueueOnlyLiveReplay -> "bigstack_queue_only_live_replay"
            | ReplayTickEventBigstackJoinWaitLiveReplayDrain -> "bigstack_join_wait_live_replay_drain"
            | ReplayTickEventBigstackJoinWait -> "bigstack_join_wait"
            | ReplayTickEventTermEntry -> "term_entry"
            | ReplayTickEventTermReentryPrefetch -> "term_reentry_prefetch"
            | ReplayTickEventTyReentryPrefetch -> "ty_reentry_prefetch"
            | ReplayTickEventJoinWait -> "join_wait"
            | ReplayTickEventUnknown x -> x

        let private replayTickReasonOfString (reason: string) =
            match if System.Object.ReferenceEquals(reason, null) then "" else reason with
            | "schedule_tick" -> ReplayTickReasonScheduleTick
            | "post_commit_parent_queue_driver_tick" -> ReplayTickReasonPostCommitParentQueueDriverTick
            | "parent_resume_deferred_drain_tick" -> ReplayTickReasonParentResumeDeferredDrainTick
            | "cross_kind_deferred_obligation_tail" -> ReplayTickReasonCrossKindDeferredObligationTail
            | "single_flight_busy_graph_mutation_tick" -> ReplayTickReasonSingleFlightBusyGraphMutationTick
            | "drain_after_active_run_no_sync_wait" -> ReplayTickReasonDrainAfterActiveRunNoSyncWait
            | "missing_after_prefetch_terminal_live_replay_grace" -> ReplayTickReasonMissingAfterPrefetchTerminalLiveReplayGrace
            | "dynamic_join_terminal_live_replay_grace" -> ReplayTickReasonDynamicJoinTerminalLiveReplayGrace
            | "parent_replay_repeat_recent_progress_tail" -> ReplayTickReasonParentReplayRepeatRecentProgressTail
            | "concrete_op_terminal_live_replay_grace" -> ReplayTickReasonConcreteOpTerminalLiveReplayGrace
            | "root_complete_stale_retarget_livelock_terminal_live_replay_grace" -> ReplayTickReasonRootCompleteStaleRetargetLivelockTerminalLiveReplayGrace
            | "symbolic_if_terminal_live_replay_grace" -> ReplayTickReasonSymbolicIfTerminalLiveReplayGrace
            | "if_unknown_return_terminal_live_replay_grace" -> ReplayTickReasonIfUnknownReturnTerminalLiveReplayGrace
            | "young_pending_parent_continuation_fuse_grace" -> ReplayTickReasonYoungPendingParentContinuationFuseGrace
            | "cooperative_replay_handoff" -> ReplayTickReasonCooperativeReplayHandoff
            | x when x.Contains("parent_replay_status_preserved_repeat", System.StringComparison.Ordinal) && x.Contains("cache_handoff", System.StringComparison.Ordinal) -> ReplayTickReasonParentReplayStatusPreservedCacheHandoff x
            | x when x.Contains("parent_replay", System.StringComparison.Ordinal) || x.Contains("poison", System.StringComparison.Ordinal) -> ReplayTickReasonParentReplayPoisonHandoffAction x
            | x -> ReplayTickReasonUnknown x

        let private replayTickReasonToString = function
            | ReplayTickReasonScheduleTick -> "schedule_tick"
            | ReplayTickReasonPostCommitParentQueueDriverTick -> "post_commit_parent_queue_driver_tick"
            | ReplayTickReasonParentResumeDeferredDrainTick -> "parent_resume_deferred_drain_tick"
            | ReplayTickReasonCrossKindDeferredObligationTail -> "cross_kind_deferred_obligation_tail"
            | ReplayTickReasonSingleFlightBusyGraphMutationTick -> "single_flight_busy_graph_mutation_tick"
            | ReplayTickReasonDrainAfterActiveRunNoSyncWait -> "drain_after_active_run_no_sync_wait"
            | ReplayTickReasonMissingAfterPrefetchTerminalLiveReplayGrace -> "missing_after_prefetch_terminal_live_replay_grace"
            | ReplayTickReasonDynamicJoinTerminalLiveReplayGrace -> "dynamic_join_terminal_live_replay_grace"
            | ReplayTickReasonParentReplayRepeatRecentProgressTail -> "parent_replay_repeat_recent_progress_tail"
            | ReplayTickReasonConcreteOpTerminalLiveReplayGrace -> "concrete_op_terminal_live_replay_grace"
            | ReplayTickReasonRootCompleteStaleRetargetLivelockTerminalLiveReplayGrace -> "root_complete_stale_retarget_livelock_terminal_live_replay_grace"
            | ReplayTickReasonSymbolicIfTerminalLiveReplayGrace -> "symbolic_if_terminal_live_replay_grace"
            | ReplayTickReasonIfUnknownReturnTerminalLiveReplayGrace -> "if_unknown_return_terminal_live_replay_grace"
            | ReplayTickReasonYoungPendingParentContinuationFuseGrace -> "young_pending_parent_continuation_fuse_grace"
            | ReplayTickReasonParentReplayStatusPreservedCacheHandoff x -> x
            | ReplayTickReasonCooperativeReplayHandoff -> "cooperative_replay_handoff"
            | ReplayTickReasonParentReplayPoisonHandoffAction x -> x
            | ReplayTickReasonUnknown x -> x

        let private replayTickReasonKindText = function
            | ReplayTickReasonParentReplayStatusPreservedCacheHandoff _ -> "parent_replay_status_preserved_cache_handoff"
            | ReplayTickReasonCooperativeReplayHandoff -> "cooperative_replay_handoff"
            | ReplayTickReasonParentReplayPoisonHandoffAction _ -> "parent_replay_poison_handoff_action"
            | ReplayTickReasonUnknown _ -> "unknown"
            | x -> replayTickReasonToString x

