            | "semantic_type_variable_value_missing_blocked" -> SemanticTypeVariableValueMissingBlocked
            | "semantic_apply_continuation_exception_blocked" -> SemanticApplyContinuationExceptionBlocked
            | "semantic_parent_replay_status_preserved_repeat_blocked" -> SemanticParentReplayStatusPreservedRepeatBlocked
            | "semantic_parent_replay_cycle_break_poisoned" -> SemanticParentReplayCycleBreakPoisoned
            | "semantic_reentrant_replay_driver_starvation_blocked" -> SemanticReentrantReplayDriverStarvationBlocked
            | "semantic_root_complete_stale_retarget_repeat_blocked" -> SemanticRootCompleteStaleRetargetRepeatBlocked
            | "semantic_selected_frontier_repeat_blocked" -> SemanticSelectedFrontierRepeatBlocked
            | "semantic_tjoinpoint_stepper_blocked" -> SemanticTjoinpointStepperBlocked
            | "semantic_joinpoint_value_blocked" -> SemanticJoinpointValueBlocked
            | "semantic_joinpoint_term_stepper_blocked" -> SemanticJoinpointTermStepperBlocked
            | "semantic_replay_payload_missing_blocked" -> SemanticReplayPayloadMissingBlocked
            | "semantic_replay_driver_exception_blocked" -> SemanticReplayDriverExceptionBlocked
            | "semantic_stale_root_retarget_blocked" -> SemanticStaleRootRetargetBlocked
            | "semantic_let_success_all_ready_apply_blocked" -> SemanticLetSuccessAllReadyApplyBlocked
            | "semantic_deferred_function_replay_exception_blocked" -> SemanticDeferredFunctionReplayExceptionBlocked
            | "semantic_let_success_apply_continuation_blocked" -> SemanticLetSuccessApplyContinuationBlocked
            | "semantic_let_success_apply_exception_blocked" -> SemanticLetSuccessApplyExceptionBlocked
            | "semantic_unbox_replay_blocked" -> SemanticUnboxReplayBlocked
            | "semantic_apply_spine_missing_direct_value_blocked" -> SemanticApplySpineMissingDirectValueBlocked
            | "semantic_root_complete_stale_retarget_live_replay_livelock_blocked" -> SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked
            | "missing_after_prefetch"
            | "semantic_missing_after_prefetch_blocked" -> SemanticMissingAfterPrefetchBlocked
            | other -> SemanticOther other

        let private semanticStatusToString status =
            match status with
            | SemanticRootComplete -> "semantic_root_complete"
            | SemanticStepPartial -> "semantic_step_partial"
            | SemanticParentContinuationCycleBlocked -> "semantic_parent_continuation_cycle_blocked"
            | SemanticRootCompletePendingJobsBlocked -> "semantic_root_complete_pending_jobs_blocked"
            | SemanticAppRootBase16StaleRetargetHardcapBlocked -> "semantic_app_root_base16_stale_retarget_hardcap_blocked"
            | SemanticDynamicJoinApplyBlocked -> "semantic_dynamic_join_apply_blocked"
            | SemanticReplayChildScheduleRepeatBlocked -> "semantic_replay_child_schedule_repeat_blocked"
            | SemanticRecordWithValueBlocked -> "semantic_record_with_value_blocked"
            | SemanticReplayFingerprintRepeatBlocked -> "semantic_replay_fingerprint_repeat_blocked"
            | SemanticOpImplRequiredBlocked -> "semantic_op_impl_required_blocked"
            | SemanticErrorTypeBlocked -> "semantic_error_type_blocked"
            | SemanticCodegenJpBodyDictMissingBlocked -> "semantic_codegen_jp_body_dict_missing_blocked"
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked -> "semantic_root_complete_stale_retarget_pending_no_queue_blocked"
            | SemanticRootCompleteStaleRetargetPendingNoQueueDeferred -> "semantic_root_complete_stale_retarget_pending_no_queue_deferred"
            | SemanticParentContinuationCycleDeferred -> "semantic_parent_continuation_cycle_deferred"
            | SemanticGlobalFuseParentContinuationCycleBlocked -> "semantic_global_fuse_parent_continuation_cycle_blocked"
            | SemanticMacroThunkMissingBlocked -> "semantic_macro_thunk_missing_blocked"
            | SemanticLiteralOpBodyStepperBlocked -> "semantic_literal_op_body_stepper_blocked"
            | SemanticApplySeqUnknownReturnWitnessBlocked -> "semantic_apply_seq_unknown_return_witness_blocked"
            | SemanticApplyContinuationAfterSeqUnknownBlocked -> "semantic_apply_continuation_after_seq_unknown_blocked"
            | SemanticSeqUnknownReturnWitnessBlocked -> "semantic_seq_unknown_return_witness_blocked"
            | SemanticIfUnknownReturnConditionBlocked -> "semantic_if_unknown_return_condition_blocked"
            | SemanticIfSymbolicConditionBlocked -> "semantic_if_symbolic_condition_blocked"
            | SemanticAnnotTestBranchSelectionBlocked -> "semantic_annot_test_branch_selection_blocked"
            | SemanticTypeApplyNominalConstructorStepperBlocked -> "semantic_type_apply_nominal_constructor_stepper_blocked"
            | SemanticNominalConstructorStepperBlocked -> "semantic_nominal_constructor_stepper_blocked"
            | SemanticTermTypeValueBlocked -> "semantic_term_type_value_blocked"
            | SemanticPairValueBlocked -> "semantic_pair_value_blocked"
            | SemanticTypeApplyNestedForallStepperBlocked -> "semantic_type_apply_nested_forall_stepper_blocked"
            | SemanticSeqTypeErrorBlocked -> "semantic_seq_type_error_blocked"
            | SemanticLeafParentContinuationMissingBlocked -> "semantic_leaf_parent_continuation_missing_blocked"
            | SemanticUnitTestValueBlocked -> "semantic_unit_test_value_blocked"
            | SemanticTypeApplyForallBodyStepperBlocked -> "semantic_type_apply_forall_body_stepper_blocked"
            | SemanticTypeVariableValueMissingBlocked -> "semantic_type_variable_value_missing_blocked"
            | SemanticApplyContinuationExceptionBlocked -> "semantic_apply_continuation_exception_blocked"
            | SemanticParentReplayStatusPreservedRepeatBlocked -> "semantic_parent_replay_status_preserved_repeat_blocked"
            | SemanticParentReplayCycleBreakPoisoned -> "semantic_parent_replay_cycle_break_poisoned"
            | SemanticReentrantReplayDriverStarvationBlocked -> "semantic_reentrant_replay_driver_starvation_blocked"
            | SemanticRootCompleteStaleRetargetRepeatBlocked -> "semantic_root_complete_stale_retarget_repeat_blocked"
            | SemanticSelectedFrontierRepeatBlocked -> "semantic_selected_frontier_repeat_blocked"
            | SemanticTjoinpointStepperBlocked -> "semantic_tjoinpoint_stepper_blocked"
            | SemanticJoinpointValueBlocked -> "semantic_joinpoint_value_blocked"
            | SemanticJoinpointTermStepperBlocked -> "semantic_joinpoint_term_stepper_blocked"
            | SemanticReplayPayloadMissingBlocked -> "semantic_replay_payload_missing_blocked"
            | SemanticReplayDriverExceptionBlocked -> "semantic_replay_driver_exception_blocked"
            | SemanticStaleRootRetargetBlocked -> "semantic_stale_root_retarget_blocked"
            | SemanticLetSuccessAllReadyApplyBlocked -> "semantic_let_success_all_ready_apply_blocked"
            | SemanticDeferredFunctionReplayExceptionBlocked -> "semantic_deferred_function_replay_exception_blocked"
            | SemanticLetSuccessApplyContinuationBlocked -> "semantic_let_success_apply_continuation_blocked"
            | SemanticLetSuccessApplyExceptionBlocked -> "semantic_let_success_apply_exception_blocked"
            | SemanticUnboxReplayBlocked -> "semantic_unbox_replay_blocked"
            | SemanticApplySpineMissingDirectValueBlocked -> "semantic_apply_spine_missing_direct_value_blocked"
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> "semantic_root_complete_stale_retarget_live_replay_livelock_blocked"
            | SemanticMissingAfterPrefetchBlocked -> "semantic_missing_after_prefetch_blocked"
            | SemanticOther x -> x

        // ALPHA1228: alpha1227 placed SidecarPrefetchOutcomeId under BigStack, but the
        // ty/term re-entry call sites intentionally address EvalWorklist.  Keep this
        // seam in EvalWorklist so missing-after-prefetch is a typed semantic outcome
        // before it crosses back to Frame.status / JSON text.
        type SidecarPrefetchKindId =
            | SidecarPrefetchTy
            | SidecarPrefetchTerm
            | SidecarPrefetchUnknown of string

        let sidecarPrefetchKindOfString kind =
            match kind with
            | "ty" -> SidecarPrefetchTy
            | "term" -> SidecarPrefetchTerm
            | other -> SidecarPrefetchUnknown other

        let sidecarPrefetchKindText = function
            | SidecarPrefetchTy -> "ty"
            | SidecarPrefetchTerm -> "term"
            | SidecarPrefetchUnknown other -> other

        type SidecarPrefetchOutcomeId =
            | SidecarPrefetchFrameAvailable
            | SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeForFrame frameOpt =
            match frameOpt with
            | Some _ -> SidecarPrefetchFrameAvailable
            | None -> SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "missing_after_prefetch"

        let sidecarPrefetchStatusText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "semantic_missing_after_prefetch_blocked"

        // ALPHA1230/1231: missing-after-prefetch is a terminal only after the
        // replay lane proves quiet.  1230 proved pending protects the BigStack
        // handoff, but the same pin could still leak through the global-fuse
        // primary-message retarget path while a fresh replay frame was being
        // promoted.  Keep the contract as a typed decision and require a quiet
        // window before surfacing.
        type GenerationInvalidationCauseId =
            | GenerationInvalidationCauseNoneObserved
            | GenerationInvalidationCauseJpIvarWaitGenerationChanged
            | GenerationInvalidationCauseUnknownOrCacheGenerationRetry

        let private generationInvalidationCauseText = function
            | GenerationInvalidationCauseNoneObserved -> "none_observed"
            | GenerationInvalidationCauseJpIvarWaitGenerationChanged -> "jp_ivar_wait_generation_changed"
            | GenerationInvalidationCauseUnknownOrCacheGenerationRetry -> "unknown_or_cache_generation_retry"

        type PrefetchResolutionStatusId =
            | PrefetchResolutionResolved
            | PrefetchResolutionNotFoundAfterSidecarPrefetch
            | PrefetchResolutionGenerationDesyncCacheMiss
            | PrefetchResolutionEvictedOrInvalidated

        let private prefetchResolutionStatusText = function
            | PrefetchResolutionResolved -> "resolved"
            | PrefetchResolutionNotFoundAfterSidecarPrefetch -> "not_found_after_sidecar_prefetch"
            | PrefetchResolutionGenerationDesyncCacheMiss -> "generation_desync_cache_miss"
            | PrefetchResolutionEvictedOrInvalidated -> "evicted_or_invalidated"

        type NodeLifecycleEventId =
            | NodeLifecycleNoVisibleEvictionReceipt
            | NodeLifecycleInvalidatedByGenerationChange
            | NodeLifecycleMissingDependencyAfterPrefetch

        let private nodeLifecycleEventText = function
            | NodeLifecycleNoVisibleEvictionReceipt -> "missing_after_prefetch_without_visible_eviction_receipt"
            | NodeLifecycleInvalidatedByGenerationChange -> "invalidated_by_generation_change"
            | NodeLifecycleMissingDependencyAfterPrefetch -> "missing_dependency_after_prefetch"

        type MissingDependencyTailBlockerId =
            | MissingDependencyTailNone
            | MissingDependencyTailBlockedPrefetch
            | MissingDependencyTailBlockedGenerationDesync
            | MissingDependencyTailBlockedJpIvarWait

        let private missingDependencyTailBlockerText = function
            | MissingDependencyTailNone -> "none"
            | MissingDependencyTailBlockedPrefetch -> "blocked:missing_prefetch"
            | MissingDependencyTailBlockedGenerationDesync -> "blocked:generation_desync"
            | MissingDependencyTailBlockedJpIvarWait -> "blocked:jp_ivar_wait"

        type JpIvarWaitStateId =
            | JpIvarWaitStateNone
            | JpIvarWaitStateGenerationChangedErasedTag0
            | JpIvarWaitStateGenerationChangedUnknownTag

        let private jpIvarWaitStateText = function
            | JpIvarWaitStateNone -> "none"
            | JpIvarWaitStateGenerationChangedErasedTag0 -> "generation_desync_erased_tag_0"
            | JpIvarWaitStateGenerationChangedUnknownTag -> "generation_desync_unknown_tag"

        type CycleBreakPoisonLiveOverrideOutcomeId =
            | CycleBreakPoisonLiveOverrideNotAttempted
            | CycleBreakPoisonLiveOverrideGranted
            | CycleBreakPoisonLiveOverrideDeniedNoLiveTail
            | CycleBreakPoisonLiveOverrideDeniedNoSemanticRootEvidence
            | CycleBreakPoisonLiveOverrideDeniedRetryBudgetExhausted
            | CycleBreakPoisonLiveOverrideLegacyLiveRetry

        let private cycleBreakPoisonLiveOverrideOutcomeText = function
            | CycleBreakPoisonLiveOverrideNotAttempted -> "not_attempted"
            | CycleBreakPoisonLiveOverrideGranted -> "granted"
            | CycleBreakPoisonLiveOverrideDeniedNoLiveTail -> "denied_no_live_tail"
            | CycleBreakPoisonLiveOverrideDeniedNoSemanticRootEvidence -> "denied_no_semantic_or_root_evidence"
            | CycleBreakPoisonLiveOverrideDeniedRetryBudgetExhausted -> "denied_retry_budget_exhausted"
            | CycleBreakPoisonLiveOverrideLegacyLiveRetry -> "legacy_live_retry"

        type MissingAfterPrefetchTerminalDecisionId =
            | MissingAfterPrefetchNotTerminal
            | MissingAfterPrefetchSurfaceTerminal
            | MissingAfterPrefetchSurfacePinnedHighRankProgress
            | MissingAfterPrefetchSurfaceSmallPendingQueue
            | MissingAfterPrefetchSurfaceSmallLiveTail
            | MissingAfterPrefetchDeferLiveReplay
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferLiveTailProbation
            | MissingAfterPrefetchDeferQuietWindow
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter

        let missingAfterPrefetchTerminalDecisionText = function
            | MissingAfterPrefetchNotTerminal -> "not_missing_after_prefetch"
            | MissingAfterPrefetchSurfaceTerminal -> "surface_terminal"
            | MissingAfterPrefetchSurfacePinnedHighRankProgress -> "surface_pinned_high_rank_progress"
            | MissingAfterPrefetchSurfaceSmallPendingQueue -> "surface_small_pending_queue"
            | MissingAfterPrefetchSurfaceSmallLiveTail -> "surface_small_live_tail"
            | MissingAfterPrefetchDeferLiveReplay -> "defer_live_replay"
            | MissingAfterPrefetchDeferFreshReplayProgress -> "defer_fresh_replay_progress"
            | MissingAfterPrefetchDeferLiveTailProbation -> "defer_live_tail_probation"
            | MissingAfterPrefetchDeferQuietWindow -> "defer_quiet_window"
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail -> "defer_generation_desync_live_tail"
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted -> "surface_generation_desync_exhausted"
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption -> "surface_negative_pending_ledger_corruption"
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter -> "hard_surface_pending_zero_no_waiter"

        let missingAfterPrefetchTerminalDecisionFor status pending queueDepth activeDepth progressYield replayComplete writeWitness terminalAgeMs =
            let replayProgressEvidence =
                (try DiagJson.snapshotKindCount "eval_worklist_source_value_stored" with _ -> 0)
                + (try DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked" with _ -> 0)
            let liveReplayEvidence = queueDepth > 0 || activeDepth > 0 || progressYield
            let highRankProgressAuthority =
                pending = 0
                && not writeWitness
                && liveReplayEvidence
                && replayProgressEvidence >= 8
            let saturatedOrActiveLiveTail =
                queueDepth >= 16
                || activeDepth > 0
                || highRankProgressAuthority
            match semanticStatusOfString status with
            | SemanticMissingAfterPrefetchBlocked when pending < 0 -> MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && saturatedOrActiveLiveTail && not replayComplete -> MissingAfterPrefetchDeferLiveTailProbation
            | SemanticMissingAfterPrefetchBlocked when pending <= 1 && queueDepth <= 2 && activeDepth = 0 && not writeWitness -> MissingAfterPrefetchSurfaceSmallPendingQueue
            | SemanticMissingAfterPrefetchBlocked when pending <= 1 && queueDepth <= 8 && activeDepth <= 4 && not writeWitness && replayProgressEvidence >= 4 && terminalAgeMs >= 1500 -> MissingAfterPrefetchSurfaceSmallLiveTail
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 && terminalAgeMs < 1500 -> MissingAfterPrefetchDeferFreshReplayProgress
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 && terminalAgeMs < 12000 -> MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && terminalAgeMs < 5000 -> MissingAfterPrefetchDeferLiveTailProbation
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence && replayProgressEvidence > 0 -> MissingAfterPrefetchSurfaceGenerationDesyncExhausted
            | SemanticMissingAfterPrefetchBlocked when pending = 0 && not writeWitness && liveReplayEvidence -> MissingAfterPrefetchHardSurfacePendingZeroNoWaiter
            | SemanticMissingAfterPrefetchBlocked when pending > 0 || liveReplayEvidence -> MissingAfterPrefetchDeferLiveReplay
            | SemanticMissingAfterPrefetchBlocked when not replayComplete && not writeWitness && terminalAgeMs < 1000 -> MissingAfterPrefetchDeferQuietWindow
            | SemanticMissingAfterPrefetchBlocked -> MissingAfterPrefetchSurfaceTerminal
            | _ -> MissingAfterPrefetchNotTerminal

        let missingAfterPrefetchTerminalDecisionShouldDefer = function
            | MissingAfterPrefetchDeferLiveReplay
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferLiveTailProbation
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchDeferQuietWindow -> true
            | _ -> false

        let missingAfterPrefetchTerminalDecisionIsFreshProgressDefer = function
            | MissingAfterPrefetchDeferFreshReplayProgress
            | MissingAfterPrefetchDeferGenerationDesyncLiveTail
            | MissingAfterPrefetchDeferLiveTailProbation -> true
            | _ -> false

        let missingAfterPrefetchTerminalDecisionShouldHardSurface = function
            | MissingAfterPrefetchHardSurfacePendingZeroNoWaiter
            | MissingAfterPrefetchSurfaceNegativePendingLedgerCorruption
            | MissingAfterPrefetchSurfacePinnedHighRankProgress
            | MissingAfterPrefetchSurfaceSmallPendingQueue
            | MissingAfterPrefetchSurfaceSmallLiveTail
            | MissingAfterPrefetchSurfaceGenerationDesyncExhausted -> true
            | _ -> false

        type SidecarPrefetchTerminalReasonId =
            | SidecarTyReentryPrefetchMissingAfterPrefetch
            | SidecarTermReentryPrefetchMissingAfterPrefetch

        let sidecarPrefetchTerminalReasonText = function
            | SidecarTyReentryPrefetchMissingAfterPrefetch -> "ty_sidecar_prefetch_missing_after_prefetch"
            | SidecarTermReentryPrefetchMissingAfterPrefetch -> "term_sidecar_prefetch_missing_after_prefetch"

        // ALPHA979: this is the smallest compile-safe step away from stringly
        // scheduling in the new keyed global-fuse branch.  It does not pretend the
        // whole worklist is reimagined yet; it gives the fuse path a real decision
        // value carrying the repeat/cap evidence, with string rendering confined to
        // the logging / Frame.status boundary.
        type GlobalFuseReplayDecision =
            | ParentContinuationFuseDeferred of int * int
            | ParentContinuationFuseDeferredTypeHole of int * int
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness of int * int
            | ParentContinuationFuseReplayRootWitnessPreserved of int * int
            | ParentContinuationFuseBlocked of int * int
            | OrphanGlobalFuseDeferred of int * int
            | OrphanGlobalFuseBlocked of int * int

        let globalFuseReplayDecisionRepeat decision =
            match decision with
            | ParentContinuationFuseDeferred(repeat, _)
            | ParentContinuationFuseDeferredTypeHole(repeat, _)
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness(repeat, _)
            | ParentContinuationFuseReplayRootWitnessPreserved(repeat, _)
            | ParentContinuationFuseBlocked(repeat, _)
            | OrphanGlobalFuseDeferred(repeat, _)
            | OrphanGlobalFuseBlocked(repeat, _) -> repeat

        let globalFuseReplayDecisionCap decision =
            match decision with
            | ParentContinuationFuseDeferred(_, cap)
            | ParentContinuationFuseDeferredTypeHole(_, cap)
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness(_, cap)
            | ParentContinuationFuseReplayRootWitnessPreserved(_, cap)
            | ParentContinuationFuseBlocked(_, cap)
            | OrphanGlobalFuseDeferred(_, cap)
            | OrphanGlobalFuseBlocked(_, cap) -> cap

        let globalFuseReplayDecisionStatusId decision =
            match decision with
            | ParentContinuationFuseDeferred _ -> SemanticParentContinuationCycleDeferred
            | ParentContinuationFuseDeferredTypeHole _ -> SemanticStepPartial
            | ParentContinuationFuseDeferredTypeHoleWithReplayRootWitness _ -> SemanticStepPartial
            | ParentContinuationFuseReplayRootWitnessPreserved _ -> SemanticStepPartial
            | ParentContinuationFuseBlocked _ -> SemanticGlobalFuseParentContinuationCycleBlocked
            | OrphanGlobalFuseDeferred _ -> SemanticStepPartial
            | OrphanGlobalFuseBlocked _ -> SemanticGlobalFuseParentContinuationCycleBlocked

        let globalFuseReplayDecisionStatusText decision =
            decision |> globalFuseReplayDecisionStatusId |> semanticStatusToString

        // ALPHA1200: alpha1199 proves alpha1199 advanced past the metronome
        // no-work frontier and returned to a concrete rank-80 parent-continuation
        // global-fuse pin.  The pin is useful only after the live replay lane is
        // empty or after a bounded late-drain grace has been consumed.  Keep that
        // arbitration as data so term/ty global-fuse sites do not surface an
        // EJP0011 while pending replay, queued replay, active drivers, or progress
        // yield are still alive.
        type ParentFuseStarvationTerminalDecisionId =
            | ParentFuseStarvationNotReached
            | ParentFuseStarvationDeferLiveReplay
            | ParentFuseStarvationDeferFreshRootReplay
            | ParentFuseStarvationProbeProgressingReplay
            | ParentFuseStarvationDeferRecentProgressReplay
            | ParentFuseStarvationFailFastLiveReplayDrip
            | ParentFuseStarvationPinTerminal

        let parentFuseStarvationTerminalDecisionText = function
            | ParentFuseStarvationNotReached -> "not_reached"
            | ParentFuseStarvationDeferLiveReplay -> "defer_live_replay"
            | ParentFuseStarvationDeferFreshRootReplay -> "defer_fresh_root_replay"
            | ParentFuseStarvationProbeProgressingReplay -> "probe_progressing_replay"
            | ParentFuseStarvationDeferRecentProgressReplay -> "defer_recent_progress_replay"
            | ParentFuseStarvationFailFastLiveReplayDrip -> "failfast_live_replay_drip"
            | ParentFuseStarvationPinTerminal -> "pin_terminal"

        let parentFuseStarvationTerminalDecisionFor starved pendingCount queueDepth activeDepth hasProgressYield freshRootWitness recentProgress repeat cap =
            let liveReplay = pendingCount > 0 && (queueDepth > 0 || activeDepth > 0 || hasProgressYield)
            if not starved then ParentFuseStarvationNotReached
            elif liveReplay && freshRootWitness && repeat <= (cap + 24) then ParentFuseStarvationDeferFreshRootReplay
            elif liveReplay && recentProgress && hasProgressYield && activeDepth > 0 && repeat <= (cap + 32) then ParentFuseStarvationDeferRecentProgressReplay
            elif liveReplay && queueDepth > 0 && activeDepth > 0 && hasProgressYield && repeat <= (cap + 16) then ParentFuseStarvationProbeProgressingReplay
            elif liveReplay && repeat <= (cap + 8) then ParentFuseStarvationDeferLiveReplay
            elif liveReplay && recentProgress then ParentFuseStarvationFailFastLiveReplayDrip
            else ParentFuseStarvationPinTerminal

        // ALPHA1192: classify the final global-fuse abort cause as data before it
        // is rendered into an EJP0011 message.  Alpha1191 reached real replay and
        // failed on a dynamic-join terminal whose original fuse text still carried
        // raw English suffixes.  Keep those suffixes at the final human boundary,
        // but make the policy/logging seam a closed DU.
        type GlobalFuseAbortCauseId =
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow
            | GlobalFuseAbortGenericTermGlobalFuse
            | GlobalFuseAbortGenericTyGlobalFuse

        let globalFuseAbortCauseText = function
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow -> "term_parent_continuation_replay_cap_exhausted_before_stackoverflow"
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow -> "ty_parent_continuation_replay_cap_exhausted_before_stackoverflow"
            | GlobalFuseAbortGenericTermGlobalFuse -> "term_global_fuse"
            | GlobalFuseAbortGenericTyGlobalFuse -> "ty_global_fuse"

        let globalFuseAbortCauseMessage = function
            | GlobalFuseAbortTermParentContinuationReplayCapExhaustedBeforeStackOverflow -> "parent-continuation replay cap exhausted before StackOverflow"
            | GlobalFuseAbortTyParentContinuationReplayCapExhaustedBeforeStackOverflow -> "ty parent-continuation replay cap exhausted before StackOverflow"
            | GlobalFuseAbortGenericTermGlobalFuse -> "aborting term worker before StackOverflow"
            | GlobalFuseAbortGenericTyGlobalFuse -> "aborting ty worker before StackOverflow"

        // ALPHA1169: keep retry-stop terminal/replay arbitration typed.  The old
        // branch was already mostly correct, but alpha1168 proved the late global
        // fuse terminal can arrive while pending replay is still live and the
        // generic yield cap has been consumed.  The DU records whether retry-stop
        // should abort, consume the normal progress-yield path, or enter the
        // global-fuse-specific live drain extension.
        type RetryStopFrontierDecisionId =
            | RetryStopNoReplay
            | RetryStopProgressYield
            | RetryStopGlobalFuseLiveDrain
            | RetryStopGlobalFuseLiveQueueDrain
            | RetryStopGlobalFusePendingStackFenceDrain
            | RetryStopDynamicJoinPendingStackFenceDrain
            | RetryStopDynamicJoinLiveDrain
            | RetryStopDynamicJoinLiveQueueDrain
            | RetryStopParentReplayStatusLiveDrain
            | RetryStopParentReplayStatusQueueDrain
            | RetryStopTerminalContractAbort
            | RetryStopBlockedAbort

        let retryStopFrontierDecisionText = function
            | RetryStopNoReplay -> "no_replay"
            | RetryStopProgressYield -> "progress_yield"
            | RetryStopGlobalFuseLiveDrain -> "global_fuse_live_drain"
            | RetryStopGlobalFuseLiveQueueDrain -> "global_fuse_live_queue_drain"
            | RetryStopGlobalFusePendingStackFenceDrain -> "cycle_fuse_deferred_by_pending_stack_fence"
            | RetryStopDynamicJoinPendingStackFenceDrain -> "dynamic_join_deferred_by_pending_stack_fence"
            | RetryStopDynamicJoinLiveDrain -> "dynamic_join_live_drain"
            | RetryStopDynamicJoinLiveQueueDrain -> "dynamic_join_live_queue_drain"
            | RetryStopParentReplayStatusLiveDrain -> "parent_replay_status_live_drain"
            | RetryStopParentReplayStatusQueueDrain -> "parent_replay_status_queue_drain"
            | RetryStopTerminalContractAbort -> "terminal_contract_abort"
            | RetryStopBlockedAbort -> "blocked_abort"

        // ALPHA1184: 1183 was the first good diagnostic run after the no-work
        // frontier, but the final retry_stop_drain still let a rank-80 global-fuse
        // parent-continuation pin retarget a live continuation envelope while pending
        // replay was alive.  Keep that arbitration typed and generic: a global fuse
        // pin is terminal only after the live replay/continuation/root evidence lane
        // is empty or quiet.  This is selection hygiene; it does not synthesize any
        // value, writer witness, root proof, codegen output, or BuildOk.
        type RetryDrainPinnedTerminalDecisionId =
            | RetryDrainPinTerminal
            | RetryDrainDeferGlobalFuseLiveReplay
            | RetryDrainDeferGlobalFuseContinuationEnvelope
            | RetryDrainDeferDynamicJoinRunnableReplay
            | RetryDrainDeferDynamicJoinPendingReplay
            | RetryDrainPreserveRootEvidence

        let retryDrainPinnedTerminalDecisionText = function
            | RetryDrainPinTerminal -> "pin_terminal"
            | RetryDrainDeferGlobalFuseLiveReplay -> "defer_global_fuse_live_replay"
            | RetryDrainDeferGlobalFuseContinuationEnvelope -> "defer_global_fuse_continuation_envelope"
            | RetryDrainDeferDynamicJoinRunnableReplay -> "defer_dynamic_join_runnable_replay"
            | RetryDrainDeferDynamicJoinPendingReplay -> "defer_dynamic_join_pending_replay"
            | RetryDrainPreserveRootEvidence -> "preserve_root_evidence"

        type RetryDrainLiveEvidenceId =
            | RetryDrainNoLiveEvidence
            | RetryDrainPendingOnly
            | RetryDrainQueueLive
            | RetryDrainActiveDriverLive
            | RetryDrainProgressYieldLive

        let retryDrainLiveEvidenceText = function
            | RetryDrainNoLiveEvidence -> "none"
            | RetryDrainPendingOnly -> "pending_only"
            | RetryDrainQueueLive -> "queue_live"
            | RetryDrainActiveDriverLive -> "active_driver_live"
            | RetryDrainProgressYieldLive -> "progress_yield_live"

        let retryDrainLiveEvidenceFor pending queueDepth activeDepth progressYield =
            if pending <= 0 then RetryDrainNoLiveEvidence
            elif queueDepth > 0 then RetryDrainQueueLive
            elif activeDepth > 0 then RetryDrainActiveDriverLive
            elif progressYield then RetryDrainProgressYieldLive
            else RetryDrainPendingOnly

        let retryDrainLiveEvidenceIsLive = function
            | RetryDrainNoLiveEvidence
            | RetryDrainPendingOnly -> false
            | RetryDrainQueueLive
            | RetryDrainActiveDriverLive
            | RetryDrainProgressYieldLive -> true

        let retryDrainLiveEvidenceHasPending = function
            | RetryDrainNoLiveEvidence -> false
            | _ -> true

        let retryDrainPinnedTerminalDecisionFor pinnedStatus frameStatus pending queueDepth activeDepth progressYield freshRootWitness =
            let liveEvidence = retryDrainLiveEvidenceFor pending queueDepth activeDepth progressYield
            let liveReplay = retryDrainLiveEvidenceIsLive liveEvidence
            let pendingReplay = retryDrainLiveEvidenceHasPending liveEvidence
            let drainableFrame =
                frameStatus = "continuation_envelope"
                || isLiveOrRootCompleteFrameStatus frameStatus
                || frameStatus = "semantic_leaf_complete"
                || frameStatus = "semantic_step_partial"
                || frameStatus = "semantic_replay_driver_exception_blocked"
            if pinnedStatus = "semantic_dynamic_join_apply_blocked" && liveReplay && drainableFrame then
                RetryDrainDeferDynamicJoinRunnableReplay
            elif pinnedStatus = "semantic_dynamic_join_apply_blocked" && pendingReplay && frameStatus = "continuation_envelope" then
                RetryDrainDeferDynamicJoinPendingReplay
            elif pinnedStatus <> "semantic_global_fuse_parent_continuation_cycle_blocked" then
                RetryDrainPinTerminal
            elif liveReplay && frameStatus = "continuation_envelope" then
                RetryDrainDeferGlobalFuseContinuationEnvelope
            elif liveReplay && freshRootWitness && isLiveOrRootCompleteFrameStatus frameStatus then
                RetryDrainPreserveRootEvidence
            elif liveReplay && (isLiveOrRootCompleteFrameStatus frameStatus || frameStatus = "semantic_leaf_complete" || frameStatus = "semantic_replay_driver_exception_blocked") then
                RetryDrainDeferGlobalFuseLiveReplay
            else
                RetryDrainPinTerminal

        let retryStopFrontierDecisionFor replayOrLiveTerminal terminalReplayContractBlocked terminalGlobalFuseParentContinuationBlocked terminalDynamicJoinApplyBlocked terminalParentReplayStatusPreservedBlocked replayStillRunnable pendingCount queueDepth activeDepth hasProgressYield frontierUsed frontierCap globalFuseUsed globalFuseCap dynamicJoinUsed dynamicJoinCap =
            if not replayOrLiveTerminal then RetryStopNoReplay
            elif terminalParentReplayStatusPreservedBlocked then RetryStopTerminalContractAbort
            elif terminalGlobalFuseParentContinuationBlocked && pendingCount > 0 && activeDepth > 0 && globalFuseUsed < (globalFuseCap * 2) then RetryStopGlobalFusePendingStackFenceDrain
            elif terminalDynamicJoinApplyBlocked && pendingCount > 0 && activeDepth > 0 && dynamicJoinUsed < (dynamicJoinCap * 2) then RetryStopDynamicJoinPendingStackFenceDrain
            elif terminalGlobalFuseParentContinuationBlocked && replayStillRunnable && pendingCount > 0 && hasProgressYield && globalFuseUsed < globalFuseCap then RetryStopGlobalFuseLiveDrain
            elif terminalGlobalFuseParentContinuationBlocked && replayStillRunnable && pendingCount > 0 && queueDepth > 0 && globalFuseUsed < globalFuseCap then RetryStopGlobalFuseLiveQueueDrain
            elif terminalDynamicJoinApplyBlocked && replayStillRunnable && pendingCount > 0 && hasProgressYield && dynamicJoinUsed < dynamicJoinCap then RetryStopDynamicJoinLiveDrain
            elif terminalDynamicJoinApplyBlocked && replayStillRunnable && pendingCount > 0 && dynamicJoinUsed < dynamicJoinCap then RetryStopDynamicJoinLiveQueueDrain
            elif terminalReplayContractBlocked then RetryStopTerminalContractAbort
            elif hasProgressYield && frontierUsed < frontierCap then RetryStopProgressYield
            else RetryStopBlockedAbort


        type SemanticTerminalContract = {
            rank: int
            next: string
        }

        let private semanticTerminalContract status =
            match status with
            | SemanticMacroThunkMissingBlocked -> Some { rank = 100; next = "explicit_eval_worklist_macro_thunk_required" }
            | SemanticCodegenJpBodyDictMissingBlocked -> Some { rank = 99; next = "explicit_codegen_jp_body_dict_required" }
            | SemanticErrorTypeBlocked -> Some { rank = 96; next = "explicit_eval_worklist_error_type_message_ready" }
            | SemanticLiteralOpBodyStepperBlocked -> Some { rank = 95; next = "explicit_eval_worklist_literal_op_body_stepper_required" }
            | SemanticOpImplRequiredBlocked -> Some { rank = 94; next = "materialize_op_impl_required_authoring_terminal_no_scheduler_deferral" }
            | SemanticApplySeqUnknownReturnWitnessBlocked -> Some { rank = 93; next = "native_hopac_apply_seq_unknown_return_witness_direct_required" }
            | SemanticApplyContinuationAfterSeqUnknownBlocked -> Some { rank = 92; next = "native_hopac_apply_continuation_after_seq_unknown_direct_required" }
            | SemanticDynamicJoinApplyBlocked -> Some { rank = 92; next = "native_hopac_dynamic_join_apply_direct_required" }
            | SemanticApplySpineMissingDirectValueBlocked -> Some { rank = 92; next = "native_hopac_apply_spine_store_direct_required" }
            // ALPHA1227: sidecar prefetch can prove that the explicit worklist has no frame
            // for a concrete recursive term/type key while BigStack has no scheduler work.
            // Rank it high enough to stop the multi-minute hot-frontier loop, but still
            // below concrete op/apply/dynamic-join obligations.
            | SemanticMissingAfterPrefetchBlocked -> Some { rank = 91; next = "native_hopac_missing_after_prefetch_direct_required" }
            | SemanticSeqUnknownReturnWitnessBlocked -> Some { rank = 91; next = "native_hopac_seq_unknown_return_witness_direct_required" }
            | SemanticIfUnknownReturnConditionBlocked -> Some { rank = 90; next = "fill_parent_continuation_ivar_immediately" }
            | SemanticIfSymbolicConditionBlocked -> Some { rank = 89; next = "native_hopac_if_symbolic_condition_direct_required" }
            | SemanticRecordWithValueBlocked -> Some { rank = 88; next = "native_hopac_record_with_stepper_direct_required" }
            | SemanticAnnotTestBranchSelectionBlocked -> Some { rank = 87; next = "native_hopac_annot_test_branch_selection_direct_required" }
            | SemanticUnboxReplayBlocked -> Some { rank = 87; next = "native_hopac_unbox_stepper_direct_required" }
            | SemanticTypeApplyNominalConstructorStepperBlocked -> Some { rank = 87; next = "explicit_eval_worklist_type_apply_nominal_constructor_stepper_required" }
            | SemanticNominalConstructorStepperBlocked -> Some { rank = 86; next = "explicit_eval_worklist_nominal_constructor_stepper_required" }
            | SemanticTermTypeValueBlocked -> Some { rank = 86; next = "explicit_eval_worklist_term_type_value_required" }
            | SemanticReplayChildScheduleRepeatBlocked -> Some { rank = 85; next = "explicit_eval_worklist_replay_child_schedule_repeat_required" }
            | SemanticPairValueBlocked -> Some { rank = 84; next = "explicit_eval_worklist_pair_value_required" }
            | SemanticTypeApplyNestedForallStepperBlocked -> Some { rank = 84; next = "explicit_eval_worklist_type_apply_nested_forall_stepper_required" }
            | SemanticSeqTypeErrorBlocked -> Some { rank = 83; next = "explicit_eval_worklist_seq_type_error_required" }
            | SemanticLeafParentContinuationMissingBlocked -> Some { rank = 82; next = "explicit_eval_worklist_leaf_parent_continuation_required" }
            | SemanticUnitTestValueBlocked -> Some { rank = 82; next = "explicit_eval_worklist_unit_test_value_required" }
            | SemanticTypeApplyForallBodyStepperBlocked -> Some { rank = 81; next = "explicit_eval_worklist_type_apply_forall_body_stepper_required" }
            | SemanticTypeVariableValueMissingBlocked -> Some { rank = 80; next = "explicit_eval_worklist_type_variable_env_required" }
            | SemanticApplyContinuationExceptionBlocked -> Some { rank = 79; next = "explicit_eval_worklist_apply_continuation_exception_required" }
            | SemanticReplayFingerprintRepeatBlocked -> Some { rank = 79; next = "explicit_eval_worklist_replay_fingerprint_repeat_required" }
            // ALPHA1001: runtime 1000 emitted this bounded terminal 21 times but
            // highRankPinnedTerminal only retargets ranks >= 80.  Rank it at the
            // high-rank boundary so the existing pinned-terminal retarget path can
            // stop the manual-interrupt loop without inventing a value or BuildOk.
            | SemanticGlobalFuseParentContinuationCycleBlocked -> Some { rank = 80; next = "explicit_eval_worklist_global_fuse_parent_continuation_cycle_required" }
            // ALPHA1303: the v1302 frontier is not the older blocked global-fuse case;
            // it is a deferred-child parent-continuation cycle that becomes Phase 2
            // material once q/a/p reaches 2/0/1.  Rank it above parent replay poison
            // so the transition hook can see it explicitly.
            | SemanticParentContinuationCycleDeferred -> Some { rank = 90; next = "fill_parent_continuation_ivar_immediately" }
            | SemanticParentReplayCycleBreakPoisoned -> Some { rank = 91; next = "fill_parent_replay_cycle_break_poison_ivar_immediately" }
            | SemanticParentReplayStatusPreservedRepeatBlocked -> Some { rank = 88; next = "native_hopac_callback_or_threadpool_replay_driver_tick" }
            | SemanticReentrantReplayDriverStarvationBlocked -> Some { rank = 78; next = "explicit_eval_worklist_reentrant_replay_driver_starvation_required" }
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked -> Some { rank = 77; next = "explicit_eval_worklist_root_complete_stale_retarget_required" }
            | SemanticRootCompleteStaleRetargetRepeatBlocked -> Some { rank = 77; next = "explicit_eval_worklist_root_complete_stale_retarget_required" }
            | SemanticAppRootBase16StaleRetargetHardcapBlocked -> Some { rank = 76; next = "explicit_eval_worklist_app_root_base16_stale_retarget_required" }
            | SemanticRootCompletePendingJobsBlocked -> Some { rank = 76; next = "explicit_eval_worklist_root_complete_pending_jobs_required" }
            | SemanticSelectedFrontierRepeatBlocked -> Some { rank = 76; next = "explicit_eval_worklist_selected_frontier_stepper_required" }
            | SemanticTjoinpointStepperBlocked -> Some { rank = 75; next = "explicit_eval_worklist_tjoinpoint_stepper_required" }
            // ALPHA1096: runtime 1095 pinned semantic_joinpoint_value_blocked repeatedly but
            // rank 74 let higher-rank generic/global-fuse evidence keep the build alive until
            // manual interruption.  This is now a concrete missing EJoinPoint' value terminal.
            | SemanticJoinpointValueBlocked -> Some { rank = 81; next = "explicit_eval_worklist_joinpoint_value_required" }
            | SemanticJoinpointTermStepperBlocked -> Some { rank = 72; next = "explicit_eval_worklist_joinpoint_term_stepper_required" }
            | SemanticReplayPayloadMissingBlocked -> Some { rank = 69; next = "explicit_eval_worklist_replay_payload_required" }
            // ALPHA1014: runtime 1013 showed a concrete replay-driver NullReferenceException
            // arriving after a generic rank-80 global-fuse pin. Rank this above global-fuse
            // and annot-test/unbox diagnostics, but still below concrete op/codegen terminals.
            | SemanticReplayDriverExceptionBlocked -> Some { rank = 88; next = "explicit_eval_worklist_replay_driver_exception_required" }
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> Some { rank = 91; next = "fill_parent_continuation_ivar_immediately" }
            | SemanticParentContinuationCycleBlocked -> Some { rank = 60; next = "explicit_eval_worklist_parent_continuation_cycle_required" }
            | SemanticStaleRootRetargetBlocked -> Some { rank = 55; next = "explicit_eval_worklist_stale_root_retarget_required" }
            | SemanticLetSuccessAllReadyApplyBlocked -> Some { rank = 45; next = "explicit_eval_worklist_let_success_all_ready_apply_required" }
            | SemanticDeferredFunctionReplayExceptionBlocked -> Some { rank = 40; next = "explicit_eval_worklist_deferred_function_replay_exception_required" }
            | SemanticLetSuccessApplyContinuationBlocked -> Some { rank = 35; next = "explicit_eval_worklist_let_success_apply_continuation_required" }
            | SemanticLetSuccessApplyExceptionBlocked -> Some { rank = 30; next = "explicit_eval_worklist_let_success_apply_exception_required" }
            | _ -> None

        let private semanticTerminalContractForText (status: string) =
            status |> semanticStatusOfString |> semanticTerminalContract

        // ALPHA1101: public diagnostics seam for callers outside EvalWorklist.
        // It preserves the closed SemanticStatusId conversion internally while keeping
        // JSON boundaries readable and backward-compatible.
        let semanticStatusCanonicalText (status: string) =
            status |> semanticStatusOfString |> semanticStatusToString

        // Keep BigStack terminal handoff decisions typed internally: callers still
        // receive legacy status text from Frame.status, but branch selection is a
        // closed DU instead of ad-hoc string equality.
        type BigStackPinnedTerminalStatus =
            | BigStackPinnedConcreteOpTerminal
            | BigStackPinnedGlobalFuseTerminal
            | BigStackPinnedOtherTerminal of string

        let bigStackPinnedTerminalStatus (status: string) =
            match semanticStatusOfString status with
            | SemanticOpImplRequiredBlocked -> BigStackPinnedConcreteOpTerminal
            | SemanticGlobalFuseParentContinuationCycleBlocked -> BigStackPinnedGlobalFuseTerminal
            | other -> BigStackPinnedOtherTerminal (semanticStatusToString other)

        // ALPHA1193: alpha1192 proved that terminal_cause_du is emitted correctly,
        // but the BigStack join still accepted a just-pinned rank-80 parent-continuation
        // global-fuse terminal at terminal_age=0ms while pending replay/root returns were
        // still draining.  Keep the fail-closed terminal, but make that handoff a typed
        // decision and give young pending parent-continuation pins one bounded drain lease.
        type BigStackPinnedTerminalHandoffDecisionId =
            | BigStackPinnedTerminalHandoffReady
            | BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse

        let bigStackPinnedTerminalHandoffDecisionText = function
            | BigStackPinnedTerminalHandoffReady -> "handoff_ready"
            | BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse -> "defer_young_pending_parent_continuation_fuse"

        let bigStackPinnedTerminalHandoffDecisionFor status pendingCount terminalAgeMs youngPendingAgeCapMs =
            match semanticStatusOfString status with
            | SemanticGlobalFuseParentContinuationCycleBlocked when pendingCount > 0 && terminalAgeMs < youngPendingAgeCapMs ->
                BigStackPinnedTerminalDeferYoungPendingParentContinuationFuse
            | _ -> BigStackPinnedTerminalHandoffReady

        type BigStackPinnedTerminalQueueDrainDecisionId =
            | BigStackPinnedTerminalQueueDrainNotNeeded
            | BigStackPinnedTerminalQueueDrainPoisonTail
            | BigStackPinnedTerminalQueueDrainStatusPreservedTail
            | BigStackPinnedTerminalQueueDrainPendingTail
            | BigStackPinnedTerminalQueueDrainDynamicJoinTail
            | BigStackPinnedTerminalQueueDrainYoungTerminalTail
            | BigStackPinnedTerminalQueueDrainLateRaceTail
            | BigStackPinnedTerminalQueueDrainActiveOnlyGrace
            | BigStackPinnedTerminalQueueDrainQuietPoisonGrace
            | BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace
            | BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail
            | BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail
            | BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail

        let bigStackPinnedTerminalQueueDrainDecisionText = function
            | BigStackPinnedTerminalQueueDrainNotNeeded -> "queue_drain_not_needed"
            | BigStackPinnedTerminalQueueDrainPoisonTail -> "poison_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainStatusPreservedTail -> "status_preserved_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainPendingTail -> "pending_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainDynamicJoinTail -> "dynamic_join_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainYoungTerminalTail -> "young_terminal_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainLateRaceTail -> "late_race_tail_queue_drain"
            | BigStackPinnedTerminalQueueDrainActiveOnlyGrace -> "active_only_tail_grace"
            | BigStackPinnedTerminalQueueDrainQuietPoisonGrace -> "quiet_poison_terminal_grace"
            | BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace -> "quiet_status_preserved_terminal_grace"
            | BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail -> "replay_incomplete_pending_tail"
            | BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail -> "parent_poison_pending_stack_fence_tail"
            | BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail -> "parent_poison_active_queue_tail"

        let bigStackPinnedTerminalQueueDrainDecisionFor status pendingCount queueDepth activeDepth terminalAgeMs queueDrainAgeCapMs replayComplete =
            let tailLive = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let activeOnlyTail = pendingCount <= 0 && queueDepth <= 0 && activeDepth > 0
            let shortPoisonTailAgeCapMs = min queueDrainAgeCapMs 500
            let quietPoisonAgeCapMs = 0
            let statusPreservedTailAgeCapMs = min queueDrainAgeCapMs 3000
            let dynamicJoinTailAgeCapMs = min queueDrainAgeCapMs 6000
            match semanticStatusOfString status with
            | SemanticParentReplayCycleBreakPoisoned when tailLive && terminalAgeMs < shortPoisonTailAgeCapMs ->
                BigStackPinnedTerminalQueueDrainPoisonTail
            | SemanticParentReplayCycleBreakPoisoned when pendingCount > 0 && activeDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // ALPHA1487: 1486.jsonl proved replay_complete/write_witness can flicker true
                // while p=2/a>0 are still behind a stack fence.  Do not let the legacy
                // old-poison 3s fail-closed branch snap before the pending fence gets its
                // bounded IVar/Alt-style drain window.
                BigStackPinnedTerminalQueueDrainParentPoisonPendingStackFenceTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount > 0 && queueDepth <= 0 && activeDepth > 0 && terminalAgeMs >= 12000 ->
                // ALPHA1366: pending work is not a drain license after the queue is empty,
                // active workers are only a quiescent tail, and the pinned poison has aged.
                // Surface through the normal terminal handoff instead of replay-only chatter.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount = 0 && queueDepth >= 16 && activeDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // ALPHA1489: 1488.jsonl moved beyond the dynamic-join frontier, then pinned
                // parent poison at pending=0 while queue≈98/active=4 and replay commits were
                // still arriving.  Pending-zero is not automatically quiet when the active
                // queue is materially draining; give it one bounded active-queue lease before
                // the legacy old_poison_tail_fail_closed handoff may surface EJP0021.
                BigStackPinnedTerminalQueueDrainParentPoisonActiveQueueTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && pendingCount > 0 && terminalAgeMs < max queueDrainAgeCapMs 60000 ->
                // ALPHA1290: runtime 1289 reached a generic ty_replay_driver/TFun pinned terminal
                // with pending=2 queue=2 and replay_complete=false.  The old poison branch
                // treated that as mature after the short 500ms poison-tail grace; keep draining
                // pending replay completeness instead of surfacing EJP0021 while work is owned.
                BigStackPinnedTerminalQueueDrainReplayIncompletePendingTail
            | SemanticParentReplayCycleBreakPoisoned when (not replayComplete) && terminalAgeMs < quietPoisonAgeCapMs ->
                // ALPHA1266: runtime 1265 reached pending=0/q=0/a=0 with replay_complete=false,
                // then near-simultaneous child replay scheduling and poison cascades still appeared
                // around the terminal handoff. Treat that as a quiet drain window, not proof that
                // EJP0021 is mature.
                BigStackPinnedTerminalQueueDrainQuietPoisonGrace
            | SemanticParentReplayCycleBreakPoisoned when tailLive ->
                // ALPHA1270: alpha1269 kept a poisoned terminal alive for hundreds of
                // seconds because the old queueDrainAgeCapMs still allowed poison_tail_queue_drain
                // until the late-race window.  Once the short poison-tail grace expires,
                // surface the fail-closed terminal instead of recycling stale tail churn.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | SemanticParentReplayStatusPreservedRepeatBlocked when tailLive && terminalAgeMs < statusPreservedTailAgeCapMs ->
                BigStackPinnedTerminalQueueDrainStatusPreservedTail
            | SemanticParentReplayStatusPreservedRepeatBlocked when (not replayComplete) && terminalAgeMs < quietPoisonAgeCapMs ->
                BigStackPinnedTerminalQueueDrainQuietStatusPreservedGrace
            | SemanticDynamicJoinApplyBlocked when tailLive && terminalAgeMs < dynamicJoinTailAgeCapMs ->
                // ALPHA1298: runtime 1297 reached rank-92 dynamic join with p/q/a shrinking to 1/4/0
                // and only replay trickle/terminal churn left. Give that tail one small bounded drain
                // window, then surface the explicit dynamic-join obligation instead of recycling the
                // late-race queue drain forever.
                BigStackPinnedTerminalQueueDrainDynamicJoinTail
            | SemanticDynamicJoinApplyBlocked when tailLive ->
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when activeOnlyTail && terminalAgeMs < queueDrainAgeCapMs ->
                BigStackPinnedTerminalQueueDrainActiveOnlyGrace
            | _ when activeOnlyTail ->
                // ALPHA1268: q=0/p=0/a>0 for an old pinned terminal is not a schedulable orphan
                // drain.  Runtime 1267 kept requesting four forced workers every 250ms while
                // each returned scheduled_async=false; after the bounded grace, surface the
                // fail-closed terminal instead of hiding it behind infinite late-race drain.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when not tailLive -> BigStackPinnedTerminalQueueDrainNotNeeded
            | _ when pendingCount > 0 && terminalAgeMs < queueDrainAgeCapMs ->
                BigStackPinnedTerminalQueueDrainPendingTail
            | _ when terminalAgeMs < min queueDrainAgeCapMs 4000 ->
                BigStackPinnedTerminalQueueDrainYoungTerminalTail
            | _ when queueDepth > 0 && terminalAgeMs < max queueDrainAgeCapMs 8000 ->
                BigStackPinnedTerminalQueueDrainLateRaceTail
            | _ when tailLive ->
                // ALPHA1269: if a poisoned/status-preserved terminal is old and the only
                // evidence is a tiny persistent tail, another late-race drain just emits
                // unschedulable orphan workers.  Let the caller surface the terminal contract.
                BigStackPinnedTerminalQueueDrainNotNeeded
            | _ -> BigStackPinnedTerminalQueueDrainNotNeeded

        let isRootCompleteStaleRetargetLiveReplayLivelockStatus (status: string) =
            match semanticStatusOfString status with
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> true
            | _ -> false

        // ALPHA1171: make the late BigStack stale-retarget handoff a typed decision.
        // Runtime 1170 proved the old Boolean gate was too narrow: replay_complete/write_witness
        // can flip true while the selected replay cell still reports replay_completeness=not_complete
        // and the rich tick is still seeing replay/root/terminal deltas.  This DU keeps the old
        // fail-closed terminal, but defers it while there is either directly runnable replay or
        // fresh replay/root/terminal progress around the captured root-stale-retarget terminal.
        type RootStaleRetargetHandoffDecisionId =
            | RootStaleRetargetNotTerminal
            | RootStaleRetargetDeferActiveReplay
            | RootStaleRetargetDeferRecentReplayProgress
            | RootStaleRetargetDeferDynamicRecordKeyBridgeTail
            | RootStaleRetargetPoisonCascadeHandoffReady
            | RootStaleRetargetTerminalChurnHandoffReady
            | RootStaleRetargetDeferredChildLivelockHandoffReady
            | RootStaleRetargetDeferredHoleSweepRequired
            | RootStaleRetargetDurableActiveReplayHandoffReady
            | RootStaleRetargetHandoffReady

        let rootStaleRetargetHandoffDecisionText = function
            | RootStaleRetargetNotTerminal -> "not_terminal"
            | RootStaleRetargetDeferActiveReplay -> "defer_active_replay"
            | RootStaleRetargetDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | RootStaleRetargetDeferDynamicRecordKeyBridgeTail -> "defer_dynamic_record_key_bridge_tail"
            | RootStaleRetargetPoisonCascadeHandoffReady -> "poison_cascade_handoff_ready"
            | RootStaleRetargetTerminalChurnHandoffReady -> "terminal_churn_handoff_ready"
            | RootStaleRetargetDeferredChildLivelockHandoffReady -> "deferred_child_livelock_handoff_ready"
            | RootStaleRetargetDeferredHoleSweepRequired -> "deferred_hole_sweep_required"
            | RootStaleRetargetDurableActiveReplayHandoffReady -> "durable_active_replay_handoff_ready"
            | RootStaleRetargetHandoffReady -> "handoff_ready"

        let rootStaleRetargetReasonLooksDeferredChild (reason: string) =
            reason.Contains("idle_deferred_child_cell", StringComparison.Ordinal)
            || reason.Contains("deferred_child_cell", StringComparison.Ordinal)
            || reason.Contains("DeferredChildCell", StringComparison.Ordinal)
            || reason.Contains("deferred_child", StringComparison.Ordinal)

        let rootStaleRetargetReasonLooksDeferredHoleSweepCandidate (reason: string) =
            rootStaleRetargetReasonLooksDeferredChild reason
            || reason.Contains("DeferredTypeVar", StringComparison.Ordinal)
            || reason.Contains("deferred_type", StringComparison.Ordinal)
            || reason.Contains("hole", StringComparison.Ordinal)

        let rootStaleRetargetHandoffDecisionFor (status: string) (reason: string) (pendingCount: int) (queueDepth: int) (activeDepth: int) (progressYield: bool) (replayComplete: bool) (writeWitness: bool) (terminalAgeMs: int) (ageCapMs: int) (recentProgress: bool) (recentSampledDelta: int64) (recentRootDelta: int64) (recentTerminalDelta: int64) (richTickAgeMs: int) (dynamicRecordKeyBridgeTailLive: bool) =
            let rootDeferredHoleSweepEligibleStatus =
                isRootCompleteStaleRetargetLiveReplayLivelockStatus status
                || status = "semantic_root_complete"
            let liveRootStaleRetarget =
                pendingCount > 0
                && not replayComplete
                && activeDepth = 0
                && queueDepth <= 16
            let noSampledOrRootAuthority =
                recentSampledDelta <= 0L
                && recentRootDelta <= 0L
            let deferredChildReason =
                rootStaleRetargetReasonLooksDeferredChild reason
            let deferredHoleSweepCandidate =
                rootStaleRetargetReasonLooksDeferredHoleSweepCandidate reason
            let terminalOrReplayChurn =
                recentTerminalDelta > 0L
                || progressYield
                || richTickAgeMs >= (min ageCapMs 8000)
            if not rootDeferredHoleSweepEligibleStatus then RootStaleRetargetNotTerminal
            elif reason.Contains("terminal_poison_cascade", StringComparison.Ordinal)
                 && reason.Contains("app_root_base16_root_witness_finalization_self_loop", StringComparison.Ordinal)
                 && liveRootStaleRetarget then
                // ALPHA1293: alpha1292 proved the poison is now correctly detected by the replay
                // driver, but the app-root stale-retarget gate kept treating the resulting
                // terminal/replay churn as live progress.  Once a poisoned child cascade reaches the rank-88 root-stale-retarget
                // self-loop with no active driver,
                // surface the explicit terminal instead of re-opening grace forever.
                RootStaleRetargetPoisonCascadeHandoffReady
            elif deferredHoleSweepCandidate
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority then
                // ALPHA1296: move toward the assessment's phase-2 synchronous sweep direction
                // without fabricating witness completion.  When the app-root stale-retarget seam
                // is parked on deferred-child/type-hole evidence with no active driver, expose a
                // dedicated sweep-required decision.  A later real implementation can attach an
                // owned DeferredTypeVar registry here; this round only names the authority boundary.
                RootStaleRetargetDeferredHoleSweepRequired
            elif deferredChildReason
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority then
                // ALPHA1295: runtime 1294 reached semantic_root_complete with active=0, pending=2,
                // low queue, replay_complete=false, and reason=idle_deferred_child_cell.  That is
                // the same rank-88 root-stale-retarget livelock, but it lacks the poison-cascade
                // substrings alpha1293 required.  Terminal/replay churn cannot keep this deferred
                // child root parked forever; surface the explicit terminal contract fail-closed.
                RootStaleRetargetDeferredChildLivelockHandoffReady
            elif (reason.Contains("app_root_base16_root_witness_finalization_self_loop", StringComparison.Ordinal)
                  || deferredChildReason)
                 && liveRootStaleRetarget
                 && noSampledOrRootAuthority
                 && terminalOrReplayChurn then
                // ALPHA1295: widen the alpha1293 terminal-churn path to include deferred-child
                // root-stale-retarget reasons and rich-busy windows where the terminal delta may
                // not line up on the exact decision tick.
                RootStaleRetargetTerminalChurnHandoffReady
            elif dynamicRecordKeyBridgeTailLive
                 && pendingCount > 0
                 && not replayComplete
                 && not writeWitness
                 && terminalAgeMs < ageCapMs * 2
                 && (queueDepth > 0 || activeDepth > 0 || progressYield || recentProgress) then
                // ALPHA1457: alpha1456 threaded dynamic-record-key bridge evidence into the
                // root-stale retarget call before the function accepted it, causing FS0003.
                // Keep the fix typed: a live dynamic-key bridge tail is its own handoff DU,
                // not another stringly active-replay grace or a positional spare argument.
                RootStaleRetargetDeferDynamicRecordKeyBridgeTail
            elif pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield) then RootStaleRetargetDeferActiveReplay
            elif pendingCount > 0 && replayComplete && writeWitness && terminalAgeMs < ageCapMs && recentProgress then RootStaleRetargetDeferRecentReplayProgress
            else RootStaleRetargetHandoffReady

        // ALPHA1173: 1172 moved the late frontier to a symbolic-if terminal while
        // replay was still pending/runnable.  Keep symbolic-if as a concrete
        // terminal, but gate BigStack handoff through a typed live-replay decision
        // instead of file-specific or status-string special cases.
        type SymbolicIfHandoffDecisionId =
            | SymbolicIfNotTerminal
            | SymbolicIfDeferActiveReplay
            | SymbolicIfDeferRecentReplayProgress
            | SymbolicIfHandoffReady

        let symbolicIfHandoffDecisionText = function
            | SymbolicIfNotTerminal -> "not_terminal"
            | SymbolicIfDeferActiveReplay -> "defer_active_replay"
            | SymbolicIfDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | SymbolicIfHandoffReady -> "handoff_ready"

        let symbolicIfHandoffDecisionFor status pendingCount queueDepth activeDepth progressYield replayComplete terminalAgeMs ageCapMs recentProgress =
            match semanticStatusOfString status with
            | SemanticIfSymbolicConditionBlocked when pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield) -> SymbolicIfDeferActiveReplay
            | SemanticIfSymbolicConditionBlocked when pendingCount > 0 && terminalAgeMs < ageCapMs && recentProgress -> SymbolicIfDeferRecentReplayProgress
            | SemanticIfSymbolicConditionBlocked -> SymbolicIfHandoffReady
            | _ -> SymbolicIfNotTerminal

        // Unknown-return if terminals are concrete diagnostics, but they are not
        // allowed to outrank a still-pending replay driver in the same bounded
        // join window.  This is intentionally structural: status + pending/replay
        // evidence only, no source path or application-specific case.
        type IfUnknownReturnHandoffDecisionId =
            | IfUnknownReturnNotTerminal
            | IfUnknownReturnDeferPendingReplay
            | IfUnknownReturnDeferPhysicalQueueReplay
            | IfUnknownReturnDeferRecentReplayProgress
            | IfUnknownReturnShadowTimeoutPierceRepeatCap
            | IfUnknownReturnShadowTimeoutPierceAbsentSidecar
            | IfUnknownReturnHandoffReady

        let ifUnknownReturnHandoffDecisionText = function
            | IfUnknownReturnNotTerminal -> "not_terminal"
            | IfUnknownReturnDeferPendingReplay -> "defer_pending_replay"
            | IfUnknownReturnDeferPhysicalQueueReplay -> "defer_physical_queue_replay"
            | IfUnknownReturnDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | IfUnknownReturnShadowTimeoutPierceRepeatCap -> "shadow_timeout_pierce_repeat_cap"
            | IfUnknownReturnShadowTimeoutPierceAbsentSidecar -> "shadow_timeout_pierce_absent_sidecar_repeat_cap"
            | IfUnknownReturnHandoffReady -> "handoff_ready"

        let ifUnknownReturnHandoffDecisionFor status pendingCount queueDepth activeDepth progressYield replayComplete terminalAgeMs ageCapMs recentProgress =
            match semanticStatusOfString status with
            | SemanticIfUnknownReturnConditionBlocked when pendingCount > 0 && not replayComplete && terminalAgeMs < ageCapMs -> IfUnknownReturnDeferPendingReplay
            | SemanticIfUnknownReturnConditionBlocked when pendingCount <= 0 && not replayComplete && terminalAgeMs < ageCapMs && (queueDepth >= 16 || activeDepth > 0 || progressYield) -> IfUnknownReturnDeferPhysicalQueueReplay
            | SemanticIfUnknownReturnConditionBlocked when terminalAgeMs >= ageCapMs && pendingCount <= 0 && queueDepth > 0 && activeDepth > 0 && not replayComplete -> IfUnknownReturnShadowTimeoutPierceRepeatCap
            | SemanticIfUnknownReturnConditionBlocked when pendingCount > 0 && terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0 || progressYield || recentProgress) -> IfUnknownReturnDeferRecentReplayProgress
            | SemanticIfUnknownReturnConditionBlocked -> IfUnknownReturnHandoffReady
            | _ -> IfUnknownReturnNotTerminal

        // ALPHA1174: 1173 proved symbolic-if moved on, but the next rank-94
        // op-implementation terminal was still handed to BigStack while pending
        // replay and fresh replay/root/terminal deltas existed. Keep it generic:
        // no .spi path is mentioned; only the semantic status and replay evidence
        // drive the handoff decision.
        type OpImplReplayLivenessId =
            | OpImplReplayNoLive
            | OpImplReplayPendingOnly
            | OpImplReplayQueueLive
            | OpImplReplayActiveDriverLive
            | OpImplReplayProgressYieldLive

        let opImplReplayLivenessText = function
            | OpImplReplayNoLive -> "no_live_replay"
            | OpImplReplayPendingOnly -> "pending_only"
            | OpImplReplayQueueLive -> "queue_live"
            | OpImplReplayActiveDriverLive -> "active_driver_live"
            | OpImplReplayProgressYieldLive -> "progress_yield_live"

        let opImplReplayLivenessFor pendingCount queueDepth activeDepth progressYield =
            if progressYield then OpImplReplayProgressYieldLive
            elif activeDepth > 0 then OpImplReplayActiveDriverLive
            elif queueDepth > 0 then OpImplReplayQueueLive
            elif pendingCount > 0 then OpImplReplayPendingOnly
            else OpImplReplayNoLive

        // ALPHA1430: make the assessment arbitration explicit.  The top-level
        // v1428 mandate says op_impl_required is a hard semantic authoring blocker,
        // even when live replay looks healthy.  Keep the contradictory pending-zero
        // live-tail note visible as policy data instead of letting it silently win.
        type OpImplSemanticTerminalPolicyId =
            | OpImplSemanticNotTerminal
            | OpImplSemanticHardAuthoringBlocker
            | OpImplSemanticSoftReplayDeferrable

        let opImplSemanticTerminalPolicyText = function
            | OpImplSemanticNotTerminal -> "not_terminal"
            | OpImplSemanticHardAuthoringBlocker -> "hard_authoring_blocker"
            | OpImplSemanticSoftReplayDeferrable -> "soft_replay_deferrable"

        let opImplSemanticTerminalPolicyFor status =
            match semanticStatusOfString status with
            | SemanticOpImplRequiredBlocked -> OpImplSemanticHardAuthoringBlocker
            | _ -> OpImplSemanticNotTerminal

        type OpImplProgressDeltaClassId =
            | OpImplDeltaNone
            | OpImplDeltaReplayChatterOnly
            | OpImplDeltaRootOrSampledWork
            | OpImplDeltaTerminalOnly

        let opImplProgressDeltaClassText = function
            | OpImplDeltaNone -> "none"
            | OpImplDeltaReplayChatterOnly -> "replay_chatter_only"
            | OpImplDeltaRootOrSampledWork -> "root_or_sampled_work"
            | OpImplDeltaTerminalOnly -> "terminal_only"

        let opImplProgressDeltaClassFor sampledDelta replayDelta rootDelta terminalDelta =
            if sampledDelta > 0L || rootDelta > 0L then OpImplDeltaRootOrSampledWork
            elif replayDelta > 0L then OpImplDeltaReplayChatterOnly
            elif terminalDelta > 0L then OpImplDeltaTerminalOnly
            else OpImplDeltaNone

        type TerminalDeferralEligibilityId =
            | TerminalDeferralNotEvaluated
            | TerminalDeferralHardSemanticNotDeferrable
            | TerminalDeferralWriterWitnessRequired
            | TerminalDeferralLiveReplayWouldDeferSoftTerminal
            | TerminalDeferralQuietTerminalCanSurface

        let terminalDeferralEligibilityText = function
            | TerminalDeferralNotEvaluated -> "not_evaluated"
            | TerminalDeferralHardSemanticNotDeferrable -> "hard_semantic_terminal_not_deferrable_by_live_replay"
            | TerminalDeferralWriterWitnessRequired -> "writer_witness_required"
            | TerminalDeferralLiveReplayWouldDeferSoftTerminal -> "live_replay_would_defer_soft_terminal"
            | TerminalDeferralQuietTerminalCanSurface -> "quiet_terminal_can_surface"

        let terminalDeferralEligibilityFor semanticPolicy writeWitness queueDepth activeDepth pendingCount replayDelta rootDelta sampledDelta =
            match semanticPolicy with
            | OpImplSemanticHardAuthoringBlocker -> TerminalDeferralHardSemanticNotDeferrable
            | _ when writeWitness -> TerminalDeferralQuietTerminalCanSurface
            | _ when queueDepth > 0 || activeDepth > 0 || pendingCount > 0 || replayDelta > 0L || rootDelta > 0L || sampledDelta > 0L -> TerminalDeferralLiveReplayWouldDeferSoftTerminal
            | _ -> TerminalDeferralWriterWitnessRequired

        type OpImplHandoffDecisionId =
            | OpImplNotTerminal
            | OpImplHandoffHardSemanticMissingImpl
            | OpImplDeferPendingReplay
            | OpImplDeferActiveReplay
            | OpImplDeferPendingActiveReplay
            | OpImplDeferQueuedReplayAlive
            | OpImplDeferPendingZeroLiveReplay
            | OpImplDeferRecentReplayProgress
            | OpImplHandoffReadyPendingZeroYieldThrash
            | OpImplHandoffReadyTerminalFlood
            | OpImplHandoffReady

        let opImplHandoffDecisionText = function
            | OpImplNotTerminal -> "not_terminal"
            | OpImplHandoffHardSemanticMissingImpl -> "hard_semantic_missing_impl_fail_closed"
            | OpImplDeferPendingReplay -> "defer_pending_replay"
            | OpImplDeferActiveReplay -> "defer_active_replay"
            | OpImplDeferPendingActiveReplay -> "defer_pending_active_replay"
            | OpImplDeferQueuedReplayAlive -> "defer_queued_replay_alive"
            | OpImplDeferPendingZeroLiveReplay -> "defer_pending_zero_live_replay"
            | OpImplDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | OpImplHandoffReadyPendingZeroYieldThrash -> "handoff_ready_pending_zero_yield_thrash"
            | OpImplHandoffReadyTerminalFlood -> "handoff_ready_terminal_flood"
            | OpImplHandoffReady -> "handoff_ready"

        let opImplSignatureFromReason (reason: string) =
            let prefix = "term_op_impl_required:"
            let raw = if String.IsNullOrWhiteSpace reason then "" else reason
            let i = raw.IndexOf(prefix, StringComparison.Ordinal)
            if i < 0 then raw
            else
                let tail = raw.Substring(i + prefix.Length)
                let stop = tail.IndexOfAny([|' '; '#'; '|'; '@'|])
                if stop >= 0 then tail.Substring(0, stop) else tail

        let opImplNameFromSignature (signatureText: string) =
            let v = if String.IsNullOrWhiteSpace signatureText then "unknown_op" else signatureText
            let slash = v.IndexOf("/", StringComparison.Ordinal)
            if slash > 0 then v.Substring(0, slash) else v

        let opImplArityFromSignature (signatureText: string) =
            let v = if String.IsNullOrWhiteSpace signatureText then "" else signatureText
            let slash = v.IndexOf("/", StringComparison.Ordinal)
            if slash >= 0 && slash < v.Length - 1 then v.Substring(slash + 1) else "unknown"

        let opImplNodeIdFromKey (key: string) =
            let v = if String.IsNullOrWhiteSpace key then "" else key
            let hash = v.LastIndexOf("#", StringComparison.Ordinal)
            if hash >= 0 && hash < v.Length - 1 then v.Substring(hash + 1) else "unknown"

        let opImplHandoffDecisionFor status pendingCount queueDepth activeDepth progressYield terminalAgeMs ageCapMs recentProgress terminalFloodMature =
            let semanticPolicy = opImplSemanticTerminalPolicyFor status
            match semanticPolicy with
            | OpImplSemanticHardAuthoringBlocker ->
                // ALPHA1430: assessment arbitration is now policy-first, not a raw status string.
                // term_op_impl_required is a hard semantic authoring blocker; live replay proves only scheduler liveness.
                // Do not let replay_repeat_live_tail_guard, pending-zero overrides, or root chatter hide a missing implementation.
                OpImplHandoffHardSemanticMissingImpl
            | OpImplSemanticSoftReplayDeferrable ->
                if pendingCount > 0 && activeDepth > 0 && not (terminalFloodMature) then OpImplDeferPendingActiveReplay
                elif activeDepth > 0 && terminalAgeMs < ageCapMs then OpImplDeferActiveReplay
                elif queueDepth > 0 && terminalAgeMs < ageCapMs then OpImplDeferQueuedReplayAlive
                elif progressYield || recentProgress then OpImplDeferRecentReplayProgress
                else OpImplHandoffReady
            | _ -> OpImplNotTerminal

        // ALPHA1010: keep pushing the live-replay policy boundary toward DUs.
        // Runtime 1009 proved semantic_annot_test_branch_selection_blocked is now
        // the useful rank-87 frontier.  Treat it as a typed surface-now terminal
        // rather than another stringly deferrable status; active replay may still
        // defer soft replay/fingerprint/root terminals, but it cannot hide the
        // concrete branch-selection obligation.
        type LiveReplayTerminalPolicy =
            | DeferTerminalWhileLiveReplay
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy

        // ALPHA1023: alpha1022 proved the app-root/base16 live hardcap can fire
        // after a real root write witness already exists.  Keep that decision as
        // a closed DU so the root-witness path can defer to finalization without
        // weakening the fail-closed terminal used when no witness exists.
        type AppRootBase16LiveReplayHardcapDecision =
            | AppRootWitnessCanFinalize
            | AppRootWitnessFinalizeSelfLoopTerminal
            | AppRootLiveReplayLivelockTerminal
            | AppRootLiveReplayDemote
            | AppRootQuiescedHardcapTerminal
            | AppRootPreserveRootEvidence

        let private appRootBase16LiveReplayHardcapDecisionToString decision =
            match decision with
            | AppRootWitnessCanFinalize -> "root_witness_can_finalize"
            | AppRootWitnessFinalizeSelfLoopTerminal -> "root_witness_finalize_self_loop_terminal"
            | AppRootLiveReplayLivelockTerminal -> "live_replay_livelock_terminal"
            | AppRootLiveReplayDemote -> "live_replay_demote"
            | AppRootQuiescedHardcapTerminal -> "quiesced_hardcap_terminal"
            | AppRootPreserveRootEvidence -> "preserve_root_evidence"

        // ALPHA1024: keep cross-kind payload attachment as a closed decision.
        // Runtime 1023 showed term cells arriving while the canonical frame was ty;
        // dropping them as kind_mismatch_frame_ty_cell_term loses runnable replay work.
        // The safe path stores the cell as a deferred replay obligation whenever
        // there is pending/queued/active replay evidence, while preserving the old
        // fail-closed rejection when the mismatch is quiescent.
        type CrossKindPayloadAttachDecision =
            | CrossKindSwitchToFreshFrontier
            | CrossKindDeferAsReplayObligation
            | CrossKindRejectUnsafeMismatch

        let private crossKindPayloadAttachDecisionToString decision =
            match decision with
            | CrossKindSwitchToFreshFrontier -> "switch_to_fresh_frontier"
            | CrossKindDeferAsReplayObligation -> "defer_as_replay_obligation"
            | CrossKindRejectUnsafeMismatch -> "reject_unsafe_mismatch"

        // ALPHA1026: a repeated NullReferenceException after a root-complete
        // write witness is not the same thing as an uncovered semantic terminal.
        // Runtime 1025 showed Hopac replay reaching semantic_root_complete, then
        // rebuilding a let-success/apply continuation until the old null-repeat
        // cap pinned let_success_apply_continuation_null_repeat_terminal. Keep
        // the decision closed: terminal only when there is no root witness/live
        // replay evidence; otherwise preserve the witness or defer the still-live
        // replay tick without pretending BuildOk locally.
        type RootWitnessNullReplayDecision =
            | RootWitnessNullDeferLiveReplay
            | RootWitnessNullPreserveComplete
            | RootWitnessNullSurfaceTerminal

        let private rootWitnessNullReplayDecisionToString decision =
            match decision with
            | RootWitnessNullDeferLiveReplay -> "root_witness_null_defer_live_replay"
            | RootWitnessNullPreserveComplete -> "root_witness_null_preserve_complete"
            | RootWitnessNullSurfaceTerminal -> "root_witness_null_surface_terminal"

        // ALPHA1028: EUnbox replay can surface a real BigStack wait timeout through
        // the child detail. Do not schedule that child again as semantic_step_partial,
        // or the replay loop masks the true blocker until a manual interrupt.
        type UnboxChildReplayDecision =
            | UnboxChildScheduleReplay
            | UnboxChildBoundJoinStall
            | UnboxChildSurfaceBlocked

        let private unboxChildReplayDecisionToString decision =
            match decision with
            | UnboxChildScheduleReplay -> "schedule_replay"
            | UnboxChildBoundJoinStall -> "bound_bigstack_join_stall"
            | UnboxChildSurfaceBlocked -> "surface_blocked"

        let private liveReplayTerminalPolicyOfSemanticStatusId = function
            | SemanticParentContinuationCycleBlocked
            | SemanticRootCompletePendingJobsBlocked
            | SemanticAppRootBase16StaleRetargetHardcapBlocked
            | SemanticReplayChildScheduleRepeatBlocked
            | SemanticRecordWithValueBlocked
            | SemanticReplayFingerprintRepeatBlocked
            | SemanticRootCompleteStaleRetargetPendingNoQueueBlocked -> DeferTerminalWhileLiveReplay
            // ALPHA1010: these are concrete obligations, not soft replay churn.
            // Let BigStack fail closed on the precise missing implementation/branch
            // selector instead of demoting them into a lower-rank global-fuse loop.
            | SemanticOpImplRequiredBlocked
            | SemanticAnnotTestBranchSelectionBlocked
            | SemanticUnboxReplayBlocked
            | SemanticApplySpineMissingDirectValueBlocked
            // ALPHA1334: dynamic-join terminal evidence is durable, but live
            // q/a/p replay is still a carrier/drain obligation, not a terminal
            // surface. Keep stale-retarget livelock aggressive; defer dynamic join.
            | SemanticRootCompleteStaleRetargetLiveReplayLivelockBlocked -> SurfaceTerminalDuringLiveReplay
            | SemanticDynamicJoinApplyBlocked -> DeferTerminalWhileLiveReplay
            // ALPHA1230: missing-after-prefetch is only terminal authority after
            // the explicit replay lane is quiet; while pending/queued/active replay
            // exists it is a drain obligation.
            | SemanticMissingAfterPrefetchBlocked -> DeferTerminalWhileLiveReplay
            // ALPHA998: semantic_global_fuse_parent_continuation_cycle_blocked
            // is emitted only after the bounded global-fuse repeat cap is
            // exhausted. Runtime 997 showed that treating it as deferrable lets
            // active/queued replay suppress the terminal forever, producing a
            // manual interrupt instead of the intended fail-closed BuildError.
            | SemanticGlobalFuseParentContinuationCycleBlocked -> TerminalNotLiveReplayPolicy
            | _ -> TerminalNotLiveReplayPolicy

        let private isLiveReplayDeferrableSemanticStatusId statusId =
            match liveReplayTerminalPolicyOfSemanticStatusId statusId with
            | DeferTerminalWhileLiveReplay -> true
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy -> false

        let private isLiveReplayDeferrableTerminalStatus status =
            status |> semanticStatusOfString |> isLiveReplayDeferrableSemanticStatusId

        // ALPHA1454: dynamic-record-key placeholder handling is a typed three-way
        // decision.  DV returned by the explicit dynamic-join runner is the existing
        // symbolic runtime carrier; DB is still not a fabricated key, but it may get
        // one bounded bridge-tail drain window when the run has just observed dynamic
        // key bridge activity and there is no writer witness.
        type DynamicRecordKeyPlaceholderDecisionId =
            | DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue
            | DynamicRecordKeyPlaceholderDeferObservedBridgeTail
            | DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail
            | DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted
            | DynamicRecordKeyPlaceholderPinTerminal

        let dynamicRecordKeyPlaceholderDecisionText = function
            | DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue -> "accept_symbolic_runtime_value"
            | DynamicRecordKeyPlaceholderDeferObservedBridgeTail -> "defer_observed_bridge_tail"
            | DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail -> "defer_dv_symbolic_live_bridge_tail"
            | DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted -> "pin_no_bridge_evidence_or_cap_exhausted"
            | DynamicRecordKeyPlaceholderPinTerminal -> "pin_terminal"

        type DynamicRecordKeyBridgeTailEvidenceId =
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue
            | DynamicRecordKeyBridgeTailCapExhausted

        type DynamicRecordKeyBridgeTailStrengthId =
            | DynamicRecordKeyBridgeTailStrengthNone
            | DynamicRecordKeyBridgeTailStrengthStrongObservedBridge
            | DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier
            | DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot
            | DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue
            | DynamicRecordKeyBridgeTailStrengthCapExhausted

        let dynamicRecordKeyBridgeTailStrengthText = function
            | DynamicRecordKeyBridgeTailStrengthNone -> "none"
            | DynamicRecordKeyBridgeTailStrengthStrongObservedBridge -> "strong_observed_bridge"
            | DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier -> "strong_dv_symbolic_carrier"
            | DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot -> "weak_pending_active_root"
            | DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue -> "weak_physical_queue"
            | DynamicRecordKeyBridgeTailStrengthCapExhausted -> "cap_exhausted"

        let dynamicRecordKeyBridgeTailStrengthForEvidence = function
            | DynamicRecordKeyBridgeTailObservedBridge -> DynamicRecordKeyBridgeTailStrengthStrongObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier -> DynamicRecordKeyBridgeTailStrengthStrongSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot -> DynamicRecordKeyBridgeTailStrengthWeakPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> DynamicRecordKeyBridgeTailStrengthWeakPhysicalQueue
            | DynamicRecordKeyBridgeTailCapExhausted -> DynamicRecordKeyBridgeTailStrengthCapExhausted
            | DynamicRecordKeyBridgeTailNone -> DynamicRecordKeyBridgeTailStrengthNone

        type DynamicRecordKeyPlaceholderRepeatCapOutcomeId =
            | DynamicRecordKeyRepeatCapSuppressedByLiveBridgeTail
            | DynamicRecordKeyRepeatCapPendingRootOnlyFallsThrough
            | DynamicRecordKeyRepeatCapPhysicalQueueOnlyFallsThrough
            | DynamicRecordKeyRepeatCapPinNoLiveBridgeTailOrCapExhausted

        let dynamicRecordKeyPlaceholderRepeatCapOutcomeText = function
            | DynamicRecordKeyRepeatCapSuppressedByLiveBridgeTail -> "bridge_tail_live_suppresses_repeat_cap_pin"
            | DynamicRecordKeyRepeatCapPendingRootOnlyFallsThrough -> "pending_root_only_falls_through_to_structural_churn"
            | DynamicRecordKeyRepeatCapPhysicalQueueOnlyFallsThrough -> "physical_queue_only_falls_through_to_structural_churn"
            | DynamicRecordKeyRepeatCapPinNoLiveBridgeTailOrCapExhausted -> "pin_no_live_bridge_tail_or_cap_exhausted"

        let dynamicRecordKeyBridgeTailEvidenceText = function
            | DynamicRecordKeyBridgeTailNone -> "none"
            | DynamicRecordKeyBridgeTailObservedBridge -> "observed_bridge"
            | DynamicRecordKeyBridgeTailSymbolicCarrier -> "dv_symbolic_carrier"
            | DynamicRecordKeyBridgeTailPendingActiveRoot -> "pending_active_root"
            | DynamicRecordKeyBridgeTailPhysicalQueue -> "physical_queue_or_active"
            | DynamicRecordKeyBridgeTailCapExhausted -> "cap_exhausted"

        let dynamicRecordKeyBridgeTailEvidenceFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (rootWitnessActivity: int)
            (bridgeCount: int)
            (symbolicAcceptedCount: int)
            (bridgeTailDeferCount: int)
            =
            if bridgeTailDeferCount >= 32 then DynamicRecordKeyBridgeTailCapExhausted
            elif pending <= 0 && queueDepth <= 0 && rootWitnessActivity <= 0 then
                // ALPHA1505: q=0/p=0 means there is no physical producer left that
                // can satisfy a dynamic-record-key bridge lease.  Active workers alone
                // are waiters, not evidence of future work; do not let them hold a
                // ghost bridge tail alive through graceful shutdown.
                DynamicRecordKeyBridgeTailNone
            elif bridgeCount > 0 then DynamicRecordKeyBridgeTailObservedBridge
            elif symbolicAcceptedCount > 0 then DynamicRecordKeyBridgeTailSymbolicCarrier
            elif pending > 0 && (activeDepth > 0 || rootWitnessActivity > 0) then DynamicRecordKeyBridgeTailPendingActiveRoot
            elif pending > 0 || queueDepth > 0 || activeDepth > 0 then DynamicRecordKeyBridgeTailPhysicalQueue
            else DynamicRecordKeyBridgeTailNone

        let dynamicRecordKeyBridgeTailEvidenceIsLive = function
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> true
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailCapExhausted -> false

        let dynamicRecordKeyBridgeTailEvidenceIsStrongRepeatCapLive = function
            | DynamicRecordKeyBridgeTailObservedBridge
            | DynamicRecordKeyBridgeTailSymbolicCarrier
            | DynamicRecordKeyBridgeTailPendingActiveRoot
            | DynamicRecordKeyBridgeTailPhysicalQueue -> true
            | DynamicRecordKeyBridgeTailNone
            | DynamicRecordKeyBridgeTailCapExhausted -> false

        let dynamicRecordKeyPlaceholderDecisionFor
            (why: string)
            (valueCase: string)
            (queueDepth: int)
            (activeDepth: int)
            (pending: int)
            (writeWitness: bool)
            (bridgeCount: int)
            (symbolicAcceptedCount: int)
            (bridgeTailDeferCount: int)
            (rootWitnessActivity: int)
            =
            let whyText = if isNull why then "" else why
            let valueCaseText = if isNull valueCase then "" else valueCase
            let isDynamicRecordKey = whyText.StartsWith("runtime_record_dynamic_key_required", StringComparison.Ordinal)
            let isDvCarrier = valueCaseText.IndexOf("DV", StringComparison.Ordinal) >= 0
            let isDbPlaceholder = valueCaseText = "DB"
            let bridgeTailEvidence =
                dynamicRecordKeyBridgeTailEvidenceFor pending queueDepth activeDepth rootWitnessActivity bridgeCount symbolicAcceptedCount bridgeTailDeferCount
            let bridgeTailLive = dynamicRecordKeyBridgeTailEvidenceIsLive bridgeTailEvidence
            let bridgeTailWindowOpen = bridgeTailDeferCount < 32
            if isDynamicRecordKey && isDvCarrier && not writeWitness then
                DynamicRecordKeyPlaceholderAcceptSymbolicRuntimeValue
            elif isDynamicRecordKey
                 && isDbPlaceholder
                 && not writeWitness
                 && bridgeTailWindowOpen
                 && bridgeTailLive then
                match bridgeTailEvidence with
                | DynamicRecordKeyBridgeTailSymbolicCarrier
                | DynamicRecordKeyBridgeTailPendingActiveRoot -> DynamicRecordKeyPlaceholderDeferDvSymbolicLiveTail
                | _ -> DynamicRecordKeyPlaceholderDeferObservedBridgeTail
            elif isDynamicRecordKey && isDbPlaceholder && not writeWitness then
                DynamicRecordKeyPlaceholderPinNoBridgeEvidenceOrCapExhausted
            else
                DynamicRecordKeyPlaceholderPinTerminal

        // ALPHA1181: dynamic-join surfacing is now a first-class decision, not a
        // stringly side-effect of liveReplayTerminalSuppressed.  This preserves the
        // aggressive alpha1180 behavior while making future tweaks exhaustive.
        type DynamicJoinTerminalDecisionId =
            | DynamicJoinTerminalSurface
            | DynamicJoinTerminalDeferLiveReplay

        let private dynamicJoinTerminalDecisionText = function
            | DynamicJoinTerminalSurface -> "surface_terminal"
            | DynamicJoinTerminalDeferLiveReplay -> "defer_live_replay"

        let private dynamicJoinTerminalDecisionForStatusId statusId =
            match statusId with
            | SemanticDynamicJoinApplyBlocked ->
                match liveReplayTerminalPolicyOfSemanticStatusId statusId with
                | DeferTerminalWhileLiveReplay -> DynamicJoinTerminalDeferLiveReplay
                | SurfaceTerminalDuringLiveReplay
                | TerminalNotLiveReplayPolicy -> DynamicJoinTerminalSurface
            | _ -> DynamicJoinTerminalSurface

        let private dynamicJoinTerminalDecisionForStatusText status =
            status |> semanticStatusOfString |> dynamicJoinTerminalDecisionForStatusId

        // ALPHA1186/1187: BigStack handoff for dynamic-join terminals is now a
        // typed decision.  Alpha1185 proved the dynamic-join frontier is real;
        // Alpha1186 proved the first age window was too short because BigStack still
        // accepted the same rank-92 terminal with pending/queued/active replay.  Keep
        // the terminal durable, but runnable replay now defers by DU until it actually
        // drains; only stalled replay without a runnable queue may surface as aged.
        type DynamicJoinReplayLivenessId =
            | DynamicJoinReplayNoLive
            | DynamicJoinReplayPendingOnly
            | DynamicJoinReplayQueueLive
            | DynamicJoinReplayActiveDriverLive
            | DynamicJoinReplayProgressYieldLive

        let dynamicJoinReplayLivenessText = function
            | DynamicJoinReplayNoLive -> "no_live_replay"
            | DynamicJoinReplayPendingOnly -> "pending_only"
            | DynamicJoinReplayQueueLive -> "queue_live"
            | DynamicJoinReplayActiveDriverLive -> "active_driver_live"
            | DynamicJoinReplayProgressYieldLive -> "progress_yield_live"

        let dynamicJoinReplayLivenessFor pending queueDepth activeDepth progressYield =
            if progressYield then DynamicJoinReplayProgressYieldLive
            elif activeDepth > 0 then DynamicJoinReplayActiveDriverLive
            elif queueDepth > 0 then DynamicJoinReplayQueueLive
            elif pending > 0 then DynamicJoinReplayPendingOnly
            else DynamicJoinReplayNoLive

        type DynamicJoinProgressEvidenceId =
            | DynamicJoinNoFreshProgress
            | DynamicJoinReplayTrickleOnly
            | DynamicJoinSampledOrReplayBurst
            | DynamicJoinRootOrTerminalDelta

        let dynamicJoinProgressEvidenceText = function
            | DynamicJoinNoFreshProgress -> "no_fresh_progress"
            | DynamicJoinReplayTrickleOnly -> "replay_trickle_only"
            | DynamicJoinSampledOrReplayBurst -> "sampled_or_replay_burst"
            | DynamicJoinRootOrTerminalDelta -> "root_or_terminal_delta"

        let dynamicJoinProgressEvidenceIsMeaningful = function
            | DynamicJoinRootOrTerminalDelta
            | DynamicJoinSampledOrReplayBurst -> true
            | DynamicJoinReplayTrickleOnly
            | DynamicJoinNoFreshProgress -> false

        type DynamicJoinProgressFreshnessId =
            | DynamicJoinProgressFresh
            | DynamicJoinProgressStale

        let dynamicJoinProgressFreshnessText = function
            | DynamicJoinProgressFresh -> "fresh"
            | DynamicJoinProgressStale -> "stale"

        let dynamicJoinProgressFreshnessFor richTickAgeMs ageCap =
            if richTickAgeMs < ageCap * 2 then DynamicJoinProgressFresh
            else DynamicJoinProgressStale

        let dynamicJoinProgressFreshnessIsFresh = function
            | DynamicJoinProgressFresh -> true
            | DynamicJoinProgressStale -> false

        let dynamicJoinProgressEvidenceFor (sampledDelta:int64) (replayDelta:int64) (rootDelta:int64) (terminalDelta:int64) =
            if rootDelta > 0L || terminalDelta > 0L then DynamicJoinRootOrTerminalDelta
            elif sampledDelta > 0L || replayDelta >= 32L then DynamicJoinSampledOrReplayBurst
            elif replayDelta > 0L then DynamicJoinReplayTrickleOnly
            else DynamicJoinNoFreshProgress

        type DynamicJoinHandoffDecisionId =
            | DynamicJoinHandoffNotDynamic
            | DynamicJoinHandoffDeferPendingReplay
            | DynamicJoinHandoffDeferActiveReplay
            | DynamicJoinHandoffDeferRunnableReplay
            | DynamicJoinHandoffDeferRecentReplayProgress
            | DynamicJoinHandoffDeferRuntimeUnionCarrier
            | DynamicJoinHandoffDeferRecordKeyBridgeTail
            | DynamicJoinHandoffDeferPendingStackFenceBridge
            | DynamicJoinHandoffDeferCooperativeYieldShadowBridge
            | DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout
            | DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout
            | DynamicJoinHandoffSurfaceWaitedStaleTail
            | DynamicJoinHandoffSurfaceQuiet
            | DynamicJoinHandoffSurfaceAgedStalledReplay

        let dynamicJoinHandoffDecisionText = function
            | DynamicJoinHandoffNotDynamic -> "not_dynamic_join"
            | DynamicJoinHandoffDeferPendingReplay -> "defer_pending_replay"
            | DynamicJoinHandoffDeferActiveReplay -> "defer_active_replay"
            | DynamicJoinHandoffDeferRunnableReplay -> "defer_runnable_replay"
            | DynamicJoinHandoffDeferRecentReplayProgress -> "defer_recent_replay_progress"
            | DynamicJoinHandoffDeferRuntimeUnionCarrier -> "defer_runtime_union_carrier"
            | DynamicJoinHandoffDeferRecordKeyBridgeTail -> "defer_record_key_bridge_tail"
            | DynamicJoinHandoffDeferPendingStackFenceBridge -> "defer_pending_stack_fence_bridge"
            | DynamicJoinHandoffDeferCooperativeYieldShadowBridge -> "defer_cooperative_yield_shadow_bridge"
            | DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout -> "native_inline_pending_stack_fence_bridge_alt_timeout"
            | DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout -> "native_inline_cooperative_yield_shadow_alt_timeout"
            | DynamicJoinHandoffSurfaceWaitedStaleTail -> "surface_waited_stale_tail"
            | DynamicJoinHandoffSurfaceQuiet -> "surface_quiet"
            | DynamicJoinHandoffSurfaceAgedStalledReplay -> "surface_aged_stalled_replay"

        type DynamicJoinPendingZeroNoWriterDecisionId =
            | DynamicJoinPendingZeroNoWriterNotDynamic
            | DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay
            | DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge
            | DynamicJoinPendingZeroNoWriterDeferRecentAuthority
            | DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue
            | DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle
            | DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver
            | DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver
            | DynamicJoinPendingZeroNoWriterHardPin

        let dynamicJoinPendingZeroNoWriterDecisionText = function
            | DynamicJoinPendingZeroNoWriterNotDynamic -> "not_dynamic_join"
            | DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay -> "defer_fresh_live_replay"
            | DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge -> "defer_live_queue_surge"
            | DynamicJoinPendingZeroNoWriterDeferRecentAuthority -> "defer_recent_authority"
            | DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue -> "defer_replay_burst_active_queue"
            | DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle -> "defer_active_replay_trickle"
            | DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver -> "defer_queued_replay_no_active_driver"
            | DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver -> "surface_queued_replay_starved_no_active_driver"
            | DynamicJoinPendingZeroNoWriterHardPin -> "hard_pin_no_writer"

        let dynamicJoinPendingZeroNoWriterDecisionFor
            (status: string)
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (terminalAge: int)
            (ageCap: int)
            (replayDelta: int64)
            (rootDelta: int64)
            (terminalDelta: int64)
            =
            match semanticStatusOfString status with
            | SemanticDynamicJoinApplyBlocked ->
                let liveTail = pending > 0 || queueDepth > 0 || activeDepth > 0
                // ALPHA1375: replay-only movement around a durable dynamic-join
                // blocker is scheduler churn, not semantic authority.  Alpha1374
                // still let replayDelta hundreds-wide extend the no-writer window
                // until jp_wait wrapped the real rank-92 terminal as generic EJP0011.
                let recentAuthority = rootDelta > 0L || terminalDelta > 0L
                if writeWitness || pending > 0 then DynamicJoinPendingZeroNoWriterNotDynamic
                elif liveTail && terminalAge < max ageCap 1 then DynamicJoinPendingZeroNoWriterDeferFreshLiveReplay
                elif pending = 0 && queueDepth >= 16 && activeDepth > 0 && replayDelta >= 32L && terminalAge < max (ageCap * 4) 60000 then DynamicJoinPendingZeroNoWriterDeferReplayBurstActiveQueue
                elif pending = 0 && queueDepth > 0 && activeDepth > 0 && replayDelta > 0L && terminalAge < max (ageCap * 8) 90000 then DynamicJoinPendingZeroNoWriterDeferActiveReplayTrickle
                elif pending = 0 && queueDepth >= 64 && activeDepth <= 0 && (replayDelta <= 0L || terminalAge >= max (ageCap * 12) 120000) then DynamicJoinPendingZeroNoWriterSurfaceQueuedReplayStarvedNoActiveDriver
                elif pending = 0 && queueDepth >= 64 && activeDepth <= 0 && replayDelta > 0L && terminalAge < max (ageCap * 12) 120000 then DynamicJoinPendingZeroNoWriterDeferQueuedReplayNoActiveDriver
                elif pending = 0 && queueDepth >= 16 && activeDepth > 0 then DynamicJoinPendingZeroNoWriterDeferLiveQueueSurge
                elif liveTail && recentAuthority && terminalAge < max (ageCap * 2) (ageCap + 1) then DynamicJoinPendingZeroNoWriterDeferRecentAuthority
                else DynamicJoinPendingZeroNoWriterHardPin
            | _ -> DynamicJoinPendingZeroNoWriterNotDynamic

        type DynamicJoinLateTailDecisionId =
            | DynamicJoinLateTailNotDynamic
            | DynamicJoinLateTailDeferLiveTail
            | DynamicJoinLateTailSurfaceQuietTail

        let dynamicJoinLateTailDecisionText = function
            | DynamicJoinLateTailNotDynamic -> "not_dynamic_join"
            | DynamicJoinLateTailDeferLiveTail -> "defer_live_tail"
            | DynamicJoinLateTailSurfaceQuietTail -> "surface_quiet_tail"

        type DynamicJoinSymbolicTailKindId =
            | DynamicJoinSymbolicTailNone
            | DynamicJoinSymbolicTailDSymbolPair
            | DynamicJoinSymbolicTailRuntimeDynTypecheck
            | DynamicJoinSymbolicTailArg2Pair

        let dynamicJoinSymbolicTailKindText = function
            | DynamicJoinSymbolicTailNone -> "none"
            | DynamicJoinSymbolicTailDSymbolPair -> "dsymbol_pair"
            | DynamicJoinSymbolicTailRuntimeDynTypecheck -> "runtime_dyn_typecheck"
            | DynamicJoinSymbolicTailArg2Pair -> "arg2_pair"

        let dynamicJoinSymbolicTailKindFor (reason: string) =
            let reasonText = if isNull reason then "" else reason
            if reasonText.Contains("DSymbol@arg0/DSymbol", StringComparison.Ordinal) then
                DynamicJoinSymbolicTailDSymbolPair
            elif reasonText.Contains("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) then
                DynamicJoinSymbolicTailRuntimeDynTypecheck
            elif reasonText.Contains("@arg2/DPair", StringComparison.Ordinal) then
                DynamicJoinSymbolicTailArg2Pair
            else
                DynamicJoinSymbolicTailNone

        let dynamicJoinSymbolicTailKindIsTail = function
            | DynamicJoinSymbolicTailNone -> false
            | DynamicJoinSymbolicTailDSymbolPair
            | DynamicJoinSymbolicTailRuntimeDynTypecheck
            | DynamicJoinSymbolicTailArg2Pair -> true

        let dynamicJoinLateTailDecisionFor
            (status: string)
            (reason: string)
            (waited: int)
            (ageCap: int)
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (_rootDelta: int64)
            (_terminalDelta: int64)
            =
            match semanticStatusOfString status with
            | SemanticDynamicJoinApplyBlocked ->
                let staleWindow = waited >= max (ageCap * 8) 12000
                let symbolicTailKind = dynamicJoinSymbolicTailKindFor reason
                if not staleWindow then DynamicJoinLateTailNotDynamic
                elif pending > 0 || queueDepth > 0 || activeDepth > 0 then DynamicJoinLateTailDeferLiveTail
                elif dynamicJoinSymbolicTailKindIsTail symbolicTailKind then DynamicJoinLateTailSurfaceQuietTail
                else DynamicJoinLateTailSurfaceQuietTail
            | _ -> DynamicJoinLateTailNotDynamic

        let dynamicJoinHandoffDecisionFor status pending queueDepth activeDepth progressYield terminalAge ageCap recentProgress sampledDelta replayDelta rootDelta terminalDelta richTickAgeMs recordKeyBridgeTailStrongLive =
            match semanticStatusOfString status with
            | SemanticDynamicJoinApplyBlocked ->
                let replayLiveness =
                    dynamicJoinReplayLivenessFor pending queueDepth activeDepth progressYield
                let progressEvidence =
                    dynamicJoinProgressEvidenceFor sampledDelta replayDelta rootDelta terminalDelta
                let progressFreshness =
                    dynamicJoinProgressFreshnessFor richTickAgeMs ageCap
                let meaningfulProgress =
                    // ALPHA1282: root/replay churn is useful before the terminal matures,
                    // but after one bounded dynamic-join window it is evidence for fail-closed
                    // handoff, not a license to keep replaying around a rank-92 blocker.
                    terminalAge < ageCap
                    && dynamicJoinProgressEvidenceIsMeaningful progressEvidence
                    && dynamicJoinProgressFreshnessIsFresh progressFreshness
                let freshAuthorityProgress =
                    // ALPHA1318: alpha1317 surfaced EJP0021 at terminal_age=6000ms while
                    // replay/root/terminal deltas were still arriving and the blocker was an
                    // explicit dynamic-record-key DV carrier.  ALPHA1375 narrows that grace:
                    // replay-only churn around semantic_dynamic_join_apply_blocked may not
                    // keep deferring the terminal after the first bounded window; root or
                    // terminal authority is required to buy extra time.
                    terminalAge < ageCap * 2
                    && dynamicJoinProgressFreshnessIsFresh progressFreshness
                    && (rootDelta > 0L || terminalDelta > 0L)
                let hardStale =
                    terminalAge >= ageCap * 16
                    && pending = 0
                    && queueDepth = 0
                    && activeDepth = 0
                    && not meaningfulProgress
                    && not freshAuthorityProgress
                let recordKeyBridgeTailGrace =
                    // ALPHA1465: generic queue/active evidence is not record-key bridge authority.
                    // Only observed bridge/DV-carrier evidence gets the dynamic-record-key grace;
                    // weak pending/root/physical tails fall through to active-structural-churn or terminal arbitration.
                    recordKeyBridgeTailStrongLive
                    && not hardStale
                    && (pending > 0 || queueDepth > 0 || activeDepth > 0 || freshAuthorityProgress || meaningfulProgress)
                let pendingStackFenceBridgeEvidence =
                    // ALPHA1497: 1496.jsonl proved the bridge can be live yet spin for minutes because late-tail arbitration
                    // rewrites it to runtime-union carrier and the HUD keeps saying weak fallthrough.  Split evidence from lease.
                    recordKeyBridgeTailStrongLive
                    && pending > 0
                    && activeDepth > 0
                    && replayDelta > 0L
                    && not hardStale
                let pendingStackFenceBridgeAltTimeout =
                    pendingStackFenceBridgeEvidence
                    && terminalAge >= max (ageCap * 16) 120000
                let pendingStackFenceBridgeAuthority =
                    pendingStackFenceBridgeEvidence
                    && not pendingStackFenceBridgeAltTimeout
                let cooperativeYieldShadowBridgeEvidence =
                    // ALPHA1499: v1498 showed p=0/q=39/a=4 term_to_ty cooperative-yield thrash while Hopac shadow parity
                    // already advertised alt=timeout_1500ms.  A cooperative yield is useful for fairness, not an infinite
                    // repeat-cap pardon once the shadow Alt timeout would have snapped the branch.
                    progressYield
                    && pending = 0
                    && queueDepth > 0
                    && activeDepth > 0
                    && replayDelta > 0L
                    && not hardStale
                let cooperativeYieldShadowAltTimeout =
                    cooperativeYieldShadowBridgeEvidence
                    && terminalAge >= 1500
                if cooperativeYieldShadowAltTimeout then
                    DynamicJoinHandoffSurfaceCooperativeYieldShadowAltTimeout
                elif pendingStackFenceBridgeAltTimeout then
                    DynamicJoinHandoffSurfacePendingStackFenceBridgeAltTimeout
                elif pendingStackFenceBridgeAuthority then
                    DynamicJoinHandoffDeferPendingStackFenceBridge
                elif cooperativeYieldShadowBridgeEvidence then
                    DynamicJoinHandoffDeferCooperativeYieldShadowBridge
                elif recordKeyBridgeTailGrace then
                    DynamicJoinHandoffDeferRecordKeyBridgeTail
                else
                    match replayLiveness with
                    | DynamicJoinReplayProgressYieldLive
                    | DynamicJoinReplayActiveDriverLive
                    | DynamicJoinReplayQueueLive ->
                        if terminalAge < ageCap then
                            DynamicJoinHandoffDeferActiveReplay
                        elif hardStale then
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                        elif freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress || (recentProgress && terminalAge < ageCap * 2) then
                            DynamicJoinHandoffDeferRunnableReplay
                        else
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                    | DynamicJoinReplayPendingOnly ->
                        if terminalAge < ageCap then
                            DynamicJoinHandoffDeferPendingReplay
                        elif freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress && terminalAge < ageCap * 2 then
                            DynamicJoinHandoffDeferRecentReplayProgress
                        else
                            DynamicJoinHandoffSurfaceAgedStalledReplay
                    | DynamicJoinReplayNoLive ->
                        if freshAuthorityProgress then
                            DynamicJoinHandoffDeferRuntimeUnionCarrier
                        elif meaningfulProgress && terminalAge < ageCap * 2 then
                            DynamicJoinHandoffDeferRecentReplayProgress
                        else
                            DynamicJoinHandoffSurfaceQuiet
            | _ -> DynamicJoinHandoffNotDynamic

        // ALPHA342: single-flight continuation frontier.
        //
        // Alpha340 proved the bounded trampoline could advance the captured trace, but the log showed
        // several Hopac/JP waiters promoting and running the same cycle concurrently. A ConcurrentQueue
        // made that look like useful parallelism while actually duplicating the same frame and racing the
        // cursor. Keep one canonical frontier per evaluator cycle until typed replay can consume the continuation envelope.
        let private gate = obj()
        let mutable private frontier : Frame option = None
        let mutable private frontierTerm : Frame option = None
        let mutable private frontierTy : Frame option = None
        let mutable private activeRun = false
        let mutable private captureSeq = 0L
        let mutable private replaySeq = 0L
        let mutable private replayScheduledKey : string option = None
        let mutable private replayQueue : ReplayTask list = []
        // ALPHA649: same-run semantic-payload backfill cache.
        // Alpha648 reached semantic_replay_payload_missing_blocked even though
        // semantic cells for the same kind/site were observed earlier in the run.
        // Store only observed ReplayCell metadata; this never fabricates values.
        let private semanticCellsByKindSite = System.Collections.Concurrent.ConcurrentDictionary<string, ReplayCell>()
        // ALPHA535: remember the first missing-payload replay terminal so later
        // downstream terminals cannot shadow the root replay-payload contract.
        let mutable private pinnedReplayPayloadMissing : Frame option = None
        // ALPHA536: remember the strongest explicit terminal contract observed so a
        // downstream let-success/apply/deferred blocker cannot shadow the real upstream
        // missing stepper contract in retry_stop.
        let mutable private pinnedTerminalContract : Frame option = None
        // ALPHA594: durable per-BuildFile terminal ledger.  Alpha593 showed
        // the live pin can be cleared by root-complete shielding before the final
        // replay-root handoff branch asks for it; keep the strongest terminal
        // observed in this transaction without making it a semantic success.
        let mutable private durableTerminalContract : Frame option = None
        // ALPHA453: compact anti-repeat ledger for continuation replays that make no semantic progress.
        let private replayFingerprintRepeats = System.Collections.Generic.Dictionary<string,int>()
        // ALPHA546: compact ledger for child replay scheduling that repeats the same semantic child.
        // Alpha545 proved the final macro terminal is correct, but a 245s gap before retry_stop
        // was spent re-scheduling the same seq/apply/deferred children around parsing.spi:257.
        // Cap that repeat as a terminal contract so retry_stop can fail closed before JP watchdog.
        let private replayChildScheduleRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private replay_child_schedule_repeat_cap = 8
        // ALPHA1012: annot-test ArgumentNullException(key) is a replay obligation
        // while at least one branch has just been scheduled.  Runtime 1011 showed
        // the true ELet branch was scheduled and BigStack immediately consumed the
        // rank-87 terminal before that short replay window could close.  Track the
        // exact annot-test branch key and pin only after a bounded repeat window.
        let private annotTestBranchSelectionGuardRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private annot_test_branch_selection_guard_cap = 2
        let private noteAnnotTestBranchSelectionGuard (key: string) =
            lock gate (fun () ->
                let mutable prior = 0
                let nextCount = if annotTestBranchSelectionGuardRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                annotTestBranchSelectionGuardRepeats.[key] <- nextCount
                nextCount)
        // ALPHA563: reentrant semantic-cell attachments can starve the replay loop without ever
        // reaching the child schedule repeat guard.  Runtime 562 emitted only reentrant-poke
        // suppressions for the same EOp/EV cells while an active driver stayed alive.  Count
        // those suppressions by semantic cell and promote the exact cell to a terminal contract.
        let private reentrantReplayPokeRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private reentrant_replay_poke_repeat_cap = 64
        let private replayReentrantPokeKey (cell: ReplayCell) =
            sprintf "%s|%s|%d|%s" cell.kind cell.shape cell.nodeId cell.site
        let private noteReentrantReplayPoke (cell: ReplayCell) =
            let key = replayReentrantPokeKey cell
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if reentrantReplayPokeRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                    reentrantReplayPokeRepeats.[key] <- nextCount
                    nextCount)
            count, key

        let reentrantReplayP0CountForReason (reason: string) =
            if String.IsNullOrWhiteSpace reason then 0
            else
                let prefix = "reentrant_replay_driver_p0_fail_closed:"
                let key =
                    let idx = reason.IndexOf(prefix, StringComparison.Ordinal)
                    if idx >= 0 then reason.Substring(idx + prefix.Length)
                    else reason
                lock gate (fun () ->
                    let mutable count = 0
                    if reentrantReplayPokeRepeats.TryGetValue(key, &count) then count else 0)
        // ALPHA1083: the repeat key includes cursor/step so only an exact no-progress
        // parent replay state spends the repeat budget.  Runtime 1082 showed
        // semantic_step_partial handoffs can still be advancing across ticks.
        // ALPHA934: scheduled parent replay preservation is a liveness guard, not
        // an unbounded parking state. Runtime 933 proved the literal-op replay can
        // resolve, then the parent replay can be preserved/deferred again with no
        // new terminal before manual interrupt. Count the exact parent replay/cell
        // identity and fail closed only after repeated preservation of the same
        // typed replay obligation.
        let private parentReplayPreservedRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private parent_replay_preserved_repeat_cap = 4
        let parentReplayPreservedRepeatCap () = parent_replay_preserved_repeat_cap
        let private normalizeReplayPreservedKeyAtom (raw: string) =
            // ALPHA1376: the old repeat key included volatile task handoff strings
            // such as ty:ty@c:/home/git/...; terminal HUD then saw cap evidence while
            // frontier repeat_stats fell back to 0/4.  Normalize every repeat key to
            // the replay cell identity first, keeping full source sites out of the key.
            let v = if String.IsNullOrWhiteSpace raw then "unknown" else raw.Replace("\\", "/")
            let hash = v.LastIndexOf("#", StringComparison.Ordinal)
            if hash >= 0 && hash < v.Length - 1 then v.Substring(hash + 1)
            else
                let slash = v.LastIndexOf("/", StringComparison.Ordinal)
                if slash >= 0 && slash < v.Length - 1 then v.Substring(slash + 1)
                else v

        let private parentReplayPreservedKey (task: ReplayTask) (cellOpt: ReplayCell option) =
            match cellOpt with
            | Some cell ->
                let stableCellId = if cell.nodeId >= 0 then string cell.nodeId else normalizeReplayPreservedKeyAtom cell.site
                sprintf "%s|%s|%s|%s|%s|%s|cursor=%d|step=%d"
                    task.driver cell.kind cell.shape stableCellId (normalizeReplayPreservedKeyAtom cell.site) cell.status cell.cursor cell.step
            | None ->
                sprintf "%s|%s|missing_cell" task.driver (normalizeReplayPreservedKeyAtom task.key)

        let private parentReplayPreservedAliasRepeats = System.Collections.Generic.Dictionary<string,int>()

        let parentReplayPreservedCountForKey (key: string) =
            if String.IsNullOrWhiteSpace key then 0
            else
                lock gate (fun () ->
                    let mutable count = 0
                    if parentReplayPreservedRepeats.TryGetValue(key, &count) then count
                    elif parentReplayPreservedAliasRepeats.TryGetValue(normalizeReplayPreservedKeyAtom key, &count) then count
                    else 0)

        let parentReplayPreservedMaxRepeatSnapshot () =
            lock gate (fun () ->
                let mutable bestCount = 0
                let mutable bestKey = ""
                for kv in parentReplayPreservedRepeats do
                    if kv.Value > bestCount then
                        bestCount <- kv.Value
                        bestKey <- kv.Key
                for kv in parentReplayPreservedAliasRepeats do
                    if kv.Value > bestCount then
                        bestCount <- kv.Value
                        bestKey <- kv.Key
                bestCount, parent_replay_preserved_repeat_cap, bestKey)

        let parentReplayPreservedRepeatCapBreachedSnapshot () =
            let count, cap, key = parentReplayPreservedMaxRepeatSnapshot()
            count, cap, key, count > cap

        let private noteParentReplayPreservedAliasUnlocked (alias: string) (count: int) =
            if not (String.IsNullOrWhiteSpace alias) then
                let key = normalizeReplayPreservedKeyAtom alias
                let mutable prior = 0
                if (not (parentReplayPreservedAliasRepeats.TryGetValue(key, &prior))) || prior < count then
                    parentReplayPreservedAliasRepeats.[key] <- count

        let parentReplayPreservedCountForReason (reason: string) =
            if String.IsNullOrWhiteSpace reason then 0
            else
                let prefix = "parent_replay_status_preserved_repeat:"
                let key =
                    let idx = reason.IndexOf(prefix, StringComparison.Ordinal)
                    if idx >= 0 then reason.Substring(idx + prefix.Length)
                    else reason
                parentReplayPreservedCountForKey key

        let parentReplayPreservedCountForFrame (frame: Frame) =
            [ parentReplayPreservedCountForReason frame.reason
              parentReplayPreservedCountForKey frame.key
              parentReplayPreservedCountForKey frame.site ]
            |> List.max

        let private noteParentReplayPreserved (task: ReplayTask) (cellOpt: ReplayCell option) =
            let key = parentReplayPreservedKey task cellOpt
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if parentReplayPreservedRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                    parentReplayPreservedRepeats.[key] <- nextCount
                    noteParentReplayPreservedAliasUnlocked task.key nextCount
                    match cellOpt with
                    | Some cell ->
                        noteParentReplayPreservedAliasUnlocked (string cell.nodeId) nextCount
                        noteParentReplayPreservedAliasUnlocked cell.site nextCount
                        noteParentReplayPreservedAliasUnlocked (sprintf "%s|%s|%d" cell.kind cell.shape cell.nodeId) nextCount
                    | None -> ()
                    nextCount)
            count, key
        // ALPHA1240: parent-preserved repeat is not a string threshold anymore.
        // If there is a live queued/active replay lane, repeat pressure is a drain
        // obligation; only exact witness hardcaps or quiet repeats pin terminal.
        type ParentReplayPreservedRepeatDecisionId =
            | ParentReplayPreservedRepeatContinue
            | ParentReplayPreservedRepeatDeferLiveReplay
            | ParentReplayPreservedRepeatCycleBreakLiveReplay
            | ParentReplayPreservedRepeatDeferStructuralSurge
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard
            | ParentReplayPreservedRepeatHardPoisonReentryCap
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            | ParentReplayPreservedRepeatPinTerminal
            | ParentReplayPreservedRepeatPinExactWitness

        let private parentReplayPreservedRepeatDecisionText = function
            | ParentReplayPreservedRepeatContinue -> "continue"
            | ParentReplayPreservedRepeatDeferLiveReplay -> "defer_live_replay"
            | ParentReplayPreservedRepeatCycleBreakLiveReplay -> "cycle_break_live_replay"
            | ParentReplayPreservedRepeatDeferStructuralSurge -> "defer_structural_surge"
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard -> "replay_repeat_live_tail_guard"
            | ParentReplayPreservedRepeatHardPoisonReentryCap -> "hard_poison_reentry_cap"
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted -> "poison_after_cycle_break_exhausted"
            | ParentReplayPreservedRepeatPinTerminal -> "pin_terminal"
            | ParentReplayPreservedRepeatPinExactWitness -> "pin_exact_witness"

        // ALPHA1292: start the multi-round migration away from ad-hoc replay-driver
        // poison strings.  This DU names the authority boundary used by the driver
        // poison handoff before later rounds move ReplayTask.status/ReplayCell.status
        // themselves from strings into typed cases.
        type ReplayDriverPoisonDecisionId =
            | ReplayDriverPoisonNoPoison
            | ReplayDriverPoisonCellPoison
            | ReplayDriverPoisonPayloadPoison
            | ReplayDriverPoisonFrontierSameIdentityPoison
            | ReplayDriverPoisonFrontierFallbackPoison

        let private replayDriverPoisonDecisionText = function
            | ReplayDriverPoisonNoPoison -> "no_poison"
            | ReplayDriverPoisonCellPoison -> "cell_poison"
            | ReplayDriverPoisonPayloadPoison -> "payload_poison"
            | ReplayDriverPoisonFrontierSameIdentityPoison -> "frontier_same_identity_poison"
            | ReplayDriverPoisonFrontierFallbackPoison -> "frontier_fallback_poison"

        let private parentReplayPreservedRepeatDecisionShouldPin = function
            | ParentReplayPreservedRepeatPinTerminal
            | ParentReplayPreservedRepeatPinExactWitness
            | ParentReplayPreservedRepeatHardPoisonReentryCap
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted -> true
            | ParentReplayPreservedRepeatContinue
            | ParentReplayPreservedRepeatDeferLiveReplay
            | ParentReplayPreservedRepeatCycleBreakLiveReplay
            | ParentReplayPreservedRepeatDeferStructuralSurge
            | ParentReplayPreservedRepeatCycleFuseLiveTailGuard -> false

        let private parentReplayPreservedRepeatTerminalStatusId = function
            | ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            | ParentReplayPreservedRepeatHardPoisonReentryCap -> SemanticParentReplayCycleBreakPoisoned
            | _ -> SemanticParentReplayStatusPreservedRepeatBlocked

        let private parentReplayPreservedRepeatTerminalStatus decision =
            decision |> parentReplayPreservedRepeatTerminalStatusId |> semanticStatusToString

        // ALPHA1337: second-pass assessment guard.  Alpha1336 blocked the named
        // cross_kind_active_replay_driver branch, but the same p=0 yield-thrash
        // leaked through parent-replay preserved deferrals.  Treat pending=0 as a
        // terminal graph fact before calling Thread.Yield.
        type ParentReplayPreservedYieldThrashDecisionId =
            | ParentReplayPreservedYieldAllowed
            | ParentReplayPreservedHardPoisonPendingZero
            | ParentReplayPreservedYieldCapBreachedSurface

        let private parentReplayPreservedYieldThrashDecisionText = function
            | ParentReplayPreservedYieldAllowed -> "yield_allowed"
            | ParentReplayPreservedHardPoisonPendingZero -> "hard_poison_pending_zero"
            | ParentReplayPreservedYieldCapBreachedSurface -> "surface_cascaded_terminal_repeat_cap_breach"

        let private parentReplayPreservedYieldThrashDecisionFor decision repeatCount repeatCap pending queueDepth activeDepth writeWitness =
            let liveQueueOrActive = queueDepth > 0 || activeDepth > 0
            let smallTailAtCap =
                decision = ParentReplayPreservedRepeatCycleFuseLiveTailGuard
                && repeatCount >= repeatCap
                && pending > 0
                && queueDepth <= 3
                && activeDepth <= 1
                && not writeWitness
            if (repeatCount > repeatCap && not writeWitness) || smallTailAtCap then
                // ALPHA1529: q/a/p liveness is evidence, not authority, once the
                // parent-preserved live-tail guard reaches its local cap on a tiny
                // tail.  1528 ended manually at q/a/p=3/1/2 with count=4/cap=4;
                // waiting for count>cap simply burns another scheduler lap.
                ParentReplayPreservedYieldCapBreachedSurface
            else
                match decision with
                | ParentReplayPreservedRepeatDeferLiveReplay
                | ParentReplayPreservedRepeatCycleBreakLiveReplay
                | ParentReplayPreservedRepeatDeferStructuralSurge
                | ParentReplayPreservedRepeatCycleFuseLiveTailGuard when pending = 0 && not liveQueueOrActive && not writeWitness ->
                    ParentReplayPreservedHardPoisonPendingZero
                | _ -> ParentReplayPreservedYieldAllowed

        // ALPHA1428: cooperative handoff repeat-cap breach needs its own closed
        // decision because runtime 1427 surfaced repeat=9/4 while q/a/p=6/4/2.
        // Pending obligations plus a physical queue are still runnable replay, not
        // proof that the cascaded parent poison should surface on this turn.
        type CooperativeRepeatCapSurfaceDecisionId =
            | CooperativeRepeatCapSurfaceNow
            | CooperativeRepeatCapDeferPendingActiveTail
            | CooperativeRepeatCapDeferActiveOnlyPendingTail
            | CooperativeRepeatCapDeferFreshQueueTail

        let private cooperativeRepeatCapSurfaceDecisionText = function
            | CooperativeRepeatCapSurfaceNow -> "surface_now"
            | CooperativeRepeatCapDeferPendingActiveTail -> "defer_pending_active_tail"
            | CooperativeRepeatCapDeferActiveOnlyPendingTail -> "defer_active_only_pending_tail"
            | CooperativeRepeatCapDeferFreshQueueTail -> "defer_fresh_queue_tail"

        let private cooperativeRepeatCapSurfaceShouldDefer = function
            | CooperativeRepeatCapDeferPendingActiveTail
            | CooperativeRepeatCapDeferActiveOnlyPendingTail
            | CooperativeRepeatCapDeferFreshQueueTail -> true
            | CooperativeRepeatCapSurfaceNow -> false

        let private cooperativeRepeatCapSurfaceDecisionFor pending queueDepth activeDepth replayComplete writeWitness =
            if replayComplete || writeWitness then CooperativeRepeatCapSurfaceNow
            elif pending > 0 && queueDepth > 0 && activeDepth > 0 then CooperativeRepeatCapDeferPendingActiveTail
            elif pending > 0 && activeDepth > 0 then CooperativeRepeatCapDeferActiveOnlyPendingTail
            elif pending = 0 && queueDepth > 0 && activeDepth > 0 then CooperativeRepeatCapDeferFreshQueueTail
            else CooperativeRepeatCapSurfaceNow

        // ALPHA1436: stack-fence repeat-cap breach is also a typed decision.
        // Runtime 1435 surfaced stack_fence_cap_breach_surface with q/a/p=4/5/2,
        // which is a live pending+active tail.  The stack fence must defer the
        // cascaded terminal just like the cooperative handoff path.
        type StackFenceRepeatCapDecisionId =
            | StackFenceRepeatCapSurfaceNow
            | StackFenceRepeatCapDeferPendingActiveTail
            | StackFenceRepeatCapDeferFreshQueueTail

        let private stackFenceRepeatCapDecisionText = function
            | StackFenceRepeatCapSurfaceNow -> "surface_now"
            | StackFenceRepeatCapDeferPendingActiveTail -> "defer_pending_active_tail"
            | StackFenceRepeatCapDeferFreshQueueTail -> "defer_fresh_queue_tail"

        let private stackFenceRepeatCapShouldDefer = function
            | StackFenceRepeatCapDeferPendingActiveTail
            | StackFenceRepeatCapDeferFreshQueueTail -> true
            | StackFenceRepeatCapSurfaceNow -> false

        let private stackFenceRepeatCapDecisionFor pending queueDepth activeDepth replayComplete writeWitness =
            // ALPHA1487: p>0/a>0 is the strongest stack-fence liveness signal.
            // 1486.jsonl surfaced stack_fence_cap_breach_surface at q/a/p=1/5/2
            // because replay_complete/write_witness can flicker while pending fence
            // waiters are still owned.  Defer the pending-active tail before trusting
            // the replay-complete bit; the surrounding budget remains bounded.
            if pending > 0 && activeDepth > 0 && queueDepth >= 0 then StackFenceRepeatCapDeferPendingActiveTail
            elif replayComplete || writeWitness then StackFenceRepeatCapSurfaceNow
            elif queueDepth > 0 && activeDepth > 0 then StackFenceRepeatCapDeferFreshQueueTail
            else StackFenceRepeatCapSurfaceNow

        // ALPHA1339: alpha1338 still let a pending-zero parent poison terminal be
        // erased by "recent progress" credit.  Recent replay/root chatter can open a
        // phase2 transition before this branch, but once this branch sees p=0 the
        // terminal itself must remain authoritative.
        type ParentReplayTerminalRecentProgressDecisionId =
            | ParentReplayTerminalRecentProgressAllowClearWithWitness
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail

        let parentReplayTerminalRecentProgressDecisionText = function
            | ParentReplayTerminalRecentProgressAllowClearWithWitness -> "allow_clear_with_witness"
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero -> "keep_pinned_pending_zero"
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained -> "confirm_pending_zero_physical_tail_drained"
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority -> "surface_replay_only_no_root_authority"
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained -> "surface_pending_zero_physical_tail_drained"
            | ParentReplayTerminalRecentProgressDeferLiveTail -> "defer_live_tail"

        let parentReplayTerminalRecentProgressDecisionShouldClear = function
            | ParentReplayTerminalRecentProgressAllowClearWithWitness -> true
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail -> false

        let parentReplayTerminalRecentProgressDecisionShouldDrainTail = function
            | ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            | ParentReplayTerminalRecentProgressDeferLiveTail -> true
            | ParentReplayTerminalRecentProgressAllowClearWithWitness
            | ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            | ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            | ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained -> false

        let parentReplayTerminalRecentProgressDecisionFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (recentReplayDelta: int64)
            (recentRootDelta: int64)
            (recentSampledDelta: int64)
            (recentTerminalDelta: int64)
            (terminalAgeMs: int)
            (stableDrainAgeMs: int)
            =
            let replayOnlyNoRootAuthorityMature =
                pending = 0
                && not writeWitness
                && queueDepth <= 0
                && activeDepth <= 0
                && terminalAgeMs >= max 750 (stableDrainAgeMs / 2)
                && recentReplayDelta > 0L
                && recentSampledDelta > 0L
                && recentRootDelta <= 0L
            if replayOnlyNoRootAuthorityMature then
                ParentReplayTerminalRecentProgressSurfaceReplayOnlyNoRootAuthority
            elif pending = 0 && not writeWitness && queueDepth <= 0 && activeDepth <= 0 && terminalAgeMs < stableDrainAgeMs then
                ParentReplayTerminalRecentProgressConfirmPhysicalTailDrained
            elif pending = 0 && not writeWitness && queueDepth <= 0 && activeDepth <= 0 then
                ParentReplayTerminalRecentProgressSurfacePhysicalTailDrained
            elif pending = 0 && not writeWitness && (queueDepth > 0 || activeDepth > 0) then
                // ALPHA1401: runtime 1400 disproved the old assumption that pinned
                // rank-83 q/a tail is only residue: the same frame still had root and
                // replay deltas plus q/a live.  Defer until the physical tail is truly
                // quiet or a hard/stale authority path fires.
                ParentReplayTerminalRecentProgressDeferLiveTail
            elif pending = 0 then ParentReplayTerminalRecentProgressKeepPinnedPendingZero
            elif writeWitness && (recentReplayDelta > 0L || recentRootDelta > 0L || recentSampledDelta > 0L || recentTerminalDelta > 0L) then
                ParentReplayTerminalRecentProgressAllowClearWithWitness
            elif queueDepth > 0 || activeDepth > 0 then ParentReplayTerminalRecentProgressDeferLiveTail
            else ParentReplayTerminalRecentProgressKeepPinnedPendingZero

        // ALPHA1340: audit pass after 1339.  Cooperative replay may only reschedule
        // a pending-zero tail when it has a real writer/root witness.  Grace/live
        // terminal labels are no longer harmless observability; they are part of the
        // livelock mechanism the assessments kept flagging.
        type ReplayDriverCooperativePendingZeroDecisionId =
            | ReplayDriverCooperativeAllowSchedule
            | ReplayDriverCooperativeHardStopPendingZero

        let replayDriverCooperativePendingZeroDecisionText = function
            | ReplayDriverCooperativeAllowSchedule -> "allow_schedule"
            | ReplayDriverCooperativeHardStopPendingZero -> "hard_stop_pending_zero"

        let replayDriverCooperativePendingZeroDecisionShouldStop = function
            | ReplayDriverCooperativeHardStopPendingZero -> true
            | ReplayDriverCooperativeAllowSchedule -> false

        let replayDriverCooperativePendingZeroDecisionFor
            (pending: int)
            (queueDepth: int)
            (activeDepth: int)
            (writeWitness: bool)
            (reason: string)
            =
            let hasRunnableTail = queueDepth > 0 || activeDepth > 0
            let reasonMentionsAssessmentEscape =
                reason.IndexOf("parent_resume", StringComparison.Ordinal) >= 0
                || reason.IndexOf("post_active_parent_resume_queue_tail", StringComparison.Ordinal) >= 0
                || reason.IndexOf("cross_kind", StringComparison.Ordinal) >= 0
                || reason.IndexOf("hot_frontier", StringComparison.Ordinal) >= 0
                || reason.IndexOf("cooperative_replay_handoff", StringComparison.Ordinal) >= 0
                || reason.IndexOf("grace", StringComparison.Ordinal) >= 0
                || reason.IndexOf("live_replay", StringComparison.Ordinal) >= 0
                || reason.IndexOf("terminal_live", StringComparison.Ordinal) >= 0
                || reason.IndexOf("no_work", StringComparison.Ordinal) >= 0
                || reason.IndexOf("root_complete_stale_retarget", StringComparison.Ordinal) >= 0
                || reason.IndexOf("concrete_op_terminal", StringComparison.Ordinal) >= 0
                || reason.IndexOf("dynamic_join_terminal", StringComparison.Ordinal) >= 0
            if pending = 0 && not hasRunnableTail && not writeWitness && reasonMentionsAssessmentEscape then
                ReplayDriverCooperativeHardStopPendingZero
            else
                ReplayDriverCooperativeAllowSchedule

        let private parentReplayPreservedRepeatDecisionFor repeatCount repeatCap exactWitnessHardcap queueDepth activeDepth pending writeWitness =
            let liveQueueOrActive = queueDepth > 0 || activeDepth > 0
            if exactWitnessHardcap then ParentReplayPreservedRepeatPinExactWitness
            elif repeatCount < repeatCap then
                // ALPHA1347: follow the assessment literally.  The local repeat cap,
                // not global pending, decides whether a preserved repeat may continue.
                // pending=0 only says no IVar is parked; it does not prove the replay
                // graph is dead, even if the queue snapshot is momentarily empty.
                ParentReplayPreservedRepeatContinue
            elif liveQueueOrActive && repeatCount >= repeatCap + 1 && not writeWitness then
                // ALPHA1364: runtime 1363 still allowed repeat=5/4 and 6/4 when
                // pending JP work existed.  Pending proves there is more graph work,
                // not that this same stale parent continuation can keep bypassing
                // the local repeat cap.  Cap+1 hard-poisons with or without pending.
                ParentReplayPreservedRepeatHardPoisonReentryCap
            elif liveQueueOrActive && repeatCount >= repeatCap then
                // ALPHA1363: exactly at the cap gets one typed live-tail guard receipt;
                // the next recurrence hard-poisons above. This preserves evidence while
                // preventing cap+2/cap+8 churn.
                ParentReplayPreservedRepeatCycleFuseLiveTailGuard
            elif liveQueueOrActive then
                ParentReplayPreservedRepeatDeferLiveReplay
            elif pending > 0 && not writeWitness then ParentReplayPreservedRepeatDeferStructuralSurge
            elif repeatCount >= repeatCap + 16 then ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            elif repeatCount >= repeatCap && not writeWitness then ParentReplayPreservedRepeatPinTerminal
            elif repeatCount >= repeatCap then ParentReplayPreservedRepeatPoisonAfterCycleBreakExhausted
            else ParentReplayPreservedRepeatPinTerminal

        // ALPHA993: a scheduled_parent_replay that has already hit the preserved-repeat cap is terminal.
        // Runtime 992 showed alpha992 fixed the NullReferenceException loop, then pinned
        // semantic_parent_replay_status_preserved_repeat_blocked while the same live replay
        // kept executing and required manual interruption. Once this cap is hit, remove the
        // replay task from the queue and publish the existing terminal instead of resuming it.
        // ALPHA992: a guarded NullReferenceException is liveness only while it
        // exposes fresh replay evidence. Runtime 991 kept reporting the same
        // let-success/apply-continuation null guards until manual interruption.
        // Count the exact replay task/cell identity and promote it to an
        // existing explicit terminal after a small cap instead of inventing a
        // new state or spinning semantic_step_partial forever.
        let private replayNullGuardRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private replay_null_guard_repeat_cap = 4
        let private replayNullGuardKey (taskOpt: ReplayTask option) (cellOpt: ReplayCell option) (ex: exn) =
            let taskPart =
                match taskOpt with
                | Some task -> sprintf "%s|%s|%s" task.driver task.status task.key
                | None -> "missing_task"
            let cellPart =
                match cellOpt with
                | Some cell -> sprintf "%s|%s|%d|%s|%s" cell.kind cell.shape cell.nodeId cell.site cell.status
                | None -> "missing_cell"
            sprintf "%s|%s|%s" (ex.GetType().Name) taskPart cellPart
        let private noteReplayNullGuard (taskOpt: ReplayTask option) (cellOpt: ReplayCell option) (ex: exn) =
            let key = replayNullGuardKey taskOpt cellOpt ex
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if replayNullGuardRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                    replayNullGuardRepeats.[key] <- nextCount
                    nextCount)
            count, key
        // ALPHA492: compact anti-repeat ledger for stale root-complete retargets.
        // A root-complete shell is evidence for its original cell only; if the same
        // different incoming cell repeatedly retargets it, quarantine that retarget
        // as a terminal blocker instead of spinning another continuation envelope.
        let private staleRootRetargetRepeats = System.Collections.Generic.Dictionary<string,int>()
        // ALPHA501: terminal ELet cycle repair attempts are capped per let/role/node.
        // This prevents retry-drain from endlessly re-scheduling the same child while
        // still allowing the live LetSpine to expose one more body/success replay.
        let private letTerminalCycleRepairs = System.Collections.Generic.Dictionary<string,int>()
        let private noteLetTerminalCycleRepairLocked (key: string) =
            let mutable prior = 0
            let next = if letTerminalCycleRepairs.TryGetValue(key, &prior) then prior + 1 else 1
            letTerminalCycleRepairs.[key] <- next
            next
        // ALPHA571: terminal parent-continuation cycle repairs are no longer
        // restricted to ELet.  Runtime 570 reached a repeated EApply/ETypeApply
        // cycle after the composite children had made real progress.  Keep a
        // separate cap so broad composite repair cannot spin forever.
        let private compositeTerminalCycleRepairs = System.Collections.Generic.Dictionary<string,int>()
        let private noteCompositeTerminalCycleRepairLocked (key: string) =
            let mutable prior = 0
            let next = if compositeTerminalCycleRepairs.TryGetValue(key, &prior) then prior + 1 else 1
            compositeTerminalCycleRepairs.[key] <- next
            next
        // ALPHA503: a ready replay duplicate can be real progress if the task was
        // produced by alpha502's leaf-yield terminal-let repair.  The old duplicate
        // guard suppressed the already-ready task and left retry_stop_drain looping
        // over duplicate=1.  Cap reruns by replay key so a bad envelope becomes a
        // typed repeat blocker instead of an unbounded scheduler spin.
        let private readyDuplicateReplayReruns = System.Collections.Generic.Dictionary<string,int>()
        let private noteReadyDuplicateReplayRerunLocked (key: string) =
            let mutable prior = 0
            let next = if readyDuplicateReplayReruns.TryGetValue(key, &prior) then prior + 1 else 1
            readyDuplicateReplayReruns.[key] <- next
            next
        // ALPHA679: retry_stop can churn on the same leaf-parent gap by yielding
        // a ty semantic_leaf_complete frontier to the same term continuation_envelope
        // over and over.  Count that exact leaf/alternate handoff and, after a small
        // cap, surface the real missing-parent terminal instead of producing MBs of
        // repeated yield logs.  This is a diagnostic/scheduler guard only.
        let private leafParentContinuationYieldRepeats = System.Collections.Generic.Dictionary<string,int>()
        let private leaf_parent_continuation_yield_cap = 16
        let private noteLeafParentContinuationYieldLocked (leaf: Frame) (alt: Frame) =
            let leafNode =
                match leaf.semanticCell with
                | Some cell -> cell.nodeId
                | None -> -1
            let altNode =
                match alt.semanticCell with
                | Some cell -> cell.nodeId
                | None -> -1
            let key = sprintf "%s|%s|%d|%s|%d|%s|%s|%d|%s" leaf.kind leaf.status leaf.cursor leaf.site leafNode alt.kind alt.status altNode alt.site
            let mutable prior = 0
            let next = if leafParentContinuationYieldRepeats.TryGetValue(key, &prior) then prior + 1 else 1
            leafParentContinuationYieldRepeats.[key] <- next
            next, key

        // ALPHA494: progress-bearing scheduler yields (fingerprint/stale-retarget)
        // can justify a bounded retry trampoline, but only if the selected frontier
        // is preserved across the immediate retry.  This counter is consumed by
        // BuildFile.retry_stop; it is not a semantic proof.
        let mutable private progressYieldCount = 0
        let private noteProgressYieldLocked () =
            progressYieldCount <- progressYieldCount + 1
        let tryConsumeProgressYield () =
            lock gate (fun () ->
                if progressYieldCount > 0 then
                    progressYieldCount <- progressYieldCount - 1
                    true
                else false)
        // ALPHA952: retry_stop must be able to distinguish a hard terminal from a
        // terminal-shaped frontier that still has a cooperative replay tick in flight.
        // This is a liveness hint only; it does not prove or fabricate semantic success.
        let hasProgressYield () =
            lock gate (fun () -> progressYieldCount > 0)
        // ALPHA1056: after a concrete root-complete write witness has decided that
        // a stale retarget should not be reinserted, stale progress-yield hints must
        // not keep retry_stop in the same pending=2 finalization loop.
        let drainProgressYield () =
            lock gate (fun () ->
                let n = progressYieldCount
                progressYieldCount <- 0
                n)
        // ALPHA484: replay-driver stack depth for suppressing semantic-cell-attached
        // self-pokes while the driver is already reducing that active typed replay.
        let mutable private replayDriverActiveDepth = 0
        let replayDriverActiveDepthValue () =
            lock gate (fun () -> replayDriverActiveDepth)

        let mutable private replayDriverStackFenceQueued = false
        let mutable private replayDriverStackFenceQueuedSinceMs = 0L
        let mutable private stackFenceHopacOverrideHotRowOrdinal = 0
        let private nextStackFenceHopacOverrideHotRowOrdinal () =
            System.Threading.Interlocked.Increment(&stackFenceHopacOverrideHotRowOrdinal)
        let private shouldEmitStackFenceHopacOverrideHotRow ordinal =
            ordinal > 0 && (ordinal <= 4 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)

        let mutable private stackFencePrefetchLedgerAuditHotRowOrdinal = 0
        let private nextStackFencePrefetchLedgerAuditHotRowOrdinal () =
            System.Threading.Interlocked.Increment(&stackFencePrefetchLedgerAuditHotRowOrdinal)
        let private shouldEmitStackFencePrefetchLedgerAuditHotRow ordinal =
            ordinal > 0 && (ordinal <= 3 || ordinal = 16 || ordinal = 64 || ordinal % 512 = 0)
        // ALPHA434: kind-local frontier slots.
        // Alpha433 proved term replay can now reach semantic_root_complete and store source-key
        // values, but the remaining log alternated term/ty fuses through one canonical frontier,
        // causing kind_local_active_reset and missing_frontier churn.  Keep at most one parked
        // frame per evaluator kind; switching kinds parks the active frame instead of erasing it.
        let private slotSetLocked (frame: Frame) =
            match frame.kind with
            | "term" -> frontierTerm <- Some frame
            | "ty" -> frontierTy <- Some frame
            | _ -> ()

        let private slotGetLocked (kind: string) =
            match kind with
            | "term" -> frontierTerm
            | "ty" -> frontierTy
            | _ -> None

        let private saveFrontierLocked () =
            match frontier with
            | Some frame -> slotSetLocked frame
            | None -> ()

        let private selectKindLocked (kind: string) =
            if kind <> "term" && kind <> "ty" then false
            else
                match frontier with
                | Some frame when frame.kind = kind ->
                    slotSetLocked frame
                    true
                | _ ->
                    saveFrontierLocked ()
                    match slotGetLocked kind with
                    | Some frame ->
                        frontier <- Some frame
                        true
                    | None ->
                        false

        let private kindFromReason (text: string) =
            if System.String.IsNullOrWhiteSpace text then "unknown"
            elif text.Contains("ty_", System.StringComparison.Ordinal) || text.Contains("ty@", System.StringComparison.Ordinal) then "ty"
            elif text.Contains("term_", System.StringComparison.Ordinal) || text.Contains("term@", System.StringComparison.Ordinal) then "term"
            else "unknown"

        let parkActiveAndSelectKind (requestedKind: string) =
            lock gate (fun () ->
                let restored = selectKindLocked requestedKind
                if not restored then frontier <- None
                replayScheduledKey <- None
                replayQueue <- []
                replayDriverStackFenceQueued <- false
                activeRun <- false
                restored)

        let parkActiveAndSelectKindKeepingReplay (event: string) (requestedKind: string) =
            // ALPHA1074: keep this helper self-contained.  It sits before
            // pendingCount in lexical order, so it cannot reference pendingCount
            // or the later local `esc` alias.  Recompute the tiny pending summary
            // from the three frontier slots while preserving replayQueue.
            let restored, qd, pendingNow =
                lock gate (fun () ->
                    let restored = selectKindLocked requestedKind
                    if not restored then frontier <- None
                    replayDriverStackFenceQueued <- false
                    activeRun <- false
                    let mutable pendingNow = 0
                    let seen = System.Collections.Generic.HashSet<string>()
                    let add (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let k = frame.kind + "|" + frame.key + "|" + frame.site
                            if seen.Add k then pendingNow <- pendingNow + 1
                        | None -> ()
                    add frontier
                    add frontierTerm
                    add frontierTy
                    restored, replayQueue.Length, pendingNow)
            DiagJson.emit (
                sprintf "{\"kind\":\"eval_worklist_global_fuse_deferred_replay_queue_preserved\",\"event\":%s,\"requested_kind\":%s,\"queue_depth\":%d,\"pending\":%d,\"restored\":%b,\"single_flight\":1,\"next\":\"await_preserved_replay_tick\"}"
                    (DiagJson.esc event) (DiagJson.esc requestedKind) qd pendingNow restored)
            restored

        // ALPHA390: write-gate witness ledger.  Alpha389 kept semantic_root_complete
        // absorbing inside the worklist, but the following retry invalidation could leave
        // BuildOk with only a BuildFile.replay_root_complete reason and no current
        // frontier cell.  Keep a short-lived typed proof for the writer; normal retry
        // control still uses hasReplayComplete() so stale completions cannot advance
        // evaluator state.
        let mutable private replayRootCompleteWitnessUtc = System.DateTime.MinValue
        let mutable private replayRootCompleteWitnessSummary = ""
        let private replayRootCompleteWitnessWindowMs = 120000.0

        // ALPHA424: stable root-complete retry ledger.
        // Alpha423 proved preserving the completed frontier is not enough: spiral.spi:2671
        // can keep proving the same cursor=trace_len root-complete cell for hundreds of
        // attempts, producing megabytes of replay logs without new information.  Track the
        // root-complete frontier fingerprint and let BuildFile stop after a small stable
        // repeat budget with a compact typed diagnostic.
        let mutable private stableRootCompleteKey = ""
        let mutable private stableRootCompleteCount = 0

        // ALPHA476: do not spend the bounded root-complete yield budget on the
        // exact same blocked-root -> selected-frontier pair forever.  The alpha475
        // runtime log proved the cap accounting works, but also proved that selecting
        // the same semantic_dynamic_join_apply_blocked term frontier 31+ times cycles
        // back to the same ty semantic_root_complete proof.
        let mutable private stableRootSelectedKey = ""
        let mutable private stableRootSelectedCount = 0
        let private stable_root_selected_frontier_repeat_cap = 8

        // ALPHA584: a selected-frontier repeat is terminal only after the real
        // typed stepper has been re-enqueued as a continuation envelope.  Runtime
        // 583 proved alpha583 ranks and aborts the repeat correctly, but also
        // showed the repeated EApply at core/listm.spi:27 was parked as a bare
        // semantic_step_partial frame with no replay queue.  Give that exact cell
        // a small, bounded replay escape before preserving the precise terminal.
        let private selectedFrontierStepperReplayAttempts = System.Collections.Generic.Dictionary<string,int>()
        let private selected_frontier_stepper_replay_cap = 2
        let private selected_frontier_stepper_rearm_cap = 2
        // Captured composite frontiers can arrive after a successful root-complete handoff:
        // the log shows an existing term/ESeq semantic cell, not a missing value. Give that
        // captured cell a bounded replay envelope before terminalizing selected-frontier repeat.
        let private selected_frontier_captured_cell_replay_cap = 4

        let private esc (s: string) =
            if Object.ReferenceEquals(s,null) then "null" else
                let s =
                    s.Replace("\\","\\\\")
                     .Replace("\"","\\\"")
                     .Replace("\r","\\r")
                     .Replace("\n","\\n")
                     .Replace("\t","\\t")
                "\"" + s + "\""

        // ALPHA1040: runtime 1039 proved a diagnostic reason could append the same
        // app-root finalization tag hundreds of times and create multi-hundred-KB
        // JSON lines. Keep the evidence, but make reason strings idempotent and
        // bounded at the diagnostic boundary; no replay value or terminal rank changes.
        let private compactReasonTag (tag: string) (reason: string) =
            if System.Object.ReferenceEquals(reason, null) || reason = "" then ""
            else
                let parts = reason.Split([|':'|], System.StringSplitOptions.RemoveEmptyEntries)
                let tagCount =
                    parts
                    |> Array.filter (fun part -> part = tag)
                    |> Array.length
                if tagCount > 0 then
                    let prefixParts =
                        parts
                        |> Array.takeWhile (fun part -> part <> tag)
                        |> Array.truncate 4
                    let prefix =
                        if prefixParts.Length = 0 then "reason"
                        else System.String.Join(":", prefixParts)
                    if tagCount = 1 then sprintf "%s:%s" prefix tag
                    else sprintf "%s:%s#repeat=%d" prefix tag tagCount
                else reason

        let private compactFrameReason (reason: string) =
            let tag = "app_root_base16_live_replay_root_witness_finalization_deferred"
            let r = compactReasonTag tag reason
            if System.Object.ReferenceEquals(r, null) then ""
            elif r.Length <= 768 then r
            else r.Substring(0, 768) + sprintf "…[+%d chars]" (r.Length - 768)

        let private boundedReasonAppend (reason: string) (tag: string) =
            let r = compactFrameReason reason
            if r.IndexOf(tag, System.StringComparison.Ordinal) >= 0 then compactFrameReason r
            elif System.String.IsNullOrEmpty r then tag
            else compactFrameReason (r + ":" + tag)

        type LogCompletenessPolicy =
            | FullFidelityJsonl
            | TruncatedPreview of int

        let private activeLogCompletenessPolicy = FullFidelityJsonl

        let private logCompletenessPolicyText policy =
            match policy with
            | FullFidelityJsonl -> "full_fidelity_jsonl"
            | TruncatedPreview n -> sprintf "truncated_preview_%d" n

        let terminalContractRank (status: string) =
            match semanticTerminalContractForText status with
            | Some contract -> contract.rank
            | None -> 0

        let isTerminalContractStatus (status: string) =
            match semanticTerminalContractForText status with
            | Some _ -> true
            | None -> false

        let terminalContractNext (status: string) =
            match semanticTerminalContractForText status with
            | Some contract -> contract.next
            | None -> "explicit_eval_worklist_real_stepper_required"

        let isParentReplayCycleBreakPoisonedStatus (status: string) =
            match semanticStatusOfString status with
            | SemanticParentReplayCycleBreakPoisoned -> true
            | _ -> false

        let private frameSemanticStatusId (frame: Frame) = semanticStatusOfString frame.status
        let private cellSemanticStatusId (cell: ReplayCell) = semanticStatusOfString cell.status
        let private frameSemanticStatusIs statusId (frame: Frame) = frameSemanticStatusId frame = statusId
        let private cellSemanticStatusIs statusId (cell: ReplayCell) = cellSemanticStatusId cell = statusId
        let private frameOrCellSemanticStatusIs statusId (frame: Frame) =
            frameSemanticStatusIs statusId frame
            || (match frame.semanticCell with
                | Some cell -> cellSemanticStatusIs statusId cell
                | None -> false)
        let private frameOrCellIsRootComplete frame = frameOrCellSemanticStatusIs SemanticRootComplete frame

        let private pendingCountUnlocked () =
            let mutable n = 0
            let seen = System.Collections.Generic.HashSet<string>()
            let add (opt: Frame option) =
                match opt with
                | Some frame ->
                    let k = frame.kind + "|" + frame.key + "|" + frame.site
                    if seen.Add k then n <- n + 1
                | None -> ()
            add frontier
            add frontierTerm
            add frontierTy
            n

        // ALPHA1139: keep the replay/root liveness DU before all consumers.
        // Alpha1138 proved the direction was right but placed the helper after
        // pinTerminalContractLocked, which F# rejects because local lets are lexical.
        // The snapshot is intentionally built from existing worklist facts only; it
        // does not promote a terminal, fabricate replay completion, or mint BuildOk.
        type ReplayDrainState =
            | ReplayDrainQuiescent
            | ReplayDrainPendingOnly
            | ReplayDrainQueueAlive
            | ReplayDrainActiveOnly
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive

        type TerminalPinLivenessGate =
            | TerminalPinNoLiveReplay
            | TerminalPinLiveReplay of ReplayDrainState
            | TerminalPinWitnessQueue of ReplayDrainState
            | TerminalPinProgressYield of ReplayDrainState

        let private replayDrainStateLocked () =
            let pending = pendingCountUnlocked()
            let qd = replayQueue.Length
            let active = replayDriverActiveDepth
            let rootWitness =
                match frontier with
                | Some frame when frameOrCellIsRootComplete frame -> true
                | Some _ -> false
                | None -> false
            let writeWitness = replayRootCompleteWitnessUtc <> System.DateTime.MinValue
            if pending <= 0 && qd <= 0 && active <= 0 then ReplayDrainQuiescent
            elif qd > 0 && rootWitness then ReplayDrainRootWitnessQueueAlive
            elif qd > 0 && writeWitness then ReplayDrainWriteWitnessQueueAlive
            elif qd > 0 then ReplayDrainQueueAlive
            elif active > 0 then ReplayDrainActiveOnly
            else ReplayDrainPendingOnly

        let private replayDrainStateToString state =
            match state with
            | ReplayDrainQuiescent -> "quiescent"
            | ReplayDrainPendingOnly -> "pending_only"
            | ReplayDrainQueueAlive -> "queue_alive"
            | ReplayDrainActiveOnly -> "active_only"
            | ReplayDrainRootWitnessQueueAlive -> "root_witness_queue_alive"
            | ReplayDrainWriteWitnessQueueAlive -> "write_witness_queue_alive"

        let private replayDrainStateHasQueue state =
            match state with
            | ReplayDrainQueueAlive
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive -> true
            | _ -> false

        let private replayDrainStateHasLiveReplay state =
            match state with
            | ReplayDrainQueueAlive
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive
            | ReplayDrainActiveOnly -> true
            | _ -> false

        let private replayDrainStateHasWitnessQueue state =
            match state with
            | ReplayDrainRootWitnessQueueAlive
            | ReplayDrainWriteWitnessQueueAlive -> true
            | _ -> false

        let private terminalPinLivenessGateOfState drainState progressYieldPending =
            if progressYieldPending then TerminalPinProgressYield drainState
            elif replayDrainStateHasWitnessQueue drainState then TerminalPinWitnessQueue drainState
            elif replayDrainStateHasLiveReplay drainState then TerminalPinLiveReplay drainState
            else TerminalPinNoLiveReplay

        let private terminalPinLivenessGateHasLiveReplay gate =
            match gate with
            | TerminalPinNoLiveReplay -> false
            | TerminalPinLiveReplay _
            | TerminalPinWitnessQueue _
            | TerminalPinProgressYield _ -> true

        let private terminalPinLivenessGateHasWitnessQueue gate =
            match gate with
            | TerminalPinWitnessQueue _ -> true
            | _ -> false

        let private terminalPinLivenessGateToString gate =
            match gate with
            | TerminalPinNoLiveReplay -> "no_live_replay"
            | TerminalPinLiveReplay state -> sprintf "live_replay:%s" (replayDrainStateToString state)
            | TerminalPinWitnessQueue state -> sprintf "witness_queue:%s" (replayDrainStateToString state)
            | TerminalPinProgressYield state -> sprintf "progress_yield:%s" (replayDrainStateToString state)

        let private liveReplayTerminalSuppressedLocked (status: string) =
            let statusId = semanticStatusOfString status
            let drainState = replayDrainStateLocked()
            let activeReplay = replayDrainStateHasLiveReplay drainState
            match liveReplayTerminalPolicyOfSemanticStatusId statusId with
            | DeferTerminalWhileLiveReplay ->
                pendingCountUnlocked() > 0 && activeReplay
            | SurfaceTerminalDuringLiveReplay
            | TerminalNotLiveReplayPolicy -> false

        let liveReplayTerminalSuppressed (status: string) =
            lock gate (fun () -> liveReplayTerminalSuppressedLocked status)

        let replayDrainStateSnapshot () =
            lock gate (fun () -> replayDrainStateLocked())

        let replayDrainStateText state = replayDrainStateToString state
        let replayDrainStateHasWitnessQueuePublic state = replayDrainStateHasWitnessQueue state
        let replayDrainStateHasLiveReplayPublic state = replayDrainStateHasLiveReplay state
        let replayDrainStateHasQueuePublic state = replayDrainStateHasQueue state

        // ALPHA1182: replay-driver exceptions are no longer pinned by the low-level
        // exception kind alone.  Runtime 1181 showed a generic NullReferenceException
        // on an EPairTest replay cell while pending/queued replay was still alive; the
        // old policy turned that first live retry into a rank-88 terminal.  Keep the
        // decision closed and generic: live drain can defer, repeated null guards still
        // pin once their bounded repeat cap fires, and no BuildOk/root proof is minted.
        type ReplayDriverExceptionTerminalDecisionId =
            | ReplayDriverExceptionPinNow
            | ReplayDriverExceptionDeferLiveReplayDrain
            | ReplayDriverExceptionNullGuardLiveReplayRetry
            | ReplayDriverExceptionPreserveRootWitnessDrain

        let private replayDriverExceptionTerminalDecisionText = function
            | ReplayDriverExceptionPinNow -> "pin_now"
            | ReplayDriverExceptionDeferLiveReplayDrain -> "defer_live_replay_drain"
            | ReplayDriverExceptionNullGuardLiveReplayRetry -> "null_guard_live_replay_retry"
            | ReplayDriverExceptionPreserveRootWitnessDrain -> "preserve_root_witness_drain"

        let private replayDriverExceptionTerminalDecisionFor pinPolicy drainState isNullException nullGuardBlocked progressYieldPending pending =
            let liveDrain =
                pending > 0
                || progressYieldPending
                || replayDrainStateHasLiveReplayPublic drainState
            match pinPolicy with
            | ReplayExceptionPreserveRootWitness when liveDrain -> ReplayDriverExceptionPreserveRootWitnessDrain
            | ReplayExceptionDeferLiveReplay when liveDrain -> ReplayDriverExceptionDeferLiveReplayDrain
            | ReplayExceptionPinTerminal when isNullException && liveDrain && not nullGuardBlocked -> ReplayDriverExceptionNullGuardLiveReplayRetry
            | _ -> ReplayDriverExceptionPinNow

        type TerminalPoisonCascadeDecisionId =
            | TerminalPoisonCascadeNone
            | TerminalPoisonCascadeGlobalFuse
            | TerminalPoisonCascadeParentReplay
            | TerminalPoisonCascadeReplayDriverException
            | TerminalPoisonCascadeOpImpl
            | TerminalPoisonCascadeDynamicJoin
            | TerminalPoisonCascadeRank80KnownTerminal

        let terminalPoisonCascadeDecisionText = function
            | TerminalPoisonCascadeNone -> "none"
            | TerminalPoisonCascadeGlobalFuse -> "global_fuse"
            | TerminalPoisonCascadeParentReplay -> "parent_replay"
            | TerminalPoisonCascadeReplayDriverException -> "replay_driver_exception"
            | TerminalPoisonCascadeOpImpl -> "op_impl"
            | TerminalPoisonCascadeDynamicJoin -> "dynamic_join"
            | TerminalPoisonCascadeRank80KnownTerminal -> "rank80_known_terminal"

        // ALPHA1409: keep the cascade live-tail deferral scheduler typed as well.
        // The branch that consumes this DU lives before the generic replay-drain helpers
        // are declared, so it must not call those later let-bound helpers directly.
        type TerminalPoisonCascadeLiveTailDeferDecisionId =
            | TerminalPoisonCascadeLiveTailNoDefer
            | TerminalPoisonCascadeLiveTailScheduleLocalDrain
            | TerminalPoisonCascadeLiveTailObserveActiveDrain

        let terminalPoisonCascadeLiveTailDeferDecisionText = function
            | TerminalPoisonCascadeLiveTailNoDefer -> "no_defer"
            | TerminalPoisonCascadeLiveTailScheduleLocalDrain -> "schedule_local_drain"
            | TerminalPoisonCascadeLiveTailObserveActiveDrain -> "observe_active_drain"

        let terminalPoisonCascadeLiveTailDeferDecisionFor pending queueDepth activeDepth progressYield =
            if pending > 0 || queueDepth > 0 then TerminalPoisonCascadeLiveTailScheduleLocalDrain
            elif activeDepth > 0 || progressYield > 0 then TerminalPoisonCascadeLiveTailObserveActiveDrain
            else TerminalPoisonCascadeLiveTailNoDefer

        let terminalPoisonCascadeDecisionFor rank pending queueDepth activeDepth progressYield status forceParentReplayCascade =
            // ALPHA1235: dynamic-join poison is the concrete 1233/1234 terminal, so
            // do not let a rank-table mismatch turn it into another passive pin.
            // If replay is or was live, dynamic-join apply blocked is poison even
            // before the generic rank>=80 gate.  Other known terminals keep the
            // rank gate.
            let liveOrRecentlyLive = pending > 0 || queueDepth > 0 || activeDepth > 0 || progressYield > 0
            let runnableQueueOrActive = queueDepth > 0 || activeDepth > 0
            if not liveOrRecentlyLive then TerminalPoisonCascadeNone
            else
                match semanticStatusOfString status with
                | SemanticDynamicJoinApplyBlocked -> TerminalPoisonCascadeDynamicJoin
                | _ when rank < 80 -> TerminalPoisonCascadeNone
                | SemanticGlobalFuseParentContinuationCycleBlocked -> TerminalPoisonCascadeGlobalFuse
                | SemanticMissingAfterPrefetchBlocked when pending = 0 && runnableQueueOrActive && progressYield > 0 ->
                    // ALPHA1398: rank-91 missing-after-prefetch is a drain obligation while the live tail is still running.
                    // A missing prefetch can be fulfilled by the active queue, so do not recursively poison slots before probation.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when runnableQueueOrActive && forceParentReplayCascade ->
                    // ALPHA1419: only proven macro authority may cascade a live parent-replay frontier.
                    // Stale pending witnesses without hard-cap receipts must defer instead of clearing q/a/p.
                    TerminalPoisonCascadeParentReplay
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when pending > 0 && liveOrRecentlyLive ->
                    // ALPHA1419: pending-positive parent replay poison is not cascade authority while q/a/progress exists.
                    // The 1418 trace.spi:121 frontier had p=2 and live replay evidence but no hard-cap receipt.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned when pending = 0 && runnableQueueOrActive ->
                    // ALPHA1347: do not let a fresh parent-replay terminal cascade murder a live queue.
                    // ALPHA1373 narrows the exception above to proven obligation-cap poison only.
                    TerminalPoisonCascadeNone
                | SemanticParentReplayStatusPreservedRepeatBlocked
                | SemanticParentReplayCycleBreakPoisoned -> TerminalPoisonCascadeParentReplay
                | SemanticReplayDriverExceptionBlocked -> TerminalPoisonCascadeReplayDriverException
                | SemanticOpImplRequiredBlocked -> TerminalPoisonCascadeOpImpl
                | SemanticOther _ when isTerminalContractStatus status -> TerminalPoisonCascadeRank80KnownTerminal
                | _ when isTerminalContractStatus status -> TerminalPoisonCascadeRank80KnownTerminal
                | _ -> TerminalPoisonCascadeNone

        // ALPHA1338: the 1337 log proved that rank-83 parent replay poison was still
        // being suppressed while pending=0 and writer witness=none.  Model the
        // suppression decision explicitly so "progress_yield" can no longer smuggle
        // a pending-zero tail back into the live replay loop.
        type ParentReplayPoisonLivenessId =
            | ParentReplayPoisonNoLiveTail
            | ParentReplayPoisonLiveQueueOrDriver
            | ParentReplayPoisonPendingWitness
            | ParentReplayPoisonRecentProgressOnly

        let private parentReplayPoisonLivenessText = function
            | ParentReplayPoisonNoLiveTail -> "no_live_tail"
            | ParentReplayPoisonLiveQueueOrDriver -> "live_queue_or_driver"
            | ParentReplayPoisonPendingWitness -> "pending_witness"
            | ParentReplayPoisonRecentProgressOnly -> "recent_progress_only"

        let private parentReplayPoisonLivenessFor terminalPinHasLiveReplay pendingForTerminalPin progressYieldCount =
            if pendingForTerminalPin > 0 then ParentReplayPoisonPendingWitness
            elif terminalPinHasLiveReplay then ParentReplayPoisonLiveQueueOrDriver
            elif progressYieldCount > 0 then ParentReplayPoisonRecentProgressOnly
            else ParentReplayPoisonNoLiveTail

        // ALPHA1396: reason strings are only input syntax at this boundary.  The
        // pin policy below consumes a typed probe so future cross-kind / preserved
        // repeat policies do not keep growing JS-style string contains branches.
        type ParentReplayPoisonReasonProbeId =
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver
            | ParentReplayPoisonReasonStatusPreservedRepeat
            | ParentReplayPoisonReasonOther of string

        let private parentReplayPoisonReasonProbeOfString (s: string) =
            let x = if isNull s then "" else s
            if x.Contains("cross_kind_active_replay_driver", StringComparison.Ordinal) then
                ParentReplayPoisonReasonCrossKindActiveReplayDriver
            elif x.Contains("parent_replay_status_preserved_repeat", StringComparison.Ordinal) then
                ParentReplayPoisonReasonStatusPreservedRepeat
            else
                ParentReplayPoisonReasonOther x

        let private parentReplayPoisonReasonProbeText = function
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver -> "cross_kind_active_replay_driver"
            | ParentReplayPoisonReasonStatusPreservedRepeat -> "parent_replay_status_preserved_repeat"
            | ParentReplayPoisonReasonOther x -> if System.String.IsNullOrWhiteSpace x then "none" else x

        let private parentReplayPoisonReasonProbeIsCrossKindActive = function
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver -> true
            | ParentReplayPoisonReasonStatusPreservedRepeat
            | ParentReplayPoisonReasonOther _ -> false

        let private parentReplayPoisonReasonProbeIsStatusPreservedRepeat = function
            | ParentReplayPoisonReasonStatusPreservedRepeat -> true
            | ParentReplayPoisonReasonCrossKindActiveReplayDriver
            | ParentReplayPoisonReasonOther _ -> false

        // ALPHA1397: keep op replay exception reason matching typed as well;
        // raw reason strings enter once at the boundary and downstream policy
        // consumes the DU, preventing more Contains branches around terminal pins.
        type OpReplayDriverExceptionReasonId =
            | OpReplayDriverExceptionNull
            | OpReplayDriverExceptionOther of string

        let private opReplayDriverExceptionReasonOfString (s: string) =
            let x = if isNull s then "" else s
            if x.Contains("op_replay_driver_null", StringComparison.Ordinal) then
                OpReplayDriverExceptionNull
            else
                OpReplayDriverExceptionOther x

        let private opReplayDriverExceptionReasonText = function
            | OpReplayDriverExceptionNull -> "op_replay_driver_null"
            | OpReplayDriverExceptionOther x -> if System.String.IsNullOrWhiteSpace x then "none" else x

        let private opReplayDriverExceptionReasonIsNull = function
            | OpReplayDriverExceptionNull -> true
            | OpReplayDriverExceptionOther _ -> false

        type ParentReplayPoisonPinSuppressionDecisionId =
            | ParentReplayPoisonPinSurface
            | ParentReplayPoisonPinSuppressWithPendingWitness
            | ParentReplayPoisonPinDeferLiveQueuePendingZero
            | ParentReplayPoisonPinHardSurfacePendingZero
            | ParentReplayPoisonPinDeferFreshRootLiveTail
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
            | ParentReplayPoisonPinForceSurfaceObligationCap
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness

        let private parentReplayPoisonPinSuppressionDecisionText = function
            | ParentReplayPoisonPinSurface -> "surface"
            | ParentReplayPoisonPinSuppressWithPendingWitness -> "suppress_with_pending_witness"
            | ParentReplayPoisonPinDeferLiveQueuePendingZero -> "defer_live_queue_pending_zero"
            | ParentReplayPoisonPinHardSurfacePendingZero -> "hard_surface_pending_zero"
            | ParentReplayPoisonPinDeferFreshRootLiveTail -> "defer_fresh_root_live_tail"
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail -> "defer_hard_obligation_fresh_pending_tail"
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail -> "defer_hard_obligation_stale_pending_live_tail"
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail -> "defer_jp_stall_pending_active_tail"
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride -> "defer_cycle_break_poison_live_tail_override"
            | ParentReplayPoisonPinForceSurfaceObligationCap -> "require_hard_obligation_cap_terminal"
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness -> "force_surface_stale_pending_witness"
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> "force_surface_hot_pending_witness"

        let private parentReplayPoisonPinSuppressionDecisionFor isParentReplayPoison liveness replayRootWriteWitnessFreshForPin capBreachForceSurface stalePendingWitnessForceSurface hotPendingWitnessForceSurface freshPendingTailHardObligationDefer stalePendingTailHardObligationDefer jpStallPendingActiveTailDefer cycleBreakPoisonLiveTailOverride =
            if not isParentReplayPoison then ParentReplayPoisonPinSurface
            elif cycleBreakPoisonLiveTailOverride then ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
            elif hotPendingWitnessForceSurface && not jpStallPendingActiveTailDefer then ParentReplayPoisonPinForceSurfaceHotPendingWitness
            elif jpStallPendingActiveTailDefer then ParentReplayPoisonPinDeferJpStallPendingActiveTail
            elif capBreachForceSurface && freshPendingTailHardObligationDefer then ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            elif capBreachForceSurface && stalePendingTailHardObligationDefer then ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            elif capBreachForceSurface then ParentReplayPoisonPinForceSurfaceObligationCap
            elif stalePendingWitnessForceSurface then ParentReplayPoisonPinForceSurfaceStalePendingWitness
            elif replayRootWriteWitnessFreshForPin then
                match liveness with
                | ParentReplayPoisonLiveQueueOrDriver
                | ParentReplayPoisonPendingWitness
                | ParentReplayPoisonRecentProgressOnly -> ParentReplayPoisonPinDeferFreshRootLiveTail
                | ParentReplayPoisonNoLiveTail -> ParentReplayPoisonPinSurface
            else
                match liveness with
                | ParentReplayPoisonLiveQueueOrDriver -> ParentReplayPoisonPinDeferLiveQueuePendingZero
                | ParentReplayPoisonPendingWitness -> ParentReplayPoisonPinSuppressWithPendingWitness
                | ParentReplayPoisonRecentProgressOnly -> ParentReplayPoisonPinHardSurfacePendingZero
                | ParentReplayPoisonNoLiveTail -> ParentReplayPoisonPinSurface

        let private parentReplayPoisonPinSuppressionDecisionSuppresses = function
            | ParentReplayPoisonPinSuppressWithPendingWitness
            | ParentReplayPoisonPinDeferLiveQueuePendingZero
            | ParentReplayPoisonPinDeferFreshRootLiveTail
            | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
            | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
            | ParentReplayPoisonPinDeferJpStallPendingActiveTail
            | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride -> true
            | ParentReplayPoisonPinSurface
            | ParentReplayPoisonPinHardSurfacePendingZero
            | ParentReplayPoisonPinForceSurfaceObligationCap
            | ParentReplayPoisonPinForceSurfaceStalePendingWitness
            | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> false

        // ALPHA1410: collapse the pending-zero parent-replay cascade authority into a DU.
        // Earlier alphas accumulated this as a large boolean OR, which made it too easy
        // to add another string/flag-only exception without updating telemetry.
        type ParentReplayPendingZeroCascadeAuthorityId =
            | ParentReplayPendingZeroCascadeNotPendingZero
            | ParentReplayPendingZeroCascadeDeferLiveTail
            | ParentReplayPendingZeroCascadeHardCapReceipt
            | ParentReplayPendingZeroCascadeStalePendingWitness
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero

        let private parentReplayPendingZeroCascadeAuthorityText = function
            | ParentReplayPendingZeroCascadeNotPendingZero -> "not_pending_zero"
            | ParentReplayPendingZeroCascadeDeferLiveTail -> "defer_live_tail"
            | ParentReplayPendingZeroCascadeHardCapReceipt -> "hard_cap_receipt"
            | ParentReplayPendingZeroCascadeStalePendingWitness -> "stale_pending_witness"
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap -> "suppression_force_surface_obligation_cap"
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness -> "suppression_force_surface_stale_witness"
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero -> "suppression_hard_surface_pending_zero"

        let private parentReplayPendingZeroCascadeAuthorityAllowsCascade = function
            | ParentReplayPendingZeroCascadeHardCapReceipt
            | ParentReplayPendingZeroCascadeStalePendingWitness
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
            | ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
            | ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero -> true
            | ParentReplayPendingZeroCascadeNotPendingZero
            | ParentReplayPendingZeroCascadeDeferLiveTail -> false

        let private parentReplayPendingZeroCascadeAuthorityFor pending hardCapReceiptCount stalePendingWitnessForceSurface pinSuppressionDecision =
            if pending <> 0 then ParentReplayPendingZeroCascadeNotPendingZero
            elif hardCapReceiptCount > 0 then ParentReplayPendingZeroCascadeHardCapReceipt
            elif stalePendingWitnessForceSurface then ParentReplayPendingZeroCascadeStalePendingWitness
            else
                match pinSuppressionDecision with
                | ParentReplayPoisonPinForceSurfaceObligationCap -> ParentReplayPendingZeroCascadeSuppressionForceSurfaceObligationCap
                | ParentReplayPoisonPinForceSurfaceStalePendingWitness -> ParentReplayPendingZeroCascadeSuppressionForceSurfaceStaleWitness
                | ParentReplayPoisonPinHardSurfacePendingZero -> ParentReplayPendingZeroCascadeSuppressionHardSurfacePendingZero
                | ParentReplayPoisonPinSurface
                | ParentReplayPoisonPinSuppressWithPendingWitness
                | ParentReplayPoisonPinDeferLiveQueuePendingZero
                | ParentReplayPoisonPinDeferFreshRootLiveTail
                | ParentReplayPoisonPinDeferHardObligationFreshPendingTail
                | ParentReplayPoisonPinDeferHardObligationStalePendingLiveTail
                | ParentReplayPoisonPinDeferJpStallPendingActiveTail
                | ParentReplayPoisonPinDeferCycleBreakLiveTailOverride
                | ParentReplayPoisonPinForceSurfaceHotPendingWitness -> ParentReplayPendingZeroCascadeDeferLiveTail

        let private pinTerminalContractLocked (event: string) (frame: Frame) =
            let isCurrentRootCompleteSite =
                frameOrCellIsRootComplete frame
            let pendingForTerminalPin =
                let mutable n = 0
                let seen = System.Collections.Generic.HashSet<string>()
                let add (opt: Frame option) =
                    match opt with
                    | Some frame ->
                        let k = frame.kind + "|" + frame.key + "|" + frame.site
                        if seen.Add k then n <- n + 1
                    | None -> ()
                add frontier
                add frontierTerm
                add frontierTy
                n
            let drainStateForTerminalPin = replayDrainStateLocked()
            let terminalPinLivenessGate = terminalPinLivenessGateOfState drainStateForTerminalPin (progressYieldCount > 0)
            let terminalPinHasLiveReplay = terminalPinLivenessGateHasLiveReplay terminalPinLivenessGate
            let terminalPinHasWitnessQueue = terminalPinLivenessGateHasWitnessQueue terminalPinLivenessGate
            let replayRootWriteWitnessFreshForPin =
                let frontierComplete =
                    match frontier with
                    | Some frame when frameOrCellIsRootComplete frame -> true
                    | Some _ -> false
                    | None -> false
                if frontierComplete then true
                else
                    let noLiveReplay =
                        pendingForTerminalPin = 0
                        && replayQueue.Length = 0
                        && replayDriverActiveDepth = 0
                    let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                    noLiveReplay
                    && replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                    && ageMs >= 0.0
                    && ageMs <= replayRootCompleteWitnessWindowMs
            let replayRootWriteWitnessSummaryForPin =
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then "none"
                else sprintf "%s age_ms=%.0f" replayRootCompleteWitnessSummary ((System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds)
            let suppressAppRootStaleRetargetPin =
                frameSemanticStatusIs SemanticRootCompleteStaleRetargetRepeatBlocked frame
                && isCurrentRootCompleteSite
                && stableRootCompleteCount > 0
                && (match frame.semanticCell with
                    | Some cell -> cell.shape = "TRecord"
                    | None -> frame.key.Contains("#"))
            let suppressAppRootParentCyclePin =
                frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                && isCurrentRootCompleteSite
                && (stableRootCompleteCount > 0 || replayRootWriteWitnessFreshForPin)
                && pendingForTerminalPin <= 2
                && replayRootWriteWitnessFreshForPin
            let suppressSyntheticChildScheduleRepeatPin =
                frameSemanticStatusIs SemanticReplayChildScheduleRepeatBlocked frame
                && pendingForTerminalPin > 0
                && replayRootWriteWitnessFreshForPin
                && (frame.site.EndsWith(":0", StringComparison.Ordinal)
                    || frame.key.Contains(":0", StringComparison.Ordinal)
                    || (match frame.semanticCell with
                        | Some cell -> cell.site.EndsWith(":0", StringComparison.Ordinal)
                        | None -> false))
            let suppressLiveReplayParentCyclePin =
                frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayAppRootBase16HardcapPin =
                frameSemanticStatusIs SemanticAppRootBase16StaleRetargetHardcapBlocked frame
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayChildScheduleRepeatPin =
                isSemanticReplayChildScheduleRepeatBlockedStatusId (semanticStatusOfString frame.status)
                && pendingForTerminalPin > 0
                && terminalPinHasLiveReplay
            let suppressLiveReplayRecordWithValuePin =
                match semanticStatusOfString frame.status with
                | SemanticRecordWithValueBlocked ->
                    pendingForTerminalPin > 0
                    && terminalPinHasLiveReplay
                | _ -> false
            let suppressLiveReplayOpImplRequiredPin =
                match semanticStatusOfString frame.status with
                | SemanticOpImplRequiredBlocked ->
                    match liveReplayTerminalPolicyOfSemanticStatusId SemanticOpImplRequiredBlocked with
                    | DeferTerminalWhileLiveReplay ->
                        pendingForTerminalPin > 0
                        && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayRootWriteWitnessFreshForPin)
                    | SurfaceTerminalDuringLiveReplay
                    | TerminalNotLiveReplayPolicy -> false
                | _ -> false
            let opReplayDriverExceptionReasonId =
                opReplayDriverExceptionReasonOfString frame.reason
            let suppressLiveReplayOpReplayDriverExceptionPin =
                frameSemanticStatusIs SemanticReplayDriverExceptionBlocked frame
                && pendingForTerminalPin > 0
                && (terminalPinHasLiveReplay || replayRootWriteWitnessFreshForPin)
                && (opReplayDriverExceptionReasonIsNull opReplayDriverExceptionReasonId
                    || (match frame.semanticCell with
                        | Some cell -> cell.kind = "term" && cell.shape = "EOp"
                        | None -> false))
            let terminalPinHopacOverridePierceSidecarP0 =
                (frameSemanticStatusIs SemanticMissingAfterPrefetchBlocked frame
                 || frame.status.IndexOf("missing_after_prefetch", StringComparison.Ordinal) >= 0
                 || frame.reason.IndexOf("missing_after_prefetch", StringComparison.Ordinal) >= 0
                 || frame.reason.IndexOf("prefetch", StringComparison.Ordinal) >= 0)
                && pendingForTerminalPin <= 0
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (DiagJson.snapshotKindCount "eval_worklist_stack_fence_prefetch_ledger_audit" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_live_replay_missing_after_prefetch_pin_suppressed" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_pending_ledger_reconciled_from_frontier_snapshot" > 0)
            let suppressLiveReplayMissingAfterPrefetchPin =
                frameSemanticStatusIs SemanticMissingAfterPrefetchBlocked frame
                && not terminalPinHopacOverridePierceSidecarP0
                && (pendingForTerminalPin > 0
                    || replayQueue.Length >= 16
                    || replayDriverActiveDepth > 0
                    || replayRootWriteWitnessFreshForPin
                    || isCurrentRootCompleteSite)
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0 || replayRootWriteWitnessFreshForPin || isCurrentRootCompleteSite)
            let parentReplayPoisonLivenessId =
                parentReplayPoisonLivenessFor terminalPinHasLiveReplay pendingForTerminalPin progressYieldCount
            let parentReplayPoisonHardCapReceiptCount =
                DiagJson.snapshotKindCount "eval_worklist_cross_kind_yield_thrash_hard_poison"
                + DiagJson.snapshotKindCount "eval_worklist_replay_obligation_post_schedule_cap_hard_poison"
            let parentReplayPoisonSuppressedPinCount =
                DiagJson.snapshotKindCount "eval_worklist_live_replay_parent_replay_poison_pin_suppressed"
            let parentReplayPoisonPreservedRepeatCount =
                parentReplayPreservedCountForFrame frame
            let parentReplayPoisonWitnessAgeMs =
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then -1.0
                else (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
            let parentReplayPoisonReasonProbeId =
                parentReplayPoisonReasonProbeOfString frame.reason
            let parentReplayPoisonReasonProbe =
                parentReplayPoisonReasonProbeText parentReplayPoisonReasonProbeId
            let parentReplayPoisonPhysicalLiveTail =
                terminalPinHasLiveReplay
                || terminalPinHasWitnessQueue
                || replayQueue.Length > 0
                || replayDriverActiveDepth > 0
            let parentReplayPoisonRepeatCapFreshRootWitnessGuard =
                // ALPHA1395: alpha1394 proved the no-root probation drain can be correct
                // but arrive too late: parent poison pin/cascade may fire first while a
                // fresh root witness and runnable sibling tail still exist.  Guard only
                // the young repeat-cap case; hard-cap receipts and stale witnesses keep
                // their terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin = 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && parentReplayPoisonPreservedRepeatCount > parent_replay_preserved_repeat_cap
                && parentReplayPoisonWitnessAgeMs >= 0.0
                && parentReplayPoisonWitnessAgeMs <= 5000.0
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0 || terminalPinHasLiveReplay || terminalPinHasWitnessQueue)
                && not isCurrentRootCompleteSite
                && (not replayRootWriteWitnessFreshForPin || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId || parentReplayPoisonHardCapReceiptCount > 0)
            let parentReplayPoisonStalePendingWitnessForceSurface =
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && not replayRootWriteWitnessFreshForPin
                && (progressYieldCount >= 1024
                    || parentReplayPoisonSuppressedPinCount >= 4
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonHardCapReceiptCount > 0)
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && (parentReplayPoisonWitnessAgeMs < 0.0
                    || parentReplayPoisonWitnessAgeMs >= 1500.0
                    || parentReplayPoisonSuppressedPinCount >= 8
                    || parentReplayPoisonPreservedRepeatCount >= 7)
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonSuppressedPinCount >= 2
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || progressYieldCount >= 32768
                    || replayQueue.Length <= 64
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || (parentReplayPoisonWitnessAgeMs >= 12000.0 && replayQueue.Length <= 8 && replayDriverActiveDepth <= 0))
            let parentReplayPoisonStalePendingWitnessCap =
                parentReplayPoisonStalePendingWitnessForceSurface
            let parentReplayPoisonPendingZeroLiveTailForceSurface =
                // ALPHA1374: alpha1373 showed pending=0 parent replay poison could still be
                // suppressed by the live-queue shield while the HUD already had same_hot=5,
                // hard_poison_obligation_cap and q/a/p=150/4/0.  Once pending is zero,
                // cross-kind live-tail churn is scheduler tail, not semantic authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin = 0
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && not replayRootWriteWitnessFreshForPin
                && (replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || ((parentReplayPoisonWitnessAgeMs < 0.0 || parentReplayPoisonWitnessAgeMs >= 12000.0)
                        && replayQueue.Length <= 8
                        && replayDriverActiveDepth <= 0))
                && (parentReplayPoisonSuppressedPinCount > 0
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || progressYieldCount >= 1024
                    || replayQueue.Length >= 32
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
            let parentReplayPoisonSmallPendingLiveTailForceSurface =
                // ALPHA1375: alpha1374 ended with p=2 while repeated hard-poison
                // receipts and small q/a live-tail churn kept the pinned dynamic/root
                // terminal wrapped as EJP0011.  A tiny pending witness is not authority
                // after hard-cap/cross-kind evidence has already told us to surface.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && pendingForTerminalPin <= 2
                && not replayRootWriteWitnessFreshForPin
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && (replayQueue.Length <= 64
                    || progressYieldCount >= 512
                    || parentReplayPoisonSuppressedPinCount >= 4
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonHardCapReceiptCount > 0)
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonSuppressedPinCount >= 2
                    || parentReplayPoisonPreservedRepeatCount >= 4
                    || parentReplayPoisonWitnessAgeMs >= 1500.0
                    || parentReplayPoisonReasonProbeIsCrossKindActive parentReplayPoisonReasonProbeId)
            let parentReplayPoisonHotPendingWitnessForceSurface =
                // ALPHA1385: alpha1384 exposed the new suppress shape:
                // repeat=1, pending=1, q=4/a=4, fresh dynamic-join witness, but
                // progress_yield_pending was already hundreds and the terminal
                // still surfaced as EJP0021 immediately after.  A tiny hot witness
                // is scheduler tail once parent-preserved replay has already pinned
                // rank-83 poison.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && pendingForTerminalPin <= 2
                && replayRootWriteWitnessFreshForPin
                && (terminalPinHasLiveReplay || terminalPinHasWitnessQueue || replayQueue.Length > 0 || replayDriverActiveDepth > 0)
                && replayQueue.Length <= 8
                && replayDriverActiveDepth <= 4
                && progressYieldCount >= 512
                && (parentReplayPoisonReasonProbeIsStatusPreservedRepeat parentReplayPoisonReasonProbeId
                    || parentReplayPoisonPreservedRepeatCount > 0
                    || parentReplayPoisonSuppressedPinCount > 0)
            let parentReplayPoisonJpStallPendingActiveTailDefer =
                // ALPHA1431: runtime 1430 emitted an EJP0014 jp_ivar_wait stall and immediately
                // selected rank83 parent replay poison while q/a/p stayed live. A terminal-flood or
                // hard-cap receipt is not enough authority to surface while the typed JP retry gate
                // has fresh evidence and pending+active replay still exists.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && pendingForTerminalPin > 0
                && replayDriverActiveDepth > 0
                && (replayQueue.Length <= 64 || progressYieldCount > 0)
                && not replayRootWriteWitnessFreshForPin
                && parentReplayPoisonHardCapReceiptCount > 0
                && (DiagJson.snapshotKindCount "eval_worklist_jp_stall_pinned_terminal_live_replay_retry" > 0
                    || DiagJson.snapshotKindCount "eval_worklist_jp_stall_strong_terminal_candidate" > 0)
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0)
            let parentReplayPoisonCapBreachForceSurface =
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && not parentReplayPoisonRepeatCapFreshRootWitnessGuard
                && (parentReplayPoisonHardCapReceiptCount > 0
                    || parentReplayPoisonPendingZeroLiveTailForceSurface
                    || parentReplayPoisonSmallPendingLiveTailForceSurface
                    || parentReplayPoisonHotPendingWitnessForceSurface)
            let parentReplayPoisonFreshPendingTailHardObligationDefer =
                // ALPHA1415: alpha1414 showed a hard-obligation cap inferred only
                // from cross-kind same-hot churn while pending/root evidence was live:
                // p=2, q=17/a=1, root_age=0, hard_cap_receipts=0.  That is a
                // probation/drain authority, not terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && parentReplayPoisonCapBreachForceSurface
                && pendingForTerminalPin > 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && (replayRootWriteWitnessFreshForPin
                    || isCurrentRootCompleteSite
                    || (parentReplayPoisonWitnessAgeMs >= 0.0 && parentReplayPoisonWitnessAgeMs <= 5000.0))
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount > 0)
            let parentReplayPoisonStalePendingTailHardObligationDefer =
                // ALPHA1419: alpha1418 hit trace.spi:121 with pending=2, q/a=7/2, progress_yield_pending=35,
                // witness_age_ms=5798, parent_repeat_count=1 and hard_cap_receipts=0. The old cap-breach path
                // treated this as require_hard_obligation_cap_terminal only because the witness was slightly
                // older than the 5s fresh-root window. This is still a bounded live pending tail, not macro terminal authority.
                frameSemanticStatusIs SemanticParentReplayCycleBreakPoisoned frame
                && parentReplayPoisonCapBreachForceSurface
                && pendingForTerminalPin > 0
                && parentReplayPoisonHardCapReceiptCount = 0
                && not replayRootWriteWitnessFreshForPin
                && not isCurrentRootCompleteSite
                && parentReplayPoisonWitnessAgeMs >= 0.0
                && parentReplayPoisonWitnessAgeMs <= 12000.0
                && parentReplayPoisonPreservedRepeatCount < 4
                && parentReplayPoisonSuppressedPinCount = 0
                && (terminalPinHasLiveReplay
                    || terminalPinHasWitnessQueue
                    || replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount > 0)
                && (replayQueue.Length > 0
                    || replayDriverActiveDepth > 0
                    || progressYieldCount >= 4)
            let parentReplayPoisonCycleBreakLiveTailOverride =
