                            sprintf "{\"kind\":\"eval_worklist_terminal_frontier_pin_snapshot\",\"event\":%s,\"status\":%s,\"rank\":%d,\"prior_rank\":%d,\"durable_prior_rank\":%d,\"kind2\":%s,\"shape_or_key_kind\":%s,\"site\":%s,\"key\":%s,\"reason\":%s,\"cursor\":%d,\"depth\":%d,\"trace_len\":%d,\"semantic_payload_present\":%b,\"semantic_cell_present\":%b,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"source_value_stores\":%d,\"root_progress_marks\":%d,\"dynamic_key_bridge_count\":%d,\"dynamic_join_blocked_count\":%d,\"parent_poison_injected_count\":%d,\"terminal_contract_pinned_count_before\":%d,\"worker_decision_du\":%s,\"hud_frontier_yield_path_du\":\"topologically_inaccessible_after_native_inline_callback\",\"qap\":\"%d/%d/%d\",\"policy\":\"terminal_frontier_receipt_only_after_typed_proof_tuple\",\"single_flight\":1,\"next\":%s%s}"
                                (esc event) (esc frame.status) rank priorRank durablePriorRank (esc frame.kind) (esc frame.key) (esc frame.site) (esc frame.key) (esc frame.reason) frame.cursor frame.depth (List.length frame.trace) (Option.isSome frame.semanticPayload) (Option.isSome frame.semanticCell) pinPending pinQueue pinActive pinSourceValueStores pinRootProgress pinDynamicKeyBridge pinDynamicJoinBlocked pinParentPoisonInjected pinTerminalPinnedCount (esc pinWorkerDecision) pinPending pinQueue pinActive (esc pinNextAction) pinProofTupleJson)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_terminal_contract_pinned\",\"event\":%s,\"status\":%s,\"rank\":%d,\"prior_rank\":%d,\"site\":%s,\"key\":%s,\"log_completeness\":%s,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc frame.status) rank priorRank (esc frame.site) (esc frame.key) (esc (logCompletenessPolicyText activeLogCompletenessPolicy)) (esc (terminalContractNext frame.status)))

        let private pinTerminalContract (event: string) (frame: Frame) =
            lock gate (fun () -> pinTerminalContractLocked event frame)

        let pinSemanticTerminalContract (event: string) (kind: string) (status: string) (key: string) (site: string) (depth: int) (re: int) (maxRe: int) (reason: string) =
            // ALPHA1001: DU seam for terminal evidence that is emitted outside a
            // ReplayCell.  Runtime 1000 showed the global-fuse terminal was logged
            // as text but never pinned, so retargetGlobalFuseAbortMessage had no
            // durable frame to select.  This wrapper preserves the old string field
            // at the record boundary while routing policy through SemanticStatusId.
            let statusId = semanticStatusOfString status
            match semanticTerminalContract statusId with
            | Some contract ->
                let frame =
                    { kind = kind
                      key = key
                      site = site
                      depth = depth
                      re = re
                      maxRe = maxRe
                      trace = []
                      reason = reason
                      status = semanticStatusToString statusId
                      cursor = 32
                      semanticPayload = Some reason
                      semanticCell = None }
                pinTerminalContract event frame
                let liveReplayPolicy =
                    match liveReplayTerminalPolicyOfSemanticStatusId statusId with
                    | DeferTerminalWhileLiveReplay -> "defer_terminal_while_live_replay"
                    | SurfaceTerminalDuringLiveReplay -> "surface_terminal_during_live_replay"
                    | TerminalNotLiveReplayPolicy -> "terminal_not_live_replay_policy"
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_terminal_contract_pinned_from_status\",\"event\":%s,\"status\":%s,\"rank\":%d,\"kind2\":%s,\"site\":%s,\"key\":%s,\"reason\":%s,\"live_replay_policy\":%s,\"log_completeness\":%s,\"single_flight\":1,\"next\":%s}"
                        (esc event) (esc frame.status) contract.rank (esc kind) (esc site) (esc key) (esc reason) (esc liveReplayPolicy) (esc (logCompletenessPolicyText activeLogCompletenessPolicy)) (esc contract.next))
            | None -> ()

        let tryPinnedTerminalContract () =
            lock gate (fun () -> pinnedTerminalContract)

        let tryDurableTerminalContract () =
            lock gate (fun () -> durableTerminalContract)

        let pinCodegenJpBodyDictMissing (event: string) (jpKind: string) (bodyName: string) (keyText: string) (dictCount: int) (message: string) =
            // ALPHA940: alpha939 reached F# codegen and failed on a real missing JP
            // body dictionary after the explicit replay machinery had proven root-complete
            // evidence.  Make the codegen blocker visible to the same terminal-contract
            // machinery instead of leaving only a raw CODEGEN error line.
            // This function records evidence only; it does not create a body dictionary,
            // placeholder, writer artifact, replay-root proof or BuildOk.
            lock gate (fun () ->
                let statusId = SemanticCodegenJpBodyDictMissingBlocked
                let status = semanticStatusToString statusId
                let jpKindId = codegenJpKindOfString jpKind
                let jpKindText = codegenJpKindToString jpKindId
                let site = sprintf "codegen@%s:%s" jpKindText bodyName
                let key = sprintf "%s:%s:%s" jpKindText bodyName keyText
                let payload = sprintf "semantic_codegen_payload(kind=%s,body=%s,key=%s,dict=%d,message=%s)" jpKindText bodyName keyText dictCount message
                let frame =
                    { kind = "codegen"
                      key = key
                      site = site
                      depth = 0
                      re = 0
                      maxRe = 0
                      trace = []
                      reason = "codegen_jp_body_dict_missing"
                      status = status
                      cursor = 0
                      semanticPayload = Some payload
                      semanticCell = None }
                pinTerminalContractLocked event frame
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_codegen_jp_body_dict_missing_terminal_pinned\",\"event\":%s,\"jp_kind\":%s,\"body\":%s,\"key\":%s,\"dict\":%d,\"status\":%s,\"rank\":%d,\"single_flight\":1,\"next\":%s}"
                        (esc event) (esc jpKind) (esc bodyName) (esc keyText) dictCount (esc status) (terminalContractRank status) (esc (terminalContractNext status))))

        let resetDurableTerminalContractLedger () =
            lock gate (fun () -> durableTerminalContract <- None)

        let clearTerminalContractIf (status: string) (site: string) (key: string) =
            lock gate (fun () ->
                let matches (frame: Frame) =
                    frame.status = status
                    && (System.String.IsNullOrEmpty(site) || frame.site = site)
                    && (System.String.IsNullOrEmpty(key) || frame.key = key)
                let pinnedCleared =
                    match pinnedTerminalContract with
                    | Some frame when matches frame ->
                        pinnedTerminalContract <- None
                        true
                    | _ -> false
                let durableCleared =
                    match durableTerminalContract with
                    | Some frame when matches frame ->
                        durableTerminalContract <- None
                        true
                    | _ -> false
                pinnedCleared || durableCleared)


        let private compactTrace (tr: Trace) : Trace =
            let head = 16
            let tail = 16
            let n = tr.Length
            if n <= head + tail + 1 then tr
            else (tr |> List.truncate head) @ (tr |> List.rev |> List.truncate tail |> List.rev)

        let private kindFromSite (site: string) =
            if String.IsNullOrWhiteSpace site then "unknown"
            elif site.StartsWith("term@", StringComparison.Ordinal) then "term"
            elif site.StartsWith("ty@", StringComparison.Ordinal) then "ty"
            else "unknown"

        let private sameCycle (a: Frame) (b: Frame) =
            a.kind = b.kind && a.key = b.key && a.site = b.site

        // ALPHA859: keep retry-drain diagnostics in lexical order.
        // Alpha858 added cross-kind terminal telemetry above the old pendingCount
        // binding; F# does not forward-declare local lets, so pendingCount must be
        // available before those helpers call it.
        let pendingCount () =
            lock gate (fun () ->
                let mutable n = 0
                let seen = System.Collections.Generic.HashSet<string>()
                let add (opt: Frame option) =
                    match opt with
                    | Some frame ->
                        let k = frame.kind + "|" + frame.key + "|" + frame.site
                        if seen.Add k then n <- n + 1
                    | None -> ()
                add frontier
                add frontierTerm
                add frontierTy
                n)

        type ParentContinuationPhase2TransitionDecisionId =
            | ParentContinuationPhase2NotCandidate
            | ParentContinuationPhase2SweepAndBridge
            | ParentContinuationPhase2NoDeferredHolesBridge

        let private parentContinuationPhase2TransitionDecisionText = function
            | ParentContinuationPhase2NotCandidate -> "not_candidate"
            | ParentContinuationPhase2SweepAndBridge -> "sweep_and_bridge"
            | ParentContinuationPhase2NoDeferredHolesBridge -> "no_deferred_holes_bridge"

        type ParentContinuationPhase2CandidateReasonId =
            | ParentContinuationPhase2Rejected
            | ParentContinuationPhase2DeferredChildIdleRootWitness
            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness

        let private parentContinuationPhase2CandidateReasonText = function
            | ParentContinuationPhase2Rejected -> "rejected"
            | ParentContinuationPhase2DeferredChildIdleRootWitness -> "deferred_child_idle_root_witness"
            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness -> "parent_replay_cycle_break_idle_root_witness"
            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness -> "deferred_type_var_cycle_break_idle_root_witness"

        type ParentContinuationPhase2IdleSnapshotId =
            | ParentContinuationPhase2IdleSnapshotNotReady
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness

        let private parentContinuationPhase2IdleSnapshotText = function
            | ParentContinuationPhase2IdleSnapshotNotReady -> "not_ready"
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness -> "queue_drained_active_parked_root_witness"

        type ParentContinuationPhase2BridgeMutationId =
            | ParentContinuationPhase2BridgeRootWitnessRecorded

        let private parentContinuationPhase2BridgeMutationText = function
            | ParentContinuationPhase2BridgeRootWitnessRecorded -> "root_witness_recorded"

        let private parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth =
            // ALPHA1308: alpha1307 reached queue-drained / write-witness tails after the
            // pair NRE seam was gone.  Keep active=0 strict, but allow the final tiny queue
            // window to be observed by the Phase 2 bridge instead of falling back to rescues.
            if pending > 0 && pending <= 3 && queueDepth <= 16 && activeDepth = 0 then
                ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness
            else
                ParentContinuationPhase2IdleSnapshotNotReady

        type PairValueExceptionHandoffDecisionId =
            | PairValueExceptionNotCandidate
            | PairValueExceptionDrainGrace
            | PairValueExceptionExplicitHandoffReady

        let pairValueExceptionHandoffDecisionText = function
            | PairValueExceptionNotCandidate -> "not_candidate"
            | PairValueExceptionDrainGrace -> "drain_grace"
            | PairValueExceptionExplicitHandoffReady -> "explicit_handoff_ready"

        let pairValueExceptionHandoffDecisionShouldHandoff = function
            | PairValueExceptionExplicitHandoffReady -> true
            | _ -> false

        let pairValueExceptionHandoffDecisionFor (status: string) (reasonText: string) rank pending queueDepth activeDepth terminalAge =
            let st = if isNull status then "" else status
            let reasonText = if isNull reasonText then "" else reasonText
            let isPairValueNre =
                st = "semantic_pair_value_blocked"
                && rank >= 80
                && (reasonText.Contains("NullReferenceException", StringComparison.Ordinal)
                    || reasonText.Contains("Object reference not set", StringComparison.Ordinal))
            if not isPairValueNre then PairValueExceptionNotCandidate
            elif terminalAge < 1500 && (pending > 0 || queueDepth > 0 || activeDepth > 0) then PairValueExceptionDrainGrace
            else PairValueExceptionExplicitHandoffReady

        let private parentContinuationPhase2CandidateReasonFor (status: string) (reasonText: string) pending queueDepth activeDepth =
            let idleId = parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth
            match idleId with
            | ParentContinuationPhase2IdleSnapshotNotReady -> ParentContinuationPhase2Rejected
            | ParentContinuationPhase2IdleSnapshotQueueDrainedActiveParkedRootWitness ->
                let deferredChild =
                    reasonText.Contains("deferred_child_cell", StringComparison.Ordinal)
                    || reasonText.Contains("parent_continuation_cycle", StringComparison.Ordinal)
                let parentReplayCycle =
                    status = "semantic_parent_replay_cycle_break_poisoned"
                    || status = "semantic_parent_replay_status_preserved_repeat_blocked"
                let parentReplayReason =
                    reasonText.Contains("parent_replay_status_preserved_repeat", StringComparison.Ordinal)
                    || reasonText.Contains("parent_continuation_ready", StringComparison.Ordinal)
                    || reasonText.Contains("cycle_break_poison", StringComparison.Ordinal)
                let deferredTypeVarReason =
                    reasonText.Contains("deferred_type_var", StringComparison.Ordinal)
                    || reasonText.Contains("single_flight_busy_cross_kind_cycle_break", StringComparison.Ordinal)
                    || reasonText.Contains("pending_monomorphization", StringComparison.Ordinal)
                if status = "semantic_parent_continuation_cycle_deferred" && deferredChild then
                    ParentContinuationPhase2DeferredChildIdleRootWitness
                elif parentReplayCycle && parentReplayReason then
                    ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
                elif parentReplayCycle && deferredTypeVarReason then
                    ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness
                else
                    ParentContinuationPhase2Rejected

        let tryParentContinuationPhase2SynchronousTransition (event: string) (reason: string) : bool =
            // ALPHA1303: follow the v1302 assessment directly.  q/a/p=2/0/1,
            // active=0 and deferred_child_cell is interpreted as the Phase 1
            // completion signal, not as a generic no-work abort.  The transition is
            // explicit and diagnostic because it may be too aggressive; nevertheless
            // it is intentionally allowed by the user for this iteration.
            let candidate =
                lock gate (fun () ->
                    let pending =
                        let mutable n = 0
                        let seen = System.Collections.Generic.HashSet<string>()
                        let add (opt: Frame option) =
                            match opt with
                            | Some frame ->
                                let k = frame.kind + "|" + frame.key + "|" + frame.site
                                if seen.Add k then n <- n + 1
                            | None -> ()
                        add pinnedTerminalContract
                        add durableTerminalContract
                        add frontier
                        add frontierTerm
                        add frontierTy
                        n
                    let queueDepth = replayQueue.Length
                    let activeDepth = replayDriverActiveDepth
                    let pick (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let candidateReasonId =
                                parentContinuationPhase2CandidateReasonFor frame.status (frame.reason + ":" + reason) pending queueDepth activeDepth
                            let idleSnapshotId = parentContinuationPhase2IdleSnapshotFor pending queueDepth activeDepth
                            match candidateReasonId with
                            | ParentContinuationPhase2DeferredChildIdleRootWitness
                            | ParentContinuationPhase2ParentReplayCycleBreakIdleRootWitness
                            | ParentContinuationPhase2DeferredTypeVarCycleBreakIdleRootWitness ->
                                Some(frame, pending, queueDepth, activeDepth, candidateReasonId, idleSnapshotId)
                            | ParentContinuationPhase2Rejected -> None
                        | _ -> None
                    [ pinnedTerminalContract; durableTerminalContract; frontier; frontierTerm; frontierTy ]
                    |> List.tryPick pick)
            match candidate with
            | None -> false
            | Some(frame, pending, queueDepth, activeDepth, candidateReasonId, idleSnapshotId) ->
                let sweepReason = sprintf "%s:%s" reason frame.reason
                let patched = EvalReplayValueStore.tryPhase2SynchronousDeferredTypeVarSweep event sweepReason 4096
                let decisionId =
                    if patched > 0 then ParentContinuationPhase2SweepAndBridge
                    else ParentContinuationPhase2NoDeferredHolesBridge
                let bridgeMutationId = ParentContinuationPhase2BridgeRootWitnessRecorded
                lock gate (fun () ->
                    let completedCell =
                        frame.semanticCell
                        |> Option.map (fun cell -> { cell with status = "semantic_root_complete"; step = cell.step + 1 })
                    let completedFrame =
                        { frame with
                            status = "semantic_root_complete"
                            reason = sprintf "phase2_parent_continuation_deferred_child_cell_bridge:patched_holes=%d" patched
                            cursor = frame.cursor + 1
                            semanticPayload = Some(sprintf "phase2_parent_continuation_root_bridge:%s" frame.key)
                            semanticCell = completedCell }
                    frontier <- Some completedFrame
                    if frame.kind = "term" then frontierTerm <- Some completedFrame
                    elif frame.kind = "ty" then frontierTy <- Some completedFrame
                    pinnedTerminalContract <- None
                    durableTerminalContract <- None
                    replayRootCompleteWitnessUtc <- System.DateTime.UtcNow
                    replayRootCompleteWitnessSummary <-
                        sprintf "alpha1305 phase2 deferred-child bridge key=%s site=%s patched=%d" frame.key frame.site patched
                    progressYieldCount <- progressYieldCount + 1
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_phase2_parent_continuation_deferred_child_cell_root_witness_bridged\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"candidate_reason_du\":%s,\"idle_snapshot_du\":%s,\"bridge_mutation_du\":%s,\"status_before\":%s,\"status_after\":\"semantic_root_complete\",\"kind2\":%s,\"site\":%s,\"key\":%s,\"patched_holes\":%d,\"pending_snapshot\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"policy\":\"alpha1306_assessment_mandated_phase2_root_bridge_extended_to_parent_replay_cycle_break_experimental_may_break_no_silent_writer_codegen\",\"single_flight\":1,\"next\":\"root_complete_probe_or_codegen_transition\"}"
                            (DiagJson.esc event)
                            (DiagJson.esc sweepReason)
                            (DiagJson.esc (parentContinuationPhase2TransitionDecisionText decisionId))
                            (DiagJson.esc (parentContinuationPhase2CandidateReasonText candidateReasonId))
                            (DiagJson.esc (parentContinuationPhase2IdleSnapshotText idleSnapshotId))
                            (DiagJson.esc (parentContinuationPhase2BridgeMutationText bridgeMutationId))
                            (DiagJson.esc frame.status)
                            (DiagJson.esc frame.kind)
                            (DiagJson.esc frame.site)
                            (DiagJson.esc frame.key)
                            patched
                            pending
                            queueDepth
                            activeDepth)
                    true)

        let codegenJpBodyDictShouldDefer () =
            lock gate (fun () ->
                let liveFrame opt =
                    match opt with
                    | Some frame ->
                        let nonCodegen =
                            match evalKindOfString frame.kind with
                            | EvalCodegen -> false
                            | _ -> true
                        let liveStatus =
                            match frameStatusOfString frame.status with
                            | FrameSemanticRootComplete -> true
                            | statusId -> isLiveExplicitFrameStatusId statusId
                        nonCodegen && liveStatus
                    | None -> false
                liveFrame frontier
                || liveFrame frontierTerm
                || liveFrame frontierTy
                || replayQueue.Length > 0
                || replayDriverActiveDepth > 0
                || progressYieldCount > 0)

        // ALPHA858: terminal contracts are kind-local evidence.
        // Runtime 857 exposed a stale cross-kind selection bug: retry_stop_drain
        // had a live ty semantic_root_complete frontier at apps/spiral/spiral.spi:2670,
        // but preferred an older term semantic_replay_fingerprint_repeat_blocked
        // contract from trace.spi:121. Cross-kind pins remain evidence for their
        // own parked kind slot; they must not retarget the current global fuse.
        let private frameKindCompatible (requestedKind: string) (frame: Frame) =
            let rk = if System.String.IsNullOrWhiteSpace requestedKind then "unknown" else requestedKind
            rk = "unknown"
            || frame.kind = rk
            || frame.site.StartsWith(rk + "@", System.StringComparison.Ordinal)
            || frame.key.StartsWith(rk + ":", System.StringComparison.Ordinal)

        // ALPHA1040: cross-kind pinned terminals are useful once, but runtime 1039
        // emitted the same ignored pin more than a thousand times. Rate-limit by
        // requested-kind/pin/reason while preserving periodic receipts.
        let private crossKindPinnedTerminalIgnoredSeen = System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        let private emitCrossKindPinnedTerminalIgnored (event: string) (requestedKind: string) (pinned: Frame) (rank: int) (why: string) =
            let emitKey = sprintf "%s|%s|%s|%s|%s|%s" event requestedKind pinned.kind pinned.status pinned.key why
            let repeatCount = crossKindPinnedTerminalIgnoredSeen.AddOrUpdate(emitKey, 1, fun _ old -> old + 1)
            if repeatCount <= 3 || repeatCount = 8 || repeatCount = 32 || repeatCount % 256 = 0 then
                DiagJson.emit (
                    sprintf """{\"kind\":\"eval_worklist_cross_kind_pinned_terminal_ignored\",\"event\":%s,\"requested_kind\":%s,\"pinned_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"reason\":%s,\"repeat_count\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_kind_local_frontier\"}"""
                        (esc event) (esc requestedKind) (esc pinned.kind) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (esc why) repeatCount (pendingCount()))

        let private clearCurrentCrossKindPinnedTerminalLocked (pinned: Frame) =
            // Clear only the active terminal selector when it is exactly the stale
            // cross-kind frame we just rejected. This does not synthesize replay
            // value, root proof, writer output, codegen result, or BuildOk.
            match pinnedTerminalContract with
            | Some p when p.kind = pinned.kind && p.key = pinned.key && p.site = pinned.site && p.status = pinned.status ->
                pinnedTerminalContract <- None
                true
            | _ -> false

        // ALPHA464: same-node replay identity deliberately ignores site/env/cursor.
        // The alpha463 tail showed the same TJoinPoint' node reappearing through two
        // source sites while the scheduled_parent_replay payload still targeted that
        // node.  Treat this as self-poke churn, not a fresh child payload.
        let private sameReplayNode (a: ReplayCell) (b: ReplayCell) =
            a.kind = b.kind && a.shape = b.shape && a.nodeId = b.nodeId

        // ALPHA544: EJP0014 can be raised while other forced-sequential workers are
        // still converging on the real terminal contract.  Alpha543 showed a macro
        // thunk pin appearing shortly after a semantic_root_complete+pending-JP-body
        // deferral.  Wait briefly for an already-running worker to publish that pin
        // before the retry gate spends time on root-complete churn.  This is
        // diagnostic-only and fail-closed: it never marks replay complete, never
        // writes output, and only returns an existing high-rank terminal contract.
        let waitForPinnedTerminalContract (event: string) (tries: int) (sleepMs: int) =
            let maxTries = max 1 (min 256 tries)
            let delay = max 1 (min 50 sleepMs)
            match tryPinnedTerminalContract() with
            | Some pinned when terminalContractRank pinned.status >= 90 ->
                let rank = terminalContractRank pinned.status
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_wait_for_pinned_terminal_contract_observed\",\"event\":%s,\"status\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"remaining_tries\":0,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                        (esc event) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) (esc (terminalContractNext pinned.status)))
                Some pinned
            | _ ->
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_wait_for_pinned_terminal_contract_no_sync_wait\",\"event\":%s,\"tries_requested\":%d,\"sleep_ms_requested\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"schedule_or_continue_fail_closed\"}"
                        (esc event) maxTries delay (pendingCount()))
                None

        let private short (maxLen: int) (s: string) =
            // ALPHA1000: maxLen remains as call-site documentation only.  The
            // compiler log must preserve complete JSON/string payloads; report and
            // UI tools may summarize later, but the receipt itself must not lose
            // tail evidence.
            match activeLogCompletenessPolicy with
            | FullFidelityJsonl -> if Object.ReferenceEquals(s,null) then "" else s
            | TruncatedPreview _ ->
                if Object.ReferenceEquals(s,null) then ""
                elif maxLen <= 3 then s
                elif s.Length > maxLen then s.Substring(0, maxLen - 3) + "..."
                else s

        let private formatCellPayload (cell: ReplayCell) =
            sprintf "semantic_eval_payload(kind=%s,shape=%s,node_id=%d,env_term=%d/%d,env_type=%d/%d,seq_len=%d,cse_depth=%d,trace_depth=%d,site=%s,cursor=%d,step=%d,status=%s)"
                cell.kind cell.shape cell.nodeId cell.envGlobalTerm cell.envStackTerm cell.envGlobalType cell.envStackType cell.seqLen cell.cseDepth cell.traceDepth cell.site cell.cursor cell.step cell.status

        let private formatCell (cell: ReplayCell) =
            sprintf "semantic_eval_cell(kind=%s,shape=%s,node_id=%d,cursor=%d,step=%d,status=%s,site=%s)"
                cell.kind cell.shape cell.nodeId cell.cursor cell.step cell.status cell.site

        type ParentReplayEnqueueDecisionId =
            | ParentReplayNoCell
            | ParentReplayScheduledTerm
            | ParentReplayScheduledTy
            | ParentReplayScheduledUnknownKind of string

        let parentReplayEnqueueDecisionText = function
            | ParentReplayNoCell -> "no_cell"
            | ParentReplayScheduledTerm -> "scheduled_term_parent_replay"
            | ParentReplayScheduledTy -> "scheduled_ty_parent_replay"
            | ParentReplayScheduledUnknownKind x -> "scheduled_unknown_parent_replay:" + x

        type ParentReplayKeyDedupeId =
            | ParentReplayStableKey
            | ParentReplayReplacedPriorKey

        let parentReplayKeyDedupeText = function
            | ParentReplayStableKey -> "stable_key"
            | ParentReplayReplacedPriorKey -> "replaced_prior_key"

        type ParentReplayDriverWakeDecisionId =
            | ParentReplayDriverWakeNoQueue
            | ParentReplayDriverWakeAlreadyActive
            | ParentReplayDriverWakeScheduleTick
            | ParentReplayDriverWakeSuppressQueuedFence

        let parentReplayDriverWakeDecisionText = function
            | ParentReplayDriverWakeNoQueue -> "no_queue"
            | ParentReplayDriverWakeAlreadyActive -> "already_active"
            | ParentReplayDriverWakeScheduleTick -> "schedule_tick"
            | ParentReplayDriverWakeSuppressQueuedFence -> "suppress_queued_fence"

        let private parentReplayDriverWakeDecisionFor queueDepth activeDepth fenceQueued =
            if queueDepth <= 0 then ParentReplayDriverWakeNoQueue
            elif activeDepth > 0 then ParentReplayDriverWakeAlreadyActive
            elif fenceQueued then ParentReplayDriverWakeSuppressQueuedFence
            else ParentReplayDriverWakeScheduleTick

        type DirectCellCycleBreakLeaseId =
            | DirectCellCycleBreakLeaseAcquired
            | DirectCellCycleBreakLeaseAlreadyActive
            | DirectCellCycleBreakLeaseRenewedAfterDrain
            | DirectCellCycleBreakLeaseRootProgressDefers
            | DirectCellCycleBreakLeaseExhausted

        let private directCellCycleBreakLeaseText = function
            | DirectCellCycleBreakLeaseAcquired -> "acquired"
            | DirectCellCycleBreakLeaseAlreadyActive -> "already_active"
            | DirectCellCycleBreakLeaseRenewedAfterDrain -> "renewed_after_drain"
            | DirectCellCycleBreakLeaseRootProgressDefers -> "root_progress_defers"
            | DirectCellCycleBreakLeaseExhausted -> "exhausted"

        let private directCellCycleBreakLeaseCounts =
            System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        let private directCellCycleBreakLeaseKey (_event: string) (cell: ReplayCell) =
            // ALPHA1259: key by stable semantic cell identity, not by wake event/status.
            // 1258 showed the same node escaping the lease through bigstack queue-fallback
            // and parent-handoff callbacks.  Status is also mutable, so including it makes
            // poison / stepper transitions look like a different hole target.
            sprintf "%s|%s|%d|%s" cell.kind cell.shape cell.nodeId cell.site

        let private directCellCycleBreakLeaseDecision (leaseKey: string) (queueDepthAtLease: int) (activeDepthAtLease: int) (rootProgressActive: bool) =
            // ALPHA1260: do not update the lease dictionary while holding the evaluator gate.
            // ConcurrentDictionary may briefly coordinate internally; that must not happen inside
            // lock gate while Hopac replay workers are parked behind the same gate.
            let leaseCount = directCellCycleBreakLeaseCounts.AddOrUpdate(leaseKey, 1, fun _ old -> old + 1)
            let drainedEnough = queueDepthAtLease <= 12 && activeDepthAtLease <= 1
            let activeTailQueueSurge =
                // ALPHA1324: alpha1323 showed q≈79/a=4 repeatedly reporting
                // root_progress_defers for the same EApply direct-cell cycle.  Root
                // activity proves liveness, not cycle freedom; after one lease, a
                // large active tail must escalate to the existing exhausted->parent
                // poison path instead of suppressing the handoff.
                queueDepthAtLease >= 64 && activeDepthAtLease >= 4
            let leaseDecision =
                if leaseCount = 1 then DirectCellCycleBreakLeaseAcquired
                elif drainedEnough && leaseCount % 4 = 0 then DirectCellCycleBreakLeaseRenewedAfterDrain
                elif activeTailQueueSurge && leaseCount >= 2 then DirectCellCycleBreakLeaseExhausted
                elif leaseCount >= 4 then DirectCellCycleBreakLeaseExhausted
                elif rootProgressActive then DirectCellCycleBreakLeaseRootProgressDefers
                else DirectCellCycleBreakLeaseAlreadyActive
            leaseDecision, leaseCount

        let mutable private replayDriverTickRequestHook : (string -> string -> bool) option = None

        type ReplayDriverTickRequestHookId =
            | ReplayDriverTickRequestNoHook
            | ReplayDriverTickRequestScheduled
            | ReplayDriverTickRequestRefused
            | ReplayDriverTickRequestFailed

        let private replayDriverTickRequestHookText = function
            | ReplayDriverTickRequestNoHook -> "no_hook"
            | ReplayDriverTickRequestScheduled -> "scheduled"
            | ReplayDriverTickRequestRefused -> "refused"
            | ReplayDriverTickRequestFailed -> "failed"

        let private replayDriverTickRequestHookScheduled = function
            | ReplayDriverTickRequestScheduled -> true
            | ReplayDriverTickRequestNoHook
            | ReplayDriverTickRequestRefused
            | ReplayDriverTickRequestFailed -> false

        let private tryRequestReplayDriverTickViaHook (event: string) (reason: string) =
            match replayDriverTickRequestHook with
            | Some hook ->
                try
                    if hook event reason then ReplayDriverTickRequestScheduled
                    else ReplayDriverTickRequestRefused
                with _ -> ReplayDriverTickRequestFailed
            | None -> ReplayDriverTickRequestNoHook

        let private directCellCycleBreakLeaseAllowsMutation = function
            | DirectCellCycleBreakLeaseAcquired
            | DirectCellCycleBreakLeaseRenewedAfterDrain -> true
            | DirectCellCycleBreakLeaseAlreadyActive
            | DirectCellCycleBreakLeaseRootProgressDefers
            | DirectCellCycleBreakLeaseExhausted -> false

        type DirectCellCycleBreakPhysicalHandoffId =
            | DirectCellCycleBreakPhysicalHandoffNone
            | DirectCellCycleBreakPhysicalHandoffParentPoison
            | DirectCellCycleBreakPhysicalHandoffDeferredHole

        let private directCellCycleBreakPhysicalHandoffText = function
            | DirectCellCycleBreakPhysicalHandoffNone -> "none"
            | DirectCellCycleBreakPhysicalHandoffParentPoison -> "parent_poison"
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> "deferred_hole"

        let private directCellCycleBreakPhysicalHandoffReason = function
            | DirectCellCycleBreakPhysicalHandoffNone -> "direct_cell_cycle_break_noop"
            | DirectCellCycleBreakPhysicalHandoffParentPoison -> "direct_cell_cycle_break_parent_poison_physical_handoff"
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> "direct_cell_cycle_break_deferred_hole_physical_handoff"

        let private directCellCycleBreakPhysicalHandoffShouldRequest = function
            | DirectCellCycleBreakPhysicalHandoffParentPoison
            | DirectCellCycleBreakPhysicalHandoffDeferredHole -> true
            | DirectCellCycleBreakPhysicalHandoffNone -> false

        let private replayDriverTextForParentCell (cell: ReplayCell) =
            match evalKindOfString cell.kind with
            | EvalTy -> replayDriverToString TyReplayDriver, ParentReplayScheduledTy
            | EvalTerm -> replayDriverToString TermReplayDriver, ParentReplayScheduledTerm
            | EvalData
            | EvalCodegen -> replayDriverToString TermReplayDriver, ParentReplayScheduledUnknownKind (evalKindToString (evalKindOfString cell.kind))
            | EvalUnknown other -> replayDriverToString TermReplayDriver, ParentReplayScheduledUnknownKind other

        let private scheduleParentReplayLocked (event: string) (reason: string) (cell: ReplayCell) =
            let driver, decision = replayDriverTextForParentCell cell
            replaySeq <- replaySeq + 1L
            let reasonKey = if System.String.IsNullOrWhiteSpace reason then "parent_continuation" else reason.Replace(" ", "_")
            let resumeKey = sprintf "%s|%s|scheduled_parent_replay|%s|%d" event reasonKey cell.kind cell.nodeId
            let replacedPrior = replayQueue |> List.exists (fun t -> t.key = resumeKey)
            let dedupeId = if replacedPrior then ParentReplayReplacedPriorKey else ParentReplayStableKey
            let resumeTask = { id = replaySeq; key = resumeKey; driver = driver; payload = formatCellPayload cell; status = replayTaskStatusToString ReplayTaskScheduledParentReplay; event = event }
            replayScheduledKey <- Some resumeKey
            replayQueue <- resumeTask :: (replayQueue |> List.filter (fun t -> t.key <> resumeKey))
            noteProgressYieldLocked ()
            DiagJson.emit (
                sprintf "{\"kind\":\"eval_worklist_parent_replay_key_dedupe\",\"event\":%s,\"decision_du\":%s,\"dedupe_du\":%s,\"driver\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"reason\":%s,\"queue_depth\":%d,\"single_flight\":1,\"next\":\"resume_parent_replay_driver\"}"
                    (esc event) (esc (parentReplayEnqueueDecisionText decision)) (esc (parentReplayKeyDedupeText dedupeId)) (esc driver) (esc cell.kind) (esc cell.shape) cell.nodeId (esc reasonKey) replayQueue.Length)
            decision

        let private replayCellFromParentCacheHandoff (req: EvalReplayValueStore.ParentCacheHandoffRequest) =
            { kind = req.cont.parentKind
              shape = req.cont.parentShape
              nodeId = req.cont.parentNodeId
              envGlobalTerm = 0
              envStackTerm = 0
              envGlobalType = 0
              envStackType = 0
              seqLen = 0
              cseDepth = 0
              traceDepth = 0
              site = sprintf "cache_handoff@child:%d:%s" req.childNodeId req.cont.role
              cursor = 0
              step = 0
              status = "parent_continuation_ready" }

        let private drainParentCacheHandoffsLocked (event: string) (maxItems: int) =
            let limit = max 1 (min 64 maxItems)
            let mutable drained = 0
            let mutable keepGoing = true
            while keepGoing && drained < limit do
                match EvalReplayValueStore.tryTakeParentCacheHandoff() with
                | Some req ->
                    let parentCell = replayCellFromParentCacheHandoff req
                    let decision = scheduleParentReplayLocked event "cache_write_parent_handoff" parentCell
                    let parentHandoffProofKey = sprintf "%s|%s|parent:%d|child:%d|role:%s" req.cont.parentKind req.cont.parentShape req.cont.parentNodeId req.childNodeId req.cont.role
                    let parentHandoffProofTuple = proofTupleForParentCacheHandoffWake parentHandoffProofKey
                    drained <- drained + 1
                    noteProgressYieldLocked ()
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_cache_write_parent_handoff_enqueued\",\"event\":%s,\"child_kind_du\":%s,\"child_node_id\":%d,\"decision_du\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"queue_depth\":%d,\"pending\":%d,\"materialized_terminal_payload_du\":%s,\"pending_graph_shard_state\":%s%s,\"single_flight\":1,\"next\":\"schedule_parent_cache_handoff_replay_continuation_immediately\"}"
                            (esc event) (esc (EvalReplayValueStore.parentCacheHandoffKindText req.childKindId)) req.childNodeId (esc (parentReplayEnqueueDecisionText decision)) (esc req.cont.parentKind) (esc req.cont.parentShape) req.cont.parentNodeId (esc req.cont.role) replayQueue.Length (pendingCount()) (esc (materializedTerminalOutcomeText MaterializedTerminalParentCacheHandoffWake)) (esc (typedTerminalPayloadText (parentCacheHandoffWakeTypedTerminalPayload parentHandoffProofKey))) (pendingGraphProofTupleJsonFields parentHandoffProofTuple))
                | None -> keepGoing <- false
            drained

        do EvalReplayValueStore.installParentCacheHandoffWake (fun () ->
            try
                // ALPHA1235: this is the concrete parent wakeup the assessment
                // demanded.  A child cache commit now immediately drains the
                // handoff queue into replayQueue after the cache write, instead
                // of waiting for passive join_wait/prefetch polling.
                lock gate (fun () -> drainParentCacheHandoffsLocked "cache_write_parent_handoff_wake_callback" 64 |> ignore)
            with _ -> ())

        // ALPHA1222: active structural cycle breaker.  When the global-fuse frontier
        // is a tiny pending/queued set backed by both term and ty hot-frontier
        // pressure, waiting for another replay drip only preserves the cross-kind
        // standoff.  Inject a deferred type hole into the ty side and explicitly
        // enqueue the opposite parent cell so the term side can collapse now; the
        // hole remains visible in PendingMonomorphizationQueue for later unification.
        type DeferredTypeVarCycleBreakDecisionId =
            | DeferredTypeVarCycleBreakNoCrossKind
            | DeferredTypeVarCycleBreakInjectedTy
            | DeferredTypeVarCycleBreakFallbackInjectedTerm
            | DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken

        let private deferredTypeVarCycleBreakDecisionText = function
            | DeferredTypeVarCycleBreakNoCrossKind -> "no_cross_kind"
            | DeferredTypeVarCycleBreakInjectedTy -> "injected_ty"
            | DeferredTypeVarCycleBreakFallbackInjectedTerm -> "fallback_injected_term"
            | DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken -> "already_had_hole_but_parent_woken"

        let tryForceDeferredTypeVarCycleBreak (event: string) (reason: string) =
            lock gate (fun () ->
                let frontierFrames = [ frontier; frontierTerm; frontierTy ] |> List.choose (fun x -> x)
                let frontierCells = frontierFrames |> List.choose (fun frame -> frame.semanticCell)
                let tyCellOpt = frontierCells |> List.tryFind (fun cell -> evalKindOfString cell.kind = EvalTy)
                let termCellOpt = frontierCells |> List.tryFind (fun cell -> evalKindOfString cell.kind = EvalTerm)
                let fallbackTermCellOpt =
                    match termCellOpt with
                    | Some _ -> termCellOpt
                    | None ->
                        frontierCells
                        |> List.tryFind (fun cell ->
                            match evalKindOfString cell.kind with
                            | EvalTerm -> true
                            | _ -> cell.shape = "ETypeApply" || cell.shape = "EApply")
                let liveReplayWindow =
                    // ALPHA1234: this is intentionally broader than the 1233 window.
                    // The manual interrupt tail had pending=2 queue=0 active=4; refusing
                    // to synthesize a hole there just leaves the four workers asleep.
                    pendingCount() <= 32
                    && replayQueue.Length <= 256
                    && replayDriverActiveDepth <= 8
                let scheduleParents decision (termCellOpt: ReplayCell option) (tyCellOpt: ReplayCell option) injected =
                    let mutable scheduled = 0
                    let mutable lastParentDecision = ParentReplayNoCell
                    match termCellOpt with
                    | Some termCell ->
                        lastParentDecision <- scheduleParentReplayLocked event "deferred_type_var_cycle_break_parent_term" termCell
                        scheduled <- scheduled + 1
                    | None -> ()
                    match tyCellOpt with
                    | Some tyCell ->
                        lastParentDecision <- scheduleParentReplayLocked event "deferred_type_var_cycle_break_parent_ty" tyCell
                        scheduled <- scheduled + 1
                    | None -> ()
                    if injected || scheduled > 0 then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_deferred_type_var_cycle_break_scheduled\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"parent_enqueue_du\":%s,\"scheduled_parents\":%d,\"injected\":%b,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending_monomorphization_queue\":%d,\"policy\":\"deferred_unification_break_fills_hole_and_wakes_parent_after_cycle_break\",\"single_flight\":1,\"next\":\"resume_parent_with_deferred_type_hole\"}"
                                (esc event) (esc reason) (esc (deferredTypeVarCycleBreakDecisionText decision)) (esc (parentReplayEnqueueDecisionText lastParentDecision)) scheduled injected (pendingCount()) replayQueue.Length replayDriverActiveDepth (EvalReplayValueStore.pendingMonomorphizationQueueDepth()))
                        true
                    else false
                if not liveReplayWindow then false
                else
                    match tyCellOpt, fallbackTermCellOpt with
                    | Some tyCell, Some termCell ->
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                tyCell.nodeId
                                (sprintf "%s:%s:term=%d:%s:ty=%d:%s" reason event termCell.nodeId termCell.shape tyCell.nodeId tyCell.shape)
                        let decision = if injected then DeferredTypeVarCycleBreakInjectedTy else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision (Some termCell) (Some tyCell) injected
                    | None, Some termCell ->
                        // Destructive fallback requested by the assessment: when the ty
                        // side exists only as a blocked frame/payloadless key, inject a
                        // visible hole at the term cell identity too, then wake that parent.
                        // It is a cycle-breaking placeholder, not semantic success.
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                termCell.nodeId
                                (sprintf "%s:%s:fallback_term_hole=%d:%s" reason event termCell.nodeId termCell.shape)
                        let decision = if injected then DeferredTypeVarCycleBreakFallbackInjectedTerm else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision (Some termCell) None injected
                    | Some tyCell, None ->
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                tyCell.nodeId
                                (sprintf "%s:%s:orphan_ty_hole=%d:%s" reason event tyCell.nodeId tyCell.shape)
                        let decision = if injected then DeferredTypeVarCycleBreakInjectedTy else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        scheduleParents decision None (Some tyCell) injected
                    | None, None -> false)

        let tryForceDeferredTypeVarCycleBreakForCell (event: string) (reason: string) (cell: ReplayCell) =
            let leaseKey = directCellCycleBreakLeaseKey event cell
            let queueDepthAtLease = try replayQueue.Length with _ -> -1
            let activeDepthAtLease = try replayDriverActiveDepth with _ -> -1
            let rootProgressActive =
                try
                    // ALPHA1324: root progress can defer a duplicate direct-cell
                    // mutation only while the queue is small enough to prove real
                    // drain.  At q>=64/a>=4 the same signal becomes evidence for
                    // active-tail poison rather than a reason to suppress it.
                    DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked" > 0
                    && queueDepthAtLease <= 63
                with _ -> false
            let leaseDecisionId, leaseCount =
                directCellCycleBreakLeaseDecision leaseKey queueDepthAtLease activeDepthAtLease rootProgressActive
            let mutable physicalHandoffId = DirectCellCycleBreakPhysicalHandoffNone
            let result =
                lock gate (fun () ->
                    if not (directCellCycleBreakLeaseAllowsMutation leaseDecisionId) then
                        let exhausted = leaseDecisionId = DirectCellCycleBreakLeaseExhausted
                        let poisonedParentEnqueue =
                            if exhausted then
                                let poisonedCell = { cell with status = semanticStatusToString SemanticParentReplayCycleBreakPoisoned }
                                let parentDecision = scheduleParentReplayLocked event "deferred_type_var_cycle_break_lease_exhausted_poison" poisonedCell
                                physicalHandoffId <- DirectCellCycleBreakPhysicalHandoffParentPoison
                                let poisonMsg =
                                    sprintf
                                        ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break_exhausted_poison","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"parent_enqueue_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"pending":%d,"queue_depth":%d,"active_depth":%d,"policy":"bounded_repeated_cycle_break_escalates_to_typed_parent_poison_and_requests_physical_replay_drain","single_flight":1,"next":"execute_parent_cycle_break_poison_inline_callback_and_wake_native_driver"}""")
                                        (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc leaseKey) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (parentReplayEnqueueDecisionText parentDecision)) (esc cell.kind) (esc cell.shape) cell.nodeId (pendingCount()) replayQueue.Length replayDriverActiveDepth
                                DiagJson.emit poisonMsg
                                true
                            else false
                        let suppressedMsg =
                            sprintf
                                ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break_suppressed","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"pending":%d,"queue_depth":%d,"active_depth":%d,"lease_queue_depth":%d,"lease_active_depth":%d,"poison_parent_enqueued":%b,"policy":"same_cell_cycle_break_hole_is_leased_without_holding_gate_for_dictionary_update","single_flight":1,"next":"continue_replay_without_duplicate_hole"}""")
                                (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc leaseKey) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc cell.kind) (esc cell.shape) cell.nodeId (pendingCount()) replayQueue.Length replayDriverActiveDepth queueDepthAtLease activeDepthAtLease poisonedParentEnqueue
                        DiagJson.emit suppressedMsg
                        poisonedParentEnqueue
                    else
                        let injected =
                            EvalReplayValueStore.putDeferredTypeVar
                                cell.nodeId
                                (sprintf "%s:%s:direct_cell_hole=%d:%s:%s:lease=%d" reason event cell.nodeId cell.kind cell.shape leaseCount)
                        let decision = if injected then DeferredTypeVarCycleBreakFallbackInjectedTerm else DeferredTypeVarCycleBreakAlreadyHadHoleButParentWoken
                        let parentDecision = scheduleParentReplayLocked event "deferred_type_var_cycle_break_direct_cell" cell
                        physicalHandoffId <- DirectCellCycleBreakPhysicalHandoffDeferredHole
                        let cycleBreakMsg =
                            sprintf
                                ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_cycle_break","event":%s,"reason":%s,"decision_du":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"parent_enqueue_du":%s,"cell_kind":%s,"cell_shape":%s,"cell_node_id":%d,"injected":%b,"pending":%d,"queue_depth":%d,"active_depth":%d,"lease_queue_depth":%d,"lease_active_depth":%d,"policy":"direct_cell_fallback_fills_hole_once_per_lease_and_reenqueues_parent_with_physical_tick","single_flight":1,"next":"resume_parent_with_deferred_type_hole"}""")
                                (esc event) (esc reason) (esc (deferredTypeVarCycleBreakDecisionText decision)) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc leaseKey) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (parentReplayEnqueueDecisionText parentDecision)) (esc cell.kind) (esc cell.shape) cell.nodeId injected (pendingCount()) replayQueue.Length replayDriverActiveDepth queueDepthAtLease activeDepthAtLease
                        DiagJson.emit cycleBreakMsg
                        true)
            if directCellCycleBreakPhysicalHandoffShouldRequest physicalHandoffId then
                let physicalReason = directCellCycleBreakPhysicalHandoffReason physicalHandoffId
                let tickRequestId = tryRequestReplayDriverTickViaHook event physicalReason
                let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                let handoffMsg =
                    sprintf
                        ("""{"kind":"eval_worklist_deferred_type_var_direct_cell_physical_handoff_requested","event":%s,"reason":%s,"lease_decision_du":%s,"lease_count":%d,"lease_key":%s,"physical_handoff_du":%s,"replay_tick_request_du":%s,"scheduled_async":%b,"policy":"cycle_break_and_poison_handoffs_request_a_driver_tick_after_parent_enqueue","single_flight":1,"next":"threadpool_replay_driver_tick_or_existing_drain"}""")
                        (esc event) (esc reason) (esc (directCellCycleBreakLeaseText leaseDecisionId)) leaseCount (esc leaseKey) (esc (directCellCycleBreakPhysicalHandoffText physicalHandoffId)) (esc (replayDriverTickRequestHookText tickRequestId)) scheduled
                DiagJson.emit handoffMsg
            result

        type SemanticCellKindKey =
            | SemanticCellKindKey of EvalKind

        let private semanticCellKindKeyOfString kind =
            SemanticCellKindKey (evalKindOfString kind)

        let private semanticCellKindKeyToString (SemanticCellKindKey kindId) =
            evalKindToString kindId

        let private semanticCellSiteKeyForKind kindId (site: string) =
            sprintf "%s|%s" (semanticCellKindKeyToString kindId) site

        let private semanticCellSiteKey (kind: string) (site: string) =
            semanticCellSiteKeyForKind (semanticCellKindKeyOfString kind) site

        let private rememberSemanticCell (cell: ReplayCell) =
            try
                if not (String.IsNullOrWhiteSpace cell.kind) && not (String.IsNullOrWhiteSpace cell.site) then
                    semanticCellsByKindSite.[semanticCellSiteKey cell.kind cell.site] <- cell
            with _ -> ()

        let private trySemanticCellForFrame (frame: Frame) : ReplayCell option =
            try
                let mutable cell = Unchecked.defaultof<ReplayCell>
                if semanticCellsByKindSite.TryGetValue(semanticCellSiteKey frame.kind frame.site, &cell) then Some cell
                else None
            with _ -> None

        // ALPHA546: scheduling the same child identity again and again is now treated
        // as a typed terminal obligation, not as useful replay progress.  The key
        // intentionally ignores step/cursor because alpha545's watchdog gap changed
        // those counters while returning to the same child obligation.
        type ReplayChildScheduleRoleId =
            | ReplayChildScheduleApplyChildren of string
            | ReplayChildScheduleTypeApplyArg of string
            | ReplayChildScheduleTypeFunChild of string
            | ReplayChildScheduleIfBranch of string
            | ReplayChildScheduleSynthetic of string
            | ReplayChildScheduleUnknown of string

        let private replayChildScheduleRoleOfString (role: string) =
            let r = if String.IsNullOrWhiteSpace role then "unknown" else role
            if r.Contains("type_apply", StringComparison.OrdinalIgnoreCase) then ReplayChildScheduleTypeApplyArg r
            elif r.Contains("type_fun", StringComparison.OrdinalIgnoreCase) || r.Contains("tfun", StringComparison.OrdinalIgnoreCase) then ReplayChildScheduleTypeFunChild r
            elif r.Contains("if", StringComparison.OrdinalIgnoreCase) || r.Contains("branch", StringComparison.OrdinalIgnoreCase) then ReplayChildScheduleIfBranch r
            elif r.Contains("synthetic", StringComparison.OrdinalIgnoreCase) then ReplayChildScheduleSynthetic r
            elif r.Contains("child", StringComparison.OrdinalIgnoreCase) || r.Contains("apply", StringComparison.OrdinalIgnoreCase) then ReplayChildScheduleApplyChildren r
            else ReplayChildScheduleUnknown r

        let private replayChildScheduleRoleText = function
            | ReplayChildScheduleApplyChildren r
            | ReplayChildScheduleTypeApplyArg r
            | ReplayChildScheduleTypeFunChild r
            | ReplayChildScheduleIfBranch r
            | ReplayChildScheduleSynthetic r
            | ReplayChildScheduleUnknown r -> r

        let private replayChildScheduleKeyForRole roleId (cell: ReplayCell) =
            sprintf "%s|%s|%s|%d|%s" (replayChildScheduleRoleText roleId) (evalKindToString (evalKindOfString cell.kind)) cell.shape cell.nodeId cell.site

        let private replayChildScheduleKey (role: string) (cell: ReplayCell) =
            replayChildScheduleKeyForRole (replayChildScheduleRoleOfString role) cell

        let private noteReplayChildSchedule (role: string) (cell: ReplayCell) =
            let roleId = replayChildScheduleRoleOfString role
            let key = replayChildScheduleKeyForRole roleId cell
            let count =
                lock gate (fun () ->
                    let mutable prior = 0
                    let nextCount = if replayChildScheduleRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                    replayChildScheduleRepeats.[key] <- nextCount
                    nextCount)
            count, key

        // ALPHA537: pin terminal replay contracts at the emission site, not only
        // when retry-drain later peeks the canonical frontier.  Alpha536 showed the
        // earlier literal/macro terminal receipts could be shadowed by a downstream
        // let-success continuation before pinTerminalContract saw them.
        let private pinTerminalCell (event: string) (reason: string) (cell: ReplayCell) =
            let status = cell.status
            if isTerminalContractStatus status then
                let frame =
                    { kind = cell.kind
                      key = sprintf "%s:%s#%d" cell.kind cell.site cell.nodeId
                      site = cell.site
                      depth = cell.traceDepth
                      re = 0
                      maxRe = 0
                      trace = []
                      reason = reason
                      status = status
                      cursor = cell.cursor
                      semanticPayload = Some (formatCellPayload cell)
                      semanticCell = Some cell }
                if liveReplayTerminalSuppressed status then
                    // ALPHA954: pinTerminalCell is above replayQueueDepth in declaration order;
                    // use the local queue under the gate instead of calling the later public helper.
                    let queueDepth = lock gate (fun () -> replayQueue.Length)
                    let activeDepth = replayDriverActiveDepthValue()
                    let progressYieldPending = hasProgressYield()
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_terminal_cell_emission_suppressed_after_live_replay\",\"event\":%s,\"status\":%s,\"rank\":%d,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"policy\":\"typed_terminal_status_defers_cell_emission_while_replay_is_live\",\"single_flight\":1,\"next\":\"continue_active_replay_driver\"}"
                            (esc event) (esc status) (terminalContractRank status) cell.nodeId (esc cell.shape) (esc cell.site) (pendingCount()) queueDepth activeDepth progressYieldPending)
                else
                    pinTerminalContract event frame
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_terminal_contract_emission_pinned\",\"event\":%s,\"status\":%s,\"rank\":%d,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"log_completeness\":%s,\"single_flight\":1,\"next\":%s}"
                            (esc event) (esc status) (terminalContractRank status) cell.nodeId (esc cell.shape) (esc cell.site) (esc (logCompletenessPolicyText activeLogCompletenessPolicy)) (esc (terminalContractNext status)))


        // ALPHA545: dynamic-join apply blockers are real terminal contracts once the
        // concrete/dynamic bridge has failed closed.  Pin the blocked replay cell at
        // emission so retry/global-fuse selection sees the dynamic frontier before it
        // burns passes on a generic continuation envelope.
        let private pinDynamicJoinBlocker (event: string) (reason: string) (detail: string) (cell: ReplayCell) =
            let blockedCell = { cell with status = semanticStatusToString SemanticDynamicJoinApplyBlocked }
            let dynamicJoinDecision = dynamicJoinTerminalDecisionForStatusText blockedCell.status
            let queueDepth = lock gate (fun () -> replayQueue.Length)
            let activeDepth = replayDriverActiveDepthValue()
            let progressYieldPending = hasProgressYield()
            let runtimeUnionCarrier =
                reason.IndexOf("DNominal/DUnion", StringComparison.Ordinal) >= 0
                || detail.IndexOf("DNominal/DUnion", StringComparison.Ordinal) >= 0
                || reason.IndexOf("DUnion", StringComparison.Ordinal) >= 0
                || detail.IndexOf("DUnion", StringComparison.Ordinal) >= 0
            let dynamicJoinPending = pendingCount()
            let freshRootOrReplayEvidence =
                progressYieldPending
                || dynamicJoinPending > 0
                || queueDepth > 0
                || activeDepth > 0
                || DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked" > 0
                || DiagJson.snapshotKindCount "eval_worklist_source_value_stored" > 0
            let reentrantDynamicJoinNoWaiter =
                dynamicJoinPending = 0
                && (reason.IndexOf("reentrant_replay_driver", StringComparison.Ordinal) >= 0
                    || detail.IndexOf("reentrant_replay_driver", StringComparison.Ordinal) >= 0)
            let dynamicJoinPinSuppressed =
                not reentrantDynamicJoinNoWaiter
                && ((dynamicJoinDecision = DynamicJoinTerminalDeferLiveReplay
                     && liveReplayTerminalSuppressed blockedCell.status)
                    || (runtimeUnionCarrier && freshRootOrReplayEvidence))
            if dynamicJoinPinSuppressed then
                // ALPHA1322: do not durably pin the first dynamic-join terminal when
                // the runtime union/root/replay carrier is still live.  Pinning here
                // caused jp_wait to preempt with the stale rank-92 terminal while the
                // driver later proved more semantic_root_complete receipts.
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_dynamic_join_terminal_suppressed_after_live_replay\",\"event\":%s,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"status\":%s,\"rank\":%d,\"reason\":%s,\"detail\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"runtime_union_carrier\":%b,\"policy\":\"dynamic_join_runtime_union_defers_durable_pin_while_root_or_replay_live\",\"decision_du\":%s,\"single_flight\":1,\"next\":\"continue_active_replay_driver\"}"
                        (esc event) blockedCell.nodeId (esc blockedCell.shape) (esc blockedCell.site) (esc blockedCell.status) (terminalContractRank blockedCell.status) (esc reason) (esc detail) dynamicJoinPending queueDepth activeDepth progressYieldPending runtimeUnionCarrier (esc (dynamicJoinTerminalDecisionText dynamicJoinDecision)))
            else
                pinTerminalCell event (reason + ":" + detail) blockedCell
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_dynamic_join_terminal_pinned\",\"event\":%s,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"status\":%s,\"rank\":%d,\"reason\":%s,\"detail\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"reentrant_no_waiter\":%b,\"decision_du\":%s,\"single_flight\":1,\"next\":%s}"
                        (esc event) blockedCell.nodeId (esc blockedCell.shape) (esc blockedCell.site) (esc blockedCell.status) (terminalContractRank blockedCell.status) (esc reason) (esc detail) dynamicJoinPending queueDepth activeDepth reentrantDynamicJoinNoWaiter (esc (dynamicJoinTerminalDecisionText dynamicJoinDecision)) (esc (terminalContractNext blockedCell.status)))
            blockedCell

        // ALPHA909: path-specific runtime archaeology must not be executable policy.
        // Keep old comments as documentation, but route active guards through typed
        // replay evidence: status, kind, shape, semantic cell/payload, pending work,
        // and fresh root-complete witnesses.  This prevents another sentinel/gibberish
        // cleanup while keeping the compiler generic for any Spiral project.
        let frameCellShapeIn (shapes: string list) (frame: Frame) =
            match frame.semanticCell with
            | Some cell -> shapes |> List.exists (fun shape -> cell.shape = shape)
            | None -> false

        let frameCellStatusIs (status: string) (frame: Frame) =
            match frame.semanticCell with
            | Some cell -> cell.status = status
            | None -> false

        let frameIsRootCompleteEvidence (frame: Frame) =
            frame.status = "semantic_root_complete" || frameCellStatusIs "semantic_root_complete" frame

        let frameHasSemanticEvidence (frame: Frame) =
            match frame.semanticCell, frame.semanticPayload with
            | Some _, _ -> true
            | _, Some payload -> not (System.String.IsNullOrWhiteSpace payload)
            | _ -> frame.key.Contains("#")

        let frameCellShapeOrSemanticEvidence (shapes: string list) (frame: Frame) =
            frameCellShapeIn shapes frame || frameHasSemanticEvidence frame

        let frameKindStatusShape (kind: string) (status: string) (shapes: string list) (frame: Frame) =
            frame.kind = kind && frame.status = status && frameCellShapeIn shapes frame

        let rootCompleteShieldsPinnedShape (status: string) (shapes: string list) (frame: Frame) (pinned: Frame) =
            frameIsRootCompleteEvidence frame
            && pinned.status = status
            && pendingCount() > 0
            && frameCellShapeOrSemanticEvidence shapes pinned

        // ALPHA538: retry_stop_drain should not let a lower-ranked replay-repeat or
        // downstream continuation shadow a high-rank terminal that was already pinned
        // at emission.  This only changes diagnostic selection; it does not mark replay
        // complete, hydrate missing payloads, or fabricate semantic values.
        let private preferPinnedTerminalForRetryDrain (event: string) (frame: Frame) =
            if event <> "retry_stop_drain" then Some frame
            else
                match tryPinnedTerminalContract() with
                | Some pinned when not (frameKindCompatible frame.kind pinned) ->
                    let rank = terminalContractRank pinned.status
                    let cleared = lock gate (fun () -> clearCurrentCrossKindPinnedTerminalLocked pinned)
                    emitCrossKindPinnedTerminalIgnored event frame.kind pinned rank (sprintf "active_frame_kind=%s status=%s cleared=%b" frame.kind frame.status cleared)
                    Some frame
                | Some pinned ->
                    let pinnedRank = terminalContractRank pinned.status
                    let frameRank = terminalContractRank frame.status
                    let pinnedBeatsRootComplete =
                        frame.status = "semantic_root_complete" && pinnedRank >= 90
                    let pinnedBeatsNonTerminal =
                        frameRank = 0
                        && pinnedRank >= 68
                        && (frame.status = "semantic_leaf_complete"
                            || frame.status = "semantic_root_complete"
                            || frame.status = "continuation_envelope"
                            || frame.status = "ready_explicit_loop"
                            || frame.status = "blocked_by_reentry")
                    let pinnedBeatsLowerTerminal =
                        pinnedRank >= 68
                        && pinnedRank > frameRank
                    // ALPHA577: when the active retry_stop frontier is already a
                    // semantic_root_complete proof, do not let a later stale TV
                    // terminal from pending-job drain replace it.  This is only a
                    // diagnostic/scheduling preference; writer gates still require
                    // the real root-complete witness and no type value is invented.
                    let rootCompleteShieldsStaleTypeVar =
                        frame.status = "semantic_root_complete"
                        && pinned.status = "semantic_type_variable_value_missing_blocked"
                        && pendingCount() > 0
                    let retargetShieldedByRootEvidence =
                        frame.status = "semantic_stale_root_retarget_blocked"
                        && pinned.status = "semantic_type_variable_value_missing_blocked"
                        && pendingCount() > 0
                    let rootCompleteShieldsPayloadMissing =
                        frame.status = "semantic_root_complete"
                        && pinned.status = "semantic_replay_payload_missing_blocked"
                        && pendingCount() > 0
                    let rootCompleteShieldsStaleTJoinPoint =
                        rootCompleteShieldsPinnedShape "semantic_tjoinpoint_stepper_blocked" ["TJoinPoint'"] frame pinned
                    let rootCompleteShieldsStaleSymbolicIf =
                        rootCompleteShieldsPinnedShape "semantic_if_symbolic_condition_blocked" ["EIfThenElse"] frame pinned
                    let rootCompleteShieldsStaleDynamicJoin =
                        rootCompleteShieldsPinnedShape "semantic_dynamic_join_apply_blocked" ["EApply"] frame pinned
                    let rootCompleteShieldsStaleMacroReplayRepeat =
                        rootCompleteShieldsPinnedShape "semantic_replay_fingerprint_repeat_blocked" ["EMacro"] frame pinned
                    let rootCompleteShieldsStaleNominalConstructor =
                        rootCompleteShieldsPinnedShape "semantic_type_apply_nominal_constructor_stepper_blocked" ["ENominal"] frame pinned
                    let rootCompleteShieldsTraceReplayRepeat =
                        rootCompleteShieldsPinnedShape "semantic_replay_fingerprint_repeat_blocked" ["EMacro"] frame pinned
                    let rootCompleteShieldsTraceUnionReplayRepeat =
                        rootCompleteShieldsPinnedShape "semantic_replay_fingerprint_repeat_blocked" ["TUnion"] frame pinned
                    let rootCompleteShieldsSameSiteStaleRetarget =
                        frameIsRootCompleteEvidence frame
                        && pinned.status = "semantic_root_complete_stale_retarget_repeat_blocked"
                        && pendingCount() > 0
                        && frame.site = pinned.site
                    let appRootShieldsCoreRealRootStaleRetarget =
                        rootCompleteShieldsPinnedShape "semantic_root_complete_stale_retarget_repeat_blocked" ["EAnnot"] frame pinned
                    let rootCompleteShieldsCoreRealApplyContinuationException =
                        frameIsRootCompleteEvidence frame
                        && pinned.status = "semantic_apply_continuation_exception_blocked"
                        && pendingCount() > 0
                        && frameHasSemanticEvidence pinned
                    let rootCompleteShieldsCoreMacroReplayRepeat =
                        rootCompleteShieldsPinnedShape "semantic_replay_fingerprint_repeat_blocked" ["EMacro"] frame pinned
                    let rootCompleteShieldsCoreRealLetReplayRepeat =
                        rootCompleteShieldsPinnedShape "semantic_replay_fingerprint_repeat_blocked" ["ELet"] frame pinned
                    let rootCompleteShieldsCoreForallBodyStepper =
                        rootCompleteShieldsPinnedShape "semantic_type_apply_forall_body_stepper_blocked" ["EOp"; "ETypeApply"] frame pinned
                    let appRootShieldsCoreUnboxStaleRetarget =
                        rootCompleteShieldsPinnedShape "semantic_root_complete_stale_retarget_repeat_blocked" ["EUnbox"] frame pinned
                    let appRootShieldsBackendOpImplRequired =
                        rootCompleteShieldsPinnedShape "semantic_op_impl_required_blocked" ["EOp"] frame pinned
                    let continuationEnvelopeShieldsCoreLetReplayRepeat =
                        isContinuationEnvelopeFrameStatus frame.status
                        && pinned.status = "semantic_replay_fingerprint_repeat_blocked"
                        && pendingCount() > 0
                        && frameCellShapeOrSemanticEvidence ["ELet"] pinned
                    let freshReplayRootWitnessAvailable =
                        let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                        replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                        && ageMs >= 0.0
                        && ageMs <= replayRootCompleteWitnessWindowMs
                    let liveDrainShieldsFreshReplayRepeat =
                        isLiveExplicitFrameStatus frame.status
                        && pinned.status = "semantic_replay_fingerprint_repeat_blocked"
                        && pendingCount() > 0
                        && freshReplayRootWitnessAvailable
                        && (match pinned.semanticCell with
                            | Some cell -> cell.shape = "EMacro" || cell.shape = "ELet" || cell.shape = "ETypeApply"
                            | None -> pinned.key.Contains("#"))
                    let liveDrainShieldsFreshOpImplRequired =
                        (isLiveOrRootCompleteFrameStatus frame.status
                         || frame.status = "semantic_replay_driver_exception_blocked")
                        && pinned.status = "semantic_op_impl_required_blocked"
                        && pendingCount() > 0
                        && freshReplayRootWitnessAvailable
                        && frameCellShapeOrSemanticEvidence ["EOp"] pinned
                    let liveDrainShieldsFreshJoinpointValue =
                        isLiveOrRootCompleteFrameStatus frame.status
                        && pinned.status = "semantic_joinpoint_value_blocked"
                        && pendingCount() > 0
                        && freshReplayRootWitnessAvailable
                        && (frameIsRootCompleteEvidence frame || frameHasSemanticEvidence frame)
                    let leafCompleteAppRootShieldsSameSiteStaleRetarget =
                        frame.status = "semantic_leaf_complete"
                        && pinned.status = "semantic_root_complete_stale_retarget_repeat_blocked"
                        && pendingCount() > 0
                        && frame.site = pinned.site
                        && frameCellShapeOrSemanticEvidence ["EApply"; "EUnitTest"] frame
                    let retryDrainShieldsBackendAnnotStaleRetarget =
                        isLiveOrRootCompleteFrameStatus frame.status
                        && pinned.status = "semantic_root_complete_stale_retarget_repeat_blocked"
                        && pendingCount() > 0
                        && ((match frame.semanticCell with
                            | Some cell when cell.status = "semantic_root_complete" -> true
                            | _ -> frame.status = "semantic_root_complete")
                            || (let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                                replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                                && ageMs >= 0.0
                                && ageMs <= replayRootCompleteWitnessWindowMs))
                        && frameCellShapeOrSemanticEvidence ["EAnnot"] pinned
                    let retryDrainPending = pendingCount()
                    // ALPHA1185: this helper sits before public replayQueueDepth in declaration order.
                    // Keep the queue read local and route the liveness classification through a DU.
                    let retryDrainQueueDepth = lock gate (fun () -> replayQueue.Length)
                    let retryDrainActiveDepth = replayDriverActiveDepthValue()
                    let retryDrainProgressYield = hasProgressYield()
                    let retryDrainLiveEvidence = retryDrainLiveEvidenceFor retryDrainPending retryDrainQueueDepth retryDrainActiveDepth retryDrainProgressYield
                    let retryDrainPinnedTerminalDecision =
                        retryDrainPinnedTerminalDecisionFor
                            pinned.status
                            frame.status
                            retryDrainPending
                            retryDrainQueueDepth
                            retryDrainActiveDepth
                            retryDrainProgressYield
                            freshReplayRootWitnessAvailable
                    let leafCompleteShieldsStaleTypeVar =
                        frame.status = "semantic_leaf_complete"
                        && pinned.status = "semantic_type_variable_value_missing_blocked"
                        && pendingCount() > 0
                    if leafCompleteAppRootShieldsSameSiteStaleRetarget then
                        // ALPHA687: runtime 686 shows that after the parent-continuation
                        // cycle yields a concrete same-site app EApply semantic_leaf_complete
                        // frontier, a freshly repinned semantic_root_complete_stale_retarget
                        // terminal at the same spiral.spi:2670 site can still outrank it.
                        // Clear only that stale diagnostic terminal preference and continue
                        // draining the concrete app leaf.  This does not synthesize a
                        // continuation, value, root proof, writer output, codegen result,
                        // or BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_root_complete_stale_retarget_repeat_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_root_complete_stale_retarget_repeat_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_leaf_complete_shields_same_site_stale_retarget\",\"event\":%s,\"leaf_site\":%s,\"stale_site\":%s,\"leaf_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"drain_concrete_app_leaf\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif rootCompleteShieldsCoreRealApplyContinuationException then
                        // ALPHA686: runtime 685 showed that the old core/real_core.spir:202
                        // apply-continuation exception pin can survive jp_wait_cycle_drain
                        // and then outrank the live app-root semantic_root_complete frontier
                        // during retry_stop_drain.  Clear only that diagnostic terminal
                        // preference and keep the app root canonical.  This does not
                        // synthesize an apply continuation, value, root proof, writer output,
                        // codegen result, or BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_apply_continuation_exception_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_apply_continuation_exception_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_app_root_shields_core_real_apply_continuation_exception\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif rootCompleteShieldsCoreMacroReplayRepeat then
                        // ALPHA688: runtime 687 shows that the same retry_stop_drain
                        // selection bug reappears after the alpha687 path: a stale
                        // core/core.spi:56 EMacro replay-fingerprint repeat terminal
                        // is preferred over the live app-root semantic_root_complete
                        // witness at apps/spiral/spiral.spi:2670.  Demote only this
                        // diagnostic pin and keep root evidence canonical; this does
                        // not synthesize replay values, continuations, writer output,
                        // codegen result, or BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_replay_fingerprint_repeat_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_replay_fingerprint_repeat_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_app_root_core_macro_replay_repeat_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif rootCompleteShieldsCoreRealLetReplayRepeat then
                        // ALPHA694: runtime 693 shows retry_stop_drain preferring a
                        // stale rank-79 core/real_core.spir:203 ELet replay-fingerprint
                        // repeat terminal over the live app-root semantic_root_complete
                        // frontier at apps/spiral/spiral.spi:2670.  Clear only that
                        // diagnostic terminal preference and keep existing app-root
                        // evidence canonical.  This does not synthesize replay values,
                        // continuations, root proofs, writer output, codegen result, or
                        // BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_replay_fingerprint_repeat_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_replay_fingerprint_repeat_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_app_root_core_real_let_replay_repeat_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif rootCompleteShieldsCoreForallBodyStepper then
                        // ALPHA696: runtime 695 shows retry_stop_drain preferring a
                        // rank-81 core/core.spi:56 EOp forall-body stepper terminal
                        // over the live app-root semantic_root_complete frontier at
                        // apps/spiral/spiral.spi:2670.  Clear only that diagnostic
                        // terminal preference and keep existing app-root evidence
                        // canonical.  This does not synthesize a forall body, value,
                        // continuation, root proof, writer output, codegen result,
                        // or BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_type_apply_forall_body_stepper_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_type_apply_forall_body_stepper_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_app_root_core_forall_body_stepper_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif appRootShieldsCoreUnboxStaleRetarget then
                        // ALPHA690: runtime 689 shows retry_stop_drain preferring a
                        // stale rank-77 core/core.spi:127 EUnbox root-complete retarget
                        // over the live app-root semantic_root_complete frontier at
                        // apps/spiral/spiral.spi:2670.  This clears only that diagnostic
                        // terminal preference and keeps the existing app-root evidence
                        // canonical.  It does not synthesize a value, continuation,
                        // root proof, writer output, codegen result, or BuildOk.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_root_complete_stale_retarget_repeat_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_root_complete_stale_retarget_repeat_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_app_root_core_unbox_stale_retarget_demoted\",\"event\":%s,\"root_site\":%s,\"stale_site\":%s,\"root_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"preserve_root_evidence\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared)
                        Some frame
                    elif liveDrainShieldsFreshOpImplRequired then
                        // ALPHA924: runtime 923 proved alpha923 resumed the idle deferred
                        // replay path, but retry_stop_drain still let a rank-94 core EOp
                        // semantic_op_impl_required pin outrank a live drain frontier while
                        // a fresh replay-root write witness existed.  Demote only the
                        // diagnostic terminal preference; the op implementation, value,
                        // continuation, root proof, writer output, codegen result, and
                        // BuildOk are still required from real replay evidence.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_op_impl_required_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_op_impl_required_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_live_drain_op_impl_required_demoted_after_root_witness\",\"event\":%s,\"frontier_site\":%s,\"stale_site\":%s,\"frontier_status\":%s,\"stale_status\":%s,\"pending\":%d,\"durable_cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"drain_live_frontier_after_root_witness\"}"
                                (esc event) (esc frame.site) (esc pinned.site) (esc frame.status) (esc pinned.status) (pendingCount()) durableCleared (esc replayRootCompleteWitnessSummary))
                        Some frame
                    elif liveDrainShieldsFreshJoinpointValue then
                        // ALPHA926: runtime 925 moved past BackendSwitch repeat and
                        // reached fresh root-complete replay evidence, but retry_stop_drain
                        // still preferred a semantic_joinpoint_value_blocked pin over the
                        // live root/drain frontier until the clean retry budget exhausted.
                        // Demote only that diagnostic joinpoint terminal while a fresh
                        // replay-root witness is alive; no joinpoint value, continuation,
                        // writer output, codegen result, root proof, or BuildOk is synthesized.
                        let durableCleared =
                            lock gate (fun () ->
                                match pinnedTerminalContract with
                                | Some p when p.status = "semantic_joinpoint_value_blocked" && p.site = pinned.site ->
                                    pinnedTerminalContract <- None
                                | _ -> ()
                                match durableTerminalContract with
                                | Some p when p.status = "semantic_joinpoint_value_blocked" && p.site = pinned.site ->
                                    durableTerminalContract <- None
                                    true
                                | _ -> false)
