                            sprintf "{\"kind\":\"eval_worklist_retry_stop_frontier_retargeted_to_pinned_terminal\",\"event\":%s,\"old_status\":%s,\"new_status\":%s,\"old_rank\":%d,\"new_rank\":%d,\"old_site\":%s,\"new_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc frame.status) (esc pinned.status) frameRank pinnedRank (esc frame.site) (esc pinned.site) (pendingCount()) (esc (terminalContractNext pinned.status)))
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_retry_drain_pinned_terminal_preferred\",\"event\":%s,\"old_status\":%s,\"new_status\":%s,\"old_rank\":%d,\"new_rank\":%d,\"old_site\":%s,\"new_site\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc frame.status) (esc pinned.status) frameRank pinnedRank (esc frame.site) (esc pinned.site) (pendingCount()) (esc (terminalContractNext pinned.status)))
                        Some pinned
                    else Some frame
                | None -> Some frame

        // ALPHA456: reconstruct a ReplayCell from the exact compact payload emitted
        // by formatCellPayload.  This bridges scheduled_parent_replay tasks that
        // carry semantic_eval_payload(...) but arrive while the frontier cell slot is
        // empty/stale.  The parser is intentionally narrow and returns None on any
        // malformed field, keeping the replay driver fail-closed.
        let private tryReplayCellPayload (payload: string) : ReplayCell option =
            let tryInt (s: string) =
                let mutable v = 0
                if Int32.TryParse(s, &v) then Some v else None
            let tryPair (s: string) =
                let ix = if Object.ReferenceEquals(s,null) then -1 else s.IndexOf('/')
                if ix <= 0 || ix >= s.Length - 1 then None
                else
                    match tryInt (s.Substring(0, ix)), tryInt (s.Substring(ix + 1)) with
                    | Some a, Some b -> Some(a, b)
                    | _ -> None
            try
                if String.IsNullOrWhiteSpace payload then None
                else
                    let marker = "semantic_eval_payload("
                    let start = payload.IndexOf(marker, StringComparison.Ordinal)
                    if start < 0 then None
                    else
                        let bodyStart = start + marker.Length
                        let stop = payload.IndexOf(")", bodyStart, StringComparison.Ordinal)
                        if stop <= bodyStart then None
                        else
                            let body = payload.Substring(bodyStart, stop - bodyStart)
                            let fields = System.Collections.Generic.Dictionary<string,string>()
                            for part in body.Split([|','|], StringSplitOptions.None) do
                                let ix = part.IndexOf('=')
                                if ix > 0 then
                                    fields.[part.Substring(0, ix).Trim()] <- part.Substring(ix + 1).Trim()
                            let get k =
                                let mutable v = ""
                                if fields.TryGetValue(k, &v) then Some v else None
                            let kind = get "kind"
                            let shape = get "shape"
                            let nodeId = get "node_id" |> Option.bind tryInt
                            let envTerm = get "env_term" |> Option.bind tryPair
                            let envType = get "env_type" |> Option.bind tryPair
                            let seqLen = get "seq_len" |> Option.bind tryInt
                            let cseDepth = get "cse_depth" |> Option.bind tryInt
                            let traceDepth = get "trace_depth" |> Option.bind tryInt
                            let site = get "site"
                            let cursor = get "cursor" |> Option.bind tryInt
                            let step = get "step" |> Option.bind tryInt
                            let status = get "status"
                            match kind, shape, nodeId, envTerm, envType, seqLen, cseDepth, traceDepth, site, cursor, step, status with
                            | Some kind, Some shape, Some nodeId, Some (egt, est), Some (egty, esty), Some seqLen, Some cseDepth, Some traceDepth, Some site, Some cursor, Some step, Some status ->
                                Some { kind = kind; shape = shape; nodeId = nodeId; envGlobalTerm = egt; envStackTerm = est; envGlobalType = egty; envStackType = esty; seqLen = seqLen; cseDepth = cseDepth; traceDepth = traceDepth; site = site; cursor = cursor; step = step; status = status }
                            | _ -> None
            with _ -> None

        // ALPHA1336: dominant queue sampling for the HUD and fail-fast yield-thrash guard.
        // The queue payload remains serialized text, so this is explicitly an observability/
        // policy boundary: parse the cell tag, count kind:shape, never manufacture a value.
        type HotQueueNodeId =
            | HotQueueDominantNodeUnknown
            | HotQueueNode of int

        let private hotQueueNodeIdText = function
            | HotQueueNode nodeId -> string nodeId
            | HotQueueDominantNodeUnknown -> "-1"

        type HotQueueSample = {
            hotQueueDu : string
            hotQueueNodeId : HotQueueNodeId
            hotQueueCount : int
            hotQueueSampled : int
        }

        let private emptyHotQueueSample =
            { hotQueueDu = "-"
              hotQueueNodeId = HotQueueDominantNodeUnknown
              hotQueueCount = 0
              hotQueueSampled = 0 }

        let private replayQueueCellHotKey (cell: ReplayCell) =
            let k = if String.IsNullOrWhiteSpace cell.kind then "unknown" else cell.kind
            let s = if String.IsNullOrWhiteSpace cell.shape then "unknown" else cell.shape
            k + ":" + s

        let private replayQueueHotQueueSampleUnlocked (maxItems: int) =
            let limit = max 1 (min 128 maxItems)
            let counts = System.Collections.Generic.Dictionary<string,int>()
            let nodeCounts = System.Collections.Generic.Dictionary<int,int>()
            let addKey (key: string) =
                let key = if String.IsNullOrWhiteSpace key then "unknown" else key
                let mutable prior = 0
                if counts.TryGetValue(key, &prior) then counts.[key] <- prior + 1
                else counts.[key] <- 1
            let addNodeId (nodeId: int) =
                let mutable prior = 0
                if nodeCounts.TryGetValue(nodeId, &prior) then nodeCounts.[nodeId] <- prior + 1
                else nodeCounts.[nodeId] <- 1
            let mutable sampled = 0
            replayQueue
            |> List.truncate limit
            |> List.iter (fun task ->
                match tryReplayCellPayload task.payload with
                | Some cell ->
                    sampled <- sampled + 1
                    addKey (replayQueueCellHotKey cell)
                    addNodeId cell.nodeId
                | None ->
                    sampled <- sampled + 1
                    addKey ("task:" + task.driver))
            if sampled <= 0 || counts.Count <= 0 then emptyHotQueueSample
            else
                let mutable bestKey = "-"
                let mutable bestCount = 0
                for kv in counts do
                    if kv.Value > bestCount then
                        bestKey <- kv.Key
                        bestCount <- kv.Value
                let mutable bestNodeId = HotQueueDominantNodeUnknown
                let mutable bestNodeCount = 0
                for kv in nodeCounts do
                    if kv.Value > bestNodeCount then
                        bestNodeId <- HotQueueNode kv.Key
                        bestNodeCount <- kv.Value
                { hotQueueDu = bestKey
                  hotQueueNodeId = bestNodeId
                  hotQueueCount = bestCount
                  hotQueueSampled = sampled }

        let replayQueueHotQueueSample (maxItems: int) =
            lock gate (fun () -> replayQueueHotQueueSampleUnlocked maxItems)

        let replayQueueHotQueueDu () =
            (replayQueueHotQueueSample 64).hotQueueDu

        let tryForceDeferredTypeVarCycleBreakFromReplayQueue (event: string) (reason: string) (maxItems: int) =
            let scanLimit = max 1 (min 64 maxItems)
            let cells =
                lock gate (fun () ->
                    replayQueue
                    |> List.truncate scanLimit
                    |> List.choose (fun task -> tryReplayCellPayload task.payload))
            if cells.IsEmpty then
                let queueDepth, activeDepth, pending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_replay_queue_cycle_break_fallback_missing_cell\",\"event\":%s,\"reason\":%s,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"no_root_cycle_break_scans_queued_payloads_when_frontier_sample_missing\",\"single_flight\":1,\"next\":\"retry_or_continue_live_replay\"}"
                        (esc event) (esc reason) scanLimit queueDepth activeDepth pending)
                false
            else
                let mutable mutated = false
                let mutable attempted = 0
                for cell in cells do
                    if not mutated then
                        attempted <- attempted + 1
                        mutated <-
                            tryForceDeferredTypeVarCycleBreakForCell
                                event
                                (sprintf "%s:replay_queue_fallback:scan=%d:attempt=%d" reason scanLimit attempted)
                                cell
                if not mutated then
                    let queueDepth, activeDepth, pending =
                        lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_queue_cycle_break_fallback_all_leased\",\"event\":%s,\"reason\":%s,\"scan_limit\":%d,\"attempted_cells\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"queue_fallback_advances_past_first_leased_cell_before_reporting_no_mutation\",\"single_flight\":1,\"next\":\"retry_or_poison_when_repeat_cap_exhausts\"}"
                            (esc event) (esc reason) scanLimit attempted queueDepth activeDepth pending)
                mutated

        type ReplayQueueSurgePoisonDecisionId =
            | ReplayQueueSurgePoisonMissingCell
            | ReplayQueueSurgePoisonAlreadyCovered
            | ReplayQueueSurgePoisonEventCapSuppressed
            | ReplayQueueSurgePoisonInjected

        let private replayQueueSurgePoisonDecisionText = function
            | ReplayQueueSurgePoisonMissingCell -> "missing_cell"
            | ReplayQueueSurgePoisonAlreadyCovered -> "already_covered"
            | ReplayQueueSurgePoisonEventCapSuppressed -> "event_cap_suppressed"
            | ReplayQueueSurgePoisonInjected -> "poison_injected"

        type ReplayQueueSurgeParentPoisonAuthorityId =
            | ReplayQueueSurgeParentPoisonSuppressLiveTailDrain
            | ReplayQueueSurgeParentPoisonAllowParentPoison

        let private replayQueueSurgeParentPoisonAuthorityText = function
            | ReplayQueueSurgeParentPoisonSuppressLiveTailDrain -> "suppress_live_tail_drain"
            | ReplayQueueSurgeParentPoisonAllowParentPoison -> "allow_parent_poison"

        let private replayQueueSurgeParentPoisonAuthorityFor (event: string) queueDepth activeDepth pending =
            if event.IndexOf("active_queue_surge_hard", StringComparison.OrdinalIgnoreCase) >= 0 then ReplayQueueSurgeParentPoisonAllowParentPoison
            elif queueDepth >= 96 && activeDepth >= 4 && pending >= 0 then ReplayQueueSurgeParentPoisonSuppressLiveTailDrain
            else ReplayQueueSurgeParentPoisonAllowParentPoison

        let private replayQueueSurgePoisonCounts =
            System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        let private replayQueueSurgePoisonEventCounts =
            System.Collections.Concurrent.ConcurrentDictionary<string,int>()

        let private replayQueueSurgePoisonEventCap (event: string) =
            // ALPHA1323: active_queue_surge_hard_poison is a bounded emergency valve for
            // q>=256/a>=4 stalls.  It needs more than the old cross-kind pulse, but still
            // stays capped to avoid unbounded terminal spray.
            if event.IndexOf("active_queue_surge_hard", StringComparison.OrdinalIgnoreCase) >= 0 then 96
            elif event.IndexOf("cross_kind", StringComparison.OrdinalIgnoreCase) >= 0 then 3
            elif event.IndexOf("queue_surge", StringComparison.OrdinalIgnoreCase) >= 0 then 48
            else 48

        let tryForceDeferredTypeVarPoisonFromReplayQueue (event: string) (reason: string) (maxItems: int) =
            let scanLimit = max 1 (min 64 maxItems)
            let eventAttempt = replayQueueSurgePoisonEventCounts.AddOrUpdate(event, 1, fun _ old -> old + 1)
            let eventCap = replayQueueSurgePoisonEventCap event
            if eventAttempt > eventCap then
                let queueDepth, activeDepth, pending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                if eventAttempt = eventCap + 1 || eventAttempt % 32 = 0 then
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_event_cap_suppressed\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"cap_parent_poison_spray_per_event_after_enough_parent_poison_requests\",\"single_flight\":1,\"next\":\"continue_replay_or_fail_closed\"}"
                            (esc event) (esc reason) (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonEventCapSuppressed)) eventAttempt eventCap scanLimit queueDepth activeDepth pending)
                false
            else
                let initialQueueDepth, initialActiveDepth, initialPending =
                    lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                let authorityId = replayQueueSurgeParentPoisonAuthorityFor event initialQueueDepth initialActiveDepth initialPending
                if authorityId = ReplayQueueSurgeParentPoisonSuppressLiveTailDrain then
                    let tickRequestId = tryRequestReplayDriverTickViaHook event "queue_surge_parent_poison_suppressed_live_tail"
                    let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_suppressed_live_tail\",\"event\":%s,\"reason\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"replay_tick_request_du\":%s,\"scheduled_async\":%b,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"alpha1412_live_queue_surge_drains_before_parent_poison_surface_no_buildok\",\"single_flight\":1,\"next\":\"continue_replay_driver_or_pressure_drain\"}"
                            (esc event) (esc reason) (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)) eventAttempt eventCap (esc (replayDriverTickRequestHookText tickRequestId)) scheduled scanLimit initialQueueDepth initialActiveDepth initialPending)
                    false
                else
                    let cells =
                        lock gate (fun () ->
                            replayQueue
                            |> List.truncate scanLimit
                            |> List.choose (fun task -> tryReplayCellPayload task.payload))
                    if cells.IsEmpty then
                        let queueDepth, activeDepth, pending =
                            lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_replay_queue_surge_poison_missing_cell\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"high_queue_surge_prefers_parent_poison_over_new_hole_churn_but_found_no_typed_payload\",\"single_flight\":1,\"next\":\"retry_or_continue_live_replay\"}"
                                (esc event) (esc reason) (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonMissingCell)) eventAttempt eventCap scanLimit queueDepth activeDepth pending)
                        false
                    else
                        let mutable injected = false
                        let mutable attempted = 0
                        let mutable covered = 0
                        for cell in cells do
                            if not injected then
                                attempted <- attempted + 1
                                let poisonKey = directCellCycleBreakLeaseKey event cell
                                let poisonCount = replayQueueSurgePoisonCounts.AddOrUpdate(poisonKey, 1, fun _ old -> old + 1)
                                if poisonCount = 1 || poisonCount % 8 = 0 then
                                    let parentDecision, queueDepth, activeDepth, pending =
                                        lock gate (fun () ->
                                            let poisonedCell = { cell with status = semanticStatusToString SemanticParentReplayCycleBreakPoisoned }
                                            let parentDecision = scheduleParentReplayLocked event "queue_surge_parent_poison" poisonedCell
                                            parentDecision, replayQueue.Length, replayDriverActiveDepth, pendingCount())
                                    let tickRequestId = tryRequestReplayDriverTickViaHook event "queue_surge_parent_poison_physical_handoff"
                                    let scheduled = replayDriverTickRequestHookScheduled tickRequestId
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_injected\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"parent_enqueue_du\":%s,\"replay_tick_request_du\":%s,\"scheduled_async\":%b,\"scan_limit\":%d,\"attempted_cells\":%d,\"poison_count\":%d,\"poison_key\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_node_id\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"materialized_terminal_payload_du\":\"QueueSurgeParentReplayCycleBreakPoisonImmediateFill\",\"hopac_ivar_registry_id\":\"parent_replay_cycle_break_poison:queue_surge\",\"witness_type\":\"ParentReplayCycleBreakPoisonImmediateFillProof\",\"proof_tuple_complete\":true,\"native_hopac_callback_route_du\":\"IVar.fill(parent_replay_cycle_break_poison:queue_surge)\",\"native_promise_identifier_du\":\"promise_id(parent_replay_cycle_break_poison:queue_surge,ParentReplayCycleBreakPoisonImmediateFillProof)\",\"commit_pathway_trace_du\":\"queue_surge_parent_poison->IVar.fill->Job.unit\",\"active_native_callback_closure_du\":\"callback=IVar.fill(parent_replay_cycle_break_poison:queue_surge)|boundary=execute_native_direct_ast_eval_before_polling_boundary|return=Job.unit|legacy=false\",\"native_callback_control_flow_gate_du\":\"proof_tuple_complete->execute_native_direct_ast_callback_before_polling_boundary->return_Job.unit->legacy_unreachable\",\"callback_tracer_du\":\"[Witness:ParentReplayCycleBreakPoisonImmediateFillProof]->[IVar:parent_replay_cycle_break_poison:queue_surge]->[Action:IVar.fill]\",\"thread_fate_du\":\"native_hopac_run_queue_after_inline_callback\",\"worker_return_topology_du\":\"return_Job.unit_after_inline_queue_surge_parent_poison_callback\",\"eval_worklist_boundary_reachable_after_callback\":false,\"legacy_live_tail_veto_reachable\":false,\"policy\":\"queue_surge_hard_authority_parent_poison_no_buildok\",\"single_flight\":1,\"next\":\"execute_queue_surge_parent_poison_inline_callback_before_eval_worklist_boundary\"}"
                                            (esc event) (esc reason) (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonInjected)) (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)) eventAttempt eventCap (esc (parentReplayEnqueueDecisionText parentDecision)) (esc (replayDriverTickRequestHookText tickRequestId)) scheduled scanLimit attempted poisonCount (esc poisonKey) (esc cell.kind) (esc cell.shape) cell.nodeId pending queueDepth activeDepth)
                                    injected <- true
                                else
                                    covered <- covered + 1
                        if not injected then
                            let queueDepth, activeDepth, pending =
                                lock gate (fun () -> replayQueue.Length, replayDriverActiveDepth, pendingCount())
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_replay_queue_surge_parent_poison_already_covered\",\"event\":%s,\"reason\":%s,\"decision_du\":%s,\"authority_du\":%s,\"event_attempt\":%d,\"event_cap\":%d,\"scan_limit\":%d,\"attempted_cells\":%d,\"covered_cells\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"policy\":\"queue_surge_poison_suppresses_repeat_receipts_after_parent_poison_was_already_requested\",\"single_flight\":1,\"next\":\"continue_replay_without_duplicate_poison\"}"
                                    (esc event) (esc reason) (esc (replayQueueSurgePoisonDecisionText ReplayQueueSurgePoisonAlreadyCovered)) (esc (replayQueueSurgeParentPoisonAuthorityText authorityId)) eventAttempt eventCap scanLimit attempted covered queueDepth activeDepth pending)
                        injected

        let snapshot (maxn: int) : Frame list =
            if maxn <= 0 then []
            else
                lock gate (fun () ->
                    let xs = ResizeArray<Frame>()
                    let seen = System.Collections.Generic.HashSet<string>()
                    let add (opt: Frame option) =
                        match opt with
                        | Some frame ->
                            let k = frame.kind + "|" + frame.key + "|" + frame.site
                            if seen.Add k then xs.Add frame
                        | None -> ()
                    add frontier
                    add frontierTerm
                    add frontierTy
                    xs |> Seq.truncate maxn |> Seq.toList)

        let replayQueueDepth () =
            lock gate (fun () -> replayQueue.Length)

        let replayDriverStatus () =
            lock gate (fun () ->
                match replayQueue with
                | task :: _ -> sprintf "%s/%s" task.driver task.status
                | [] -> "none")

        let semanticPayloadStatus () =
            lock gate (fun () ->
                match frontier with
                | Some frame ->
                    match frame.semanticCell, frame.semanticPayload with
                    | Some _, _ -> "cell"
                    | _, Some p when not (String.IsNullOrWhiteSpace p) -> "semantic"
                    | _ -> "missing"
                | None -> "none")

        // ALPHA980: move the replay scheduler away from dumb status aliases.
        // A replay obligation carries the actual runnable/suppressed work item,
        // its liveness snapshot, and its terminal budget.  Strings are now only
        // a serialization boundary for JSON/status fields.
        type ReplayObligationKind =
            | ReplayObligationRun
            | ReplayObligationDefer
            | ReplayObligationBlock

        // ALPHA1141: reason strings had become the new untyped edge after
        // ReplayObligation itself became a DU-backed carrier.  Keep raw text
        // only at the JSON/status boundary so the active cross-kind loop can
        // be bucketed without promoting any semantic completion.
        type ReplayObligationReasonId =
            | ReplayReasonCrossKindActiveDriver
            | ReplayReasonIdleCrossKindDriver
            | ReplayReasonParentResumeCellDeferred
            | ReplayReasonSameNodeParentReplayDeferred
            | ReplayReasonActiveReplayCellDeferred
            | ReplayReasonReentrantReplayDriver
            | ReplayReasonDeferredChildCell
            | ReplayReasonUnknown of string

        let private replayObligationReasonOfString (reason: string) =
            match if System.Object.ReferenceEquals(reason, null) then "" else reason with
            | "cross_kind_active_replay_driver" -> ReplayReasonCrossKindActiveDriver
            | "idle_cross_kind_replay_driver" -> ReplayReasonIdleCrossKindDriver
            | "parent_resume_cell_deferred" -> ReplayReasonParentResumeCellDeferred
            | "same_node_parent_replay_cell_deferred" -> ReplayReasonSameNodeParentReplayDeferred
            | "active_replay_cell_deferred" -> ReplayReasonActiveReplayCellDeferred
            | "reentrant_replay_driver" -> ReplayReasonReentrantReplayDriver
            | "deferred_child_cell" -> ReplayReasonDeferredChildCell
            | x -> ReplayReasonUnknown x

        let private replayObligationReasonText = function
            | ReplayReasonCrossKindActiveDriver -> "cross_kind_active_replay_driver"
            | ReplayReasonIdleCrossKindDriver -> "idle_cross_kind_replay_driver"
            | ReplayReasonParentResumeCellDeferred -> "parent_resume_cell_deferred"
            | ReplayReasonSameNodeParentReplayDeferred -> "same_node_parent_replay_cell_deferred"
            | ReplayReasonActiveReplayCellDeferred -> "active_replay_cell_deferred"
            | ReplayReasonReentrantReplayDriver -> "reentrant_replay_driver"
            | ReplayReasonDeferredChildCell -> "deferred_child_cell"
            | ReplayReasonUnknown x -> x

        type ReplayObligationLivenessKind =
            | ReplayObligationQuiescent
            | ReplayObligationPendingOnly
            | ReplayObligationQueued
            | ReplayObligationActive
            | ReplayObligationDeferredCell
            | ReplayObligationProgressYield

        let private replayObligationLivenessKindText = function
            | ReplayObligationQuiescent -> "quiescent"
            | ReplayObligationPendingOnly -> "pending_only"
            | ReplayObligationQueued -> "queued"
            | ReplayObligationActive -> "active"
            | ReplayObligationDeferredCell -> "deferred_cell"
            | ReplayObligationProgressYield -> "progress_yield"

        type ReplayObligationTarget = {
            kind : string
            shape : string
            site : string
            nodeId : int
            driver : string
        }

        type ReplayLivenessSnapshot = {
            pending : int
            queueDepth : int
            activeDepth : int
            payloadStatus : string
            hasDeferredCell : bool
            hasProgressYield : bool
            kind : ReplayObligationLivenessKind
        }

        type CrossKindReentryEvidenceId =
            | CrossKindReentryNoHotNode
            | CrossKindReentrySameHotNode of int
            | CrossKindReentryQueueSurge of int
            | CrossKindReentryRootStalled of int

        let private crossKindReentryEvidenceText = function
            | CrossKindReentryNoHotNode -> "no_hot_node"
            | CrossKindReentrySameHotNode n -> "same_hot_node:" + string n
            | CrossKindReentryQueueSurge q -> "queue_surge:" + string q
            | CrossKindReentryRootStalled ms -> "root_stalled:" + string ms

        type CrossKindReentryEvidence = {
            evidenceId : CrossKindReentryEvidenceId
            effectiveReentryCount : int
            sameHotNodeCount : int
            rootReceiptCount : int
            lastRootReceiptAgeMs : int
        }

        type HotReplayObligationId =
            | HotReplayObligationTermSameKind
            | HotReplayObligationTySameKind
            | HotReplayObligationTermToTy
            | HotReplayObligationTyToTerm
            | HotReplayObligationCrossKindUnknown

        let private hotReplayObligationText = function
            | HotReplayObligationTermSameKind -> "term_same_kind_reentry"
            | HotReplayObligationTySameKind -> "ty_same_kind_reentry"
            | HotReplayObligationTermToTy -> "term_to_ty"
            | HotReplayObligationTyToTerm -> "ty_to_term"
            | HotReplayObligationCrossKindUnknown -> "cross_kind_unknown"

        let private hotReplayObligationFor activeDriverKind cellKind =
            match activeDriverKind, cellKind with
            | "term", "term" -> HotReplayObligationTermSameKind
            | "ty", "ty" -> HotReplayObligationTySameKind
            | "term", "ty" -> HotReplayObligationTermToTy
            | "ty", "term" -> HotReplayObligationTyToTerm
            | _ -> HotReplayObligationCrossKindUnknown

        let mutable private crossKindLastHotNodeId = HotQueueDominantNodeUnknown
        let mutable private crossKindSameHotNodeCount = 0
        let mutable private crossKindLastRootReceiptCount = 0
        let mutable private crossKindLastRootReceiptMs = 0L
        let mutable private pendingStarvationStartMs = 0L

        let private hotQueueNodeIdSame (a: HotQueueNodeId) (b: HotQueueNodeId) =
            match a, b with
            | HotQueueNode x, HotQueueNode y -> x = y
            | _ -> false

        let private hotQueueNodeIdKnown = function
            | HotQueueNode _ -> true
            | HotQueueDominantNodeUnknown -> false

        let private crossKindRootReceiptCount () =
            DiagJson.snapshotKindCount "eval_worklist_source_value_stored"
            + DiagJson.snapshotKindCount "eval_worklist_root_complete_replay_progress_marked"

        let private noteCrossKindReentryEvidence (hotQueue: HotQueueSample) (liveness: ReplayLivenessSnapshot) =
            let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let rootCount = crossKindRootReceiptCount()
            lock gate (fun () ->
                if rootCount > crossKindLastRootReceiptCount || crossKindLastRootReceiptMs <= 0L then
                    crossKindLastRootReceiptCount <- rootCount
                    crossKindLastRootReceiptMs <- nowMs
                if hotQueueNodeIdKnown hotQueue.hotQueueNodeId then
                    if hotQueueNodeIdSame hotQueue.hotQueueNodeId crossKindLastHotNodeId then
                        crossKindSameHotNodeCount <- crossKindSameHotNodeCount + 1
                    else
                        crossKindLastHotNodeId <- hotQueue.hotQueueNodeId
                        crossKindSameHotNodeCount <- 1
                else
                    crossKindSameHotNodeCount <- 0
                    crossKindLastHotNodeId <- HotQueueDominantNodeUnknown
                let rootAge =
                    if crossKindLastRootReceiptMs <= 0L then -1
                    else int (min 2147483647L (max 0L (nowMs - crossKindLastRootReceiptMs)))
                let physicalSameHotNodeCount = max crossKindSameHotNodeCount hotQueue.hotQueueCount
                let effective = max hotQueue.hotQueueCount (max liveness.queueDepth physicalSameHotNodeCount)
                let evidenceId =
                    if rootAge >= 500 && (liveness.queueDepth > 0 || liveness.activeDepth > 0) then CrossKindReentryRootStalled rootAge
                    elif physicalSameHotNodeCount >= 2 then CrossKindReentrySameHotNode physicalSameHotNodeCount
                    elif liveness.queueDepth >= 12 then CrossKindReentryQueueSurge liveness.queueDepth
                    else CrossKindReentryNoHotNode
                { evidenceId = evidenceId
                  effectiveReentryCount = effective
                  sameHotNodeCount = physicalSameHotNodeCount
                  rootReceiptCount = rootCount
                  lastRootReceiptAgeMs = rootAge })

        let private pendingStarvedMsSnapshot () =
            let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            let p = pendingCount()
            lock gate (fun () ->
                if p > 0 then
                    if pendingStarvationStartMs <= 0L then pendingStarvationStartMs <- nowMs
                    int (min 2147483647L (max 0L (nowMs - pendingStarvationStartMs)))
                else
                    pendingStarvationStartMs <- 0L
                    0)

        let private staleRetargetObligationShieldActive () =
            lock gate (fun () ->
                // ALPHA1372: force the option type to Frame.  Both Frame and
                // ReplayTask have a status field, and alpha1371 left this helper
                // unannotated; F# inferred ReplayTask option, then rejected the
                // terminal ledgers below as Frame option.
                let isStaleRetargetFrame (opt: Frame option) =
                    match opt with
                    | Some frame -> isRootCompleteStaleRetargetLiveReplayLivelockStatus frame.status
                    | None -> false
                isStaleRetargetFrame pinnedTerminalContract
                || isStaleRetargetFrame durableTerminalContract
                || DiagJson.snapshotKindCount "eval_worklist_bigstack_root_stale_retarget_handoff_decision" > 0)

        type ReplayObligationMacroTerminalDecisionId =
            | ReplayObligationMacroTerminalNone
            | ReplayObligationMacroTerminalStaleRetarget

        let private replayObligationMacroTerminalDecisionText = function
            | ReplayObligationMacroTerminalNone -> "none"
            | ReplayObligationMacroTerminalStaleRetarget -> "stale_retarget"

        let private replayObligationMacroTerminalDecisionFor () =
            if staleRetargetObligationShieldActive() then ReplayObligationMacroTerminalStaleRetarget
            else ReplayObligationMacroTerminalNone

        let private replayObligationMacroTerminalBlocksDeferral = function
            | ReplayObligationMacroTerminalStaleRetarget -> true
            | ReplayObligationMacroTerminalNone -> false

        type ReplayObligation = {
            obligation : ReplayObligationKind
            target : ReplayObligationTarget
            liveness : ReplayLivenessSnapshot
            reason : ReplayObligationReasonId
            repeat : int
            cap : int
        }

        // ALPHA1336: the assessment's key invariant as a DU.  If a cross-kind
        // obligation wants to yield while pending=0, no parked IVar/work item exists
        // that can resolve it.  That is terminal graph evidence, not scheduler liveness.
        type CrossKindYieldThrashDecisionId =
            | CrossKindYieldThrashPromoteRequeue
            | CrossKindYieldThrashDeferFreshRootPendingTail
            | CrossKindYieldThrashDeferZeroRepeatActiveTail
            | CrossKindYieldThrashHardPoisonPendingZero
            | CrossKindYieldThrashHardPoisonHotQueue
            | CrossKindYieldThrashHardPoisonReentryCap
            | CrossKindYieldThrashHardPoisonObligationCap
            | CrossKindYieldThrashHardPoisonPostScheduleCap
            | CrossKindYieldThrashHardPoisonStaleRetargetObligation
            | CrossKindYieldThrashHardPoisonRootStalled

        let private crossKindYieldThrashDecisionText = function
            | CrossKindYieldThrashPromoteRequeue -> "promote_requeue"
            | CrossKindYieldThrashDeferFreshRootPendingTail -> "defer_fresh_root_pending_tail"
            | CrossKindYieldThrashDeferZeroRepeatActiveTail -> "defer_zero_repeat_active_tail"
            | CrossKindYieldThrashHardPoisonPendingZero -> "hard_poison_pending_zero"
            | CrossKindYieldThrashHardPoisonHotQueue -> "hard_poison_hot_queue"
            | CrossKindYieldThrashHardPoisonReentryCap -> "hard_poison_reentry_cap"
            | CrossKindYieldThrashHardPoisonObligationCap -> "hard_poison_obligation_cap"
            | CrossKindYieldThrashHardPoisonPostScheduleCap -> "hard_poison_post_schedule_cap"
            | CrossKindYieldThrashHardPoisonStaleRetargetObligation -> "hard_poison_stale_retarget_obligation"
            | CrossKindYieldThrashHardPoisonRootStalled -> "hard_poison_root_stalled"

        let private crossKindYieldThrashDecisionFor (liveness: ReplayLivenessSnapshot) (hotQueue: HotQueueSample) (evidence: CrossKindReentryEvidence) =
            let repeatCap = 4
            let rootStalled = evidence.lastRootReceiptAgeMs >= 500
            let capBreached = evidence.effectiveReentryCount > repeatCap
            let sameHotCapBreached = evidence.sameHotNodeCount >= repeatCap
            let freshPendingTail =
                liveness.pending > 0
                && evidence.lastRootReceiptAgeMs >= 0
                && evidence.lastRootReceiptAgeMs < 5000
                && (liveness.queueDepth > 0 || liveness.activeDepth > 0 || liveness.hasProgressYield)
            // ALPHA1420: zero-repeat/pre-cap active tails are live probation authority.
            let zeroRepeatActiveTail =
                evidence.effectiveReentryCount < repeatCap
                && liveness.activeDepth > 0
                && (liveness.queueDepth > 0 || liveness.pending > 0 || liveness.hasProgressYield || evidence.rootReceiptCount > 0)
                && evidence.lastRootReceiptAgeMs >= 0
                && evidence.lastRootReceiptAgeMs < 5000
            if freshPendingTail && (capBreached || sameHotCapBreached) then
                CrossKindYieldThrashDeferFreshRootPendingTail
            elif zeroRepeatActiveTail then
                CrossKindYieldThrashDeferZeroRepeatActiveTail
            else
                match evidence.evidenceId with
                | _ when rootStalled && capBreached ->
                    CrossKindYieldThrashHardPoisonObligationCap
                | _ when rootStalled && sameHotCapBreached ->
                    CrossKindYieldThrashHardPoisonReentryCap
                | CrossKindReentryRootStalled ms when ms >= 500 && evidence.effectiveReentryCount >= 8 ->
                    CrossKindYieldThrashHardPoisonRootStalled
                | CrossKindReentrySameHotNode n when n >= repeatCap ->
                    CrossKindYieldThrashHardPoisonReentryCap
                | CrossKindReentryQueueSurge q when q >= 64 && evidence.lastRootReceiptAgeMs >= 500 ->
                    CrossKindYieldThrashHardPoisonRootStalled
                | _ ->
                    if evidence.effectiveReentryCount > repeatCap && liveness.activeDepth > 0 then
                        CrossKindYieldThrashHardPoisonObligationCap
                    elif hotQueue.hotQueueCount >= repeatCap then
                        CrossKindYieldThrashHardPoisonReentryCap
                    elif liveness.pending = 0 && (liveness.queueDepth > 0 || liveness.activeDepth > 0) then
                        if hotQueue.hotQueueCount >= repeatCap then CrossKindYieldThrashHardPoisonHotQueue
                        else CrossKindYieldThrashHardPoisonPendingZero
                    else CrossKindYieldThrashPromoteRequeue

        // ALPHA1350: dynamic-join reentrant replay with p=0 is a closed DU.
        // There is no parked continuation that can clear the reentrancy lock, so
        // yielding/requeueing is mathematically useless.  Fail closed instead of
        // manufacturing another scheduler grace loop.
        type ReentrantReplayLivelockDecisionId =
            | ReentrantReplayContinueActive
            | ReentrantReplayHardPoisonPendingZero

        let private reentrantReplayLivelockDecisionText = function
            | ReentrantReplayContinueActive -> "continue_active"
            | ReentrantReplayHardPoisonPendingZero -> "hard_poison_pending_zero"

        let private reentrantReplayLivelockDecisionFor (liveness: ReplayLivenessSnapshot) =
            if liveness.pending = 0 then ReentrantReplayHardPoisonPendingZero
            else ReentrantReplayContinueActive

        let private replayObligationKindText = function
            | ReplayObligationRun -> "run"
            | ReplayObligationDefer -> "defer"
            | ReplayObligationBlock -> "block"

        let private replayObligationStatusText obligation =
            match obligation.obligation with
            | ReplayObligationRun -> "semantic_replay_obligation_run"
            | ReplayObligationDefer -> "semantic_replay_obligation_deferred"
            | ReplayObligationBlock -> "semantic_replay_obligation_blocked"

        let private captureReplayLiveness () =
            let pending = pendingCount()
            let queueDepth = replayQueueDepth()
            let activeDepth = lock gate (fun () -> replayDriverActiveDepth)
            let hasDeferredCell = EvalReplayValueStore.hasDeferredReplayCell()
            let hasProgressYield = hasProgressYield()
            let kind =
                if hasProgressYield then ReplayObligationProgressYield
                elif hasDeferredCell then ReplayObligationDeferredCell
                elif activeDepth > 0 then ReplayObligationActive
                elif queueDepth > 0 then ReplayObligationQueued
                elif pending > 0 then ReplayObligationPendingOnly
                else ReplayObligationQuiescent
            { pending = pending
              queueDepth = queueDepth
              activeDepth = activeDepth
              payloadStatus = semanticPayloadStatus()
              hasDeferredCell = hasDeferredCell
              hasProgressYield = hasProgressYield
              kind = kind }

        // ALPHA981: this helper must not shadow the typed replayDriverForKind above.
        // The typed helper is EvalKind -> ReplayDriverId; this one renders the
        // obligation target at the JSON/status boundary from a raw cell.kind tag.
        // Keeping the names distinct prevents F# from resolving the parent-resume
        // pipeline to the string helper and producing FS0001 at the later replay driver site.
        let private replayDriverTextForCellKind (kind: string) =
            match evalKindOfString kind with
            | EvalTerm -> replayDriverToString TermReplayDriver
            | EvalTy -> replayDriverToString TyReplayDriver
            | _ -> "unknown_replay_driver"

        // ALPHA1372: must be defined before emitReplayObligation, which now
        // reports hot_oblig_du from the active ReplayTask.
        let private replayTaskDriverKind (task: ReplayTask) =
            if task.driver.StartsWith("term_", StringComparison.Ordinal) then "term"
            elif task.driver.StartsWith("ty_", StringComparison.Ordinal) then "ty"
            else "unknown"

        let private replayObligationTargetFromCell (cell: ReplayCell) =
            { kind = cell.kind
              shape = cell.shape
              site = cell.site
              nodeId = cell.nodeId
              driver = replayDriverTextForCellKind cell.kind }

        let private makeReplayObligation obligation reason repeat cap cell =
            { obligation = obligation
              target = replayObligationTargetFromCell cell
              liveness = captureReplayLiveness()
              reason = reason
              repeat = repeat
              cap = cap }

        let private makeReplayObligationFromText obligation reason repeat cap cell =
            makeReplayObligation obligation (replayObligationReasonOfString reason) repeat cap cell

        let private emitReplayObligation event kindName obligation =
            let reasonText = replayObligationReasonText obligation.reason
            let activeDriverKind =
                lock gate (fun () ->
                    match replayQueue with
                    | activeTask :: _ -> replayTaskDriverKind activeTask
                    | [] -> obligation.target.kind)
            let hotObligationDu =
                hotReplayObligationText (hotReplayObligationFor activeDriverKind obligation.target.kind)
            let pStarvedMs = pendingStarvedMsSnapshot()
            let macroTerminalDecision = replayObligationMacroTerminalDecisionFor()
            DiagJson.emit (
                sprintf "{\"kind\":%s,\"event\":%s,\"status\":%s,\"obligation\":%s,\"reason\":%s,\"reason_du\":%s,\"liveness_du\":%s,\"target_kind\":%s,\"target_shape\":%s,\"target_site\":%s,\"target_node_id\":%d,\"target_driver\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"payload_status\":%s,\"has_deferred_cell\":%b,\"has_progress_yield\":%b,\"repeat\":%d,\"cap\":%d,\"hot_oblig_du\":%s,\"p_starved_ms\":%d,\"macro_terminal_du\":%s,\"single_flight\":1,\"next\":%s}"
                    (esc kindName) (esc event) (esc (replayObligationStatusText obligation)) (esc (replayObligationKindText obligation.obligation)) (esc reasonText) (esc reasonText) (esc (replayObligationLivenessKindText obligation.liveness.kind))
                    (esc obligation.target.kind) (esc obligation.target.shape) (esc obligation.target.site) obligation.target.nodeId (esc obligation.target.driver)
                    obligation.liveness.pending obligation.liveness.queueDepth obligation.liveness.activeDepth (esc obligation.liveness.payloadStatus) obligation.liveness.hasDeferredCell obligation.liveness.hasProgressYield
                    obligation.repeat obligation.cap (esc hotObligationDu) pStarvedMs (esc (replayObligationMacroTerminalDecisionText macroTerminalDecision)) (esc obligation.target.driver))



        let tryPinnedReplayPayloadMissing () =
            lock gate (fun () -> pinnedReplayPayloadMissing)

        // ALPHA364: distinguish local leaf value resolution from root replay completion.
        // Alpha363 proved the old gate was still too permissive: a single EV leaf could mark
        // semantic_leaf_complete, trigger retry_after_replay_root_complete if not gated, and let an unstable write
        // path emit a tiny residual. Until a parent-continuation stack proves the root frame, local
        // value resolutions are semantic_leaf_complete and remain fail-closed.
        let hasReplayPartial () =
            lock gate (fun () ->
                match frontier with
                | Some frame when frame.status = "semantic_step_partial" || frame.status = "semantic_step_done" || frame.status = "semantic_leaf_complete" || frame.status = "semantic_replay_obligation_deferred" || frame.status = "semantic_parent_continuation_cycle_blocked" || frame.status = "semantic_type_variable_value_missing_blocked" || frame.status = "semantic_stale_root_retarget_blocked" || frame.status = "semantic_replay_driver_exception_blocked" || frame.status = "semantic_replay_payload_missing_blocked" || frame.status = "semantic_record_with_value_blocked" || frame.status = "semantic_seq_type_error_blocked" || frame.status = "semantic_replay_child_schedule_repeat_blocked" || frame.status = "semantic_macro_thunk_missing_blocked" || frame.status = "semantic_tjoinpoint_stepper_blocked" || frame.status = "semantic_literal_op_body_stepper_blocked" || frame.status = "semantic_let_success_apply_exception_blocked" || frame.status = "semantic_let_success_all_ready_apply_blocked" || frame.status = "semantic_let_success_apply_continuation_blocked" || frame.status = "semantic_apply_continuation_exception_blocked" || frame.status = "semantic_deferred_function_replay_exception_blocked" -> true
                | Some frame ->
                    match frame.semanticCell with
                    | Some cell when cell.status = "semantic_step_partial" || cell.status = "semantic_step_done" || cell.status = "semantic_leaf_complete" || cell.status = "semantic_replay_obligation_deferred" || cell.status = "semantic_parent_continuation_cycle_blocked" || cell.status = "semantic_type_variable_value_missing_blocked" || cell.status = "semantic_stale_root_retarget_blocked" || cell.status = "semantic_replay_driver_exception_blocked" || cell.status = "semantic_replay_payload_missing_blocked" || cell.status = "semantic_record_with_value_blocked" || cell.status = "semantic_seq_type_error_blocked" || cell.status = "semantic_replay_child_schedule_repeat_blocked" || cell.status = "semantic_macro_thunk_missing_blocked" || cell.status = "semantic_tjoinpoint_stepper_blocked" || cell.status = "semantic_literal_op_body_stepper_blocked" || cell.status = "semantic_let_success_apply_exception_blocked" || cell.status = "semantic_let_success_all_ready_apply_blocked" || cell.status = "semantic_let_success_apply_continuation_blocked" || cell.status = "semantic_apply_continuation_exception_blocked" || cell.status = "semantic_deferred_function_replay_exception_blocked" -> true
                    | _ -> false
                | None -> false)

        let hasReplayComplete () =
            lock gate (fun () ->
                match frontier with
                | Some frame when frame.status = "semantic_root_complete" -> true
                | Some frame ->
                    match frame.semanticCell with
                    | Some cell when cell.status = "semantic_root_complete" -> true
                    | _ -> false
                | None -> false)

        // ALPHA410: root-complete witnesses are kind-local for evaluator returns.
        // Alpha409 proved a term frontier could complete, after which a ty entry
        // incorrectly treated that term completion as a missing type value.
        // Keep the global witness for coarse diagnostics/write gating, but require
        // the frame or attached cell to match the caller kind before returning ty/term.
        // ALPHA411: active fuses are also kind-local.  Alpha410 proved the completed-kind
        // reset, then exposed a live ty fuse (file_system.spi:993) being consumed by
        // term_entry_global_fuse as a missing term value.  Reset active cross-kind fuses
        // before value-missing diagnostics so the requested evaluator can proceed normally.
        let frameReplayCompleteKind (kind: string) (frame: Frame) =
            // ALPHA448: a frame-level semantic_root_complete is not a proof for a newly
            // attached same-kind cell unless that cell is also complete.  Alpha447 proved
            // the old rule can keep attempting build for listm.spi:6 while the live cell
            // is a different TJoinPoint' at runtime.spi:330.
            let cellComplete =
                match frame.semanticCell with
                | Some cell when cell.kind = kind && cell.status = "semantic_root_complete" -> true
                | _ -> false
            let frameComplete =
                frame.kind = kind
                && frame.status = "semantic_root_complete"
                && (match frame.semanticCell with Some _ -> cellComplete | None -> true)
            frameComplete || cellComplete

        let frameReplayCompleteAny (frame: Frame) =
            let frameComplete = frame.status = "semantic_root_complete"
            let cellComplete =
                match frame.semanticCell with
                | Some cell when cell.status = "semantic_root_complete" -> true
                | _ -> false
            frameComplete || cellComplete

        let private rootCompleteFingerprintLocked () =
            match frontier with
            | Some frame when frameReplayCompleteAny frame ->
                let cellKey =
                    match frame.semanticCell with
                    | Some cell -> sprintf "%s:%s:%s:cursor=%d:step=%d:site=%s" cell.kind cell.shape cell.status cell.cursor cell.step cell.site
                    | None -> "cell:none"
                // ALPHA429: stable root-complete is semantic, but not oblivious to parent-continuation progress.
                // Alpha428 proved the ledger finally works, yet it also false-positive aborted while
                // the parent replay was still advancing through semantic_step_partial -> parent_resume ->
                // semantic_root_complete.  Keep node allocation ids out, but include replay cursor/step/site
                // so a genuinely moving parent continuation does not look like the same terminal proof.
                sprintf "%s|%s|%s|cursor=%d|trace=%d|frame_status=%s|queue=%d|%s" frame.kind frame.key frame.site frame.cursor frame.trace.Length frame.status replayQueue.Length cellKey
            | _ -> ""

        let private selectedFrontierFingerprintLocked (frame: Frame) =
            let cellKey =
                match frame.semanticCell with
                | Some cell -> sprintf "%s:%s:%s:cursor=%d:step=%d:site=%s" cell.kind cell.shape cell.status cell.cursor cell.step cell.site
                | None -> "cell:none"
            sprintf "%s|%s|%s|status=%s|cursor=%d|trace=%d|queue=%d|%s" frame.kind frame.key frame.site frame.status frame.cursor frame.trace.Length replayQueue.Length cellKey

        let private noteStableRootSelectedFrontierLocked (blockedRootKey: string) (selected: Frame) =
            let selectedKey = blockedRootKey + "=>" + selectedFrontierFingerprintLocked selected
            if selectedKey = stableRootSelectedKey then
                stableRootSelectedCount <- stableRootSelectedCount + 1
            else
                stableRootSelectedKey <- selectedKey
                stableRootSelectedCount <- 1
            stableRootSelectedCount, selectedKey

        let private noteSelectedFrontierStepperReplayLocked (key: string) =
            let mutable prior = 0
            let nextCount = if selectedFrontierStepperReplayAttempts.TryGetValue(key, &prior) then prior + 1 else 1
            selectedFrontierStepperReplayAttempts.[key] <- nextCount
            nextCount

        let noteRootCompleteHandoff () =
            lock gate (fun () ->
                let key = rootCompleteFingerprintLocked ()
                if System.String.IsNullOrWhiteSpace key then
                    stableRootCompleteKey <- ""
                    stableRootCompleteCount <- 0
                    0, "none"
                else
                    if key = stableRootCompleteKey then
                        stableRootCompleteCount <- stableRootCompleteCount + 1
                    else
                        stableRootCompleteKey <- key
                        stableRootCompleteCount <- 1
                    stableRootCompleteCount, key)

        let hasReplayCompleteKind (kind: string) =
            lock gate (fun () ->
                match frontier with
                | Some frame -> frameReplayCompleteKind kind frame
                | None -> false)

        let hasReplayCompleteOtherKind (kind: string) =
            lock gate (fun () ->
                match frontier with
                | Some frame -> frameReplayCompleteAny frame && frame.kind <> kind
                | None -> false)

        let private rememberReplayRootComplete (event: string) (outcome: string) (cell: ReplayCell) =
            replayRootCompleteWitnessUtc <- System.DateTime.UtcNow
            replayRootCompleteWitnessSummary <- sprintf "event=%s outcome=%s cell=%s" event outcome (formatCell cell)

        let hasReplayCompleteWriteWitness () =
            lock gate (fun () ->
                let frontierComplete =
                    match frontier with
                    | Some frame when frameOrCellIsRootComplete frame -> true
                    | Some _ -> false
                    | None -> false
                if frontierComplete then true
                else
                    let noLiveReplay =
                        pendingCount() = 0
                        && replayQueueDepth() = 0
                        && replayDriverActiveDepthValue() = 0
                    let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                    noLiveReplay
                    && replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                    && ageMs >= 0.0
                    && ageMs <= replayRootCompleteWitnessWindowMs)

        let hasFreshReplayRootWitness () =
            lock gate (fun () ->
                let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                && ageMs >= 0.0
                && ageMs <= replayRootCompleteWitnessWindowMs)

        let replayCompleteWriteWitnessSummary () =
            lock gate (fun () ->
                if replayRootCompleteWitnessUtc = System.DateTime.MinValue then "none"
                else sprintf "%s age_ms=%.0f" replayRootCompleteWitnessSummary ((System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds))

        let private frameLooksObsoleteAfterRootWitness (frame: Frame) =
            let status = if System.Object.ReferenceEquals(frame.status,null) then "" else frame.status
            let reason = if System.Object.ReferenceEquals(frame.reason,null) then "" else frame.reason
            let cellStatus =
                match frame.semanticCell with
                | Some cell when not (System.Object.ReferenceEquals(cell.status,null)) -> cell.status
                | _ -> ""
            let rootComplete = status = "semantic_root_complete" || cellStatus = "semantic_root_complete"
            (not rootComplete)
            && (status.Contains("stale", System.StringComparison.Ordinal)
                || reason.Contains("stale", System.StringComparison.Ordinal)
                || status = "continuation_envelope"
                || status = "semantic_step_partial")

        let heartbeatRootWitnessQuiescenceSweep () =
            try
                let beforeCount, afterCount, dropped, rootSite, writeWitness =
                    lock gate (fun () ->
                        let countPendingLocked () =
                            let mutable n = 0
                            let seen = System.Collections.Generic.HashSet<string>()
                            let add (opt: Frame option) =
                                match opt with
                                | Some frame ->
                                    let k = frame.kind + "|" + frame.key + "|" + frame.site
                                    if seen.Add k then n <- n + 1
                                | None -> ()
                            add frontier
                            add frontierTerm
                            add frontierTy
                            n
                        let frameRootComplete (opt: Frame option) =
                            match opt with
                            | Some frame when frame.status = "semantic_root_complete" -> true
                            | Some frame ->
                                match frame.semanticCell with
                                | Some cell when cell.status = "semantic_root_complete" -> true
                                | _ -> false
                            | None -> false
                        let rootOpt =
                            match frontier with
                            | Some f when frameRootComplete (Some f) -> Some f
                            | _ ->
                                match frontierTerm with
                                | Some f when frameRootComplete (Some f) -> Some f
                                | _ ->
                                    match frontierTy with
                                    | Some f when frameRootComplete (Some f) -> Some f
                                    | _ -> None
                        let frontierComplete = rootOpt.IsSome
                        let noReplayQueue = replayQueue.IsEmpty
                        let writeWitness =
                            frontierComplete
                            || (replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                                && (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds <= replayRootCompleteWitnessWindowMs)
                        let beforeCount = countPendingLocked()
                        let rootSite = match rootOpt with Some f -> f.site | None -> "missing_root_frontier"
                        if writeWitness && noReplayQueue && beforeCount > 0 then
                            let mutable dropped = 0
                            let scrub (opt: Frame option) =
                                match opt with
                                | Some f when frameLooksObsoleteAfterRootWitness f ->
                                    dropped <- dropped + 1
                                    None
                                | other -> other
                            frontier <- scrub frontier
                            frontierTerm <- scrub frontierTerm
                            frontierTy <- scrub frontierTy
                            if dropped > 0 then
                                replayDriverStackFenceQueued <- false
                                replayDriverStackFenceQueuedSinceMs <- 0L
                                progressYieldCount <- 0
                            beforeCount, countPendingLocked(), dropped, rootSite, writeWitness
                        else beforeCount, beforeCount, 0, rootSite, writeWitness)
                if dropped > 0 then
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_root_witness_quiescence_sweep\",\"event\":\"heartbeat_no_work_stall\",\"pending_before\":%d,\"pending_after\":%d,\"dropped_stale_frontiers\":%d,\"root_site\":%s,\"write_witness\":%b,\"queue_depth\":%d,\"active_depth\":%d,\"single_flight\":1,\"next\":\"retry_clean_buildfile_after_stale_frontier_sweep\"}"
                            beforeCount afterCount dropped (esc rootSite) writeWitness (replayQueueDepth()) (replayDriverActiveDepthValue()))
                dropped
            with _ -> 0

        // ALPHA439: only completed semantic states are absorbing for the bounded
        // trampoline.  Alpha438 proved that treating semantic_step_partial as terminal
        // strands a real child replay at cursor=trace_len: ESeq schedules its first
        // child EApply, the child reports semantic_step_partial, and retry_stop aborts
        // with explicit_eval_worklist_real_stepper_required instead of building the
        // next replay continuation.  Keep root/leaf absorbing to preserve alpha389's
        // no-downgrade invariant, but let partial/done states flow back into the
        // continuation adapter when their trace cursor is exhausted.
        let private isSemanticTerminalStatus (status: string) =
            status = "semantic_root_complete"
            || status = "semantic_leaf_complete"
            || status = "semantic_parent_continuation_cycle_blocked"
            || status = semanticStatusToString SemanticRootCompleteStaleRetargetPendingNoQueueBlocked
            || status = "semantic_type_variable_value_missing_blocked"
            || status = "semantic_stale_root_retarget_blocked"
            || status = "semantic_replay_driver_exception_blocked"
            || status = "semantic_replay_payload_missing_blocked"
            || status = "semantic_seq_type_error_blocked"
            || status = "semantic_replay_child_schedule_repeat_blocked"
            || status = "semantic_replay_fingerprint_repeat_blocked"
            || status = "semantic_joinpoint_term_stepper_blocked"
            || status = "semantic_macro_thunk_missing_blocked"
            || status = "semantic_tjoinpoint_stepper_blocked"
            || status = "semantic_joinpoint_value_blocked"
            || status = "semantic_literal_op_body_stepper_blocked"
            || status = "semantic_let_success_apply_exception_blocked"
            || status = "semantic_let_success_all_ready_apply_blocked"
            || status = "semantic_let_success_apply_continuation_blocked"
            || status = "semantic_nominal_constructor_stepper_blocked"
            || status = "semantic_type_apply_forall_body_stepper_blocked"
            || status = "semantic_apply_continuation_exception_blocked"
            || status = "semantic_deferred_function_replay_exception_blocked"

        let private semanticTerminalNext (status: string) =
            if status = "semantic_root_complete" then "attempt_build"
            elif status = "semantic_leaf_complete" then "explicit_eval_worklist_parent_continuation_required"
            elif status = "semantic_parent_continuation_cycle_blocked" then "explicit_eval_worklist_parent_continuation_cycle_required"
            elif status = semanticStatusToString SemanticRootCompleteStaleRetargetPendingNoQueueBlocked then "explicit_eval_worklist_root_complete_stale_retarget_required"
            elif status = "semantic_type_variable_value_missing_blocked" then "explicit_eval_worklist_type_variable_env_required"
            elif status = "semantic_stale_root_retarget_blocked" then "explicit_eval_worklist_stale_root_retarget_required"
            elif status = "semantic_replay_driver_exception_blocked" then "explicit_eval_worklist_replay_driver_exception_required"
            elif status = "semantic_replay_payload_missing_blocked" then "explicit_eval_worklist_replay_payload_required"
            elif status = "semantic_seq_type_error_blocked" then "explicit_eval_worklist_seq_type_error_required"
            elif status = "semantic_replay_child_schedule_repeat_blocked" then "explicit_eval_worklist_replay_child_schedule_repeat_required"
            elif status = "semantic_replay_fingerprint_repeat_blocked" then "explicit_eval_worklist_replay_fingerprint_repeat_required"
            elif status = "semantic_joinpoint_term_stepper_blocked" then "explicit_eval_worklist_joinpoint_term_stepper_required"
            elif status = "semantic_macro_thunk_missing_blocked" then "explicit_eval_worklist_macro_thunk_required"
            elif status = "semantic_tjoinpoint_stepper_blocked" then "explicit_eval_worklist_tjoinpoint_stepper_required"
            elif status = "semantic_joinpoint_value_blocked" then "explicit_eval_worklist_joinpoint_value_required"
            elif status = "semantic_literal_op_body_stepper_blocked" then "explicit_eval_worklist_literal_op_body_stepper_required"
            elif status = "semantic_let_success_apply_exception_blocked" then "explicit_eval_worklist_let_success_apply_exception_required"
            elif status = "semantic_let_success_all_ready_apply_blocked" then "explicit_eval_worklist_let_success_all_ready_apply_required"
            elif status = "semantic_let_success_apply_continuation_blocked" then "explicit_eval_worklist_let_success_apply_continuation_required"
            elif status = "semantic_nominal_constructor_stepper_blocked" then "explicit_eval_worklist_nominal_constructor_stepper_required"
            elif status = "semantic_type_apply_forall_body_stepper_blocked" then "explicit_eval_worklist_type_apply_forall_body_stepper_required"
            elif status = "semantic_apply_continuation_exception_blocked" then "explicit_eval_worklist_apply_continuation_exception_required"
            elif status = "semantic_deferred_function_replay_exception_blocked" then "explicit_eval_worklist_deferred_function_replay_exception_required"
            else "explicit_eval_worklist_real_stepper_required"

        let private semanticPayloadOf (frame: Frame) =
            match frame.semanticCell, frame.semanticPayload with
            | Some cell, _ -> formatCellPayload cell
            | _, Some p when not (String.IsNullOrWhiteSpace p) -> p
            | _ ->
                match trySemanticCellForFrame frame with
                | Some cell -> formatCellPayload cell
                | None -> "semantic_eval_payload_missing"

        let private semanticCellOf (frame: Frame) =
            match frame.semanticCell with
            | Some cell -> Some cell
            | None -> trySemanticCellForFrame frame

        let private replayKey (frame: Frame) =
            sprintf "%s|%s|%s|%d|%d" frame.kind frame.key frame.site frame.cursor frame.trace.Length

        let private replayDriverFor (frame: Frame) =
            match frame.kind with
            | "term" -> "term_replay_driver"
            | "ty" -> "ty_replay_driver"
            | _ -> "unknown_replay_driver"

        // ALPHA465/1372: replayTaskDriverKind moved above emitReplayObligation
        // because generic obligation telemetry needs it before this point.

        let private activeReplayDriverKindMismatch (kind: string) =
            lock gate (fun () ->
                match replayQueue with
                | task :: _ ->
                    let taskKind = replayTaskDriverKind task
                    taskKind <> "unknown" && taskKind <> kind
                | [] -> false)

        let private replayDriverNextFor (task: ReplayTask) (hasCell: bool) (hasSemantic: bool) =
            match task.driver, hasCell, hasSemantic with
            | "term_replay_driver", true, _ -> "execute_term_eval_stepper"
            | "ty_replay_driver", true, _ -> "execute_ty_eval_stepper"
            | "term_replay_driver", false, true -> "wire_term_typed_replay_cell"
            | "ty_replay_driver", false, true -> "wire_ty_typed_replay_cell"
            | "term_replay_driver", false, false -> "wire_term_eval_payload"
            | "ty_replay_driver", false, false -> "wire_ty_eval_payload"
            | _, true, _ -> "execute_unknown_eval_stepper"
            | _, false, true -> "wire_unknown_typed_replay_cell"
            | _ -> "wire_unknown_eval_payload"

        // ALPHA349: typed replay-cell driver commit gate.
        //
        // Alpha347/348 proved the semantic payload can reach the replay driver and dispatch a reducer. It was still a
        // string envelope, so the driver could only say "wire_term_eval_stepper". Alpha347
        // keeps that textual envelope for diagnostics, but also carries a ReplayCell record
        // and emits a deterministic eval_worklist_replay_step. This is the first stack-safe
        // stepper boundary: it does not recurse into term/ty yet; it hands a typed cell to the
        // future executor and deduplicates repeated driver ticks.
        // ALPHA498: drain one preserved deferred replay child after the active driver
        // fully unwinds.  Alpha497 intentionally suppressed cross-kind/reentrant pokes while a
        // parent/root replay was already reducing; the missing piece is the safe handoff after
        // that active tick is done and no replay task remains queued.
        let private tryScheduleDeferredAfterActiveDriver (event: string) =
            let deferredOpt =
                // ALPHA916: annotated test bodies now arrive as the next concrete
                // replay obligation after the live-cycle defer.  Drain them before
                // macro/type catch-alls so the explicit EAnnotTest stepper gets a tick
                // instead of being hidden behind an older fingerprint-repeat terminal.
                match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EAnnotTest" -1 with
                | Some cell -> Some cell
                | None ->
                    // ALPHA971: direct EAnnot wrappers can surface after root-complete
                    // handoff while their inner/type children are still live. Drain
                    // them before macro/type catch-alls so the annotation spine keeps
                    // its own replay tick instead of being buried behind stale root proof.
                    match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EAnnot" -1 with
                    | Some cell -> Some cell
                    | None ->
                        // ALPHA562: do not starve term macro apply-args behind the ty catch-all.
                        // Runtime 561 showed EMacro apply_arg_child was repeatedly scheduled while
                        // a ty replay driver remained active, then terminalized as child_schedule_repeat.
                        match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EMacro" -1 with
                        | Some cell -> Some cell
                        | None ->
                            match EvalReplayValueStore.tryTakeDeferredReplayCell "ty" "TFun" -1 with
                            | Some cell -> Some cell
                            | None ->
                                match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EFun'" -1 with
                                | Some cell -> Some cell
                                | None ->
                                    // Prefer a live EJoinPoint' obligation before the
                                    // generic term catch-all. Runtime evidence showed the pinned terminal
                                    // at sm'_real.spir:285 while an EUnitTest/term replay queue was still
                                    // alive; this priority keeps joinpoint value materialization typed.
                                    match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EJoinPoint'" -1 with
                                    | Some cell -> Some cell
                                    | None ->
                                        match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "EUnitTest" -1 with
                                        | Some cell -> Some cell
                                        | None ->
                                            match EvalReplayValueStore.tryTakeDeferredReplayCell "term" "" -1 with
                                            | Some cell -> Some cell
                                            | None -> EvalReplayValueStore.tryTakeDeferredReplayCell "ty" "" -1
            match deferredOpt with
            | Some deferredCell ->
                let replayCell : ReplayCell = {
                    kind = deferredCell.kind
                    shape = deferredCell.shape
                    nodeId = deferredCell.nodeId
                    envGlobalTerm = deferredCell.envGlobalTerm
                    envStackTerm = deferredCell.envStackTerm
                    envGlobalType = deferredCell.envGlobalType
                    envStackType = deferredCell.envStackType
                    seqLen = deferredCell.seqLen
                    cseDepth = deferredCell.cseDepth
                    traceDepth = deferredCell.traceDepth
                    site = deferredCell.site
                    cursor = deferredCell.cursor
                    step = deferredCell.step
                    status = "deferred_after_active_driver_ready"
                }
                let scheduled =
                    lock gate (fun () ->
                        if replayQueue.IsEmpty then
                            replaySeq <- replaySeq + 1L
                            let childDriver = replayCell.kind |> evalKindOfString |> replayDriverForKind (UnknownReplayDriver "unknown_replay_driver") |> replayDriverToString
                            let childKey = sprintf "deferred_after_active_driver|%s|%s|%d|%d" replayCell.kind replayCell.shape replayCell.nodeId replayCell.step
                            let childTask = { id = replaySeq; key = childKey; driver = childDriver; payload = formatCellPayload replayCell; status = "scheduled_replay"; event = event }
                            replayScheduledKey <- Some childKey
                            replayQueue <- [childTask]
                            true, childDriver, childKey, replaySeq
                        else
                            false, "", "", 0L)
                match scheduled with
                | true, childDriver, childKey, replayId ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_deferred_after_active_driver_scheduled\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"key\":%s,\"cell\":%s,\"queue_depth\":%d,\"single_flight\":1,\"next\":%s}"
                            (esc event) replayId (esc childDriver) (esc childKey) (esc (formatCell replayCell)) (replayQueueDepth()) (esc childDriver))
                    true
                | false, _, _, _ ->
                    EvalReplayValueStore.putDeferredReplayCell deferredCell
                    false
            | None -> false

        let private replayDriverStackFenceCap = 4

        // ALPHA1232: the 1231 assessment says the right frontier is not another
        // terminal: it is live parent-resume replay that is already queued/active
        // but can starve behind single-flight.  Model the handoff as a closed DU
        // before it becomes JSON text.
        type ParentResumeReplayDrainDecisionId =
            | ParentResumeReplayDrainNoop
            | ParentResumeReplayDrainAwaitActive
            | ParentResumeReplayDrainScheduleBackupTick
            | ParentResumeReplayDrainScheduleTailTick
            | ParentResumeReplayDrainHardStopPendingZero

        let private parentResumeReplayDrainDecisionText = function
            | ParentResumeReplayDrainNoop -> "noop"
            | ParentResumeReplayDrainAwaitActive -> "await_active"
            | ParentResumeReplayDrainScheduleBackupTick -> "schedule_backup_tick"
            | ParentResumeReplayDrainScheduleTailTick -> "schedule_tail_tick"
            | ParentResumeReplayDrainHardStopPendingZero -> "hard_stop_pending_zero"

        let private parentResumeReplayDrainDecisionShouldSchedule = function
            | ParentResumeReplayDrainScheduleBackupTick
            | ParentResumeReplayDrainScheduleTailTick -> true
            | ParentResumeReplayDrainNoop
            | ParentResumeReplayDrainAwaitActive
            | ParentResumeReplayDrainHardStopPendingZero -> false

        // ALPHA1520: 1519's live tail ended with same_node_parent_replay_cell_deferred
        // plus same_node_parent_replay_self_poke while q>0/p>0. Treat that as a
        // typed drain decision instead of a passive string-only await.
        type SameNodeParentReplayDrainDecisionId =
            | SameNodeParentReplayAwaitExistingTick
            | SameNodeParentReplayScheduleBackupTick
            | SameNodeParentReplayScheduleTailTick
            | SameNodeParentReplayHardStopPendingZero

        let private sameNodeParentReplayDrainDecisionText = function
            | SameNodeParentReplayAwaitExistingTick -> "await_existing_parent_replay_tick"
            | SameNodeParentReplayScheduleBackupTick -> "schedule_same_node_parent_replay_backup_tick"
            | SameNodeParentReplayScheduleTailTick -> "schedule_same_node_parent_replay_tail_tick"
            | SameNodeParentReplayHardStopPendingZero -> "hard_stop_same_node_parent_replay_pending_zero"

        let private sameNodeParentReplayDrainDecisionShouldSchedule = function
            | SameNodeParentReplayScheduleBackupTick
            | SameNodeParentReplayScheduleTailTick -> true
            | SameNodeParentReplayAwaitExistingTick
            | SameNodeParentReplayHardStopPendingZero -> false

        let private sameNodeParentReplayDrainDecisionFor queueDepth activeDepth pending =
            if pending <= 0 && queueDepth <= 0 && activeDepth <= 0 then SameNodeParentReplayHardStopPendingZero
            elif queueDepth > 0 && activeDepth <= replayDriverStackFenceCap then SameNodeParentReplayScheduleBackupTick
            elif queueDepth > 0 && pending > 0 then SameNodeParentReplayScheduleTailTick
            else SameNodeParentReplayAwaitExistingTick

        let private parentResumeReplayDrainDecisionFor (reason: string) queueDepth activeDepth pending =
            if pending = 0 && reason = "reentrant_replay_driver" then ParentResumeReplayDrainHardStopPendingZero
            elif pending = 0 && queueDepth <= 0 && activeDepth <= 0 then ParentResumeReplayDrainHardStopPendingZero
            else
                match replayObligationReasonOfString reason with
                | ReplayReasonParentResumeCellDeferred
                | ReplayReasonSameNodeParentReplayDeferred
                | ReplayReasonActiveReplayCellDeferred
                | ReplayReasonCrossKindActiveDriver
                | ReplayReasonDeferredChildCell ->
                    if queueDepth > 0 && activeDepth <= replayDriverStackFenceCap then ParentResumeReplayDrainScheduleBackupTick
                    elif queueDepth > 0 && activeDepth >= replayDriverStackFenceCap && pending > 0 then ParentResumeReplayDrainScheduleTailTick
                    elif queueDepth > 0 then ParentResumeReplayDrainAwaitActive
                    elif pending > 0 then ParentResumeReplayDrainScheduleBackupTick
                    else ParentResumeReplayDrainNoop
                | _ -> ParentResumeReplayDrainNoop

        let rec private runReplayDriver (event: string) =
            let activeDepthAfterEnter =
                lock gate (fun () ->
                    replayDriverActiveDepth <- replayDriverActiveDepth + 1
                    replayDriverActiveDepth)
            let scheduleReplayDriverTick (reason: string) (event': string) =
                let queueDepthAtYield, shouldScheduleRaw, decision, tickPressureId =
                    lock gate (fun () ->
                        let qd = replayQueue.Length
                        let nowMs = System.DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                        let staleQueued = replayDriverStackFenceQueued && replayDriverStackFenceQueuedSinceMs > 0L && nowMs - replayDriverStackFenceQueuedSinceMs > 100L
                        if staleQueued then replayDriverStackFenceQueued <- false
                        let tickPressureId = replayTickQueuePressureFor qd replayDriverActiveDepth replayDriverStackFenceQueued staleQueued
                        let decision = replayTickRequestDecisionFromPressure tickPressureId
                        let shouldSchedule = replayTickRequestDecisionShouldSchedule decision
                        // ALPHA951: a cooperative handoff with runnable queue is real scheduler progress.
                        // Count it for retry_stop so root-complete/pending-job terminals do not abort
                        // before the fresh replay tick has a chance to consume the queued continuation.
                        if qd > 0 then noteProgressYieldLocked ()
                        if shouldSchedule then
                            replayDriverStackFenceQueued <- true
                            replayDriverStackFenceQueuedSinceMs <- nowMs
                        qd, shouldSchedule, decision, tickPressureId)
                let pinnedParentReplayPoisonTerminalCommitted =
                    try
                        match tryPinnedTerminalContract() with
                        | Some pinned when isParentReplayCycleBreakPoisonedStatus pinned.status -> true
                        | _ -> false
                    with _ -> false
                let pendingGraphTerminalCommitCount =
                    DiagJson.snapshotKindCount "eval_worklist_stack_fence_hopac_override_pierced_repeat_cap"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_poison_hopac_override_pierced_live_tail"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_live_tail_override_deferred"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_shadow_timeout_pierced_repeat_cap_probation"
                    + DiagJson.snapshotKindCount "eval_worklist_parent_replay_cycle_break_poison_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_semantic_stale_retarget_shadow_timeout_pierced_missing_prefetch_cycle_break"
                    + DiagJson.snapshotKindCount "eval_worklist_if_unknown_return_condition_shadow_timeout_pierced_repeat_cap"
                    + DiagJson.snapshotKindCount "eval_worklist_if_unknown_return_condition_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_dynamic_record_key_bridge_tail_shadow_timeout_pierced_weak_pending_active_root"
                    + DiagJson.snapshotKindCount "eval_worklist_dynamic_record_key_bridge_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_idle_cross_kind_active_ty_sidecar_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_op_impl_required_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_bigstack_op_impl_required_hard_semantic_fail_closed"
                    + DiagJson.snapshotKindCount "eval_worklist_bigstack_op_impl_required_terminal_dispatched_before_ejp0021"
                    + DiagJson.snapshotKindCount "eval_worklist_idle_cross_kind_replay_driver_with_active_ty_sidecar_drain"
                    + DiagJson.snapshotKindCount "eval_worklist_small_queue_parent_replay_poison_shadow_timeout_pierced_repeat_cap_probation"
                    + DiagJson.snapshotKindCount "eval_worklist_deferred_child_cell_pending_graph_terminal_committed"
                    + DiagJson.snapshotKindCount "eval_worklist_native_cutover_backup_tick_suppressed"
                    + (if pinnedParentReplayPoisonTerminalCommitted then 1 else 0)
                let pendingGraphTerminalAlreadyCommitted =
                    pendingGraphTerminalCommitCount > 0 || pinnedParentReplayPoisonTerminalCommitted
                let nativeCutoverReasonRequestsLegacyTick =
                    reason.Contains("cooperative_replay_handoff", System.StringComparison.Ordinal)
                    || reason.Contains("parent_replay", System.StringComparison.Ordinal)
                    || reason.Contains("post_active_parent_resume", System.StringComparison.Ordinal)
                    || reason.Contains("cross_kind", System.StringComparison.Ordinal)
                    || reason.Contains("deferred_child_cell", System.StringComparison.Ordinal)
                    || reason.Contains("semantic_stale_retarget", System.StringComparison.Ordinal)
                    || reason.Contains("dynamic_record_key_bridge", System.StringComparison.Ordinal)
                    || reason.Contains("bridge_tail", System.StringComparison.Ordinal)
                    || reason.Contains("weak_pending_active_root", System.StringComparison.Ordinal)
                    || reason.Contains("reentrant_replay_driver", System.StringComparison.Ordinal)
                    || reason.Contains("if_unknown_return", System.StringComparison.Ordinal)
                    || reason.Contains("JPMethodUnknownRet", System.StringComparison.Ordinal)
                    || reason.Contains("explicit_eval_worklist_if_unknown_return_condition_required", System.StringComparison.Ordinal)
                    || reason.Contains("replay_commit_terminal", System.StringComparison.Ordinal)
                    || reason.Contains("stack_fence", System.StringComparison.Ordinal)
                    || reason.Contains("op_impl_required", System.StringComparison.Ordinal)
                    || reason.Contains("semantic_op_impl_required", System.StringComparison.Ordinal)
                    || reason.Contains("term_op_impl_required", System.StringComparison.Ordinal)
                    || reason.Contains("explicit_eval_worklist_op_impl_required", System.StringComparison.Ordinal)
                    || reason.Contains("hard_semantic_missing_impl", System.StringComparison.Ordinal)
                    || reason.Contains("hard_semantic_op_impl", System.StringComparison.Ordinal)
                    || reason.Contains("Conv/2", System.StringComparison.Ordinal)
                    || reason.Contains("repeat_cap", System.StringComparison.Ordinal)
                    || reason.Contains("blocked_repeat_cap", System.StringComparison.Ordinal)
                    || reason.Contains("surface_cascaded_terminal_repeat_cap_breach", System.StringComparison.Ordinal)
                    || reason.Contains("hard_poison_obligation", System.StringComparison.Ordinal)
                    || reason.Contains("live_tail_evidence_overrides_no_root_bypass", System.StringComparison.Ordinal)
                    || reason.Contains("replay_obligation_deferred_extended_live_tail", System.StringComparison.Ordinal)
                    || event'.Contains("minimal_heartbeat", System.StringComparison.Ordinal)
                    || event'.Contains("dynamic_record_key_bridge", System.StringComparison.Ordinal)
                    || event'.Contains("bridge_tail", System.StringComparison.Ordinal)
                    || event'.Contains("if_unknown_return", System.StringComparison.Ordinal)
                    || event'.Contains("replay_commit_terminal", System.StringComparison.Ordinal)
                    || event'.Contains("stack_fence", System.StringComparison.Ordinal)
                    || event'.Contains("op_impl_required", System.StringComparison.Ordinal)
                    || event'.Contains("hard_semantic_op_impl", System.StringComparison.Ordinal)
                    || event'.Contains("repeat_cap", System.StringComparison.Ordinal)
                    || event'.Contains("cache_write_parent_handoff", System.StringComparison.Ordinal)
                    || event'.Contains("term_entry", System.StringComparison.Ordinal)
                let nativeCutoverBackupTickSuppressed =
                    pendingGraphTerminalAlreadyCommitted
                    && nativeCutoverReasonRequestsLegacyTick
                    && (not (hasReplayCompleteWriteWitness())
                        || reason.Contains("parent_replay_cycle_break_poison", System.StringComparison.Ordinal)
                        || reason.Contains("parent_replay_status_preserved_repeat", System.StringComparison.Ordinal)
                        || reason.Contains("hard_poison_obligation", System.StringComparison.Ordinal)
                        || reason.Contains("live_tail_evidence_overrides_no_root_bypass", System.StringComparison.Ordinal)
                        || reason.Contains("replay_obligation_deferred_extended_live_tail", System.StringComparison.Ordinal)
                        || reason.Contains("dynamic_record_key_bridge", System.StringComparison.Ordinal)
                        || reason.Contains("bridge_tail", System.StringComparison.Ordinal)
                        || reason.Contains("weak_pending_active_root", System.StringComparison.Ordinal)
                        || reason.Contains("reentrant_replay_driver", System.StringComparison.Ordinal)
                        || reason.Contains("idle_cross_kind", System.StringComparison.Ordinal)
                        || reason.Contains("active_ty_sidecar", System.StringComparison.Ordinal)
                        || reason.Contains("cooperative_replay_handoff", System.StringComparison.Ordinal)
                        || reason.Contains("op_impl_required", System.StringComparison.Ordinal)
                        || reason.Contains("semantic_op_impl_required", System.StringComparison.Ordinal)
                        || reason.Contains("term_op_impl_required", System.StringComparison.Ordinal)
                        || reason.Contains("hard_semantic_missing_impl", System.StringComparison.Ordinal)
                        || pinnedParentReplayPoisonTerminalCommitted
                        || event'.Contains("cache_write_parent_handoff", System.StringComparison.Ordinal))
                let shouldSchedule = shouldScheduleRaw && not nativeCutoverBackupTickSuppressed
                if nativeCutoverBackupTickSuppressed then
                    lock gate (fun () ->
                        replayDriverStackFenceQueued <- false
                        replayDriverStackFenceQueuedSinceMs <- 0L)
                let cooperativeOwnerDu = replayHandoffOwnerToString (replayHandoffOwnerForState reason queueDepthAtYield activeDepthAfterEnter replayDriverStackFenceCap "semantic_step_partial")
                let cooperativeLiveness = captureReplayLiveness()
                let pendingAtYield = pendingCount()
