                                                                                    || why.IndexOf("runtime_function_apply_requires_dyn_typecheck", StringComparison.Ordinal) >= 0)
                                                                                && (detail.IndexOf("/DPair", StringComparison.Ordinal) >= 0
                                                                                    || why.IndexOf("/DPair", StringComparison.Ordinal) >= 0)
