                                                                                    sprintf "{\"kind\":\"eval_worklist_apply_function_body_dynamic_function_literal_tail_resolved\",\"event\":%s,\"node_id\":%d,\"shape\":%s,\"site\":%s,\"reason\":%s,\"detail\":%s,\"decision_du\":\"schedule_literal_tail_replay\",\"single_flight\":1,\"next\":\"resume_parent_replay_driver\"}"
                                                                                        (esc event) cellReady.nodeId (esc cellReady.shape) (esc cellReady.site) (esc why) (esc detail))
                                                                                compositeOrParent ("term_apply_function_body_dynamic_function_literal_tail_resolved:" + why + ":" + detail) cellReady
