                                                                                        sprintf "{\"kind\":\"eval_worklist_apply_function_body_dynamic_function_part_eval_tail_scheduled\",\"event\":%s,\"parent_node_id\":%d,\"body_node_id\":%d,\"body_shape\":%s,\"site\":%s,\"reason\":%s,\"detail\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"root_witness_activity\":%d,\"recoverable_bridge\":true,\"decision_du\":\"schedule_part_eval_body_replay\",\"single_flight\":1,\"next\":\"explicit_eval_worklist_function_body_stepper_required\"}"
