            // ALPHA1404: alpha1403 showed this pressure-worker branch surfacing repeat-cap
            // at q=80/a=4 while active_tail_quiescent=false, immediately before a later
            // no-root bypass accepted the same rank-83 terminal.  A live q>=16/a>0 tail is
            // probation evidence, not terminal authority; let it fall through to the bounded
            // pressure drain worker request below instead of emitting the cap-breach surface.
            let pressureRepeatCapStillLive = pressurePinnedRepeatCapBreached && initialQueueDepth >= 16 && initialActiveDepth > 0
            if (not scheduledAny) && activeTailPressureWorkerAllowed && pressurePinnedRepeatCapBreached && not pressureRepeatCapStillLive then
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_forced_pressure_drain_worker_cap_breach_surface\",\"event\":%s,\"reason\":%s,\"worker_decision_du\":%s,\"worker_defer_decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"qap\":\"%d/%d/%d\",\"attempts_suppressed\":%d,\"pressure_worker_trigger\":%s,\"evaluated_queue_depth\":%d,\"parent_repeat_count\":%d,\"parent_repeat_cap\":%d,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"active_tail_quiescent\":false,\"scheduled_async\":false,\"policy\":\"pressure_worker_repeat_cap_breach_outvotes_q_ge_16_tail_no_buildok\",\"single_flight\":1,\"next\":\"surface_cascaded_terminal\"}"
                        (esc event) (esc reason) (esc (replayWorkerDecisionText ReplayWorkerSurfaceCascadedTerminalRepeatCapBreach)) (esc (replayWorkerDeferDecisionText ReplayWorkerDeferBlockedRepeatCapBeforePressureWorker)) initialQueueDepth initialActiveDepth (pendingCount()) initialQueueDepth initialActiveDepth (pendingCount()) boundedAttempts (esc (if initialQueueDepth >= 16 then sprintf "q_ge_16(eval_q=%d)" initialQueueDepth else sprintf "mature_root_tail(eval_q=%d)" initialQueueDepth)) initialQueueDepth pressurePinnedRepeatCount pressurePinnedRepeatCap (esc pressurePinnedStatus) pressurePinnedRank (esc pressurePinnedSite) (esc pressurePinnedKey))
                scheduledAny <- true
            elif (not scheduledAny) && activeTailPressureWorkerAllowed then
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_forced_pressure_drain_worker_requested\",\"event\":%s,\"reason\":%s,\"worker_decision_du\":%s,\"worker_defer_decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"qap\":\"%d/%d/%d\",\"attempts_suppressed\":%d,\"pressure_worker_trigger\":%s,\"evaluated_queue_depth\":%d,\"parent_repeat_count\":%d,\"parent_repeat_cap\":%d,\"active_tail_quiescent\":false,\"policy\":\"alpha1327_bounded_active_tail_pressure_worker_q_ge_16_or_mature_root_tail_no_buildok\",\"single_flight\":1,\"next\":\"threadpool_replay_driver_tick_pressure_worker\"}"
                        (esc event) (esc reason) (esc (replayWorkerDecisionText ReplayWorkerPressureWorkerLiveTailYield)) (esc (replayWorkerDeferDecisionText ReplayWorkerDeferPressureWorkerLiveTailYieldAllowed)) initialQueueDepth initialActiveDepth (pendingCount()) initialQueueDepth initialActiveDepth (pendingCount()) boundedAttempts (esc (if initialQueueDepth >= 16 then sprintf "q_ge_16(eval_q=%d)" initialQueueDepth else sprintf "mature_root_tail(eval_q=%d)" initialQueueDepth)) initialQueueDepth pressurePinnedRepeatCount pressurePinnedRepeatCap)
                System.Threading.ThreadPool.QueueUserWorkItem(System.Threading.WaitCallback(fun _ ->
                    try
                        try
                            runReplayDriver event
                        with ex ->
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_forced_pressure_drain_worker_error\",\"event\":%s,\"reason\":%s,\"error_type\":%s,\"message\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_forced_pressure_drain_error\"}"
                                    (esc event) (esc reason) (esc (ex.GetType().Name)) (esc ex.Message) (replayQueueDepth()) (pendingCount()))
                    finally
                        lock gate (fun () ->
                            replayDriverStackFenceQueued <- false
                            replayDriverStackFenceQueuedSinceMs <- 0L))) |> ignore
                scheduledAny <- true
            elif (not scheduledAny) && initialActiveDepth > 0 then
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_forced_active_tail_quiescent_no_queue\",\"event\":%s,\"reason\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"attempts_suppressed\":%d,\"pressure_worker_trigger\":\"small_q_active_tail(eval_q=%d)\",\"evaluated_queue_depth\":%d,\"active_tail_quiescent\":%b,\"policy\":\"alpha1327_small_q_active_tail_suppressed_unless_mature_root_tail_no_buildok\",\"single_flight\":1,\"next\":\"continue_active_replay_or_fail_closed\"}"
                        (esc event) (esc reason) initialQueueDepth initialActiveDepth boundedAttempts initialQueueDepth initialQueueDepth (initialQueueDepth <= 0 && initialActiveDepth > 0))
            scheduledAny

        do EvalReplayValueStore.installParentCacheHandoffWake (fun () ->
            try
                // ALPHA1237: alpha1236 proved the cache-write callback drains
                // parent handoffs into replayQueue, but no replay driver was
                // scheduled afterwards.  The second callback is intentionally
                // separate from the drain callback: first commit/drain, then
                // ask the cooperative driver to run the queued parent work.
                let queueDepthBeforeWake = replayQueueDepth()
                let activeDepthBeforeWake = replayDriverActiveDepthValue()
                let wakeDecision =
                    lock gate (fun () ->
                        parentReplayDriverWakeDecisionFor replayQueue.Length replayDriverActiveDepth replayDriverStackFenceQueued)
                let scheduled =
                    replayDriverCooperativeTickFromGlobalFuse
                        "cache_write_parent_handoff_wake_callback"
                        "post_commit_parent_queue_driver_tick"
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_parent_handoff_driver_wake_requested\",\"event\":\"cache_write_parent_handoff_wake_callback\",\"decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"scheduled_async\":%b,\"pending\":%d%s,\"materialized_terminal_payload_du\":\"ParentCacheHandoffWake\",\"pending_graph_shard_state\":\"TerminalPayload(ParentCacheHandoffWake)\",\"jsonl_recycle_du\":\"emit_once_then_compact_parent_cache_handoff_wake\",\"single_flight\":1,\"next\":\"native_hopac_callback_or_threadpool_replay_driver_tick\"}"
                        (esc (parentReplayDriverWakeDecisionText wakeDecision)) queueDepthBeforeWake activeDepthBeforeWake scheduled (pendingCount()) (pendingGraphProofTupleJsonFields (proofTupleForParentCacheHandoffWake "cache_write_parent_handoff_wake_callback"))
                )
            with _ -> ())

        do
            DiagJson.setNoWorkStallPoke (fun () ->
                try
                    // ALPHA1142: the alpha1141 no-work worker started, then never
                    // reached its finished receipt.  The old first move called
                    // pendingCount()/replayQueueDepth(), both of which can wait on the
                    // evaluator gate while the heartbeat is trying to rescue that very
                    // gate.  Take a bounded snapshot first; if the evaluator still owns
                    // the gate, emit a reproducible gate-busy frontier and let the worker
                    // finish instead of leaving rescue_in_flight pinned forever.
                    let mutable gateTaken = false
                    let mutable gateBusy = false
                    let mutable qdBefore = -1
                    let mutable adBefore = -1
                    let mutable pendingBefore = -1
                    let mutable wasQueued = false
                    let mutable rootWitnessBefore = false
                    let mutable releasedActive = false
                    let gateBusySeen = DiagJson.noWorkRescueGateBusyCount()
                    let gateWaitMs = DiagJson.noWorkGateProbeWaitMs gateBusySeen
                    let probePolicy = DiagJson.noWorkGateProbePolicyText (DiagJson.noWorkGateProbePolicyFor gateBusySeen)
                    try
                        // Repeated gate_busy receipts showed that a fixed 64ms probe proved
                        // obstruction but could not distinguish a hot owner from a nearly-free gate.
                        // Escalate bounded waits by typed policy so the rescue can inspect more
                        // often without ever becoming an unbounded pin.
                        gateTaken <- System.Threading.Monitor.TryEnter(gate, gateWaitMs)
                        if gateTaken then
                            qdBefore <- replayQueue.Length
                            adBefore <- replayDriverActiveDepth
                            pendingBefore <- pendingCountUnlocked()
                            rootWitnessBefore <- hasReplayCompleteWriteWitness()
                            wasQueued <- replayDriverStackFenceQueued
                            replayDriverStackFenceQueued <- false
                            replayDriverStackFenceQueuedSinceMs <- 0L
                            let orphanedRootWitnessActive =
                                replayDriverActiveDepth > 0
                                && replayQueue.IsEmpty
                                && pendingBefore <= 0
                                && rootWitnessBefore
                            let orphanedDeferredActive =
                                // ALPHA1317: runtime 1316 still ended with q=0/a>0/p=2.
                                // In a no-work rescue window, a small pending/deferred tail plus
                                // an empty replay queue means active depth is stale ownership, not
                                // runnable work.  Clear the active counter only; do not promote any
                                // root/writer/codegen authority.
                                replayDriverActiveDepth > 0
                                && replayQueue.IsEmpty
                                && pendingBefore > 0
                                && pendingBefore <= 2
                                && not rootWitnessBefore
                            if replayDriverActiveDepth > 0 && (replayQueue.Length > 0 || pendingBefore > 0 || wasQueued || orphanedRootWitnessActive || orphanedDeferredActive) then
                                replayDriverActiveDepth <- 0
                                releasedActive <- true
                        else
                            gateBusy <- true
                    finally
                        if gateTaken then System.Threading.Monitor.Exit(gate)
                    if gateBusy then
                        DiagJson.noteNoWorkRescueGateBusy ()
                        let gateBusyRescueDecisionId = DiagJson.noWorkGateBusyRescueDecisionFor gateBusySeen
                        let replayTickRequested =
                            match gateBusyRescueDecisionId with
                            | DiagJson.NoWorkGateBusyScheduleReplayTick
                            | DiagJson.NoWorkGateBusyScheduleSparseReplayTick ->
                                System.Threading.ThreadPool.QueueUserWorkItem(System.Threading.WaitCallback(fun _ ->
                                    try
                                        try
                                            runReplayDriver "heartbeat_no_work_gate_busy"
                                        with ex ->
                                            DiagJson.emit (
                                                sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_gate_busy_replay_tick_error\",\"event\":\"heartbeat_no_work_gate_busy\",\"decision_du\":%s,\"error_type\":%s,\"message\":%s,\"single_flight\":1,\"next\":\"explicit_no_work_gate_busy_replay_tick_error\"}"
                                                    (esc (DiagJson.noWorkGateBusyRescueDecisionText gateBusyRescueDecisionId)) (esc (ex.GetType().Name)) (esc ex.Message))
                                    finally
                                        try
                                            lock gate (fun () ->
                                                replayDriverStackFenceQueued <- false
                                                replayDriverStackFenceQueuedSinceMs <- 0L)
                                        with _ -> ())) |> ignore
                                true
                            | _ -> false
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_rescue_gate_busy\",\"event\":\"heartbeat_no_work_stall\",\"gate_wait_ms\":%d,\"gate_busy_seen\":%d,\"rescue_probe_policy_du\":%s,\"gate_busy_rescue_decision_du\":%s,\"queue_depth_before\":%d,\"active_depth_before\":%d,\"pending\":%d,\"root_witness\":%b,\"released_active_depth\":%b,\"scheduled_deferred\":false,\"swept_stale_frontiers\":0,\"replay_tick_requested\":%b,\"single_flight\":1,\"next\":%s}"
                                gateWaitMs gateBusySeen (esc probePolicy) (esc (DiagJson.noWorkGateBusyRescueDecisionText gateBusyRescueDecisionId)) qdBefore adBefore pendingBefore rootWitnessBefore releasedActive replayTickRequested (esc (if replayTickRequested then "threadpool_replay_driver_tick_from_gate_busy" else "gate_busy_worker_finished_no_pinned_rescue")))
                    else
                        let scheduledDeferred =
                            if qdBefore <= 0 && pendingBefore > 0 then tryScheduleDeferredAfterActiveDriver "heartbeat_no_work_stall"
                            else false
                        let qdAfterDeferred =
                            if scheduledDeferred then replayQueueDepth()
                            else qdBefore
                        let sweptStaleFrontiers =
                            if qdAfterDeferred <= 0 && pendingBefore > 0 then heartbeatRootWitnessQuiescenceSweep()
                            else 0
                        let qdAfter =
                            if scheduledDeferred || sweptStaleFrontiers > 0 then replayQueueDepth()
                            else qdAfterDeferred
                        let adAfter =
                            if scheduledDeferred || sweptStaleFrontiers > 0 then replayDriverActiveDepthValue()
                            elif releasedActive then 0
                            else adBefore
                        let replayObligationNoWorkProbe =
                            qdAfter <= 0
                            && pendingBefore <= 0
                            && (DiagJson.snapshotKindCount "eval_worklist_replay_obligation_deferred" > 0
                                || DiagJson.snapshotKindCount "eval_worklist_replay_obligation_deferred_cross_kind_shielded" > 0)
                        let replayTickRequested =
                            if qdAfter > 0 || replayObligationNoWorkProbe then
                                if replayObligationNoWorkProbe then
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_heartbeat_replay_obligation_no_work_probe_requested\",\"event\":\"heartbeat_no_work_stall\",\"queue_depth_after\":%d,\"active_depth_after\":%d,\"pending\":%d,\"root_witness\":%b,\"single_flight\":1,\"next\":\"threadpool_replay_driver_tick_final_obligation_probe\"}"
                                            qdAfter adAfter pendingBefore rootWitnessBefore)
                                System.Threading.ThreadPool.QueueUserWorkItem(System.Threading.WaitCallback(fun _ ->
                                    try
                                        try
                                            runReplayDriver "heartbeat_no_work_stall"
                                        with ex ->
                                            DiagJson.emit (
                                                sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_replay_tick_error\",\"event\":\"heartbeat_no_work_stall\",\"error_type\":%s,\"message\":%s,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_no_work_replay_tick_error\"}"
                                                    (esc (ex.GetType().Name)) (esc ex.Message) (replayQueueDepth()) (pendingCount()))
                                    finally
                                        lock gate (fun () ->
                                            replayDriverStackFenceQueued <- false
                                            replayDriverStackFenceQueuedSinceMs <- 0L))) |> ignore
                                true
                            else false
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_heartbeat_nowork_rescue\",\"event\":\"heartbeat_no_work_stall\",\"gate_wait_ms\":%d,\"gate_busy_seen\":%d,\"rescue_probe_policy_du\":%s,\"queue_depth_before\":%d,\"queue_depth_after\":%d,\"active_depth_before\":%d,\"active_depth_after\":%d,\"pending\":%d,\"root_witness\":%b,\"gate_busy\":false,\"released_active_depth\":%b,\"scheduled_deferred\":%b,\"swept_stale_frontiers\":%d,\"replay_tick_requested\":%b,\"single_flight\":1,\"next\":\"threadpool_replay_driver_tick_or_quiescence_sweep\"}"
                                gateWaitMs gateBusySeen (esc probePolicy) qdBefore qdAfter adBefore adAfter pendingBefore rootWitnessBefore releasedActive scheduledDeferred sweptStaleFrontiers replayTickRequested)
                        if releasedActive && qdAfter = 0 && pendingBefore <= 0 then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_orphan_active_released\",\"event\":\"heartbeat_no_work_stall\",\"active_depth_before\":%d,\"active_depth_after\":%d,\"root_witness\":%b,\"queue_depth\":%d,\"pending\":%d,\"policy\":\"orphan_active_depth_release_only_no_buildok_promotion\",\"single_flight\":1,\"next\":\"retry_after_releasing_orphan_replay_active_depth\"}"
                                    adBefore adAfter rootWitnessBefore qdAfter pendingBefore)
                with ex ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_heartbeat_no_work_replay_rescue_error\",\"event\":\"heartbeat_no_work_stall\",\"error_type\":%s,\"message\":%s,\"single_flight\":1,\"next\":\"explicit_no_work_rescue_error\"}"
                            (esc (ex.GetType().Name)) (esc ex.Message)))

        let maybeWakeReplayAfterGlobalFuseDeferral (event: string) (reason: string) =
            try
                let qd = replayQueueDepth()
                let ad = replayDriverActiveDepthValue()
                let pendingAtRequest = pendingCount()
                // ALPHA1079: alpha1078 showed a real deferred replay queue with
                // pending=1/queue=1/active=1 at rust.spi:266.  Waiting for
                // active_depth>=8 was too conservative there: the single active
                // parent had already yielded a concrete child replay obligation.
                if qd > 0 && (ad >= 1 || pendingAtRequest <= 1) then
                    replayDriverCooperativeTickFromGlobalFuse event reason |> ignore
            with _ -> ()


        let frontierSummary () =
            match snapshot 1 with
            | frame :: _ ->
                let cell =
                    match frame.semanticCell with
                    | Some c -> short 160 (formatCell c)
                    | None -> "none"
                sprintf "frontier kind=%s status=%s depth=%d re=%d/%d trace=%d cursor=%d replay_queue=%d driver=%s payload=%s cell=%s site=%s key=%s"
                    frame.kind frame.status frame.depth frame.re frame.maxRe frame.trace.Length frame.cursor (replayQueueDepth()) (replayDriverStatus()) (semanticPayloadStatus()) cell
                    (short 96 frame.site) (short 120 frame.key)
            | [] -> "frontier empty"

        let panel () =
            try
                let frames = snapshot 3
                if frames.IsEmpty then "" else
                    let sb = System.Text.StringBuilder()
                    sb.AppendFormat("eval.worklist pending={0} single_flight=1 active={1}", frames.Length, (if activeRun then 1 else 0)) |> ignore
                    frames
                    |> List.iteri (fun i frame ->
                        sb.AppendLine() |> ignore
                        let cell =
                            match frame.semanticCell with
                            | Some c -> short 120 (formatCell c)
                            | None -> "none"
                        let line =
                            sprintf "  #%d kind=%s status=%s depth=%d re=%d/%d trace=%d cursor=%d replay_queue=%d driver=%s payload=%s cell=%s site=%s"
                                i frame.kind frame.status frame.depth frame.re frame.maxRe frame.trace.Length frame.cursor (replayQueueDepth()) (replayDriverStatus()) (semanticPayloadStatus()) cell (short 92 frame.site)
                        sb.Append(line) |> ignore)
                    sb.ToString().TrimEnd()
            with _ -> ""

        let emitPanel (event: string) =
            try
                let n = pendingCount()
                let summary = frontierSummary()
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_panel\",\"event\":%s,\"pending\":%d,\"single_flight\":1,\"active\":%d,\"replay_queue\":%d,\"semantic_payload\":%s,\"summary\":%s}"
                        (esc event) n (if activeRun then 1 else 0) (replayQueueDepth()) (esc (semanticPayloadStatus())) (esc summary))
            with _ -> ()

        let fromCycleFuse (reason: string) : Frame =
            let key, site, depth, _gen, re, maxRe = TermCycleFuse.describe()
            { kind = kindFromSite site
              key = key
              site = site
              depth = depth
              re = re
              maxRe = maxRe
              trace = TermCycleFuse.traceSnapshot() |> compactTrace
              reason = reason
              status = "blocked_by_reentry"
              cursor = 0
              semanticPayload = None
              semanticCell = None }

        let emit (event: string) (frame: Frame) : unit =
            try
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_frame\",\"event\":%s,\"reason\":%s,\"frame_kind\":%s,\"key\":%s,\"site\":%s,\"depth\":%d,\"re\":%d,\"max_re\":%d,\"trace_lines\":%d,\"status\":%s,\"cursor\":%d,\"single_flight\":1}"
                        (esc event) (esc frame.reason) (esc frame.kind) (esc frame.key) (esc frame.site) frame.depth frame.re frame.maxRe frame.trace.Length (esc frame.status) frame.cursor)
            with _ -> ()

        let attachSemanticPayload (event: string) (payload: string) : unit =
            try
                let payload = short 1800 payload
                let attached =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let frame' = { frame with semanticPayload = Some payload }
                            frontier <- Some frame'
                            true
                        | None -> false)
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_payload\",\"event\":%s,\"attached\":%d,\"semantic_payload\":%s,\"pending\":%d,\"single_flight\":1}"
                        (esc event) (if attached then 1 else 0) (esc (if attached then "semantic" else "missing_frontier")) (pendingCount()))
            with _ -> ()

        let attachSemanticCell (event: string) (cell: ReplayCell) : unit =
            try
                let payload = formatCellPayload cell |> short 1800
                rememberSemanticCell cell
                let attached, attachStatus =
                    lock gate (fun () ->
                        selectKindLocked cell.kind |> ignore
                        match frontier with
                        | Some frame when frame.kind = cell.kind ->
                            // ALPHA448: do not let a completed same-kind frame masquerade as
                            // completion for a different incoming semantic cell.  This was the
                            // alpha447 live-loop: frame=listm.spi:6/root_complete, cell=TJoinPoint'
                            // at runtime.spi:330.  Keep the trace shell, retarget it to the end,
                            // and force a continuation envelope so the typed replay driver handles
                            // the incoming cell instead of repeatedly attempting build.
                            // ALPHA450: when a scheduled parent replay is active, the incoming same-kind
                            // child cell is useful evidence, but it must not overwrite the parent cell that
                            // the queued replay task is about to reduce. Alpha449 showed the hot loop:
                            // ETypeApply(parent) -> EForall'(child) -> parent_resume -> child overwrite -> ...
                            let sameNodeParentReplayProtected =
                                match replayQueue, frame.semanticCell with
                                | task :: _, Some parent ->
                                    // ALPHA464: alpha463's tail is not a child-over-parent overwrite;
                                    // it is the active scheduled_parent_replay receiving the same
                                    // TJoinPoint' node as a fresh semantic cell and immediately poking
                                    // itself.  Defer that same-node payload so the queued parent replay
                                    // can advance instead of re-entering the same driver frame.
                                    let taskTargetsIncoming =
                                        task.payload.Contains(sprintf "node_id=%d" cell.nodeId)
                                        || task.key.Contains(sprintf "|parent|%d|" cell.nodeId)
                                    replayTaskStatusIsScheduledParent task.status
                                    && taskTargetsIncoming
                                    && sameReplayNode parent cell
                                    && parent.status <> "semantic_root_complete"
                                    && parent.status <> "semantic_leaf_complete"
                                | _ -> false
                            let activeReplayCellProtected =
                                if sameNodeParentReplayProtected then false
                                else
                                    match replayQueue, frame.semanticCell with
                                    | task :: _, Some parent ->
                                        // ALPHA452: alpha451 preserved scheduled_parent_replay, but the same
                                        // overwrite hazard appears for a root continuation replay: a scheduled
                                        // EApply(trace.spi:295) is on the replay queue, then a late EUnitTest
                                        // child cell arrives and replaces the frontier before the driver reduces
                                        // the original continuation.  Protect any in-flight same-kind replay
                                        // cell whose queued payload/key points at the current frontier cell.
                                        let taskTargetsParent =
                                            task.payload.Contains(sprintf "node_id=%d" parent.nodeId)
                                            || task.key.Contains(sprintf "|parent|%d|" parent.nodeId)
                                            || (replayTaskStatusIsScheduledParent task.status && task.key.Contains("|parent|"))
                                        let activeReplayStatus =
                                            replayTaskStatusIsQueuedReplay task.status
                                        activeReplayStatus
                                        && taskTargetsParent
                                        && parent.kind = cell.kind
                                        && parent.nodeId <> cell.nodeId
                                        && parent.status <> "semantic_root_complete"
                                        && parent.status <> "semantic_leaf_complete"
                                    | _ -> false
                            let staleRootComplete =
                                if sameNodeParentReplayProtected || activeReplayCellProtected then false
                                else
                                    frame.status = "semantic_root_complete"
                                    && (match frame.semanticCell with
                                        | Some old -> old.nodeId <> cell.nodeId || old.site <> cell.site || old.shape <> cell.shape || old.kind <> cell.kind || old.status <> "semantic_root_complete"
                                        | None -> frame.site <> cell.site)
                            let staleRootRetargetCount =
                                if staleRootComplete then
                                    let key =
                                        sprintf "%s|%s|%s|%d|frame=%s|cursor=%d"
                                            cell.kind cell.shape cell.site cell.nodeId frame.key frame.cursor
                                    let mutable prior = 0
                                    let next = if staleRootRetargetRepeats.TryGetValue(key, &prior) then prior + 1 else 1
                                    staleRootRetargetRepeats.[key] <- next
                                    next
                                else 0
                            let staleRootRetargetQuarantined = staleRootComplete && staleRootRetargetCount > 3
                            // ALPHA581: a stale-root retarget must not overwrite an already
                            // replay-complete root frame even before quarantine.  Runtime 580
                            // showed repeated eval_worklist_stale_root_complete_retargeted before
                            // the final stale TV mask; defer the stale cell immediately.
                            let suppressRootCompleteRetarget =
                                staleRootComplete
                                && frameReplayCompleteAny frame
                            let rootCompleteStaleRetargetHardCap = 32
                            let rootCompleteStaleRetargetTerminal =
                                suppressRootCompleteRetarget
                                && staleRootRetargetCount >= rootCompleteStaleRetargetHardCap
                            // ALPHA674: runtime 673 hit the hard cap with the root and
                            // incoming cell describing the same ty/TRecord node/site/shape at
                            // spiral.spi:2670.  That is not a new stale terminal; it is the
                            // root-complete frame echoing its own semantic cell with a stale
                            // cell-status.  Align the cell with the already-proven frame and
                            // keep the root evidence instead of pinning a synthetic terminal.
                            let sameRootCompleteCellEcho =
                                rootCompleteStaleRetargetTerminal
                                && frame.status = "semantic_root_complete"
                                && (match frame.semanticCell with
                                    | Some old ->
                                        old.kind = cell.kind
                                        && old.nodeId = cell.nodeId
                                        && old.site = cell.site
                                        && old.shape = cell.shape
                                    | None ->
                                        frame.kind = cell.kind
                                        && frame.site = cell.site)
                            let sameSiteAppRootRetargetEcho =
                                // ALPHA863: alpha862 showed the same app-root hardcap can
                                // arrive as TRecord first and then as TFun at the identical
                                // ty@apps/spiral/spiral.spi:2670 site.  Once the live frame is
                                // semantic_root_complete and the incoming cell is same-kind and
                                // same-site app root evidence, shape is not a stronger proof of
                                // failure.  Preserve the root witness instead of pinning the
                                // synthetic stale-retarget terminal.
                                rootCompleteStaleRetargetTerminal
                                && frame.status = "semantic_root_complete"
                                && frame.kind = cell.kind
