                                            (esc event) (esc cell.kind) (esc cell.shape) (esc cell.site) cell.nodeId (esc crossKindReentryEvidenceName) crossKindLiveness.queueDepth crossKindLiveness.activeDepth crossKindLiveness.pending crossKindTailQueueDepth crossKindReentryCount crossKindReentryEvidence.sameHotNodeCount crossKindReentryEvidence.lastRootReceiptAgeMs (esc crossKindHotObligationDu) crossKindPStarvedMs (esc crossKindTailDecisionText) (esc crossKindYieldThrashDecisionName))
                                elif shouldLogCrossKindObligation then
