                                            (esc event) (esc cell.kind) (esc cell.shape) (esc cell.site) cell.nodeId (esc crossKindDirectionText) (esc cell.shape) (esc cell.site) crossKindReentryCount crossKindReentryCount (esc crossKindReentryEvidenceName) crossKindReentryEvidence.sameHotNodeCount crossKindReentryEvidence.lastRootReceiptAgeMs crossKindLiveness.queueDepth crossKindLiveness.activeDepth crossKindLiveness.pending (esc crossKindOwnerDuText) (esc (replayObligationLivenessKindText crossKindLiveness.kind)) (esc (hotQueueNodeIdText hotQueueBefore.hotQueueNodeId)) hotQueueBefore.hotQueueCount (esc crossKindHotObligationDu) crossKindPStarvedMs (esc crossKindYieldThrashDecisionName) (crossKindReentryCount > 4)
                                    )
                                    DiagJson.emit (
                                        sprintf """{"kind":"eval_worklist_replay_obligation_deferred_cross_kind_shielded","event":%s,"incoming_kind":%s,"incoming_shape":%s,"incoming_site":%s,"incoming_node_id":%d,"active_driver_kind":%s,"target_kind":%s,"cross_kind_direction":%s,"obligation_shape":%s,"reentry_site":%s,"reentry_count":%d,"yield_thrash_count_since_last_real_progress":%d,"cross_kind_reentry_evidence_du":%s,"consecutive_thrash_on_same_hot_node":%d,"last_root_receipt_age_ms":%d,"promote_requeue_reason":"cross_kind_reentry","parent_enqueue_du":%s,"queue_depth":%d,"thread_yielded":%b,"hot_queue_node_id":%s,"hot_oblig_du":%s,"p_starved_ms":%d,"yield_thrash_decision_du":%s,"repeat_cap":4,"repeat_cap_breached":%b,"single_flight":1,"next":"typed_replay_obligation_deferred"}"""
                                            (esc event) (esc cell.kind) (esc cell.shape) (esc cell.site) cell.nodeId (esc activeDriverKindText) (esc cell.kind) (esc crossKindDirectionText) (esc cell.shape) (esc cell.site) crossKindReentryCount crossKindReentryCount (esc crossKindReentryEvidenceName) crossKindReentryEvidence.sameHotNodeCount crossKindReentryEvidence.lastRootReceiptAgeMs (esc crossKindTailDecisionText) crossKindTailQueueDepth yielded (esc (hotQueueNodeIdText hotQueueBefore.hotQueueNodeId)) (esc crossKindHotObligationDu) crossKindPStarvedMs (esc crossKindYieldThrashDecisionName) (crossKindReentryCount > 4)
                                    )
                        elif attachStatus = "same_node_parent_replay_cell_deferred" then
                            let sameNodeQueueDepth = replayQueueDepth()
                            let sameNodeActiveDepth = replayDriverActiveDepthValue()
                            let sameNodePending = pendingCount()
                            let sameNodeDecision = sameNodeParentReplayDrainDecisionFor sameNodeQueueDepth sameNodeActiveDepth sameNodePending
                            let sameNodeDecisionText = sameNodeParentReplayDrainDecisionText sameNodeDecision
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_same_node_replay_poke_suppressed\",\"event\":%s,\"reason\":\"same_node_parent_replay_self_poke\",\"decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"semantic_payload\":%s,\"single_flight\":1,\"next\":%s}"
                                    (esc event) (esc sameNodeDecisionText) sameNodeQueueDepth sameNodeActiveDepth sameNodePending (esc attachStatus) (esc sameNodeDecisionText))
                            if sameNodeParentReplayDrainDecisionShouldSchedule sameNodeDecision then
                                let sameNodeTickDecision = replayTickRequestDecision sameNodeQueueDepth sameNodeActiveDepth false true
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_same_node_parent_replay_drain_tick_requested\",\"event\":%s,\"reason\":\"same_node_parent_replay_self_poke\",\"decision_du\":%s,\"tick_decision_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"threadpool_replay_driver_tick\"}"
                                        (esc event) (esc sameNodeDecisionText) (esc (replayTickRequestDecisionToString sameNodeTickDecision)) sameNodeQueueDepth sameNodeActiveDepth sameNodePending)
                                replayDriverCooperativeTickFromGlobalFuse event "same_node_parent_replay_drain_tick" |> ignore
                    else
                        if idleDeferredChildPoke then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_idle_deferred_replay_poke_resumed\",\"event\":%s,\"reason\":\"idle_deferred_child_cell\",\"queue_depth\":%d,\"semantic_payload\":%s,\"single_flight\":1,\"next\":\"run_replay_driver\"}"
                                    (esc event) (replayQueueDepth()) (esc attachStatus))
                        if idleCrossKindPoke then
                            let obligation = makeReplayObligation ReplayObligationRun ReplayReasonIdleCrossKindDriver 0 1 cell
                            emitReplayObligation event "eval_worklist_replay_obligation_run" obligation
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_idle_cross_kind_replay_poke_resumed\",\"event\":%s,\"reason\":\"idle_cross_kind_replay_driver\",\"idle_cross_kind_replay_driver_kind\":%s,\"idle_cross_kind_replay_driver_site\":%s,\"idle_cross_kind_replay_driver_duration_ms\":0,\"idle_cross_kind_replay_driver_awaiting\":\"cross_kind_sibling_or_parent_continuation_cell\",\"incoming_kind\":%s,\"incoming_shape\":%s,\"incoming_site\":%s,\"incoming_node_id\":%d,\"queue_depth\":%d,\"semantic_payload\":%s,\"single_flight\":1,\"next\":\"run_replay_driver\"}"
                                    (esc event) (esc cell.kind) (esc cell.site) (esc cell.kind) (esc cell.shape) (esc cell.site) cell.nodeId (replayQueueDepth()) (esc attachStatus))
                        let replayDriverProofKey = sprintf "%s|%s|%s|node:%d" event cell.kind cell.site cell.nodeId
                        let replayDriverProofTuple = proofTupleForReentryPrefetchTerminalDriver replayDriverProofKey
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_replay_driver_poke\",\"event\":%s,\"reason\":\"semantic_cell_attached\",\"queue_depth\":%d,\"semantic_payload\":%s,\"materialized_terminal_payload_du\":%s,\"pending_graph_shard_state\":%s%s,\"single_flight\":1,\"next\":\"run_reentry_prefetch_terminal_driver_immediately\"}"
                                (esc event) (replayQueueDepth()) (esc attachStatus) (esc (materializedTerminalOutcomeText MaterializedTerminalReentryPrefetchTerminalDriver)) (esc (typedTerminalPayloadText (reentryPrefetchTerminalDriverTypedTerminalPayload replayDriverProofKey))) (pendingGraphProofTupleJsonFields replayDriverProofTuple))
                        runReplayDriver event
            with _ -> ()

        let resetStableRootCompleteLedger () =
            lock gate (fun () ->
                stableRootCompleteKey <- ""
                stableRootCompleteCount <- 0)

        let reset () =
            lock gate (fun () ->
                frontier <- None
                frontierTerm <- None
                frontierTy <- None
                activeRun <- false
                replayScheduledKey <- None
                replayQueue <- []
                replayDriverStackFenceQueued <- false
                replayFingerprintRepeats.Clear()
                replayChildScheduleRepeats.Clear()
                reentrantReplayPokeRepeats.Clear()
                parentReplayPreservedRepeats.Clear()
                staleRootRetargetRepeats.Clear()
                leafParentContinuationYieldRepeats.Clear()
                progressYieldCount <- 0)

        let tryPeek () : Frame option =
            lock gate (fun () -> frontier)

        let capture (reason: string) : Frame =
            let fresh = fromCycleFuse reason
            let event, frame =
                lock gate (fun () ->
                    selectKindLocked fresh.kind |> ignore
                    match frontier with
                    | Some old when sameCycle old fresh ->
                        slotSetLocked old
                        "capture:dedup", old
                    | _ ->
                        captureSeq <- captureSeq + 1L
                        frontier <- Some fresh
                        slotSetLocked fresh
                        replayScheduledKey <- None
                        replayQueue <- []
                        // ALPHA427: captures may churn while the same root-complete proof recurs;
                        // keep the cross-attempt stable ledger and let noteRootCompleteHandoff
                        // decide whether the fingerprint is new or repeated.
                        "captured", fresh)
            emit event frame
            emitPanel "capture"
            frame


        let ensureCaptured (reason: string) : Frame option =
            let requestedKind = kindFromReason reason
            if requestedKind = "term" || requestedKind = "ty" then
                lock gate (fun () -> selectKindLocked requestedKind |> ignore)
            match tryPeek() with
            | Some frame when requestedKind = "unknown" || frame.kind = requestedKind -> Some frame
            | Some _ when TermCycleFuse.isTripped() -> Some (capture reason)
            | Some _ -> None
            | None ->
                if TermCycleFuse.isTripped() then Some (capture reason)
                else None


        let private replaceHead (frame': Frame) : Frame =
            lock gate (fun () ->
                frontier <- Some frame'
                frame')

        let promoteHead (event: string) : Frame option =
            try
                let promoted =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let alreadyRunning =
                                frame.status = "ready_explicit_loop" ||
                                frame.status = "tracing_explicit_loop" ||
                                frame.status = "continuation_envelope" ||
                                isSemanticTerminalStatus frame.status
                            let frame' =
                                if alreadyRunning then frame
                                else { frame with status = "ready_explicit_loop"; cursor = min frame.cursor frame.trace.Length }
                            frontier <- Some frame'
                            Some(frame', alreadyRunning)
                        | None -> None)
                match promoted with
                | Some(frame', alreadyRunning) ->
                    emit (event + (if alreadyRunning then ":already_ready" else ":promoted")) frame'
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_consume\",\"event\":%s,\"pending\":%d,\"status\":%s,\"cursor\":%d,\"single_flight\":1,\"next\":%s}"
                            (esc event) (pendingCount()) (esc frame'.status) frame'.cursor
                            (esc (if activeRun then "single_flight_busy" else "bounded_trampoline")))
                    Some frame'
                | None -> None
            with _ -> None

        let private traceAt (frame: Frame) (i: int) =
            try
                if i < 0 || i >= frame.trace.Length then ""
                else
                    let r = frame.trace.[i]
                    let a, b = r.range
                    sprintf "%s:%d:%d-%d:%d" r.path a.line a.character b.line b.character
            with _ -> ""

        // ALPHA1036: global-fuse diagnostics are often the visible terminal, while the
        // actual trace lives in the selected frontier or the TermCycleFuse snapshot.
        // Emit a compact JSON fragment so global-fuse records no longer look empty.
        let globalFuseTraceJson () =
            try
                let frameOpt = lock gate (fun () -> frontier)
                let frame, source =
                    match frameOpt with
                    | Some frame when frame.trace.Length > 0 -> frame, "frontier"
                    | _ -> fromCycleFuse "global_fuse_trace_context", "replay_repeat_guard"
                let traceN = frame.trace.Length
                let head =
                    frame.trace
                    |> List.truncate 4
                    |> List.mapi (fun i _ -> sprintf "%d:%s" i (traceAt frame i))
                    |> String.concat "|"
                let tail =
                    let skipN = max 0 (traceN - 4)
                    frame.trace
                    |> List.skip skipN
                    |> List.mapi (fun i _ -> sprintf "%d:%s" (skipN + i) (traceAt frame (skipN + i)))
                    |> String.concat "|"
                sprintf "\"trace_source\":%s,\"trace_lines\":%d,\"trace_cursor\":%d,\"trace_site\":%s,\"trace_key\":%s,\"trace_head\":%s,\"trace_tail\":%s"
                    (esc source) traceN frame.cursor (esc frame.site) (esc frame.key) (esc head) (esc tail)
            with _ ->
                "\"trace_source\":\"error\",\"trace_lines\":0,\"trace_cursor\":0,\"trace_site\":\"\",\"trace_key\":\"\",\"trace_head\":\"\",\"trace_tail\":\"\""

        let private adapterPayload (frame: Frame) =
            try
                let traceN = frame.trace.Length
                let head =
                    frame.trace
                    |> List.truncate 8
                    |> List.mapi (fun i _ -> sprintf "%d:%s" i (traceAt frame i))
                    |> String.concat "|"
                let tail =
                    let skipN = max 0 (traceN - 8)
                    frame.trace
                    |> List.skip skipN
                    |> List.mapi (fun i _ -> sprintf "%d:%s" (skipN + i) (traceAt frame (skipN + i)))
                    |> String.concat "|"
                let focus =
                    if traceN <= 0 then ""
                    else traceAt frame (min (max 0 frame.cursor) (traceN - 1))
                let replayMode =
                    match frame.kind with
                    | "term" -> "term_replay"
                    | "ty" -> "ty_replay"
                    | _ -> "unknown_replay"
                sprintf "replay_continuation(mode=%s,kind=%s,key=%s,site=%s,cursor=%d/%d,focus=%s,semantic=%s,head=%s,tail=%s)"
                    replayMode frame.kind frame.key frame.site frame.cursor traceN focus (semanticPayloadOf frame) head tail
            with _ ->
                sprintf "replay_continuation(kind=%s,key=%s,site=%s,cursor=%d/%d,semantic=%s)"
                    frame.kind frame.key frame.site frame.cursor frame.trace.Length (semanticPayloadOf frame)

        let private nextFor (frame: Frame) =
            match frame.status with
            | "semantic_replay_driver_exception_blocked" -> "explicit_eval_worklist_replay_driver_exception_required"
            | "semantic_replay_payload_missing_blocked" -> "explicit_eval_worklist_replay_payload_required"
            | "semantic_seq_type_error_blocked" -> "explicit_eval_worklist_seq_type_error_required"
            | "semantic_replay_child_schedule_repeat_blocked" -> "explicit_eval_worklist_replay_child_schedule_repeat_required"
            | "semantic_let_success_apply_exception_blocked" -> "explicit_eval_worklist_let_success_apply_exception_required"
            | "semantic_let_success_all_ready_apply_blocked" -> "explicit_eval_worklist_let_success_all_ready_apply_required"
            | "semantic_let_success_apply_continuation_blocked" -> "explicit_eval_worklist_let_success_apply_continuation_required"
            | "semantic_type_apply_forall_body_stepper_blocked" -> "explicit_eval_worklist_type_apply_forall_body_stepper_required"
            | "semantic_apply_continuation_after_seq_unknown_blocked" -> "explicit_eval_worklist_apply_continuation_after_seq_unknown_required"
            | "semantic_apply_continuation_exception_blocked" -> "explicit_eval_worklist_apply_continuation_exception_required"
            | "semantic_deferred_function_replay_exception_blocked" -> "explicit_eval_worklist_deferred_function_replay_exception_required"
            | "semantic_replay_fingerprint_repeat_blocked" -> "explicit_eval_worklist_replay_fingerprint_repeat_required"
            | "semantic_joinpoint_term_stepper_blocked" -> "explicit_eval_worklist_joinpoint_term_stepper_required"
            | "semantic_macro_thunk_missing_blocked" -> "explicit_eval_worklist_macro_thunk_required"
            | "semantic_tjoinpoint_stepper_blocked" -> "explicit_eval_worklist_tjoinpoint_stepper_required"
            | "semantic_joinpoint_value_blocked" -> "explicit_eval_worklist_joinpoint_value_required"
            | "semantic_literal_op_body_stepper_blocked" -> "explicit_eval_worklist_literal_op_body_stepper_required"
            | "semantic_dynamic_join_apply_blocked" -> "native_hopac_dynamic_join_apply_direct_required"
            | "semantic_type_apply_nominal_constructor_stepper_blocked" -> "explicit_eval_worklist_type_apply_nominal_constructor_stepper_required"
            | "semantic_nominal_constructor_stepper_blocked" -> "explicit_eval_worklist_nominal_constructor_stepper_required"
            | "semantic_if_unknown_return_condition_blocked" -> "explicit_eval_worklist_if_unknown_return_condition_required"
            | "semantic_parent_continuation_cycle_blocked" -> "explicit_eval_worklist_parent_continuation_cycle_required"
            | "semantic_type_variable_value_missing_blocked" -> "explicit_eval_worklist_type_variable_env_required"
            | "semantic_stale_root_retarget_blocked" -> "explicit_eval_worklist_stale_root_retarget_required"
            | "semantic_payload_required" -> "wire_eval_payload"
            | "semantic_step_partial" -> "explicit_eval_worklist_real_stepper_required"
            | "semantic_step_done" -> "explicit_eval_worklist_real_stepper_required"
            | "semantic_root_complete" -> "attempt_build"
            | "semantic_leaf_complete" -> "explicit_eval_worklist_parent_continuation_required"
            | "continuation_envelope" -> "schedule_term_ty_replay"
            | "tracing_explicit_loop" -> "advance_trace_cursor"
            | "ready_explicit_loop" -> "bounded_trampoline"
            | status when isTerminalContractStatus status -> terminalContractNext status
            | _ -> "bounded_trampoline"

        // ALPHA466: a semantic_leaf_complete frame with no registered parent
        // continuation is not a root proof and must not spin the retry drain forever.
        // Alpha465 proved real replay progress up to term_type_apply_type_arg_scheduled
        // and dynamic join leaf completion, but the jp_wait_cycle_drain tail then kept
        // re-entering explicit_eval_worklist_parent_continuation_required while another
        // kind-local frontier was pending.  Park the leaf in its kind slot and yield the
        // canonical frontier to the alternate live kind; this is fail-closed because it
        // never marks semantic_root_complete and never opens the writer gate.
        let private tryYieldLeafParentContinuationBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let noParentContinuation =
                            match frame.semanticCell with
                            | Some cell -> EvalReplayValueStore.tryParentContinuation cell.nodeId |> Option.isNone
                            | None -> true
                        let blockedLeaf =
                            frame.status = "semantic_leaf_complete"
                            && replayQueue.IsEmpty
                            && noParentContinuation
                            && not (frameReplayCompleteAny frame)
                        if not blockedLeaf then None
                        else
                            slotSetLocked frame
                            let alternate =
                                let other =
                                    if frame.kind = "term" then frontierTy
                                    elif frame.kind = "ty" then frontierTerm
                                    else None
                                match other with
                                | Some alt when not (sameCycle alt frame) && alt.status <> "semantic_leaf_complete" && alt.status <> "semantic_root_complete" -> Some alt
                                | _ -> None
                            let tryRepairAlternateTerminalLetCycleLocked (alt: Frame) : Frame option =
                                match alt.semanticCell with
                                | Some cell when alt.status = "semantic_parent_continuation_cycle_blocked"
                                                 && alt.kind = "term"
                                                 && cell.kind = "term"
                                                 && cell.shape = "ELet" ->
                                    match EvalReplayValueStore.tryLetSpine cell.nodeId with
                                    | Some spine ->
                                        let makeChildReplay role shape nodeId status nextLabel =
                                            let repairKey = sprintf "%d|leaf_yield|%s|%d" cell.nodeId role nodeId
                                            let attempt = noteLetTerminalCycleRepairLocked repairKey
                                            if attempt > 8 then None
                                            else
                                                EvalReplayValueStore.putParentContinuation nodeId {
                                                    parentKind = cell.kind
                                                    parentShape = cell.shape
                                                    parentNodeId = cell.nodeId
                                                    role = role
                                                }
                                                let childCell = { cell with shape = shape; nodeId = nodeId; status = status; step = 0 }
                                                let repaired =
                                                    { alt with
                                                        status = "continuation_envelope"
                                                        cursor = alt.trace.Length
                                                        reason = alt.reason + ":leaf_yield_terminal_let_cycle_replay"
                                                        semanticPayload = Some(formatCellPayload childCell)
                                                        semanticCell = Some childCell }
                                                frontier <- Some repaired
                                                slotSetLocked repaired
                                                replayScheduledKey <- None
                                                replayQueue <- []
                                                noteProgressYieldLocked ()
                                                DiagJson.emit (
                                                    sprintf "{\"kind\":\"eval_worklist_terminal_let_cycle_replay\",\"event\":%s,\"route\":\"leaf_yield\",\"let_node_id\":%d,\"role\":%s,\"attempt\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                                        (esc event) cell.nodeId (esc role) attempt (esc (formatCell childCell)) (pendingCount()) (esc nextLabel))
                                                Some repaired
                                        let missingBody =
                                            spine.bodyNodeIds
                                            |> Array.mapi (fun i nodeId -> i, nodeId)
                                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                                        match missingBody with
                                        | Some (i, nodeId) ->
                                            let shape = if i < spine.bodyShapes.Length then spine.bodyShapes.[i] else "unknown"
                                            makeChildReplay (sprintf "let_body_%d" i) shape nodeId "let_body_ready" "schedule_let_body_replay"
                                        | None when not (EvalReplayValueStore.tryTermReady spine.successNodeId) ->
                                            makeChildReplay "let_success" spine.successShape spine.successNodeId "let_success_ready" "schedule_let_success_replay"
                                        | None -> None
                                    | None -> None
                                | _ -> None
                            match alternate with
                            | Some alt ->
                                let yieldCount, yieldKey =
                                    if event = "retry_stop_drain" then noteLeafParentContinuationYieldLocked frame alt
                                    else 1, ""
                                let leafYieldChurnCapped =
                                    event = "retry_stop_drain"
                                    && yieldCount > leaf_parent_continuation_yield_cap
                                    && alt.status = "continuation_envelope"
                                    && pendingCount() > 0
                                let leafYieldCrossKindContinuationHandoff =
                                    leafYieldChurnCapped
                                    && frame.kind = "ty"
                                    && frame.status = "semantic_leaf_complete"
                                    && frameCellShapeIn ["EApply"] frame
                                    && alt.kind = "term"
                                    && alt.status = "continuation_envelope"
                                    && frameHasSemanticEvidence alt
                                    && (match frame.semanticCell with
                                        | Some cell ->
                                            cell.kind = "term"
                                            && cell.shape = "EApply"
                                            && cell.status = "semantic_leaf_complete"
                                        | None -> false)
                                if leafYieldCrossKindContinuationHandoff then
                                    // ALPHA881: runtime 880 proved the generic churn cap can stop
                                    // just after it schedules a live runtime fixture path:23 continuation
                                    // for the tests() leaf at spiral.spi:2670.  This exact handoff is
                                    // not a terminal missing-parent contract yet: preserve the selected
                                    // continuation envelope and its existing replay queue so the drain
                                    // can execute the scheduled replay instead of clearing it.
                                    let handoffFrame = { alt with reason = alt.reason + ":leaf_parent_testing_handoff_churn_deferred" }
                                    frontier <- Some handoffFrame
                                    slotSetLocked handoffFrame
                                    replayScheduledKey <- None
                                    noteProgressYieldLocked ()
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_leaf_parent_testing_handoff_churn_deferred\",\"event\":%s,\"leaf_kind\":%s,\"leaf_site\":%s,\"leaf_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_site\":%s,\"count\":%d,\"cap\":%d,\"pending\":%d,\"yield_key\":%s,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                                            (esc event) (esc frame.kind) (esc frame.site) (esc frame.status) (esc handoffFrame.kind) (esc handoffFrame.status) (esc handoffFrame.site) yieldCount leaf_parent_continuation_yield_cap (pendingCount()) (esc yieldKey))
                                    Some handoffFrame
                                elif leafYieldChurnCapped then
                                    let terminalFrame =
                                        { frame with
                                            status = "semantic_leaf_parent_continuation_missing_blocked"
                                            reason = frame.reason + ":leaf_parent_yield_churn_capped" }
                                    frontier <- Some terminalFrame
                                    slotSetLocked terminalFrame
                                    replayScheduledKey <- None
                                    replayQueue <- []
                                    pinTerminalContractLocked event terminalFrame
                                    DiagJson.emit (
                                        sprintf "{\"kind\":\"eval_worklist_leaf_parent_yield_churn_capped\",\"event\":%s,\"leaf_kind\":%s,\"leaf_site\":%s,\"leaf_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_site\":%s,\"count\":%d,\"cap\":%d,\"pending\":%d,\"yield_key\":%s,\"single_flight\":1,\"next\":\"explicit_eval_worklist_leaf_parent_continuation_required\"}"
                                            (esc event) (esc frame.kind) (esc frame.site) (esc frame.status) (esc alt.kind) (esc alt.status) (esc alt.site) yieldCount leaf_parent_continuation_yield_cap (pendingCount()) (esc yieldKey))
                                    Some terminalFrame
                                else
                                    match tryRepairAlternateTerminalLetCycleLocked alt with
                                    | Some repaired -> Some repaired
                                    | None ->
                                        frontier <- Some alt
                                        replayScheduledKey <- None
                                        replayQueue <- []
                                        Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_leaf_parent_continuation_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA490: a parent-continuation cycle blocker is useful evidence but not a
        // reason to keep rebuilding the same continuation envelope.  Park the blocked
        // frame in its kind slot and yield to another already-live frontier when one
        // exists.  If no alternate exists, leave the blocked frame terminal so retry_stop
        // reports explicit_eval_worklist_parent_continuation_cycle_required instead of
        // spinning another replay envelope.
        let private tryYieldParentContinuationCycleBlocked (event: string) (frame: Frame) : Frame option =
            try
                let makeTerminalCompositeReplayLocked (cell: ReplayCell) role childKind shape nodeId status nextLabel =
                    let repairKey = sprintf "%s|%d|%s|%s|%d" cell.shape cell.nodeId role childKind nodeId
                    let attempt = noteCompositeTerminalCycleRepairLocked repairKey
                    if attempt > 12 then None
                    else
                        EvalReplayValueStore.putParentContinuation nodeId {
                            parentKind = cell.kind
                            parentShape = cell.shape
                            parentNodeId = cell.nodeId
                            role = role
                        }
                        let childCell =
                            { cell with
                                kind = childKind
                                shape = shape
                                nodeId = nodeId
                                status = status
                                step = 0 }
                        let repaired =
                            { frame with
                                kind = childKind
                                status = "continuation_envelope"
                                cursor = frame.trace.Length
                                reason = frame.reason + ":terminal_composite_cycle_replay"
                                semanticPayload = Some(formatCellPayload childCell)
                                semanticCell = Some childCell }
                        frontier <- Some repaired
                        slotSetLocked repaired
                        replayScheduledKey <- None
                        replayQueue <- []
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_terminal_composite_cycle_replay\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"child_kind\":%s,\"child_shape\":%s,\"child_node_id\":%d,\"attempt\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc role) (esc childKind) (esc shape) nodeId attempt (esc (formatCell childCell)) (pendingCount()) (esc nextLabel))
                        Some repaired

                let terminalCompositeRootEligible (cell: ReplayCell) =
                    cell.kind = frame.kind
                    && (frame.cursor >= frame.trace.Length || cell.cursor >= frame.trace.Length)

                let terminalCompositeStatusAndNext (cell: ReplayCell) =
                    if terminalCompositeRootEligible cell then
                        "semantic_root_complete", "attempt_build", "eval_worklist_terminal_composite_cycle_root_resolved"
                    else
                        "semantic_leaf_complete", "explicit_eval_worklist_parent_continuation_required", "eval_worklist_terminal_composite_cycle_value_resolved"

                let clearParentCycleTerminalAfterCompositeRootLocked (resolvedStatus: string) (cell: ReplayCell) =
                    if resolvedStatus = "semantic_root_complete" then
                        let matches (pinned: Frame) =
                            pinned.status = "semantic_parent_continuation_cycle_blocked"
                            && (pinned.key = frame.key
                                || pinned.site = frame.site
                                || (match pinned.semanticCell with
                                    | Some pinnedCell -> pinnedCell.kind = cell.kind && pinnedCell.nodeId = cell.nodeId
                                    | None -> false))
                        let pinnedCleared =
                            match pinnedTerminalContract with
                            | Some pinned when matches pinned ->
                                pinnedTerminalContract <- None
                                true
                            | _ -> false
                        let durableCleared =
                            match durableTerminalContract with
                            | Some pinned when matches pinned ->
                                durableTerminalContract <- None
                                true
                            | _ -> false
                        if pinnedCleared || durableCleared then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_parent_cycle_terminal_cleared_after_composite_root\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"pinned_cleared\":%b,\"durable_cleared\":%b,\"pending\":%d,\"single_flight\":1,\"next\":\"attempt_build_without_stale_terminal_contract\"}"
                                    (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId pinnedCleared durableCleared (pendingCount()))

                let completeCompositeIfReadyLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTermDetailed cell.nodeId with
                    | Choice1Of2 value ->
                        EvalReplayValueStore.putTermValue cell.nodeId value
                        let resolvedStatus, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                        let resolvedCell = { cell with status = resolvedStatus }
                        let resolved =
                            { frame with
                                kind = cell.kind
                                status = resolvedStatus
                                semanticCell = Some resolvedCell
                                semanticPayload = Some(formatCellPayload resolvedCell) }
                        clearParentCycleTerminalAfterCompositeRootLocked resolvedStatus cell
                        frontier <- Some resolved
                        slotSetLocked resolved
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            sprintf "{\"kind\":%s,\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc resolvedKind) (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc (formatCell resolvedCell)) (pendingCount()) (esc resolvedNext))
                        Some resolved
                    | Choice2Of2 detail ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_terminal_composite_cycle_value_blocked\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"detail\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                                (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc detail) (pendingCount()))
                        None

                let completeTypeCompositeIfReadyLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeDetailed cell.nodeId with
                    | Choice1Of2 value ->
                        EvalReplayValueStore.putTypeValue cell.nodeId value
                        let resolvedStatus, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                        let resolvedCell = { cell with status = resolvedStatus }
                        let resolved =
                            { frame with
                                kind = cell.kind
                                status = resolvedStatus
                                semanticCell = Some resolvedCell
                                semanticPayload = Some(formatCellPayload resolvedCell) }
                        clearParentCycleTerminalAfterCompositeRootLocked resolvedStatus cell
                        frontier <- Some resolved
                        slotSetLocked resolved
                        noteProgressYieldLocked ()
                        DiagJson.emit (
                            sprintf "{\"kind\":%s,\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc (resolvedKind + "_ty")) (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc (formatCell resolvedCell)) (pendingCount()) (esc resolvedNext))
                        Some resolved
                    | Choice2Of2 detail ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_terminal_type_composite_cycle_value_blocked\",\"event\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"detail\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                                (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc detail) (pendingCount()))
                        None

                let tryRepairTerminalSeqCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.trySeqSpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.firstNodeId) then
                            makeTerminalCompositeReplayLocked cell "seq_first" "term" spine.firstShape spine.firstNodeId "seq_first_ready" "schedule_seq_first_replay"
                        elif not (EvalReplayValueStore.tryTermReady spine.secondNodeId) then
                            makeTerminalCompositeReplayLocked cell "seq_second" "term" spine.secondShape spine.secondNodeId "seq_second_ready" "schedule_seq_second_replay"
                        else
                            completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalLetCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryLetSpine cell.nodeId with
                    | Some spine ->
                        let missingBody =
                            spine.bodyNodeIds
                            |> Array.mapi (fun i nodeId -> i, nodeId)
                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                        match missingBody with
                        | Some (i, nodeId) ->
                            let shape = if i < spine.bodyShapes.Length then spine.bodyShapes.[i] else "unknown"
                            makeTerminalCompositeReplayLocked cell (sprintf "let_body_%d" i) "term" shape nodeId "let_body_ready" "schedule_let_body_replay"
                        | None when not (EvalReplayValueStore.tryTermReady spine.successNodeId) ->
                            makeTerminalCompositeReplayLocked cell "let_success" "term" spine.successShape spine.successNodeId "let_success_ready" "schedule_let_success_replay"
                        | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalApplyCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryApplySpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.headNodeId) then
                            makeTerminalCompositeReplayLocked cell "apply_head" "term" spine.headShape spine.headNodeId "apply_head_ready" "schedule_apply_head_replay"
                        else
                            let missingArg =
                                spine.argNodeIds
                                |> Array.mapi (fun i nodeId -> i, nodeId)
                                |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                            match missingArg with
                            | Some (i, nodeId) ->
                                let shape = if i < spine.argShapes.Length then spine.argShapes.[i] else "unknown"
                                makeTerminalCompositeReplayLocked cell (sprintf "apply_arg_%d" i) "term" shape nodeId "apply_arg_ready" "schedule_apply_arg_replay"
                            | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalTypeApplyCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeApplySpine cell.nodeId with
                    | Some spine ->
                        if not (EvalReplayValueStore.tryTermReady spine.funcNodeId) then
                            makeTerminalCompositeReplayLocked cell "type_apply_function" "term" spine.funcShape spine.funcNodeId "type_apply_function_ready" "schedule_type_apply_function_replay"
                        else
                            match EvalReplayValueStore.tryType spine.typeNodeId with
                            | None ->
                                makeTerminalCompositeReplayLocked cell "type_apply_type_arg" "ty" spine.typeShape spine.typeNodeId "type_apply_type_arg_ready" "schedule_type_apply_type_arg_replay"
                            | Some _ ->
                                match EvalReplayValueStore.tryTypeApplyBodyValueAt cell.nodeId with
                                | Some value ->
                                    EvalReplayValueStore.putTermValue cell.nodeId value
                                    match EvalReplayValueStore.tryParentContinuation cell.nodeId with
                                    | Some cont when cont.parentNodeId <> cell.nodeId ->
                                        let parentCell =
                                            { cell with
                                                kind = cont.parentKind
                                                shape = cont.parentShape
                                                nodeId = cont.parentNodeId
                                                status = "parent_continuation_ready"
                                                step = cell.step + 1 }
                                        let repaired =
                                            { frame with
                                                kind = cont.parentKind
                                                status = "continuation_envelope"
                                                cursor = frame.trace.Length
                                                reason = frame.reason + ":terminal_type_apply_body_parent_resume"
                                                semanticCell = Some parentCell
                                                semanticPayload = Some(formatCellPayload parentCell) }
                                        frontier <- Some repaired
                                        slotSetLocked repaired
                                        replayScheduledKey <- None
                                        replayQueue <- []
                                        noteProgressYieldLocked ()
                                        DiagJson.emit (
                                            sprintf "{\"kind\":\"eval_worklist_terminal_type_apply_cycle_body_parent_resumed\",\"event\":%s,\"child\":%s,\"parent_kind\":%s,\"parent_shape\":%s,\"parent_node_id\":%d,\"role\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"resume_parent_replay_driver\"}"
                                                (esc event) (esc (formatCell cell)) (esc cont.parentKind) (esc cont.parentShape) cont.parentNodeId (esc cont.role) (pendingCount()))
                                        Some repaired
                                    | _ ->
                                        let resolvedStatus, resolvedNext, resolvedKind = terminalCompositeStatusAndNext cell
                                        let resolvedCell = { cell with status = resolvedStatus }
                                        let resolved =
                                            { frame with
                                                kind = cell.kind
                                                status = resolvedStatus
                                                semanticCell = Some resolvedCell
                                                semanticPayload = Some(formatCellPayload resolvedCell) }
                                        frontier <- Some resolved
                                        slotSetLocked resolved
                                        noteProgressYieldLocked ()
                                        DiagJson.emit (
                                            sprintf "{\"kind\":%s,\"event\":%s,\"parent_node_id\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                                (esc (resolvedKind + "_type_apply_body")) (esc event) cell.nodeId (esc (formatCell resolvedCell)) (pendingCount()) (esc resolvedNext))
                                        Some resolved
                                | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalTypeFunCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypeFunSpine cell.nodeId with
                    | Some spine ->
                        match EvalReplayValueStore.tryType spine.argNodeId, EvalReplayValueStore.tryType spine.bodyNodeId with
                        | None, _ ->
                            makeTerminalCompositeReplayLocked cell "tfun_arg" "ty" spine.argShape spine.argNodeId "tfun_arg_ready" "schedule_tfun_arg_replay"
                        | _, None ->
                            makeTerminalCompositeReplayLocked cell "tfun_body" "ty" spine.bodyShape spine.bodyNodeId "tfun_body_ready" "schedule_tfun_body_replay"
                        | Some argTy, Some bodyTy ->
                            EvalReplayValueStore.putTypeValue cell.nodeId (YFun(argTy, bodyTy, spine.funType))
                            completeTypeCompositeIfReadyLocked cell
                    | None -> completeTypeCompositeIfReadyLocked cell

                let tryRepairTerminalTypePairCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryTypePairSpine cell.nodeId with
                    | Some spine ->
                        match EvalReplayValueStore.tryType spine.leftNodeId, EvalReplayValueStore.tryType spine.rightNodeId with
                        | None, _ ->
                            makeTerminalCompositeReplayLocked cell "tpair_left" "ty" spine.leftShape spine.leftNodeId "tpair_left_ready" "schedule_tpair_left_replay"
                        | _, None ->
                            makeTerminalCompositeReplayLocked cell "tpair_right" "ty" spine.rightShape spine.rightNodeId "tpair_right_ready" "schedule_tpair_right_replay"
                        | Some leftTy, Some rightTy ->
                            EvalReplayValueStore.putTypeValue cell.nodeId (YPair(leftTy, rightTy))
                            completeTypeCompositeIfReadyLocked cell
                    | None -> completeTypeCompositeIfReadyLocked cell

                let tryRepairTerminalRecordWithCycleLocked (cell: ReplayCell) =
                    match EvalReplayValueStore.tryRecordWithSpine cell.nodeId with
                    | Some spine ->
                        let missingChild =
                            spine.childNodeIds
                            |> Array.mapi (fun i nodeId -> i, nodeId)
                            |> Array.tryFind (fun (_, nodeId) -> not (EvalReplayValueStore.tryTermReady nodeId))
                        match missingChild with
                        | Some (i, nodeId) ->
                            let shape = if i < spine.childShapes.Length then spine.childShapes.[i] else "unknown"
                            let role = if i < spine.childRoles.Length then spine.childRoles.[i] else sprintf "record_with_child_%d" i
                            makeTerminalCompositeReplayLocked cell role "term" shape nodeId "record_with_child_ready" "schedule_record_with_child_replay"
                        | None -> completeCompositeIfReadyLocked cell
                    | None -> None

                let tryRepairTerminalCompositeCycleLocked () =
                    match frame.semanticCell with
                    | Some cell when frame.status = "semantic_parent_continuation_cycle_blocked"
                                     && cell.kind = "term" ->
                        match cell.shape with
                        | "ELet" -> tryRepairTerminalLetCycleLocked cell
                        | "ESeq" -> tryRepairTerminalSeqCycleLocked cell
                        | "EApply" -> tryRepairTerminalApplyCycleLocked cell
                        | "ETypeApply" -> tryRepairTerminalTypeApplyCycleLocked cell
                        | "ERecordWith" -> tryRepairTerminalRecordWithCycleLocked cell
                        | _ -> None
                    | Some cell when frame.status = "semantic_parent_continuation_cycle_blocked"
                                     && cell.kind = "ty" ->
                        match cell.shape with
                        | "TFun" -> tryRepairTerminalTypeFunCycleLocked cell
                        | "TPair" -> tryRepairTerminalTypePairCycleLocked cell
                        | _ -> completeTypeCompositeIfReadyLocked cell
                    | _ -> None

                let switched =
                    lock gate (fun () ->
                        let blockedCycle =
                            frameSemanticStatusIs SemanticParentContinuationCycleBlocked frame
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedCycle then None
                        else
                            match tryRepairTerminalCompositeCycleLocked () with
                            | Some repaired -> Some repaired
                            | None ->
                                slotSetLocked frame
                                let candidates =
                                    [ frontierTerm; frontierTy ]
                                    |> List.choose (fun x -> x)
                                    |> List.filter (fun alt ->
                                        not (sameCycle alt frame)
                                        && alt.status <> "semantic_parent_continuation_cycle_blocked"
                                        && alt.status <> "semantic_replay_fingerprint_repeat_blocked"
                                        && alt.status <> "semantic_joinpoint_term_stepper_blocked"
                                        && alt.status <> "semantic_joinpoint_value_blocked"
                                        && alt.status <> "semantic_replay_payload_missing_blocked"
                                        && alt.status <> "semantic_macro_thunk_missing_blocked"
                                        && alt.status <> "semantic_tjoinpoint_stepper_blocked"
                                        && alt.status <> "semantic_literal_op_body_stepper_blocked"
                                        && alt.status <> "semantic_leaf_complete")
                                let selected =
                                    match candidates |> List.tryFind (fun alt -> alt.status = "semantic_root_complete") with
                                    | Some root -> Some root
                                    | None ->
                                        match candidates |> List.tryFind (fun alt -> alt.status = "continuation_envelope" || alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop") with
                                        | Some live -> Some live
                                        | None -> candidates |> List.tryHead
                                match selected with
                                | Some alt ->
                                    frontier <- Some alt
                                    replayScheduledKey <- None
                                    replayQueue <- []
                                    Some alt
                                | None -> None)
                match switched with
                | Some alt when alt.status = "continuation_envelope"
                                && (alt.reason.Contains("terminal_let_cycle_replay")
                                    || alt.reason.Contains("terminal_composite_cycle_replay")) ->
                    Some alt
                | Some alt ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_parent_continuation_cycle_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA491: a TV child with no materialized type environment is terminal evidence,
        // but should not monopolize retry_stop while a different kind-local frontier is live.
        // Park it and yield to another non-terminal frontier when one exists.
        let private tryYieldTypeVariableValueMissingBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedTypeVar =
                            frame.status = "semantic_type_variable_value_missing_blocked"
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedTypeVar then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && alt.status <> "semantic_type_variable_value_missing_blocked"
                                    && alt.status <> "semantic_parent_continuation_cycle_blocked"
                                    && alt.status <> "semantic_replay_fingerprint_repeat_blocked"
                                    && alt.status <> "semantic_replay_payload_missing_blocked"
                                    && alt.status <> "semantic_macro_thunk_missing_blocked"
                                    && alt.status <> "semantic_tjoinpoint_stepper_blocked"
                                    && alt.status <> "semantic_literal_op_body_stepper_blocked"
                                    && alt.status <> "semantic_leaf_complete")
                            let selected =
                                match candidates |> List.tryFind (fun alt -> alt.status = "semantic_root_complete") with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> alt.status = "continuation_envelope" || alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop") with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayQueue <- []
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_type_variable_value_missing_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA493: a stale-root retarget blocker is terminal evidence for the blocked
        // cell, but it should not monopolize retry_stop while another kind-local frontier
        // is already live.  Park it in the kind slot and yield to a non-terminal alternate
        // frontier when one exists.  This never promotes the stale proof to root-complete.
        let private tryYieldStaleRootRetargetBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedRetarget =
                            frame.status = "semantic_stale_root_retarget_blocked"
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedRetarget then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && alt.status <> "semantic_stale_root_retarget_blocked"
                                    && alt.status <> "semantic_type_variable_value_missing_blocked"
                                    && alt.status <> "semantic_parent_continuation_cycle_blocked"
                                    && alt.status <> "semantic_replay_fingerprint_repeat_blocked"
                                    && alt.status <> "semantic_replay_payload_missing_blocked"
                                    && alt.status <> "semantic_macro_thunk_missing_blocked"
                                    && alt.status <> "semantic_tjoinpoint_stepper_blocked"
                                    && alt.status <> "semantic_literal_op_body_stepper_blocked"
                                    && alt.status <> "semantic_leaf_complete")
                            let selected =
                                match candidates |> List.tryFind (fun alt -> alt.status = "semantic_root_complete") with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> alt.status = "continuation_envelope" || alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop") with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayQueue <- []
                                noteProgressYieldLocked ()
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_stale_root_retarget_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA477: retry_stop can now reach a real semantic leaf after jp_wait_cycle_drain
        // without yet having the parent continuation registered.  That is progress, but not
        // a root proof.  Request one bounded replay retry so the parent-continuation sidecar
        // can be observed on the next pass, rather than aborting immediately as a generic
        // semantic_step_partial.  The caller remains responsible for the normal retry cap.
        let tryRequestLeafParentContinuationRetry (event: string) (attempt: int) (maxAttempts: int) : bool =
            try
                match tryPeek() with
                | Some frame ->
                    let noParentContinuation =
                        match frame.semanticCell with
                        | Some cell -> EvalReplayValueStore.tryParentContinuation cell.nodeId |> Option.isNone
                        | None -> true
                    let blockedLeaf =
                        frame.status = "semantic_leaf_complete"
                        && replayQueue.IsEmpty
                        && noParentContinuation
                        && not (frameReplayCompleteAny frame)
                    if not blockedLeaf then false
                    else
                        let yieldedAlternate =
                            match tryYieldLeafParentContinuationBlocked event frame with
                            | Some _ -> true
                            | None -> false
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_leaf_parent_continuation_retry\",\"event\":%s,\"attempt\":%d,\"next_attempt\":%d,\"max_attempts\":%d,\"frame_kind\":%s,\"status\":%s,\"key\":%s,\"site\":%s,\"cursor\":%d,\"trace_lines\":%d,\"pending\":%d,\"yielded_alternate\":%b,\"single_flight\":1,\"policy\":\"bounded_retry_after_leaf_parent_continuation_missing\",\"next\":\"attempt_build\"}"
                                (esc event) attempt (attempt + 1) maxAttempts (esc frame.kind) (esc frame.status) (esc frame.key) (esc frame.site) frame.cursor frame.trace.Length (pendingCount()) yieldedAlternate)
                        true
                | None -> false
            with _ -> false

        // ALPHA470/494: a replay fingerprint repeat is useful evidence, but it
        // should not monopolize the canonical retry drain while another frontier is
        // live.  Alpha494 adds two guardrails observed after alpha493: progress-bearing
        // fingerprint-yields are counted for a bounded retry trampoline, and when no
        // independent kind-local slot exists, a live same-cycle non-terminal frontier
        // may be selected once instead of aborting immediately on the repeat blocker.
        let private tryYieldReplayFingerprintRepeatBlocked (event: string) (frame: Frame) : Frame option =
            try
                let mutable selectedScope = "none"
                let switched =
                    lock gate (fun () ->
                        let blockedRepeat =
                            frame.status = "semantic_replay_fingerprint_repeat_blocked"
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedRepeat then None
                        else
                            slotSetLocked frame
                            let liveNonRepeat (alt: Frame) =
                                alt.status <> "semantic_replay_fingerprint_repeat_blocked"
                                && alt.status <> "semantic_joinpoint_term_stepper_blocked"
                                && alt.status <> "semantic_joinpoint_value_blocked"
                                && alt.status <> "semantic_parent_continuation_cycle_blocked"
                                && alt.status <> "semantic_type_variable_value_missing_blocked"
                                && alt.status <> "semantic_stale_root_retarget_blocked"
                                && alt.status <> "semantic_leaf_complete"
                            let allCandidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter liveNonRepeat
                            let independent =
                                allCandidates |> List.filter (fun alt -> not (sameCycle alt frame))
                            let sameCycleLive =
                                allCandidates |> List.filter (fun alt -> sameCycle alt frame)
                            let candidates =
                                match independent with
                                | _ :: _ ->
                                    selectedScope <- "independent"
                                    independent
                                | [] ->
                                    selectedScope <- "same_cycle_live"
                                    sameCycleLive
                            let selected =
                                match candidates |> List.tryFind (fun alt -> alt.status = "semantic_root_complete") with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> alt.status = "continuation_envelope" || alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop") with
                                    | Some live -> Some live
                                    | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayQueue <- []
                                noteProgressYieldLocked ()
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    let kind =
                        if selectedScope = "same_cycle_live" then "eval_worklist_replay_fingerprint_repeat_same_cycle_yielded"
                        else "eval_worklist_replay_fingerprint_repeat_yielded"
                    DiagJson.emit (
                        sprintf "{\"kind\":%s,\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"scope\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc kind) (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (esc selectedScope) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA471: dynamic apply blocked on a DV/DB runtime typecheck is not
        // semantic progress, but it also should not terminate retry_stop while an
        // alternate kind frontier is pending.  Park the blocked dynamic-join frame
        // and yield to another live frontier.  This is scheduler-only: the value
        // store, replay-root witness, and writer gates remain unchanged.
        let private tryYieldDynamicArgApplyBlocked (event: string) (frame: Frame) : Frame option =
            try
                let switched =
                    lock gate (fun () ->
                        let blockedDynamic =
                            frame.status = "semantic_dynamic_join_apply_blocked"
                            && replayQueue.IsEmpty
                            && not (frameReplayCompleteAny frame)
                        if not blockedDynamic then None
                        else
                            slotSetLocked frame
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && alt.status <> "semantic_replay_fingerprint_repeat_blocked"
                                    && alt.status <> "semantic_replay_payload_missing_blocked"
                                    && alt.status <> "semantic_macro_thunk_missing_blocked"
                                    && alt.status <> "semantic_tjoinpoint_stepper_blocked"
                                    && alt.status <> "semantic_literal_op_body_stepper_blocked"
                                    && alt.status <> "semantic_leaf_complete"
                                    && alt.status <> "semantic_dynamic_join_apply_blocked")
                            let selected =
                                match candidates |> List.tryFind (fun alt -> alt.status = "semantic_root_complete") with
                                | Some root -> Some root
                                | None ->
                                    match candidates |> List.tryFind (fun alt -> alt.status = "continuation_envelope") with
                                    | Some cont -> Some cont
                                    | None ->
                                        match candidates |> List.tryFind (fun alt -> alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop") with
                                        | Some live -> Some live
                                        | None -> candidates |> List.tryHead
                            match selected with
                            | Some alt ->
                                frontier <- Some alt
                                replayScheduledKey <- None
                                replayQueue <- []
                                Some alt
                            | None -> None)
                match switched with
                | Some alt ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_dynamic_arg_apply_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"drain_selected_frontier\"}"
                            (esc event) (esc frame.kind) (esc frame.status) (esc alt.kind) (esc alt.status) (pendingCount()))
                    Some alt
                | None -> None
            with _ -> None

        // ALPHA473: a semantic_root_complete frontier is a proof, not a scheduler sink.
        // Alpha472 reached multiple source_value_stored events and then stopped on
        // stable_root_complete_livelock while pending alternate work remained.  When
        // the root-complete handoff repeats up to the outer cap, park the completed
        // proof in its kind slot and select a live non-root frontier before aborting.
        // This is scheduler-only: it cannot create BuildOk, cannot mark completion,
        // and cannot unlock writer/shrink gates.
        let tryYieldStableRootCompleteHandoff (event: string) : Frame option =
            try
                let rankStableRootYieldCandidate (alt: Frame) =
                    if alt.status = "semantic_dynamic_join_apply_blocked" then 0
                    elif alt.status = "continuation_envelope" then 1
                    elif alt.status = "ready_explicit_loop" || alt.status = "tracing_explicit_loop" || alt.status = "semantic_step_partial" then 2
                    else 3

                let chooseStableRootYieldCandidate candidates =
                    candidates
                    |> List.sortBy rankStableRootYieldCandidate
                    |> List.tryHead

                let crossKindSelectedStepper (frame: Frame) =
                    match frame.semanticCell with
                    | Some cell when cell.status = "selected_frontier_stepper_ready" ->
                        (cell.kind = "term" && cell.site.StartsWith("ty@", StringComparison.Ordinal))
                        || (cell.kind = "ty" && cell.site.StartsWith("term@", StringComparison.Ordinal))
                    | _ -> false

                // Selected-frontier promotion happens in the root-complete handoff path,
                // outside the normal bounded trampoline.  A continuation envelope without a
                // queued replay task only burns retry budget.  Enqueue the promoted envelope
                // immediately so the next preserved-progress attempt has a concrete driver.
                let enqueueSelectedFrontierReplayLocked (event: string) (frame: Frame) (route: string) =
                    let payload = adapterPayload frame
                    let key = replayKey frame
                    let driver = replayDriverFor frame
                    replaySeq <- replaySeq + 1L
                    let task = { id = replaySeq; key = key; driver = driver; payload = payload; status = "scheduled_replay"; event = event }
                    replayScheduledKey <- Some key
                    replayQueue <- [task]
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_selected_frontier_replay_enqueued\",\"event\":%s,\"route\":%s,\"replay_id\":%d,\"driver\":%s,\"frame_kind\":%s,\"frame_status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"execute_selected_frontier_replay_driver\"}"
                            (esc event) (esc route) task.id (esc driver) (esc frame.kind) (esc frame.status) frame.cursor frame.trace.Length (replayQueueDepth()) (pendingCount()))

                let tryPromoteSelectedFrontierStepperLocked (repeated: Frame) (repeatCount: int) (repeatedKey: string) =
                    match repeated.semanticCell with
                    | Some cell when (repeated.status = "captured"
                                      || repeated.status = "ready_explicit_loop"
                                      || repeated.status = "tracing_explicit_loop"
                                      || repeated.status = "semantic_apply_continuation_exception_blocked")
                                     && cell.kind = "term"
                                     && cell.shape = "ESeq"
                                     && (cell.status = "captured" || cell.status = "new" || cell.status = "stepper_ready") ->
                        let replayKey = repeatedKey + "|selected_captured_cell_replay|" + string cell.nodeId + "|" + cell.shape + "|cursor=" + string cell.cursor + "|step=" + string cell.step
                        let attempt = noteSelectedFrontierStepperReplayLocked replayKey
                        if attempt > selected_frontier_captured_cell_replay_cap then None
                        else
                            let replayCell = { cell with status = "selected_frontier_stepper_ready" }
                            let promoted =
                                { repeated with
                                    status = "continuation_envelope"
                                    cursor = repeated.trace.Length
                                    reason = repeated.reason + ":selected_captured_frontier_cell_replay"
                                    semanticPayload = Some(formatCellPayload replayCell)
                                    semanticCell = Some replayCell }
                            frontier <- Some promoted
                            slotSetLocked promoted
                            enqueueSelectedFrontierReplayLocked event promoted "captured_cell_replay"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- ""
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_selected_frontier_captured_cell_replay\",\"event\":%s,\"frame_status\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_status\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"run_captured_frontier_typed_stepper\"}"
                                    (esc event) (esc repeated.status) (esc cell.kind) (esc cell.shape) (esc cell.status) cell.nodeId (esc cell.site) attempt selected_frontier_captured_cell_replay_cap repeatCount stable_root_selected_frontier_repeat_cap (pendingCount()))
                            Some promoted
                    | Some cell when repeated.status = "semantic_step_partial"
                                     && cell.kind = "term"
                                     && (cell.shape = "EApply" || cell.shape = "ETypeApply" || cell.shape = "ELet" || cell.shape = "ESeq") ->
                        let replayKey = repeatedKey + "|selected_frontier_stepper|" + string cell.nodeId + "|" + cell.shape
                        let attempt = noteSelectedFrontierStepperReplayLocked replayKey
                        if attempt > selected_frontier_stepper_replay_cap then None
                        else
                            let replayCell = { cell with status = "selected_frontier_stepper_ready" }
                            let promoted =
                                { repeated with
                                    status = "continuation_envelope"
                                    cursor = repeated.trace.Length
                                    reason = repeated.reason + ":selected_frontier_stepper_replay"
                                    semanticPayload = Some(formatCellPayload replayCell)
                                    semanticCell = Some replayCell }
                            frontier <- Some promoted
                            slotSetLocked promoted
                            enqueueSelectedFrontierReplayLocked event promoted "stepper_replay"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- ""
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_selected_frontier_stepper_replay\",\"event\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"run_selected_frontier_typed_stepper\"}"
                                    (esc event) (esc cell.kind) (esc cell.shape) cell.nodeId (esc cell.site) attempt selected_frontier_stepper_replay_cap repeatCount stable_root_selected_frontier_repeat_cap (pendingCount()))
                            Some promoted
                    | Some cell when repeated.status = "continuation_envelope"
                                     && cell.kind = "term"
                                     && cell.status = "selected_frontier_stepper_ready"
                                     && (cell.shape = "EApply" || cell.shape = "ETypeApply" || cell.shape = "ELet" || cell.shape = "ESeq") ->
                        let replayKey =
                            repeatedKey + "|selected_frontier_stepper_rearm|" + string cell.nodeId + "|" + cell.shape + "|cursor=" + string cell.cursor + "|step=" + string cell.step
                        let attempt = noteSelectedFrontierStepperReplayLocked replayKey
                        if attempt > selected_frontier_stepper_rearm_cap then None
                        else
                            let rearmed =
                                { repeated with
                                    status = "continuation_envelope"
                                    cursor = repeated.trace.Length
                                    reason = repeated.reason + ":selected_frontier_stepper_rearm"
                                    semanticPayload = Some(formatCellPayload cell)
                                    semanticCell = Some cell }
                            frontier <- Some rearmed
                            slotSetLocked rearmed
                            enqueueSelectedFrontierReplayLocked event rearmed "stepper_rearm"
                            noteProgressYieldLocked ()
                            stableRootSelectedKey <- ""
                            stableRootSelectedCount <- 0
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_selected_frontier_stepper_rearm\",\"event\":%s,\"cell_kind\":%s,\"cell_shape\":%s,\"cell_status\":%s,\"node_id\":%d,\"site\":%s,\"attempt\":%d,\"cap\":%d,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"rearm_selected_frontier_typed_stepper\"}"
                                    (esc event) (esc cell.kind) (esc cell.shape) (esc cell.status) cell.nodeId (esc cell.site) attempt selected_frontier_stepper_rearm_cap repeatCount stable_root_selected_frontier_repeat_cap (pendingCount()))
                            Some rearmed
                    | _ -> None

                let switched =
                    lock gate (fun () ->
                        match frontier with
                        | Some frame when frameReplayCompleteAny frame && replayQueue.IsEmpty ->
                            slotSetLocked frame
                            let blockedRootKey = rootCompleteFingerprintLocked ()
                            let candidates =
                                [ frontierTerm; frontierTy ]
                                |> List.choose (fun x -> x)
                                |> List.filter (fun alt ->
                                    not (sameCycle alt frame)
                                    && not (frameReplayCompleteAny alt)
                                    && alt.status <> "semantic_leaf_complete")
                            let preferred = chooseStableRootYieldCandidate candidates
                            let selected, repeatBlocked =
                                match preferred with
                                | Some pref ->
                                    let prefKey = blockedRootKey + "=>" + selectedFrontierFingerprintLocked pref
                                    if prefKey = stableRootSelectedKey && stableRootSelectedCount >= stable_root_selected_frontier_repeat_cap then
                                        let fallback =
                                            candidates
                                            |> List.filter (fun alt -> blockedRootKey + "=>" + selectedFrontierFingerprintLocked alt <> stableRootSelectedKey)
                                            |> chooseStableRootYieldCandidate
                                        match fallback with
                                        | Some alt -> Some alt, Some(pref, stableRootSelectedCount, prefKey)
                                        | None ->
                                            // ALPHA582: forcing the same semantic_step_partial frontier after
                                            // the repeat cap only burns the root-complete yield budget.  Runtime
                                            // 581 proved the lone child repeats until trampoline exhaustion; when
                                            // there is no alternate, surface the exact repeat terminal instead.
                                            // ALPHA588: runtime 587 exposed a narrower case where the repeated
                                            // selected frontier is already a selected_frontier_stepper_ready term
                                            // cell, but its site is ty@... under a completed ty root.  That is a
                                            // stale cross-kind continuation, not stronger evidence than the root
                                            // proof; demote it and leave the semantic_root_complete frontier intact.
                                            if crossKindSelectedStepper pref then
                                                let demotedRepeatCount = stableRootSelectedCount
                                                let cellSummary =
                                                    match pref.semanticCell with
                                                    | Some cell -> formatCell cell
                                                    | None -> "none"
                                                stableRootSelectedKey <- ""
                                                stableRootSelectedCount <- 0
                                                DiagJson.emit (
                                                    sprintf """{\"kind\":\"eval_worklist_cross_kind_selected_frontier_demoted\",\"event\":%s,\"repeated_kind\":%s,\"repeated_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"preserve_root_complete_build_attempt\"}"""
                                                        (esc event) (esc pref.kind) (esc pref.status) demotedRepeatCount stable_root_selected_frontier_repeat_cap (esc prefKey) (esc cellSummary) (pendingCount()))
                                                None, None
                                            else
                                                None, Some(pref, stableRootSelectedCount, prefKey)
                                    else
                                        Some pref, None
                                | None -> None, None
                            match selected with
                            | Some alt ->
                                let selectedRepeatCount, selectedKey = noteStableRootSelectedFrontierLocked blockedRootKey alt
                                let promotedTerminal =
                                    if alt.status = "semantic_apply_continuation_exception_blocked"
                                       || alt.status = "semantic_replay_payload_missing_blocked"
                                       || alt.status = "semantic_replay_child_schedule_repeat_blocked" then
                                        tryPromoteSelectedFrontierStepperLocked alt selectedRepeatCount selectedKey
                                    else None
                                match promotedTerminal with
                                | Some promoted ->
                                    Some (Choice1Of2(frame, promoted, repeatBlocked, selectedRepeatCount, selectedKey))
                                | None ->
                                    frontier <- Some alt
                                    replayScheduledKey <- None
                                    replayQueue <- []
                                    Some (Choice1Of2(frame, alt, repeatBlocked, selectedRepeatCount, selectedKey))
                            | None ->
                                match repeatBlocked with
                                | Some info -> Some (Choice2Of2 info)
                                | None -> None
                        | _ -> None)
                match switched with
                | Some (Choice1Of2(blocked, alt, repeatBlocked, selectedRepeatCount, selectedKey)) ->
                    match repeatBlocked with
                    | Some(repeated, repeatCount, repeatedKey) ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_blocked\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"repeated_kind\":%s,\"repeated_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"fallback_key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"alternate_frontier_selected\"}"
                                (esc event) (esc blocked.kind) (esc blocked.status) (esc repeated.kind) (esc repeated.status) (esc alt.kind) (esc alt.status) repeatCount stable_root_selected_frontier_repeat_cap (esc repeatedKey) (esc selectedKey) (pendingCount()))
                        if selectedKey = repeatedKey then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_forced\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"forced_kind\":%s,\"forced_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"forced_key\":%s,\"pending\":%d,\"single_flight\":1,\"policy\":\"no_alternate_frontier_force_only_live_child\",\"next\":\"retry_selected_frontier\"}"
                                    (esc event) (esc blocked.kind) (esc blocked.status) (esc alt.kind) (esc alt.status) repeatCount stable_root_selected_frontier_repeat_cap (esc selectedKey) (pendingCount()))
                    | None -> ()
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_stable_root_complete_yielded\",\"event\":%s,\"blocked_kind\":%s,\"blocked_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"selected_repeat_count\":%d,\"selected_repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"retry_selected_frontier\"}"
                            (esc event) (esc blocked.kind) (esc blocked.status) (esc alt.kind) (esc alt.status) selectedRepeatCount stable_root_selected_frontier_repeat_cap (pendingCount()))
                    Some alt
                | Some (Choice2Of2(repeated, repeatCount, repeatedKey)) ->
                    let promoted =
                        lock gate (fun () ->
                            tryPromoteSelectedFrontierStepperLocked repeated repeatCount repeatedKey)
                    match promoted with
                    | Some frame ->
                        Some frame
                    | None ->
                        let terminalFrame =
                            { repeated with
                                status = "semantic_selected_frontier_repeat_blocked"
                                reason = repeated.reason + ":selected_frontier_repeat_terminal" }
                        // A selected-frontier repeat is scheduler evidence. If a stronger
                        // semantic terminal was already pinned during replay, keep that terminal
                        // visible instead of overwriting it with the lower-rank repeat symptom.
                        let visibleFrame, priorRank, repeatRank, demotedBelowPinned, priorSource =
                            lock gate (fun () ->
                                let repeatRank = terminalContractRank terminalFrame.status
                                let liveRank =
                                    match pinnedTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                let durableRank =
                                    match durableTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                let priorSource, priorOpt, priorRank =
                                    if durableRank > liveRank then
                                        "durable_ledger", durableTerminalContract, durableRank
                                    elif liveRank > 0 then
                                        "live_pinned", pinnedTerminalContract, liveRank
                                    else
                                        "none", None, 0
                                match priorOpt with
                                | Some prior when priorRank > repeatRank ->
                                    frontier <- Some prior
                                    slotSetLocked prior
                                    prior, priorRank, repeatRank, true, priorSource
                                | _ ->
                                    frontier <- Some terminalFrame
                                    slotSetLocked terminalFrame
                                    pinTerminalContractLocked event terminalFrame
                                    terminalFrame, priorRank, repeatRank, false, priorSource)
                        if demotedBelowPinned then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_demoted_below_stronger_terminal\",\"event\":%s,\"repeat_status\":%s,\"repeat_rank\":%d,\"terminal_status\":%s,\"terminal_rank\":%d,\"terminal_site\":%s,\"terminal_source\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) (esc terminalFrame.status) repeatRank (esc visibleFrame.status) priorRank (esc visibleFrame.site) (esc priorSource) repeatCount stable_root_selected_frontier_repeat_cap (pendingCount()) (esc (terminalContractNext visibleFrame.status)))

                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_blocked\",\"event\":%s,\"blocked_kind\":\"unknown\",\"blocked_status\":\"semantic_root_complete\",\"repeated_kind\":%s,\"repeated_status\":%s,\"selected_kind\":%s,\"selected_status\":%s,\"visible_kind\":%s,\"visible_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"fallback_key\":\"none\",\"pending\":%d,\"single_flight\":1,\"next\":\"abort_precise_terminal\"}"
                                (esc event) (esc repeated.kind) (esc repeated.status) (esc terminalFrame.kind) (esc terminalFrame.status) (esc visibleFrame.kind) (esc visibleFrame.status) repeatCount stable_root_selected_frontier_repeat_cap (esc repeatedKey) (pendingCount()))
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_terminal\",\"event\":%s,\"repeated_kind\":%s,\"repeated_status\":%s,\"visible_status\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"repeated_key\":%s,\"pending\":%d,\"single_flight\":1,\"policy\":\"stop_forced_same_frontier_after_repeat_cap_preserve_stronger_terminal\",\"next\":%s}"
                                (esc event) (esc repeated.kind) (esc repeated.status) (esc visibleFrame.status) repeatCount stable_root_selected_frontier_repeat_cap (esc repeatedKey) (pendingCount()) (esc (terminalContractNext visibleFrame.status)))
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_selected_frontier_repeat_pinned_terminal\",\"event\":%s,\"status\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"repeat_count\":%d,\"repeat_cap\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc visibleFrame.status) (terminalContractRank visibleFrame.status) (esc visibleFrame.site) (esc visibleFrame.key) repeatCount stable_root_selected_frontier_repeat_cap (pendingCount()) (esc (terminalContractNext visibleFrame.status)))
                        Some visibleFrame
                | None -> None
            with _ -> None

        let private isTerminalAdapter (frame: Frame) =
            frame.status = "continuation_envelope"

        let private emitAdapter (event: string) (frame: Frame) =
            try
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_adapter\",\"event\":%s,\"adapter\":\"trace_continuation\",\"frame_kind\":%s,\"status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"payload\":%s,\"single_flight\":1,\"next\":%s}"
                        (esc event) (esc frame.kind) (esc frame.status) frame.cursor frame.trace.Length (esc (adapterPayload frame)) (esc (nextFor frame)))
            with _ -> ()

        let private scheduleReplay (event: string) (frame: Frame) =
            try
                let backfillCellOpt =
                    if Option.isNone frame.semanticCell && Option.isNone frame.semanticPayload then trySemanticCellForFrame frame
                    else None
                let payload = adapterPayload frame
                let key = replayKey frame
                let driver = replayDriverFor frame
                match backfillCellOpt with
                | Some cell ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_payload_backfilled_from_semantic_cell_cache\",\"event\":%s,\"frame_kind\":%s,\"frame_site\":%s,\"cell\":%s,\"single_flight\":1,\"next\":\"schedule_replay_with_semantic_payload\"}"
                            (esc event) (esc frame.kind) (esc frame.site) (esc (formatCell cell)))
                | None -> ()
                let task, duplicate =
                    lock gate (fun () ->
                        let incomingHasSemantic = payload.Contains("semantic_eval_payload(")
                        let wasMissingSemantic (t: ReplayTask) =
                            t.status = "driver_blocked_semantic_payload"
                            || t.payload.Contains("semantic_eval_payload_missing")
                        match replayScheduledKey with
                        | Some k when k = key ->
                            match replayQueue with
                            | h :: rest ->
                                // ALPHA447: same-key replay envelopes may first be scheduled from
                                // jp_wait_cycle_drain with semantic_eval_payload_missing, then later
                                // revisit the exact cursor after a same-kind semantic cell attaches.
                                // Do not keep the stale missing-payload task forever: refresh it and
                                // let the driver run again.  This preserves dedupe for identical
                                // empty envelopes while unblocking the real typed continuation.
                                if wasMissingSemantic h && incomingHasSemantic then
                                    let t = { h with payload = payload; status = "scheduled_replay"; event = event }
                                    replayQueue <- (t :: rest) |> List.truncate 16
                                    t, false
                                else
                                    h, true
                            | [] ->
                                replaySeq <- replaySeq + 1L
                                let t = { id = replaySeq; key = key; driver = driver; payload = payload; status = "scheduled_replay"; event = event }
                                replayQueue <- [t]
                                t, false
                        | _ ->
                            replaySeq <- replaySeq + 1L
                            let t = { id = replaySeq; key = key; driver = driver; payload = payload; status = "scheduled_replay"; event = event }
                            replayScheduledKey <- Some key
                            replayQueue <- (t :: replayQueue) |> List.truncate 16
                            t, false)
                // ALPHA455: a duplicate driver_blocked_semantic_payload task that still
                // carries semantic_eval_payload_missing is not progress.  Alpha454 allowed the
                // parent replay to reduce, but the follow-up jp_wait_cycle_drain repeatedly
                // reran an identical missing-payload envelope at sm'_operators.spi:19.  Park the
                // frontier as an explicit payload requirement until a later same-key envelope
                // refreshes the queued task with a real semantic_eval_payload(...).
                let blockedMissingDuplicate =
                    duplicate
                    && replayTaskStatusOfString task.status = ReplayTaskDriverBlockedSemanticPayload
                    && task.payload.Contains("semantic_eval_payload_missing")
                let rerunBlockedDuplicate = duplicate && replayTaskStatusOfString task.status = ReplayTaskDriverBlockedSemanticPayload && not blockedMissingDuplicate
                let readyDuplicateCandidate =
                    duplicate
                    && (match replayTaskStatusOfString task.status with | ReplayTaskDriverReadyReplayCell | ReplayTaskDriverReadySemanticPayload -> true | _ -> false)
                    && frame.status = "continuation_envelope"
                    && frame.reason.Contains("leaf_yield_terminal_let_cycle_replay")
                let readyDuplicateAttempt =
                    if readyDuplicateCandidate then lock gate (fun () -> noteReadyDuplicateReplayRerunLocked key) else 0
                let rerunReadyDuplicate = readyDuplicateCandidate && readyDuplicateAttempt <= 4
                let blockReadyDuplicate = readyDuplicateCandidate && readyDuplicateAttempt > 4
                let duplicateNext =
                    if blockedMissingDuplicate then "blocked_payload_duplicate_suppressed"
                    elif rerunBlockedDuplicate then "rerun_blocked_replay_driver"
                    elif rerunReadyDuplicate then "rerun_ready_duplicate_replay_driver"
                    elif blockReadyDuplicate then "ready_duplicate_replay_cap"
                    else "already_scheduled"
                let scheduledStatusDuText = replayTaskStatusToString (replayTaskStatusOfString task.status)
                let scheduledDriverDuText = replayDriverToString (replayDriverOfString task.driver)
                let scheduledLiveness = captureReplayLiveness()
                let scheduledOwnerDuText = replayHandoffOwnerToString (replayHandoffOwnerForState "schedule" scheduledLiveness.queueDepth scheduledLiveness.activeDepth 4 task.status)
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_replay_schedule\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"driver_du\":%s,\"status\":%s,\"status_du\":%s,\"owner_du\":%s,\"liveness_du\":%s,\"queue_depth\":%d,\"active_depth\":%d,\"pending\":%d,\"duplicate\":%d,\"payload\":%s,\"single_flight\":1,\"next\":%s}"
                        (esc event) task.id (esc task.driver) (esc scheduledDriverDuText) (esc task.status) (esc scheduledStatusDuText) (esc scheduledOwnerDuText) (esc (replayObligationLivenessKindText scheduledLiveness.kind)) scheduledLiveness.queueDepth scheduledLiveness.activeDepth scheduledLiveness.pending (if duplicate then 1 else 0) (esc task.payload) (esc (if duplicate then duplicateNext else task.driver)))
                if blockedMissingDuplicate then
                    let payloadFrameOpt =
                        lock gate (fun () ->
                            match frontier with
                            | Some frame ->
                                let frame' = { frame with status = "semantic_replay_payload_missing_blocked"; reason = frame.reason + ":missing_semantic_payload_scheduler_terminal" }
                                let payloadRank = terminalContractRank frame'.status
                                let priorRank =
                                    match pinnedTerminalContract with
                                    | Some prior -> terminalContractRank prior.status
                                    | None -> 0
                                pinnedReplayPayloadMissing <- Some frame'
                                pinTerminalContractLocked event frame'
                                // ALPHA569: payload-missing is evidence that the scheduler lacks a
                                // typed cell, not stronger semantic evidence than an already pinned
                                // TV/TJoinPoint/value blocker.  Keep the concrete terminal as the
                                // visible frontier when it has a higher rank.
                                if priorRank > payloadRank then
                                    match pinnedTerminalContract with
                                    | Some prior ->
                                        frontier <- Some prior
                                        slotSetLocked prior
                                    | None -> ()
                                else
                                    frontier <- Some frame'
                                    slotSetLocked frame'
                                Some(frame', priorRank, payloadRank)
                            | None -> None)
                    match payloadFrameOpt with
                    | Some(_, priorRank, payloadRank) when priorRank > payloadRank ->
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_replay_payload_missing_demoted_below_pinned_terminal\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"payload_rank\":%d,\"pinned_rank\":%d,\"pending\":%d,\"single_flight\":1,\"next\":\"prefer_concrete_pinned_terminal\"}"
                                (esc event) task.id (esc task.driver) payloadRank priorRank (pendingCount()))
                    | _ -> ()
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_payload_missing_blocked\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":\"semantic_replay_payload_missing_blocked\",\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_eval_worklist_replay_payload_required\"}"
                            (esc event) task.id (esc task.driver) (replayQueueDepth()) (esc task.payload) (pendingCount()))
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_replay_payload_missing_pinned\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"status\":\"semantic_replay_payload_missing_blocked\",\"pending\":%d,\"single_flight\":1,\"next\":\"prefer_payload_missing_terminal\"}"
                            (esc event) task.id (esc task.driver) (pendingCount()))
                elif blockReadyDuplicate then
                    lock gate (fun () ->
                        match frontier with
                        | Some frame ->
                            let frame' =
                                { frame with
                                    status = "semantic_replay_fingerprint_repeat_blocked"
                                    reason = frame.reason + ":ready_duplicate_replay_cap" }
                            frontier <- Some frame'
                            slotSetLocked frame'
                        | None -> ())
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_ready_duplicate_replay_cap\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"attempt\":%d,\"cap\":4,\"status\":\"semantic_replay_fingerprint_repeat_blocked\",\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"explicit_eval_worklist_replay_fingerprint_repeat_required\"}"
                            (esc event) task.id (esc task.driver) readyDuplicateAttempt (replayQueueDepth()) (esc task.payload) (pendingCount()))
                elif (not duplicate) || rerunBlockedDuplicate || rerunReadyDuplicate then
                    if rerunReadyDuplicate then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_ready_duplicate_replay_driver_rerun\",\"event\":%s,\"replay_id\":%d,\"driver\":%s,\"attempt\":%d,\"cap\":4,\"queue_depth\":%d,\"payload\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) task.id (esc task.driver) readyDuplicateAttempt (replayQueueDepth()) (esc task.payload) (pendingCount()) (esc task.driver))
                    runReplayDriver event
            with _ -> ()

        let private beginRun (event: string) =
            let mutable acquired = false
            let mutable waits = 0
            acquired <-
                lock gate (fun () ->
                    if activeRun then false
                    else activeRun <- true; true)
            if not acquired then
                waits <- 1
                try
                    lock gate (fun () -> drainParentCacheHandoffsLocked event 64) |> ignore
                    let cycleBreakInjected =
                        tryForceDeferredTypeVarCycleBreak event "single_flight_busy_cross_kind_cycle_break"
                    if cycleBreakInjected || replayQueueDepth() > 0 || EvalReplayValueStore.hasDeferredReplayCell() || EvalReplayValueStore.parentCacheHandoffQueueDepth() > 0 then
                        replayDriverCooperativeTickFromGlobalFuse event "single_flight_busy_graph_mutation_tick" |> ignore
                with _ -> ()
                acquired <-
                    lock gate (fun () ->
                        if activeRun then false
                        else activeRun <- true; true)
            if waits > 0 then
                try
                    DiagJson.emit (
                        sprintf "{\"kind\":\"%s\",\"event\":%s,\"waits\":%d,\"wait_ms\":0,\"parent_cache_handoffs\":%d,\"single_flight\":1,\"next\":\"%s\"}"
                            (if acquired then "eval_worklist_single_flight_reacquired_after_graph_tick" else "eval_worklist_single_flight_busy_no_sync_wait")
                            (esc event) waits (EvalReplayValueStore.parentCacheHandoffQueueDepth())
                            (if acquired then "bounded_trampoline" else "return_busy_frontier"))
                with _ -> ()
            acquired

        let private endRun () =
            lock gate (fun () -> activeRun <- false)

        let private stepOnce (event: string) (step: int) (limit: int) : Frame option =
            lock gate (fun () ->
                match frontier with
                | None -> None
                | Some f ->
                    let loc = traceAt f f.cursor
                    let capturedLeafCell =
                        f.status = "semantic_leaf_complete"
                        && (match f.semanticCell with
                            | Some cell -> cell.status = "captured" || cell.status = "new"
                            | None -> false)
                    let lateCapturedLeafCell =
                        capturedLeafCell
                        && f.cursor >= f.trace.Length
                    let orphanCapturedLeafCell =
                        event = "retry_stop_drain"
                        && capturedLeafCell
                        && f.cursor < f.trace.Length
                        && replayQueueDepth() = 0
                    let status', cursor', next' =
                        if f.status = "semantic_replay_driver_exception_blocked" then
                            f.status, f.cursor, "explicit_eval_worklist_replay_driver_exception_required"
                        elif f.status = "semantic_replay_fingerprint_repeat_blocked" then
                            f.status, f.cursor, "explicit_eval_worklist_replay_fingerprint_repeat_required"
                        elif f.status = "semantic_joinpoint_term_stepper_blocked" then
                            f.status, f.cursor, "explicit_eval_worklist_joinpoint_term_stepper_required"
                        elif f.status = "semantic_joinpoint_value_blocked" then
                            f.status, f.cursor, "explicit_eval_worklist_joinpoint_value_required"
                        elif lateCapturedLeafCell then
                            "continuation_envelope", f.cursor, "replay_late_captured_leaf_cell"
                        elif orphanCapturedLeafCell then
                            "continuation_envelope", f.cursor, "replay_orphan_captured_leaf_cell"
                        elif isSemanticTerminalStatus f.status then
                            // ALPHA389: never rebuild a replay envelope from a semantic terminal state.
                            // Root completion must survive retry_stop_drain so BuildFile can retry safely.
                            f.status, f.cursor, semanticTerminalNext f.status
                        elif f.status = "continuation_envelope" then
                            "continuation_envelope", f.cursor, "schedule_term_ty_replay"
                        elif f.cursor < f.trace.Length then
                            "tracing_explicit_loop", f.cursor + 1, "advance_trace_cursor"
                        else
                            // ALPHA343/345: terminal replay envelope + driver scheduling. Do not advance forever after the trace is exhausted;
                            // materialize a deterministic continuation payload with replay anchors instead of a bare adapter gate marker.
                            "continuation_envelope", f.cursor, "build_replay_continuation_envelope"
                    let f' = { f with status = status'; cursor = cursor' }
                    frontier <- Some f'
                    emit (event + ":step") f'
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_step\",\"event\":%s,\"step\":%d,\"budget\":%d,\"frame_kind\":%s,\"status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"trace_loc\":%s,\"single_flight\":1,\"next\":%s}"
                            (esc event) step limit (esc f'.kind) (esc f'.status) f'.cursor f'.trace.Length (esc loc) (esc next'))
                    if next' = "replay_late_captured_leaf_cell" || next' = "replay_orphan_captured_leaf_cell" then
                        let cellText =
                            match f.semanticCell with
                            | Some cell -> formatCell cell
                            | None -> "none"
                        let marker =
                            if next' = "replay_orphan_captured_leaf_cell"
                            then "eval_worklist_orphan_captured_leaf_cell_replayed"
                            else "eval_worklist_late_captured_leaf_cell_replayed"
                        DiagJson.emit (
                            sprintf "{\"kind\":%s,\"event\":%s,\"frame_kind\":%s,\"frame_status\":%s,\"cursor\":%d,\"trace_lines\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"schedule_term_ty_replay\"}"
                                (esc marker) (esc event) (esc f.kind) (esc f.status) f.cursor f.trace.Length (esc cellText) (pendingCount()))
                    if isTerminalAdapter f' then
                        emitAdapter event f'
                        scheduleReplay event f'
                    Some f')

        let runBounded (event: string) (budget: int) : Frame option =
            try
                let limit = if budget <= 0 then 1 else min budget 256
                if beginRun event then
                    try
                        let mutable steps = 0
                        let mutable last : Frame option = tryPeek()
                        let mutable blocked = false
                        while steps < limit && not blocked do
                            match stepOnce event steps limit with
                            | Some f ->
                                last <- Some f
                                steps <- steps + 1
                                blocked <- isTerminalAdapter f || isSemanticTerminalStatus f.status || f.status = "semantic_replay_fingerprint_repeat_blocked" || f.status = "semantic_joinpoint_term_stepper_blocked" || f.status = "semantic_joinpoint_value_blocked" || f.status = "semantic_replay_driver_exception_blocked" || f.status = "semantic_replay_payload_missing_blocked" || f.status = "semantic_payload_required"
                            | None ->
                                blocked <- true
                        let finalCursor =
                            match last with
                            | Some f -> f.cursor
                            | None -> -1
                        let finalStatus =
                            match last with
                            | Some f -> f.status
                            | None -> "empty"
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_run\",\"event\":%s,\"steps\":%d,\"budget\":%d,\"pending\":%d,\"single_flight\":1,\"skipped\":0,\"final_status\":%s,\"cursor\":%d}"
                                (esc event) steps limit (pendingCount()) (esc finalStatus) finalCursor)
                        last
                    finally
                        endRun ()
                else
                    let frame = tryPeek()
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_run\",\"event\":%s,\"steps\":0,\"budget\":%d,\"pending\":%d,\"single_flight\":1,\"skipped\":1,\"final_status\":%s,\"cursor\":%d}"
                            (esc event) limit (pendingCount())
                            (esc (match frame with Some f -> f.status | None -> "empty"))
                            (match frame with Some f -> f.cursor | None -> -1))
                    frame
            with _ -> None

        // ALPHA388: retry_stop is the supervisor's last synchronous chance to
        // finish a captured explicit worklist frontier.  Alpha387 proved that
        // ty replay could be half-drained (cursor=16/32) while another Hopac
        // worker still held the single-flight run token; retry_stop then
        // reported driver_state=none and aborted before the typed cell could
        // reach the replay driver.  Wait briefly for the active token, then run
        // a larger bounded drain.  This only advances trace/replay state; it
        // does not mark semantic_root_complete unless the typed stepper itself
        // proves it.
        let private drainAfterActiveRun (event: string) (budget: int) : Frame option =
            let limit = if budget <= 0 then 256 else min 768 (max 256 budget)
            // ALPHA471: the repeat-yield path can expose a two-kind dynamic-arg handoff
            // (term EApply blocked while a ty/TFun frontier resolves).  Keep the bound small,
            // but allow enough passes to alternate once after the first explicit dynamic block.
            let baseMaxPasses = 32
            // ALPHA507: retry_stop_drain may still be making real queued-replay
            // progress after twelve passes (alpha506 ended with replay_queue=1 and
            // a term_replay_driver still advancing the dynamic-record bridge).  Extend
            // only this terminal drain, and keep the bound finite/fail-closed.
            let maxPasses =
                // ALPHA508: alpha507 still made visible forward progress at pass 63
                // (same live queue, higher replay id, higher EApply step).  Keep the
                // extension terminal-only and finite, but allow enough turns for this
                // dynamic-record bridge to either discharge or reveal the next blocker.
                if event = "retry_stop_drain" then 384
                else baseMaxPasses
            let mutable waits = 0
            if lock gate (fun () -> activeRun) then
                waits <- 1
                try
                    replayDriverCooperativeTickFromGlobalFuse event "drain_after_active_run_no_sync_wait" |> ignore
                with _ -> ()
            let before = tryPeek()
            let mutable after = before
            let mutable pass = 0
            let mutable keepGoing = true
            while keepGoing && pass < maxPasses do
                if lock gate (fun () -> activeRun) then
                    keepGoing <- false
                else
                    if pass > 0 then
                        let status, cursor, next =
                            match after with
                            | Some frame -> frame.status, frame.cursor, nextFor frame
                            | None -> "missing_before_retry_drain_continue", -1, "retry_stop_raise"
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_retry_drain_continue\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) pass (esc status) cursor (hasReplayComplete()) (pendingCount()) (esc next))
                    if event = "retry_stop_drain" && pass >= baseMaxPasses && replayQueueDepth() > 0 then
                        let status, cursor, next =
                            match after with
                            | Some frame -> frame.status, frame.cursor, nextFor frame
                            | None -> "missing_before_retry_drain_live_queue_extend", -1, "run_replay_driver"
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_retry_drain_live_queue_extend\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                (esc event) pass (esc status) cursor (replayQueueDepth()) (pendingCount()) (esc next))
                    let drained = runBounded event limit
                    // ALPHA403: runBounded returns the last pre-driver frame when a synchronous
                    // replay driver commits semantic_root_complete from scheduleReplay.  Re-peek
                    // after the drain so callers do not see stale continuation_envelope.
                    let canonical0 =
                        match tryPeek() with
                        | Some frame when frame.status = "semantic_parent_continuation_cycle_blocked" -> Some frame
                        | Some frame when hasReplayComplete() -> Some frame
                        | _ -> drained
                    let canonicalFingerprintQueued =
                        match canonical0 with
                        | Some frame when event = "retry_stop_drain" && (frame.status = "semantic_replay_fingerprint_repeat_blocked" || frame.status = "semantic_joinpoint_term_stepper_blocked") && replayQueueDepth() > 0 ->
                            let qd0 = replayQueueDepth()
                            let cellText =
                                match frame.semanticCell with
                                | Some cell -> formatCell cell
                                | None -> "none"
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_replay_fingerprint_live_queue_drain\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_before\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"run_replay_driver\"}"
                                    (esc event) (esc frame.status) frame.cursor qd0 (esc cellText) (pendingCount()))
                            runReplayDriver event
                            let qd1 = replayQueueDepth()
                            let afterDriver =
                                match tryPeek() with
                                | Some frame' -> Some frame'
                                | None -> canonical0
                            let statusAfter, cursorAfter =
                                match afterDriver with
                                | Some frame' -> frame'.status, frame'.cursor
                                | None -> "missing_after_fingerprint_live_queue_drain", -1
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_replay_fingerprint_live_queue_drain_result\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) (esc statusAfter) cursorAfter qd1 (pendingCount()) (esc (if qd1 > 0 then "continue_retry_drain" else "retry_drain_repeek")))
                            afterDriver
                        | _ -> canonical0
                    let canonicalQueued =
                        match canonicalFingerprintQueued with
                        | Some frame when frame.status = "semantic_leaf_complete" && replayQueueDepth() > 0 ->
                            let qd0 = replayQueueDepth()
                            let cellText =
                                match frame.semanticCell with
                                | Some cell -> formatCell cell
                                | None -> "none"
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_leaf_complete_queued_replay_drain\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_before\":%d,\"cell\":%s,\"pending\":%d,\"single_flight\":1,\"next\":\"run_replay_driver\"}"
                                    (esc event) (esc frame.status) frame.cursor qd0 (esc cellText) (pendingCount()))
                            runReplayDriver event
                            let qd1 = replayQueueDepth()
                            let afterDriver =
                                match tryPeek() with
                                | Some frame' -> Some frame'
                                | None -> canonicalFingerprintQueued
                            let statusAfter, cursorAfter =
                                match afterDriver with
                                | Some frame' -> frame'.status, frame'.cursor
                                | None -> "missing_after_leaf_queued_replay_drain", -1
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_leaf_complete_queued_replay_drain_result\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"queue_depth_after\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) (esc statusAfter) cursorAfter qd1 (pendingCount()) (esc (if qd1 > 0 then "continue_retry_drain" else "retry_drain_repeek")))
                            afterDriver
                        | _ -> canonicalFingerprintQueued
                    let canonical =
                        match canonicalQueued with
                        | Some frame ->
                            match tryYieldParentContinuationCycleBlocked event frame with
                            | Some selected -> Some selected
                            | None ->
                                match tryYieldTypeVariableValueMissingBlocked event frame with
                                | Some selected -> Some selected
                                | None ->
                                    match tryYieldStaleRootRetargetBlocked event frame with
                                    | Some selected -> Some selected
                                    | None ->
                                        match tryYieldLeafParentContinuationBlocked event frame with
                                        | Some selected -> Some selected
                                        | None ->
                                            match tryYieldReplayFingerprintRepeatBlocked event frame with
                                            | Some selected -> Some selected
                                            | None ->
                                                match tryYieldDynamicArgApplyBlocked event frame with
                                                | Some selected -> Some selected
                                                | None -> canonicalQueued
                        | None -> canonicalQueued
                    let canonical =
                        match canonical with
                        | Some frame -> preferPinnedTerminalForRetryDrain event frame
                        | None -> None
                    match canonical with
                    | Some frame ->
                        after <- Some frame
                        pass <- pass + 1
                        pinTerminalContract event frame
                        if (event = "retry_stop_drain" || event = "jp_wait_cycle_drain") && (frame.status = "semantic_replay_fingerprint_repeat_blocked" || frame.status = "semantic_joinpoint_term_stepper_blocked") then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_terminal_replay_fingerprint_repeat_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"queue_depth\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc frame.status) frame.cursor (replayQueueDepth()) (pendingCount()) (esc (nextFor frame)))
                            keepGoing <- false
                        elif event = "retry_stop_drain" && frame.status = "semantic_let_success_apply_exception_blocked" && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_terminal_let_success_apply_exception_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc frame.status) frame.cursor (pendingCount()) (esc (nextFor frame)))
                            keepGoing <- false
                        elif isTerminalContractStatus frame.status then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_terminal_contract_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"rank\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc frame.status) frame.cursor (terminalContractRank frame.status) (pendingCount()) (esc (nextFor frame)))
                            keepGoing <- false
                        elif event = "retry_stop_drain" && frame.status = "semantic_replay_driver_exception_blocked" && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_terminal_replay_exception_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc frame.status) frame.cursor (pendingCount()) (esc (nextFor frame)))
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frame.status = "semantic_root_complete" && pendingCount() > 0 && replayQueueDepth() = 0 && (hasProgressYield() || replayDriverActiveDepthValue() > 0) then
                            // ALPHA953: pending-jobs terminals are only hard terminals when
                            // the typed liveness seam says no cooperative replay is still in
                            // flight. Runtime 952 showed this terminal could pin while a
                            // progress-yield retry and deferred parent replay were still
                            // observable immediately afterwards.
                            after <- Some frame
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_root_complete_pending_jobs_progress_yield_allowed\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"progress_yield_pending\":%b,\"policy\":\"defer_pending_jobs_terminal_while_typed_replay_liveness_is_present\",\"single_flight\":1,\"next\":\"retry_stop_progress_yield\"}"
                                    (esc event) pass (esc frame.status) frame.cursor (pendingCount()) (replayQueueDepth()) (replayDriverActiveDepthValue()) (hasProgressYield()))
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frame.status = "semantic_root_complete" && pendingCount() > 0 && replayQueueDepth() = 0 then
                            // ALPHA939: alpha938 proved the ty-reentry preflight can drain and return
                            // concrete typed values, but retry_stop_drain could still stop on a
                            // semantic_root_complete frontier while JP bookkeeping reported outstanding
                            // bodies and no replay queue. Make that state an explicit terminal contract
                            // instead of falling back to an open-ended wait/manual interrupt. This does
                            // not close the writer barrier, does not mark BuildFile.replay_root_complete,
                            // and does not synthesize missing JP bodies.
                            let blockedCellOpt =
                                match frame.semanticCell with
                                | Some cell -> Some { cell with status = "semantic_root_complete_pending_jobs_blocked" }
                                | None -> None
                            let blockedPayload =
                                match blockedCellOpt with
                                | Some cell -> Some (formatCellPayload cell)
                                | None -> frame.semanticPayload
                            let blockedFrame =
                                { frame with
                                    status = "semantic_root_complete_pending_jobs_blocked"
                                    reason = "retry_stop_root_complete_pending_jobs_no_queue"
                                    semanticCell = blockedCellOpt
                                    semanticPayload = blockedPayload }
                            after <- Some blockedFrame
                            pinTerminalContract event blockedFrame
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_retry_stop_root_complete_pending_jobs_terminal_pinned\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"rank\":%d,\"queue_depth\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc blockedFrame.status) blockedFrame.cursor (pendingCount()) (terminalContractRank blockedFrame.status) (replayQueueDepth()) (esc (terminalContractNext blockedFrame.status)))
                            keepGoing <- false
                        elif event = "retry_stop_drain" && pass >= baseMaxPasses && frame.status = "semantic_leaf_complete" && replayQueueDepth() = 0 then
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_terminal_leaf_no_queue_drain_stopped\",\"event\":%s,\"pass\":%d,\"status\":%s,\"cursor\":%d,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                                    (esc event) pass (esc frame.status) frame.cursor (pendingCount()) (esc (nextFor frame)))
                            keepGoing <- false
                    | None ->
                        keepGoing <- false
                        pass <- pass + 1
            match after with
            | Some _ -> after
            | None -> before

        let drainRetryStop (budget: int) : Frame option =
            drainAfterActiveRun "retry_stop_drain" budget

        // ALPHA392: forced sequential jp_wait can observe a term-cycle fuse before
        // EJP0014.  Alpha391 proved this path may already have a live frontier at
        // cursor=8/32, but the small jp_wait slice only advanced to cursor=24 and
        // left retry_stop to finish.  Drain the same frontier here, while preserving
        // the invariant that only typed replay may set semantic_root_complete.
        let drainJpCyclePreflight (budget: int) : Frame option =
            try
                let before = tryPeek()
                let after = drainAfterActiveRun "jp_wait_cycle_drain" budget
                let status, cursor, complete, next =
                    match after with
                    | Some frame -> frame.status, frame.cursor, hasReplayComplete(), nextFor frame
                    | None -> "missing_after_cycle_drain", -1, hasReplayComplete(), "jp_wait_cycle_raise"
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_jp_cycle_preflight\",\"event\":\"jp_wait_observed_sequential_replay_repeat_guard\",\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                        (esc status) cursor complete (pendingCount()) (esc next))
                match after with
                | Some _ -> after
                | None -> before
            with _ -> None

        // ALPHA391: EJP0014 jp_wait stalls are liveness frontiers too.  If a
        // semantic worklist frame is already present, or a cycle fuse can be
        // captured, spend a bounded synchronous slice draining it before the
        // retry path invalidates the generation.  This preserves alpha390's
        // write-gate strictness: only typed replay can set semantic_root_complete.
        let drainJpStallPreflight (event: string) (budget: int) : Frame option =
            try
                let before =
                    match tryPeek() with
                    | Some frame -> Some frame
                    | None -> ensureCaptured "jp_wait_stall_preflight"
                match before with
                | Some _ ->
                    promoteHead event |> ignore
                    let after = drainRetryStop budget
                    let status, cursor, complete, next =
                        match after with
                        | Some frame -> frame.status, frame.cursor, hasReplayComplete(), nextFor frame
                        | None -> "missing_after_drain", -1, hasReplayComplete(), "abort_without_write"
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_jp_stall_preflight\",\"event\":%s,\"status\":%s,\"cursor\":%d,\"replayCompleteNow\":%b,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                            (esc event) (esc status) cursor complete (pendingCount()) (esc next))
                    after
                | None ->
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_jp_stall_preflight\",\"event\":%s,\"status\":\"missing_frontier\",\"cursor\":-1,\"replayCompleteNow\":false,\"pending\":0,\"single_flight\":1,\"next\":\"jp_wait_retry_diag\"}"
                            (esc event))
                    None
            with _ -> None

        let ensureCapturedAndRun (reason: string) (event: string) (budget: int) : Frame option =
            match ensureCaptured reason with
            | Some _ ->
                promoteHead event |> ignore
                runBounded event budget
            | None -> None

        let requiredMessage (msg: string) (frame: Frame) =
            let cellState = match frame.semanticCell with Some c -> formatCell c | None -> "none"
            let replayComplete = frame.status = "semantic_root_complete" || (match frame.semanticCell with Some c -> c.status = "semantic_root_complete" | None -> false)
            let completeness =
                if replayComplete then "complete"
                elif frame.status = "semantic_leaf_complete" then "leaf_complete_parent_continuation_missing"
                elif frame.status = "semantic_leaf_parent_continuation_missing_blocked" then "leaf_parent_continuation_missing_blocked"
                elif frame.status = "semantic_selected_frontier_repeat_blocked" then "selected_frontier_repeat_blocked"
                elif frame.status = "semantic_replay_driver_exception_blocked" then "replay_driver_exception_blocked"
                elif frame.status = "semantic_replay_payload_missing_blocked" then "replay_payload_missing_blocked"
                elif frame.status = "semantic_joinpoint_value_blocked" then "joinpoint_value_blocked"
                elif frame.status = "semantic_replay_fingerprint_repeat_blocked" then "replay_fingerprint_repeat_blocked"
                elif frame.status = "semantic_if_unknown_return_condition_blocked" then "if_unknown_return_condition_blocked"
                elif frame.status = "semantic_if_symbolic_condition_blocked" then "if_symbolic_condition_blocked"
                elif frame.status = "semantic_joinpoint_term_stepper_blocked" then "joinpoint_term_stepper_blocked"
                elif frame.status = "semantic_macro_thunk_missing_blocked" then "macro_thunk_missing_blocked"
                elif frame.status = "semantic_tjoinpoint_stepper_blocked" then "tjoinpoint_stepper_blocked"
                elif frame.status = "semantic_literal_op_body_stepper_blocked" then "literal_op_body_stepper_blocked"
                elif frame.status = "semantic_dynamic_join_apply_blocked" then "dynamic_join_apply_blocked"
                elif frame.status = "semantic_nominal_constructor_stepper_blocked" then "nominal_constructor_stepper_blocked"
                elif frame.status = "semantic_seq_type_error_blocked" then "seq_type_error_blocked"
                elif frame.status = "semantic_parent_continuation_cycle_blocked" then "parent_continuation_cycle_blocked"
                elif frame.status = "semantic_global_fuse_parent_continuation_cycle_blocked" then "global_fuse_parent_continuation_cycle_blocked"
                elif frame.status = "semantic_parent_replay_status_preserved_repeat_blocked" then "parent_replay_status_preserved_repeat_blocked"
                elif frame.status = "semantic_replay_obligation_deferred" then "replay_obligation_deferred"
                elif frame.status = "semantic_type_variable_value_missing_blocked" then "type_variable_value_missing_blocked"
                elif frame.status = "semantic_stale_root_retarget_blocked" then "stale_root_retarget_blocked"
                elif frame.status = "semantic_let_success_apply_exception_blocked" then "let_success_apply_exception_blocked"
                elif frame.status = "semantic_let_success_all_ready_apply_blocked" then "let_success_all_ready_apply_blocked"
                elif frame.status = "semantic_let_success_apply_continuation_blocked" then "let_success_apply_continuation_blocked"
                elif frame.status = "semantic_type_apply_forall_body_stepper_blocked" then "type_apply_forall_body_stepper_blocked"
                elif frame.status = "semantic_apply_continuation_exception_blocked" then "apply_continuation_exception_blocked"
                elif frame.status = "semantic_deferred_function_replay_exception_blocked" then "deferred_function_replay_exception_blocked"
                elif frame.status = "semantic_step_partial" || frame.status = "semantic_step_done" then "partial_one_step_only"
                else "not_complete"
            sprintf "%s\nEvalWorklistFrame: kind=%s status=%s site=%s key=%s reason=%s depth=%d re=%d/%d trace_lines=%d pending=%d cursor=%d single_flight=1 replay_queue=%d semantic_payload=%s replay_complete=%b replay_completeness=%s replay_cell=%s adapter=trace_replay_continuation next=%s driver=%s driver_state=%s payload=%s"
                msg frame.kind frame.status frame.site frame.key (compactFrameReason frame.reason) frame.depth frame.re frame.maxRe frame.trace.Length (pendingCount()) frame.cursor (replayQueueDepth()) (semanticPayloadStatus()) replayComplete completeness cellState (nextFor frame) (replayDriverFor frame) (replayDriverStatus()) (adapterPayload frame)


        // ALPHA540: when a global fuse abort is raised after retry_stop has already
        // selected a high-rank terminal, make the raised message name that terminal.
        // This prevents run_tests/root-source traces from looking like the live
        // problem when the real blocker is the pinned macro/literal/payload contract.
        //
        // ALPHA541: the alpha540 marker proved the retarget worked but also showed
        // unbounded marker churn: 377 retarget events in alpha540, followed by stale
        // semantic_root_complete returns.  Treat rank >= 80 pinned terminals as a
        // hard global-fuse contract and rate-limit marker emission by pinned key.
        let private globalFuseTerminalRetargetSeen = System.Collections.Concurrent.ConcurrentDictionary<string, int>()

        let private retargetSeenOnce (key: string) =
            globalFuseTerminalRetargetSeen.TryAdd(key, 1)

        let private highRankPinnedTerminal (requestedKind: string) =
            match tryPinnedTerminalContract() with
            | Some pinned ->
                let rank = terminalContractRank pinned.status
                let missingAfterPrefetchDecisionId =
                    missingAfterPrefetchTerminalDecisionFor
                        pinned.status
                        (pendingCount())
                        (replayQueueDepth())
                        (replayDriverActiveDepthValue())
                        (hasProgressYield())
                        (hasReplayComplete())
                        (hasReplayCompleteWriteWitness())
                        0
                let missingAfterPrefetchRetargetDeferred =
                    missingAfterPrefetchTerminalDecisionShouldDefer missingAfterPrefetchDecisionId
                if missingAfterPrefetchRetargetDeferred then
                    if retargetSeenOnce (sprintf "missing-after-prefetch-high-rank|%s|%s|%s" requestedKind pinned.status pinned.key) then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_missing_after_prefetch_high_rank_retarget_deferred\",\"event\":\"global_fuse_terminal_probe\",\"requested_kind\":%s,\"pinned_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"decision_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"replay_complete\":%b,\"write_witness\":%b,\"single_flight\":1,\"next\":\"preserve_replay_lane_before_missing_after_prefetch_terminal\"}"
                                (esc requestedKind) (esc pinned.kind) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (esc (missingAfterPrefetchTerminalDecisionText missingAfterPrefetchDecisionId)) (pendingCount()) (replayQueueDepth()) (replayDriverActiveDepthValue()) (hasReplayComplete()) (hasReplayCompleteWriteWitness()))
                    None
                elif rank >= 80 && frameKindCompatible requestedKind pinned then Some (pinned, rank)
                elif rank >= 80 then
                    // ALPHA1047: pre-Hopac kind locality. A high-rank terminal from a
                    // different evaluator kind is evidence for its own lane, not a
                    // selector for this global-fuse probe. Clear only the active pin;
                    // durable evidence remains available to same-kind consumers.
                    let cleared = lock gate (fun () -> clearCurrentCrossKindPinnedTerminalLocked pinned)
                    emitCrossKindPinnedTerminalIgnored "global_fuse_terminal_probe" requestedKind pinned rank (sprintf "high_rank_terminal_belongs_to_other_kind cleared=%b" cleared)
                    if cleared then
                        DiagJson.emit (
                            sprintf """{\"kind\":\"eval_worklist_cross_kind_global_fuse_active_pin_cleared\",\"event\":\"global_fuse_terminal_probe\",\"requested_kind\":%s,\"pinned_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"single_flight\":1,\"policy\":\"pre_hopac_kind_local_terminal_contracts\",\"next\":\"preserve_kind_local_frontier\"}"""
                                (esc requestedKind) (esc pinned.kind) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()))
                    None
                else None
            | None -> None

        let private trimOriginalFuseForMessage (msg: string) =
            let withoutFrame =
                let marker = "\nEvalWorklistFrame:"
                let idx = msg.IndexOf(marker, System.StringComparison.Ordinal)
                if idx >= 0 then msg.Substring(0, idx) else msg
            withoutFrame.Replace("\r", " ").Replace("\n", " ⏎ ")

        // ALPHA1192: terminal-primary retargets now expose the dynamic-join/root
        // fuse cause through a DU.  The final text can still carry the original
        // human-readable fuse, but downstream receipts can key on terminal_cause_du
        // instead of scanning message substrings.
        type TerminalPrimaryCauseId =
            | TerminalCauseDynamicJoinRuntimeDynTypecheck
            | TerminalCauseDynamicJoinFunctionBodyDynamicArg
            | TerminalCauseParentContinuationReplayCapExhausted
            | TerminalCauseTyParentContinuationReplayCapExhausted
            | TerminalCauseGlobalFuseAbort
            | TerminalCausePinnedTerminal

        let terminalPrimaryCauseText = function
            | TerminalCauseDynamicJoinRuntimeDynTypecheck -> "dynamic_join_runtime_dyn_typecheck"
            | TerminalCauseDynamicJoinFunctionBodyDynamicArg -> "dynamic_join_function_body_dynamic_arg"
            | TerminalCauseParentContinuationReplayCapExhausted -> "parent_continuation_replay_cap_exhausted"
            | TerminalCauseTyParentContinuationReplayCapExhausted -> "ty_parent_continuation_replay_cap_exhausted"
            | TerminalCauseGlobalFuseAbort -> "global_fuse_abort"
            | TerminalCausePinnedTerminal -> "pinned_terminal"

        let terminalPrimaryCauseFor (msg: string) (pinned: Frame) =
            let safeMsg = if System.String.IsNullOrEmpty msg then "" else msg
            let safeReason = if System.String.IsNullOrEmpty pinned.reason then "" else pinned.reason
            let blob = safeMsg + "\n" + safeReason
            if pinned.status = semanticStatusToString SemanticDynamicJoinApplyBlocked && blob.IndexOf("runtime_function_apply_requires_dyn_typecheck", System.StringComparison.Ordinal) >= 0 then TerminalCauseDynamicJoinRuntimeDynTypecheck
            elif pinned.status = semanticStatusToString SemanticDynamicJoinApplyBlocked && blob.IndexOf("term_apply_function_body_dynamic_arg_blocked", System.StringComparison.Ordinal) >= 0 then TerminalCauseDynamicJoinFunctionBodyDynamicArg
            elif blob.IndexOf("ty parent-continuation replay cap exhausted", System.StringComparison.Ordinal) >= 0 then TerminalCauseTyParentContinuationReplayCapExhausted
            elif blob.IndexOf("parent-continuation replay cap exhausted", System.StringComparison.Ordinal) >= 0 then TerminalCauseParentContinuationReplayCapExhausted
            elif blob.IndexOf("global term-cycle fuse", System.StringComparison.Ordinal) >= 0 then TerminalCauseGlobalFuseAbort
            else TerminalCausePinnedTerminal

        let terminalPrimaryMessage (requestedKind: string) (msg: string) (pinned: Frame) (rank: int) =
            let emitKey = sprintf "primary|%s|%s|%s" requestedKind pinned.status pinned.key
            let terminalCause = terminalPrimaryCauseFor msg pinned
            let terminalCauseText = terminalPrimaryCauseText terminalCause
            if retargetSeenOnce emitKey then
                DiagJson.emit (
                    sprintf "{\"kind\":\"eval_worklist_terminal_primary_message_selected\",\"event\":%s,\"requested_kind\":%s,\"status\":%s,\"terminal_cause_du\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                        (esc "terminal_primary_message") (esc requestedKind) (esc pinned.status) (esc terminalCauseText) rank (esc pinned.site) (esc pinned.key) (pendingCount()) (esc (nextFor pinned)))
            let primaryPrefix = "[spiral_compiler] EJP0011: pinned terminal contract blocked"
            let alreadyPrimary =
                not (System.String.IsNullOrEmpty msg)
                && msg.StartsWith(primaryPrefix, System.StringComparison.Ordinal)
                && msg.IndexOf("pinned_terminal=", System.StringComparison.Ordinal) >= 0
            if alreadyPrimary then
                if retargetSeenOnce (emitKey + "|idempotent") then
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_terminal_primary_message_idempotent\",\"event\":%s,\"requested_kind\":%s,\"status\":%s,\"terminal_cause_du\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"single_flight\":1,\"next\":%s}"
                            (esc "terminal_primary_message") (esc requestedKind) (esc pinned.status) (esc terminalCauseText) rank (esc pinned.site) (esc pinned.key) (pendingCount()) (esc (nextFor pinned)))
                if msg.IndexOf("\nEvalWorklistFrame:", System.StringComparison.Ordinal) >= 0 then msg else requiredMessage msg pinned
            else
                let originalFuse = trimOriginalFuseForMessage msg
                let pinnedMsg =
                    sprintf "[spiral_compiler] EJP0011: pinned terminal contract blocked status=%s terminal_cause_du=%s rank=%d site=%s requested_kind=%s\npinned_terminal=%s pinned_rank=%d pinned_site=%s requested_kind=%s original_fuse=%s"
                        pinned.status terminalCauseText rank pinned.site requestedKind pinned.status rank pinned.site requestedKind originalFuse
                requiredMessage pinnedMsg pinned

        let private pinnedTerminalMessage (requestedKind: string) (msg: string) (pinned: Frame) (rank: int) =
            terminalPrimaryMessage requestedKind msg pinned rank

        let retargetGlobalFuseAbortMessage (event: string) (requestedKind: string) (msg: string) =
            match highRankPinnedTerminal requestedKind with
            | Some (pinned, rank) ->
                let missingAfterPrefetchDecisionId =
                    missingAfterPrefetchTerminalDecisionFor
                        pinned.status
                        (pendingCount())
                        (replayQueueDepth())
                        (replayDriverActiveDepthValue())
                        (hasProgressYield())
                        (hasReplayComplete())
                        (hasReplayCompleteWriteWitness())
                        0
                if missingAfterPrefetchTerminalDecisionShouldDefer missingAfterPrefetchDecisionId then
                    if retargetSeenOnce (sprintf "abort-suppressed|%s|%s|%s|%s" event requestedKind pinned.status pinned.key) then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_global_fuse_abort_retarget_missing_after_prefetch_deferred\",\"event\":%s,\"requested_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"decision_du\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"replay_complete\":%b,\"write_witness\":%b,\"single_flight\":1,\"next\":\"continue_replay_before_primary_terminal\"}"
                                (esc event) (esc requestedKind) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (esc (missingAfterPrefetchTerminalDecisionText missingAfterPrefetchDecisionId)) (pendingCount()) (replayQueueDepth()) (replayDriverActiveDepthValue()) (hasReplayComplete()) (hasReplayCompleteWriteWitness()))
                    msg
                else
                    let emitKey = sprintf "abort|%s|%s|%s|%s" event requestedKind pinned.status pinned.key
                    if retargetSeenOnce emitKey then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_global_fuse_abort_retargeted_to_pinned_terminal\",\"event\":%s,\"requested_kind\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"single_flight\":1,\"rate_limited\":1,\"next\":%s}"
                                (esc event) (esc requestedKind) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) (esc (nextFor pinned)))
                    pinnedTerminalMessage requestedKind msg pinned rank
            | None -> msg

        let trySuppressGlobalFuseReplayReturnForPinnedTerminal (event: string) (requestedKind: string) (shape: string) (msg: string) =
            match highRankPinnedTerminal requestedKind with
            | Some (pinned, rank) ->
                let freshReplayRootWitnessAvailable =
                    let ageMs = (System.DateTime.UtcNow - replayRootCompleteWitnessUtc).TotalMilliseconds
                    replayRootCompleteWitnessUtc <> System.DateTime.MinValue
                    && ageMs >= 0.0
                    && ageMs <= replayRootCompleteWitnessWindowMs
                let freshRootWitnessShieldsOpImplReturn =
                    pinned.status = "semantic_op_impl_required_blocked"
                    && pendingCount() > 0
                    && freshReplayRootWitnessAvailable
                    && frameCellShapeOrSemanticEvidence ["EOp"] pinned
                    && (shape = "TFun"
                        || shape = "EApply"
                        || shape = "EV"
                        || shape = "EForall'"
                        || shape = "ETypeApply"
                        || shape = "EOp")
                let staleListmSymbolicIfRootReturn =
                    pinned.status = "semantic_if_symbolic_condition_blocked"
                    && pendingCount() > 0
                    && frameCellShapeOrSemanticEvidence ["EIfThenElse"] pinned
                    && (shape = "TFun"
                        || shape = "EApply"
                        || shape = "EV"
                        || shape = "EForall'"
                        || shape = "ETypeApply")
                let freshRootWitnessShieldsGlobalFuseReturn =
                    // ALPHA1072: runtime 1071 reached stable root-complete at backend.spi:80
                    // and jp_wait closed with pending=0/enqueued=done, but the final
                    // BuildError was retargeted to an older rank-80 global-fuse parent
                    // continuation terminal.  When this function is called, the current
                    // path already has a global replay-complete return in hand; a fresh
                    // replay-root write witness is stronger than a stale generic global
                    // fuse pin, but only for that generic parent-continuation status.
                    pinned.status = "semantic_global_fuse_parent_continuation_cycle_blocked"
                    && freshReplayRootWitnessAvailable
                    && (shape = "TFun"
                        || shape = "TPrim"
                        || shape = "TV"
                        || shape = "TB"
                        || shape = "TPair"
                        || shape = "TRecord"
                        || shape = "TUnion"
                        || shape = "TNominal"
                        || shape = "TApply"
                        || shape = "TExists"
                        || shape = "TForall'"
                        || shape = "EApply"
                        || shape = "EV"
                        || shape = "EFun'"
                        || shape = "EForall'"
                        || shape = "ETypeApply"
                        || shape = "ERecordWith"
                        || shape = "EUnbox"
                        || shape = "EOp")
                if freshRootWitnessShieldsOpImplReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when p.status = "semantic_op_impl_required_blocked" && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when p.status = "semantic_op_impl_required_blocked" && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_fresh_op_impl_required\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}"
                            (esc event) (esc requestedKind) (esc shape) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) durableCleared (esc replayRootCompleteWitnessSummary))
                    None
                elif staleListmSymbolicIfRootReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when p.status = "semantic_if_symbolic_condition_blocked" && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when p.status = "semantic_if_symbolic_condition_blocked" && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_stale_if_symbolic\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}"
                            (esc event) (esc requestedKind) (esc shape) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) durableCleared)
                    None
                elif freshRootWitnessShieldsGlobalFuseReturn then
                    let durableCleared =
                        lock gate (fun () ->
                            match pinnedTerminalContract with
                            | Some p when p.status = "semantic_global_fuse_parent_continuation_cycle_blocked" && p.site = pinned.site ->
                                pinnedTerminalContract <- None
                            | _ -> ()
                            match durableTerminalContract with
                            | Some p when p.status = "semantic_global_fuse_parent_continuation_cycle_blocked" && p.site = pinned.site ->
                                durableTerminalContract <- None
                                true
                            | _ -> false)
                    DiagJson.emit (
                        sprintf "{\"kind\":\"eval_worklist_global_fuse_root_return_demotes_stale_parent_fuse\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"durable_cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"allow_root_complete_replay_return\"}"
                            (esc event) (esc requestedKind) (esc shape) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) durableCleared (esc replayRootCompleteWitnessSummary))
                    None
                else
                    let emitKey = sprintf "return|%s|%s|%s|%s|%s" event requestedKind shape pinned.status pinned.key
                    if retargetSeenOnce emitKey then
                        DiagJson.emit (
                            sprintf "{\"kind\":\"eval_worklist_global_fuse_replay_return_suppressed_by_pinned_terminal\",\"event\":%s,\"requested_kind\":%s,\"shape\":%s,\"pinned_status\":%s,\"pinned_rank\":%d,\"pinned_site\":%s,\"pinned_key\":%s,\"pending\":%d,\"fresh_root_witness\":%b,\"single_flight\":1,\"next\":%s}"
                                (esc event) (esc requestedKind) (esc shape) (esc pinned.status) rank (esc pinned.site) (esc pinned.key) (pendingCount()) freshReplayRootWitnessAvailable (esc (nextFor pinned)))
                    Some (pinnedTerminalMessage requestedKind msg pinned rank)
            | None -> None


    /// ### JoinPointKey
    type JoinPointKey =
        | JPMethod of (string ConsedNode * E) * ConsedNode<RData [] * Ty [] * Ty>
        | JPClosure of (string ConsedNode * E) * ConsedNode<RData [] * Ty [] * Ty>
    

    /// ### JoinPointCall
    type JoinPointCall = JoinPointKey * TyV []
    

    /// ### CodeMacro
    type CodeMacro =
        | CMText of string
        | CMTerm of Data * is_inline : bool
        | CMType of Ty
        | CMTypeLit of Ty
    

    /// ### TypedBind
    type TypedBind =
        | TyLet of Data * Trace * TypedOp
        | TyLocalReturnOp of Trace * TypedOp * Data
        | TyLocalReturnData of Data * Trace
    

    and TypedOp =
        | TyMacro of CodeMacro list
        | TyOp of Op * Data list
        | TyUnionBox of string * Data * Union
        | TyUnionUnbox of TyV list * Union * Map<string,Data list * TypedBind []> * TypedBind [] option
        | TyIntSwitch of TyV * TypedBind [] [] * TypedBind []
        | TyToLayout of Data * Ty
        | TyLayoutIndexAll of TyV
        | TyLayoutIndexByKey of TyV * string
        | TyLayoutMutableSet of TyV * string list * Data
        | TyFailwith of Ty * Data
        | TyApply of TyV * Data
        | TyConv of Ty * Data
        | TySizeOf of Ty
        | TyArrayLiteral of Ty * Data list
        | TyArrayCreate of Ty * Data
        | TyArrayLength of Ty * Data
        | TyStringLength of Ty * Data
        | TyIf of cond: Data * tr: TypedBind [] * fl: TypedBind []
        | TyWhile of cond: JoinPointCall * TypedBind []
        | TyDo of TypedBind []
        | TyIndent of TypedBind []
        | TyJoinPoint of JoinPointCall
        | TyBackend of (string ConsedNode * E) * ConsedNode<RData [] * Ty [] * Ty> * Range
    

    /// ### UnionRewrite
    type UnionRewrite = UnionData of string * Data | UnionBlockers of string Set
    

    /// ### LangEnv
    type LangEnv = {
        trace : Trace
        seq : ResizeArray<TypedBind>
        cse : Dictionary<TypedOp, Data> list
        unions : Map<TyV, UnionRewrite>
        i : int ref
        env_global_type : Ty []
        env_global_term : Data []
        env_stack_type : Ty []
        env_stack_term : Data []
        backend : string ConsedNode
        globals : ResizeArray<string>
        globals_lock : obj
        globals_seen : System.Collections.Concurrent.ConcurrentDictionary<string, byte>
        join_point_method_key_names : System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, string>
        join_point_closure_key_names : System.Collections.Concurrent.ConcurrentDictionary<ConsedNode<RData [] * Ty [] * Ty>, string>
        jp_method_stack : System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>
        jp_closure_stack : System.Collections.Generic.HashSet<ConsedNode<RData [] * Ty [] * Ty>>
        jp_type_stack : System.Collections.Generic.HashSet<ConsedNode<Ty []>>
        }

    let private evalNodeShapeTerm (x: E) =
        match x with
        | EFun _ -> "EFun" | EFun' _ -> "EFun'" | EForall _ -> "EForall" | EForall' _ -> "EForall'"
        | ERecursiveFun' _ -> "ERecursiveFun'" | ERecursiveForall' _ -> "ERecursiveForall'" | ERecursive _ -> "ERecursive" | EPatternRef _ -> "EPatternRef"
        | EJoinPoint _ -> "EJoinPoint" | EJoinPoint' _ -> "EJoinPoint'" | EB _ -> "EB" | EV _ -> "EV" | ELit _ -> "ELit" | EDefaultLit _ -> "EDefaultLit"
        | ESymbol _ -> "ESymbol" | EType _ -> "EType" | EApply _ -> "EApply" | EArray _ -> "EArray" | ETypeApply _ -> "ETypeApply" | ERecBlock _ -> "ERecBlock"
        | ERecordWith _ -> "ERecordWith" | EModule _ -> "EModule" | EOp _ -> "EOp" | EPatternMiss _ -> "EPatternMiss" | ETypePatternMiss _ -> "ETypePatternMiss"
        | EAnnot _ -> "EAnnot" | EIfThenElse _ -> "EIfThenElse" | EIfThen _ -> "EIfThen" | EPair _ -> "EPair" | ESeq _ -> "ESeq" | EMutableSet _ -> "EMutableSet"
        | EReal _ -> "EReal" | EExists _ -> "EExists" | EMacro _ -> "EMacro" | EPrototypeApply _ -> "EPrototypeApply" | EPatternMemo _ -> "EPatternMemo" | ENominal _ -> "ENominal"
        | ELet _ -> "ELet" | EUnbox _ -> "EUnbox" | EExistsTest _ -> "EExistsTest" | EPairTest _ -> "EPairTest" | ESymbolTest _ -> "ESymbolTest"
        | ERecordTest _ -> "ERecordTest" | EAnnotTest _ -> "EAnnotTest" | ENominalTest _ -> "ENominalTest" | EUnitTest _ -> "EUnitTest" | ELitTest _ -> "ELitTest" | EDefaultLitTest _ -> "EDefaultLitTest" | ETypecase _ -> "ETypecase"

    let private evalNodeShapeTy (x: TPrepass) =
        match x with
        | TForall' _ -> "TForall'" | TForall _ -> "TForall" | TArrow' _ -> "TArrow'" | TArrow _ -> "TArrow" | TExists -> "TExists"
        | TJoinPoint' _ -> "TJoinPoint'" | TJoinPoint _ -> "TJoinPoint" | TPatternRef _ -> "TPatternRef" | TB _ -> "TB" | TLit _ -> "TLit" | TV _ -> "TV"
        | TPair _ -> "TPair" | TFun _ -> "TFun" | TRecord _ -> "TRecord" | TModule _ -> "TModule" | TUnion _ -> "TUnion" | TSymbol _ -> "TSymbol"
        | TApply _ -> "TApply" | TPrim _ -> "TPrim" | TTerm _ -> "TTerm" | TMacro _ -> "TMacro" | TNominal _ -> "TNominal" | TArray _ -> "TArray" | TLayout _ -> "TLayout" | TMetaV _ -> "TMetaV" | TTypecase _ -> "TTypecase"

    let private evalPayload (kind: string) (shape: string) (nodeId: int) (site: string) (s: LangEnv) =
        sprintf "semantic_eval_payload(kind=%s,shape=%s,node_id=%d,env_term=%d/%d,env_type=%d/%d,seq_len=%d,cse_depth=%d,trace_depth=%d,site=%s)"
            kind shape nodeId s.env_global_term.Length s.env_stack_term.Length s.env_global_type.Length s.env_stack_type.Length s.seq.Count s.cse.Length s.trace.Length site

    let private evalCell (kind: string) (shape: string) (nodeId: int) (site: string) (s: LangEnv) : EvalWorklist.ReplayCell =
        // ALPHA403: PartEvalResult.ty_to_data intentionally keeps seq = null
        // after partial evaluation.  Codegen may still force nominal type
        // application while TermCycleFuse is armed, so replay diagnostics must
        // describe that post-peval environment without dereferencing nullable
        // fields or allocating fake codegen state.
        let safeArrayLen (xs: 'a []) = if obj.ReferenceEquals(xs, null) then 0 else xs.Length
        let safeResizeCount (xs: ResizeArray<'a>) = if obj.ReferenceEquals(xs, null) then 0 else xs.Count
        let safeListLen (xs: 'a list) = if obj.ReferenceEquals(xs, null) then 0 else xs.Length
        let envGlobalTerm, envStackTerm, envGlobalType, envStackType, seqLen, cseDepth, traceDepth =
            if obj.ReferenceEquals(s, null) then
                0, 0, 0, 0, 0, 0, 0
            else
                safeArrayLen s.env_global_term,
                safeArrayLen s.env_stack_term,
                safeArrayLen s.env_global_type,
                safeArrayLen s.env_stack_type,
                safeResizeCount s.seq,
                safeListLen s.cse,
                safeListLen s.trace
        { kind = kind
          shape = shape
          nodeId = nodeId
          envGlobalTerm = envGlobalTerm
          envStackTerm = envStackTerm
          envGlobalType = envGlobalType
          envStackType = envStackType
          seqLen = seqLen
          cseDepth = cseDepth
          traceDepth = traceDepth
          site = site
          cursor = 0
          step = 0
          status = "new" }
    

    /// ### show_ty
    let show_ty x =
        let rec f prec x =
            let p = p prec
            match x with
            | YVoid -> "void"
            | YB -> "()"
            | YLit x -> show_lit x
            | YPair(a,b) -> p 25 (sprintf "%s * %s" (f 25 a) (f 24 b))
            | YSymbol x -> sprintf ".%s" x
            | YTypeFunction _ -> p 0 (sprintf "? => ?")
            | YForall -> p 0 (sprintf "forall ?. ?")
            | YExists -> p 0 (sprintf "exists ?. ?")
            | YRecord l -> sprintf "{%s}" (l |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f -1 v)) |> String.concat "; ")
            | YUnion l -> sprintf "{%s}" (l.Item.cases |> Map.toList |> List.map (fun ((_,k),v) -> sprintf "%s : %s" k (f -1 v)) |> String.concat " | ")
            | YPrim x -> show_primt x
            | YArray a -> p 30 (sprintf "array_base %s" (f 30 a))
            | YFun(a,b,FT_Vanilla) -> p 20 (sprintf "%s -> %s" (f 20 a) (f 19 b))
            | YFun(a,b,FT_Pointer) -> p 20 (sprintf "fptr (%s -> %s)" (f 20 a) (f 19 b))
            | YFun(a,b,FT_Closure) -> p 20 (sprintf "closure (%s -> %s)" (f 20 a) (f 19 b))
            | YMacro a -> p 30 (List.map (function TypeLit a | Type a -> f -1 a | Text a -> a) a |> String.concat "")
            | YApply(a,b) -> p 30 (sprintf "%s %s" (f 29 a) (f 30 b))
            | YLayout(a,b) -> p 30 (sprintf "%s %s" (show_layout_type b) (f 30 a))
            | YNominal x -> x.node.name
            | YMetavar _ -> "?"
        f -1 x
    

    /// ### Type-class helpers for diagnostic validation
    /// Used to detect obvious cache collisions (e.g., returning i32 when function expected).
    let is_ty_callable ty =
        match ty with
        | YFun _ | YForall | YTypeFunction _ -> true
        | YLayout(inner, _) ->
            match inner with
            | YFun _ | YRecord _ -> true
            | _ -> false
        | YNominal n ->
            // Some nominals wrap functions.
            match n.node.name with
            | s when s.Contains("fun") || s.Contains("closure") || s.Contains("Func") -> true
            | _ -> false
        | _ -> false
    

    let is_ty_primitive ty =
        match ty with
        | YPrim _ | YLit _ -> true
        | _ -> false
    

    /// ### RetryTracker
    /// Thread-safe tracking of retry attempts for EJP0003 type errors.
    /// Helps detect when retries are resolving issues vs when they're failing consistently.
    module RetryTracker =
        open System
        open System.Collections.Concurrent
        open System.Threading
    

        let mutable private attemptCount = 0
        let mutable private successCount = 0
        let mutable private failCount = 0
        let private inRetry = new ThreadLocal<int>(fun () -> 0)
    

        let isInRetry () = inRetry.Value > 0
    

        let enterRetry () =
            inRetry.Value <- inRetry.Value + 1
            Interlocked.Increment(&attemptCount) |> ignore
    

        let exitRetrySuccess () =
            inRetry.Value <- max 0 (inRetry.Value - 1)
            Interlocked.Increment(&successCount) |> ignore
    

        let exitRetryFail () =
            inRetry.Value <- max 0 (inRetry.Value - 1)
            Interlocked.Increment(&failCount) |> ignore
    

        let getStats () =
            sprintf "attempts=%d success=%d fail=%d" attemptCount successCount failCount
    

        let logIfActive () =
            let a, s, f = attemptCount, successCount, failCount
            if a > 0 then
                DiagSidecar.emit (sprintf "RetryTracker: %s" (getStats ()))
    

    /// ### DiagNN
    /// Small, online "neural-ish" helper for diagnostics: hashed embeddings + cosine similarity.
    /// Always enabled in v43+ for error pattern clustering. Lightweight and thread-safe.
    module DiagNN =
        open System
        open System.Collections.Concurrent
    

        let private dims = 64
    

        let inline enabled () = true  // v43: always on
    

        let private centroids = ConcurrentDictionary<string, float []>()
        let private counts = ConcurrentDictionary<string, int>()
    

        let private fnv1a32 (s: string) : uint32 =
            let mutable h = 2166136261u
            for i = 0 to s.Length - 1 do
                h <- (h ^^^ uint32 (int s.[i])) * 16777619u
            h
    

        let private embed (s: string) : float [] =
            let v = Array.zeroCreate<float> dims
            if String.IsNullOrEmpty s then v
            else
                // Simple tokenization; stable enough for clustering and similarity hints.
                let toks =
                    s.Split([|' '; '\t'; '\r'; '\n'; '|'; ','; ';'; '('; ')'; '['; ']'; '{'; '}'; '<'; '>'; ':'; '='; '\''; '"'|],
                            StringSplitOptions.RemoveEmptyEntries)
                let n = min toks.Length 512
                for i = 0 to n - 1 do
                    let t = toks.[i]
                    let h = fnv1a32 t
                    let idx = int (h % uint32 dims)
                    let sign = if (h &&& 1u) = 0u then 1.0 else -1.0
                    v.[idx] <- v.[idx] + sign
                // L2 normalize (avoid div0).
                let mutable norm = 0.0
                for i = 0 to dims - 1 do norm <- norm + v.[i] * v.[i]
                if norm > 0.0 then
                    let inv = 1.0 / sqrt norm
                    for i = 0 to dims - 1 do v.[i] <- v.[i] * inv
                v
    

        let private cosine (a: float []) (b: float []) : float =
            let mutable dot = 0.0
            let mutable i = 0
            while i < dims do
                dot <- dot + a.[i] * b.[i]
                i <- i + 1
            dot
    

        let record (clusterKey: string) (payload: string) : string option =
            if not (enabled ()) then None
            else
                try
                    let x = embed payload
                    let c = counts.AddOrUpdate(clusterKey, 1, (fun _ n -> n + 1))
                    let w = centroids.GetOrAdd(clusterKey, (fun _ -> Array.zeroCreate<float> dims))
                    lock w (fun () ->
                        // Exponential-ish moving average; stable enough for hints.
                        let alpha = 1.0 / float c
                        for i = 0 to dims - 1 do
                            w.[i] <- w.[i] + alpha * (x.[i] - w.[i])
                    )
                    // Nearest neighbors among existing clusters (bounded scan; only when enabled).
                    let mutable best1 = ("", -1.0)
                    let mutable best2 = ("", -1.0)
                    let mutable best3 = ("", -1.0)
                    for kv in centroids do
                        let k = kv.Key
                        if k <> clusterKey then
                            let s = cosine x kv.Value
                            if s > snd best1 then
                                best3 <- best2
                                best2 <- best1
                                best1 <- (k, s)
                            elif s > snd best2 then
                                best3 <- best2
                                best2 <- (k, s)
                            elif s > snd best3 then
                                best3 <- (k, s)
                    let fmt (k, s) =
                        if k = "" then ""
                        else sprintf "%s(%.2f)" k s
                    let near =
                        [ fmt best1; fmt best2; fmt best3 ]
                        |> List.filter (fun s -> s <> "")
                        |> String.concat ", "
                    Some (sprintf "cluster=%s count=%d near=[%s]" clusterKey c near)
                with _ ->
                    None
    

    /// ### CacheGeneration
    /// Global generation counter for cache invalidation in deep recursion scenarios.
    /// When cache corruption is detected (EJP0007/EJP0008), incrementing the generation
    /// marks all older entries as stale, enabling clean retry without full cache flush.
    module CacheGeneration =
        open System
        open System.Threading
    

        let mutable private generation = 0L
        let private lastInvalidationTime = ref DateTime.MinValue
        let private invalidationReasons = System.Collections.Concurrent.ConcurrentQueue<string>()
    

        let mutable private invalidation_count = 0L
        let invalidationCount () = Interlocked.Read(&invalidation_count)

        // Alpha100: fallback sequencial escopado (ativado apenas por retries; reset no inicio do build)
        let mutable private jp_force_sequential = 0
        // Alpha36: allow subsystems to register cache-clear callbacks that run on invalidation.
        let private onInvalidate = System.Collections.Concurrent.ConcurrentBag<string -> unit>()
        let registerOnInvalidate (f: string -> unit) =
            onInvalidate.Add f

        let requestSequential () =
            // Ativa um modo “sem races” para o retry atual, sem virar estado oculto permanente.
            if Interlocked.Exchange(&jp_force_sequential, 1) = 0 then
                DiagSidecar.emit (sprintf "CacheGeneration.requestSequential: enabled gen=%d" (Interlocked.Read(&generation)))

        let resetSequentialRequest () =
            if Interlocked.Exchange(&jp_force_sequential, 0) <> 0 then
                DiagSidecar.emit (sprintf "CacheGeneration.requestSequential: reset gen=%d" (Interlocked.Read(&generation)))

        let isSequentialRequested () = Interlocked.CompareExchange(&jp_force_sequential, 0, 0) <> 0
    

        /// Get current generation number
        let current () = Interlocked.Read(&generation)
        do Progress88.set_gen_provider current
    

        /// Invalidate cache generation with a reason string for diagnostics
        let invalidate (reason: string) =
            let newGen = Interlocked.Increment(&generation)
            Interlocked.Increment(&invalidation_count) |> ignore
            lastInvalidationTime := DateTime.UtcNow
            invalidationReasons.Enqueue(sprintf "[gen=%d] %s @ %s" newGen reason (DateTime.UtcNow.ToString("HH:mm:ss.fff")))
            // Keep only last 32 reasons
            while invalidationReasons.Count > 32 do
                let mutable v = Unchecked.defaultof<string>
                invalidationReasons.TryDequeue(&v) |> ignore
            DiagSidecar.emit (sprintf "CacheGeneration.invalidate: gen=%d reason=%s" newGen reason)
            // Alpha36: best-effort clear hooks to prevent stale placeholder resolutions from leaking across generations.
            try
                for cb in onInvalidate do
                    try cb reason with _ -> ()
            with _ -> ()
            newGen

        /// Record a diagnostic reason without changing the cache generation.
        /// ALPHA468: jp_wait can close after a typed replay root-complete proof in the
        /// same build attempt.  The writer needs that proof in the reason ledger, but
        /// incrementing the generation here would turn success back into a retry.
        let noteReason (reason: string) =
            let gen = Interlocked.Read(&generation)
            invalidationReasons.Enqueue(sprintf "[gen=%d] %s @ %s" gen reason (DateTime.UtcNow.ToString("HH:mm:ss.fff")))
            while invalidationReasons.Count > 32 do
                let mutable v = Unchecked.defaultof<string>
                invalidationReasons.TryDequeue(&v) |> ignore
            DiagSidecar.emit (sprintf "CacheGeneration.noteReason: gen=%d reason=%s" gen reason)

        /// Snapshot recent invalidation reasons (most recent first), for diagnostics
        let reasonsSnapshot (n: int) : string list =
            try
                invalidationReasons.ToArray()
                |> Array.rev
                |> (fun a -> if n <= 0 then [||] else a |> Array.truncate (min n a.Length))
                |> Array.toList
            with _ -> []
    

        /// Check if a generation is stale (older than current)
        let isStale (g: int64) = g < Interlocked.Read(&generation)
    

        /// Get recent invalidation reasons for diagnostics
        let getRecentReasons () = invalidationReasons.ToArray() |> Array.toList
    

    /// ### RecursionTracker
    /// Thread-local recursion depth tracking for detecting deep nesting scenarios
    /// like sm'.replicate → join_body_unit loops that trigger cache corruption.
    module RecursionTracker =
        open System
        open System.Threading
        open System.Collections.Concurrent
    

        let private threadDepth = new ThreadLocal<int>(fun () -> 0)
        let mutable private maxObserved = 0
        let private deepCallSites = ConcurrentDictionary<string, int>()
    

        /// Enter a recursive context, returns current depth
        let enter (site: string) : int =
            let d = threadDepth.Value + 1
            threadDepth.Value <- d
            // Track max observed depth
            let mutable current = maxObserved
            while d > current && Interlocked.CompareExchange(&maxObserved, d, current) <> current do
                current <- maxObserved
            // Track deep call sites (> 50 depth)
            if d > 50 then
                deepCallSites.AddOrUpdate(site, 1, (fun _ n -> n + 1)) |> ignore
            d
    

        /// Exit a recursive context
        let exit () =
            threadDepth.Value <- max 0 (threadDepth.Value - 1)
    

        /// Get current recursion depth for this thread
        let currentDepth () = threadDepth.Value
    

        /// Set recursion depth directly (for BigStack thread inheritance)
        let setDepth (d: int) = threadDepth.Value <- d
    

        /// Check if currently in deep recursion (> 100)
        let isDeep () = threadDepth.Value > 100
    

        /// Check if moderately deep (> 50)
        let isModeratelyDeep () = threadDepth.Value > 50
    

        /// Get max observed depth across all threads
        let getMaxObserved () = maxObserved
    

        /// Get deep call site statistics
        let getDeepSites () = deepCallSites.ToArray() |> Array.toList
    
    
    
    
    





    /// BigStack: Executes thunks on dedicated threads with large stacks.
    /// Used for deep recursion when EnsureSufficientExecutionStack triggers.
    /// 
    ///
    /// CONFIGURATION (hardcoded SOTA defaults):
    /// - Stack size: 256MB per level (enough for 100K+ recursive calls)
    /// - Max nesting: 32 levels (8GB total address space)
    /// - Automatic depth inheritance across BigStack boundaries
    

    module BigStack =
        open System
        open System.Threading
    

        /// Thread-local nesting counter (0 = main stack, >0 = inside BigStack)
        let private active : ThreadLocal<int> = new ThreadLocal<int>(fun () -> 0)
    

        /// True if currently executing on a BigStack thread
        let isActive () = active.Value > 0
    

        // SOTA defaults - no environment variable overrides
        let private stackMb = 256         // baseline MB per stack level
        let private maxNestingLevels = 32 // alpha180: cap nesting; prefer larger first stacks (big stacks park parent frames)

        // ALPHA1102: keep join policy gated by a closed tag DU.
        // We only fast-retry peval_main in forced sequential mode; term/ty nested stacks
        // keep their existing root-complete / terminal-contract handoff rules.
        type BigStackJoinTagId =
            | BigStackPevalMain
            | BigStackTerm
            | BigStackTy
            | BigStackJoinPoint
            | BigStackOther of string

        let private bigStackJoinTagId (tag: string) =
            if String.IsNullOrEmpty tag then BigStackOther ""
            elif tag = "peval_main" then BigStackPevalMain
            elif tag.StartsWith("term", StringComparison.Ordinal) then BigStackTerm
            elif tag.StartsWith("ty", StringComparison.Ordinal) then BigStackTy
            elif tag.StartsWith("jp_", StringComparison.Ordinal) then BigStackJoinPoint
            else BigStackOther tag

        let private bigStackJoinTagText = function
            | BigStackPevalMain -> "peval_main"
            | BigStackTerm -> "term"
            | BigStackTy -> "ty"
            | BigStackJoinPoint -> "jp"
            | BigStackOther _ -> "other"

        // ALPHA1284: close BigStack terminal/HUD frontier phases as a DU.
        // Alpha1283 improved frontier observability but still passed phase labels as
        // raw strings, making typo drift possible exactly at the diagnostic boundary.
        type BigStackFrontierPhaseId =
            | BigStackFrontierFastRetryGate
            | BigStackFrontierFastRetryRaise
            | BigStackFrontierPinnedSeen
            | BigStackFrontierQueueDrain
            | BigStackFrontierLateRaceQueueDrain
            | BigStackFrontierTerminalHandoff
            | BigStackFrontierOther of string

        let private bigStackFrontierPhaseText = function
            | BigStackFrontierFastRetryGate -> "fast_retry_gate"
            | BigStackFrontierFastRetryRaise -> "fast_retry_raise"
            | BigStackFrontierPinnedSeen -> "pinned_seen"
            | BigStackFrontierQueueDrain -> "queue_drain"
            | BigStackFrontierLateRaceQueueDrain -> "late_race_queue_drain"
            | BigStackFrontierTerminalHandoff -> "terminal_handoff"
            | BigStackFrontierOther text -> text

        // ALPHA1285: close terminal frontier reasons and fast-failure usefulness as DUs.
        // Fast failure is only a wasted round when it emits no durable frontier.
        // Runtime 1284 did emit a durable frontier, so keep that evidence typed.
        type BigStackTerminalReasonId =
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired
            | BigStackTerminalReasonReplayDriverPoisonHardFail
            | BigStackTerminalReasonQueueSurgeParentPoison
            | BigStackTerminalReasonDynamicJoinRequired
            | BigStackTerminalReasonMissingAfterPrefetch
            | BigStackTerminalReasonCrossKindActiveReplayDriver
            | BigStackTerminalReasonCrossKindYieldThrash
            | BigStackTerminalReasonHardPoisonObligationCap
            | BigStackTerminalReasonReplayObligation
            | BigStackTerminalReasonOther of string

        let private bigStackTerminalReasonOfString (reason: string) =
            if System.String.IsNullOrEmpty reason then BigStackTerminalReasonOther ""
            elif reason.StartsWith("parent_replay_status_preserved_repeat", StringComparison.Ordinal) then BigStackTerminalReasonParentReplayStatusPreservedRepeat
            elif reason.StartsWith("runtime_record_dynamic_key_required", StringComparison.Ordinal) then BigStackTerminalReasonRuntimeRecordDynamicKeyRequired
            elif reason.StartsWith("replay_driver_poison_hard_fail", StringComparison.Ordinal) then BigStackTerminalReasonReplayDriverPoisonHardFail
            elif reason.StartsWith("queue_surge_parent_poison", StringComparison.Ordinal) then BigStackTerminalReasonQueueSurgeParentPoison
            elif reason.Contains("missing-after-prefetch") || reason.Contains("missing_after_prefetch") || reason.Contains("semantic_missing_after_prefetch_blocked") then BigStackTerminalReasonMissingAfterPrefetch
            elif reason.Contains("hard_poison_obligation_cap") then BigStackTerminalReasonHardPoisonObligationCap
            elif reason.Contains("cross_kind_yield_thrash") then BigStackTerminalReasonCrossKindYieldThrash
            elif reason.Contains("cross_kind_active_replay_driver") then BigStackTerminalReasonCrossKindActiveReplayDriver
            elif reason.Contains("replay_obligation") || reason.Contains("typed_replay_obligation") then BigStackTerminalReasonReplayObligation
            elif reason.Contains("dynamic_arg_join_required") || reason.Contains("dynamic_join") then BigStackTerminalReasonDynamicJoinRequired
            else BigStackTerminalReasonOther reason

        let private bigStackTerminalReasonText = function
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat -> "parent_replay_status_preserved_repeat"
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired -> "runtime_record_dynamic_key_required"
            | BigStackTerminalReasonReplayDriverPoisonHardFail -> "replay_driver_poison_hard_fail"
            | BigStackTerminalReasonQueueSurgeParentPoison -> "queue_surge_parent_poison"
            | BigStackTerminalReasonDynamicJoinRequired -> "dynamic_join_required"
            | BigStackTerminalReasonMissingAfterPrefetch -> "missing_after_prefetch_blocked"
            | BigStackTerminalReasonCrossKindActiveReplayDriver -> "cross_kind_active_replay_driver"
            | BigStackTerminalReasonCrossKindYieldThrash -> "cross_kind_yield_thrash"
            | BigStackTerminalReasonHardPoisonObligationCap -> "hard_poison_obligation_cap"
            | BigStackTerminalReasonReplayObligation -> "replay_obligation"
            | BigStackTerminalReasonOther text ->
                if System.String.IsNullOrEmpty text then "none"
                else
                    let compact = text.Replace("\r", " ").Replace("\n", " ").Replace("\t", " ")
                    if compact.Length > 96 then "other:" + compact.Substring(0, 96)
                    else "other:" + compact

        type BigStackFastFailureUsefulnessId =
            | BigStackFastFailureUnclassified
            | BigStackFastFailureUsefulFrontierPinned
            | BigStackFastFailureUsefulDynamicBridgeLocalized
            | BigStackFastFailureUsefulPoisonTailBounded
            | BigStackFastFailureUsefulParentReplayPoisonHandoff
            | BigStackFastFailureLowInfoNoAuthority

        let private bigStackFastFailureUsefulnessText = function
            | BigStackFastFailureUnclassified -> "unclassified"
            | BigStackFastFailureUsefulFrontierPinned -> "useful_frontier_pinned"
            | BigStackFastFailureUsefulDynamicBridgeLocalized -> "useful_dynamic_bridge_localized"
            | BigStackFastFailureUsefulPoisonTailBounded -> "useful_poison_tail_bounded"
            | BigStackFastFailureUsefulParentReplayPoisonHandoff -> "useful_parent_replay_poison_handoff"
            | BigStackFastFailureLowInfoNoAuthority -> "low_info_no_authority"

        // ALPHA1308: a typed gate separates the old q>0 deferred-child bridge from the
        // alpha1307 frontier: q/a/p drained, write witness present, but parent-replay
        // cycle-break poison still wins and the heartbeat eventually aborts.  This gate
        // lets the bridge fire in that specific write-witness tail without treating
        // arbitrary poison as success.
        type BigStackParentContinuationPhase2GateId =
            | BigStackParentContinuationPhase2GateClosed
            | BigStackParentContinuationPhase2PendingDeferredTail
            | BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail
            | BigStackParentContinuationPhase2ActiveWriteWitnessTail

        let private bigStackParentContinuationPhase2GateText = function
            | BigStackParentContinuationPhase2GateClosed -> "closed"
            | BigStackParentContinuationPhase2PendingDeferredTail -> "pending_deferred_tail"
            | BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail -> "queue_drained_write_witness_tail"
            | BigStackParentContinuationPhase2ActiveWriteWitnessTail -> "active_write_witness_tail"

        let private bigStackParentContinuationPhase2GateShouldBridge = function
            | BigStackParentContinuationPhase2GateClosed -> false
            | _ -> true

        let private bigStackParentContinuationPhase2GateFor
            (status: string)
            (reasonText: string)
            pendingCount
            queueDepth
            activeDepth
            replayComplete
            writeWitness =
            let st = if isNull status then "" else status
            let reasonText = if isNull reasonText then "" else reasonText
            let statusCandidate =
                st = "semantic_parent_continuation_cycle_deferred"
                || st = "semantic_parent_replay_cycle_break_poisoned"
                || st = "semantic_parent_replay_status_preserved_repeat_blocked"
            let reasonCandidate =
                reasonText.Contains("deferred_child_cell", StringComparison.Ordinal)
                || reasonText.Contains("parent_continuation_cycle", StringComparison.Ordinal)
                || reasonText.Contains("parent_replay_status_preserved_repeat", StringComparison.Ordinal)
                || reasonText.Contains("parent_continuation_ready", StringComparison.Ordinal)
                || reasonText.Contains("single_flight_busy_cross_kind_cycle_break", StringComparison.Ordinal)
            if not statusCandidate || not reasonCandidate || replayComplete then
                BigStackParentContinuationPhase2GateClosed
            elif pendingCount > 0 && pendingCount <= 3 && queueDepth <= 8 && activeDepth = 0 then
                BigStackParentContinuationPhase2PendingDeferredTail
            elif pendingCount = 0
                 && queueDepth <= 16
                 && activeDepth = 0
                 && writeWitness
                 && st = "semantic_parent_replay_cycle_break_poisoned" then
                BigStackParentContinuationPhase2QueueDrainedWriteWitnessTail
            elif pendingCount = 0
                 && queueDepth <= 8
                 && activeDepth <= 4
                 && writeWitness
                 && st = "semantic_parent_replay_cycle_break_poisoned" then
                BigStackParentContinuationPhase2ActiveWriteWitnessTail
            else
                BigStackParentContinuationPhase2GateClosed

        // ALPHA1287: split explicit parent-replay poison handoff from final failure.
        // Runtime 1286 proved the terminal handoff is now reached, but it still raised
        // while active replay/root witnesses were live. Keep the terminal authoritative,
        // but give a typed post-handoff grace window before surfacing EJP0021.
        type BigStackExplicitParentReplayPoisonHandoffActionId =
            | BigStackExplicitParentReplayPoisonSurface
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail
            | BigStackExplicitParentReplayPoisonDeferActiveTail
            | BigStackExplicitParentReplayPoisonDeferRootWitness
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness
            | BigStackExplicitParentReplayPoisonDeferRootAuthority

        let private bigStackExplicitParentReplayPoisonHandoffActionText = function
            | BigStackExplicitParentReplayPoisonSurface -> "surface_ejp0021"
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress -> "defer_recent_root_or_replay_progress_tail"
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep -> "defer_deferred_type_hole_sweep_tail"
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail -> "defer_live_unfinished_tail"
            | BigStackExplicitParentReplayPoisonDeferActiveTail -> "defer_active_tail"
            | BigStackExplicitParentReplayPoisonDeferRootWitness -> "defer_root_witness_tail"
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge -> "defer_dynamic_bridge_tail"
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness -> "defer_replay_completeness_tail"
            | BigStackExplicitParentReplayPoisonDeferRootAuthority -> "defer_root_authority_tail"

        type BigStackParentReplayPendingZeroPhysicalTailDecisionId =
            | BigStackParentReplayPendingZeroPhysicalTailNone
            | BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail
            | BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail

        let private bigStackParentReplayPendingZeroPhysicalTailDecisionText = function
            | BigStackParentReplayPendingZeroPhysicalTailNone -> "none"
            | BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail -> "drain_pending_zero_physical_tail"
            | BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail -> "observe_pending_zero_no_live_tail"

        let private bigStackParentReplayPendingZeroPhysicalTailDecisionFor pendingZeroNoWriter physicalLiveTail =
            if pendingZeroNoWriter && physicalLiveTail then BigStackParentReplayPendingZeroPhysicalTailDrainLiveTail
            elif pendingZeroNoWriter then BigStackParentReplayPendingZeroPhysicalTailObserveNoLiveTail
            else BigStackParentReplayPendingZeroPhysicalTailNone

        type BigStackParentReplayRecentProgressCreditId =
            | BigStackParentReplayRecentProgressCreditOpen
            | BigStackParentReplayRecentProgressCreditExhaustedByClearCap
            | BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood
            | BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt

        let private bigStackParentReplayRecentProgressCreditText = function
            | BigStackParentReplayRecentProgressCreditOpen -> "open"
            | BigStackParentReplayRecentProgressCreditExhaustedByClearCap -> "exhausted_by_clear_cap"
            | BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood -> "exhausted_by_terminal_flood"
            | BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt -> "exhausted_by_phase2_attempt"

        let private bigStackParentReplayRecentProgressCreditFor postHandoffDeferrals recentProgressClears terminalFloodCount phase2BridgeAttempts =
            if phase2BridgeAttempts > 0 && recentProgressClears >= 2 then
                BigStackParentReplayRecentProgressCreditExhaustedByPhase2Attempt
            elif terminalFloodCount >= 96 then
                BigStackParentReplayRecentProgressCreditExhaustedByTerminalFlood
            elif postHandoffDeferrals + recentProgressClears >= 8 then
                BigStackParentReplayRecentProgressCreditExhaustedByClearCap
            else
                BigStackParentReplayRecentProgressCreditOpen

        let private bigStackParentReplayRecentProgressCreditAllowsClear = function
            | BigStackParentReplayRecentProgressCreditOpen -> true
            | _ -> false

        // ALPHA1431: terminal-flood is a useful anti-livelock signal, but alpha1430 proved it
        // can outrank a still-live JP parent poison frontier: EJP0014 selected rank83 while
        // pending=2, active=4, root_progress=21 and the typed retry gate had just fired.
        // Keep this as a closed guard so terminal_flood_count>=96 cannot silently erase
        // pending+active JP tail authority.
        type BigStackParentReplayTerminalFloodCreditGuardId =
            | BigStackParentReplayTerminalFloodCreditNoOverride
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail

        let private bigStackParentReplayTerminalFloodCreditGuardText = function
            | BigStackParentReplayTerminalFloodCreditNoOverride -> "no_override"
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail -> "protected_by_pending_active_jp_tail"
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail -> "protected_by_material_live_tail"
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail -> "expired_cooperative_handoff_live_tail"

        let private bigStackParentReplayTerminalFloodCreditGuardFor status reason pendingCount queueDepth activeDepth rootProgress replayComplete writeWitness terminalFloodCount jpRetryCount =
            let materialLiveParentReplayTail =
                status = "semantic_parent_replay_cycle_break_poisoned"
                && reason = BigStackTerminalReasonParentReplayStatusPreservedRepeat
                && not replayComplete
                && not writeWitness
                && pendingCount > 0
                && activeDepth > 0
                && queueDepth <= 64
                && rootProgress > 0
                && terminalFloodCount >= 96
            let cooperativeHandoffTailExpired =
                // ALPHA1550: alpha1549 proved semantic-stale-retarget can pierce, but the BigStack
                // parent-replay terminal flood guard still kept a tiny cooperative_handoff tail alive
                // as material work.  When there is no JP retry, no writer/replay completion and the
                // terminal flood is already deep, this is no longer semantic progress: it is a typed
                // fail-closed handoff boundary.
                materialLiveParentReplayTail
                && jpRetryCount <= 0
                && terminalFloodCount >= 128
                && pendingCount <= 2
                && queueDepth <= 5
                && activeDepth <= 4
            if cooperativeHandoffTailExpired then
                BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail
            elif materialLiveParentReplayTail && jpRetryCount > 0 then
                BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail
            elif materialLiveParentReplayTail then
                BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail
            else
                BigStackParentReplayTerminalFloodCreditNoOverride

        let private bigStackParentReplayTerminalFloodCreditGuardAllowsClear = function
            | BigStackParentReplayTerminalFloodCreditProtectedByPendingActiveJpTail -> true
            | BigStackParentReplayTerminalFloodCreditProtectedByMaterialLiveTail -> true
            | BigStackParentReplayTerminalFloodCreditExpiredCooperativeHandoffLiveTail -> false
            | BigStackParentReplayTerminalFloodCreditNoOverride -> false

        type BigStackDynamicJoinDeferredFloodId =
            | BigStackDynamicJoinDeferredFloodNotMature
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge
            | BigStackDynamicJoinDeferredFloodCapExhausted
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail

        let private bigStackDynamicJoinDeferredFloodText = function
            | BigStackDynamicJoinDeferredFloodNotMature -> "not_mature"
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge -> "protected_pending_active_bridge"
            | BigStackDynamicJoinDeferredFloodCapExhausted -> "cap_exhausted"
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail -> "repeated_live_tail"
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail -> "waited_live_tail"

        let private bigStackDynamicJoinDeferredFloodFor status deferredCount terminalAge pendingCount queueDepth activeDepth recentReplayDelta recentRootDelta recentTerminalDelta rootWitnessActivity =
            if status = "semantic_dynamic_join_apply_blocked" then
                // ALPHA1380: 1379 showed terminal_age can reset while the same rank-92
                // dynamic-join blocker keeps being deferred.  The run-level deferral count
                // and small active-tail shape are therefore authority to stop treating live
                // replay as a fresh semantic witness.
                if pendingCount > 0 && activeDepth > 0 && recentReplayDelta >= 32L && rootWitnessActivity > 0 && deferredCount < 96 then
                    BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge
                elif deferredCount >= 24 && queueDepth <= 128 && activeDepth <= 4 then
                    BigStackDynamicJoinDeferredFloodRepeatedLiveTail
                elif deferredCount >= 12 && terminalAge >= 1000 && queueDepth <= 128 && activeDepth <= 4 && recentRootDelta <= 0L then
                    BigStackDynamicJoinDeferredFloodWaitedLiveTail
                elif deferredCount >= 6
                     && terminalAge >= 4000
                     && queueDepth <= 64
                     && activeDepth <= 4
                     && recentRootDelta <= 0L
                     && recentTerminalDelta <= 1L then
                    BigStackDynamicJoinDeferredFloodCapExhausted
                else
                    BigStackDynamicJoinDeferredFloodNotMature
            else
                BigStackDynamicJoinDeferredFloodNotMature

        let private bigStackDynamicJoinDeferredFloodShouldSurface = function
            | BigStackDynamicJoinDeferredFloodCapExhausted
            | BigStackDynamicJoinDeferredFloodRepeatedLiveTail
            | BigStackDynamicJoinDeferredFloodWaitedLiveTail -> true
            | BigStackDynamicJoinDeferredFloodNotMature
            | BigStackDynamicJoinDeferredFloodProtectedPendingActiveBridge -> false

        let private bigStackExplicitParentReplayPoisonHandoffDeferralCap = function
            | BigStackExplicitParentReplayPoisonSurface -> 0
            // ALPHA1300: while root/replay authority is fresh, a rank-83 parent-repeat pin
            // is not yet a final poison contract. Keep a bounded diagnostic grace window and
            // expose the deferred-type-hole sweep seam without fabricating completion.
            | BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress -> 12
            | BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep -> 18
            // ALPHA1297: runtime 1296 showed defer_live_unfinished_tail can dominate after
            // the terminal has already become an explicit parent-replay poison contract.
            // Keep a small live-tail grace window, but do not let q/a churn bypass the cap.
            | BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail -> 6
            | BigStackExplicitParentReplayPoisonDeferReplayCompleteness -> 12
            | BigStackExplicitParentReplayPoisonDeferRootAuthority -> 10
            | BigStackExplicitParentReplayPoisonDeferDynamicBridge -> 8
            | BigStackExplicitParentReplayPoisonDeferRootWitness -> 8
            | BigStackExplicitParentReplayPoisonDeferActiveTail -> 6

        let private bigStackExplicitParentReplayPoisonHandoffActionFor terminalAgeMs pendingCount queueDepth activeDepth rootProgress dynamicKeyBridge replayComplete postHandoffDeferrals ageCapMs recentReplayDelta recentRootDelta recentTerminalDelta recentSampledDelta =
            let physicalLiveTail = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let recentAuthorityProgress =
                recentRootDelta > 0L
                || recentSampledDelta > 0L
                || recentTerminalDelta > 0L
            let recentReplayMovement = recentReplayDelta > 0L
            let likelyDeferredTypeHoleSweep =
                not replayComplete
                && rootProgress >= 16
                && queueDepth <= 8
                && activeDepth <= 4
                && recentReplayMovement
                && terminalAgeMs < (max ageCapMs 120000)
            // ALPHA1342: alpha1341 was manually interrupted after 593s with a
            // pinned parent-replay poison, q/a/p=2/4/2, root/sample/terminal deltas
            // quiet and replay yielding only as scheduler churn.  A tiny live tail is
            // no longer authority to keep defer_live_unfinished_tail alive forever.
            let tinyStaleParentReplayPoisonTail =
                not replayComplete
                && physicalLiveTail
                && pendingCount <= 3
                && queueDepth <= 4
                && activeDepth <= 4
                && terminalAgeMs >= (max ageCapMs 12000)
                && recentRootDelta <= 0L
                && recentSampledDelta <= 0L
                && recentTerminalDelta <= 0L
            if tinyStaleParentReplayPoisonTail then
                BigStackExplicitParentReplayPoisonSurface
            elif not replayComplete && recentAuthorityProgress && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferRecentRootOrReplayProgress
            elif likelyDeferredTypeHoleSweep && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferDeferredTypeHoleSweep
            elif not replayComplete && physicalLiveTail then
                BigStackExplicitParentReplayPoisonDeferLiveUnfinishedTail
            elif dynamicKeyBridge > 0 && postHandoffDeferrals < 6 then
                BigStackExplicitParentReplayPoisonDeferDynamicBridge
            elif not replayComplete && rootProgress > 0 && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferReplayCompleteness
            elif terminalAgeMs < ageCapMs && (queueDepth > 0 || activeDepth > 0) then
                if rootProgress > 0 then BigStackExplicitParentReplayPoisonDeferRootWitness
                else BigStackExplicitParentReplayPoisonDeferActiveTail
            elif not replayComplete && postHandoffDeferrals < 8 then
                BigStackExplicitParentReplayPoisonDeferRootAuthority
            else BigStackExplicitParentReplayPoisonSurface

        let private bigStackExplicitParentReplayPoisonHandoffShouldDefer = function
            | BigStackExplicitParentReplayPoisonSurface -> false
            | _ -> true

        let private bigStackFastFailureUsefulnessFor (status: string) (reasonId: BigStackTerminalReasonId) dynamicKeyBridge poisonCascade terminalPins rootProgress =
            match reasonId with
            | BigStackTerminalReasonRuntimeRecordDynamicKeyRequired when dynamicKeyBridge > 0 ->
                BigStackFastFailureUsefulDynamicBridgeLocalized
            | BigStackTerminalReasonParentReplayStatusPreservedRepeat when status = "semantic_parent_replay_cycle_break_poisoned" && poisonCascade > 0 && terminalPins > 0 ->
                BigStackFastFailureUsefulParentReplayPoisonHandoff
            | _ when not (System.String.IsNullOrEmpty status) && terminalPins > 0 ->
                BigStackFastFailureUsefulFrontierPinned
            | _ when dynamicKeyBridge = 0 && poisonCascade = 0 && terminalPins = 0 && rootProgress = 0 ->
                BigStackFastFailureLowInfoNoAuthority
            | _ -> BigStackFastFailureUnclassified

        let private bigStackSequentialHotFrontierFastRetryAllowed = function
            | BigStackPevalMain -> true
            | _ -> false

        let private bigStackReplayChatterFastRetryAllowed = function
            | BigStackPevalMain
            | BigStackTerm
            | BigStackTy -> true
            | _ -> false

        // ALPHA1105: runtime 1104 proved the previous 4096 threshold was unreachable
        // before the hard timeout because these counters represent sampled liveness
        // receipts at the join boundary.  Keep the threshold closed and local to
        // peval_main fast-retry so it cannot become semantic authority.
        let private bigStackDiagnosticActivityFastRetryThreshold = 32

        // ALPHA1383: generation-change waits that already have a small tripped
        // term-cycle fuse should surface a typed fail-closed terminal instead of
        // spending a retry-only EJP0018 round.  The DU keeps retry vs terminal
        // authority explicit at the BigStack boundary.
        type BigStackGenerationChangeDecisionId =
            | BigStackGenerationChangeObserve
            | BigStackGenerationChangeRetryEjp0018
            | BigStackGenerationChangeDeferLiveReplayTail
            | BigStackGenerationChangeSurfaceTermCycleFusePoison

        let private bigStackGenerationChangeDecisionText = function
            | BigStackGenerationChangeObserve -> "observe"
            | BigStackGenerationChangeRetryEjp0018 -> "retry_ejp0018"
            | BigStackGenerationChangeDeferLiveReplayTail -> "defer_live_reentry_fuse_tail"
            | BigStackGenerationChangeSurfaceTermCycleFusePoison -> "surface_term_reentry_fuse_poison"

        let private bigStackGenerationChangeDecisionFor tag cycleTripped terminalAlreadyPinned pendingCount queueDepth activeDepth replayComplete writeWitness waitedSinceGenChangeMs =
            let liveTailRunnable = pendingCount > 0 || queueDepth > 0 || activeDepth > 0
            let liveTailFresh = waitedSinceGenChangeMs >= 0 && waitedSinceGenChangeMs < 5000
            if cycleTripped
               && tag = "peval_main"
               && not replayComplete
               && not writeWitness
               && liveTailRunnable
               && liveTailFresh then
                BigStackGenerationChangeDeferLiveReplayTail
            elif cycleTripped
                 && tag = "peval_main"
                 && not terminalAlreadyPinned
                 && not replayComplete
                 && not writeWitness
                 && pendingCount <= 2
                 && queueDepth <= 16
                 && activeDepth <= 4
                 && waitedSinceGenChangeMs >= 0 then
                BigStackGenerationChangeSurfaceTermCycleFusePoison
            elif cycleTripped || waitedSinceGenChangeMs >= 0 then
                BigStackGenerationChangeRetryEjp0018
            else
                BigStackGenerationChangeObserve

        // ALPHA1103: closed evidence id for retry policy; no ad-hoc policy strings
        // in the predicate.  Text is only emitted at the diagnostic boundary.
        type BigStackFastRetryEvidenceId =
            | BigStackFastRetryHotFrontier
            | BigStackFastRetryDiagnosticActivity
            | BigStackFastRetryCycleFuse
            | BigStackFastRetryPreSequentialDiagnosticActivity

        let private bigStackFastRetryEvidenceText = function
            | BigStackFastRetryHotFrontier -> "hot_frontier"
            | BigStackFastRetryDiagnosticActivity -> "diagnostic_activity"
            | BigStackFastRetryCycleFuse -> "replay_repeat_guard"
            | BigStackFastRetryPreSequentialDiagnosticActivity -> "preseq_diagnostic_activity"

        type BigStackFastRetryActionId =
            | BigStackFastRetryRaiseEjp0019
            | BigStackFastRetryRaiseReplayNoRootEjp0019
            | BigStackFastRetryRaiseReplayChatterEjp0019
            | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019
            | BigStackFastRetryDeferHotFrontierActivity
            | BigStackFastRetryDeferLiveReplay
            | BigStackFastRetryDeferSemanticTailActivity
            | BigStackFastRetryDeferActiveTailYield
            | BigStackFastRetryObserveOnly

        let private bigStackFastRetryActionText = function
            | BigStackFastRetryRaiseEjp0019 -> "raise_ejp0019"
            | BigStackFastRetryRaiseReplayNoRootEjp0019 -> "raise_replay_no_root_ejp0019"
            | BigStackFastRetryRaiseReplayChatterEjp0019 -> "raise_replay_chatter_ejp0019"
            | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 -> "raise_stale_no_root_small_queue_ejp0019"
            | BigStackFastRetryDeferHotFrontierActivity -> "defer_hot_frontier_activity"
            | BigStackFastRetryDeferLiveReplay -> "defer_live_replay"
            | BigStackFastRetryDeferSemanticTailActivity -> "defer_semantic_tail_activity"
            | BigStackFastRetryDeferActiveTailYield -> "defer_active_tail_yield"
            | BigStackFastRetryObserveOnly -> "observe_only"

        // ALPHA1333: closed exit decision for the hot-frontier retry boundary.
        // The old path collapsed every fast-retry raise into EJP0019 even when the
        // frontier was still alive (1332 final: pending=2/q=1/a=4/root_wit≈15).
        type BigStackHotFrontierExitDecisionId =
            | BigStackHotFrontierExitObserve
            | BigStackHotFrontierExitYieldActiveTail
            | BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            | BigStackHotFrontierExitPendingActiveRepeatCapDrain
            | BigStackHotFrontierExitPendingQueueRepeatCapDrain
            | BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain
            | BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain
            | BigStackHotFrontierExitActiveStructuralChurnCircuitBreak
            | BigStackHotFrontierExitSurfaceRepeatCapBreach
            | BigStackHotFrontierExitHardPoisonPendingZero
            | BigStackHotFrontierExitRaiseEjp0019

        let private bigStackHotFrontierExitDecisionText = function
            | BigStackHotFrontierExitObserve -> "observe"
            | BigStackHotFrontierExitYieldActiveTail -> "yield_active_tail"
            | BigStackHotFrontierExitRepeatCapProbationDrainInFlight -> "repeat_cap_probation_drain_in_flight"
            | BigStackHotFrontierExitPendingActiveRepeatCapDrain -> "pending_active_repeat_cap_drain"
            | BigStackHotFrontierExitPendingQueueRepeatCapDrain -> "pending_queue_repeat_cap_drain"
            | BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain -> "dynamic_record_key_bridge_tail_drain"
            | BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain -> "dynamic_join_pending_fence_bridge_drain"
            | BigStackHotFrontierExitActiveStructuralChurnCircuitBreak -> "active_structural_churn_circuit_break"
            | BigStackHotFrontierExitSurfaceRepeatCapBreach -> "surface_cascaded_terminal_repeat_cap_breach"
            | BigStackHotFrontierExitHardPoisonPendingZero -> "hard_poison_pending_zero"
            | BigStackHotFrontierExitRaiseEjp0019 -> "raise_ejp0019"

        let private bigStackHotFrontierExitDecisionFor action pending queueDepth activeDepth rootWitness replayComplete writeWitness progressYield repeatCapBreached repeatCapProbationDrainInFlight recordKeyBridgeTailLive dynamicJoinPendingFenceBridgeLive =
            let wantsRaise =
                match action with
                | BigStackFastRetryRaiseEjp0019
                | BigStackFastRetryRaiseReplayNoRootEjp0019
                | BigStackFastRetryRaiseReplayChatterEjp0019
                | BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 -> true
                | _ -> false
            if repeatCapBreached && recordKeyBridgeTailLive && (pending > 0 || queueDepth > 0 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitDynamicRecordKeyBridgeTailDrain
            elif repeatCapBreached && dynamicJoinPendingFenceBridgeLive && (pending > 0 || queueDepth > 0 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitDynamicJoinPendingFenceBridgeDrain
            elif repeatCapBreached && repeatCapProbationDrainInFlight && not recordKeyBridgeTailLive && not dynamicJoinPendingFenceBridgeLive && not replayComplete && not writeWitness then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && queueDepth >= 128 && activeDepth >= 4 && rootWitness > 0 && not replayComplete && not writeWitness && not recordKeyBridgeTailLive then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && queueDepth >= 16 && activeDepth >= 2 && not replayComplete && not writeWitness && not recordKeyBridgeTailLive then BigStackHotFrontierExitActiveStructuralChurnCircuitBreak
            elif repeatCapBreached && activeDepth > 0 && pending > 0 && (queueDepth <= 16 || rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitPendingActiveRepeatCapDrain
            elif repeatCapBreached && pending > 0 && queueDepth > 0 && queueDepth <= 16 && not replayComplete && not writeWitness then BigStackHotFrontierExitPendingQueueRepeatCapDrain
            elif repeatCapBreached && activeDepth > 0 && queueDepth > 0 && pending = 0 && (rootWitness > 0 || progressYield) && not replayComplete && not writeWitness then BigStackHotFrontierExitRepeatCapProbationDrainInFlight
            elif repeatCapBreached && not replayComplete && not writeWitness then BigStackHotFrontierExitSurfaceRepeatCapBreach
            elif action = BigStackFastRetryDeferActiveTailYield && activeDepth > 0 && queueDepth > 0 && pending = 0 && queueDepth <= 64 then BigStackHotFrontierExitYieldActiveTail
            elif action = BigStackFastRetryDeferActiveTailYield && activeDepth > 0 && pending > 0 then BigStackHotFrontierExitYieldActiveTail
            elif not wantsRaise then BigStackHotFrontierExitObserve
            elif replayComplete || writeWitness then BigStackHotFrontierExitObserve
            elif action = BigStackFastRetryRaiseStaleNoRootSmallQueueEjp0019 then BigStackHotFrontierExitRaiseEjp0019
            elif activeDepth > 0 && pending = 0 && queueDepth > 0 && queueDepth <= 64 && (rootWitness > 0 || progressYield) then BigStackHotFrontierExitYieldActiveTail
            elif activeDepth > 0 && pending = 0 && queueDepth > 0 then BigStackHotFrontierExitHardPoisonPendingZero
            elif activeDepth > 0 && pending > 0 && (queueDepth <= 8 || rootWitness >= 10 || progressYield) then BigStackHotFrontierExitYieldActiveTail
            else BigStackHotFrontierExitRaiseEjp0019

        type ReplayNoRootFinishDecisionId =
            | ReplayNoRootFinishObserve
            | ReplayNoRootFinishHoldRootOrComplete
            | ReplayNoRootFinishGraceDrainingFrontier
            | ReplayNoRootFinishLastChanceDrain
            | ReplayNoRootFinishRaiseRetry

        let private replayNoRootFinishDecisionText = function
            | ReplayNoRootFinishObserve -> "observe"
            | ReplayNoRootFinishHoldRootOrComplete -> "hold_root_or_complete"
            | ReplayNoRootFinishGraceDrainingFrontier -> "grace_draining_frontier"
            | ReplayNoRootFinishLastChanceDrain -> "last_chance_drain_no_root_budget"
            | ReplayNoRootFinishRaiseRetry -> "raise_retry_no_root_budget"

        type ReplayNoRootFinishEvidenceId =
            | ReplayNoRootFinishEvidenceRootOrWriter
            | ReplayNoRootFinishEvidenceFreshRootWitness
            | ReplayNoRootFinishEvidenceStaleNoRootSmallQueue
            | ReplayNoRootFinishEvidenceReplayOnlyChatter
            | ReplayNoRootFinishEvidenceColdStructuralSurge
            | ReplayNoRootFinishEvidenceObserve

        let private replayNoRootFinishEvidenceText = function
            | ReplayNoRootFinishEvidenceRootOrWriter -> "root_or_writer"
            | ReplayNoRootFinishEvidenceFreshRootWitness -> "fresh_root_witness"
            | ReplayNoRootFinishEvidenceStaleNoRootSmallQueue -> "stale_no_root_small_queue"
            | ReplayNoRootFinishEvidenceReplayOnlyChatter -> "replay_only_chatter"
            | ReplayNoRootFinishEvidenceColdStructuralSurge -> "cold_structural_surge"
            | ReplayNoRootFinishEvidenceObserve -> "observe"

        // ALPHA1425: closed gate for no-root queue pressure. Alpha1424 showed
        // q/a/root progress (q=63/a=4/roots=6, repeat=2/4, terminal=0) briefly
        // classified as raise_retry_no_root_budget while the same tail was fresh.
        // This DU keeps fresh-root pressure as drain authority until either the
        // queue is truly mature or root freshness expires.
        type ReplayNoRootPressureGateId =
            | ReplayNoRootPressureFreshRootDrain
            | ReplayNoRootPressureMatureQueueRetry
            | ReplayNoRootPressureObserve

        let private replayNoRootPressureGateText = function
            | ReplayNoRootPressureFreshRootDrain -> "fresh_root_pressure_drain"
            | ReplayNoRootPressureMatureQueueRetry -> "mature_queue_pressure_retry"
            | ReplayNoRootPressureObserve -> "observe"

        let private replayNoRootPressureGateFor waitedMs queueDepth activeDepth rootWitnessActivity rootWitnessStillRising rootWitnessGraceActive =
            if activeDepth >= 4 && queueDepth >= 48 && queueDepth < 96 && rootWitnessActivity > 0 && (rootWitnessStillRising || rootWitnessGraceActive) && waitedMs < 9000 then ReplayNoRootPressureFreshRootDrain
            elif waitedMs >= 1250 && queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 9000 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 8 && not (rootWitnessStillRising || rootWitnessGraceActive) then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 26000 && queueDepth >= 48 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 34000 && queueDepth >= 32 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            elif waitedMs >= 44000 && queueDepth >= 24 && activeDepth >= 4 then ReplayNoRootPressureMatureQueueRetry
            else ReplayNoRootPressureObserve

        type ReplayNoRootDrainBudgetId =
            | ReplayNoRootDrainNoBudget
            | ReplayNoRootDrainStandardBudget
            | ReplayNoRootDrainUnderutilizedQueueBudget

        let private replayNoRootDrainBudgetText = function
            | ReplayNoRootDrainNoBudget -> "none"
            | ReplayNoRootDrainStandardBudget -> "standard_drain_budget"
            | ReplayNoRootDrainUnderutilizedQueueBudget -> "underutilized_queue_drain_budget"

        let private replayNoRootDrainBudgetValue = function
            | ReplayNoRootDrainNoBudget -> 0
            | ReplayNoRootDrainStandardBudget -> 4
            | ReplayNoRootDrainUnderutilizedQueueBudget -> 8

        let private replayNoRootDrainBudgetFor queueDepth activeDepth =
            if queueDepth >= 16 && activeDepth >= 4 then ReplayNoRootDrainUnderutilizedQueueBudget
            elif queueDepth >= 128 || activeDepth >= 4 then ReplayNoRootDrainStandardBudget
            else ReplayNoRootDrainNoBudget

        let private replayNoRootFinishEvidenceFor decisionId rootWitnessStillRising staleSmallQueue replayChatter coldStructural replayComplete writeWitness =
            if replayComplete || writeWitness then ReplayNoRootFinishEvidenceRootOrWriter
            elif rootWitnessStillRising then ReplayNoRootFinishEvidenceFreshRootWitness
            elif staleSmallQueue then ReplayNoRootFinishEvidenceStaleNoRootSmallQueue
            elif replayChatter then ReplayNoRootFinishEvidenceReplayOnlyChatter
            elif coldStructural then ReplayNoRootFinishEvidenceColdStructuralSurge
            else
                match decisionId with
                | ReplayNoRootFinishRaiseRetry -> ReplayNoRootFinishEvidenceStaleNoRootSmallQueue
                | _ -> ReplayNoRootFinishEvidenceObserve

        // ALPHA1411: no-root bypass probation is authority, not a loose string.
        // Alpha1410 reached 87.6% then surfaced rank-83 with repeat=4/4,
        // q/a/p=14/1/2 and deny=repeat_cap_not_breached.  Reaching the cap
        // with a live queue/active/pending tail is a probation/drain condition;
        // only an exhausted, quiet, or writer-complete tail may surface terminal.
        type NoRootBudgetBypassProbationDecisionId =
            | NoRootBudgetBypassProbationNone
            | NoRootBudgetBypassProbationMissingAfterPrefetchLiveTail
            | NoRootBudgetBypassProbationMissingAfterPrefetchFrontierPendingSidecar
            | NoRootBudgetBypassProbationRank83LiveRootSemanticTail
            | NoRootBudgetBypassProbationRank83WriteWitnessIncompleteLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapWriteWitnessPendingSemanticTail
            | NoRootBudgetBypassProbationLiveTailEvidenceOverride
            | NoRootBudgetBypassProbationSmallQueueActiveAuthorityOverride
            | NoRootBudgetBypassProbationActiveOnlyPendingAuthorityOverride
            | NoRootBudgetBypassProbationPreCapActiveTailOverride
            | NoRootBudgetBypassProbationRank83RepeatCapPendingSemanticTail
            | NoRootBudgetBypassProbationRank83RepeatCapReachedLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapBreachedLiveTail

        let private noRootBudgetBypassProbationDecisionText = function
            | NoRootBudgetBypassProbationNone -> "none"
            | NoRootBudgetBypassProbationMissingAfterPrefetchLiveTail -> "missing_after_prefetch_live_tail"
            | NoRootBudgetBypassProbationMissingAfterPrefetchFrontierPendingSidecar -> "missing_after_prefetch_frontier_pending_sidecar"
            | NoRootBudgetBypassProbationRank83LiveRootSemanticTail -> "rank83_live_root_semantic_tail"
            | NoRootBudgetBypassProbationRank83WriteWitnessIncompleteLiveTail -> "rank83_write_witness_incomplete_live_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapWriteWitnessPendingSemanticTail -> "rank83_repeat_cap_write_witness_pending_semantic_tail"
            | NoRootBudgetBypassProbationLiveTailEvidenceOverride -> "live_tail_evidence_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationSmallQueueActiveAuthorityOverride -> "small_queue_active_authority_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationActiveOnlyPendingAuthorityOverride -> "active_only_pending_authority_overrides_no_root_bypass"
            | NoRootBudgetBypassProbationPreCapActiveTailOverride -> "pre_cap_active_tail_override_forces_probation"
            | NoRootBudgetBypassProbationRank83RepeatCapPendingSemanticTail -> "rank83_repeat_cap_pending_semantic_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapReachedLiveTail -> "rank83_repeat_cap_reached_live_tail"
            | NoRootBudgetBypassProbationRank83RepeatCapBreachedLiveTail -> "rank83_repeat_cap_breached_live_tail"

        let private noRootBudgetBypassProbationShouldDrain = function
            | NoRootBudgetBypassProbationNone -> false
            | NoRootBudgetBypassProbationMissingAfterPrefetchLiveTail
            | NoRootBudgetBypassProbationMissingAfterPrefetchFrontierPendingSidecar
            | NoRootBudgetBypassProbationRank83LiveRootSemanticTail
            | NoRootBudgetBypassProbationRank83WriteWitnessIncompleteLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapWriteWitnessPendingSemanticTail
            | NoRootBudgetBypassProbationLiveTailEvidenceOverride
            | NoRootBudgetBypassProbationSmallQueueActiveAuthorityOverride
            | NoRootBudgetBypassProbationActiveOnlyPendingAuthorityOverride
            | NoRootBudgetBypassProbationPreCapActiveTailOverride
            | NoRootBudgetBypassProbationRank83RepeatCapPendingSemanticTail
            | NoRootBudgetBypassProbationRank83RepeatCapReachedLiveTail
            | NoRootBudgetBypassProbationRank83RepeatCapBreachedLiveTail -> true

        // ALPHA1424: one authoritative live-tail override DU for no-root bypass.
        // Earlier alphas exposed the same truth through scattered deny strings;
        // this DU is the single field that future HUD/JSONL consumers can trust.
        type NoRootBudgetBypassLiveTailOverrideDecisionId =
            | NoRootBudgetBypassLiveTailOverrideGranted
            | NoRootBudgetBypassLiveTailOverrideGrantedSmallQueueActiveAuthority
            | NoRootBudgetBypassLiveTailOverrideGrantedActiveOnlyPendingAuthority
            | NoRootBudgetBypassLiveTailOverrideDeniedSmallQueueActiveAuthorityExhausted
            | NoRootBudgetBypassLiveTailOverrideDeniedRank
            | NoRootBudgetBypassLiveTailOverrideDeniedReplayComplete
            | NoRootBudgetBypassLiveTailOverrideDeniedQuiescent
            | NoRootBudgetBypassLiveTailOverrideDeniedNoPhysicalTail
            | NoRootBudgetBypassLiveTailOverrideDeniedNoAuthorityEvidence
            | NoRootBudgetBypassLiveTailOverrideDeniedPredicateOrder

        let private noRootBudgetBypassLiveTailOverrideDecisionText = function
            | NoRootBudgetBypassLiveTailOverrideGranted -> "granted_live_tail_override"
            | NoRootBudgetBypassLiveTailOverrideGrantedSmallQueueActiveAuthority -> "granted_small_queue_active_authority"
            | NoRootBudgetBypassLiveTailOverrideGrantedActiveOnlyPendingAuthority -> "granted_active_only_pending_authority"
            | NoRootBudgetBypassLiveTailOverrideDeniedSmallQueueActiveAuthorityExhausted -> "denied_small_queue_active_authority_exhausted"
            | NoRootBudgetBypassLiveTailOverrideDeniedRank -> "denied_rank_not_probation_eligible"
            | NoRootBudgetBypassLiveTailOverrideDeniedReplayComplete -> "denied_replay_complete"
            | NoRootBudgetBypassLiveTailOverrideDeniedQuiescent -> "denied_active_tail_quiescent"
            | NoRootBudgetBypassLiveTailOverrideDeniedNoPhysicalTail -> "denied_no_physical_tail"
            | NoRootBudgetBypassLiveTailOverrideDeniedNoAuthorityEvidence -> "denied_no_root_or_semantic_authority"
            | NoRootBudgetBypassLiveTailOverrideDeniedPredicateOrder -> "denied_predicate_order_or_terminal_authority"

        type ReplayNoRootStructuralActionId =
            | ReplayNoRootStructuralObserve
            | ReplayNoRootStructuralDrainLiveReplay
            | ReplayNoRootStructuralDrainLiveReplayTickRequested
            | ReplayNoRootStructuralRootProgressDrain
            | ReplayNoRootStructuralReplayRootWitnessQueueDrainRequested
            | ReplayNoRootStructuralActiveQueueSurgeHardPoisonSkipped
            | ReplayNoRootStructuralActiveQueueSurgeHardPoisonInjected
            | ReplayNoRootStructuralQueueSurgePoisonDeferredColdStructuralSurge
            | ReplayNoRootStructuralQueueSurgeRaiseRetryPoisonSkipped
            | ReplayNoRootStructuralQueueSurgeRaiseRetryPoisonInjected
            | ReplayNoRootStructuralQueueSurgeRepeatedDeferralPoisonSkipped
            | ReplayNoRootStructuralQueueSurgeRepeatedDeferralPoisonInjected
            | ReplayNoRootStructuralQueueSurgePoisonSkipped
            | ReplayNoRootStructuralQueueSurgePoisonInjected
            | ReplayNoRootStructuralCrossKindPoisonDeferredColdStructuralSurge
            | ReplayNoRootStructuralCrossKindPoisonSkipped
            | ReplayNoRootStructuralCrossKindPoisonInjected
            | ReplayNoRootStructuralQueueSurgeCycleBreakSkipped
            | ReplayNoRootStructuralQueueSurgeCycleBreakInjected
            | ReplayNoRootStructuralWakeIdleQueue
            | ReplayNoRootStructuralWakeIdleQueueSkipped
            | ReplayNoRootStructuralCycleBreakSkipped
            | ReplayNoRootStructuralCycleBreakInjected

        let private replayNoRootStructuralActionText = function
            | ReplayNoRootStructuralObserve -> "observe"
            | ReplayNoRootStructuralDrainLiveReplay -> "drain_live_replay"
            | ReplayNoRootStructuralDrainLiveReplayTickRequested -> "drain_live_replay_tick_requested"
            | ReplayNoRootStructuralRootProgressDrain -> "root_progress_drain"
            | ReplayNoRootStructuralReplayRootWitnessQueueDrainRequested -> "replay_root_witness_queue_drain_requested"
            | ReplayNoRootStructuralActiveQueueSurgeHardPoisonSkipped -> "active_queue_surge_hard_poison_skipped"
            | ReplayNoRootStructuralActiveQueueSurgeHardPoisonInjected -> "active_queue_surge_hard_poison_injected"
            | ReplayNoRootStructuralQueueSurgePoisonDeferredColdStructuralSurge -> "queue_surge_poison_deferred_cold_structural_surge"
            | ReplayNoRootStructuralQueueSurgeRaiseRetryPoisonSkipped -> "queue_surge_raise_retry_poison_skipped"
            | ReplayNoRootStructuralQueueSurgeRaiseRetryPoisonInjected -> "queue_surge_raise_retry_poison_injected"
            | ReplayNoRootStructuralQueueSurgeRepeatedDeferralPoisonSkipped -> "queue_surge_repeated_deferral_poison_skipped"
            | ReplayNoRootStructuralQueueSurgeRepeatedDeferralPoisonInjected -> "queue_surge_repeated_deferral_poison_injected"
            | ReplayNoRootStructuralQueueSurgePoisonSkipped -> "queue_surge_poison_skipped"
            | ReplayNoRootStructuralQueueSurgePoisonInjected -> "queue_surge_poison_injected"
            | ReplayNoRootStructuralCrossKindPoisonDeferredColdStructuralSurge -> "cross_kind_poison_deferred_cold_structural_surge"
            | ReplayNoRootStructuralCrossKindPoisonSkipped -> "cross_kind_poison_skipped"
            | ReplayNoRootStructuralCrossKindPoisonInjected -> "cross_kind_poison_injected"
            | ReplayNoRootStructuralQueueSurgeCycleBreakSkipped -> "queue_surge_cycle_break_skipped"
            | ReplayNoRootStructuralQueueSurgeCycleBreakInjected -> "queue_surge_cycle_break_injected"
            | ReplayNoRootStructuralWakeIdleQueue -> "wake_idle_queue"
            | ReplayNoRootStructuralWakeIdleQueueSkipped -> "wake_idle_queue_skipped"
            | ReplayNoRootStructuralCycleBreakSkipped -> "cycle_break_skipped"
            | ReplayNoRootStructuralCycleBreakInjected -> "cycle_break_injected"

        type ReplayParentPoisonScopeId =
            | ReplayParentPoisonQueueSurge
            | ReplayParentPoisonCrossKind

        let private replayParentPoisonScopeText = function
            | ReplayParentPoisonQueueSurge -> "queue_surge_parent_poison"
            | ReplayParentPoisonCrossKind -> "cross_kind_parent_poison"

        // ALPHA1379: close queue-surge parent-poison maturity as a DU. Alpha1378
        // proved the terminal was correct but too late: q>=96/a=4/root>=10 kept
        // passing through cold_structural_surge receipts before the rank-83 poison
        // became visible. This typed gate makes high-root queue surge authority
        // explicit instead of hiding it in ad-hoc string thresholds.
        type ReplayQueueSurgeMaturityId =
            | ReplayQueueSurgeColdStructural
            | ReplayQueueSurgeMatureRepeatedDeferral
            | ReplayQueueSurgeMatureHighRootQueue
            | ReplayQueueSurgeMatureStalledRootQueue
            | ReplayQueueSurgeMatureWallClock

        let private replayQueueSurgeMaturityText = function
            | ReplayQueueSurgeColdStructural -> "cold_structural_surge"
            | ReplayQueueSurgeMatureRepeatedDeferral -> "mature_repeated_deferral"
            | ReplayQueueSurgeMatureHighRootQueue -> "mature_high_root_queue"
            | ReplayQueueSurgeMatureStalledRootQueue -> "mature_stalled_root_queue"
            | ReplayQueueSurgeMatureWallClock -> "mature_wall_clock"

        let private replayQueueSurgeMaturityIsMature = function
            | ReplayQueueSurgeColdStructural -> false
            | ReplayQueueSurgeMatureRepeatedDeferral
            | ReplayQueueSurgeMatureHighRootQueue
            | ReplayQueueSurgeMatureStalledRootQueue
            | ReplayQueueSurgeMatureWallClock -> true

        let private replayQueueSurgeMaturityFor waitedMs queueDepth activeDepth rootWitnessActivity coldDeferrals rootWitnessStallMs =
            if queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 8 && waitedMs >= 750 then ReplayQueueSurgeMatureHighRootQueue
            elif queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 && rootWitnessStallMs >= 750 && waitedMs >= 1000 then ReplayQueueSurgeMatureStalledRootQueue
            elif queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 3 && coldDeferrals >= 1 && waitedMs >= 500 then ReplayQueueSurgeMatureRepeatedDeferral
            elif queueDepth >= 64 && activeDepth >= 4 && rootWitnessActivity >= 4 && waitedMs >= 9000 then ReplayQueueSurgeMatureWallClock
            else ReplayQueueSurgeColdStructural

        type BigStackQueueSurgeRetryDecisionId =
            | BigStackQueueSurgeRetryObserve
            | BigStackQueueSurgeRetryDrainRepeatCapProbation
            | BigStackQueueSurgeRetryEscalateRepeatCapExhausted
            | BigStackQueueSurgeRetryInjectParentPoison

        let private bigStackQueueSurgeRetryDecisionText = function
            | BigStackQueueSurgeRetryObserve -> "observe"
            | BigStackQueueSurgeRetryDrainRepeatCapProbation -> "drain_repeat_cap_probation"
            | BigStackQueueSurgeRetryEscalateRepeatCapExhausted -> "escalate_repeat_cap_exhausted"
            | BigStackQueueSurgeRetryInjectParentPoison -> "inject_parent_poison"

        let private bigStackQueueSurgeRetryDecisionFor finishDecisionId noPinnedBudgetBypass queueDepth activeDepth rootWitnessActivity repeatCount repeatCap waitedMs replayComplete writeWitness =
            if replayComplete || writeWitness then BigStackQueueSurgeRetryObserve
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && repeatCap > 0
                 && repeatCount >= (max 8 (repeatCap * 2))
                 && waitedMs >= 24000 then
                // ALPHA1421: 1420 showed q=307/a=4/root=9/repeat=10/4 still
                // draining after 45s because the old cap*32 threshold required
                // repeat=128.  Mature queue-surge probation must close before it
                // becomes a CPU-only livelock.
                BigStackQueueSurgeRetryEscalateRepeatCapExhausted
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && repeatCap > 0
                 && repeatCount >= repeatCap then
                BigStackQueueSurgeRetryDrainRepeatCapProbation
            elif finishDecisionId = ReplayNoRootFinishRaiseRetry
                 && noPinnedBudgetBypass
                 && activeDepth >= 4
                 && queueDepth >= 96
                 && rootWitnessActivity >= 4
                 && (repeatCap <= 0 || repeatCount < repeatCap)
                 && waitedMs >= 12000 then
                BigStackQueueSurgeRetryInjectParentPoison
            else BigStackQueueSurgeRetryObserve

        // No-root finish-budget receipts remain typed, but their JSON emission is
        // cadence-gated so live replay does not drown the HUD/log in identical
        // hold_root_or_complete lines.
        type ReplayNoRootFinishLogCadenceId =
            | ReplayNoRootFinishLogSuppress
            | ReplayNoRootFinishLogDecisionChanged
            | ReplayNoRootFinishLogRootWitnessDelta
            | ReplayNoRootFinishLogQueuePhaseShift
            | ReplayNoRootFinishLogQueueSurgeMilestone
            | ReplayNoRootFinishLogCadenceDue
            | ReplayNoRootFinishLogRaiseRetry

        let private replayNoRootFinishLogCadenceText = function
            | ReplayNoRootFinishLogSuppress -> "suppress"
            | ReplayNoRootFinishLogDecisionChanged -> "decision_changed"
            | ReplayNoRootFinishLogRootWitnessDelta -> "root_witness_delta"
            | ReplayNoRootFinishLogQueuePhaseShift -> "queue_phase_shift"
            | ReplayNoRootFinishLogQueueSurgeMilestone -> "queue_surge_milestone"
            | ReplayNoRootFinishLogCadenceDue -> "cadence_due"
            | ReplayNoRootFinishLogRaiseRetry -> "raise_retry"

        let private replayNoRootFinishLogCadenceFor decision waitedMs lastEmitMs lastDecision rootWitnessActivity lastRootWitnessActivity queueDepth lastQueueDepth =
            if decision = ReplayNoRootFinishObserve then ReplayNoRootFinishLogSuppress
            elif decision <> lastDecision then ReplayNoRootFinishLogDecisionChanged
            elif decision = ReplayNoRootFinishRaiseRetry && waitedMs - lastEmitMs >= 3000 then ReplayNoRootFinishLogRaiseRetry
            elif rootWitnessActivity > lastRootWitnessActivity then ReplayNoRootFinishLogRootWitnessDelta
            elif queueDepth >= 128 && (queueDepth / 64) <> (lastQueueDepth / 64) then ReplayNoRootFinishLogQueueSurgeMilestone
            elif queueDepth < 128 && (queueDepth / 16) <> (lastQueueDepth / 16) then ReplayNoRootFinishLogQueuePhaseShift
            elif waitedMs - lastEmitMs >= 3000 then ReplayNoRootFinishLogCadenceDue
            else ReplayNoRootFinishLogSuppress

        type ReplayRootWitnessStallId =
            | ReplayRootWitnessProgressFresh
            | ReplayRootWitnessStalled of int

        let private replayRootWitnessStallFor waitedMs lastEmitMs rootWitnessActivity lastRootWitnessActivity =
            if rootWitnessActivity > lastRootWitnessActivity then ReplayRootWitnessProgressFresh
            else ReplayRootWitnessStalled (max 0 (waitedMs - lastEmitMs))

        let private replayRootWitnessStallText = function
            | ReplayRootWitnessProgressFresh -> "fresh"
            | ReplayRootWitnessStalled _ -> "stalled"

        let private replayRootWitnessStallMs = function
            | ReplayRootWitnessProgressFresh -> 0
            | ReplayRootWitnessStalled ms -> ms

        type ReplayActiveTailQuiescenceId =
            | ReplayActiveTailNotQuiescent
            | ReplayActiveTailQuiescentNoQueue

        let private replayActiveTailQuiescenceFor queueDepth activeDepth =
            if queueDepth <= 0 && activeDepth > 0 then ReplayActiveTailQuiescentNoQueue
            else ReplayActiveTailNotQuiescent

        let private replayActiveTailQuiescenceText = function
            | ReplayActiveTailNotQuiescent -> "not_quiescent"
            | ReplayActiveTailQuiescentNoQueue -> "quiescent_no_queue"

        let private replayActiveTailQuiescenceBool = function
            | ReplayActiveTailNotQuiescent -> false
            | ReplayActiveTailQuiescentNoQueue -> true

        let private replayNoRootFinishDecisionFor waitedMs queueDepth activeDepth rootWitnessActivity terminalSignals rootWitnessStillRising rootWitnessGraceActive replayComplete writeWitness =
            if replayComplete || writeWitness then ReplayNoRootFinishHoldRootOrComplete
            elif replayNoRootPressureGateFor waitedMs queueDepth activeDepth rootWitnessActivity rootWitnessStillRising rootWitnessGraceActive = ReplayNoRootPressureFreshRootDrain then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 12000 && queueDepth <= 8 && activeDepth <= 4 && rootWitnessActivity >= 192 then
                // ALPHA1278: alpha1277 proved the old terminal-signal gate was too strict:
                // the HUD had thousands of terminal_signals, but this local no-root budget
                // counted only selected terminal kinds and kept returning grace_draining_frontier
                // at q≈6/a≈3/roots≈1108.  Mature root authority plus a small active tail is
                // enough to surface the fail-closed retry instead of waiting for one more
                // low-frequency replay trickle.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 45000 && queueDepth <= 8 && activeDepth <= 4 && rootWitnessActivity >= 128 && terminalSignals >= 160 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 1250 && queueDepth >= 96 && activeDepth >= 4 && rootWitnessActivity >= 4 then
                // ALPHA1381: alpha1380 showed q≈101..148/a=4/roots=4 being
                // reported as cold_structural_surge for several seconds before the
                // correct rank-83 poison surfaced. Root=4 is enough authority once
                // queue pressure is already triple digit and no writer/replay-complete exists.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 2500 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 2 then
                // ALPHA1325: alpha1324 showed q≈53-85/a=4 with only 2-6 root
                // witnesses still being deferred as cold structural surge.  Queue+active
                // pressure is already scheduler debt at this point; raise fail-closed
                // before the graph drains into a silent no-work tail.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 6500 && queueDepth >= 64 && activeDepth >= 4 && rootWitnessActivity >= 8 then
                // ALPHA1324: alpha1323 spent the tail at q≈79-98/a=4/roots=9,
                // but the generic root-witness grace branch sat above queue-pressure
                // raises.  Mature active-tail pressure now outranks root-progress
                // grace; the retry is still fail-closed and produces no BuildOk.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 9000 && queueDepth >= 48 && activeDepth >= 4 && rootWitnessActivity >= 8 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 14000 && queueDepth >= 32 && activeDepth >= 4 && rootWitnessActivity >= 8 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 26000 && queueDepth >= 48 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 34000 && queueDepth >= 32 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 44000 && queueDepth >= 24 && activeDepth >= 4 then ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 9000 && queueDepth <= 8 && activeDepth >= 4 && rootWitnessActivity >= 12 then
                // ALPHA1327: 1326 showed the exact post-pressure tail:
                // q≈3/a=4/roots≈15 kept choosing grace_draining_frontier at
                // 9.25s, 12.25s and 15.25s, then the metronome spent 130s in
                // no-work rescue.  Treat this as mature scheduler debt, not
                // generic root-progress grace.
                ReplayNoRootFinishRaiseRetry
            elif waitedMs >= 15000 && queueDepth <= 16 && activeDepth >= 4 && rootWitnessActivity >= 12 then ReplayNoRootFinishRaiseRetry
            elif rootWitnessActivity > 0 && (rootWitnessStillRising || rootWitnessGraceActive) then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 18000 && queueDepth <= 2 && activeDepth <= 0 then ReplayNoRootFinishGraceDrainingFrontier
            elif waitedMs >= 30000 && queueDepth > 0 && activeDepth <= 0 then ReplayNoRootFinishLastChanceDrain
            else ReplayNoRootFinishObserve

        type ReplayQueueDrainDecisionId =
            | ReplayQueueDrainNoQueue
            | ReplayQueueDrainActiveDriver
            | ReplayQueueDrainScheduleTick
            | ReplayQueueDrainLongWaitForceTick

        let private replayQueueDrainDecisionText = function
            | ReplayQueueDrainNoQueue -> "no_queue"
            | ReplayQueueDrainActiveDriver -> "active_driver"
            | ReplayQueueDrainScheduleTick -> "schedule_tick"
            | ReplayQueueDrainLongWaitForceTick -> "long_wait_force_tick"

        let private replayQueueDrainDecisionFor queueDepth activeDepth waitedMs =
            if queueDepth <= 0 then ReplayQueueDrainNoQueue
            elif activeDepth > 0 then ReplayQueueDrainActiveDriver
            elif waitedMs >= 8000 then ReplayQueueDrainLongWaitForceTick
            else ReplayQueueDrainScheduleTick

        let private replayQueueDrainDecisionShouldTick = function
            | ReplayQueueDrainScheduleTick
            | ReplayQueueDrainLongWaitForceTick -> true
            | ReplayQueueDrainNoQueue
            | ReplayQueueDrainActiveDriver -> false

        type BigStackSchedulerWorkId =
            | BigStackSchedulerWorkPresent
            | BigStackSchedulerWorkAbsentHotFrontierOnly
            | BigStackSchedulerWorkWriteWitnessTail
            | BigStackSchedulerWorkReplayComplete
            | BigStackSchedulerWorkCycleFuse

        let private bigStackSchedulerWorkText = function
            | BigStackSchedulerWorkPresent -> "scheduler_work_present"
            | BigStackSchedulerWorkAbsentHotFrontierOnly -> "scheduler_work_absent_hot_frontier_only"
            | BigStackSchedulerWorkWriteWitnessTail -> "write_witness_tail"
            | BigStackSchedulerWorkReplayComplete -> "replay_complete"
            | BigStackSchedulerWorkCycleFuse -> "replay_repeat_guard"

        type CyclePoisonPolicyId =
            | CyclePoisonNone
            | CyclePoisonObserveHotFrontierOnly
            | CyclePoisonCandidateRetry
            | CyclePoisonCandidateRepeatedAbort

        let private cyclePoisonPolicyText = function
            | CyclePoisonNone -> "none"
            | CyclePoisonObserveHotFrontierOnly -> "observe_hot_frontier_only"
            | CyclePoisonCandidateRetry -> "poison_candidate_retry"
            | CyclePoisonCandidateRepeatedAbort -> "poison_candidate_repeated_abort"

        type HotFrontierProgressVerdictId =
            | HotFrontierNoHotWork
            | HotFrontierRisingNoSchedulerWork
            | HotFrontierCappedPoisonCandidate
            | HotFrontierSchedulerWorkPresent
            | HotFrontierReplayOrWriteWitness
            | HotFrontierCycleFuseTripped

        let private hotFrontierProgressVerdictText = function
            | HotFrontierNoHotWork -> "no_hot_work"
            | HotFrontierRisingNoSchedulerWork -> "rising_no_scheduler_work"
            | HotFrontierCappedPoisonCandidate -> "capped_poison_candidate"
            | HotFrontierSchedulerWorkPresent -> "scheduler_work_present"
            | HotFrontierReplayOrWriteWitness -> "replay_or_write_witness"
            | HotFrontierCycleFuseTripped -> "replay_repeat_guard_tripped"

        let private hotFrontierProgressVerdictFor schedulerWorkId capReached activityStillRising activityGraceActive =
            match schedulerWorkId with
            | BigStackSchedulerWorkCycleFuse -> HotFrontierCycleFuseTripped
            | BigStackSchedulerWorkReplayComplete
            | BigStackSchedulerWorkWriteWitnessTail -> HotFrontierReplayOrWriteWitness
            | BigStackSchedulerWorkPresent -> HotFrontierSchedulerWorkPresent
            | BigStackSchedulerWorkAbsentHotFrontierOnly when capReached -> HotFrontierCappedPoisonCandidate
            | BigStackSchedulerWorkAbsentHotFrontierOnly when activityStillRising || activityGraceActive -> HotFrontierRisingNoSchedulerWork
            | BigStackSchedulerWorkAbsentHotFrontierOnly -> HotFrontierNoHotWork

        type ActivePendingDesyncDecisionId =
            | ActivePendingNoDesync
            | ActivePendingSmallQueueHotMixed
            | ActivePendingExtremeCrossKind
            | ActivePendingNoSchedulerSeedMixed
            | ActivePendingNoSchedulerWarmMixed
            | ActivePendingNoSchedulerHotMixed
            | ActivePendingNoSchedulerExtremeMixed

        let private activePendingDesyncDecisionText = function
            | ActivePendingNoDesync -> "no_desync"
            | ActivePendingSmallQueueHotMixed -> "small_queue_hot_mixed"
            | ActivePendingExtremeCrossKind -> "extreme_cross_kind"
            | ActivePendingNoSchedulerSeedMixed -> "no_scheduler_seed_mixed"
            | ActivePendingNoSchedulerWarmMixed -> "no_scheduler_warm_mixed"
            | ActivePendingNoSchedulerHotMixed -> "no_scheduler_hot_mixed"
            | ActivePendingNoSchedulerExtremeMixed -> "no_scheduler_extreme_mixed"

        let private activePendingDesyncDecisionFor active pending queueDepth termHot tyHot replayComplete =
            let totalHot = termHot + tyHot
            if replayComplete then ActivePendingNoDesync
            elif pending = 0 && queueDepth = 0 && active = 0 && termHot >= 60000 && tyHot >= 40000 then ActivePendingNoSchedulerExtremeMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 20000 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerHotMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 3000 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerWarmMixed
            elif pending = 0 && queueDepth = 0 && active = 0 && totalHot >= 1200 && termHot > 0 && tyHot > 0 then ActivePendingNoSchedulerSeedMixed
            elif active >= 4 && pending <= 2 && queueDepth <= 1 && termHot >= 60000 && tyHot >= 40000 then ActivePendingExtremeCrossKind
            elif active >= 4 && pending <= 2 && queueDepth <= 1 && totalHot >= 20000 then ActivePendingSmallQueueHotMixed
            else ActivePendingNoDesync

        let private activePendingDesyncCapDeferrals = function
            | ActivePendingExtremeCrossKind -> 3
            | ActivePendingNoSchedulerExtremeMixed -> 3
            | ActivePendingNoSchedulerHotMixed -> 4
            | ActivePendingNoSchedulerWarmMixed -> 4
            | ActivePendingNoSchedulerSeedMixed -> 6
            | ActivePendingSmallQueueHotMixed -> 8
            | ActivePendingNoDesync -> 768

        let private activePendingDesyncCapWaitMs = function
            | ActivePendingExtremeCrossKind -> 6000
            | ActivePendingNoSchedulerExtremeMixed -> 8000
            | ActivePendingNoSchedulerHotMixed -> 10000
            | ActivePendingNoSchedulerWarmMixed -> 12000
            | ActivePendingNoSchedulerSeedMixed -> 16000
            | ActivePendingSmallQueueHotMixed -> 16000
            | ActivePendingNoDesync -> 180000

        let private activePendingDesyncExtendedWaitMs = function
            | ActivePendingExtremeCrossKind -> 12000
            | ActivePendingNoSchedulerExtremeMixed -> 8000
            | ActivePendingNoSchedulerHotMixed -> 10000
            | ActivePendingNoSchedulerWarmMixed -> 12000
            | ActivePendingNoSchedulerSeedMixed -> 16000
            | ActivePendingSmallQueueHotMixed -> 32000
            | ActivePendingNoDesync -> 360000

        type HotFrontierRisingExtensionDecisionId =
            | HotFrontierNoRisingExtension
            | HotFrontierAllowRisingExtension

        let private hotFrontierRisingExtensionText = function
            | HotFrontierNoRisingExtension -> "no_rising_extension"
            | HotFrontierAllowRisingExtension -> "allow_rising_extension"

        let private hotFrontierRisingExtensionFor = function
            | ActivePendingNoSchedulerSeedMixed
            | ActivePendingNoSchedulerWarmMixed
            | ActivePendingNoSchedulerHotMixed
            | ActivePendingNoSchedulerExtremeMixed -> HotFrontierNoRisingExtension
            | _ -> HotFrontierAllowRisingExtension

        type SidecarPrefetchOutcomeId =
            | SidecarPrefetchFrameAvailable
            | SidecarPrefetchMissingAfterPrefetch

        let sidecarPrefetchOutcomeText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "missing_after_prefetch"

        let sidecarPrefetchStatusText = function
            | SidecarPrefetchFrameAvailable -> "frame_available"
            | SidecarPrefetchMissingAfterPrefetch -> "semantic_missing_after_prefetch_blocked"

        type RetryHotkeyPressureId =
            | RetryHotkeyCold
            | RetryHotkeyTermDominant
            | RetryHotkeyTyDominant
            | RetryHotkeyMixedHot
            | RetryHotkeyExtremeMixed

        let retryHotkeyPressureText = function
            | RetryHotkeyCold -> "cold"
            | RetryHotkeyTermDominant -> "term_dominant"
            | RetryHotkeyTyDominant -> "ty_dominant"
            | RetryHotkeyMixedHot -> "mixed_hot"
            | RetryHotkeyExtremeMixed -> "extreme_mixed"

        let retryHotkeyPressureFor termCount tyCount =
            let total = termCount + tyCount
            if total <= 0 then RetryHotkeyCold
            elif total >= 20000 && termCount > 0 && tyCount > 0 then RetryHotkeyExtremeMixed
            elif termCount > tyCount * 2 then RetryHotkeyTermDominant
            elif tyCount > termCount * 2 then RetryHotkeyTyDominant
            else RetryHotkeyMixedHot

        let retryHotkeyTermRatioPct termCount tyCount =
            let total = termCount + tyCount
            if total <= 0 then 0
            else int ((int64 termCount * 100L) / int64 total)

        type RetryWaitPressureId =
            | RetryWaitUnknown
            | RetryWaitBrief
            | RetryWaitStalled
            | RetryWaitCapped

        let retryWaitPressureText = function
            | RetryWaitUnknown -> "unknown"
            | RetryWaitBrief -> "brief"
            | RetryWaitStalled -> "stalled"
            | RetryWaitCapped -> "capped"

        let retryWaitPressureFor waitedMs stalledMs cappedMs =
            if waitedMs < 0L then RetryWaitUnknown
            elif waitedMs >= int64 cappedMs then RetryWaitCapped
            elif waitedMs > int64 stalledMs then RetryWaitStalled
            else RetryWaitBrief

        type RetryReentrySignalId =
            | RetryReentryNone
            | RetryReentryTermCycleFuse
            | RetryReentryHotFrontierRetry
            | RetryReentryWaitCap
            | RetryReentryMixedPressure

        let retryReentrySignalText = function
            | RetryReentryNone -> "none"
            | RetryReentryTermCycleFuse -> "term_reentry_fuse"
            | RetryReentryHotFrontierRetry -> "hot_frontier_retry"
            | RetryReentryWaitCap -> "wait_cap"
            | RetryReentryMixedPressure -> "mixed_pressure"

        let retryReentrySignalFor code termCount tyCount waitedMs =
            let total = termCount + tyCount
            if code = EJPCodes.EJP0011 then RetryReentryTermCycleFuse
            elif waitedMs >= 45000L then RetryReentryWaitCap
            elif total >= 20000 && waitedMs > 0L then RetryReentryMixedPressure
            elif total > 0 then RetryReentryHotFrontierRetry
            else RetryReentryNone

        // v128-alpha180: Bigger first-stack for deep Spiral list recursion (listm.spi foldBack/map).
        // Prefer a single large stack to avoid BigStack nesting (parent stacks remain parked).
        let private stackBytesFor (tag: string) (nestLevel: int) : int * int =
            let mb =
                match tag with
                | _ when tag.StartsWith("term") ->
                    // v130-alpha186: grow first stacks so we don't trampoline-nest into BigStack until exhaustion.
                    // NOTE: Thread stack size is an Int32; keep < 2GB to avoid overflow.
                    if nestLevel <= 4 then 1792 else 1536
                | _ when tag.StartsWith("ty") ->
                    if nestLevel <= 4 then 1792 else 1536
                | _ when tag.StartsWith("jp_") ->
                    if nestLevel <= 2 then 512 else stackMb
                | "peval_main" ->
                    if nestLevel = 1 then 1792 else 1024
                | _ -> stackMb
            // keep overall address-space bounded when deeply nested
            let mb =
                if tag.StartsWith("term") || tag.StartsWith("ty") then mb
                elif nestLevel >= 16 then min mb 256
                else mb
            let bytes64 = (int64 mb) <<< 20
            let bytes =
                if bytes64 > int64 Int32.MaxValue then Int32.MaxValue
                else int bytes64
            mb, bytes


        /// Current nesting level (0 = main, 1+ = BigStack depth)
        let getNest () = active.Value

        /// Get effective MB for the given tag
        let getMb (tag: string) = fst (stackBytesFor tag (getNest () + 1))
    

        /// Maximum allowed nesting (32 levels)
        let getMaxNest () = maxNestingLevels
    

        /// Stack size in MB (256MB)
        let getGlobalMb () = stackMb
    

        /// Execute f on a BigStack thread if nesting limit not exceeded.
        /// Returns None if max nesting reached (caller should handle gracefully).
        let tryRun<'T> (tag: string) (f: unit -> 'T) : 'T option =
            let parentNest = active.Value
            let parentDepth = RecursionTracker.currentDepth()

            // v131-alpha190: If we're already on a BigStack thread, prefer running inline.
            // This avoids runaway trampoline nesting (EJP0010) triggered by repeated stack checks inside deep recursion.
            let spawn () =
                if parentNest >= maxNestingLevels then
                    try DiagSidecar.emit (sprintf "[spiral_compiler] BIGSTACK exhausted tag=%s parentNest=%d maxNest=%d" tag parentNest maxNestingLevels) with _ -> ()
                    None
                else
                    let nestLevel = parentNest + 1
                    // v129-alpha181: Inherit parent depth to reduce runaway nesting (we allocate large stacks for term/ty).
                    // (was: reset-to-1 heuristic; removed)
                    let mutable res = Unchecked.defaultof<'T>
                    let mutable err : exn option = None
                    let mutable childTid = -1
                    let mb, stackBytes = stackBytesFor tag nestLevel
                    let th =
                        new Thread(ThreadStart(fun () ->
                            childTid <- Thread.CurrentThread.ManagedThreadId
                            active.Value <- nestLevel
                            // v129-alpha181: Inherit parent depth.
                            // alpha209: clamp inherited depth to avoid false EJP0009 when we cross BigStack boundaries many times
                            // (Depth is a diagnostic guard; semantic cycles are handled primarily by EvalCycleGuard.)
                            let inherited =
                                if tag.StartsWith("term") || tag.StartsWith("ty") then min parentDepth 8192 else parentDepth
                            RecursionTracker.setDepth inherited
                            try
                                try
                                    res <- f ()
                                with e ->
                                    err <- Some e
                            finally
                                active.Value <- parentNest
                        ), stackBytes)
                    th.IsBackground <- true
                    try th.Name <- sprintf "spiral.bigstack.%s" tag with _ -> ()
                    try
                        DiagSidecar.emit (sprintf "[spiral_compiler] BIGSTACK spawn tag=%s nest=%d/%d mb=%d bytes=%d parent_tid=%d" tag nestLevel maxNestingLevels mb stackBytes Thread.CurrentThread.ManagedThreadId)
                    with _ -> ()
                    // v107-alpha14: avoid flowing ExecutionContext/AsyncLocal into BigStack threads

                    let flow = System.Threading.ExecutionContext.SuppressFlow()

                    try

                        th.Start()

                    finally

                        flow.Undo()
                    // [BIGSTACK-211-001] Avoid infinite Join() hangs; abort on generation change / long stall.
                    // ALPHA446: a completed semantic replay frontier is also a liveness signal.
                    // Alpha445 proved the child BigStack can keep spinning on the same
                    // TJoinPoint' ty_entry while EvalWorklist is already semantic_root_complete;
                    // without this escape the parent only notices after the 240s hard timeout.
                    let gen0 = CacheGeneration.current()
                    let join_slice_ms = 250
                    let join_abort_ms = 240000
                    let join_gen_change_abort_ms = 2000
                    let join_root_complete_probe_ms = 1500
                    let join_root_complete_probe_cap = 1
                    let mutable waited = 0
                    let mutable gen_changed : (int64 * int64 * int) option = None
                    let mutable genWaitTJoinPointGraceEmitted = false
                    let mutable pinnedTerminalFirstSeen : (int * string) option = None
                    let mutable seqFastRetryGateSnapshotEmitted = false
                    let mutable seqHotFrontierAbsentSchedulerCapEmitted = false
                    let mutable seqHotFrontierExtendedCapEmitted = false
                    let mutable seqLastDiagnosticActivityForHotFrontier = -1
                    let mutable seqHotFrontierActivityDeferralUntilMs = 0
                    let mutable seqHotFrontierActivityDeferrals = 0
                    let mutable seqLastSemanticTailActivityForJoin = -1
                    let mutable seqSemanticTailActivityDeferralUntilMs = 0
                    let mutable seqSemanticTailActivityDeferrals = 0
                    let mutable seqLastRootWitnessActivityForJoin = -1
                    let mutable seqRootWitnessActivityDeferralUntilMs = 0
                    let mutable seqRootWitnessActivityDeferrals = 0
                    let mutable seqLastRootWitnessYieldWaitedMs = 0
                    let mutable seqReplayNoRootFinishLastEmitMs = -1000000
                    let mutable seqRepeatCapProbationDrainLastEmitMs = -1000000
                    let mutable seqReplayNoRootFinishLastDecision = ReplayNoRootFinishObserve
                    let mutable seqReplayNoRootFinishLastRootWitness = -1
                    let mutable seqReplayNoRootFinishLastQueue = -1
                    let mutable seqReplayNoRootTerminalTailPinned = false
                    let joinTagId = bigStackJoinTagId tag
                    let emitBigStackHudSnapshot (phaseId: BigStackFrontierPhaseId) (evidence: string) (waitedNow: int) (fastRetryReady: bool) =
                        try
                            let phase = bigStackFrontierPhaseText phaseId
                            let hudTermHotCount = DiagSidecar.snapshotTopKeyedCount "[spiral_compiler] EJP0011W|term_hot|"
                            let hudTyHotCount = DiagSidecar.snapshotTopKeyedCount "[spiral_compiler] EJP0011W|ty_hot|"
                            let hudDiagnosticActivity =
                                DiagJson.snapshotKindCount "eval_worklist_apply_spine_post_fuse_recursive_children_registered"
                                + DiagJson.snapshotKindCount "eval_worklist_if_branch_children_registered"
                                + DiagJson.snapshotKindCount "eval_worklist_type_apply_arg_tv_env_snapshot"
                                + DiagJson.snapshotKindCount "eval_worklist_type_fun_tv_child_env_snapshot"
                            let hudPending = EvalWorklist.pendingCount()
                            let hudQueue = EvalWorklist.replayQueueDepth()
                            let hudActive = EvalWorklist.replayDriverActiveDepthValue()
                            let hudReplayComplete = EvalWorklist.hasReplayComplete()
                            let hudWriteWitness = EvalWorklist.hasReplayCompleteWriteWitness()
                            let hudSequential = CacheGeneration.isSequentialRequested()
                            let hudCycleFuse = TermCycleFuse.isTripped()
                            let hudTerminalStatus, hudTerminalRank, hudTerminalSite, hudTerminalKey =
                                try
                                    match EvalWorklist.tryPinnedTerminalContract() with
                                    | Some pinned -> pinned.status, EvalWorklist.terminalContractRank pinned.status, pinned.site, pinned.key
                                    | None ->
                                        match EvalWorklist.tryDurableTerminalContract() with
                                        | Some pinned -> pinned.status, EvalWorklist.terminalContractRank pinned.status, pinned.site, pinned.key
                                        | None -> "", 0, "", ""
                                with _ -> "", 0, "", ""
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_hud_snapshot\",\"event\":\"bigstack_join_wait\",\"phase\":%s,\"tag\":%s,\"tag_du\":%s,\"evidence_du\":%s,\"waited_ms\":%d,\"budget_waited_ms\":%d,\"seq_wait_stall_ms\":%d,\"diagnostic_activity_retry_ms\":%d,\"diagnostic_activity_threshold\":%d,\"front_fail_fast_ready\":%b,\"front_sequential_requested\":%b,\"front_diagnostic_activity\":%d,\"front_hot_term\":%d,\"front_hot_ty\":%d,\"front_worklist_pending\":%d,\"front_replay_queue\":%d,\"front_replay_active\":%d,\"front_replay_complete\":%b,\"front_write_witness\":%b,\"front_replay_repeat_guard\":%b,\"front_terminal_status\":%s,\"front_terminal_rank\":%d,\"front_terminal_site\":%s,\"front_terminal_key\":%s,\"policy\":\"hud_observability_only_no_semantic_promotion\",\"single_flight\":1,\"next\":\"hud_after_round\"}"
