                            sprintf "{\"kind\":\"eval_worklist_jp_wait_fast_close_deferred_live_replay\",\"event\":\"jp_wait_fast_close\",\"decision_du\":%s,\"q\":%d,\"cc\":%d,\"explicit_pending\":%d,\"replay_queue\":%d,\"active_depth\":%d,\"single_flight\":1,\"next\":\"continue_wait_for_explicit_worklist_replay\"}"
                                (DiagJson.esc (jpWaitForceCloseDecisionText forceCloseDecisionId)) jp_work_q.Count cd.CurrentCount explicitPendingNow replayQueueNow activeDepthNow)
                        try ignore (System.Threading.Interlocked.Exchange(&jp_last_progress_ms, peval_sw.ElapsedMilliseconds)) with _ -> ()

