                            match EvalWorklist.drainJpCyclePreflight 1024 with
                            | Some f -> f
                            | None -> frame
                        let pending_root_now = System.Threading.Interlocked.Read(&jp_pending_count)
                        let enq_root_now = System.Threading.Interlocked.Read(&jp_total_enqueued)
                        let done_root_now = System.Threading.Interlocked.Read(&jp_total_done)
                        let cc_root_now =
                            try int64 cd.CurrentCount
                            with _ -> -1L
                        let jpBodiesStillPending =
                            pending_root_now > 0L || done_root_now < enq_root_now
                        let explicitPendingNow =
                            try EvalWorklist.pendingCount()
                            with _ -> 0
                        let replayQueueNow =
                            try EvalWorklist.replayQueueDepth()
                            with _ -> 0
                        let replayActiveNow =
                            try EvalWorklist.replayDriverActiveDepthValue()
                            with _ -> 0
                        let termCycleFuseFrameStatusId = termCycleFuseFrameStatusFor frame
                        let termCycleFuseFrameStatusName = termCycleFuseFrameStatusText termCycleFuseFrameStatusId
                        let termCycleFuseDecisionId =
                            termCycleFuseLiveReplayDecisionFor termCycleFuseFrameStatusId frame pending_root_now enq_root_now done_root_now cc_root_now explicitPendingNow replayQueueNow replayActiveNow
                        let termCycleFuseDecisionName =
                            termCycleFuseLiveReplayDecisionText termCycleFuseDecisionId
                        if termCycleFuseFrameStatusId = TermCycleFuseStatusRootComplete && jpBodiesStillPending then
                            // ALPHA548: alpha547 made retry_stop_drain stop on the rank-100 macro terminal,
                            // but jp_wait still kept waiting for JP bodies after a root-complete replay proof.
                            // If a high-rank terminal is already pinned, the outstanding JP body wait is not
                            // useful progress; abort as the pinned terminal EJP0011 contract before EJP0014.
                            let pendingPinnedTerminal =
                                try
                                    match EvalWorklist.tryPinnedTerminalContract() with
                                    | Some pinned when EvalWorklist.terminalContractRank pinned.status >= 90 -> Some pinned
                                    | _ -> None
                                with _ -> None
                            match pendingPinnedTerminal with
                            | Some pinned when pinned.status = "semantic_op_impl_required_blocked" && EvalWorklist.hasReplayCompleteWriteWitness() && EvalWorklist.frameHasSemanticEvidence pinned ->
                                // ALPHA924: when jp_wait already has a semantic_root_complete frontier
                                // and outstanding JP bodies, a fresh replay-root witness must be allowed
                                // to continue draining/finalizing instead of aborting on an older rank-94
                                // EOp implementation diagnostic.  Clear only the diagnostic terminal
                                // selector; no op implementation, value, root proof, writer output,
                                // codegen result, or BuildOk is synthesized.
                                let rank = EvalWorklist.terminalContractRank pinned.status
                                let cleared = EvalWorklist.clearTerminalContractIf pinned.status pinned.site pinned.key
                                DiagJson.emit (
                                    sprintf "{\"kind\":\"eval_worklist_jp_wait_root_complete_pending_op_impl_demoted_after_root_witness\",\"event\":\"jp_wait_cycle_preflight\",\"status\":%s,\"rank\":%d,\"site\":%s,\"key\":%s,\"pending\":%d,\"enqueued\":%d,\"done\":%d,\"current_count\":%d,\"cleared\":%b,\"witness\":%s,\"single_flight\":1,\"next\":\"continue_wait_for_jp_bodies\"}"
                                        (DiagJson.esc pinned.status) rank (DiagJson.esc pinned.site) (DiagJson.esc pinned.key) pending_root_now enq_root_now done_root_now cc_root_now cleared (DiagJson.esc (EvalWorklist.replayCompleteWriteWitnessSummary())))
                                try TermCycleFuse.reset() with _ -> ()
                            | Some pinned ->
