                                | Some cell -> cell.site
                                | None -> cycle_site
                            DiagJson.emit (
                                sprintf "{\"kind\":\"eval_worklist_jp_replay_repeat_guard_live_replay_deferred\",\"event\":\"jp_wait_cycle_preflight\",\"decision_du\":%s,\"status\":%s,\"frame_status_du\":%s,\"repeat_guard_trigger_shape\":%s,\"repeat_guard_trigger_site\":%s,\"pending\":%d,\"queue_depth\":%d,\"active_depth\":%d,\"jp_pending\":%d,\"jp_enqueued\":%d,\"jp_done\":%d,\"current_count\":%d,\"cycle_depth\":%d,\"cycle_re\":%d,\"cycle_max_re\":%d,\"policy\":\"assessment_term_reentry_fuse_must_not_poison_live_cross_kind_parent_replay_no_buildok\",\"single_flight\":1,\"next\":\"reset_replay_repeat_guard_and_continue_live_replay\"}"
                                    (DiagJson.esc termCycleFuseDecisionName)
                                    (DiagJson.esc frame.status)
                                    (DiagJson.esc termCycleFuseFrameStatusName)
                                    (DiagJson.esc frameShapeForDiag)
